const createOption = (value, label) => {
  const option = document.createElement("option");
  option.value = value;
  option.textContent = label;
  return option;
};

const getSegurosColaboradoresCatalog = () => {
  const seen = new Set();
  const catalog = [];
  const add = (value, label = "") => {
    const raw = String(value || "").trim();
    if (!raw) return;
    const key = normalizeSimple(raw);
    if (!key || seen.has(key)) return;
    seen.add(key);
    catalog.push({ value: raw, label: String(label || raw).trim() || raw });
  };
  SEGUROS_RESPONSABLES_FIJOS.forEach((name) => add(name, name));
  (state.usersList || []).forEach((user) => {
    const service = normalizeSimple(user?.servicio || "");
    const canUse =
      !service ||
      service.includes("seguros") ||
      service.includes("direccion") ||
      service.includes("administracion");
    if (!canUse) return;
    const label = `${user?.nombre || ""} ${user?.apellido || ""}`.trim();
    const value = (user?.usuario || "").trim() || label;
    add(value, label || value);
  });
  return catalog;
};

const getSegurosRamosCatalog = () => {
  const seen = new Set();
  const catalog = [];
  const add = (value) => {
    const raw = String(value || "").trim();
    if (!raw) return;
    const key = normalizeSimple(raw);
    if (!key || seen.has(key)) return;
    seen.add(key);
    catalog.push(raw);
  };
  SEGUROS_RAMOS_CATALOGO.forEach(add);
  const source = state.segurosCrmData;
  if (source?.columns?.length && Array.isArray(source?.rows)) {
    const ramoIndex = source.columns.indexOf("ramo");
    if (ramoIndex >= 0) {
      source.rows.forEach((row) => add(row?.[ramoIndex]));
    }
  }
  return catalog;
};

const refreshSegurosColaboradoresList = (columns = [], rows = []) => {
  if (!segurosColaboradoresList) return;
  segurosColaboradoresList.innerHTML = "";
  getSegurosColaboradoresCatalog().forEach((item) => {
    segurosColaboradoresList.appendChild(createOption(item.value, item.label));
  });
  [seguroOcrColaborador].forEach((selectEl) => {
    if (!selectEl || selectEl.tagName !== "SELECT") return;
    const current = String(selectEl.value || "").trim();
    selectEl.innerHTML = "";
    selectEl.appendChild(createOption("", "Selecciona colaborador"));
    getSegurosColaboradoresCatalog().forEach((item) => {
      selectEl.appendChild(createOption(item.value, item.label));
    });
    if (current) {
      selectEl.value = current;
      if (String(selectEl.value || "").trim() !== current) {
        selectEl.appendChild(createOption(current, current));
        selectEl.value = current;
      }
    }
  });
};

const refreshSegurosRamosList = (columns = [], rows = [], company = "") => {
  if (!segurosRamosList) return;
  const companyKey = normalizeSimple(company);
  const ramoIndex = columns.indexOf("ramo");
  const companyIndex = columns.indexOf("compania");
  const priority = [];
  const rest = new Set(SEGUROS_RAMOS_CATALOGO);
  if (ramoIndex >= 0) {
    rows.forEach((row) => {
      const ramo = String(row[ramoIndex] || "").trim();
      if (!ramo) return;
      const rowCompany = companyIndex >= 0 ? normalizeSimple(row[companyIndex] || "") : "";
      if (!companyKey || (rowCompany && rowCompany === companyKey)) {
        if (!priority.includes(ramo)) priority.push(ramo);
      } else {
        rest.add(ramo);
      }
    });
  }
  const ordered = [...priority, ...Array.from(rest).filter((item) => !priority.includes(item))];
  segurosRamosList.innerHTML = "";
  ordered.forEach((ramo) => segurosRamosList.appendChild(createOption(ramo, ramo)));
  [seguroOcrRamo, segurosBdtOcrRamo].forEach((selectEl) => {
    if (!selectEl || selectEl.tagName !== "SELECT") return;
    const current = String(selectEl.value || "").trim();
    selectEl.innerHTML = "";
    selectEl.appendChild(createOption("", "Selecciona ramo"));
    ordered.forEach((ramo) => {
      selectEl.appendChild(createOption(ramo, ramo));
    });
    if (current) {
      selectEl.value = current;
      if (String(selectEl.value || "").trim() !== current) {
        selectEl.appendChild(createOption(current, current));
        selectEl.value = current;
      }
    }
  });
};

const euroFormatter = new Intl.NumberFormat("es-ES", {
  style: "currency",
  currency: "EUR",
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
});

const formatEuros = (value) => {
  if (value === null || value === undefined || value === "") return euroFormatter.format(0);
  if (typeof value === "number") return euroFormatter.format(Number.isFinite(value) ? value : 0);
  let text = String(value).trim();
  if (!text) return euroFormatter.format(0);
  text = text.replace(/[^\d.,-]/g, "");
  const hasComma = text.includes(",");
  const hasDot = text.includes(".");
  if (hasComma && hasDot) {
    // es-ES: dots for thousands, comma for decimals
    text = text.replace(/\./g, "").replace(",", ".");
  } else if (hasComma) {
    text = text.replace(",", ".");
  } else if (hasDot) {
    // If dots look like thousands separators (e.g. 20.000), remove them
    const parts = text.split(".");
    const last = parts[parts.length - 1];
    const allGroupsAre3 = parts.slice(1).every((p) => p.length === 3);
    if (allGroupsAre3 && last.length === 3) {
      text = parts.join("");
    }
  }
  const num = Number(text);
  return euroFormatter.format(Number.isFinite(num) ? num : 0);
};

const formatEurosCompact = (value) => formatEuros(value).replace(/\s/g, "");

const numberFormatter = new Intl.NumberFormat("es-ES");
const quantityFormatter = new Intl.NumberFormat("es-ES", {
  minimumFractionDigits: 0,
  maximumFractionDigits: 2,
});

const formatPercent = (value) => {
  const num = Number(value) || 0;
  const normalized = num > 0 && num <= 1 ? num * 100 : num;
  return `${normalized.toFixed(2)}%`;
};

