const renderIco = (id, size = 18) =>
  `<svg width="${Number(size) || 18}" height="${Number(size) || 18}" viewBox="0 0 24 24" fill="none" aria-hidden="true"><use href="#ico-${String(id || "")
    .trim()
    .replace(/[^a-z0-9-]/gi, "")}"></use></svg>`;

const setPasswordToggleIcon = (button, isHidden) => {
  if (!button) return;
  const hidden = Boolean(isHidden);
  button.innerHTML = renderIco(hidden ? "eye" : "eye-off", 18);
  button.setAttribute("aria-label", hidden ? "Mostrar contraseña" : "Ocultar contraseña");
  button.setAttribute("title", hidden ? "Mostrar contraseña" : "Ocultar contraseña");
};

const createIconButton = (iconKey, label, opts = {}) => {
  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = `icon-btn icon-btn--sm ${opts.danger ? "icon-btn--danger" : ""}`.trim();
  btn.title = label;
  btn.setAttribute("aria-label", label);
  btn.innerHTML = ICONS[iconKey] || String(opts.fallback || "•");
  return btn;
};

const formatPercentOrDash = (value) => {
  const num = Number(value);
  return Number.isFinite(num) ? formatPercent(num) : "-";
};

const rowsToObjectsByColumns = (columns = [], rows = []) =>
  rows.map((row) =>
    Object.fromEntries(columns.map((column, index) => [column, Array.isArray(row) ? row[index] : row?.[column]]))
  );

const normalizeName = (value) => {
  return String(value || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^A-Za-z0-9 ]+/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .toUpperCase();
};

const normalizeSimple = (value) =>
  String(value || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .trim();

// Normaliza textos de "lookups" (catálogos/alias) para comparaciones robustas.
// - Quita tildes
// - Minúsculas
// - Convierte separadores/puntuación a espacios
// - Colapsa espacios
const normalizeLookupText = (value) =>
  normalizeSimple(value)
    .replace(/[^a-z0-9]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
try {
  window.normalizeLookupText = normalizeLookupText;
} catch (e) {}

function setSimuladoresPane(pane = "", options = {}) {
  const next = normalizeSimple(pane || "");
  try {
    state.simuladoresPane = next;
  } catch (e) {}
  try {
    localStorage.setItem(SIMULADORES_PANE_STORAGE_KEY, next);
  } catch (e) {}

  const panes = document.querySelectorAll('.simuladores-pane[data-sim-pane]');
  panes.forEach((el) => {
    const key = normalizeSimple(el.dataset.simPane || "");
    const show = !next || next === "all" || key === next;
    el.classList.toggle("hidden", !show);
    el.hidden = !show;
  });

  const status = document.getElementById("simHubStatus");
  if (status) {
    if (!next) status.textContent = "Mostrando todos los simuladores.";
    else if (next === "irpf") status.textContent = "Vista: IRPF.";
    else if (next === "plusvalia") status.textContent = "Vista: Plusvalía (IIVTNU).";
    else if (next === "alquiler") status.textContent = "Vista: Alquileres.";
    else if (next === "informe") status.textContent = "Vista: Informe fiscal (venta).";
    else status.textContent = "";
  }

  if (options?.scroll) {
    const hub = document.getElementById("simuladoresHub");
    if (hub && typeof hub.scrollIntoView === "function") {
      hub.scrollIntoView({ behavior: "smooth", block: "start" });
    }
  }
}

function scrollToSimuladoresPane(pane = "") {
  const key = normalizeSimple(pane || "");
  const el =
    (key === "irpf" && document.getElementById("simPaneIrpf")) ||
    (key === "plusvalia" && document.getElementById("simPanePlusvalia")) ||
    (key === "alquiler" && document.getElementById("simPaneAlquiler")) ||
    (key === "informe" && document.getElementById("simPaneInforme")) ||
    null;
  if (el && typeof el.scrollIntoView === "function") {
    el.scrollIntoView({ behavior: "smooth", block: "start" });
    return true;
  }
  return false;
}

function openWorkspaceSimuladores(opts = {}) {
  const pane = opts?.pane || "";
  const prefill = opts?.prefill && typeof opts.prefill === "object" ? opts.prefill : {};
  if (openEmbeddedFiscalWizard({ pane: pane || "", prefill })) {
    return;
  }
  // Los simuladores viven en el workspace tenant. En modo plataforma (admin) no existe la vista `motores`.
  let workspace = "";
  try {
    const params = new URLSearchParams(window.location.search || "");
    workspace = String(params.get("workspace") || "").trim();
  } catch (e) {}
  if (!workspace) {
    try {
      workspace = String(state.currentWorkspaceTarget || "").trim();
    } catch (e) {}
  }
  openHolding({ mode: "tenant", workspace, view: "motores", engine: "simuladores" });
  window.setTimeout(() => {
    try {
      setSimuladoresPane(pane);
    } catch (e) {}
    try {
      applyFiscalWizardPrefill(prefill);
    } catch (e) {}
    try {
      if (pane) scrollToSimuladoresPane(pane);
    } catch (e) {}
  }, 180);
}

const tokenizeSearchQuery = (raw = "") => {
  const text = String(raw || "").trim();
  if (!text) return [];
  const tokens = [];
  let buf = "";
  let quote = "";
  for (let i = 0; i < text.length; i += 1) {
    const ch = text[i];
    if (quote) {
      if (ch === quote) {
        quote = "";
        continue;
      }
      buf += ch;
      continue;
    }
    if (ch === '"' || ch === "'") {
      quote = ch;
      continue;
    }
    if (/\s/.test(ch)) {
      if (buf) tokens.push(buf);
      buf = "";
      continue;
    }
    buf += ch;
  }
  if (buf) tokens.push(buf);
  return tokens;
};

const normalizeAdvancedSearchKey = (rawKey = "") => {
  const key = normalizeSimple(rawKey);
  if (!key) return "";
  if (["tel", "tlf", "tlfno", "telefono", "telefono1", "telefono2", "phone"].includes(key)) return "tel";
  if (["movil", "mobile", "celular", "cell"].includes(key)) return "movil";
  if (["mail", "correo", "email", "e-mail"].includes(key)) return "email";
  if (["dni", "nif", "cif", "doc", "documento"].includes(key)) return "nif";
  if (["cp", "postal", "codigo_postal", "codigopostal"].includes(key)) return "codigo_postal";
  if (["prov", "provincia"].includes(key)) return "provincia";
  if (["pob", "poblacion", "localidad", "ciudad", "municipio"].includes(key)) return "poblacion";
  if (["ref", "referencia"].includes(key)) return "referencia";
  if (["refcat", "refcatastral", "catastral", "referencia_catastral"].includes(key)) return "referencia_catastral";
  return key;
};

const isAdvancedSearchEmptyValue = (valueRaw = "", valueNorm = "") => {
  const raw = String(valueRaw || "").trim();
  if (!raw) return true;
  if (raw === "!") return true;
  const norm = String(valueNorm || "").trim();
  return ["vacio", "vacío", "empty", "null", "none"].includes(norm);
};

const createAdvancedSearchMatcher = (
  raw = "",
  {
    text = null,
    fields = {},
  } = {}
) => {
  const tokens = tokenizeSearchQuery(raw);
  if (!tokens.length) return () => true;

  const termSpecs = [];
  const filterSpecs = [];
  tokens.forEach((token) => {
    if (!token) return;
    let rawToken = String(token || "").trim();
    if (!rawToken) return;
    let neg = false;
    if (rawToken.startsWith("-")) {
      neg = true;
      rawToken = rawToken.slice(1);
    }
    if (!rawToken) return;

    const idx = rawToken.indexOf(":");
    if (idx > 0) {
      const key = normalizeAdvancedSearchKey(rawToken.slice(0, idx));
      const valueRaw = rawToken.slice(idx + 1);
      if (key && fields && Object.prototype.hasOwnProperty.call(fields, key)) {
        filterSpecs.push({
          key,
          neg,
          valueRaw,
          valueNorm: normalizeSimple(valueRaw),
        });
        return;
      }
    }

    termSpecs.push({
      neg,
      valueNorm: normalizeSimple(rawToken),
    });
  });

  const resolveText = (row) => {
    try {
      const value = text ? text(row) : "";
      return normalizeSimple(value);
    } catch {
      return "";
    }
  };

  const resolveField = (row, key) => {
    const entry = fields?.[key];
    if (!entry) return "";
    try {
      if (typeof entry === "function") return String(entry(row) || "");
      if (entry && typeof entry.get === "function") return String(entry.get(row) || "");
      return String(entry || "");
    } catch {
      return "";
    }
  };

  const matchField = (row, key, valueNorm) => {
    const entry = fields?.[key];
    if (!entry) return false;
    if (entry && typeof entry.test === "function") {
      try {
        return Boolean(entry.test(row, valueNorm));
      } catch {
        return false;
      }
    }
    const rawValue = resolveField(row, key);
    const rowNorm = normalizeSimple(rawValue);
    if (entry && typeof entry === "object" && entry.match === "equals") {
      return rowNorm === valueNorm;
    }
    return rowNorm.includes(valueNorm);
  };

  return (row) => {
    const hay = resolveText(row);
    for (const spec of termSpecs) {
      if (!spec.valueNorm) continue;
      const hit = hay.includes(spec.valueNorm);
      if (spec.neg ? hit : !hit) return false;
    }
    for (const spec of filterSpecs) {
      const empty = isAdvancedSearchEmptyValue(spec.valueRaw, spec.valueNorm);
      if (empty) {
        const rawValue = String(resolveField(row, spec.key) || "").trim();
        const hit = !rawValue;
        if (spec.neg ? hit : !hit) return false;
        continue;
      }
      const hit = matchField(row, spec.key, spec.valueNorm);
      if (spec.neg ? hit : !hit) return false;
    }
    return true;
  };
};

const parseServiceList = (value) =>
  String(value || "")
    // Compat: algunos flujos guardan servicios como "Gestoría - Administración Fincas" o con separador "·".
    .split(/(?:\s+-\s+|[|,/;·]+)/)
    .map((item) => normalizeSimple(item))
    .filter(Boolean);

const normalizeWorkspaceServiceKey = (value) => {
  const raw = normalizeSimple(value);
  if (!raw) return "";
  if (raw === "hipotecas" || raw === "financiacion") return "financiaciones";
  if (raw === "administracion fincas" || raw === "administracion de fincas" || raw === "admin de fincas") return "fincas";
  if (raw.includes("fincas")) return "fincas";
  return raw;
};

const ADMIN_SERVICE_OPTIONS = [
  "Gestoría",
  "Seguros",
  "Inmobiliaria",
  "Financiaciones",
  "Admin de fincas",
  "Dirección",
  "Administración",
];

const resolveWorkspaceModuleKeyFromAdminServiceLabel = (label = "") => {
  const normalized = normalizeSimple(label);
  if (!normalized) return "";
  if (["direccion", "administracion"].includes(normalized)) return "";
  if (normalized.includes("gestoria")) return "gestoria";
  if (normalized.includes("seguros")) return "seguros";
  if (normalized.includes("inmobiliaria")) return "inmobiliaria";
  if (normalized.includes("financi") || normalized.includes("hipotec")) return "financiacion";
  if (normalized.includes("fincas")) return "fincas";
  if (normalized.includes("reformas") || normalized.includes("obras")) return "reformas";
  return "";
};

const getWorkspaceAccessServiceOptions = () => {
  const options = Array.isArray(ADMIN_SERVICE_OPTIONS) ? ADMIN_SERVICE_OPTIONS : [];
  if (!isTenantWorkspaceMode()) return options;
  const enabledKeys = new Set(state.currentWorkspaceEnabledModules || []);
  if (!enabledKeys.size) return options;
  return options.filter((label) => {
    const moduleKey = resolveWorkspaceModuleKeyFromAdminServiceLabel(label);
    if (!moduleKey) return true; // Dirección / Administración (no son módulos).
    return enabledKeys.has(moduleKey);
  });
};

const ADMIN_ROLE_OPTIONS = [
  "Lectura",
  "Gestoría",
  "Seguros",
  "Inmobiliaria",
  "Financiaciones",
  "Administrador",
];

const RRHH_CONTRACT_TYPE_OPTIONS = [
  "Indefinido",
  "Temporal",
  "Fijo discontinuo",
  "Interinidad",
  "Prácticas",
  "Formación y aprendizaje",
  "Obra y servicio",
  "Becario",
  "Otro",
];

const ADMIN_SERVICE_BY_KEY = ADMIN_SERVICE_OPTIONS.reduce((acc, label) => {
  acc[normalizeSimple(label)] = label;
  return acc;
}, {});

const parseAdminServices = (value) => {
  const keys = parseServiceList(value);
  const ordered = [];
  keys.forEach((key) => {
    if (key === "hipotecas") key = "financiaciones";
    if (key === "administracion de fincas") key = "administracion fincas";
    if (["administracion fincas", "administracion de fincas", "admin de fincas"].includes(key)) key = "fincas";
    const label = ADMIN_SERVICE_BY_KEY[key] || getServiceLabelFromNormalized(key) || key;
    if (label && !ordered.includes(label)) {
      ordered.push(label);
    }
  });
  return ordered;
};

const joinAdminServices = (values) => {
  const normalized = parseAdminServices((values || []).join(","));
  return normalized.join(", ");
};

const buildRrhhContractTypeOptions = (currentValue = "") => {
  const current = String(currentValue || "").trim();
  const currentKey = normalizeSimple(current);
  const unique = [];
  const seen = new Set();
  const pushUnique = (label) => {
    const text = String(label || "").trim();
    if (!text) return;
    const key = normalizeSimple(text);
    if (!key || seen.has(key)) return;
    seen.add(key);
    unique.push(text);
  };
  if (current) pushUnique(current);
  RRHH_CONTRACT_TYPE_OPTIONS.forEach((opt) => pushUnique(opt));
  const out = [`<option value="">Selecciona tipo</option>`];
  unique.forEach((opt) => {
    const selected = normalizeSimple(opt) === currentKey ? "selected" : "";
    out.push(`<option value="${escapeHtml(opt)}" ${selected}>${escapeHtml(opt)}</option>`);
  });
  return out.join("");
};

const expandServiceAliases = (services) => {
  const set = new Set(services || []);
  // Normaliza alias habituales en `usuarios.servicio` (evita negar acceso por etiquetas distintas).
  // Ej: "CRM inmobiliario" debe comportarse como "inmobiliaria".
  Array.from(set).forEach((svc) => {
    const key = normalizeSimple(svc);
    if (!key) return;
    // Heurísticas: si el servicio viene con apellido/marca ("Fincas Velazquez", "Seguros Modernia", etc.)
    // lo colapsamos al módulo raíz.
    if (key === "inmo" || key === "crm inmo" || key === "crm inmobiliario" || key === "crm inmobiliaria") set.add("inmobiliaria");
    if (key.includes("inmobili")) set.add("inmobiliaria");
    if (key.includes("seguro")) set.add("seguros");
    if (key.includes("gestor")) set.add("gestoria");
    if (key.includes("finca")) set.add("fincas");
    if (key.includes("hipotec") || key.includes("financi")) set.add("financiaciones");
  });
  if (set.has("financiaciones")) set.add("hipotecas");
  if (set.has("hipotecas")) set.add("financiaciones");
  if (set.has("administracion fincas")) set.add("administracion de fincas");
  if (set.has("administracion de fincas")) set.add("administracion fincas");
  if (set.has("admin de fincas")) {
    set.add("administracion fincas");
    set.add("administracion de fincas");
  }
  if (set.has("administracion fincas") || set.has("administracion de fincas")) set.add("fincas");
  if (set.has("admin de fincas")) set.add("fincas");
  if (set.has("fincas")) set.add("administracion fincas");
  return Array.from(set);
};

const getServiceLabelFromNormalized = (value) => {
  const normalized = normalizeSimple(value);
  if (!normalized) return "";
  if (SERVICE_LABELS[normalized]) return SERVICE_LABELS[normalized];
  const match = SERVICE_OPTIONS.find(
    (service) => normalizeSimple(service) === normalized
  );
  return match || "";
};

const getAllowedServiceKeys = () => {
  if (!state.currentUserServices || !state.currentUserServices.length) {
    return null;
  }
  return new Set(state.currentUserServices.map((value) => normalizeSimple(value)));
};

const getVisibleServiceKeys = () => {
  const allowed = getAllowedServiceKeys();
  const clientServices = expandServiceAliases(
    (state.currentClienteServices || []).map((value) => normalizeSimple(value))
  );
  if (!allowed) {
    return clientServices.length ? new Set(clientServices) : null;
  }
  if (!clientServices.length) return allowed;
  const intersection = new Set();
  clientServices.forEach((value) => {
    if (allowed.has(value)) intersection.add(value);
  });
  return intersection;
};

const isPrivilegedService = (value) => {
  const normalized = normalizeSimple(value);
  return ["direccion", "administracion", "control"].includes(normalized);
};

const isPrivilegedRole = (value) => {
  const normalized = normalizeSimple(value);
  return ["administrador", "admin", "direccion", "administracion", "control"].includes(normalized);
};

const hasAdminWideAccess = (user) => {
  if (!user) return false;
  if (Boolean(user.is_superadmin)) return true;
  if (isPrivilegedRole(user.rol || "")) return true;
  if (isPrivilegedService(user.servicio || "")) return true;
  return false;
};

const isPrivilegedUser = (user) => {
  if (!user) return false;
  // En modo multi-workspace estricto, la "administración global" (home platform/admin)
  // se controla por allowlist (superadmin), no por rol/servicio.
  return Boolean(user.is_superadmin);
};

const isWorkspaceMemberManagerRole = (value) => {
  const normalized = normalizeSimple(value);
  return normalized === "owner" || normalized === "admin";
};

const canManageCurrentWorkspace = () => {
  const user = getAuthScopeUser();
  if (user && hasAdminWideAccess(user)) return true;
  return isWorkspaceMemberManagerRole(state.currentWorkspaceMemberRole || "");
};

const canAccessGestoriaAdminDashboard = () => {
  const user = getAuthScopeUser();
  if (user && isPrivilegedUser(user)) return true;
  if (user && isPrivilegedRole(user.rol || "")) return true;
  return isWorkspaceMemberManagerRole(state.currentWorkspaceMemberRole || "");
};

const canAccessAdminPanel = (user) => {
  if (!user) return false;
  return Boolean(user.is_superadmin);
};

const canAccessSharedHomeModules = (user) => hasAdminWideAccess(user);

const getPrimaryRestrictedHomeService = (user) => {
  if (!user || hasAdminWideAccess(user)) return "";
  const services = expandServiceAliases(parseServiceList(user.servicio || ""));
  for (const service of services) {
    if (service === "inmobiliaria") return "inmobiliaria";
    if (service === "gestoria") return "gestoria";
    if (service === "fincas" || service === "administracion fincas" || service === "administracion de fincas") return "fincas";
    if (service === "seguros") return "seguros";
    if (service === "financiaciones" || service === "hipotecas") return "financiaciones";
  }
  return "";
};

const resolveRestrictedCompanyAccess = (empresaName) => {
  if (empresaName === DASHBOARD_COMPANY && userCanAccessService("inmobiliaria")) {
    return "inmobiliaria";
  }
  if (empresaName === resolveCrmFinEmpresaNombre() && userCanAccessService("financiaciones")) {
    return "financiaciones";
  }
  const fincasServices = [
    userCanAccessService("seguros") ? "seguros" : "",
    userCanAccessService("gestoria") ? "gestoria" : "",
    userCanAccessService("fincas") ? "fincas" : "",
  ].filter(Boolean);
  if (empresaName === FINCAS_COMPANY && fincasServices.length === 1) {
    return fincasServices[0];
  }
  return "";
};

const resolveDefaultTenantWorkspaceSlug = () => {
  try {
    const fromStatus = String(state?.homeTimeStatus?.workspace_slug || "").trim();
    if (fromStatus) return normalizeTenantWorkspaceSlug(fromStatus, DEFAULT_TENANT_WORKSPACE_SLUG);
  } catch (e) {}
  try {
    const fromCurrent = String(state?.currentWorkspaceTarget || state?.currentWorkspaceName || "").trim();
    if (fromCurrent) return normalizeTenantWorkspaceSlug(fromCurrent, DEFAULT_TENANT_WORKSPACE_SLUG);
  } catch (e) {}
  try {
    const rows = Array.isArray(state?.workspaces) ? state.workspaces : [];
    if (rows.length === 1) {
      const value = String(rows[0]?.slug || rows[0]?.nombre || rows[0]?.id || "").trim();
      if (value) return normalizeTenantWorkspaceSlug(value, DEFAULT_TENANT_WORKSPACE_SLUG);
    }
  } catch (e) {}
  return DEFAULT_TENANT_WORKSPACE_SLUG;
};

const getTenantWorkspaceIdFromUrl = () => {
  try {
    const params = new URLSearchParams(window.location.search || "");
    const ws = String(params.get("workspace") || "").trim();
    return ws;
  } catch (_e) {
    return "";
  }
};

const resolveActiveTenantWorkspaceId = () => {
  try {
    const ws =
      String(state.currentWorkspaceId || "").trim()
      || String(getTenantWorkspaceIdFromUrl() || "").trim()
      || String(state.homeTimeStatus?.workspace_id || "").trim()
      || (() => {
        try { return String(localStorage.getItem("crm.currentWorkspaceId") || "").trim(); } catch { return ""; }
      })();
    return ws;
  } catch (_e) {
    return "";
  }
};

const shouldPreferTenantRouting = () => {
  // Si ya estamos en modo tenant/workspace o hay un workspace_id recordado, no debemos caer al modo global.
  if (isTenantWorkspaceMode && isTenantWorkspaceMode()) return true;
  try {
    const stored = String(localStorage.getItem("crm.currentWorkspaceId") || "").trim();
    if (stored) return true;
  } catch (_e) {}
  return Boolean(String(state.currentWorkspaceId || "").trim());
};

const ensureTenantParams = (params) => {
  if (!params) return params;
  if (params.get("holding") === "1" && String(params.get("mode") || "").toLowerCase() === "tenant" && params.get("workspace")) {
    return params;
  }
  if (!shouldPreferTenantRouting()) return params;
  // workspace id: URL > state > localStorage
  const wsFromUrl = getTenantWorkspaceIdFromUrl();
  const wsFromState = String(state.currentWorkspaceId || "").trim();
  let wsFromStore = "";
  try {
    wsFromStore = String(localStorage.getItem("crm.currentWorkspaceId") || "").trim();
  } catch (_e) {}
  const ws = wsFromUrl || wsFromState || wsFromStore;
  if (!ws) return params;
  params.set("holding", "1");
  params.set("mode", "tenant");
  params.set("workspace", ws);
  return params;
};

const getAuthScopeUser = () => {
  if (state.authUser && (state.authUser.usuario || state.authUser.id)) {
    return state.authUser;
  }
  return getUserByValue(getCurrentUser());
};

const getUserByValue = (value) => {
  const normalized = normalizeSimple(value);
  let found = (state.usersList || []).find((user) => {
    const usuario = normalizeSimple(user.usuario || "");
    const nombre = normalizeSimple(user.nombre || "");
    const full = normalizeSimple(`${user.nombre || ""} ${user.apellido || ""}`.trim());
    return (
      (usuario && usuario === normalized) ||
      (full && full === normalized) ||
      (nombre && nombre === normalized)
    );
  });
  if (!found && userSelect && userSelect.value) {
    const selected = normalizeSimple(userSelect.value);
    found = (state.usersList || []).find((user) => {
      const usuario = normalizeSimple(user.usuario || "");
      const nombre = normalizeSimple(user.nombre || "");
      const full = normalizeSimple(`${user.nombre || ""} ${user.apellido || ""}`.trim());
      return (
        (usuario && usuario === selected) ||
        (full && full === selected) ||
        (nombre && nombre === selected)
      );
    });
  }
  return found;
};

const syncCurrentUserScope = () => {
  const user = getAuthScopeUser();
  if (!user) {
    state.currentUserServices = [];
    state.currentUserServiceLabel = "";
    return;
  }
  state.currentUserServiceLabel = user.servicio || "";
  state.currentUserServices = expandServiceAliases(parseServiceList(user.servicio || ""));
};

const getServiceFilterParam = () => {
  const user = getAuthScopeUser();
  if (!user) return "";
  if (hasAdminWideAccess(user)) return "";
  const services = expandServiceAliases(parseServiceList(user.servicio || ""));
  return services.join(",");
};

const userCanAccessService = (serviceKey) => {
  const normalized = normalizeSimple(serviceKey || "");
  if (!normalized) return true;
  const user = getAuthScopeUser();
  if (!user) {
    return !(state.usersList && state.usersList.length);
  }
  if (hasAdminWideAccess(user)) return true;
  const allowed = new Set(expandServiceAliases(parseServiceList(user.servicio || "")));
  if (!allowed.size) return false;
  if (normalized === "fincas") {
    if (allowed.has("fincas") || allowed.has("administracion fincas") || allowed.has("administracion de fincas") || allowed.has("admin de fincas")) {
      return true;
    }
    // Compat: si el servicio viene como etiqueta tipo "Fincas Velazquez", "Administración Fincas - Velazquez", etc.
    // consideramos que habilita el módulo Fincas.
    try {
      for (const key of allowed) {
        if (String(key || "").includes("fincas")) return true;
      }
    } catch (e) {}
    return false;
  }
  if (normalized === "gestoria") {
    if (allowed.has("gestoria")) return true;
    try {
      if (
        allowed.has("fincas") ||
        allowed.has("administracion fincas") ||
        allowed.has("administracion de fincas") ||
        allowed.has("admin de fincas")
      ) {
        return true;
      }
      for (const key of allowed) {
        const text = String(key || "");
        if (text.includes("gestoria") || text.includes("gestoría")) return true;
        if (text.includes("fincas")) return true;
      }
    } catch (e) {}
    return false;
  }
  if (normalized === "seguros") {
    if (allowed.has("seguros")) return true;
    try {
      for (const key of allowed) if (String(key || "").includes("seguros") || String(key || "").includes("seguro")) return true;
    } catch (e) {}
    return false;
  }
  if (normalized === "inmobiliaria") {
    if (allowed.has("inmobiliaria")) return true;
    try {
      for (const key of allowed) if (String(key || "").includes("inmobili")) return true;
    } catch (e) {}
    return false;
  }
  if (normalized === "hipotecas") {
    return allowed.has("hipotecas") || allowed.has("financiaciones");
  }
  if (normalized === "financiaciones") {
    return allowed.has("financiaciones") || allowed.has("hipotecas");
  }
  return allowed.has(normalized);
};

const normalizeMatch = (value) =>
  String(value || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]/g, "")
    .trim();

let currentActionEdit = null;
let modalLoading = false;

const populateActionModalResponsables = (serviceValue = "") => {
  if (!actionModalResponsable) return;
  const filter = normalizeSimple(serviceValue || "");
  const users = state.usersList || [];
  actionModalResponsable.innerHTML = "";
  actionModalResponsable.appendChild(createOption("", "Selecciona responsable"));
  users
    .filter((user) => {
      if (!filter) return true;
      const service = normalizeSimple(user.servicio || "");
      if (!service) return true;
      if (service.includes(filter)) return true;
      if (["direccion", "administracion"].includes(service)) return true;
      return false;
    })
    .forEach((user) => {
      const label = `${user.nombre || ""} ${user.apellido || ""}`.trim();
      const value = user.usuario || label || user.nombre || "";
      if (!value) return;
      actionModalResponsable.appendChild(createOption(value, label || value));
    });
};

const setDefaultActionModalResponsable = (desiredRaw) => {
  if (!actionModalResponsable) return;
  const current = String(actionModalResponsable.value || "").trim();
  if (current) return;
  const desired = String(desiredRaw || "").trim();
  if (!desired) return;
  const options = Array.from(actionModalResponsable.options || []);
  const direct = options.find((opt) => String(opt.value || "").trim() === desired);
  if (direct) {
    actionModalResponsable.value = direct.value;
    return;
  }
  const desiredKey = normalizeSimple(desired);
  const byLabel = options.find((opt) => normalizeSimple(opt.textContent || "") === desiredKey);
  if (byLabel) {
    actionModalResponsable.value = byLabel.value;
  }
};

const ensureModalDataLoaded = async () => {
  if (modalLoading) return;
  modalLoading = true;
  try {
    if (!state.usersList || !state.usersList.length) {
      await loadUsuarios();
    }
    if (!state.clientesList || !state.clientesList.length) {
      await loadClientesList();
    }
    populateAgendaClientes(actionModalClientes, actionModalClienteInput, actionModalClienteId);
    populateActionModalResponsables(actionModalServicioSelect?.value || "");
  } catch (err) {
    // No bloquees la apertura del modal si falla la carga de listas (agenda debe seguir siendo operativa).
    try {
      console.warn("ensureModalDataLoaded failed", err);
    } catch (e) {}
    try {
      setUiToast("Aviso", "No se pudo cargar la lista de usuarios/clientes. Puedes escribir el cliente manualmente.");
    } catch (e) {}
  } finally {
    modalLoading = false;
  }
};

const ensureActionModalClientesReady = async () => {
  try {
    if (!state.clientesList || !state.clientesList.length) {
      await loadClientesList().catch(() => null);
    }
    populateAgendaClientes(actionModalClientes, actionModalClienteInput, actionModalClienteId);
  } catch (e) {}
};

const syncActionModalClienteButtons = () => {
  const clienteData = resolveClienteFromInput(actionModalClienteInput, actionModalClienteId);
  if (actionModalOpenCliente) {
    actionModalOpenCliente.disabled = !clienteData.cliente_id;
  }
  if (actionModalCreateCliente) {
    const nombre = String(clienteData.cliente_nombre || "").trim();
    actionModalCreateCliente.disabled = !nombre || Boolean(clienteData.cliente_id);
  }
};

const setSelectValueWithoutCarry = (select, rawValue, fallbackValue = "") => {
  if (!select) return "";
  const desired = String(rawValue ?? "").trim();
  const fallback = String(fallbackValue ?? "").trim();
  try {
    select.selectedIndex = -1;
  } catch (e) {}
  const hasBlank = Array.from(select.options || []).some((opt) => opt.value === "");
  if (!hasBlank) {
    try {
      select.insertBefore(createOption("", ""), select.firstChild);
    } catch (e) {}
  }
  const options = Array.from(select.options || []);
  const desiredOption = desired ? options.find((opt) => opt.value === desired) : null;
  if (desiredOption) {
    select.value = desired;
    return select.value;
  }
  if (desired) {
    try {
      select.appendChild(createOption(desired, desired));
      select.value = desired;
      return select.value;
    } catch (e) {}
  }
  const fallbackOption = fallback ? options.find((opt) => opt.value === fallback) : null;
  if (fallbackOption) {
    select.value = fallback;
    return select.value;
  }
  select.value = "";
  if (String(select.value || "").trim()) {
    try {
      select.selectedIndex = -1;
    } catch (e) {}
  }
  return select.value || "";
};

const getCrmAgendaStorageScope = () => {
  const user = normalizeSimple(getCurrentUser?.() || "usuario") || "usuario";
  let workspace = "";
  try {
    workspace =
      (typeof resolveActiveTenantWorkspaceId === "function" ? String(resolveActiveTenantWorkspaceId() || "").trim() : "")
      || (typeof getTenantWorkspaceIdFromUrl === "function" ? String(getTenantWorkspaceIdFromUrl() || "").trim() : "");
  } catch (e) {
    workspace = "";
  }
  return `${user}:${workspace || "global"}`;
};

const getCrmAgendaStorageKey = (name) => `crm.agenda.${name}.${getCrmAgendaStorageScope()}`;

const readCrmAgendaStorage = (name, legacyKey = "") => {
  try {
    const scoped = localStorage.getItem(getCrmAgendaStorageKey(name));
    if (scoped !== null && scoped !== undefined) return scoped;
    return legacyKey ? localStorage.getItem(legacyKey) : null;
  } catch (e) {
    return null;
  }
};

const writeCrmAgendaStorage = (name, value) => {
  try {
    localStorage.setItem(getCrmAgendaStorageKey(name), String(value ?? ""));
  } catch (e) {}
};

const openActionEditor = (ev, context = null) => {
  if (!actionModal) return;
  void ensureModalDataLoaded();
  void ensureActionModalClientesReady();
  currentActionEdit = ev;
  // Evita “contaminación”: el guardado debe decidir si es update/create por un id estable, no por un objeto mutable.
  state.actionModalEditId = String(ev?.id || "").trim();
  // Snapshot defensivo: evita mutaciones accidentales del objeto referenciado en `lastAgendaEvents`.
  state.actionModalEditSnapshot = ev ? JSON.parse(JSON.stringify(ev)) : null;
  state.actionModalContext = context && typeof context === "object" ? context : null;
  if (actionModalServicioSelect) {
    actionModalServicioSelect.disabled = Boolean(state.actionModalContext?.lock_service);
  }
  if (actionModalEstado) {
    actionModalEstado.disabled = Boolean(state.actionModalContext?.lock_estado);
  }
  if (actionModalStatus) actionModalStatus.textContent = "";
  if (actionModalClienteInput) actionModalClienteInput.value = ev.cliente || "";
  if (actionModalClienteId) actionModalClienteId.value = ev.cliente_id || "";
  if (actionModalServicioSelect) {
    actionModalServicioSelect.value = ev.serviceId || ev.service || "";
    if (!actionModalServicioSelect.value) {
      actionModalServicioSelect.value = "gestoria";
    }
  }
  if (actionModalFecha) actionModalFecha.value = ev.dateKey || "";
  if (actionModalHora) actionModalHora.value = ev.time || "";
  if (actionModalHoraFin) actionModalHoraFin.value = ev.timeEnd || "";
  if (actionModalTipo) {
    setSelectValueWithoutCarry(actionModalTipo, ev.tipo || "");
  }
  if (actionModalNotas) actionModalNotas.value = ev.notas || "";
  if (actionModalRecordatorio) {
    actionModalRecordatorio.value =
      ev.recordatorio_min !== undefined && ev.recordatorio_min !== null
        ? String(ev.recordatorio_min)
        : "";
  }
  if (actionModalEstado) {
    setSelectValueWithoutCarry(actionModalEstado, ev.estado || "Pendiente", "Pendiente");
  }
  if (actionModalResponsable) {
    populateActionModalResponsables(ev.serviceId || ev.service || "");
    // IMPORTANTE: si la acción no tiene responsable, no arrastres el valor anterior del <select>.
    // (Bug: al editar una cita "sin responsable" se quedaba el responsable de la cita anterior).
    setSelectValueWithoutCarry(actionModalResponsable, ev.responsable || "");
  }
  if (state.actionModalContext) {
    const ctx = state.actionModalContext;
    if ((ctx.servicio || ctx.service) && actionModalServicioSelect) {
      actionModalServicioSelect.value = String(ctx.servicio || ctx.service || "").trim();
    }
    const ctxClienteNombre = String(ctx.cliente_nombre || "").trim();
    const ctxClienteId = String(ctx.cliente_id || "").trim();
    if (ctxClienteNombre && actionModalClienteInput) actionModalClienteInput.value = ctxClienteNombre;
    if (ctxClienteId && actionModalClienteId) actionModalClienteId.value = ctxClienteId;
  }
  syncActionModalClienteButtons();
  actionModal.classList.remove("hidden");
  syncCrmModalOpenState();
};

const openActionCreator = (dateValue, timeValue, serviceValue, context = null) => {
  if (!actionModal) return;
  void ensureModalDataLoaded();
  void ensureActionModalClientesReady();
  currentActionEdit = null;
  state.actionModalEditId = "";
  state.actionModalEditSnapshot = null;
  state.actionModalContext = context && typeof context === "object" ? context : null;
  if (actionModalStatus) actionModalStatus.textContent = "";
  // Reset fuerte: evita heredar cliente/tipo/etc si el usuario abre el creador tras editar otra cita.
  if (actionModalClienteInput) actionModalClienteInput.value = "";
  if (actionModalClienteId) actionModalClienteId.value = "";
  if (actionModalServicioSelect) {
    actionModalServicioSelect.value = serviceValue || "";
    actionModalServicioSelect.disabled = Boolean(state.actionModalContext?.lock_service);
  }
  if (actionModalFecha) actionModalFecha.value = dateValue || formatAgendaDate(new Date());
  if (actionModalHora) actionModalHora.value = timeValue || "";
  if (actionModalHoraFin) {
    // Google Calendar-like: si se crea con hora, proponemos +60min.
    const defaultEnd = timeValue ? addMinutesToAgendaTime(timeValue, 60) : "";
    actionModalHoraFin.value = defaultEnd;
  }
  if (actionModalTipo) {
    // Reset duro: algunos <select> mantienen el valor anterior si "" no existe como opción.
    actionModalTipo.value = "";
    if (String(actionModalTipo.value || "").trim() && actionModalTipo.options && actionModalTipo.options.length) {
      actionModalTipo.selectedIndex = 0;
    }
  }
  if (actionModalNotas) actionModalNotas.value = "";
  if (actionModalRecordatorio) actionModalRecordatorio.value = "";
  if (actionModalEstado) actionModalEstado.value = "Pendiente";
  if (actionModalEstado) {
    actionModalEstado.disabled = Boolean(state.actionModalContext?.lock_estado);
  }
  if (actionModalResponsable) {
    populateActionModalResponsables(serviceValue || "gestoria");
    actionModalResponsable.value = "";
  }
  if (state.actionModalContext) {
    const ctx = state.actionModalContext;
    const ctxClienteNombre = String(ctx.cliente_nombre || "").trim();
    const ctxClienteId = String(ctx.cliente_id || "").trim();
    if (ctxClienteNombre && actionModalClienteInput) actionModalClienteInput.value = ctxClienteNombre;
    if (ctxClienteId && actionModalClienteId) actionModalClienteId.value = ctxClienteId;
    if ((ctx.servicio || ctx.service) && actionModalServicioSelect) {
      actionModalServicioSelect.value = String(ctx.servicio || ctx.service || "").trim();
    }
    const defaultTipo = String(ctx.default_tipo || "").trim();
    if (defaultTipo && actionModalTipo && !String(actionModalTipo.value || "").trim()) {
      actionModalTipo.value = defaultTipo;
      // Si la opción no existe, no dejamos el valor anterior: mantenemos el reset.
      if (String(actionModalTipo.value || "").trim() !== defaultTipo && actionModalTipo.options && actionModalTipo.options.length) {
        actionModalTipo.selectedIndex = 0;
      }
    }
  }
  if (actionModalResponsable) {
    const ctxResp = String(state.actionModalContext?.default_responsable || "").trim();
    setDefaultActionModalResponsable(ctxResp || getCurrentUser());
  }
  syncActionModalClienteButtons();
  actionModal.classList.remove("hidden");
  syncCrmModalOpenState();
};

const closeActionEditor = () => {
  if (actionModal) actionModal.classList.add("hidden");
  currentActionEdit = null;
  state.actionModalEditId = "";
  state.actionModalEditSnapshot = null;
  state.actionModalContext = null;
  if (actionModalServicioSelect) actionModalServicioSelect.disabled = false;
  if (actionModalEstado) actionModalEstado.disabled = false;
  syncCrmModalOpenState();
};

const agendaStates = new Map();
const agendaViews = ["day", "week", "month", "year"];
let lastAgendaEvents = [];

const parseAgendaDate = (value) => {
  if (!value) return null;
  const raw = String(value || "").trim();
  if (!raw) return null;
  // IMPORTANT: `new Date('YYYY-MM-DD')` se interpreta como UTC en muchos motores.
  // Para agenda tipo Google Calendar queremos tratar fechas como locales (sin desplazamientos).
  const m = raw.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (m) {
    const y = Number(m[1]);
    const mm = Number(m[2]);
    const d = Number(m[3]);
    const date = new Date(y, mm - 1, d);
    return Number.isNaN(date.getTime()) ? null : date;
  }
  const date = new Date(raw);
  return Number.isNaN(date.getTime()) ? null : date;
};

const formatAgendaDate = (date) => {
  const d = new Date(date);
  if (Number.isNaN(d.getTime())) return "";
  const pad2 = (n) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())}`;
};

const parseAgendaTimeMinutes = (value) => {
  const raw = String(value || "").trim();
  if (!raw) return null;
  const m = raw.match(/^(\d{1,2}):(\d{2})/);
  if (!m) return null;
  const h = Number(m[1]);
  const min = Number(m[2]);
  if (!Number.isFinite(h) || !Number.isFinite(min)) return null;
  if (h < 0 || h > 23 || min < 0 || min > 59) return null;
  return (h * 60) + min;
};

const normalizeAgendaTimeString = (value) => {
  const raw = String(value || "").trim();
  if (!raw) return "";
  const m = raw.match(/^(\d{1,2}):(\d{2})/);
  if (!m) return raw;
  const h = Number(m[1]);
  const min = Number(m[2]);
  if (!Number.isFinite(h) || !Number.isFinite(min)) return raw;
  if (h < 0 || h > 23 || min < 0 || min > 59) return raw;
  return `${String(h).padStart(2, "0")}:${String(min).padStart(2, "0")}`;
};

const formatAgendaTimeFromMinutes = (minutes) => {
  if (!Number.isFinite(minutes)) return "";
  const total = ((Math.round(minutes) % (24 * 60)) + (24 * 60)) % (24 * 60);
  const h = Math.floor(total / 60);
  const m = total % 60;
  return `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}`;
};

const addMinutesToAgendaTime = (timeRaw, deltaMinutes) => {
  const start = parseAgendaTimeMinutes(timeRaw);
  if (start === null) return "";
  const delta = Number(deltaMinutes || 0);
  if (!Number.isFinite(delta)) return "";
  return formatAgendaTimeFromMinutes(start + delta);
};

const normalizeAgendaTimeRange = (startRaw, endRaw) => {
  const start = String(startRaw || "").trim();
  const end = String(endRaw || "").trim();
  if (!start) return { label: "Todo el día", start: "", end: "" };
  if (!end) return { label: start, start, end: "" };
  const startMin = parseAgendaTimeMinutes(start);
  const endMin = parseAgendaTimeMinutes(end);
  if (startMin === null || endMin === null) return { label: `${start}–${end}`, start, end };
  if (endMin <= startMin) return { label: start, start, end: "" };
  return { label: `${start}–${end}`, start, end };
};

const getWeekStart = (date) => {
  const day = new Date(date);
  const dow = (day.getDay() + 6) % 7;
  day.setDate(day.getDate() - dow);
  day.setHours(0, 0, 0, 0);
  return day;
};

const hashHue = (value) => {
  const text = String(value || "");
  let hash = 0;
  for (let i = 0; i < text.length; i += 1) {
    hash = (hash * 31 + text.charCodeAt(i)) >>> 0;
  }
  return hash % 360;
};

const agendaColorVarsForResponsible = (responsable) => {
  const raw = String(responsable || "").trim();
  if (!raw) {
    return { bg: "rgba(248, 250, 252, 0.95)", border: "rgba(15, 23, 42, 0.18)" };
  }
  const hue = hashHue(normalizeSimple(raw));
  return {
    bg: `hsla(${hue}, 80%, 90%, 0.96)`,
    border: `hsla(${hue}, 65%, 40%, 0.90)`,
  };
};

const resolveAgendaTipoBadge = (tipoRaw) => {
  const tipo = normalizeSimple(tipoRaw || "");
  if (!tipo) return "CITA";
  if (tipo.includes("cita")) return "CITA";
  if (tipo.includes("llamada") || tipo.includes("call")) return "LLAM.";
  if (tipo.includes("whatsapp") || tipo === "wa") return "WA";
  if (tipo.includes("email") || tipo.includes("mail") || tipo.includes("correo")) return "MAIL";
  if (tipo.includes("tarea")) return "TAREA";
  return "ACT.";
};

const resolveAgendaTipoKey = (tipoRaw) => {
  const tipo = normalizeSimple(tipoRaw || "");
  if (!tipo) return "cita";
  if (tipo.includes("cita")) return "cita";
  if (
    tipo.includes("llamada") ||
    tipo.includes("call") ||
    tipo.includes("whatsapp") ||
    tipo.includes("email") ||
    tipo.includes("mail") ||
    tipo.includes("correo")
  ) {
    return "tarea";
  }
  if (tipo.includes("tarea")) return "tarea";
  return "actividad";
};

const buildAgendaEvents = (rows = [], serviceId = "", serviceLabel = "") => {
  return rows
    .map((row) => {
      const date = parseAgendaDate(row.fecha);
      if (!date) return null;
      return {
        id: row.id || "",
        cliente_id: row.cliente_id || "",
        inmueble_id: row.inmueble_id || "",
        date,
        dateKey: formatAgendaDate(date),
        time: normalizeAgendaTimeString(row.hora || ""),
        timeEnd: normalizeAgendaTimeString(row.hora_fin || ""),
        tipo: row.tipo || "",
        cliente: row.cliente || "",
        responsable: row.responsable || "",
        estado: row.estado || "",
        notas: row.notas || "",
        recordatorio_min: row.recordatorio_min || "",
        serviceId: serviceId || row.servicio || "",
        serviceLabel: serviceLabel || SERVICE_LABELS[row.servicio] || row.servicio || "",
      };
    })
    .filter(Boolean);
};

const renderAgendaCalendar = (container, events, label = "") => {
  if (!container) return;
  const today = new Date();
  const state =
    agendaStates.get(container) || {
      view: "month",
      month: today.getMonth(),
      year: today.getFullYear(),
      day: formatAgendaDate(today),
      serviceFilter: "all",
      responsableFilter: "all",
    };
  const readOnly = container.dataset.readonly === "1";
  const defaultService = (container.dataset.service || "").trim();
  const availableServices = Array.from(
    new Set(events.map((ev) => ev.serviceId || ev.service).filter(Boolean))
  );
  const filteredEvents = events.filter((ev) => {
    if (state.serviceFilter && state.serviceFilter !== "all") {
      if ((ev.serviceId || ev.service) !== state.serviceFilter) return false;
    }
    if (state.responsableFilter && state.responsableFilter !== "all") {
      if ((ev.responsable || "") !== state.responsableFilter) return false;
    }
    return true;
  });
  const eventsByDate = new Map();
  filteredEvents.forEach((ev) => {
    if (!eventsByDate.has(ev.dateKey)) {
      eventsByDate.set(ev.dateKey, []);
    }
    eventsByDate.get(ev.dateKey).push(ev);
  });
  lastAgendaEvents = filteredEvents;

  const reminderEvents = filteredEvents.filter((ev) => {
    if (!ev.recordatorio_min || !ev.dateKey) return false;
    const time = ev.time || "00:00";
    const eventDate = new Date(`${ev.dateKey}T${time}`);
    if (Number.isNaN(eventDate.getTime())) return false;
    const minutes = (eventDate.getTime() - Date.now()) / 60000;
    if (minutes < 0 || minutes > Number(ev.recordatorio_min)) return false;
    const estado = normalizeSimple(ev.estado);
    if (["hecho", "completado", "finalizado", "cancelado"].includes(estado)) return false;
    const currentUser = getCurrentUser();
    if (currentUser && ev.responsable && ev.responsable !== currentUser) {
      return false;
    }
    return true;
  });

  const years = Array.from(
    new Set(filteredEvents.map((ev) => ev.date.getFullYear()).concat([today.getFullYear()]))
  ).sort((a, b) => a - b);

  container.innerHTML = "";
  const header = document.createElement("div");
  header.className = "agenda-controls";
  const title = document.createElement("div");
  title.innerHTML = `<strong>${label || "Agenda"}</strong>`;
  header.appendChild(title);

  const viewControls = document.createElement("div");
  viewControls.className = "agenda-view-controls";
  agendaViews.forEach((view) => {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = view === state.view ? "active" : "";
    btn.textContent =
      view === "day" ? "Día" : view === "week" ? "Semana" : view === "month" ? "Mes" : "Año";
    btn.addEventListener("click", () => {
      state.view = view;
      agendaStates.set(container, state);
      renderAgendaCalendar(container, events, label);
    });
    viewControls.appendChild(btn);
  });
  header.appendChild(viewControls);

  const rangeControls = document.createElement("div");
  rangeControls.className = "agenda-range-controls";
  const monthSelect = document.createElement("select");
  const monthNames = Array.from({ length: 12 }, (_, idx) =>
    new Date(2000, idx, 1).toLocaleString("es-ES", { month: "long" })
  );
  monthNames.forEach((name, idx) => {
    const option = createOption(idx, name);
    monthSelect.appendChild(option);
  });
  monthSelect.value = state.month;
  monthSelect.addEventListener("change", () => {
    state.month = Number(monthSelect.value);
    state.day = formatAgendaDate(new Date(state.year, state.month, 1));
    agendaStates.set(container, state);
    renderAgendaCalendar(container, events, label);
  });

  const yearSelect = document.createElement("select");
  years.forEach((year) => {
    yearSelect.appendChild(createOption(year, String(year)));
  });
  yearSelect.value = state.year;
  yearSelect.addEventListener("change", () => {
    state.year = Number(yearSelect.value);
    state.day = formatAgendaDate(new Date(state.year, state.month, 1));
    agendaStates.set(container, state);
    renderAgendaCalendar(container, events, label);
  });
  rangeControls.appendChild(monthSelect);
  rangeControls.appendChild(yearSelect);
  header.appendChild(rangeControls);

  const inferredService =
    availableServices.length === 1 ? availableServices[0] : defaultService || "";
  if (!readOnly) {
    const createBtn = document.createElement("button");
    createBtn.type = "button";
    createBtn.className = "agenda-create";
    createBtn.textContent = "Nueva cita";
    createBtn.addEventListener("click", () => {
      const serviceValue =
        state.serviceFilter && state.serviceFilter !== "all"
          ? state.serviceFilter
          : inferredService;
      openActionCreator(state.day, "", serviceValue);
    });
    header.appendChild(createBtn);
  }

  const filterControls = document.createElement("div");
  filterControls.className = "agenda-filters";
  if (availableServices.length > 1) {
    const serviceSelect = document.createElement("select");
    serviceSelect.appendChild(createOption("all", "Todos los servicios"));
    availableServices.forEach((service) => {
      const label = SERVICE_LABELS[service] || service;
      serviceSelect.appendChild(createOption(service, label));
    });
    serviceSelect.value = state.serviceFilter || "all";
    serviceSelect.addEventListener("change", () => {
      state.serviceFilter = serviceSelect.value;
      agendaStates.set(container, state);
      renderAgendaCalendar(container, events, label);
    });
    filterControls.appendChild(serviceSelect);
  }
  const responsableSelect = document.createElement("select");
  responsableSelect.appendChild(createOption("all", "Todos los responsables"));
  const responsables = Array.from(
    new Set(filteredEvents.map((ev) => ev.responsable).filter(Boolean))
  ).sort();
  responsables.forEach((responsable) => {
    responsableSelect.appendChild(createOption(responsable, responsable));
  });
  responsableSelect.value = state.responsableFilter || "all";
  responsableSelect.addEventListener("change", () => {
    state.responsableFilter = responsableSelect.value;
    agendaStates.set(container, state);
    renderAgendaCalendar(container, events, label);
  });
  filterControls.appendChild(responsableSelect);
  header.appendChild(filterControls);

  container.appendChild(header);

  if (reminderEvents.length) {
    const reminderBox = document.createElement("div");
    reminderBox.className = "agenda-reminders";
    reminderBox.innerHTML = "<strong>Recordatorios próximos</strong>";
    const list = document.createElement("div");
    list.className = "agenda-reminders-list";
    reminderEvents.slice(0, 5).forEach((ev) => {
      const row = document.createElement("div");
      row.className = "agenda-reminder-row";
      row.textContent = `${ev.time || ""} · ${ev.cliente || ev.tipo || "Acción"} · ${ev.serviceLabel || ev.service || ""}`;
      list.appendChild(row);
    });
    reminderBox.appendChild(list);
    container.appendChild(reminderBox);
  }

  const body = document.createElement("div");
  body.className = "agenda-body";

  const updateActionDate = async (id, fecha, hora) => {
    if (readOnly) return;
    if (!id || !fecha) return;
    const target = events.find((ev) => ev.id === id) || null;
    const payload = { id, fecha, usuario: getCurrentUser() };
    // IMPORTANTE: si `hora` NO se envía, backend no la borra. Así al arrastrar de día a día se conserva.
    const horaNorm = typeof hora === "string" ? String(hora || "").trim() : "";
    if (horaNorm) {
      payload.hora = normalizeAgendaTimeString(horaNorm);
      // Conserva duración al mover dentro del día.
      const startPrev = parseAgendaTimeMinutes(target?.time || "");
      const endPrev = parseAgendaTimeMinutes(target?.timeEnd || "");
      if (startPrev !== null && endPrev !== null && endPrev > startPrev) {
        const duration = endPrev - startPrev;
        payload.hora_fin = formatAgendaTimeFromMinutes(parseAgendaTimeMinutes(payload.hora) + duration);
      }
    }
    try {
      await apiPost("/api/acciones_update", payload);
      if (target) {
        const newDate = parseAgendaDate(fecha);
        if (newDate) {
          target.date = newDate;
          target.dateKey = formatAgendaDate(newDate);
        }
        if (horaNorm) {
          target.time = payload.hora;
          if (payload.hora_fin) target.timeEnd = payload.hora_fin;
        }
      }
      renderAgendaCalendar(container, events, label);
    } catch (err) {
      try {
        setUiToast("No se pudo mover la cita", String(err?.message || "Error desconocido"));
      } catch (e) {}
    }
  };

  const makeEventRow = (ev, compact = false) => {
    const row = document.createElement("div");
    const estadoKey = normalizeSimple(ev.estado || "pendiente") || "pendiente";
    const timeMeta = normalizeAgendaTimeRange(ev.time || "", ev.timeEnd || "");
    const titleText = formatNombreCliente(ev.cliente || "") || String(ev.tipo || "").trim() || "Acción";
    const serviceText = String(ev.serviceLabel || ev.service || "").trim();
    const responsableText = String(ev.responsable || "").trim() || "Sin responsable";
    const estadoText = String(ev.estado || "").trim() || "Pendiente";
    const notesText = String(ev.notas || "").trim();
    row.className = compact
      ? `agenda-week-row agenda-event estado-${estadoKey}`
      : `agenda-day-row agenda-event estado-${estadoKey}`;
    row.draggable = !readOnly;
    row.dataset.id = ev.id || "";
    row.dataset.date = ev.dateKey;
    row.innerHTML = `
      <div class="agenda-time">${escapeHtml(timeMeta.label || "-")}</div>
      <div class="agenda-info">
        <div class="agenda-title">${escapeHtml(titleText)}</div>
        <div class="agenda-meta">${escapeHtml(serviceText)} · ${escapeHtml(responsableText)} · ${escapeHtml(estadoText)}</div>
        ${compact || !notesText ? "" : `<div class="agenda-notes">${escapeHtml(notesText)}</div>`}
      </div>
    `;
    if (ev.inmueble_id) {
      const link = document.createElement("button");
      link.type = "button";
      link.className = "agenda-link";
      link.textContent = "Ver inmueble";
      link.addEventListener("click", (event) => {
        event.stopPropagation();
        openInmuebleFromAgenda(ev.inmueble_id);
      });
      row.appendChild(link);
    }
    if (!readOnly) {
      row.addEventListener("click", () => {
        openActionEditor(ev);
      });
      row.addEventListener("dragstart", (event) => {
        event.dataTransfer.setData("text/plain", ev.id || "");
        try {
          event.dataTransfer.effectAllowed = "move";
        } catch (e) {}
      });
    }
    return row;
  };

  if (state.view === "year") {
    const grid = document.createElement("div");
    grid.className = "agenda-year-grid";
    monthNames.forEach((name, idx) => {
      const monthCell = document.createElement("button");
      monthCell.type = "button";
      monthCell.className = "agenda-year-cell";
      const count = filteredEvents.filter(
        (ev) => ev.date.getFullYear() === state.year && ev.date.getMonth() === idx
      ).length;
      monthCell.innerHTML = `<div class="month-name">${name}</div><div class="month-count">${count} acciones</div>`;
      monthCell.addEventListener("click", () => {
        state.view = "month";
        state.month = idx;
        agendaStates.set(container, state);
        renderAgendaCalendar(container, events, label);
      });
      grid.appendChild(monthCell);
    });
    body.appendChild(grid);
  } else if (state.view === "month") {
    const monthGrid = document.createElement("div");
    monthGrid.className = "agenda-month-grid";
    const monthStart = new Date(state.year, state.month, 1);
    const monthEnd = new Date(state.year, state.month + 1, 0);
    const startDay = (monthStart.getDay() + 6) % 7;
    const totalDays = monthEnd.getDate();
    const weekHeader = document.createElement("div");
    weekHeader.className = "agenda-weekdays";
    ["L", "M", "X", "J", "V", "S", "D"].forEach((labelDay) => {
      const cell = document.createElement("div");
      cell.textContent = labelDay;
      weekHeader.appendChild(cell);
    });
    monthGrid.appendChild(weekHeader);
    const daysGrid = document.createElement("div");
    daysGrid.className = "agenda-days";
    for (let i = 0; i < startDay; i += 1) {
      const empty = document.createElement("div");
      empty.className = "agenda-day empty";
      daysGrid.appendChild(empty);
    }
    for (let day = 1; day <= totalDays; day += 1) {
      const date = new Date(state.year, state.month, day);
      const dateKey = formatAgendaDate(date);
      const dayEvents = eventsByDate.get(dateKey) || [];
      const statusCounts = dayEvents.reduce((acc, ev) => {
        const key = normalizeSimple(ev.estado || "pendiente") || "pendiente";
        acc[key] = (acc[key] || 0) + 1;
        return acc;
      }, {});
      const dominantStatus = Object.entries(statusCounts).sort((a, b) => b[1] - a[1])[0]?.[0];
      const cell = document.createElement("button");
      cell.type = "button";
      cell.className = "agenda-day";
      if (dominantStatus) {
        cell.classList.add(`day-status-${dominantStatus}`);
      }
      if (dateKey === state.day) {
        cell.classList.add("active");
      }
      cell.innerHTML = `<span class="day-number">${day}</span><span class="day-count">${dayEvents.length || ""}</span>`;
      cell.addEventListener("click", () => {
        state.day = dateKey;
        agendaStates.set(container, state);
        renderAgendaCalendar(container, events, label);
      });
      if (!readOnly) {
        cell.addEventListener("dblclick", () => {
          const serviceValue =
            state.serviceFilter && state.serviceFilter !== "all"
              ? state.serviceFilter
              : inferredService;
          openActionCreator(dateKey, "", serviceValue);
        });
      }
      if (!readOnly) {
        cell.addEventListener("dragover", (event) => event.preventDefault());
        cell.addEventListener("drop", (event) => {
          event.preventDefault();
          const id = event.dataTransfer.getData("text/plain");
          updateActionDate(id, dateKey);
        });
      }
      daysGrid.appendChild(cell);
    }
    monthGrid.appendChild(daysGrid);
    const side = document.createElement("div");
    side.className = "agenda-side";
    const sideEvents = eventsByDate.get(state.day) || [];
    const sideTitle = document.createElement("div");
    sideTitle.className = "agenda-side-title";
    sideTitle.textContent = state.day;
    side.appendChild(sideTitle);
    if (!sideEvents.length) {
      side.innerHTML += "<p class='muted'>Sin acciones.</p>";
    } else {
      sideEvents
        .sort((a, b) => (a.time || "").localeCompare(b.time || ""))
        .forEach((ev) => {
          const row = makeEventRow(ev);
          const openBtn = document.createElement("button");
          openBtn.type = "button";
          openBtn.className = "agenda-open-client";
          openBtn.textContent = "Abrir cliente";
          openBtn.addEventListener("click", (event) => {
            event.stopPropagation();
            if (ev.cliente_id) {
              openClienteDetail(ev.cliente_id);
            }
          });
          row.appendChild(openBtn);
          side.appendChild(row);
        });
    }
    const wrap = document.createElement("div");
    wrap.className = "agenda-split";
    wrap.appendChild(monthGrid);
    wrap.appendChild(side);
    body.appendChild(wrap);
  } else if (state.view === "week") {
    const weekStart = getWeekStart(state.day || formatAgendaDate(today));
    const week = document.createElement("div");
    week.className = "agenda-week-grid";
    const hours = Array.from({ length: 13 }, (_, idx) => 8 + idx);
    for (let i = 0; i < 7; i += 1) {
      const dayDate = new Date(weekStart);
      dayDate.setDate(dayDate.getDate() + i);
      const dayKey = formatAgendaDate(dayDate);
      const dayEvents = eventsByDate.get(dayKey) || [];
      const column = document.createElement("div");
      column.className = "agenda-week-day";
      const headerDay = document.createElement("div");
      headerDay.className = "agenda-week-title";
      headerDay.textContent = dayDate.toLocaleString("es-ES", {
        weekday: "short",
        day: "numeric",
        month: "short",
      });
      column.appendChild(headerDay);
      if (!readOnly) {
        column.addEventListener("dragover", (event) => event.preventDefault());
        column.addEventListener("drop", (event) => {
          event.preventDefault();
          const id = event.dataTransfer.getData("text/plain");
          updateActionDate(id, dayKey);
        });
      }
      const hoursGrid = document.createElement("div");
      hoursGrid.className = "agenda-week-hours";
      hours.forEach((hour) => {
        const hourCell = document.createElement("div");
        hourCell.className = "agenda-week-hour";
        const label = document.createElement("div");
        label.className = "agenda-hour-label";
        label.textContent = `${String(hour).padStart(2, "0")}:00`;
        hourCell.appendChild(label);
        const slot = document.createElement("div");
        slot.className = "agenda-hour-slot";
        if (!readOnly) {
          slot.addEventListener("dragover", (event) => event.preventDefault());
          slot.addEventListener("drop", (event) => {
            event.preventDefault();
            const id = event.dataTransfer.getData("text/plain");
            updateActionDate(id, dayKey, `${String(hour).padStart(2, "0")}:00`);
          });
          slot.addEventListener("click", (event) => {
            // Si pulsas sobre una cita existente, no abras “nuevo”.
            if (event?.target?.closest?.(".agenda-event")) return;
            const serviceValue =
              state.serviceFilter && state.serviceFilter !== "all"
                ? state.serviceFilter
                : inferredService;
            openActionCreator(dayKey, `${String(hour).padStart(2, "0")}:00`, serviceValue);
          });
        }
        const slotEvents = dayEvents.filter((ev) => {
          if (!ev.time) return false;
          const evHour = Number(ev.time.split(":")[0]);
          return evHour === hour;
        });
        if (slotEvents.length) {
          slotEvents.forEach((ev) => {
            slot.appendChild(makeEventRow(ev, true));
          });
        }
        hourCell.appendChild(slot);
        hoursGrid.appendChild(hourCell);
      });
      if (!dayEvents.length) {
        const empty = document.createElement("div");
        empty.className = "muted";
        empty.textContent = "Sin acciones";
        column.appendChild(empty);
      }
      column.appendChild(hoursGrid);
      week.appendChild(column);
    }
    body.appendChild(week);
  } else {
    const dayEvents = eventsByDate.get(state.day) || [];
    const hours = Array.from({ length: 13 }, (_, idx) => 8 + idx);
    const dayGrid = document.createElement("div");
    dayGrid.className = "agenda-day-hours";
    hours.forEach((hour) => {
      const hourCell = document.createElement("div");
      hourCell.className = "agenda-week-hour";
      const label = document.createElement("div");
      label.className = "agenda-hour-label";
      label.textContent = `${String(hour).padStart(2, "0")}:00`;
      hourCell.appendChild(label);
      const slot = document.createElement("div");
      slot.className = "agenda-hour-slot";
      if (!readOnly) {
        slot.addEventListener("dragover", (event) => event.preventDefault());
        slot.addEventListener("drop", (event) => {
          event.preventDefault();
          const id = event.dataTransfer.getData("text/plain");
          updateActionDate(id, state.day, `${String(hour).padStart(2, "0")}:00`);
        });
        slot.addEventListener("click", (event) => {
          if (event?.target?.closest?.(".agenda-event")) return;
          const serviceValue =
            state.serviceFilter && state.serviceFilter !== "all"
              ? state.serviceFilter
              : inferredService;
          openActionCreator(state.day, `${String(hour).padStart(2, "0")}:00`, serviceValue);
        });
      }
      const slotEvents = dayEvents.filter((ev) => {
        if (!ev.time) return false;
        const evHour = Number(ev.time.split(":")[0]);
        return evHour === hour;
      });
      if (slotEvents.length) {
        slotEvents.forEach((ev) => {
          slot.appendChild(makeEventRow(ev, true));
        });
      }
      hourCell.appendChild(slot);
      dayGrid.appendChild(hourCell);
    });
    body.appendChild(dayGrid);
    const list = document.createElement("div");
    list.className = "agenda-day-list";
    if (!dayEvents.length) {
      list.innerHTML = "<p class='muted'>Sin acciones para este día.</p>";
    } else {
      dayEvents
        .sort((a, b) => (a.time || "").localeCompare(b.time || ""))
        .forEach((ev) => {
          list.appendChild(makeEventRow(ev));
        });
    }
    body.appendChild(list);
  }

  container.appendChild(body);
};

const normalizeYear = (value) => {
  if (value === null || value === undefined || value === "") {
    return null;
  }
  return String(value);
};

const getYearValue = (series, year) => {
  const target = normalizeYear(year);
  const entry = series.find((item) => normalizeYear(item.year) === target);
  return entry ? entry.total || 0 : 0;
};

const buildCompanyMeta = (item, selectedYear) => {
  const isEstudio = item.empresa === DASHBOARD_COMPANY;
  const finEmpresa = resolveCrmFinEmpresa();
  const isFin = !!finEmpresa && item.empresa === finEmpresa.nombre;
  const isFincas = item.empresa === FINCAS_COMPANY;
  if (isEstudio && state.homeDashboard && selectedYear) {
    const ventas = getYearValue(state.homeDashboard.ventas, selectedYear);
    const alquileres = getYearValue(state.homeDashboard.alquileres, selectedYear);
    const facturado = getYearValue(state.homeDashboard.ingresos, selectedYear);
    const gastos = getYearValue(state.homeDashboard.gastos, selectedYear);
    return [
      `Compraventas ${selectedYear}: ${numberFormatter.format(ventas)}`,
      `Alquileres ${selectedYear}: ${numberFormatter.format(alquileres)}`,
      `Facturado: ${euroFormatter.format(facturado)}`,
      `Gastos: ${euroFormatter.format(gastos)}`,
    ];
  }
  if (isFin && state.homeHipotecaStats) {
    const stats = state.homeHipotecaStats;
    return [
      `Hipotecas totales: ${numberFormatter.format(stats.total || 0)}`,
      `Firmadas mes: ${numberFormatter.format(stats.firmadas_mes || 0)}`,
      `Financiacion media: ${formatPercent(stats.porcentaje_medio)}`,
      `Comision media: ${euroFormatter.format(stats.comision_media || 0)}`,
    ];
  }
  if (isFincas && state.homeFincasStats) {
    const stats = state.homeFincasStats;
    return [
      `Facturado ${stats.year}: ${euroFormatter.format(stats.facturado || 0)}`,
      `Gastos ${stats.year}: ${euroFormatter.format(stats.gastos || 0)}`,
      `Clientes empresa: ${numberFormatter.format(stats.clientes_empresas || 0)}`,
      `Autónomos: ${numberFormatter.format(stats.autonomos || 0)}`,
      `Pólizas en vigor: ${numberFormatter.format(stats.polizas_vigor || 0)}`,
      `Comunidades: ${numberFormatter.format(stats.comunidades || 0)}`,
    ];
  }
  return [
    `Seguros: ${item.seguros} · Gestoría: ${item.gestoria}`,
    `Hipotecas: ${item.hipotecas} · Alquileres: ${item.alquileres}`,
    `Inversores: ${item.inversores} · Ops: ${item.inversure_ops}`,
  ];
};

const renderCompanyCards = () => {
  if (coreCards) {
    coreCards.innerHTML = "";
  }
  if (coreCards) {
    const user = getAuthScopeUser();
    const isPriv = hasAdminWideAccess(user);
    const canAdmin = canAccessAdminPanel(user);
    const canInmo = userCanAccessService("inmobiliaria");
    const canGestoria = userCanAccessService("gestoria");
    const canSeguros = userCanAccessService("seguros");
    const canFin = userCanAccessService("financiaciones");
    const primaryRestrictedService = getPrimaryRestrictedHomeService(user);
	    const enabledModules = new Set(state.currentWorkspaceEnabledModules || []);
	    const workspaceScoped = enabledModules.size > 0;
	    const timeProfile = findCurrentUserTimeProfile();
	    const workspaceSlug = resolveDefaultTenantWorkspaceSlug();
      const dedupeCoreCards = () => {
        // Defensive: evita duplicados por estados intermedios / renderizados repetidos.
        try {
          const seen = new Set();
          Array.from(coreCards.children || []).forEach((node) => {
            if (!node || node.nodeType !== 1) return;
            const el = node;
            const actionKey = String(el.dataset?.action || "").trim();
            const titleKey = String(el.querySelector?.("h3")?.textContent || "").trim();
            const hrefKey = String(el.querySelector?.("a.card-link")?.getAttribute?.("href") || "").trim();
            const key = `${actionKey}::${hrefKey}::${titleKey}`;
            if (!titleKey && !actionKey && !hrefKey) return;
            if (seen.has(key)) {
              el.remove();
              return;
            }
            seen.add(key);
          });
        } catch (e) {}
      };

	    const buildInitials = (value) => {
      const parts = String(value || "")
        .trim()
        .split(/\s+/)
        .filter(Boolean);
      if (!parts.length) return "U";
      const letters = parts.slice(0, 2).map((p) => p[0]).join("");
      return letters.toUpperCase();
    };

			    const appendPersonalCard = () => {
		      const employee = timeProfile?.employee || null;
		      const homePersona = state.homeTimeStatus?.persona || null;
		      const personaId = String(employee?.id || homePersona?.id || "").trim();
			      const isAdmin = isPrivilegedUser(user) || canAccessAdminPanel(user);
			      // La card "Personal" siempre abre RRHH en modo self, incluso para admins.
			      // Así no te manda a "Equipo" y siempre ves tu espacio personal.
			      const rrhhHref = `/?holding=1&mode=tenant&workspace=${encodeURIComponent(workspaceSlug)}&view=rrhh&rrhh=self`;
	      const displayName =
	        employee?.nombre
	        || homePersona?.nombre
	        || `${user?.nombre || ""} ${user?.apellido || ""}`.trim()
	        || user?.usuario
        || user?.email
        || "Usuario";
      const companyLabel =
        employee?.empresa_nombre
        || homePersona?.empresa_nombre
        || getWorkspaceDisplayName(state.currentWorkspaceName || workspaceSlug || DEFAULT_TENANT_WORKSPACE_SLUG);
      const photoUrl = String(employee?.foto_url || "").trim();
      const homeToday = state.homeTimeStatus?.today || null;
      const entryLabel = timeProfile?.latestEntry
        ? `${timeProfile.latestEntry.hora_inicio || "--:--"}${timeProfile.latestEntry.hora_fin ? ` - ${timeProfile.latestEntry.hora_fin}` : " · Abierto"}`
        : (homeToday?.checkin
          ? `${homeToday.checkin || "--:--"}${homeToday.checkout ? ` - ${homeToday.checkout}` : " · Abierto"}`
          : "Sin fichaje de hoy");
      const seniority = (() => {
        const iso = String(employee?.fecha_alta || "").slice(0, 10);
        if (!/^\d{4}-\d{2}-\d{2}$/.test(iso)) return "";
        const parts = iso.split("-").map((v) => Number(v));
        const start = new Date(parts[0], parts[1] - 1, parts[2]);
        if (Number.isNaN(start.getTime())) return "";
        const end = new Date();
        const endDate = new Date(end.getFullYear(), end.getMonth(), end.getDate());
        let months = (endDate.getFullYear() - start.getFullYear()) * 12 + (endDate.getMonth() - start.getMonth());
        if (endDate.getDate() < start.getDate()) months -= 1;
        months = Math.max(0, months);
        const years = Math.floor(months / 12);
        const rem = months % 12;
        return years > 0 ? `${years}a ${rem}m` : `${months}m`;
      })();
	      const subtitle = (employee || homePersona)
	        ? `${companyLabel} · ${entryLabel}${seniority ? ` · Antigüedad ${seniority}` : ""}`
	        : "Completa tu ficha y documentación en RRHH.";
	      const timeLabel = (() => {
	        const status = state.homeTimeStatus || null;
	        const personaOk = Boolean(String(status?.persona?.id || "").trim());
	        return personaOk ? "Fichar" : "Registro horario";
	      })();
		      const card = document.createElement("div");
		      card.className = "company-card personal-card";
		      card.dataset.action = "rrhh-home";
		      if (personaId) card.dataset.rrhhPersona = personaId;
		      card.innerHTML = `
		        <div class="company-card-head">
          <div class="rrhh-avatar">
            ${photoUrl ? `<img src="${escapeHtml(buildPhotoSrc(photoUrl))}" alt="" />` : `<span class="rrhh-avatar-initials">${escapeHtml(buildInitials(displayName))}</span>`}
          </div>
          <div>
            <h3>Personal</h3>
            <div class="company-meta">${escapeHtml(displayName)}</div>
            <div class="company-meta">${escapeHtml(subtitle)}</div>
          </div>
			        </div>
			        <div class="workspace-home-card-actions">
			          <a class="card-link" href="${rrhhHref}" data-action="rrhh-home">Abrir</a>
			          <button type="button" class="secondary ghost button-inline" data-action="time-punch">${timeLabel}</button>
			        </div>
			      `;
		      coreCards.appendChild(card);
		    };

		    const appendServiceCard = (serviceKey) => {
		      const service = normalizeSimple(serviceKey);
		      const card = document.createElement("div");
		      card.className = "company-card";
		      const tenantPrefix = workspaceScoped
		        ? `/?holding=1&mode=tenant&workspace=${encodeURIComponent(workspaceSlug)}`
		        : "";
		      if (service === "inmobiliaria") {
		        card.dataset.action = "crm-inmo";
	        card.innerHTML = `
	          <h3>CRM Inmobiliario</h3>
	          <div class="company-meta">Noticias, inmuebles y operaciones.</div>
	          <div class="company-meta">Servicio inmobiliario.</div>
	          <a class="card-link" href="${tenantPrefix ? `${tenantPrefix}&crm=inmo&tab=crm` : "/?crm=inmo"}" data-action="crm-inmo">Entrar</a>
	        `;
		      } else if (service === "gestoria") {
		        card.dataset.action = "crm-gestoria";
		        card.innerHTML = `
		          <h3>CRM Gestoría</h3>
		          <div class="company-meta">Clientes en gestión y seguimiento.</div>
		          <div class="company-meta">Servicio de gestoría.</div>
		          <a class="card-link" href="${tenantPrefix ? `${tenantPrefix}&crm=gestoria&tab=gestoria-crm` : "/?crm=gestoria"}" data-action="crm-gestoria">Entrar</a>
		        `;
		      } else if (service === "fincas") {
		        const href = tenantPrefix ? `${tenantPrefix}&view=fincas` : `/?holding=1&mode=tenant&workspace=${encodeURIComponent(workspaceSlug)}&view=fincas`;
		        card.dataset.action = "workspace-fincas";
		        card.innerHTML = `
		          <h3>Fincas</h3>
		          <div class="company-meta">Comunidades, incidencias, juntas y seguimiento.</div>
		          <div class="company-meta">Área de administración de fincas.</div>
		          <a class="card-link" href="${href}" data-action="workspace-fincas">Entrar</a>
		        `;
		      } else if (service === "seguros") {
		        card.dataset.action = "crm-seguros";
		        card.innerHTML = `
	          <h3>CRM Seguros</h3>
	          <div class="company-meta">Pólizas, renovaciones y oportunidades.</div>
	          <div class="company-meta">Servicio de seguros.</div>
	          <a class="card-link" href="${tenantPrefix ? `${tenantPrefix}&crm=seguros&tab=seguros-crm` : "/?crm=seguros"}" data-action="crm-seguros">Entrar</a>
	        `;
	      } else if (service === "financiaciones") {
	        card.dataset.action = "crm-fin";
	        card.innerHTML = `
	          <h3>CRM Financiaciones</h3>
	          <div class="company-meta">Hipotecas y seguimiento.</div>
	          <div class="company-meta">Servicio financiero.</div>
		          <a class="card-link" href="${tenantPrefix ? `${tenantPrefix}&crm=fin&tab=fin-crm` : "/?crm=fin"}" data-action="crm-fin">Entrar</a>
	        `;
		      } else {
		        return;
		      }
		      coreCards.appendChild(card);
		    };

	    const appendSimuladoresCard = () => {
	      const href = `/?holding=1&mode=tenant&workspace=${encodeURIComponent(workspaceSlug)}&view=motores&engine=simuladores`;
	      const card = document.createElement("div");
	      card.className = "company-card";
	      card.dataset.action = "workspace-simuladores";
	      card.innerHTML = `
	        <h3>Simuladores fiscales</h3>
	        <div class="company-meta">IRPF/IRNR, IIVTNU y generación de informe PDF.</div>
	        <div class="company-meta">Útil para ventas y expedientes.</div>
	        <a class="card-link" href="${href}" data-action="workspace-simuladores">Abrir</a>
	      `;
	      coreCards.appendChild(card);
	    };

		    if (!isPriv) {
		      appendPersonalCard();
		      // Cards de servicios asignados: el usuario no admin debe poder entrar directamente al servicio.
		      try {
		        const services = expandServiceAliases(parseServiceList(user?.servicio || ""));
		        const mapped = new Set();
		        services.forEach((key) => {
		          if (key === "hipotecas") key = "financiaciones";
		          if (["inmobiliaria", "gestoria", "seguros", "financiaciones", "fincas"].includes(key)) mapped.add(key);
		        });
		        Array.from(mapped).forEach((key) => appendServiceCard(key));
		        if (mapped.has("gestoria") || mapped.has("inmobiliaria") || mapped.has("fincas")) {
		          appendSimuladoresCard();
		        }
		      } catch (e) {}
		      // Prompt de fichaje (solo si aplica al usuario).
		      maybeAutoShowHomeTimePunchModal();
	        dedupeCoreCards();
		      return;
		    }

    appendPersonalCard();
    const platformCard = document.createElement("div");
    platformCard.className = "company-card";
    platformCard.dataset.action = "holding-admin";
    platformCard.innerHTML = `
      <h3>Admin Verifika²</h3>
      <div class="company-meta">Configuración de workspaces, módulos, branding y control de plataforma.</div>
      <div class="company-meta">Vista de administración global.</div>
	      <a class="card-link" href="/?holding=1&mode=platform" data-action="holding-admin">Entrar</a>
    `;
    coreCards.appendChild(platformCard);

	    const homeWorkspacesCard = document.createElement("div");
    homeWorkspacesCard.className = "company-card";
    homeWorkspacesCard.dataset.action = "holding-workspaces";
    homeWorkspacesCard.innerHTML = `
      <h3>Workspaces</h3>
      <div class="company-meta">Cargando lista de workspaces...</div>
      <div class="company-meta">Selecciona dónde quieres entrar.</div>
	      <a class="card-link" href="/?holding=1&mode=platform&view=tenant" data-action="holding-workspaces">Ver listado</a>
    `;
	    coreCards.appendChild(homeWorkspacesCard);

      // En el home (admins) mostramos cada workspace como card independiente.
      // Esto evita confusión con "Workspace Verifika²" cuando hay múltiples workspaces.
      try {
        const renderId = `${Date.now()}-${Math.random().toString(16).slice(2)}`;
        state.homeWorkspacesRenderId = renderId;
        (async () => {
          // Evita llamadas repetidas si el home se repinta varias veces.
          const now = Date.now();
          const recentRows = Array.isArray(state.homeWorkspacesRows) ? state.homeWorkspacesRows : null;
          const recentAt = Number(state.homeWorkspacesFetchedAt || 0) || 0;
          let rows = recentRows && (now - recentAt) < 60_000 ? recentRows : null;
          if (!rows) {
            const data = await safeWorkspaceApi("/api/workspaces", null);
            rows = Array.isArray(data?.rows) ? data.rows : null;
            if (rows) {
              state.homeWorkspacesRows = rows;
              state.homeWorkspacesFetchedAt = Date.now();
            }
          }
          if (state.homeWorkspacesRenderId !== renderId) return;
          if (!rows || !rows.length) return;
          if (!coreCards || !coreCards.contains(homeWorkspacesCard)) return;

          // Reemplaza la card "Workspaces" por N cards, una por workspace.
          try {
            homeWorkspacesCard.remove();
          } catch (e) {}
          rows.forEach((row) => {
            const workspaceId = String(row?.id || "").trim();
            const rawName = String(row?.nombre || row?.name || row?.slug || row?.id || "").trim();
            const brandedName = getWorkspaceDisplayName(row);
            const showBranding =
              rawName
              && brandedName
              && normalizeWorkspaceIdentifier(rawName) !== normalizeWorkspaceIdentifier(brandedName);
            const meta = [
              String(row?.kind || "").trim() || "Directo",
              String(row?.plan || "").trim() || "Enterprise",
              String(row?.estado || "").trim() || "Activo",
            ].filter(Boolean);
            const counts = [
              `Empresas: ${numberFormatter.format(Number(row?.empresas_total || 0) || 0)}`,
              `Módulos: ${numberFormatter.format(Number(row?.modulos_activos || 0) || 0)}`,
            ];
            const card = document.createElement("div");
            card.className = "company-card";
            card.dataset.action = `home-workspace:${workspaceId || rawName || brandedName}`;
	            const href = workspaceId
	              ? `/?holding=1&mode=tenant&workspace=${encodeURIComponent(workspaceId)}&view=operations`
	              : `/?holding=1&mode=platform&view=tenant`;
            card.innerHTML = `
              <h3>${escapeHtml(rawName || brandedName || "Workspace")}</h3>
              <div class="company-meta">${escapeHtml(meta.join(" · "))}${showBranding ? ` · Marca: ${escapeHtml(brandedName)}` : ""}</div>
              <div class="company-meta">${escapeHtml(counts.join(" · "))}</div>
              <a class="card-link" href="${href}">Entrar</a>
            `;
            coreCards.appendChild(card);
          });
          dedupeCoreCards();
        })();
      } catch (e) {}
	    maybeAutoShowHomeTimePunchModal();
      dedupeCoreCards();
	  }
	};

const getClientesCardCount = () => {
  const clientesCountRaw =
    state.clientesCardStats?.total ??
    state.clientesCardStats?.count ??
    state.clientesCardStats?.clientes_total ??
    state.clientesStats?.total ??
    state.clientesStats?.count ??
    state.clientesStats?.clientes_total ??
    (Array.isArray(state.clientesList) ? state.clientesList.length : 0);
  return Number(clientesCountRaw) || 0;
};

const refreshClientesCardCount = () => {
  const el = document.getElementById("clientesCardTotal");
  if (!el) return;
  const clientesCount = getClientesCardCount();
  el.textContent = numberFormatter.format(clientesCount);
};

