const getWorkspaceModuleMeta = (row = {}) => {
  const base = WORKSPACE_MODULE_STRUCTURE[row.modulo_key] || {};
  return {
    section: base.section || "workspace_engines",
    family: base.family || (WORKSPACE_CATEGORY_LABELS[row.categoria] || "Módulo"),
    badge: base.badge || "Módulo",
    description: base.description || "Capacidad configurable del workspace dentro de Verifika².",
  };
};

const groupWorkspaceModulesBySection = (rows = []) =>
  WORKSPACE_SECTION_DEFINITIONS.map((section) => ({
    ...section,
    rows: rows.filter((row) => getWorkspaceModuleMeta(row).section === section.key),
  })).filter((section) => section.rows.length);

const normalizeWorkspaceIdentifier = (value = "") => normalizeSimple(String(value || "").trim());
const isTenantWorkspaceMode = () => (state.currentWorkspaceEntryMode || "platform") === "tenant";
const normalizeMonthValue = (value = "") => {
  const raw = String(value || "").trim();
  if (/^\d{4}-\d{2}$/.test(raw)) return raw;
  return new Date().toISOString().slice(0, 7);
};

const safeSetMonthInputValue = (input, value) => {
  if (!input) return;
  const normalized = normalizeMonthValue(value);
  try {
    input.value = normalized;
  } catch {
    try {
      input.value = "";
    } catch (e) {}
  }
};

const getWorkspaceDisplayName = (workspace = null) => {
  const rawName =
    typeof workspace === "string"
      ? workspace
      : workspace?.nombre || workspace?.name || workspace?.slug || workspace?.id || "";
  const normalized = normalizeWorkspaceIdentifier(rawName);
  if (!normalized) return "Workspace";
  if (["modernia", "grupomodernia", "grupo-modernia", "verifika2", "verifika", "verifika-2"].includes(normalized)) {
    return DEFAULT_TENANT_WORKSPACE_NAME;
  }
  return rawName;
};

const isGrupoModerniaWorkspace = () => {
  const candidates = [
    state.currentWorkspaceDetail?.workspace?.nombre,
    state.currentWorkspaceDetail?.workspace?.slug,
    state.currentWorkspaceName,
    state.currentWorkspaceTarget,
  ];
  return candidates.some((value) => {
    const normalized = normalizeWorkspaceIdentifier(value || "");
    return ["modernia", "grupomodernia", "grupo-modernia", "verifika2", "verifika", "verifika-2"].includes(normalized);
  });
};

const workspaceHasEnabledModule = (moduleKey = "") =>
  new Set(state.currentWorkspaceEnabledModules || []).has(String(moduleKey || "").trim());

const canUseLegalCopilot = () => isGrupoModerniaWorkspace() || workspaceHasEnabledModule("copilot");

const syncCrmLegalAvailability = () => {
  const enabled = canUseLegalCopilot();
  const legalTabBtn = crmWorkspaceTabs?.querySelector('[data-crm-view="legal"]');
  if (legalTabBtn) {
    legalTabBtn.classList.toggle("hidden", !enabled);
    legalTabBtn.disabled = !enabled;
  }
  if (!enabled && state.crmWorkspaceView === "legal") {
    state.crmWorkspaceView = "resumen";
  }
};

const findWorkspaceRecord = (rows = [], identifier = "") => {
  const normalized = normalizeWorkspaceIdentifier(identifier);
  if (!normalized) return null;
  return rows.find((row) => {
    const id = normalizeWorkspaceIdentifier(row.id || "");
    const slug = normalizeWorkspaceIdentifier(row.slug || "");
    const nombre = normalizeWorkspaceIdentifier(row.nombre || "");
    return normalized === id || normalized === slug || normalized === nombre;
  }) || null;
};

const renderWorkspaceTenantContext = () => {
  if (!workspaceTenantContext) return;
  const workspace = state.currentWorkspaceDetail?.workspace || null;
  if (!workspace) {
    workspaceTenantContext.innerHTML = "";
    workspaceTenantContext.classList.add("hidden");
    workspaceTenantContext.hidden = true;
    return;
  }

  workspaceTenantContext.classList.remove("hidden");
  workspaceTenantContext.hidden = false;

  const name = getWorkspaceDisplayName(workspace);
  const kind = String(workspace.kind || "").trim();
  const estado = String(workspace.estado || "").trim();
  const plan = String(workspace.plan || "").trim();
  const companiesTotal = Number(workspace.empresas_total || state.currentWorkspaceDetail?.companies?.length || 0);
  const modulesTotal = Number(workspace.modulos_activos || (state.currentWorkspaceEnabledModules || []).length || 0);
  const metaParts = [kind, plan, estado].filter(Boolean);
  const counts = [
    companiesTotal ? `${numberFormatter.format(companiesTotal)} empresas` : "",
    modulesTotal ? `${numberFormatter.format(modulesTotal)} módulos` : "",
  ].filter(Boolean);

  workspaceTenantContext.innerHTML = `
    <div>
      <strong>${escapeHtml(String(name || "Workspace"))}</strong>
      <div class="muted">${escapeHtml(metaParts.join(" · "))}${counts.length ? ` · ${escapeHtml(counts.join(" · "))}` : ""}</div>
    </div>
    <div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center">
      <button type="button" class="secondary ghost" data-workspace-tenant-jump="general">Datos</button>
      <button type="button" class="secondary ghost" data-workspace-tenant-jump="empresas">Empresas</button>
    </div>
  `;
  workspaceTenantContext.querySelectorAll("[data-workspace-tenant-jump]").forEach((button) => {
    button.addEventListener("click", () => {
      const section = button.dataset.workspaceTenantJump || "general";
      setWorkspaceTenantSection(section, { scroll: true });
    });
  });
};

const shouldShowWorkspaceCompanySwitcher = () => {
  const mode = state.currentWorkspaceEntryMode || "platform";
  if (mode === "tenant") return false;
  const companies = state.currentWorkspaceDetail?.companies || [];
  if (!Array.isArray(companies) || companies.length <= 1) return false;
  const view = String(state.currentWorkspaceView || "overview").trim().toLowerCase();
  // Solo cuando afecta al trabajo diario (evita confusión en Configuración/Clientes/Resumen).
  return ["operations", "fincas", "rrhh", "motores"].includes(view);
};

const updateWorkspaceEntryChrome = () => {
  const mode = state.currentWorkspaceEntryMode || "platform";
  const authUser = getAuthScopeUser();
  const canManageWorkspace = Boolean(authUser && canManageCurrentWorkspace());
  const workspaceSource =
    state.currentWorkspaceDetail?.workspace?.nombre
    || state.currentWorkspaceName
    || state.currentWorkspaceTarget
    || (mode === "tenant" ? DEFAULT_TENANT_WORKSPACE_SLUG : "");
  const workspaceName = getWorkspaceDisplayName(
    workspaceSource || "Workspace"
  );
  if (holdingTitle) {
    holdingTitle.textContent = mode === "tenant" ? `Workspace ${workspaceName}` : "Gestión de workspaces";
  }
  if (holdingSubtitle) {
    holdingSubtitle.textContent =
      mode === "tenant"
        ? `Todo lo operativo de ${workspaceName} se organiza desde este workspace por contenedores de servicio.`
        : "Administra workspaces, módulos activos, branding y estructura de clientes.";
  }
  if (holdingBackBtn) {
    holdingBackBtn.textContent = mode === "tenant" ? "Volver al panel" : "Volver al panel";
  }
  const tenantOperationalMode = mode === "tenant";
  // En tenant queremos separar claramente:
  // - Operativa: "Áreas del grupo" (launcher)
  // - Configuración: KPIs/Salud/Comercial + setup del workspace
  const overviewTargetView = tenantOperationalMode ? "tenant" : "overview";
  if (workspaceKpis) workspaceKpis.dataset.workspaceView = overviewTargetView;
  if (workspaceOverviewHealth) workspaceOverviewHealth.dataset.workspaceView = overviewTargetView;
  if (workspaceOverviewCommercial) workspaceOverviewCommercial.dataset.workspaceView = overviewTargetView;
  // En tenant, movemos el detalle operativo (presupuestos + paneles por servicio) a Configuración,
  // dejando Operativa como "home" de accesos.
  const operationsTargetView = tenantOperationalMode ? "tenant" : "operations";
  const operationsPanels = [
    workspaceBudgetForm?.closest('[data-workspace-view]'),
    workspaceGestoriaOverview?.closest('[data-workspace-view]'),
    workspaceSegurosOverview?.closest('[data-workspace-view]'),
    workspaceFinOverview?.closest('[data-workspace-view]'),
    workspaceInmoOverview?.closest('[data-workspace-view]'),
    workspaceServiceDesks?.closest('[data-workspace-view]'),
  ].filter(Boolean);
  operationsPanels.forEach((panel) => {
    panel.dataset.workspaceView = operationsTargetView;
  });
  if (workspaceViewTabs) workspaceViewTabs.classList.remove("hidden");
  if (workspaceCompanySwitcher) {
    workspaceCompanySwitcher.classList.toggle("hidden", tenantOperationalMode || !shouldShowWorkspaceCompanySwitcher());
  }
  if (workspaceOverviewLauncherCard) workspaceOverviewLauncherCard.classList.toggle("tenant-home-card", tenantOperationalMode);
  workspaceViewButtons.forEach((button) => {
    const viewKey = button.dataset.workspaceViewTab || "";
    if (tenantOperationalMode) {
      const shouldShow =
        viewKey === "operations"
        || viewKey === "fincas"
        || viewKey === "rrhh"
        || (viewKey === "motores" && canManageWorkspace)
        || (viewKey === "tenant" && canManageWorkspace);
      button.classList.toggle("hidden", !shouldShow);
      button.disabled = viewKey === "tenant" && !canManageWorkspace;
      return;
    }
    button.classList.remove("hidden");
    button.disabled = false;
  });
  renderWorkspaceTenantContext();
};

const setWorkspaceCompanyContext = (companyId = "", options = {}) => {
  const { rerenderForms = true, reloadScopedPanels = true } = options;
  const raw = state.currentWorkspaceDetail || {};
  const companiesV2 = Array.isArray(raw?.companies_v2) ? raw.companies_v2 : [];
  const legacy = Array.isArray(raw?.companies) ? raw.companies : [];
  const companies = companiesV2.length ? companiesV2 : legacy;
  if ((state.currentWorkspaceEntryMode || "platform") === "tenant") {
    const selected =
      companies.find((row) => String(row?.id || "").trim() === String(companyId || "").trim())
      || companies[0]
      || null;
    // En tenant, `workspace_company_id` SOLO es válido si tenemos `companies_v2`.
    // Si no existe (workspace en modo legacy), no enviamos un id legacy como `workspace_company_id`.
    const tenantHasV2 = companiesV2.length > 0;
    state.currentWorkspaceCompanyWsId = tenantHasV2 && selected ? String(selected?.id || "").trim() : "";
    state.currentWorkspaceCompanyId = selected
      ? String(selected?.legacy_empresa_id || selected?.id || "").trim()
      : "";
    state.currentWorkspaceCompanyName = selected ? String(selected?.nombre || "").trim() : "";
    renderWorkspaceCompanySwitcher([]); // en tenant no mostramos switcher global
    renderWorkspaceCompanies(companies);
    renderWorkspaceCompanyScopedData();
    if (rerenderForms) {
      fillWorkspaceBillingForm();
      fillWorkspaceBudgetForm();
      fillWorkspaceRemittancesForm();
      fillWorkspaceInboxForm();
      fillWorkspaceSeriesForm();
      fillWorkspaceTimeForm();
      fillWorkspaceFincasCommunityForm();
      fillWorkspaceFincasProviderForm();
    }
    if (reloadScopedPanels) {
      loadWorkspaceCompanyScopedPanels();
    }
    return;
  }
  const selected =
    companies.find((row) => String(row.id || "") === String(companyId || ""))
    || companies[0]
    || null;
  // En platform (admin), soporta tanto legacy (`companies`) como v2 (`companies_v2`).
  state.currentWorkspaceCompanyWsId = selected?.legacy_empresa_id ? String(selected?.id || "") : "";
  state.currentWorkspaceCompanyId = selected?.legacy_empresa_id ? String(selected?.legacy_empresa_id || "") : (selected?.id || "");
  state.currentWorkspaceCompanyName = selected?.nombre || "";
  renderWorkspaceCompanySwitcher(companies);
  renderWorkspaceCompanies(companies);
  renderWorkspaceCompanyScopedData();
  if (rerenderForms) {
    fillWorkspaceBillingForm();
    fillWorkspaceBudgetForm();
    fillWorkspaceRemittancesForm();
    fillWorkspaceInboxForm();
    fillWorkspaceSeriesForm();
    fillWorkspaceTimeForm();
    fillWorkspaceFincasCommunityForm();
    fillWorkspaceFincasProviderForm();
  }
  if (reloadScopedPanels) {
    loadWorkspaceCompanyScopedPanels();
  }
};

const getWorkspaceCompanyFilter = () =>
  (state.currentWorkspaceEntryMode || "platform") === "tenant"
    ? ""
    : String(state.currentWorkspaceCompanyId || "").trim();

const getWorkspaceCompanyQuery = () => {
  if ((state.currentWorkspaceEntryMode || "platform") === "tenant") return "";
  const wsCompanyId = String(state.currentWorkspaceCompanyWsId || "").trim();
  if (wsCompanyId) return `&workspace_company_id=${encodeURIComponent(wsCompanyId)}`;
  const legacy = String(state.currentWorkspaceCompanyId || "").trim();
  return legacy ? `&empresa_id=${encodeURIComponent(legacy)}` : "";
};
const getWorkspaceCompanyContextLabel = () =>
  (state.currentWorkspaceEntryMode || "platform") === "tenant"
    ? getWorkspaceDisplayName(state.currentWorkspaceName || state.currentWorkspaceTarget || DEFAULT_TENANT_WORKSPACE_SLUG)
    : (state.currentWorkspaceCompanyName || "Empresa activa");

const filterWorkspaceRowsByCompany = (rows = [], field = "empresa_id", serviceKey = "") => {
  const companyId = getWorkspaceCompanyFilter();
  const items = Array.isArray(rows) ? rows : [];
  if (serviceKey) {
    try {
      if (!shouldScopeByCompanyForService(serviceKey)) return items;
    } catch (e) {}
  }
  if (!companyId) return items;
  return items.filter((row) => String(row?.[field] || "").trim() === companyId);
};

const shouldScopeByCompanyForService = (serviceKey = "") => {
  const authUser = getAuthScopeUser();
  if (!authUser) return true;
  // Regla general Modernia: si el usuario tiene asignado un servicio,
  // ve TODO lo relacionado con ese servicio dentro del workspace.
  try {
    if (userCanAccessService(serviceKey)) return false;
  } catch (e) {}
  return true;
};

// Fincas: regla de producto Modernia → cualquier usuario con acceso al módulo debe ver
// todas las comunidades/incidencias del workspace. No aplicamos scope por empresa.
const shouldScopeFincasByCompany = () => false;

const filterWorkspaceFincasRowsByCompany = (rows = [], field = "empresa_id") => {
  const items = Array.isArray(rows) ? rows : [];
  if (!shouldScopeFincasByCompany()) return items;
  return filterWorkspaceRowsByCompany(items, field);
};

const filterWorkspaceDocumentHubData = (payload = {}) => {
  const rows = Array.isArray(payload.rows) ? payload.rows : [];
  const companyName = normalizeSimple(state.currentWorkspaceCompanyName || "");
  if (!companyName) return payload;
  const filteredRows = rows.filter((row) => normalizeSimple(row?.empresa || "") === companyName);
  return {
    ...payload,
    rows: filteredRows,
    summary: {
      ...(payload.summary || {}),
      documentos_total: filteredRows.length,
      pendientes_asignacion: filteredRows.filter((row) => Number(row?.assignable || 0) === 1 && row?.suggested_cliente_id).length,
    },
  };
};

const renderWorkspaceCompanyScopedData = () => {
  const raw = state.currentWorkspaceData || {};
  const billingRows = filterWorkspaceRowsByCompany(raw.billingRows || []);
  const budgetRows = filterWorkspaceRowsByCompany(raw.budgetRows || []);
  const collectionRows = filterWorkspaceRowsByCompany(raw.collectionRows || []);
  const remittanceRows = filterWorkspaceRowsByCompany(raw.remittanceRows || []);
  const seriesRows = filterWorkspaceRowsByCompany(raw.seriesRows || []);
  const inboxRows = filterWorkspaceRowsByCompany(raw.inboxRows || []);
  const timeRows = filterWorkspaceRowsByCompany(raw.timeRows || []);
  const timeEmployees = filterWorkspaceRowsByCompany(raw.timeEmployees || []);
  const timePeriods = filterWorkspaceRowsByCompany(raw.timePeriods || []);
  const communityRows = filterWorkspaceFincasRowsByCompany(raw.fincasCommunities || []);
  const communityIds = new Set(communityRows.map((row) => String(row.id || "")).filter(Boolean));
  const providerRows = (raw.fincasProviders || []).filter((row) => {
    const rowCompanyId = String(row?.empresa_id || "").trim();
    const rowCommunityId = String(row?.comunidad_id || "").trim();
    return (rowCompanyId && rowCompanyId === getWorkspaceCompanyFilter()) || (rowCommunityId && communityIds.has(rowCommunityId));
  });
  const incidentRows = (raw.fincasIncidents || []).filter((row) => communityIds.has(String(row?.comunidad_id || "").trim()));
  const meetingRows = (raw.fincasMeetings || []).filter((row) => communityIds.has(String(row?.comunidad_id || "").trim()));
  state.workspaceBillingRows = billingRows;
  renderWorkspaceBillingList(billingRows);
  renderWorkspaceBudgetList(budgetRows);
  renderWorkspaceCollectionsList(collectionRows);
  renderWorkspaceRemittancesList(remittanceRows);
  renderWorkspaceSeriesList(seriesRows);
  renderWorkspaceInboxList(inboxRows);
  state.workspaceTimeEmployees = timeEmployees;
  renderWorkspaceTimeEmployeeList(timeEmployees);
  applyWorkspaceTimeMode();
  renderWorkspaceTimeSystemUsers(state.workspaceTimeUsers || []);
  if (timeEmployees.length) {
    let selected = timeEmployees[0];
    if (!isWorkspaceTimeManager()) {
      const ownId = resolveWorkspaceTimePersonaForAuthUser(timeEmployees);
      if (ownId) {
        const mine = timeEmployees.find((row) => String(row?.id || "") === String(ownId));
        if (mine) selected = mine;
      } else {
        // No seleccionamos "otro" empleado por defecto si el usuario no está vinculado.
        selected = null;
      }
    }
    if (selected) {
      selectWorkspacePersona(selected);
    }
  } else {
    state.workspaceTimeSelectedPersonaId = "";
    state.workspaceTimeSelectedPersona = null;
    renderWorkspaceTimeEmployeePreview();
    renderWorkspaceTimeAudit([]);
  }
  hydrateWorkspaceTimeEmployeeSelect(timeEmployees);
  renderWorkspaceTimeSummary(raw.timeSummary || null);
  renderWorkspaceTimeList(timeRows);
  renderWorkspaceFincasCommunityList(communityRows);
  renderWorkspaceFincasProviderList(providerRows);
  renderWorkspaceFincasIncidentList(incidentRows);
  renderWorkspaceFincasMeetingList(meetingRows);
  hydrateWorkspaceCommunitySelect(communityRows);
  hydrateWorkspaceFincasBudgetQuickSelect({
    communities: communityRows,
    budgets: shouldScopeFincasByCompany() ? budgetRows : (Array.isArray(raw.budgetRows) ? raw.budgetRows : []),
  });
  hydrateWorkspaceProviderSelect(providerRows);
  try {
    const ledgerRows = Array.isArray(state.workspaceFincasLedgerRows) ? state.workspaceFincasLedgerRows : [];
    const communityIds = new Set(communityRows.map((row) => String(row.id || "")).filter(Boolean));
    const filteredLedger = ledgerRows.filter((row) => !row.comunidad_id || communityIds.has(String(row.comunidad_id || "")));
    renderWorkspaceFincasLedgerList(filteredLedger);
  } catch (e) {}
  renderWorkspaceFincasDashboard();
  renderWorkspacePortalList(raw.portalRows || []);
  hydrateWorkspacePortalRequestTargets(raw.portalRows || []);
  renderWorkspacePortalRequestList(raw.portalRequestRows || []);
  renderWorkspaceAutomationList(raw.automationRows || []);
  renderWorkspaceAutomationLogs(raw.automationLogRows || []);
  renderWorkspaceDocumentHub(filterWorkspaceDocumentHubData(raw.docs || {}));
  if (workspaceTimeMonth) {
    try {
      workspaceTimeMonth.value = normalizeMonthValue(state.workspaceTimeMonth || "");
    } catch {
      workspaceTimeMonth.value = "";
    }
  }
  state.workspaceTimePeriods = timePeriods;
  renderWorkspaceTimePeriodLock(timePeriods);
  if (workspaceTimeExportBtn) {
    const companyQuery = getWorkspaceCompanyQuery();
    workspaceTimeExportBtn.href = `/api/workspace_registro_horario_export?workspace_id=${encodeURIComponent(state.currentWorkspaceId || "")}&month=${encodeURIComponent(state.workspaceTimeMonth || "")}${companyQuery}`;
  }
};

const loadWorkspaceCompanyScopedPanels = async () => {
  if (!state.currentWorkspaceId) return;
  const companyQuery = getWorkspaceCompanyQuery();
  const [gestoriaOverview, segurosOverview, finOverview, inmoOverview, serviceDesks] = await Promise.all([
    safeWorkspaceApi(`/api/workspace_gestoria_overview?workspace_id=${encodeURIComponent(state.currentWorkspaceId)}${companyQuery}`, {}),
    safeWorkspaceApi(`/api/workspace_seguros_overview?workspace_id=${encodeURIComponent(state.currentWorkspaceId)}${companyQuery}`, {}),
    safeWorkspaceApi(`/api/workspace_fin_overview?workspace_id=${encodeURIComponent(state.currentWorkspaceId)}${companyQuery}`, {}),
    safeWorkspaceApi(`/api/workspace_inmo_overview?workspace_id=${encodeURIComponent(state.currentWorkspaceId)}${companyQuery}`, {}),
    safeWorkspaceApi(`/api/workspace_service_desks?workspace_id=${encodeURIComponent(state.currentWorkspaceId)}${companyQuery}`, {}),
  ]);
  renderWorkspaceGestoriaOverview(gestoriaOverview || {});
  renderWorkspaceSegurosOverview(segurosOverview || {});
  renderWorkspaceFinOverview(finOverview || {});
  renderWorkspaceInmoOverview(inmoOverview || {});
  renderWorkspaceServiceDesks(serviceDesks || {});
};

const renderWorkspaceCompanySwitcher = (rows = []) => {
  if (!workspaceCompanySwitcher) return;
  if ((state.currentWorkspaceEntryMode || "platform") === "tenant") {
    workspaceCompanySwitcher.innerHTML = "";
    workspaceCompanySwitcher.classList.add("hidden");
    return;
  }
  const companies = Array.isArray(rows) ? rows : [];
  if (!companies.length) {
    workspaceCompanySwitcher.innerHTML = "";
    workspaceCompanySwitcher.classList.add("hidden");
    return;
  }
  workspaceCompanySwitcher.classList.toggle("hidden", !shouldShowWorkspaceCompanySwitcher());
  const activeId = String(state.currentWorkspaceCompanyId || companies[0]?.id || "");
  workspaceCompanySwitcher.innerHTML = `
    <div class="workspace-company-switcher-card">
      <div>
        <strong>Empresa activa</strong>
        <div class="muted">El trabajo diario del workspace se aterriza sobre una empresa operativa del grupo.</div>
      </div>
      <div class="workspace-company-switcher-actions">
        ${companies.map((row) => `
          <button
            type="button"
            class="workspace-company-pill${String(row.id || "") === activeId ? " is-active" : ""}"
            data-workspace-company-pill="${row.id || ""}"
          >${row.nombre || "-"}</button>
        `).join("")}
      </div>
    </div>
  `;
  workspaceCompanySwitcher.querySelectorAll("[data-workspace-company-pill]").forEach((button) => {
    button.addEventListener("click", () => {
      setWorkspaceCompanyContext(button.dataset.workspaceCompanyPill || "");
    });
  });
};

const normalizeWorkspaceViewKey = (value = "") => {
  const key = String(value || "").trim().toLowerCase();
  if (["overview", "tenant", "clients", "operations", "rrhh", "motores", "fincas"].includes(key)) {
    return key;
  }
  return "overview";
};

const normalizeWorkspaceEngineKey = (value = "") => {
  const key = String(value || "").trim().toLowerCase();
  // "rrhh" vive como vista propia del workspace (no como motor de configuración).
  if (
    [
      "documental",
      "facturacion",
      "contabilidad",
      "facturas_recibidas",
      "portal_cliente",
      "registro_horario",
      "automatizaciones",
      "simuladores",
      "copilot",
    ].includes(key)
  ) {
    return key;
  }
  return "documental";
};

const normalizeWorkspaceEngineGroupKey = (value = "") => {
  const key = String(value || "").trim().toLowerCase();
  if (["operativa", "admin", "avanzado"].includes(key)) return key;
  return "operativa";
};

const inferWorkspaceEngineGroupForEngine = (engineKey = "") => {
  const key = normalizeSimple(engineKey || "");
  if (["documental", "facturas_recibidas", "portal_cliente"].includes(key)) return "operativa";
  if (["contabilidad", "facturacion", "registro_horario"].includes(key)) return "admin";
  return "avanzado";
};

const normalizeWorkspaceModuleKey = (value = "") => {
  const key = normalizeSimple(value || "");
  if (!key) return "";
  if (key === "portal" || key === "portalcliente" || key === "portal_cliente") return "portal_cliente";
  if (key === "facturas" || key === "facturasocr" || key === "facturas_recibidas") return "facturas_recibidas";
  if (key === "presupuestos") return "facturacion";
  if (key === "conta") return "contabilidad";
  if (key === "horario" || key === "registro" || key === "registrohorario") return "registro_horario";
  return key;
};

const setWorkspaceEngineGroup = (group = "operativa", { persist = true } = {}) => {
  const normalized = normalizeWorkspaceEngineGroupKey(group);
  state.currentWorkspaceEngineGroup = normalized;
  if (persist) {
    try {
      localStorage.setItem("crm.workspaceEngineGroup", normalized);
    } catch (e) {}
  }
  if (workspaceEngineGroupButtons?.length) {
    workspaceEngineGroupButtons.forEach((btn) => {
      btn.classList.toggle(
        "active",
        normalizeWorkspaceEngineGroupKey(btn.dataset.workspaceEngineGroup || "") === normalized
      );
    });
  }
  if (workspaceEngineGroupItems?.length) {
    workspaceEngineGroupItems.forEach((btn) => {
      const itemGroup = normalizeWorkspaceEngineGroupKey(btn.dataset.workspaceEngineGroupItem || "");
      const hidden = itemGroup !== normalized;
      btn.classList.toggle("hidden", hidden);
      btn.hidden = hidden;
    });
  }
};

const syncWorkspaceEngineTabsVisibility = () => {
  if (!isTenantWorkspaceMode()) return;
  if (!Array.isArray(workspaceEngineButtons) || !workspaceEngineButtons.length) return;
  const enabledSet = new Set((state.currentWorkspaceEnabledModules || []).map((key) => normalizeWorkspaceModuleKey(key)));
  // Si no hay lista, no filtramos (modo compatible).
  if (!enabledSet.size) return;

  let firstVisible = "";
  workspaceEngineButtons.forEach((button) => {
    const engineKey = normalizeSimple(button?.dataset?.workspaceEngineTab || "");
    if (!engineKey) return;
    const isVisible = enabledSet.has(engineKey) || enabledSet.has(normalizeWorkspaceModuleKey(engineKey));
    button.classList.toggle("hidden", !isVisible);
    button.hidden = !isVisible;
    if (!firstVisible && isVisible) firstVisible = engineKey;
  });

  const desired = normalizeSimple(state.currentWorkspaceEngineView || "");
  if (desired && enabledSet.has(desired)) return;
  if (firstVisible) {
    setWorkspaceEngineView(firstVisible);
  }
};

const ensureWorkspaceEngineGroupBoot = () => {
  if (!workspaceEngineGroupTabs) return;
  try {
    const desired = normalizeWorkspaceEngineGroupKey(
      state.currentWorkspaceEngineGroup
        || localStorage.getItem("crm.workspaceEngineGroup")
        || inferWorkspaceEngineGroupForEngine(state.currentWorkspaceEngineView || "documental")
    );
    setWorkspaceEngineGroup(desired, { persist: false });
  } catch (e) {}
  if (workspaceEngineGroupButtons?.length) {
    workspaceEngineGroupButtons.forEach((btn) => {
      btn.addEventListener("click", () => {
        setWorkspaceEngineGroup(btn.dataset.workspaceEngineGroup || "operativa", { persist: true });
      });
    });
  }
};

const normalizeTenantSectionKey = (value = "") => {
  const key = String(value || "").trim().toLowerCase();
  if (["general", "empresas", "usuarios", "modulos", "módulos", "permisos"].includes(key)) {
    if (key === "módulos") return "modulos";
    return key;
  }
  return "general";
};

const setWorkspaceTenantSection = (section = "general", options = {}) => {
  const { persist = true, scroll = false } = options;
  const normalized = normalizeTenantSectionKey(section);
  state.currentWorkspaceTenantSection = normalized;
  if (persist) {
    try {
      localStorage.setItem("crm.workspaceTenantSection", normalized);
    } catch (e) {}
  }
  if (workspaceTenantTabs) {
    workspaceTenantTabs.querySelectorAll("[data-workspace-tenant-tab]").forEach((button) => {
      button.classList.toggle("active", normalizeTenantSectionKey(button.dataset.workspaceTenantTab || "") === normalized);
    });
  }
  const panels = Array.from(document.querySelectorAll("[data-tenant-section]")).filter((panel) =>
    Boolean(panel.closest('[data-workspace-view="tenant"]'))
  );
  panels.forEach((panel) => {
    const panelKey = normalizeTenantSectionKey(panel.dataset.tenantSection || "");
    const isHidden = panelKey !== normalized;
    panel.classList.toggle("hidden", isHidden);
    panel.hidden = isHidden;
  });
  if (scroll && workspaceTenantTabs && typeof workspaceTenantTabs.scrollIntoView === "function") {
    workspaceTenantTabs.scrollIntoView({ behavior: "smooth", block: "start" });
  }
};

let iivtnuMunicipiosCache = null;
let iivtnuLastParsed = null;

