const buildIrpfPayloadFromForm = () => {
  if (!irpfGainForm) return {};
  const formData = new FormData(irpfGainForm);
  const payload = Object.fromEntries(formData.entries());
  payload.brand_logo_url = payload.brand_logo_url || "/assets/grupo_modernia_logo.png";
  if (!payload.empresa_nombre) {
    payload.empresa_nombre =
      resolveCrmInmoEmpresaNombre() || resolveCrmGestoriaEmpresaNombre() || state.currentWorkspaceCompanyName || "";
  }
  return payload;
};

const syncFiscalWizardPvVisibility = () => {
  if (!fiscalWizardForm) return;
  const ccaa = String(new FormData(fiscalWizardForm).get("ccaa") || "AN").toUpperCase();
  fiscalWizardForm.querySelectorAll(".fiscal-pv-territorio").forEach((el) => {
    el.classList.toggle("hidden", ccaa !== "PV");
  });
};

const normalizeDgtReference = (value = "") => {
  const raw = String(value || "").trim().toUpperCase();
  if (!raw) return "";
  const cleaned = raw.replace(/\s+/g, "").replace(/[._]/g, "");
  const match = cleaned.match(/^V(\d{4})[-/](\d{2,4})$/);
  if (!match) return "";
  const num = match[1];
  const year = match[2].slice(-2);
  return `V${num}-${year}`;
};

const setFiscalWizardDgtRefs = (refs = [], options = {}) => {
  const { replace = false } = options || {};
  const incoming = Array.isArray(refs) ? refs : [refs];
  const current = replace ? [] : Array.isArray(fiscalWizardDgtRefs) ? [...fiscalWizardDgtRefs] : [];
  const seen = new Set(current);
  incoming.forEach((item) => {
    const normalized = normalizeDgtReference(item);
    if (!normalized) return;
    if (seen.has(normalized)) return;
    seen.add(normalized);
    current.push(normalized);
  });
  fiscalWizardDgtRefs = current;
  renderFiscalWizardDgtRefs();
};

// Backward-compat: algunos despliegues usaron el nombre "Dat" por error (setFiscalWizardDatRefs).
const setFiscalWizardDatRefs = (refs = [], options = {}) => setFiscalWizardDgtRefs(refs, options);

const renderFiscalWizardDgtRefs = () => {
  if (!fiscalWizardDgtList) return;
  const refs = Array.isArray(fiscalWizardDgtRefs) ? fiscalWizardDgtRefs : [];
  if (!refs.length) {
    fiscalWizardDgtList.innerHTML = "<div class='muted'>Sin referencias.</div>";
    return;
  }
  fiscalWizardDgtList.innerHTML = refs
    .map((ref) => {
      const lookup = fiscalWizardDgtLookupCache.get(ref) || null;
      const title = lookup?.title ? String(lookup.title) : "";
      const summary = lookup?.page_title ? String(lookup.page_title) : lookup?.summary ? String(lookup.summary) : "";
      const url = lookup?.url ? String(lookup.url) : "";
      const subtitle = title || summary ? [title, summary].filter(Boolean).join(" · ") : lookup ? "Consulta preparada." : "Sin consultar.";
      const urlHtml = url
        ? ` · <a href="${escapeHtml(url)}" target="_blank" rel="noreferrer">Abrir</a>`
        : "";
      return `
        <div class="crm-focus-link" style="display:flex; align-items:flex-start; justify-content:space-between; gap:12px;">
          <div style="min-width:0;">
            <strong>${escapeHtml(ref)}</strong>
            <span>${escapeHtml(subtitle)}${urlHtml}</span>
          </div>
          <div style="flex:0 0 auto; display:flex; gap:8px; align-items:center;">
            <button type="button" class="secondary ghost button-inline" data-dgt-lookup="${escapeHtml(ref)}">Consultar</button>
            <button type="button" class="danger ghost button-inline" data-dgt-remove="${escapeHtml(ref)}">Quitar</button>
          </div>
        </div>
      `;
    })
    .join("");
};

const renderFiscalWizardResult = (data = null) => {
  if (!fiscalWizardResult) return;
  if (!data) {
    fiscalWizardResult.innerHTML = "";
    return;
  }
  const irpf = data?.irpf?.result || {};
  const iiv = data?.iivtnu?.result || {};
  const fields = [
    [
      "IRPF/IRNR · Importe a pagar (estimado)",
      (data?.irpf?.params?.regimen_fiscal || "").toString().toLowerCase() === "irnr" ? (irpf.cuota_neta ?? "") : (irpf.cuota_ahorro_estimada ?? ""),
    ],
    ["IIVTNU · Cuota recomendada", iiv.cuota_recomendada ?? ""],
    ["IIVTNU · Método", iiv.metodo_recomendado ?? ""],
  ];
  fiscalWizardResult.innerHTML = `
    <div class="ui-table">
      <table class="data-table">
        <tbody>
          ${fields
            .map(
              ([label, value]) => `
                <tr>
                  <th>${escapeHtml(label)}</th>
                  <td>${escapeHtml(value == null ? "" : String(value))}</td>
                </tr>
              `
            )
            .join("")}
        </tbody>
      </table>
    </div>
  `;
};

const ensureIivtnuMunicipios = async () => {
  if (!iivtnuMunicipioSelect) return [];
  if (Array.isArray(iivtnuMunicipiosCache) && iivtnuMunicipiosCache.length) return iivtnuMunicipiosCache;
  iivtnuMunicipioSelect.innerHTML = "<option value=\"\">Cargando...</option>";
  try {
    const data = await postJsonWithDbRetry("/api/iivtnu_municipios", { scope: "all" });
    const items = Array.isArray(data?.items) ? data.items : [];
    iivtnuMunicipiosCache = items;
  } catch (err) {
    iivtnuMunicipiosCache = [];
  }
  const options = Array.isArray(iivtnuMunicipiosCache) ? iivtnuMunicipiosCache : [];
  if (!options.length) {
    iivtnuMunicipiosCache = [{ ine: "29067", nombre: "Málaga", provincia: "Málaga" }];
  }
  iivtnuMunicipioSelect.innerHTML = (iivtnuMunicipiosCache || [])
    .map((row) => {
      const ine = String(row?.ine || "").trim();
      const label = `${row?.nombre || ine || "Municipio"}${row?.provincia ? ` (${row.provincia})` : ""}`;
      return `<option value="${escapeHtml(ine)}">${escapeHtml(label)}</option>`;
    })
    .join("");
  try {
    const prev = String(localStorage.getItem("crm.iivtnu.municipio_ine") || "").trim();
    if (prev && iivtnuMunicipioSelect.querySelector(`option[value="${CSS.escape(prev)}"]`)) {
      iivtnuMunicipioSelect.value = prev;
    }
  } catch (e) {}
  return iivtnuMunicipiosCache || [];
};

const inferIivtnuMunicipioByCp = (cp = "", municipios = []) => {
  const clean = normalizePostalCode(cp);
  if (!clean || clean.length < 2) return "";
  const province = clean.slice(0, 2);
  if (province === "29") {
    const candidates = municipios.filter((row) => String(row?.provincia || "").toLowerCase() === "málaga");
    if (candidates.length === 1) return String(candidates[0]?.ine || "");
    const malagaCapital = candidates.find((row) => String(row?.nombre || "").trim().toLowerCase() === "málaga");
    if (malagaCapital) return String(malagaCapital.ine || "");
  }
  return "";
};

const renderIivtnuParsed = (parsed = null) => {
  if (!iivtnuPdfParsed) return;
  if (!parsed) {
    iivtnuPdfParsed.innerHTML = "<p class='muted'>Sin datos extraídos todavía.</p>";
    return;
  }
  const docType = String(parsed.doc_type || "").trim().toLowerCase();
  let note = "";
  if (docType === "carta_pago") {
    note =
      "Carta de pago: normalmente no incluye los datos del inmueble/fechas necesarios para simular. Úsala para conciliar NRC/importe o validar.";
  } else if (docType === "guia_autoliquidacion") {
    note =
      "Guía/autoliquidación: puede traer parte de los campos (CP, ref. catastral, etc.). Si faltan fechas/valor suelo, tendrás que completarlos a mano.";
  } else if (docType === "autoliquidacion" || docType === "simulacion_ayuda") {
    note = "Este PDF suele incluir campos suficientes para autocompletar el simulador.";
  }
		  const fields = [
		    ["Tipo documento", parsed.doc_type || "-"],
		    ["Municipio", parsed.municipio || "-"],
		    ["CP", parsed.codigo_postal || "-"],
		    ["Ref. catastral", parsed.referencia_catastral || "-"],
		    ["Nº liquidación", parsed.numero_liquidacion || "-"],
		    ["UTM", parsed.utm || "-"],
		    ["Adquisición", parsed.fecha_adquisicion || "-"],
		    ["Transmisión", parsed.fecha_transmision || "-"],
		    ["Valor suelo", parsed.valor_suelo],
		    ["Valor suelo reducido", parsed.valor_suelo_reducido],
		    ["Coef. reducción", parsed.coef_reduccion],
		    ["Valor catastral total", parsed.valor_catastral_total],
		    ["Valor transmisión", parsed.valor_transmision],
		    ["Valor adquisición", parsed.valor_adquisicion],
		    ["% participación", parsed.participacion_pct],
		    ["% suelo (B/A)", parsed.porcentaje_suelo],
		    ["Base imponible", parsed.base_imponible],
		    ["Tipo gravamen (%)", parsed.tipo_gravamen_pct],
		    ["Cuota", parsed.cuota_tributaria],
		    ["Clase transmisión", parsed.clase_transmision || "-"],
		    ["Derecho transmitido", parsed.derecho_transmitido || "-"],
		    ["Subdivisión (%)", parsed.subdivision_pct],
		    ["Bonificación (%)", parsed.bonificacion_pct],
		    ["Bonificación importe", parsed.bonificacion_importe],
		    ["Recargo", parsed.recargo_importe],
		    ["Intereses", parsed.intereses_importe],
		    ["Importe total", parsed.importe_total],
		    ["NRC", parsed.nrc || "-"],
		    ["Referencia A.E.B.", parsed.referencia_aeb || "-"],
		    ["Modelo", parsed.modelo || "-"],
		    ["Ejercicio", parsed.ejercicio || "-"],
		    ["Fecha pago", parsed.fecha_pago || "-"],
		  ];
  iivtnuPdfParsed.innerHTML = `
    ${note ? `<p class="muted" style="margin: 0 0 10px 0;">${escapeHtml(note)}</p>` : ""}
	    <div class="ui-table">
	      <table class="data-table">
	        <tbody>
	          ${fields
            .map(
              ([label, value]) => `
                <tr>
                  <th>${escapeHtml(label)}</th>
                  <td>${escapeHtml(value == null ? "" : String(value))}</td>
                </tr>
              `
            )
            .join("")}
        </tbody>
      </table>
	    </div>
	  `;
};

const renderIivtnuSimulatorResult = (resp = null) => {
  if (!iivtnuSimulatorResult) return;
  if (!resp) {
    iivtnuSimulatorResult.innerHTML = "";
    return;
  }
  const result = resp?.result || {};
  const params = resp?.params || {};
  const objetivo = result?.objetivo || {};
  const real = result?.real || null;
  const tipoInfo = params?.tipo_is_manual ? "Manual" : params?.tipo_is_estimated ? "Estimado" : "Ordenanza/tabla";
  const fields = [
    ["Situación especial", (result.situacion_especial || "").trim() || "—"],
    ["Motivo", (result.situacion_motivo || "").trim() || "—"],
    ["Método recomendado", result.metodo_recomendado || "objetivo"],
    ["Cuota recomendada", result.cuota_recomendada ?? result.cuota_tributaria],
    ["Años", result.years],
    ["Meses", result.months],
    ["Coeficiente objetivo", result.coef_objetivo],
    ["Valor suelo usado", result.valor_suelo_usado ?? ""],
    ["Factor derecho (%)", result.derecho_factor_pct ?? ""],
    ["Base (objetivo)", objetivo.base_imponible ?? result.base_imponible],
    ["Tipo gravamen (%)", result.tipo_gravamen_pct],
    ["Bonificación (%)", result.bonificacion_pct],
    ["Bonificación (modo)", result.bonificacion_modo || "—"],
    ["Bonificación (motivo)", result.bonificacion_motivo || "—"],
    ["Cuota bruta (objetivo)", objetivo.cuota_tributaria_bruta ?? result.cuota_tributaria_bruta],
    ["Bonificación importe (objetivo)", objetivo.bonificacion_importe ?? result.bonificacion_importe],
    ["Cuota neta (objetivo)", objetivo.cuota_tributaria ?? result.cuota_tributaria],
    ["Tipo (origen)", tipoInfo],
    ["Fuente tipo", params.source_label || params.source_url || "—"],
    ["Fuente coeficientes", params.coef_source_label || params.coef_source_url || "—"],
  ];
  if (real && typeof real === "object") {
    fields.push(["Ganancia total", real.ganancia_total]);
    fields.push(["Ratio suelo", real.ratio_suelo]);
    fields.push(["Ganancia suelo", real.ganancia_suelo]);
    fields.push(["Base (real)", real.base_imponible]);
    fields.push(["Cuota bruta (real)", real.cuota_tributaria_bruta]);
    fields.push(["Bonificación importe (real)", real.bonificacion_importe]);
    fields.push(["Cuota (real)", real.cuota_tributaria]);
    fields.push(["No incremento", real.no_incremento ? "Sí" : "No"]);
  }
  iivtnuSimulatorResult.innerHTML = `
    <div class="ui-table">
      <table class="data-table">
        <tbody>
          ${fields
            .map(
              ([label, value]) => `
                <tr>
                  <th>${escapeHtml(label)}</th>
                  <td>${escapeHtml(value == null ? "" : String(value))}</td>
                </tr>
              `
            )
            .join("")}
        </tbody>
      </table>
    </div>
  `;
};

const ensureIivtnuSimulator = async () => {
  if (!iivtnuSimulatorForm || !iivtnuMunicipioSelect) return;
  await ensureIivtnuMunicipios();
  if (iivtnuMunicipioCp) {
    iivtnuMunicipioCp.addEventListener("change", async () => {
      const cp = normalizePostalCode(iivtnuMunicipioCp.value);
      if (!cp || cp.length !== 5) return;
      try {
        const resp = await postJsonWithDbRetry("/api/iivtnu_cp_lookup", { codigo_postal: cp }, { timeoutMs: 20000 });
        const ine = String(resp?.ine || "").trim();
        if (ine && iivtnuMunicipioSelect.querySelector(`option[value="${CSS.escape(ine)}"]`)) {
          iivtnuMunicipioSelect.value = ine;
        }
      } catch (e) {}
    });
  }
  iivtnuMunicipioSelect.addEventListener("change", () => {
    try {
      localStorage.setItem("crm.iivtnu.municipio_ine", String(iivtnuMunicipioSelect.value || ""));
    } catch (e) {}
  });
  if (iivtnuPdfApplyBtn) {
    iivtnuPdfApplyBtn.addEventListener("click", () => {
      const parsed = iivtnuLastParsed;
      if (!parsed) return;
      if (iivtnuMunicipioSelect && parsed.municipio_ine && iivtnuMunicipioSelect.querySelector(`option[value="${CSS.escape(parsed.municipio_ine)}"]`)) {
        iivtnuMunicipioSelect.value = parsed.municipio_ine;
      }
      const acq = iivtnuSimulatorForm.querySelector('[name="fecha_adquisicion"]');
      const tx = iivtnuSimulatorForm.querySelector('[name="fecha_transmision"]');
      const vs = iivtnuSimulatorForm.querySelector('[name="valor_suelo"]');
      const pct = iivtnuSimulatorForm.querySelector('[name="participacion_pct"]');
      const bonif = iivtnuSimulatorForm.querySelector('[name="bonificacion_pct"]');
      const tipo = iivtnuSimulatorForm.querySelector('[name="tipo_gravamen_pct_manual"]');
      const vcTotal = iivtnuSimulatorForm.querySelector('[name="valor_catastral_total"]');
      const vsReducido = iivtnuSimulatorForm.querySelector('[name="valor_suelo_reducido"]');
      const coefRed = iivtnuSimulatorForm.querySelector('[name="coef_reduccion"]');
      const vAdq = iivtnuSimulatorForm.querySelector('[name="valor_adquisicion"]');
      const vTx = iivtnuSimulatorForm.querySelector('[name="valor_transmision"]');
      const tipoTrans = iivtnuSimulatorForm.querySelector('[name="tipo_transmision"]');
      const derecho = iivtnuSimulatorForm.querySelector('[name="derecho_tipo"]');
      const pctSuelo = iivtnuSimulatorForm.querySelector('[name="porcentaje_suelo"]');
      if (acq && parsed.fecha_adquisicion) acq.value = parsed.fecha_adquisicion;
      if (tx && parsed.fecha_transmision) tx.value = parsed.fecha_transmision;
      if (vs && parsed.valor_suelo != null) vs.value = String(parsed.valor_suelo);
      if (vsReducido && parsed.valor_suelo_reducido != null) vsReducido.value = String(parsed.valor_suelo_reducido);
      if (coefRed && parsed.coef_reduccion != null) coefRed.value = String(parsed.coef_reduccion);
      if (vcTotal && parsed.valor_catastral_total != null) vcTotal.value = String(parsed.valor_catastral_total);
      if (vAdq && parsed.valor_adquisicion != null) vAdq.value = String(parsed.valor_adquisicion);
      if (vTx && parsed.valor_transmision != null) vTx.value = String(parsed.valor_transmision);
      if (pct && parsed.participacion_pct != null) pct.value = String(parsed.participacion_pct);
      if (pct && parsed.subdivision_pct != null && (!pct.value || pct.value === "100")) pct.value = String(parsed.subdivision_pct);
      if (pctSuelo && parsed.porcentaje_suelo != null && (!pctSuelo.value || pctSuelo.value === "0")) pctSuelo.value = String(parsed.porcentaje_suelo);
      if (bonif && parsed.bonificacion_pct != null) bonif.value = String(parsed.bonificacion_pct);
      if (tipo && parsed.tipo_gravamen_pct != null) tipo.value = String(parsed.tipo_gravamen_pct);
      if (tipoTrans && parsed.clase_transmision) {
        const raw = String(parsed.clase_transmision || "").trim().toLowerCase();
        if (raw.includes("compra") || raw.includes("venta")) tipoTrans.value = "onerosa";
        if (raw.includes("don")) tipoTrans.value = "donacion";
        if (raw.includes("heren")) tipoTrans.value = "mortis_causa";
      }
      if (derecho && parsed.derecho_transmitido) {
        const raw = String(parsed.derecho_transmitido || "").trim().toLowerCase();
        if (raw.includes("pleno")) derecho.value = "pleno_dominio";
        if (raw.includes("nuda")) derecho.value = "nuda_propiedad";
        if (raw.includes("usuf")) derecho.value = "usufructo_vitalicio";
        if (raw.includes("uso") || raw.includes("habit")) derecho.value = "uso_habitacion";
      }
      if (iivtnuSimulatorStatus) iivtnuSimulatorStatus.textContent = "Datos aplicados desde PDF.";
    });
  }
  if (iivtnuPdfSaveTipoBtn) {
    iivtnuPdfSaveTipoBtn.addEventListener("click", async () => {
      const parsed = iivtnuLastParsed;
      if (!parsed) return;
      if (!parsed.municipio_ine || !parsed.fecha_transmision || parsed.tipo_gravamen_pct == null) return;
      if (iivtnuPdfSaveTipoStatus) iivtnuPdfSaveTipoStatus.textContent = "Guardando tipo...";
      try {
        const payload = {
          municipio_ine: String(parsed.municipio_ine || "").trim(),
          devengo: String(parsed.fecha_transmision || "").trim(),
          tipo_gravamen_pct: parsed.tipo_gravamen_pct,
          bonificacion_pct: parsed.bonificacion_pct,
          source_label: `PDF ${parsed.filename || ""}`.trim(),
          source_url: "",
        };
        await postJsonWithDbRetry("/api/iivtnu_param_upsert", payload, { timeoutMs: 30000 });
        if (iivtnuPdfSaveTipoStatus) iivtnuPdfSaveTipoStatus.textContent = "Tipo guardado.";
      } catch (err) {
        if (iivtnuPdfSaveTipoStatus) iivtnuPdfSaveTipoStatus.textContent = err.message || "No se pudo guardar.";
      }
    });
  }
  renderIivtnuParsed(null);
};

