const syncIrpfRentalMode = () => {
  if (!irpfRentalForm) return;
  const mode = String(new FormData(irpfRentalForm).get("modo") || "arrendado").toLowerCase();
  const arrFields = irpfRentalForm.querySelectorAll(".irpf-rental-arrendado");
  const impFields = irpfRentalForm.querySelectorAll(".irpf-rental-imputacion");
  const showArr = mode !== "imputacion";
  arrFields.forEach((el) => {
    el.classList.toggle("hidden", !showArr);
    el.hidden = !showArr;
  });
  impFields.forEach((el) => {
    el.classList.toggle("hidden", showArr);
    el.hidden = showArr;
  });
};

const ensureIrpfSimulators = () => {
  if (irpfGainStatus) irpfGainStatus.textContent = "";
  if (irpfRentalStatus) irpfRentalStatus.textContent = "";
  renderIrpfGainResult(null);
  renderIrpfRentalResult(null);
  if (irpfRentalForm) {
    const modeSel = irpfRentalForm.querySelector('select[name="modo"]');
    if (modeSel) modeSel.addEventListener("change", syncIrpfRentalMode);
    syncIrpfRentalMode();
  }
};

const setWorkspaceEngineView = (engine = "documental") => {
  const normalized = normalizeWorkspaceEngineKey(engine);
  state.currentWorkspaceEngineView = normalized;
  // Al entrar por deep-link, selecciona automáticamente el grupo adecuado.
  try {
    setWorkspaceEngineGroup(inferWorkspaceEngineGroupForEngine(normalized), { persist: true });
  } catch (e) {}
  // Asegura que "Motores" sea la vista activa cuando se selecciona un engine
  // (evita mezclas visuales si el estado estaba en otra vista).
  if (normalizeSimple(state.currentWorkspaceView || "") !== "motores") {
    try {
      setWorkspaceView("motores", { forceTenantView: true });
    } catch (e) {}
  }
  workspaceEngineButtons.forEach((button) => {
    button.classList.toggle("active", (button.dataset.workspaceEngineTab || "") === normalized);
  });
  workspaceEnginePanels.forEach((panel) => {
    const panelEngine = panel.dataset.workspaceEngine || "";
    const isHidden = panelEngine !== normalized;
    panel.classList.toggle("hidden", isHidden);
    panel.hidden = isHidden;
  });
  // Facturas (OCR) es un flujo específico: ocultamos el formulario genérico de Inbox
  // para evitar confusión (queda disponible en Documentos).
  try {
    const inboxForm = document.getElementById("workspaceInboxForm");
    if (inboxForm) {
      const hideGeneric = normalized === "facturas_recibidas";
      inboxForm.classList.toggle("hidden", hideGeneric);
      inboxForm.hidden = hideGeneric;
    }
  } catch (e) {}
  if (normalized === "simuladores") {
    void ensureIivtnuSimulator();
    ensureIrpfSimulators();
  }
  if (normalized === "contabilidad") {
    void refreshWorkspaceContabilidad({ force: false }).catch(() => {});
  }
  syncHoldingUrlParams();
};

const setWorkspaceView = (view = "overview", options = {}) => {
  const { scroll = false, forceTenantView = false } = options;
  let normalized = normalizeWorkspaceViewKey(view);
  const tenantMode = (state.currentWorkspaceEntryMode || "platform") === "tenant";
  const platformMode = !tenantMode;
  // Modo plataforma (admin): el workspace es una pantalla de configuración.
  // La operativa vive en el panel principal, no como pestañas dentro de Workspaces.
  if (platformMode && !["overview", "tenant"].includes(normalized)) {
    normalized = "overview";
  }
  if (tenantMode && normalized === "overview") {
    normalized = "operations";
  }
  const tenantAllowed = new Set(["operations", "fincas", "rrhh", "motores"]);
  if (tenantMode && !forceTenantView && normalized !== "tenant" && !tenantAllowed.has(normalized)) {
    normalized = "operations";
  }
  if (tenantMode && normalized === "tenant") {
    const user = getAuthScopeUser();
    if (!isPrivilegedUser(user)) {
      normalized = "operations";
    }
  }
  if (normalized !== "rrhh") {
    state.workspaceRrhhEntry = "";
  }
  state.currentWorkspaceView = normalized;

  const enabledModules = tenantMode
    ? new Set((state.currentWorkspaceEnabledModules || []).map((key) => normalizeSimple(key)))
    : null;
  const moduleEnabled = (key = "") => {
    const normalizedKey = normalizeSimple(key);
    if (!normalizedKey || !enabledModules || !enabledModules.size) return true;
    if (enabledModules.has(normalizedKey)) return true;
    // Aliases comunes (keys heredadas vs labels UI)
    if (normalizedKey === "financiacion" && enabledModules.has("financiaciones")) return true;
    if (normalizedKey === "financiaciones" && enabledModules.has("financiacion")) return true;
    return false;
  };
  const panelModuleAllowed = (panel) => {
    if (!tenantMode) return true;
    if (!enabledModules || !enabledModules.size) return true;
    const only = String(panel?.dataset?.workspaceModule || "").trim();
    if (only) return moduleEnabled(only);
    const any = String(panel?.dataset?.workspaceModuleAny || "").trim();
    if (!any) return true;
    return any
      .split(",")
      .map((item) => item.trim())
      .filter(Boolean)
      .some((key) => moduleEnabled(key));
  };

  workspaceViewButtons.forEach((button) => {
    button.classList.toggle("active", (button.dataset.workspaceViewTab || "") === normalized);
  });
  workspaceViewPanels.forEach((panel) => {
    const isHidden = (panel.dataset.workspaceView || "") !== normalized || !panelModuleAllowed(panel);
    panel.classList.toggle("hidden", isHidden);
    panel.hidden = isHidden;
  });

  // En vista distinta de "Motores", forzamos a ocultar todos los paneles de engine.
  // Esto evita que queden "pegados" (por re-tags temporales, errores de estado o restores)
  // y aparezcan debajo de Operativa/Configuración, como en la captura del usuario.
  if (normalized !== "motores") {
    workspaceEnginePanels.forEach((panel) => {
      panel.classList.add("hidden");
      panel.hidden = true;
    });
  }

  if (normalized === "tenant") {
    let desired = "general";
    try {
      desired = normalizeTenantSectionKey(localStorage.getItem("crm.workspaceTenantSection") || "");
    } catch {
      desired = "general";
    }
    setWorkspaceTenantSection(state.currentWorkspaceTenantSection || desired, { persist: false });
  }
  if (normalized === "motores") {
    ensureWorkspaceEngineGroupBoot();
    setWorkspaceEngineView(state.currentWorkspaceEngineView || "documental");
  }
  if (normalized === "rrhh") {
    // RRHH es un espacio propio, no un "motor" de configuración.
    void refreshWorkspaceRrhh();
  }
  if (normalized === "fincas") {
    setWorkspaceFincasTab(state.workspaceFincasTab || "dashboard");
  }
  syncHoldingUrlParams();
  if (workspaceCompanySwitcher) {
    workspaceCompanySwitcher.classList.toggle("hidden", !shouldShowWorkspaceCompanySwitcher());
  }
  if (scroll && workspaceViewTabs) {
    workspaceViewTabs.scrollIntoView({ behavior: "smooth", block: "start" });
  }
};

const focusWorkspaceView = (view, element = null, options = {}) => {
  setWorkspaceView(view, options);
  if (element && typeof element.scrollIntoView === "function") {
    element.scrollIntoView({ behavior: "smooth", block: "start" });
  }
};

const focusWorkspaceEngine = async (engine, element = null, options = {}) => {
  setWorkspaceView("motores", options);
  setWorkspaceEngineView(engine);
  if (engine === "registro_horario") {
    if (isWorkspaceTimeManager()) {
      await refreshWorkspaceTimeSetup();
      await refreshWorkspaceTimeSweepStatus();
      await runWorkspaceTimeAlertSweep();
    } else {
      applyWorkspaceTimeMode();
    }
  }
  if (engine === "rrhh") {
    await refreshWorkspaceRrhh();
  }
  if (element && typeof element.scrollIntoView === "function") {
    element.scrollIntoView({ behavior: "smooth", block: "start" });
  }
};

workspaceEngineButtons.forEach((button) => {
  button.addEventListener("click", async () => {
    const engine = button.dataset.workspaceEngineTab || "documental";
    setWorkspaceEngineView(engine);
    if (engine === "registro_horario") {
      if (isWorkspaceTimeManager()) {
        await refreshWorkspaceTimeSetup();
        await refreshWorkspaceTimeSweepStatus();
        await runWorkspaceTimeAlertSweep();
      } else {
        applyWorkspaceTimeMode();
      }
    }
    if (engine === "rrhh") {
      await refreshWorkspaceRrhh();
    }
  });
});

// Delegación defensiva: si por cualquier motivo los listeners anteriores no se montaron
// (caché, cambios DOM, reinicios parciales), este handler asegura que los tabs de Motores funcionan.
try {
  if (!window.__workspaceEngineTabsDelegationBound) {
    window.__workspaceEngineTabsDelegationBound = true;
    document.addEventListener("click", async (ev) => {
      const target = ev?.target;
      const btn = target?.closest?.("[data-workspace-engine-tab]");
      if (!btn) return;
      const engine = btn.dataset.workspaceEngineTab || "documental";
      // Evita interferir fuera de la vista de Motores.
      if (normalizeSimple(state.currentWorkspaceView || "") !== "motores") return;
      setWorkspaceEngineView(engine);
      try {
        if (engine === "registro_horario") {
          if (isWorkspaceTimeManager()) {
            await refreshWorkspaceTimeSetup();
            await refreshWorkspaceTimeSweepStatus();
            await runWorkspaceTimeAlertSweep();
          } else {
            applyWorkspaceTimeMode();
          }
        }
        if (engine === "rrhh") {
          await refreshWorkspaceRrhh();
        }
      } catch (e) {}
    });
  }
} catch (e) {}

