const inferFiscalTerritoryFromProvincia = (provinciaRaw = "") => {
  const provincia = normalizeLookupText(provinciaRaw);
  if (!provincia) return { ccaa: "", pv_territorio: "" };
  const map = new Map([
    // Andalucía
    ["almeria", { ccaa: "AN" }],
    ["cadiz", { ccaa: "AN" }],
    ["cordoba", { ccaa: "AN" }],
    ["granada", { ccaa: "AN" }],
    ["huelva", { ccaa: "AN" }],
    ["jaen", { ccaa: "AN" }],
    ["malaga", { ccaa: "AN" }],
    ["sevilla", { ccaa: "AN" }],
    // Aragón
    ["huesca", { ccaa: "AR" }],
    ["teruel", { ccaa: "AR" }],
    ["zaragoza", { ccaa: "AR" }],
    // Asturias
    ["asturias", { ccaa: "AS" }],
    // Illes Balears
    ["illes balears", { ccaa: "IB" }],
    ["islas baleares", { ccaa: "IB" }],
    // Canarias
    ["las palmas", { ccaa: "CN" }],
    ["santa cruz de tenerife", { ccaa: "CN" }],
    // Cantabria
    ["cantabria", { ccaa: "CB" }],
    // Castilla-La Mancha
    ["albacete", { ccaa: "CM" }],
    ["ciudad real", { ccaa: "CM" }],
    ["cuenca", { ccaa: "CM" }],
    ["guadalajara", { ccaa: "CM" }],
    ["toledo", { ccaa: "CM" }],
    // Castilla y León
    ["avila", { ccaa: "CL" }],
    ["burgos", { ccaa: "CL" }],
    ["leon", { ccaa: "CL" }],
    ["palencia", { ccaa: "CL" }],
    ["salamanca", { ccaa: "CL" }],
    ["segovia", { ccaa: "CL" }],
    ["soria", { ccaa: "CL" }],
    ["valladolid", { ccaa: "CL" }],
    ["zamora", { ccaa: "CL" }],
    // Cataluña
    ["barcelona", { ccaa: "CT" }],
    ["girona", { ccaa: "CT" }],
    ["lleida", { ccaa: "CT" }],
    ["tarragona", { ccaa: "CT" }],
    // Comunitat Valenciana
    ["alicante", { ccaa: "VC" }],
    ["castellon", { ccaa: "VC" }],
    ["valencia", { ccaa: "VC" }],
    // Extremadura
    ["badajoz", { ccaa: "EX" }],
    ["caceres", { ccaa: "EX" }],
    // Galicia
    ["a coruna", { ccaa: "GA" }],
    ["coruna", { ccaa: "GA" }],
    ["lugo", { ccaa: "GA" }],
    ["ourense", { ccaa: "GA" }],
    ["pontevedra", { ccaa: "GA" }],
    // Madrid
    ["madrid", { ccaa: "MD" }],
    // Murcia
    ["murcia", { ccaa: "MC" }],
    // Navarra
    ["navarra", { ccaa: "NC" }],
    // País Vasco (foral)
    ["alava", { ccaa: "PV", pv_territorio: "AL" }],
    ["araba", { ccaa: "PV", pv_territorio: "AL" }],
    ["guipuzcoa", { ccaa: "PV", pv_territorio: "GI" }],
    ["gipuzkoa", { ccaa: "PV", pv_territorio: "GI" }],
    ["vizcaya", { ccaa: "PV", pv_territorio: "BI" }],
    ["bizkaia", { ccaa: "PV", pv_territorio: "BI" }],
    // La Rioja
    ["la rioja", { ccaa: "RI" }],
    ["rioja", { ccaa: "RI" }],
    // Ceuta / Melilla
    ["ceuta", { ccaa: "CE" }],
    ["melilla", { ccaa: "ML" }],
  ]);
  return map.get(provincia) || { ccaa: "", pv_territorio: "" };
};

let fiscalWizardPresetsCache = null;
let fiscalWizardPresetsLoading = null;

const loadFiscalWizardPresets = async () => {
  if (fiscalWizardPresetsCache) return fiscalWizardPresetsCache;
  if (fiscalWizardPresetsLoading) return fiscalWizardPresetsLoading;
  fiscalWizardPresetsLoading = (async () => {
    try {
      const resp = await fetch("/assets/supuestos/fiscal_venta_presets.json", { credentials: "same-origin" });
      const data = await resp.json().catch(() => null);
      if (!resp.ok || !data || typeof data !== "object") throw new Error("No se pudieron cargar los supuestos.");
      fiscalWizardPresetsCache = data;
      return data;
    } catch (err) {
      fiscalWizardPresetsCache = null;
      throw err;
    } finally {
      fiscalWizardPresetsLoading = null;
    }
  })();
  return fiscalWizardPresetsLoading;
};

const setFormFieldValue = (form, name, rawValue) => {
  if (!form || !name) return;
  const selector = `[name="${CSS.escape(String(name))}"]`;
  const el = form.querySelector(selector);
  if (!el) return;
  const value = rawValue == null ? "" : rawValue;
  const type = String(el.type || "").toLowerCase();
  if (type === "checkbox") {
    el.checked = Boolean(value);
  } else {
    el.value = typeof value === "string" ? value : String(value);
  }
  try {
    el.dispatchEvent(new Event("change", { bubbles: true }));
  } catch (e) {}
};

const applyFiscalWizardPreset = (preset = null) => {
  if (!preset || typeof preset !== "object") return;
  const wizard = preset.wizard && typeof preset.wizard === "object" ? preset.wizard : {};
  const irpf = preset.irpf && typeof preset.irpf === "object" ? preset.irpf : {};
  const iivtnu = preset.iivtnu && typeof preset.iivtnu === "object" ? preset.iivtnu : {};

  applyFiscalWizardPrefill({
    operacion: wizard.operacion || "venta",
    ccaa: wizard.ccaa || "",
    pv_territorio: wizard.pv_territorio || "",
    referencia: wizard.referencia || "",
    codigo_postal: iivtnu.codigo_postal || "",
    fecha_transmision: irpf.fecha_transmision || iivtnu.fecha_transmision || "",
    valor_transmision: irpf.valor_transmision || iivtnu.valor_transmision || "",
  });

  if (irpfGainForm && irpf && typeof irpf === "object") {
    Object.entries(irpf).forEach(([k, v]) => setFormFieldValue(irpfGainForm, k, v));
  }

  if (iivtnuSimulatorForm && iivtnu && typeof iivtnu === "object") {
    Object.entries(iivtnu).forEach(([k, v]) => setFormFieldValue(iivtnuSimulatorForm, k, v));
  }

  const cp = normalizePostalCode(iivtnu.codigo_postal || "");
  if (iivtnuMunicipioCp && cp && cp.length === 5) {
    iivtnuMunicipioCp.value = cp;
    try {
      iivtnuMunicipioCp.dispatchEvent(new Event("change", { bubbles: true }));
    } catch (e) {}
  }

  fiscalWizardActivePreset = preset;
  setFiscalWizardDgtRefs(preset?.dgt_refs || preset?.dgt || [], { replace: true });
};

const applyFiscalWizardPrefill = (prefill = {}) => {
  if (!prefill || typeof prefill !== "object") return;
  const referencia = String(prefill.referencia || "").trim();
  const operacion = String(prefill.operacion || "").trim().toLowerCase();
  const ccaa = String(prefill.ccaa || "").trim().toUpperCase();
  const pv = String(prefill.pv_territorio || "").trim().toUpperCase();
  const codigoPostal = normalizePostalCode(prefill.codigo_postal || prefill.codigoPostal || "");
  const clienteId = String(prefill.cliente_id || prefill.clienteId || prefill.cliente || "").trim();

  if (fiscalWizardForm) {
    if (operacion && fiscalWizardForm.querySelector(`select[name="operacion"] option[value="${CSS.escape(operacion)}"]`)) {
      fiscalWizardForm.querySelector('select[name="operacion"]').value = operacion;
    }
    if (ccaa && fiscalWizardForm.querySelector(`select[name="ccaa"] option[value="${CSS.escape(ccaa)}"]`)) {
      fiscalWizardForm.querySelector('select[name="ccaa"]').value = ccaa;
    }
    if (pv && fiscalWizardForm.querySelector(`select[name="pv_territorio"] option[value="${CSS.escape(pv)}"]`)) {
      fiscalWizardForm.querySelector('select[name="pv_territorio"]').value = pv;
    }
    if (referencia) {
      const refInput = fiscalWizardForm.querySelector('input[name="referencia"]');
      if (refInput) refInput.value = referencia;
    }
    try {
      syncFiscalWizardPvVisibility();
    } catch (e) {}
    try {
      fiscalWizardForm.dispatchEvent(new Event("change", { bubbles: true }));
    } catch (e) {}
  }

  if (irpfGainForm) {
    if (clienteId) {
      const el = irpfGainForm.querySelector('input[name="cliente_id"]');
      if (el) {
        el.value = clienteId;
        try {
          el.dispatchEvent(new Event("change", { bubbles: true }));
        } catch (e) {}
      }
    }
    if (ccaa && irpfGainForm.querySelector(`select[name="ccaa"] option[value="${CSS.escape(ccaa)}"]`)) {
      irpfGainForm.querySelector('select[name="ccaa"]').value = ccaa;
    }
    if (referencia) {
      const refInput = irpfGainForm.querySelector('input[name="referencia"]');
      if (refInput) refInput.value = referencia;
    }
    const fechaTx = String(prefill.fecha_transmision || prefill.fechaTx || "").trim();
    const valorTx = String(prefill.valor_transmision || prefill.valorTx || "").trim();
    if (fechaTx) {
      const el = irpfGainForm.querySelector('input[name="fecha_transmision"]');
      if (el) el.value = fechaTx;
    }
    if (valorTx) {
      const el = irpfGainForm.querySelector('input[name="valor_transmision"]');
      if (el) el.value = valorTx;
    }
  }

  if (iivtnuSimulatorForm) {
    const fechaTx = String(prefill.fecha_transmision || prefill.fechaTx || "").trim();
    if (fechaTx) {
      const el = iivtnuSimulatorForm.querySelector('input[name="fecha_transmision"]');
      if (el) el.value = fechaTx;
    }
  }

  if (iivtnuMunicipioCp && codigoPostal && codigoPostal.length === 5) {
    iivtnuMunicipioCp.value = codigoPostal;
    try {
      iivtnuMunicipioCp.dispatchEvent(new Event("change", { bubbles: true }));
    } catch (e) {}
  }
};

const openWorkspaceFiscalWizard = (prefill = {}) => {
  if (openEmbeddedFiscalWizard({ pane: "informe", prefill })) {
    return;
  }
  fiscalWizardActivePreset = null;
  setFiscalWizardDgtRefs([], { replace: true });
  let workspace = "";
  try {
    const params = new URLSearchParams(window.location.search || "");
    workspace = String(params.get("workspace") || "").trim();
  } catch (e) {}
  if (!workspace) {
    try {
      workspace = String(state.currentWorkspaceTarget || "").trim();
    } catch (e) {}
  }
  openHolding({ mode: "tenant", workspace, view: "motores", engine: "simuladores" });
  window.setTimeout(() => {
    try {
      setSimuladoresPane("informe");
    } catch (e) {}
    try {
      applyFiscalWizardPrefill(prefill);
    } catch (e) {}
    try {
      scrollToSimuladoresPane("informe");
    } catch (e) {}
  }, 180);
};

