const refreshWorkspaceContabilidad = async ({ force = false } = {}) => {
  if (!workspaceContaReload || !workspaceContaKpis) return;
  if (!state.currentWorkspaceId) return;

  if (workspaceContaReload.dataset.bound !== "1") {
    workspaceContaReload.dataset.bound = "1";
    workspaceContaReload.addEventListener("click", () => refreshWorkspaceContabilidad({ force: true }).catch(() => {}));
  }
  if (workspaceContaEmpresa && workspaceContaEmpresa.dataset.bound !== "1") {
    workspaceContaEmpresa.dataset.bound = "1";
    workspaceContaEmpresa.addEventListener("change", () => {
      state.workspaceContaEmpresaId = String(workspaceContaEmpresa.value || "").trim();
      try {
        localStorage.setItem("crm.workspaceContaEmpresaId", state.workspaceContaEmpresaId);
      } catch (e) {}
      refreshWorkspaceContabilidad({ force: true }).catch(() => {});
    });
  }

  syncWorkspaceContabilidadEmpresaSelect();
  const empresaId = String(state.workspaceContaEmpresaId || "").trim();
  if (!empresaId) {
    workspaceContaKpis.innerHTML = "";
    if (workspaceContaInfo) workspaceContaInfo.textContent = "Sin empresa seleccionada.";
    renderWorkspaceContabilidadFacturas([]);
    renderWorkspaceContabilidadAsientos([]);
    renderWorkspaceContabilidadEntries([]);
    return;
  }

  const cacheAgeMs = Date.now() - Number(state.workspaceContaCache?.ts || 0);
  const isFreshCache = cacheAgeMs >= 0 && cacheAgeMs < 45000;
  if (!force && state.workspaceContaCache && String(state.workspaceContaCache.empresaId || "") === empresaId && isFreshCache) {
    const payload = state.workspaceContaCache.payload || {};
    const facturasPayload = state.workspaceContaCache.facturas || {};
    const asientosPayload = state.workspaceContaCache.asientos || {};
    const summary = payload.summary || {};
    renderGestoriaDashKpis(workspaceContaKpis, [
      { title: "Asientos", value: numberFormatter.format(Number(summary.total_rows || 0)), note: "Anotaciones" },
      { title: "Ingresos", value: euroFormatter.format(Number(summary.ingresos || 0)), note: "Suma importes" },
      { title: "Gastos", value: euroFormatter.format(Number(summary.gastos || 0)), note: "Suma importes" },
      { title: "Resultado", value: euroFormatter.format(Number(summary.resultado || 0)), note: "Ingresos - gastos" },
    ]);
    renderWorkspaceContabilidadFacturas(facturasPayload.rows || []);
    renderWorkspaceContabilidadAsientos(asientosPayload.rows || []);
    renderWorkspaceContabilidadEntries(payload.rows || []);
    if (workspaceContaInfo) workspaceContaInfo.textContent = `Empresa ${empresaId}`;
    return;
  }

  workspaceContaReload.disabled = true;
  workspaceContaReload.textContent = "Cargando...";
  if (workspaceContaInfo) workspaceContaInfo.textContent = "Cargando contabilidad...";
  try {
    const params = new URLSearchParams({ empresa_id: empresaId, limit: "200" });
    const [conta, facturas, asientos] = await Promise.all([
      api(`/api/gestoria_contabilidad?${params.toString()}`),
      api(`/api/gestoria_facturas?${new URLSearchParams({ empresa_id: empresaId }).toString()}`).catch(() => ({ rows: [] })),
      api(`/api/gestoria_asientos?${new URLSearchParams({ empresa_id: empresaId }).toString()}`).catch(() => ({ rows: [] })),
    ]);
    if (conta?.error) throw new Error(String(conta.error));
    state.workspaceContaCache = { empresaId, payload: conta, facturas, asientos, ts: Date.now() };

    const summary = conta.summary || {};
    renderGestoriaDashKpis(workspaceContaKpis, [
      { title: "Anotaciones", value: numberFormatter.format(Number(summary.total_rows || 0)), note: "gestoria_contabilidad" },
      { title: "Ingresos", value: euroFormatter.format(Number(summary.ingresos || 0)), note: "Suma importes" },
      { title: "Gastos", value: euroFormatter.format(Number(summary.gastos || 0)), note: "Suma importes" },
      { title: "Resultado", value: euroFormatter.format(Number(summary.resultado || 0)), note: "Ingresos - gastos" },
    ]);
    renderWorkspaceContabilidadFacturas(facturas.rows || []);
    renderWorkspaceContabilidadAsientos(asientos.rows || []);
    renderWorkspaceContabilidadEntries(conta.rows || []);
    if (workspaceContaInfo) {
      const companyName =
        (state.currentWorkspaceDetail?.companies || []).find((row) => String(row.id || "") === empresaId)?.nombre || empresaId;
      workspaceContaInfo.textContent = `Empresa: ${companyName}`;
    }
  } catch (err) {
    workspaceContaKpis.innerHTML = "";
    renderWorkspaceContabilidadFacturas([]);
    renderWorkspaceContabilidadAsientos([]);
    renderWorkspaceContabilidadEntries([]);
    if (workspaceContaInfo) workspaceContaInfo.textContent = err?.message || "No se pudo cargar la contabilidad.";
  } finally {
    workspaceContaReload.disabled = false;
    workspaceContaReload.textContent = "Actualizar";
  }
};

const fillWorkspaceBillingForm = (record = null) => {
  if (!workspaceBillingForm) return;
  hydrateWorkspaceCompanySelects();
  const companies = state.currentWorkspaceDetail?.companies || [];
  const emptyRecord = {
    id: "",
    workspace_id: state.currentWorkspaceId || "",
    empresa_id: state.currentWorkspaceCompanyId || companies[0]?.id || "",
    cliente_id: "",
    cliente_lookup: "",
    servicio: "",
    serie: "",
    numero: "",
    fecha_emision: "",
    fecha_vencimiento: "",
    subtotal: "",
    impuestos: "",
    total: "",
    estado: "Borrador",
    forma_cobro: "",
    responsable: "",
    cobrada: 0,
    concepto: "",
    notas: "",
  };
  const payload = { ...emptyRecord, ...(record || {}) };
  ["id", "workspace_id", "empresa_id", "cliente_id", "servicio", "serie", "numero", "fecha_emision", "fecha_vencimiento", "subtotal", "impuestos", "total", "estado", "forma_cobro", "responsable", "concepto", "notas"].forEach((field) => {
    const input = workspaceBillingForm.querySelector(`[name="${field}"]`);
    if (!input) return;
    input.value = payload[field] ?? "";
  });
  const chargedInput = workspaceBillingForm.querySelector('[name="cobrada"]');
  if (chargedInput) chargedInput.checked = Number(payload.cobrada || 0) === 1;
  if (workspaceBillingClienteLookup) {
    workspaceBillingClienteLookup.value = payload.cliente_lookup || "";
  }
};

const renderWorkspaceBillingList = (rows = []) => {
  if (!workspaceBillingList) return;
  state.workspaceBillingRows = Array.isArray(rows) ? rows : [];
  if (!state.workspaceBillingRows.length) {
    workspaceBillingList.innerHTML = "<p class='muted'>Sin movimientos de facturación todavía.</p>";
    return;
  }
  workspaceBillingList.innerHTML = `
    <div class="workspace-billing-list">
      ${state.workspaceBillingRows
        .map(
          (row) => `
            <div class="workspace-billing-row">
              <div>
                <strong>${row.concepto || "Movimiento sin concepto"}</strong>
                <div class="muted">${row.empresa_nombre || "-"}${row.cliente_nombre ? ` · ${row.cliente_nombre}` : ""}</div>
                <div class="muted">Saldo ${euroFormatter.format(Number(row.saldo_pendiente || 0))}${row.remesa_id ? " · en remesa" : ""}${row.conciliacion_estado ? ` · ${row.conciliacion_estado}` : ""}</div>
              </div>
              <div class="workspace-billing-meta">
                <span>${row.fecha_emision || "Sin fecha"}</span>
                <span>${euroFormatter.format(Number(row.total || 0))}</span>
                <span>${row.estado || "Borrador"}</span>
                <a class="secondary ghost button-inline" href="/api/workspace_factura_pdf?id=${encodeURIComponent(row.id || "")}&workspace_id=${encodeURIComponent(state.currentWorkspaceId || "")}" target="_blank" rel="noreferrer">PDF</a>
                ${Number(row.saldo_pendiente || 0) > 0 ? `<button type="button" class="secondary ghost" data-billing-collect="${row.id}">Cobrar</button>` : ""}
                <button type="button" class="secondary ghost" data-billing-edit="${row.id}">Editar</button>
              </div>
            </div>
          `
        )
        .join("")}
    </div>
  `;
  workspaceBillingList.querySelectorAll("[data-billing-edit]").forEach((button) => {
    button.addEventListener("click", () => {
      const billingId = button.dataset.billingEdit || "";
      const record = state.workspaceBillingRows.find((row) => String(row.id || "") === String(billingId));
      if (!record) return;
      const clientLabel = record.cliente_nombre
        ? `${record.cliente_nombre}${record.cliente_nif ? ` · ${record.cliente_nif}` : ""}`
        : "";
      fillWorkspaceBillingForm({ ...record, cliente_lookup: clientLabel });
      if (workspaceBillingStatus) workspaceBillingStatus.textContent = "Editando movimiento existente.";
      workspaceBillingForm?.scrollIntoView({ behavior: "smooth", block: "start" });
    });
  });
  workspaceBillingList.querySelectorAll("[data-billing-collect]").forEach((button) => {
    button.addEventListener("click", () => {
      const billingId = button.dataset.billingCollect || "";
      const record = state.workspaceBillingRows.find((row) => String(row.id || "") === String(billingId));
      if (!record) return;
      fillWorkspaceCollectionsForm({
        factura_id: record.id,
        fecha_cobro: new Date().toISOString().slice(0, 10),
        importe: Number(record.saldo_pendiente || 0).toFixed(2),
        metodo: record.forma_cobro || "Transferencia",
        estado: "Aplicado",
        referencia: [record.serie, record.numero].filter(Boolean).join("-"),
      });
      if (workspaceCollectionsStatus) workspaceCollectionsStatus.textContent = "Cobro preparado desde la factura.";
      workspaceCollectionsForm?.scrollIntoView({ behavior: "smooth", block: "start" });
    });
  });
};

const parseWorkspaceBudgetLinesText = (raw = "") => {
  return String(raw || "")
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean)
    .map((line) => {
      const [categoria = "", concepto = "", cantidad = "1", unidad = "", precio = "0", descuento = "0"] = line.split("|").map((part) => part.trim());
      return {
        categoria,
        concepto: concepto || categoria,
        cantidad: Number(cantidad || 0) || 0,
        unidad,
        precio_unitario: Number(precio || 0) || 0,
        descuento_pct: Number(descuento || 0) || 0,
      };
    })
    .filter((line) => line.concepto);
};

