const hydrateWorkspaceCompanySelects = () => {
  const companies = state.currentWorkspaceDetail?.companies || [];
  const defaultCompanyId = state.currentWorkspaceCompanyId || companies[0]?.id || "";
  const html = companies.map((row) => `<option value="${row.id}">${row.nombre || "-"}</option>`).join("");
  [
    workspaceBillingForm,
    workspaceBudgetForm,
    workspaceInboxForm,
    workspaceFacturaUploadForm,
    workspaceSeriesForm,
    workspaceTimeForm,
    workspaceTimeEmployeeForm,
    workspaceFincasCommunityForm,
    workspaceRemittancesForm,
    workspaceFincasProviderForm,
    workspaceFincasBudgetQuickForm,
  ].forEach((form) => {
    const select = form?.querySelector('[name="empresa_id"]');
    if (select) {
      select.innerHTML = html;
      if (defaultCompanyId) {
        select.value = defaultCompanyId;
      }
      if (!String(select.value || "").trim() && companies[0]?.id) {
        select.value = companies[0].id;
      }
    }
  });
};

const ensureWorkspaceCompaniesLoaded = async () => {
  const current = state.currentWorkspaceDetail?.companies || [];
  if (current.length || !state.currentWorkspaceId) {
    return current;
  }
  const detail = await safeWorkspaceApi(`/api/workspace_detail?id=${encodeURIComponent(state.currentWorkspaceId)}`, null);
  if (detail?.workspace) {
    state.currentWorkspaceDetail = {
      ...(state.currentWorkspaceDetail || {}),
      ...detail,
    };
  }
  return state.currentWorkspaceDetail?.companies || [];
};

