const normalizeWorkspaceFincasTab = (value = "") => {
  const key = String(value || "").trim().toLowerCase();
  if (["dashboard", "comunidades", "comunidad_ficha", "incidencias", "proveedores", "juntas", "contabilidad", "presupuestos"].includes(key)) return key;
  return "dashboard";
};

const renderWorkspaceFincasDashboard = () => {
  if (!workspaceFincasDashboardKpis) return;
  const raw = state.currentWorkspaceData || {};
  const communities = filterWorkspaceFincasRowsByCompany(raw.fincasCommunities || []);
  const communityIds = new Set(communities.map((row) => String(row.id || "")).filter(Boolean));
  const comuneros = communities.reduce((acc, row) => acc + (Number(row.num_vecinos || 0) || 0), 0);
  const cuotaMensual = communities.reduce((acc, row) => acc + (Number(row.cuota_mensual || 0) || 0), 0);
  const budgetsBase = shouldScopeFincasByCompany()
    ? filterWorkspaceRowsByCompany(raw.budgetRows || [])
    : (Array.isArray(raw.budgetRows) ? raw.budgetRows : []);
  const budgets = budgetsBase.filter((row) => normalizeBudgetServiceKey(row.servicio || "") === "fincas");
  const selectedYear = String(yearSelect?.value || "").trim() || String(new Date().getFullYear());
  const getRowYear = (row) => {
    const dateValue = String(row?.fecha || row?.created_at || row?.updated_at || "").trim();
    const match = dateValue.match(/^(\d{4})/);
    return match ? match[1] : "";
  };
  const budgetsYear = budgets.filter((row) => getRowYear(row) === selectedYear);
  const budgetsTotal = budgetsYear.length;
  const budgetsAccepted = budgetsYear.filter((row) => normalizeSimple(row.estado || "") === "aceptado").length;
  const budgetsRejected = budgetsYear.filter((row) => normalizeSimple(row.estado || "") === "rechazado").length;
  const budgetsPresented = budgetsYear.filter((row) => normalizeSimple(row.estado || "") !== "borrador").length;
  const budgetsAcceptRatio = budgetsPresented > 0 ? `${((budgetsAccepted / budgetsPresented) * 100).toFixed(0)}%` : "-";
  const budgetsRejectRatio = budgetsPresented > 0 ? `${((budgetsRejected / budgetsPresented) * 100).toFixed(0)}%` : "-";
  const ledgerRows = Array.isArray(state.workspaceFincasLedgerRows) ? state.workspaceFincasLedgerRows : [];
  const relevantLedger = ledgerRows.filter((row) => !row.comunidad_id || communityIds.has(String(row.comunidad_id || "")));
  const ingresos = relevantLedger
    .filter((row) => normalizeSimple(row.tipo || "") === "ingreso")
    .reduce((acc, row) => acc + (Number(row.importe || 0) || 0), 0);
  const gastos = relevantLedger
    .filter((row) => normalizeSimple(row.tipo || "") === "gasto")
    .reduce((acc, row) => acc + (Number(row.importe || 0) || 0), 0);
  const ctxLabel = getWorkspaceCompanyContextLabel();

  const kpis = [
    { label: "Comunidades", value: numberFormatter.format(communities.length || 0), note: `Contexto: ${ctxLabel}` },
    { label: "Comuneros", value: numberFormatter.format(comuneros || 0), note: "Suma de viviendas" },
    { label: "Cuota mensual", value: euroFormatter.format(cuotaMensual || 0), note: "Suma de cuotas por comunidad" },
    { label: "Ingresos", value: euroFormatter.format(ingresos || 0), note: "Desde contabilidad (ingresos)" },
    { label: "Gastos", value: euroFormatter.format(gastos || 0), note: "Desde contabilidad (gastos)" },
    {
      label: `Presupuestos ${selectedYear}`,
      value: `${budgetsAccepted}/${budgetsPresented}`,
      note: `Aceptados/presentados · rechazados ${budgetsRejected} · ratio ok ${budgetsAcceptRatio} · ratio no ${budgetsRejectRatio}`,
    },
  ];

  workspaceFincasDashboardKpis.innerHTML = `
    <div class="workspace-summary-kpis">
      ${kpis.map((item) => `
        <div class="workspace-mini-kpi">
          <span>${escapeHtml(item.label)}</span>
          <strong>${escapeHtml(item.value)}</strong>
          <div class="muted">${escapeHtml(item.note || "")}</div>
        </div>
      `).join("")}
    </div>
    <p class="muted">Tip: registra movimientos en la pestaña Contabilidad para que el dashboard se alimente automáticamente.</p>
  `;
};

let _workspaceFincasCommunitiesLastFetchAt = 0;
const refreshWorkspaceFincasCommunities = async ({ force = false, silent = false } = {}) => {
  if (!state.currentWorkspaceId) return;
  const nowTs = Date.now();
  if (!force && _workspaceFincasCommunitiesLastFetchAt && (nowTs - _workspaceFincasCommunitiesLastFetchAt) < 1500) {
    return;
  }
  _workspaceFincasCommunitiesLastFetchAt = nowTs;
  try {
    const data = await api(`/api/workspace_fincas_comunidades?workspace_id=${encodeURIComponent(state.currentWorkspaceId)}&limit=500`);
    const rows = Array.isArray(data?.rows) ? data.rows : [];
    state.currentWorkspaceData = {
      ...(state.currentWorkspaceData || {}),
      fincasCommunities: rows,
    };
    renderWorkspaceCompanyScopedData();
    if (!silent && workspaceFincasCommunityStatus) workspaceFincasCommunityStatus.textContent = "";
  } catch (error) {
    if (!silent && workspaceFincasCommunityStatus) {
      workspaceFincasCommunityStatus.textContent = error?.message || "No se pudieron refrescar las comunidades.";
    }
  }
};

