const loadWorkspaceDetail = async (workspaceId) => {
  if (!workspaceId) return;
  state.currentWorkspaceId = workspaceId;
  state.currentWorkspaceMemberRole = "";
  try {
    const wsRow = (state.workspaces || []).find((row) => String(row?.id || "") === String(workspaceId || ""));
    if (wsRow && wsRow.member_role != null) {
      state.currentWorkspaceMemberRole = String(wsRow.member_role || "").trim();
    }
  } catch (e) {}
  try {
    localStorage.setItem("crm.currentWorkspaceId", String(workspaceId || ""));
  } catch (e) {}
  // Evita cargar un workspace con DB todavía "fría" (Render/PG): si no, se muestran fichas vacías y
  // el usuario siente que "se han borrado" configuraciones.
  {
    const health = await probeDbHealth();
    if (!health.ok) {
      const attempt = Number(state.workspaceDetailRetryAttempt || 0) || 0;
      const nextAttempt = Math.min(8, attempt + 1);
      state.workspaceDetailRetryAttempt = nextAttempt;
      const delayMs = Math.min(45000, 1200 * Math.pow(1.6, nextAttempt));
      setUiToast("Base de datos no disponible", `${health.body || `HTTP ${health.status}`} · Reintentando en ${Math.round(delayMs / 1000)}s...`);
      window.setTimeout(() => {
        loadWorkspaceDetail(workspaceId).catch(() => {});
      }, delayMs);
      return;
    }
    state.workspaceDetailRetryAttempt = 0;
  }
  hideUiToast();
  const authUser = getAuthScopeUser();
  const isSuperAdmin = Boolean(authUser && isPrivilegedUser(authUser));
  let canManageWorkspace = Boolean(authUser && canManageCurrentWorkspace());
  // Necesario para selects (Responsable/Asesor) en CRMs verticales.
  // El endpoint filtra lo sensible (emails) para usuarios no privilegiados.
  await safeWorkspaceApi(`/api/usuarios?workspace_id=${encodeURIComponent(workspaceId)}`, { rows: authUser ? [authUser] : [] }).then((data) => {
    const rows = Array.isArray(data?.rows) ? data.rows : [];
    state.usersList = rows.length ? rows : authUser ? [authUser] : [];
    populateResponsableSelects();
    populateAsesorSelects();
    refreshSegurosColaboradoresList();
  });
  // Reset inmediato para evitar que, si falla la carga, se queden datos “pegados” del workspace/persona anterior.
  state.currentWorkspaceClients = [];
  state.currentWorkspaceData = {};
  state.workspaceTimeEmployees = [];
  state.workspaceTimeSummary = null;
  state.currentWorkspaceServiceMatrixRows = [];
  state.currentWorkspaceServiceCompanyDefaults = {};
  let detail = null;
  detail = await safeWorkspaceApi(`/api/workspace_detail?id=${encodeURIComponent(workspaceId)}`, null);
  if (!detail || !detail.workspace) {
    clearCurrentWorkspaceUi();
    updateWorkspaceEntryChrome();
    const attempt = Number(state.workspaceDetailRetryAttempt || 0) || 0;
    const nextAttempt = Math.min(8, attempt + 1);
    state.workspaceDetailRetryAttempt = nextAttempt;
    const delayMs = Math.min(45000, 1200 * Math.pow(1.6, nextAttempt));
    const lastErr = state.lastApiError?.message ? String(state.lastApiError.message) : "No se pudo cargar el workspace.";
    setUiToast("Error cargando el workspace", `${lastErr} · Reintentando en ${Math.round(delayMs / 1000)}s...`);
    window.setTimeout(() => {
      loadWorkspaceDetail(workspaceId).catch(() => {});
    }, delayMs);
    return;
  }
  try {
    if (detail.member_role != null) {
      state.currentWorkspaceMemberRole = String(detail.member_role || "").trim();
    }
  } catch (e) {}
  if (detail && typeof detail.can_manage_workspace !== "undefined") {
    canManageWorkspace = Boolean(authUser && (isSuperAdmin || Boolean(detail.can_manage_workspace) || canManageCurrentWorkspace()));
  } else {
    canManageWorkspace = Boolean(authUser && canManageCurrentWorkspace());
  }
  // Normaliza companies: muchas pantallas legacy consumen `detail.companies`.
  // En modo v2 (workspace_companies) preferimos `companies_v2`, pero exponemos también el array unificado en `companies`
  // para no romper dependencias antiguas (RRHH, formularios, openCompany, etc.).
  try {
    const companiesV2 = Array.isArray(detail?.companies_v2) ? detail.companies_v2 : [];
    const companiesLegacy = Array.isArray(detail?.companies) ? detail.companies : [];
    const unified = companiesV2.length ? companiesV2 : companiesLegacy;
    detail.companies = unified;
  } catch (e) {}
  state.currentWorkspaceDetail = detail;
  state.currentWorkspaceEnabledModules = getWorkspaceEnabledModules(detail.modules || []);
  state.currentWorkspaceName = detail.workspace?.nombre || "";
  {
    const matrix = await safeWorkspaceApi(
      `/api/workspace_service_matrix?workspace_id=${encodeURIComponent(workspaceId)}`,
      { rows: [], defaults: {} }
    );
    state.currentWorkspaceServiceMatrixRows = Array.isArray(matrix?.rows) ? matrix.rows : [];
    state.currentWorkspaceServiceCompanyDefaults = matrix?.defaults && typeof matrix.defaults === "object" ? matrix.defaults : {};
  }
  // Mantén la URL alineada con el workspace seleccionado.
  // Usamos `id` para evitar ambigüedad entre slugs legacy (modernia/verifika2) y nombres rebrandeados.
  state.currentWorkspaceTarget = String(detail.workspace?.id || workspaceId || "").trim() || String(workspaceId || "").trim();
  syncHoldingUrlParams();
  const companiesV2 = Array.isArray(detail?.companies_v2) ? detail.companies_v2 : [];
  const companiesLegacy = Array.isArray(detail?.companies) ? detail.companies : [];
  const companies = companiesV2.length ? companiesV2 : companiesLegacy;
  const tenantOperationalMode = (state.currentWorkspaceEntryMode || "platform") === "tenant";
  const companyMatch = companies.find((row) => {
    const rowWsId = String(row?.id || "").trim();
    const rowLegacyId = String(row?.legacy_empresa_id || "").trim();
    const wantedLegacy = String(state.currentWorkspaceCompanyId || "").trim();
    const wantedWs = String(state.currentWorkspaceCompanyWsId || "").trim();
    if (wantedWs && rowWsId && rowWsId === wantedWs) return true;
    if (wantedLegacy && rowLegacyId && rowLegacyId === wantedLegacy) return true;
    return false;
  });
  const picked = companyMatch || companies[0] || null;
  if (tenantOperationalMode) {
    state.currentWorkspaceCompanyName = picked?.nombre || "";
    state.currentWorkspaceCompanyWsId = companiesV2.length ? String(picked?.id || "") : "";
    state.currentWorkspaceCompanyId = companiesV2.length
      ? String(picked?.legacy_empresa_id || picked?.id || "")
      : String(picked?.id || "");
  } else {
    state.currentWorkspaceCompanyName = picked?.nombre || "";
    state.currentWorkspaceCompanyWsId = companiesV2.length ? String(picked?.id || "") : "";
    state.currentWorkspaceCompanyId = companiesV2.length ? String(picked?.legacy_empresa_id || "") : String(picked?.id || "");
  }
  const companyQuery = getWorkspaceCompanyQuery();
  const timeMonth = normalizeMonthValue(state.workspaceTimeMonth || "");
  state.workspaceTimeMonth = timeMonth;
  const viewHint = String(
    state.currentWorkspaceView
      || new URLSearchParams(window.location.search || "").get("view")
      || ""
  )
    .trim()
    .toLowerCase();
  const minimalForRrhh = viewHint === "rrhh";

  // Pintado rápido del workspace: módulos + estructura, sin esperar a cargar paneles pesados.
  // Esto mejora mucho el "time-to-first-cards" al entrar en Operativa.
  fillWorkspaceForm(detail.workspace || {});
  renderWorkspaceCommercialPack(detail.workspace || {}, detail.commercial_package || {});
  renderWorkspacePermissionMatrix(detail.permission_matrix || []);
  renderWorkspaceLauncher(detail.workspace || {}, detail.modules || []);
  renderWorkspaceCompanySwitcher(companies);
  renderWorkspaceCompanies(companies);
  renderWorkspaceModules(detail.modules || []);
  updateWorkspaceEntryChrome();
  syncCrmLegalAvailability();
  {
    const tenantMode = (state.currentWorkspaceEntryMode || "platform") === "tenant";
    const view = state.currentWorkspaceView || "overview";
    setWorkspaceView(view, { forceTenantView: tenantMode && normalizeSimple(view) !== "operations" });
  }
  renderWorkspaceList(state.workspaces || []);
  renderCompanyCards();

  // Fast boot: 1 request en lugar de 20-25 (mejora enorme en iOS/PWA).
  const bootParams = new URLSearchParams({
    workspace_id: String(workspaceId || ""),
    month: String(timeMonth || ""),
  });
  if (state.currentWorkspaceCompanyId) {
    bootParams.set("empresa_id", String(state.currentWorkspaceCompanyId || ""));
  }
  if (minimalForRrhh) {
    bootParams.set("minimal", "1");
  }
  const boot = await safeWorkspaceApi(`/api/workspace_boot?${bootParams.toString()}`, null);

  const timeUsers = boot?.time_users || await safeWorkspaceApi(
    `/api/workspace_registro_usuarios?workspace_id=${encodeURIComponent(workspaceId)}${companyQuery}&limit=300`,
    { rows: [] }
  );
  state.workspaceTimeUsers = timeUsers.rows || [];

  let members = { rows: [] };
  if (canManageWorkspace) {
    members = await safeWorkspaceApi(`/api/workspace_members?workspace_id=${encodeURIComponent(workspaceId)}`, { rows: [] });
  }
  state.currentWorkspaceMembers = members.rows || [];
  let links = { rows: [] };
  if (canManageWorkspace) {
    links = await safeWorkspaceApi(`/api/workspace_links?workspace_id=${encodeURIComponent(workspaceId)}`, { rows: [] });
  }
  state.currentWorkspaceLinks = links.rows || [];

  // Evitar "stampede" de decenas de requests al entrar en el workspace.
  let billing = {};
  let docs = { rows: [], summary: {} };
  let billingRows = { rows: [] };
  let budgetRows = { rows: [] };
  let collections = { rows: [] };
  let remittances = { rows: [] };
  let workspaceClients = { rows: [] };
  let health = {};
  let gestoriaOverview = {};
  let segurosOverview = {};
  let finOverview = {};
  let inmoOverview = {};
  let serviceDesks = {};
  let series = { rows: [] };
  let inbox = { rows: [] };
  let portal = { rows: [] };
  let portalRequests = { rows: [] };
  let automations = { rows: [] };
  let automationLogs = { rows: [] };

  // RRHH necesita estos datos para pintar cards y jornada.
  const timeRows = boot?.time_rows || await safeWorkspaceApi(
    `/api/workspace_registro_horario?workspace_id=${encodeURIComponent(workspaceId)}&month=${encodeURIComponent(timeMonth)}${companyQuery}&limit=250`,
    { rows: [] }
  );
  const timeEmployees = boot?.time_employees || await safeWorkspaceApi(
    `/api/workspace_registro_personal?workspace_id=${encodeURIComponent(workspaceId)}${companyQuery}&activos=0&limit=500`,
    { rows: [] }
  );
  const timeSummary = boot?.time_summary || await safeWorkspaceApi(
    `/api/workspace_registro_horario_resumen?workspace_id=${encodeURIComponent(workspaceId)}&month=${encodeURIComponent(timeMonth)}${companyQuery}`,
    {}
  );
  const timePeriods = boot?.time_periods || await safeWorkspaceApi(
    `/api/workspace_registro_periodos?workspace_id=${encodeURIComponent(workspaceId)}${companyQuery}`,
    { rows: [] }
  );
  let fincasCommunities = boot?.fincas_communities || { rows: [] };
  let fincasIncidents = boot?.fincas_incidents || { rows: [] };
  let fincasProviders = boot?.fincas_providers || { rows: [] };
  let fincasMeetings = boot?.fincas_meetings || { rows: [] };

  if (!minimalForRrhh) {
    billing = boot?.billing_summary || await safeWorkspaceApi(`/api/workspace_billing_summary?workspace_id=${encodeURIComponent(workspaceId)}`, {});
    docs = boot?.docs || await safeWorkspaceApi(`/api/workspace_document_hub?workspace_id=${encodeURIComponent(workspaceId)}`, { rows: [], summary: {} });
    billingRows = boot?.billing_rows || await safeWorkspaceApi(`/api/workspace_facturacion?workspace_id=${encodeURIComponent(workspaceId)}`, { rows: [] });
    budgetRows = boot?.budget_rows || await safeWorkspaceApi(`/api/workspace_presupuestos?workspace_id=${encodeURIComponent(workspaceId)}`, { rows: [] });
    collections = boot?.collections || await safeWorkspaceApi(`/api/workspace_cobros?workspace_id=${encodeURIComponent(workspaceId)}`, { rows: [] });
    remittances = boot?.remittances || await safeWorkspaceApi(`/api/workspace_remesas?workspace_id=${encodeURIComponent(workspaceId)}`, { rows: [] });
    workspaceClients = boot?.clients || await safeWorkspaceApi(`/api/workspace_clientes?workspace_id=${encodeURIComponent(workspaceId)}&limit=60`, { rows: [] });
    health = boot?.health || await safeWorkspaceApi(`/api/workspace_health?workspace_id=${encodeURIComponent(workspaceId)}`, {});
    gestoriaOverview = boot?.gestoria_overview || await safeWorkspaceApi(`/api/workspace_gestoria_overview?workspace_id=${encodeURIComponent(workspaceId)}${companyQuery}`, {});
    segurosOverview = boot?.seguros_overview || await safeWorkspaceApi(`/api/workspace_seguros_overview?workspace_id=${encodeURIComponent(workspaceId)}${companyQuery}`, {});
    finOverview = boot?.fin_overview || await safeWorkspaceApi(`/api/workspace_fin_overview?workspace_id=${encodeURIComponent(workspaceId)}${companyQuery}`, {});
    inmoOverview = boot?.inmo_overview || await safeWorkspaceApi(`/api/workspace_inmo_overview?workspace_id=${encodeURIComponent(workspaceId)}${companyQuery}`, {});
    serviceDesks = boot?.service_desks || await safeWorkspaceApi(`/api/workspace_service_desks?workspace_id=${encodeURIComponent(workspaceId)}${companyQuery}`, {});
    series = boot?.series || await safeWorkspaceApi(`/api/workspace_series?workspace_id=${encodeURIComponent(workspaceId)}`, { rows: [] });
    inbox = boot?.inbox || await safeWorkspaceApi(`/api/workspace_inbox?workspace_id=${encodeURIComponent(workspaceId)}`, { rows: [] });
    portal = boot?.portal || await safeWorkspaceApi(`/api/workspace_portal?workspace_id=${encodeURIComponent(workspaceId)}`, { rows: [] });
    portalRequests = boot?.portal_requests || await safeWorkspaceApi(`/api/workspace_portal_requerimientos?workspace_id=${encodeURIComponent(workspaceId)}`, { rows: [] });
    automations = boot?.automations || await safeWorkspaceApi(`/api/workspace_automatizaciones?workspace_id=${encodeURIComponent(workspaceId)}`, { rows: [] });
    automationLogs = boot?.automation_logs || await safeWorkspaceApi(`/api/workspace_automatizacion_logs?workspace_id=${encodeURIComponent(workspaceId)}&limit=12`, { rows: [] });
    fincasCommunities = boot?.fincas_communities || await safeWorkspaceApi(`/api/workspace_fincas_comunidades?workspace_id=${encodeURIComponent(workspaceId)}`, { rows: [] });
    fincasIncidents = boot?.fincas_incidents || await safeWorkspaceApi(`/api/workspace_fincas_incidencias?workspace_id=${encodeURIComponent(workspaceId)}`, { rows: [] });
    fincasProviders = boot?.fincas_providers || await safeWorkspaceApi(`/api/workspace_fincas_proveedores?workspace_id=${encodeURIComponent(workspaceId)}`, { rows: [] });
    fincasMeetings = boot?.fincas_meetings || await safeWorkspaceApi(`/api/workspace_fincas_juntas?workspace_id=${encodeURIComponent(workspaceId)}`, { rows: [] });
  }
  state.currentWorkspaceClients = workspaceClients.rows || [];
  state.currentWorkspaceData = {
    docs,
    billingRows: billingRows.rows || [],
    budgetRows: budgetRows.rows || [],
    collectionRows: collections.rows || [],
    remittanceRows: remittances.rows || [],
    seriesRows: series.rows || [],
    inboxRows: inbox.rows || [],
    portalRows: portal.rows || [],
    portalRequestRows: portalRequests.rows || [],
    automationRows: automations.rows || [],
    automationLogRows: automationLogs.rows || [],
    timeRows: timeRows.rows || [],
    timeEmployees: timeEmployees.rows || [],
    timeSummary: timeSummary || null,
    timePeriods: timePeriods.rows || [],
    fincasCommunities: fincasCommunities.rows || [],
    fincasIncidents: fincasIncidents.rows || [],
    fincasProviders: fincasProviders.rows || [],
    fincasMeetings: fincasMeetings.rows || [],
  };
  state.workspaceTimeEmployees = timeEmployees.rows || [];
  state.workspaceTimeSummary = timeSummary || null;
  syncWorkspaceClientOptions(workspaceClients.rows || []);
  fillWorkspaceForm(detail.workspace || {});
  let systemAudit = null;
  if (!minimalForRrhh) {
    try {
      const auditPayload = await safeWorkspaceApi("/api/system_audit_latest", null);
      if (auditPayload && typeof auditPayload === "object" && Object.keys(auditPayload).length) {
        systemAudit = auditPayload;
      }
    } catch (e) {}
  }
  renderWorkspaceHealth(health || {}, systemAudit);
  renderWorkspaceCommercialPack(detail.workspace || {}, detail.commercial_package || {});
  renderWorkspacePermissionMatrix(detail.permission_matrix || []);
  renderWorkspaceLauncher(detail.workspace || {}, detail.modules || []);
  void refreshWorkspaceHomeAlerts();
  renderWorkspaceCompanySwitcher(companies);
  renderWorkspaceCompanies(companies);
  renderWorkspaceMembers(state.currentWorkspaceMembers || []);
  renderWorkspaceLinks(state.currentWorkspaceLinks || []);
  renderWorkspaceClientBase(workspaceClients.rows || []);
  renderWorkspaceClientDetail(null);
  renderWorkspaceModules(detail.modules || []);
  renderWorkspaceBillingSummary(billing || {});
  renderWorkspaceGestoriaOverview(gestoriaOverview || {});
  renderWorkspaceSegurosOverview(segurosOverview || {});
  renderWorkspaceFinOverview(finOverview || {});
  renderWorkspaceInmoOverview(inmoOverview || {});
  renderWorkspaceServiceDesks(serviceDesks || {});
  renderWorkspaceCopilotHub();
  renderWorkspaceRrhhHub();
  if (state.currentWorkspaceView === "motores") {
    const engine = state.currentWorkspaceEngineView || "documental";
    if (engine === "registro_horario") {
      if (isWorkspaceTimeManager()) {
        await refreshWorkspaceTimeSetup();
        await refreshWorkspaceTimeSweepStatus();
        await runWorkspaceTimeAlertSweep();
      } else {
        applyWorkspaceTimeMode();
      }
    }
    if (engine === "rrhh") {
      await refreshWorkspaceRrhh();
    }
  }
  fillWorkspaceBillingForm();
  fillWorkspaceBudgetForm();
  fillWorkspaceCollectionsForm();
  fillWorkspaceRemittancesForm();
  fillWorkspaceSeriesForm();
  fillWorkspaceInboxForm();
  fillWorkspacePortalRequestForm();
  fillWorkspaceAutomationForm();
  fillWorkspaceTimeEmployeeForm();
  fillWorkspaceTimeForm();
  fillWorkspaceFincasCommunityForm();
  fillWorkspaceFincasIncidentForm();
  fillWorkspaceFincasProviderForm();
  fillWorkspaceFincasMeetingForm();
  renderWorkspaceCompanyScopedData();
  updateWorkspaceEntryChrome();
  syncCrmLegalAvailability();
  {
    const tenantMode = (state.currentWorkspaceEntryMode || "platform") === "tenant";
    const view = state.currentWorkspaceView || "overview";
    setWorkspaceView(view, { forceTenantView: tenantMode && normalizeSimple(view) !== "operations" });
  }
  if ((workspaceClients.rows || []).length) {
    await openWorkspaceClient360((workspaceClients.rows || [])[0].id, {
      prefetchedRow: (workspaceClients.rows || [])[0],
      silent: true,
    });
  } else {
    state.currentWorkspaceClientId = "";
    state.currentWorkspaceClientData = null;
    renderWorkspaceClientDetail(null);
  }
  renderWorkspaceList(state.workspaces || []);
  renderCompanyCards();
};

const loadWorkspaceCentral = async () => {
  // Si la DB está fría, /api/workspaces puede tardar 30s por timeout. Mejor gatear con /api/health (rápido)
  // y reintentar con backoff.
  const health = await probeDbHealth();
  if (!health.ok) {
    clearCurrentWorkspaceUi();
    renderWorkspaceList([]);
    try {
      setUiToast(
        "Base de datos no disponible",
        `${health.body || `HTTP ${health.status}`} · Reintentando cargar el workspace en unos segundos...`
      );
    } catch (e) {}
    updateWorkspaceEntryChrome();
    const attempt = Number(state.workspaceCentralRetryAttempt || 0) || 0;
    const nextAttempt = Math.min(7, attempt + 1);
    state.workspaceCentralRetryAttempt = nextAttempt;
    const delayMs = Math.min(45000, 1000 * Math.pow(1.8, nextAttempt));
    window.setTimeout(() => {
      loadWorkspaceCentral().catch(() => {});
    }, delayMs);
    return;
  }
  const data = await safeWorkspaceApi("/api/workspaces", null);
  if (!data) {
    clearCurrentWorkspaceUi();
    renderWorkspaceList([]);
    // Evita un alert bloqueante: en Render esto suele ser un reinicio/deploy o cold start.
    try {
      const last = state.lastApiError || {};
      if (document.body.classList.contains("auth-locked") || last.status === 401) {
        // Si hemos caído a login, no mostramos toast extra.
      } else if (last.status) {
        setUiToast("Error al cargar", last.message || `HTTP ${last.status}`);
      } else {
        setUiToast("Servidor no disponible", (last.message || "Reintentando...").trim() || "Reintentando...");
      }
    } catch (e) {}
    updateWorkspaceEntryChrome();
    // Reintento con backoff simple.
    const attempt = Number(state.workspaceCentralRetryAttempt || 0) || 0;
    const nextAttempt = Math.min(6, attempt + 1);
    state.workspaceCentralRetryAttempt = nextAttempt;
    const delayMs = Math.min(30000, 1000 * Math.pow(2, nextAttempt));
    window.setTimeout(() => {
      loadWorkspaceCentral().catch(() => {});
    }, delayMs);
    return;
  }
  hideUiToast();
  state.workspaceCentralRetryAttempt = 0;
  state.workspaces = data.rows || [];
  renderWorkspaceKpis(data.summary || {});
  renderWorkspaceList(state.workspaces);
  renderHoldingOrgChart();
  const targetedWorkspace = findWorkspaceRecord(
    state.workspaces,
    normalizeTenantWorkspaceSlug(state.currentWorkspaceTarget || "", "")
  );
  const selectedId =
    targetedWorkspace?.id
      || (state.workspaces.some((row) => String(row.id || "") === String(state.currentWorkspaceId || ""))
      ? state.currentWorkspaceId
      : (state.workspaces[0] && state.workspaces[0].id) || "");
	  if (selectedId) {
	    await loadWorkspaceDetail(selectedId);
	  } else {
	    clearCurrentWorkspaceUi();
	    {
	      const tenantMode = (state.currentWorkspaceEntryMode || "platform") === "tenant";
	      const view = state.currentWorkspaceView || "overview";
	      setWorkspaceView(view, { forceTenantView: tenantMode && normalizeSimple(view) !== "operations" });
	    }
	    renderCompanyCards();
	  }
	  updateWorkspaceEntryChrome();
	};

const renderHoldingOrgChart = () => {
  if (!holdingOrgChart) {
    return;
  }
  const selectedYear = yearSelect?.value;
  const companies = state.empresas.map((empresa) => empresa.nombre);
  const siblings = companies.filter((name) => name !== AIE_COMPANY);
  const aieMembers = siblings;
  const resumenMap = new Map(
    state.resumen.map((item) => [item.empresa, item])
  );
  const buildNode = (name, isAie) => {
    const item = resumenMap.get(name);
    const lines = item ? buildCompanyMeta(item, selectedYear) : [];
    const metaHtml = lines
      .map((line) => `<div class="muted">${line}</div>`)
      .join("");
    return `
      <div class="org-node${isAie ? " org-aie" : ""}" data-empresa="${name}">
        <h4>${name}</h4>
        ${metaHtml}
        ${isAie ? '<div class="muted">Subsidiaria AIE</div>' : ""}
        <button type="button">Entrar</button>
      </div>
    `;
  };
  const root = `
    <ul>
      <li>
        <div class="org-node">
          <h4>Inmovere Holding</h4>
          <div class="muted">Grupo principal</div>
        </div>
        <ul>
          ${siblings
            .filter((name) => name !== AIE_COMPANY)
            .map(
              (name) => `
            <li>
              ${buildNode(name, false)}
            </li>
          `
            )
            .join("")}
          <li class="org-aie-node">
            ${buildNode(AIE_COMPANY, true)}
            <div class="muted">Socias: ${aieMembers.join(" · ")}</div>
          </li>
        </ul>
      </li>
    </ul>
  `;
  holdingOrgChart.innerHTML = root;
  holdingOrgChart.querySelectorAll(".org-node button").forEach((btn) => {
    btn.addEventListener("click", (event) => {
      const node = event.currentTarget.closest(".org-node");
      if (!node) return;
      const name = node.dataset.empresa;
      if (name) {
        openCompany(name);
      }
    });
  });
};

const updateExplorerHeader = (empresaName) => {
  if (empresaName) {
    explorerTitle.textContent = `Explorador de datos · ${empresaName}`;
    explorerSubtitle.textContent = "Entrada de datos y revisión por módulo.";
  } else {
    explorerTitle.textContent = "Explorador de datos";
    explorerSubtitle.textContent = "Filtra por empresa, módulo y texto.";
  }
  const canInmo = userCanAccessService("inmobiliaria");
  const canGestoria = userCanAccessService("gestoria");
  const canFincas = userCanAccessService("fincas");
  const canSeguros = userCanAccessService("seguros");
  const canFin = userCanAccessService("financiaciones");
  updateCompanySummary(empresaName);
  if (aieTab) {
    aieTab.classList.toggle("hidden", empresaName !== AIE_COMPANY);
    if (empresaName !== AIE_COMPANY && currentTab === "aie") {
      setTab("operativa");
    }
  }
  if (operativaTab) {
    const hideOperativa =
      empresaName === FINCAS_COMPANY || empresaName === resolveCrmFinEmpresaNombre();
    operativaTab.classList.toggle("hidden", hideOperativa);
    if (empresaName === FINCAS_COMPANY && currentTab === "operativa") {
      setTab("gestoria-dash");
    }
    if (empresaName === resolveCrmFinEmpresaNombre() && currentTab === "operativa") {
      setTab("fin-crm");
    }
  }
  if (empresaName === FINCAS_COMPANY && currentTab === "alta") {
    state.gestoriaCrmView = "alta";
    setTab("gestoria-crm");
  }
  if (crmTab) {
    // Fase 1: el servicio manda (no la empresa actualmente abierta).
    // La empresa "interna" del servicio se resuelve al abrir el CRM (openCrmInmobiliario).
    crmTab.classList.toggle("hidden", !canInmo);
    if (!canInmo && currentTab === "crm") {
      setTab("operativa");
    }
  }
  if (fincasCrmTab) {
    fincasCrmTab.classList.toggle("hidden", !canGestoria);
    if (!canGestoria && currentTab === "gestoria-crm") setTab("operativa");
  }
  if (gestoriaDashTab) {
    // Dashboard Gestoría accesible a cualquier usuario con acceso a Gestoría.
    const canDash = canGestoria;
    gestoriaDashTab.classList.toggle("hidden", !canDash);
    if (!canDash && currentTab === "gestoria-dash") setTab("gestoria-crm");
  }
  if (gestoriaDocsTab) {
    gestoriaDocsTab.classList.toggle("hidden", !canGestoria);
    if (!canGestoria && currentTab === "gestoria-docs") setTab("operativa");
  }
  if (gestoriaAgendaTab) {
    gestoriaAgendaTab.classList.toggle("hidden", !canGestoria);
    if (!canGestoria && currentTab === "gestoria-agenda") setTab("operativa");
  }
  if (gestoriaFactTab) {
    const showFact = canGestoria || canFincas;
    gestoriaFactTab.classList.toggle("hidden", !showFact);
    if (!showFact && currentTab === "gestoria-fact") {
      setTab("gestoria-conta");
    }
  }
  if (gestoriaContaTab) {
    gestoriaContaTab.classList.toggle("hidden", !canGestoria);
    if (!canGestoria && currentTab === "gestoria-conta") setTab("operativa");
  }
  if (segurosCrmTab) {
    segurosCrmTab.classList.toggle("hidden", !canSeguros);
    if (!canSeguros && currentTab === "seguros-crm") setTab("operativa");
  }
  if (finCrmTab) {
    finCrmTab.classList.toggle("hidden", !canFin);
    if (!canFin && currentTab === "fin-crm") setTab("operativa");
  }
  if (finSimTab) {
    finSimTab.classList.toggle("hidden", !canFin);
    if (!canFin && currentTab === "fin-sim") setTab("operativa");
  }
  try {
    syncExplorerLightningSidebar();
  } catch (e) {}
};

const syncExplorerLightningSidebar = () => {
  if (!explorerLightningSidebar || !viewTabs) return;
  const current = String(currentTab || "").trim();
  explorerLightningSidebar.querySelectorAll("[data-explorer-tab]").forEach((btn) => {
    const key = String(btn.dataset.explorerTab || "").trim();
    if (!key) return;
    const tabBtn = viewTabs.querySelector(`.tab[data-tab=\"${key}\"]`);
    const unavailable =
      !tabBtn || tabBtn.classList.contains("hidden") || tabBtn.classList.contains("hidden-context");
    btn.classList.toggle("hidden", unavailable);
    btn.classList.toggle("active", key === current);
  });
  // La sidebar "Explorer" (verde) es solo para el Explorador (página empresa).
  // En contexto CRM vertical (Lightning shell), se oculta para evitar duplicidad de navegación y ganar espacio.
  const shouldHideExplorerSidebar =
    viewTabs.classList.contains("hidden") ||
    document.body.classList.contains("crm-context-vertical") ||
    (crmSection && !crmSection.classList.contains("hidden"));
  explorerLightningSidebar.classList.toggle("hidden", shouldHideExplorerSidebar);
};

const slugify = (value) =>
  String(value || "")
    .toLowerCase()
    .replace(/\./g, "")
    .replace(/\s+/g, "-")
    .replace(/[^a-z0-9-]/g, "");

const setUrlParams = (params, { replace = false } = {}) => {
  const url = new URL(window.location.href);
  // Guardarraíl tenant/workspace:
  // Si venimos de una URL con `holding=1&mode=tenant&workspace=...` no permitimos perder esos parámetros
  // al navegar dentro de la SPA (evita caer al "CRM general" y perder empresas del workspace).
  try {
    const prev = new URLSearchParams(url.search || "");
    const prevWorkspace = String(prev.get("workspace") || "").trim();
    const prevMode = String(prev.get("mode") || "").trim().toLowerCase();
    const prevHolding = String(prev.get("holding") || "").trim();
    if (prevHolding === "1" && prevMode === "tenant" && prevWorkspace) {
      if (!params.get("workspace")) params.set("workspace", prevWorkspace);
      if (!params.get("mode")) params.set("mode", "tenant");
      if (!params.get("holding")) params.set("holding", "1");
    }
  } catch (_e) {}
  url.search = params.toString();
  if (replace) {
    history.replaceState({}, "", url.toString());
  } else {
    history.pushState({}, "", url.toString());
  }
};

const setPage = (page) => {
  state.currentPage = page;
  // UI unificada: usamos siempre la identidad corporativa (misma base que CRM inmobiliario).
  document.body.classList.add("theme-operativa");
  document.body.classList.toggle("page-empresa", page !== "home");
  // Anti-mezcla: al salir del shell CRM vertical (Inmo/Seguros/Fin/Gestoría) hacia páginas transversales,
  // limpiamos el contexto CRM para que no “pegue” estilos (crm-context-vertical, etc.).
  if (page !== "empresa") {
    document.body.classList.remove(
      "crm-context-vertical",
      "crm-context-inmo",
      "crm-context-seguros",
      "crm-context-fin",
      "crm-context-gestoria"
    );
  }
  try {
    debugLog("setPage()", page);
  } catch (e) {}
  // Diagnóstico: si la URL pide un deep-link pero acabamos en Home, lo mostramos en UI (sin depender de consola).
  try {
    if (page === "home" && isDebugEnabled()) {
      const params = new URLSearchParams(window.location.search || "");
      const hasDeepLink = ["holding", "crm", "clientes", "cliente", "poliza", "empresa", "agenda", "admin", "portal_token", "portal_inmo", "firma_inmo"]
        .some((key) => params.has(key));
      if (hasDeepLink) {
        setUiToast("Routing: volvió a Home", `URL actual: ${window.location.href}`);
        debugLog("Routing: volvió a Home", `URL actual: ${window.location.href}`);
      }
    }
  } catch (e) {}
  if (homeSection) {
    homeSection.classList.toggle("hidden", page !== "home");
  }
  if (page === "home") {
    try {
      loadSegurosRenewalAlertForUser();
    } catch (e) {}
  }
  if (renewalAlert && page !== "home") {
    renewalAlert.classList.add("hidden");
  }
  if (segurosRenewalAlert && page !== "home") {
    segurosRenewalAlert.classList.add("hidden");
  }
  if (explorerSection) {
    explorerSection.classList.toggle("hidden", page !== "empresa");
  }
  if (holdingSection) {
    holdingSection.classList.toggle("hidden", page !== "holding");
  }
  if (agendaSection) {
    agendaSection.classList.toggle("hidden", page !== "agenda");
  }
  if (adminSection) {
    adminSection.classList.toggle("hidden", page !== "admin");
  }
  if (workspacePortalPublicSection) {
    workspacePortalPublicSection.classList.toggle("hidden", page !== "portal-public");
  }
  if (clientePage) {
    clientePage.classList.toggle("hidden", page !== "cliente");
  }
  if (seguroPage) {
    seguroPage.classList.toggle("hidden", page !== "seguro");
  }
  if (clientesDetail) {
    clientesDetail.classList.toggle("hidden", page !== "cliente");
  }
};

const openCompany = (empresaName, options = {}) => {
  const { allowRestricted = false } = options;
  if (!allowRestricted) {
    const user = getAuthScopeUser();
    if (!canAccessSharedHomeModules(user)) {
      const restrictedAccess = resolveRestrictedCompanyAccess(empresaName);
      if (restrictedAccess === "inmobiliaria") {
        openCrmInmobiliario();
        return;
      }
      if (restrictedAccess === "seguros") {
        openSegurosCrm();
        return;
      }
      if (restrictedAccess === "gestoria") {
        openGestoriaCrm();
        return;
      }
      if (restrictedAccess === "financiaciones") {
        openFinCrm();
        return;
      }
      goHome();
      return;
    }
  }
  setCrmMode("");
  if (isTenantWorkspaceMode()) {
    const companies = state.currentWorkspaceDetail?.companies || [];
    if (Array.isArray(companies) && companies.length) {
      state.empresas = companies;
      if (empresaSelect) {
        empresaSelect.innerHTML = "";
        empresaSelect.appendChild(createOption("", "Todas las empresas"));
        companies.forEach((item) => {
          empresaSelect.appendChild(createOption(item.id, item.nombre));
        });
      }
    }
  }
  const empresa = state.empresas.find((e) => e.nombre === empresaName);
  if (!empresa) {
    if (isTenantWorkspaceMode()) {
      // En modo tenant, la plataforma no puede depender de "empresa" para operar.
      // Evitamos bloquear el routing con un alert que aparece en cascada al navegar por servicios.
      return;
    }
    if (!state.empresas.length) {
      api("/api/empresas")
        .then((empresas) => {
          state.empresas = empresas;
          empresaSelect.innerHTML = "";
          empresaSelect.appendChild(createOption("", "Todas las empresas"));
          empresas.forEach((item) => {
            empresaSelect.appendChild(createOption(item.id, item.nombre));
          });
          openCompany(empresaName);
        })
        .catch(() => {
          alert("No se pudieron cargar las empresas. Revisa el servidor.");
        });
      return;
    }
    alert("Empresa no encontrada.");
    return;
  }
  if (homeSection) {
    homeSection.classList.add("hidden");
  }
  setModule("empresas");
  empresaSelect.value = empresa.id;
  state.currentEmpresaId = empresa.id;
  state.currentEmpresaName = empresa.nombre;
  const preferFinCrm = (() => {
    if (!userCanAccessService("financiaciones")) return false;
    const finEmpresa = resolveCrmFinEmpresa();
    return !!finEmpresa && String(finEmpresa.id) === String(empresa.id);
  })();
  if (preferFinCrm && !state.hipotecaAltaView) {
    state.hipotecaAltaView = "dashboard";
  }
  setTab(preferFinCrm ? "fin-crm" : "operativa");
  updateExplorerHeader(empresa.nombre);
  if (!preferFinCrm) {
    setDefaultTableForCompany(
      state.resumen.find((item) => item.empresa === empresaName)
    );
    ensureOperativaTable();
  }
  updateTableVisibility();
  explorerSection.classList.remove("hidden");
  if (preferFinCrm) {
    loadFinCrm();
  } else {
    loadTable();
  }
  setPage("empresa");
  setUrlParams(new URLSearchParams({ empresa: slugify(empresaName) }));
  if (currentTab === "crm") {
    loadCrmCaptaciones();
  }
  window.scrollTo({ top: 0, behavior: state.booting ? "auto" : "smooth" });
};

const openClientesModule = (opts = {}) => {
  const user = getAuthScopeUser();
  if (!canAccessSharedHomeModules(user)) {
    goHome();
    return;
  }
  const service = String(opts.service || "").trim().toLowerCase();
  const empresaId = String(opts.empresa_id || opts.empresaId || "").trim();
  state.clientesContextService = service;
  state.clientesContextEmpresaId = empresaId;
  if (homeSection) {
    homeSection.classList.add("hidden");
  }
  setModule("clientes");
  setPage("empresa");
  // Clientes es transversal: lo mostramos siempre en el layout estándar (no dentro de un CRM vertical).
  try {
    setTab("operativa");
  } catch (e) {}
  try {
    updateExplorerHeader("Clientes");
  } catch (e) {}
  if (explorerSection) {
    explorerSection.classList.remove("hidden");
  }
  try {
    updateTableVisibility();
  } catch (e) {}
  try {
    loadClientesTable();
  } catch (e) {}
  setUrlParams(new URLSearchParams({ clientes: "1" }));
};

const getClientesContextServiceParam = () => {
  if (state.currentModule === "clientes") {
    const svc = String(state.clientesContextService || "").trim();
    if (svc) return svc;
  }
  // Si estamos dentro de un CRM vertical, el maestro de clientes debe quedar acotado al servicio del vertical.
  // Evita que en Inmobiliaria aparezcan clientes de Seguros/Gestoría/etc.
  try {
    if (currentTab === "crm") return "inmobiliaria";
    if (currentTab === "seguros-crm") return "seguros";
    if (currentTab === "gestoria-crm" || currentTab === "gestoria-dash" || currentTab === "gestoria-docs" || currentTab === "gestoria-agenda" || currentTab === "gestoria-fact" || currentTab === "gestoria-conta") {
      return "gestoria";
    }
    if (currentTab === "fin-crm" || currentTab === "fin-sim") return "financiaciones";
    const crmParam = normalizeSimple(new URLSearchParams(window.location.search || "").get("crm") || "");
    if (crmParam === "inmo" || crmParam === "inmobiliaria") return "inmobiliaria";
    if (crmParam === "seguros") return "seguros";
    if (crmParam === "fin" || crmParam === "financiaciones" || crmParam === "hipotecas") return "financiaciones";
  } catch (e) {}
  return getServiceFilterParam();
};

const resolveEmpresaById = (empresaId) => {
  const id = String(empresaId || "").trim();
  if (!id) return null;
  const direct = state.empresas.find((e) => String(e.id || "").trim() === id) || null;
  if (direct) return direct;
  // Compat fase 6: si `state.empresas` contiene `workspace_companies` (v2),
  // permitimos resolver también por `legacy_empresa_id`.
  const legacy = state.empresas.find((e) => String(e.legacy_empresa_id || "").trim() === id) || null;
  return legacy || null;
};

// En modo tenant/v2, `empresa.id` puede ser el id de `workspace_companies` y no el legacy `empresas.id`.
// Para endpoints legacy que esperan `empresa_id`, usamos siempre el id legacy si está disponible.
const resolveLegacyEmpresaId = (empresa) =>
  String((empresa && (empresa.legacy_empresa_id || empresa.id)) || "").trim();

const SERVICE_COMPANY_STORAGE = {
  inmobiliaria: "crm.serviceCompany.inmobiliaria",
  seguros: "crm.serviceCompany.seguros",
  gestoria: "crm.serviceCompany.gestoria",
  financiaciones: "crm.serviceCompany.financiaciones",
};

const getWorkspaceIdForStorage = () => {
  try {
    if (!isTenantWorkspaceMode()) return "";
  } catch {
    return "";
  }
  try {
    const direct = String(state.currentWorkspaceId || "").trim();
    if (direct) return direct;
  } catch (e) {}
  try {
    const params = new URLSearchParams(window.location.search || "");
    const fromUrl = String(params.get("workspace") || "").trim();
    if (fromUrl) return fromUrl;
  } catch (e) {}
  try {
    const stored = String(localStorage.getItem("crm.currentWorkspaceId") || "").trim();
    return stored;
  } catch (e) {}
  return "";
};

const getServiceCompanyStorageKey = (serviceKey = "") => {
  const base = SERVICE_COMPANY_STORAGE[String(serviceKey || "").trim().toLowerCase()] || "";
  if (!base) return "";
  const wsId = getWorkspaceIdForStorage();
  if (!wsId) return base;
  // Evita fugas entre workspaces: separa selección de empresa por workspace.
  return `${base}.${wsId}`;
};

const getStoredServiceCompanyId = (serviceKey = "") => {
  const key = getServiceCompanyStorageKey(serviceKey);
  if (!key) return "";
  try {
    const scoped = String(localStorage.getItem(key) || "").trim();
    if (scoped) return scoped;
    // Migración suave: si venimos de modo global o de una versión sin scoping,
    // usamos el valor anterior SOLO si existe en el workspace actual.
    const legacyKey = SERVICE_COMPANY_STORAGE[String(serviceKey || "").trim().toLowerCase()] || "";
    if (!legacyKey) return "";
    const legacyValue = String(localStorage.getItem(legacyKey) || "").trim();
    if (!legacyValue) return "";
    try {
      if (!resolveEmpresaById(legacyValue)) return "";
    } catch (e) {
      return "";
    }
    try {
      localStorage.setItem(key, legacyValue);
    } catch (e) {}
    return legacyValue;
  } catch {
    return "";
  }
};

const setStoredServiceCompanyId = (serviceKey = "", empresaId = "") => {
  const key = getServiceCompanyStorageKey(serviceKey);
  if (!key) return;
  try {
    const id = String(empresaId || "").trim();
    if (!id) {
      localStorage.removeItem(key);
      return;
    }
    localStorage.setItem(key, id);
  } catch (e) {}
};

const getWorkspaceDefaultCompanyIdForServiceKey = (serviceKey = "") => {
  const key = normalizeWorkspaceServiceKey(serviceKey);
  if (!key) return "";
  const defaults = state.currentWorkspaceServiceCompanyDefaults || {};
  return String(defaults[key] || "").trim();
};

const resolveWorkspaceDefaultEmpresa = (serviceKey = "") => {
  const id = getWorkspaceDefaultCompanyIdForServiceKey(serviceKey);
  return id ? resolveEmpresaById(id) : null;
};

const resolveCrmInmoEmpresa = () => {
  // 1) Si ya hay empresa "Inmo" fijada (p.ej. usuario cambiando de ficha), úsala.
  const explicit = resolveEmpresaById(state.crmInmoEmpresaId);
  if (explicit) return explicit;

  const stored = resolveEmpresaById(getStoredServiceCompanyId("inmobiliaria"));
  if (stored) return stored;

  const fromMatrix = resolveWorkspaceDefaultEmpresa("inmobiliaria");
  if (fromMatrix) return fromMatrix;

  // 2) Fallback: intenta la empresa mapeada para el servicio; si no existe, usa la primera disponible.
  // Nota: NO usamos `state.currentEmpresaId` porque puede venir de otro servicio (Seguros/Hipotecas) y dejar el CRM Inmobiliaria vacío.
  const preferredName = SERVICE_COMPANY_MAP?.Inmobiliaria || DASHBOARD_COMPANY;
  const preferred = state.empresas.find((e) => e.nombre === preferredName) || null;
  if (preferred) return preferred;

  const modernia =
    state.empresas.find((e) => normalizeSimple(e.nombre).includes("modernia")) || null;
  if (modernia) return modernia;

  return state.empresas[0] || null;
};

const resolveCrmInmoEmpresaNombre = () => resolveCrmInmoEmpresa()?.nombre || "";
const resolveCrmInmoEmpresaId = () => resolveCrmInmoEmpresa()?.id || "";

const resolveCurrentInmuebleEmpresa = () => {
  const inmuebleEmpresaId = String(
    state.currentInmuebleContext?.inmueble?.empresa_id ||
      state.currentInmueble?.empresa_id ||
      ""
  ).trim();
  const matched = inmuebleEmpresaId ? resolveEmpresaById(inmuebleEmpresaId) : null;
  return matched || resolveCrmInmoEmpresa();
};

const resolveCurrentInmuebleEmpresaNombre = () =>
  resolveCurrentInmuebleEmpresa()?.nombre || resolveCrmInmoEmpresaNombre() || "";

// Compat: algunos flujos (Agenda/Acciones) esperan helpers "EmpresaId/EmpresaNombre".
const resolveCurrentInmuebleEmpresaId = () =>
  resolveCurrentInmuebleEmpresa()?.id || resolveCrmInmoEmpresaId() || "";

const resolveCrmSegurosEmpresaNombre = () => resolveCrmSegurosEmpresa()?.nombre || FINCAS_COMPANY;
const resolveCrmGestoriaEmpresaNombre = () => resolveCrmGestoriaEmpresa()?.nombre || FINCAS_COMPANY;
const resolveCrmFinEmpresaNombre = () => resolveCrmFinEmpresa()?.nombre || FIN_COMPANY;

const resolveCrmSegurosEmpresa = () => {
  const explicit = resolveEmpresaById(state.crmSegurosEmpresaId);
  if (explicit) return explicit;
  const stored = resolveEmpresaById(getStoredServiceCompanyId("seguros"));
  if (stored) return stored;
  const fromMatrix = resolveWorkspaceDefaultEmpresa("seguros");
  if (fromMatrix) return fromMatrix;
  const preferredName = SERVICE_COMPANY_MAP?.Seguros || FINCAS_COMPANY;
  const preferred = state.empresas.find((e) => e.nombre === preferredName) || null;
  if (preferred) return preferred;
  const fincas = state.empresas.find((e) => normalizeSimple(e.nombre).includes("fincas")) || null;
  if (fincas) return fincas;
  return state.empresas[0] || null;
};

const resolveCrmGestoriaEmpresa = () => {
  // En modo tenant, la "fuente de verdad" es la empresa activa del workspace (o su matriz de servicio),
  // nunca el fallback por nombre ("Fincas...") que pertenece al modo global.
  try {
    if (isTenantWorkspaceMode()) {
      const activeWsCompanyId = String(state.currentWorkspaceCompanyId || "").trim();
      if (activeWsCompanyId) {
        const active = resolveEmpresaById(activeWsCompanyId);
        if (active) return active;
      }
    }
  } catch (e) {}
  const explicit = resolveEmpresaById(state.crmGestoriaEmpresaId);
  if (explicit) return explicit;
  const stored = resolveEmpresaById(getStoredServiceCompanyId("gestoria"));
  if (stored) return stored;
  const fromMatrix = resolveWorkspaceDefaultEmpresa("gestoria");
  if (fromMatrix) return fromMatrix;
  const preferredName = SERVICE_COMPANY_MAP?.["Gestoría"] || FINCAS_COMPANY;
  const preferred = state.empresas.find((e) => e.nombre === preferredName) || null;
  if (preferred) return preferred;
  const fincas = state.empresas.find((e) => normalizeSimple(e.nombre).includes("fincas")) || null;
  if (fincas) return fincas;
  return state.empresas[0] || null;
};

const resolveCrmFinEmpresa = () => {
  const explicit = resolveEmpresaById(state.crmFinEmpresaId);
  if (explicit) return explicit;
  const stored = resolveEmpresaById(getStoredServiceCompanyId("financiaciones"));
  if (stored) return stored;
  const fromMatrix = resolveWorkspaceDefaultEmpresa("financiaciones");
  if (fromMatrix) return fromMatrix;
  const preferredName = SERVICE_COMPANY_MAP?.Hipotecas || FIN_COMPANY;
  const preferred = state.empresas.find((e) => e.nombre === preferredName) || null;
  if (preferred) return preferred;
  const fin = state.empresas.find((e) => normalizeSimple(e.nombre).includes("financi")) || null;
  if (fin) return fin;
  return state.empresas[0] || null;
};

const resolveEmpresaForServiceKey = (serviceKey = "") => {
  const key = normalizeSimple(String(serviceKey || ""));
  if (!key) return null;
  if (key === "seguros") return resolveCrmSegurosEmpresa();
  if (key === "gestoria" || key === "fincas" || key === "gestoria_fincas") return resolveCrmGestoriaEmpresa();
  if (key === "inmobiliaria" || key === "inmo") return resolveCrmInmoEmpresa();
  if (key === "financiaciones" || key === "hipotecas") return resolveCrmFinEmpresa();
  return resolveEmpresaById(state.currentEmpresaId);
};

const syncCrmInmoBrand = (empresaNombre = "") => {
  if (!crmBrandTitle || !crmBrandSubtitle) return;
  const company = String(empresaNombre || state.currentEmpresaName || "").trim();
  crmBrandTitle.textContent = company || "Inmobiliaria";
  crmBrandSubtitle.textContent = "CRM inmobiliario";
};

const resolveCrmTecnocloudVertical = () => {
  let crmContext = "";
  try {
    crmContext = normalizeSimple(new URLSearchParams(window.location.search || "").get("crm") || "");
  } catch {
    crmContext = "";
  }
  const tab = String(currentTab || "").trim();
  const isExplicitCrmTab =
    tab === "crm" || tab === "seguros-crm" || tab === "fin-crm" || tab === "fin-sim" || tab.startsWith("gestoria");
  // Evita que el "contexto CRM" se quede pegado en pantallas transversales (Clientes, Admin, Holding, etc.).
  if (!crmContext && !isExplicitCrmTab) return "";
  // Tab explícito tiene prioridad sobre querystring (evita "mezclas" por URLs antiguas).
  if (tab === "seguros-crm") return "seguros";
  if (tab === "fin-crm" || tab === "fin-sim") return "fin";
  if (tab === "crm") {
    // Si la URL fuerza vertical (`?crm=inmo|fin|seguros|gestoria`) debe tener prioridad incluso
    // cuando `state.crmWorkspaceView` venga persistido de otra sesión/vertical.
    if (crmContext === "gestoria") return "gestoria";
    if (crmContext === "seguros") return "seguros";
    if (crmContext === "fin" || crmContext === "financiaciones" || crmContext === "hipotecas") return "fin";
    if (crmContext === "inmo" || crmContext === "inmobiliaria") return "inmo";
    const view = String(state.crmWorkspaceView || "").trim();
    if (view === "fin") return "fin";
    if (view === "seguros") return "seguros";
    if (view === "gestoria") return "gestoria";
    return "inmo";
  }
  if (tab.startsWith("gestoria")) return "gestoria";
  if (crmContext === "gestoria") return "gestoria";
  if (crmContext === "seguros") return "seguros";
  if (crmContext === "fin" || crmContext === "financiaciones" || crmContext === "hipotecas") return "fin";
  if (crmContext === "inmo" || crmContext === "inmobiliaria") return "inmo";
  return "inmo";
};

const syncCrmInsertOptionsForVertical = (vertical = "") => {
  if (!crmInsertList) return;
  const v = String(vertical || "").trim();
  const allowed = new Set();
  if (v === "fin") {
    ["actividad", "cliente", "hipoteca"].forEach((k) => allowed.add(k));
  } else if (v === "seguros") {
    ["actividad", "cliente"].forEach((k) => allowed.add(k));
  } else if (v === "gestoria") {
    ["actividad", "cliente", "presupuesto", "renta"].forEach((k) => allowed.add(k));
  } else {
    ["actividad", "cliente", "captacion", "demanda", "edificio"].forEach((k) => allowed.add(k));
  }
  crmInsertList.querySelectorAll("button[data-crm-insert]").forEach((btn) => {
    const key = String(btn.dataset.crmInsert || "").trim();
    if (!key) return;
    btn.classList.toggle("hidden-context", !allowed.has(key));
  });
};

const syncCrmTecnocloudVerticalNav = () => {
  const vertical = resolveCrmTecnocloudVertical();
  const isGestoria = vertical === "gestoria";
  const isInmo = vertical === "inmo";
  const isFin = vertical === "fin";
  // Hardening: si la URL fuerza `?crm=inmo`, nunca ocultes las vistas base de Inmobiliaria.
  // (En algunos arranques/headless el contexto puede tardar y acabar marcando hidden-context
  // en botones críticos como Agenda.)
  let forcedCrm = "";
  try {
    forcedCrm = String(new URLSearchParams(window.location.search || "").get("crm") || "").trim().toLowerCase();
  } catch (e) {
    forcedCrm = "";
  }
  const allowedViews =
    vertical === "seguros"
      ? new Set(["seguros"])
      : vertical === "fin"
        ? new Set(["fin"])
        : vertical === "gestoria"
          ? new Set([]) // En Gestoría usamos tabs de servicio (no `data-crm-view`).
          : new Set([
              "resumen",
              "clientes",
	              "dashboard",
              "captaciones",
              "inmuebles",
              "mapa_inmuebles",
              "alquileres",
              "compraventas",
              "demandas",
              "relaciones",
              "visitas",
              "agenda",
              "informadores",
              "edificios",
              "legal",
            ]);
	  if (forcedCrm === "inmo" || forcedCrm === "inmobiliaria") {
	    ["resumen", "dashboard", "captaciones", "inmuebles", "clientes", "agenda", "visitas", "demandas", "relaciones"].forEach((k) =>
	      allowedViews.add(k)
	    );
	  }

  const applyToRoot = (root) => {
    if (!root) return;
    root.querySelectorAll("[data-crm-view]").forEach((btn) => {
      const key = String(btn.dataset.crmView || "").trim();
      if (!key) return;
      // Hard guarantee: en contexto `?crm=inmo` Agenda nunca debe quedar oculta.
      if ((forcedCrm === "inmo" || forcedCrm === "inmobiliaria") && key === "agenda") {
        btn.classList.remove("hidden-context");
        return;
      }
      btn.classList.toggle("hidden-context", !allowedViews.has(key));
    });
  };

  applyToRoot(crmWorkspaceTabs);
  applyToRoot(crmLightningSidebar);

  try {
    if (crmLightningSidebar) {
      crmLightningSidebar.querySelectorAll(".crm-side-inmo-only").forEach((node) => {
        node.classList.toggle("hidden", vertical !== "inmo");
      });
    }
  } catch (e) {}

  // Sidebar Gestoría: reutiliza el patrón "Lightning" pero navega por tabs propios (gestoria-*)
  // en lugar de views (data-crm-view). Se muestra solo en contexto Gestoría.
  try {
    if (crmLightningSidebar) {
      crmLightningSidebar.querySelectorAll(".crm-side-gestoria").forEach((node) => {
        node.classList.toggle("hidden", !isGestoria);
      });
      crmLightningSidebar.querySelectorAll('[data-crm-service-tab].crm-side-gestoria').forEach((btn) => {
        btn.classList.toggle("active", isGestoria && String(btn.dataset.crmServiceTab || "") === String(currentTab || ""));
      });
    }
  } catch (e) {}

  // Sidebar Financiaciones: accesos operativos (Dash/Listado/Agenda/Más)
  try {
    if (crmLightningSidebar) {
      crmLightningSidebar.querySelectorAll(".crm-side-fin").forEach((node) => {
        node.classList.toggle("hidden", !isFin);
      });
      crmLightningSidebar.querySelectorAll(".crm-side-fin-launcher").forEach((node) => {
        node.classList.toggle("hidden", isFin);
      });
      crmLightningSidebar.querySelectorAll('.crm-side-item.crm-side-fin[data-hipoteca-section]').forEach((btn) => {
        const desired = String(state.hipotecaAltaView || "dashboard");
        const current = desired === "alta" ? "bdt" : desired;
        btn.classList.toggle("active", isFin && String(btn.dataset.hipotecaSection || "") === current);
      });
    }
  } catch (e) {}

  // No mezclar pantallas: Gestoría NO debe mostrar el workspace del CRM Inmobiliaria.
  // Reutilizamos el estilo (topbar / módulos). La vista activa la decide `setCrmWorkspaceView`.
  if (crmWorkspaceShell) {
    const showFicha = isInmo && String(state.crmWorkspaceView || "") === "inmueble_ficha";
    // En vista ficha, ocultamos el shell/listados siempre.
    crmWorkspaceShell.classList.toggle("hidden", showFicha ? true : false);
  }
  if (crmLightningSidebar) {
    // Sidebar estilo "Lightning" en Inmobiliaria, Gestoría y Financiaciones.
    crmLightningSidebar.classList.toggle("hidden", !(isInmo || isGestoria || vertical === "fin" || vertical === "seguros"));
  }
  if (typeof inmuebleDetail !== "undefined" && inmuebleDetail) {
    // No mezclar pantallas: el detalle de inmueble solo debe verse en la vista dedicada.
    const showFicha = isInmo && String(state.crmWorkspaceView || "") === "inmueble_ficha";
    inmuebleDetail.classList.toggle("hidden", !showFicha);
  }

	  // Topbar: alterna módulos Inmobiliaria vs Gestoría.
	  try {
	    const inmoModules = document.getElementById("crmTopModules");
	    const gestoriaModules = document.getElementById("crmTopGestoriaModules");
	    const finModules = document.getElementById("crmTopFinModules");
	    const viewportW = window.innerWidth || document.documentElement.clientWidth || 0;
	    const isNarrow = viewportW > 0 && viewportW <= 820;
	    if (inmoModules) inmoModules.classList.toggle("hidden", vertical === "gestoria" || vertical === "fin");
	    // En escritorio, la navegación principal va en la barra lateral; no duplicar con módulos en topbar.
	    if (gestoriaModules) gestoriaModules.classList.toggle("hidden", vertical !== "gestoria" || !isNarrow);
	    // En Financiaciones, la navegación vive en el sidebar (no duplicar en topbar).
	    if (finModules) finModules.classList.toggle("hidden", true);
	    if (gestoriaModules) {
	      gestoriaModules.querySelectorAll("[data-crm-service-tab]").forEach((btn) => {
	        btn.classList.toggle("active", String(btn.dataset.crmServiceTab || "") === String(currentTab || ""));
	      });
	    }
	  } catch (e) {}

  // Financiaciones: usar módulos "card" en topbar, no micro-tabs internos.
  try {
    if (hipotecaTabs) hipotecaTabs.classList.toggle("hidden", vertical === "fin");
  } catch (e) {}

  const showInmoChrome = vertical === "inmo" || vertical === "gestoria" || vertical === "fin" || vertical === "seguros";
  const showInmoRecents = vertical === "inmo";
  const viewportW = window.innerWidth || document.documentElement.clientWidth || 0;
  const isNarrow = viewportW > 0 && viewportW <= 820;
  // Evitar duplicidad: solo un punto de entrada para "+ Nuevo".
  if (crmTopNewBtn) crmTopNewBtn.classList.toggle("hidden", !showInmoChrome || isNarrow);
  if (crmQuickNewBtn) crmQuickNewBtn.classList.toggle("hidden", !showInmoChrome || !isNarrow);
  if (crmRecentBtn) crmRecentBtn.classList.toggle("hidden", !showInmoRecents);
  if (!showInmoChrome) {
    setCrmQuickNewOpen(false);
    setCrmRecentOpen(false);
  }
  if (!showInmoRecents) {
    setCrmRecentOpen(false);
  }
  syncCrmInsertOptionsForVertical(vertical);

  if (crmBrandTitle && crmBrandSubtitle) {
    const company = String(state.currentEmpresaName || "").trim();
    if (vertical === "seguros") {
      crmBrandTitle.textContent = company || "Seguros";
      crmBrandSubtitle.textContent = "CRM seguros";
    } else if (vertical === "fin") {
      crmBrandTitle.textContent = company || "Financiaciones";
      crmBrandSubtitle.textContent = "CRM financiaciones";
    } else if (vertical === "gestoria") {
      crmBrandTitle.textContent = company || "Gestoría";
      crmBrandSubtitle.textContent = "CRM gestoría";
    } else {
      syncCrmInmoBrand(company);
    }
  }
};

// Algunos arranques (especialmente en headless / deep-links) pueden renderizar la sidebar antes de que
// se ejecute `updateTableVisibility()`/`syncCrmTecnocloudVerticalNav()`, dejando botones con `hidden-context`
// aunque el usuario haya forzado `?crm=inmo`. Esto rompe navegación (Agenda) y tests E2E.
const ensureCrmForcedInmoNavVisibility = () => {
  let forced = "";
  try {
    forced = String(new URLSearchParams(window.location.search || "").get("crm") || "").trim().toLowerCase();
  } catch (e) {
    forced = "";
  }
  if (!(forced === "inmo" || forced === "inmobiliaria")) return false;

  const unhide = (root) => {
    if (!root) return;
    ["resumen", "captaciones", "inmuebles", "clientes", "agenda", "visitas", "demandas", "relaciones"].forEach(
      (key) => {
        root.querySelectorAll(`[data-crm-view="${key}"]`).forEach((btn) => btn.classList.remove("hidden-context"));
      }
    );
  };
  unhide(crmWorkspaceTabs);
  unhide(crmLightningSidebar);
  return true;
};

try {
  if (ensureCrmForcedInmoNavVisibility()) {
    window.requestAnimationFrame(() => {
      try {
        ensureCrmForcedInmoNavVisibility();
      } catch (e) {}
    });
    if (crmLightningSidebar && typeof MutationObserver !== "undefined") {
      const obs = new MutationObserver(() => {
        try {
          ensureCrmForcedInmoNavVisibility();
        } catch (e) {}
        try {
          const agendaBtn = crmLightningSidebar.querySelector('[data-crm-view="agenda"]');
          if (agendaBtn && !agendaBtn.classList.contains("hidden-context")) {
            obs.disconnect();
          }
        } catch (e) {}
      });
      obs.observe(crmLightningSidebar, { childList: true, subtree: true, attributes: true, attributeFilter: ["class"] });
      window.setTimeout(() => {
        try {
          obs.disconnect();
        } catch (e) {}
      }, 60000);
    }
  }
} catch (e) {}

const openCrmInmobiliario = () => {
  try {
    closeHomeTimePunchModal({ persist: false });
  } catch (e) {}
  const fromHome = state.currentPage === "home";
  const hadRouteParams = (() => {
    try {
      const params = new URLSearchParams(window.location.search);
      return (
        params.has("crm")
        || params.has("empresa")
        || params.has("clientes")
        || params.has("cliente")
        || params.has("poliza")
        || params.has("holding")
        || params.has("admin")
        || params.has("agenda")
        || params.has("portal_token")
      );
    } catch {
      return false;
    }
  })();
  if (!userCanAccessService("inmobiliaria")) return;
  // Necesario para selects (Responsable/Asesor) dentro del CRM Inmobiliaria.
  if (!state.usersList || !state.usersList.length) {
    loadUsuarios().catch(() => {});
  }
  if (isTenantWorkspaceMode()) {
    const companies =
      (state.currentWorkspaceDetail?.companies_v2 || state.currentWorkspaceDetail?.companies) || [];
    if (Array.isArray(companies) && companies.length) {
      state.empresas = companies;
      if (empresaSelect) {
        empresaSelect.innerHTML = "";
        empresaSelect.appendChild(createOption("", "Todas las empresas"));
        companies.forEach((item) => {
          empresaSelect.appendChild(createOption(item.id, item.nombre));
        });
      }
    }
  }
  if (!state.empresas.length) {
    api("/api/empresas")
      .then((empresas) => {
        state.empresas = Array.isArray(empresas) ? empresas : [];
        openCrmInmobiliario();
      })
      .catch(() => {
        alert("No se pudieron cargar las empresas. Revisa el servidor.");
      });
    return;
  }
  const empresa = resolveCrmInmoEmpresa();
  if (!empresa && !isTenantWorkspaceMode()) {
    alert("No hay empresas disponibles para abrir el CRM inmobiliario.");
    return;
  }
  if (!isTenantWorkspaceMode() && empresa) {
    // Asegura contexto de empresa (necesario para endpoints legacy que requieren empresa_nombre).
    openCompany(empresa.nombre, { allowRestricted: true });
  } else {
    // Tenant: abrir CRM sin depender de empresa.
    try {
      if (homeSection) homeSection.classList.add("hidden");
      if (explorerSection) explorerSection.classList.remove("hidden");
      setModule("empresas");
      setPage("empresa");
    } catch (e) {}
  }
  syncCrmInmoBrand(empresa?.nombre || "");
  state.crmInmoEmpresaId = empresa?.id || "";
  setStoredServiceCompanyId("inmobiliaria", empresa?.id || "");
  setTab("crm");
  updateTableVisibility();
  syncCrmLegalAvailability();
  setCrmWorkspaceView(state.crmWorkspaceView || "resumen");
  // Evita lanzar 3 requests grandes a la vez (Render/PG puede estar frío).
  loadCrmCaptaciones();
  window.setTimeout(() => loadCrmInmuebles(), 120);
  window.setTimeout(() => loadCrmCompraventas(), 240);
  // Mantener URL "crm=inmo" para que los deep-links funcionen aunque `openCompany` haya puesto `?empresa=...`.
  const currentParams = new URLSearchParams(window.location.search);
  ensureTenantParams(currentParams);
  currentParams.delete("empresa");
  currentParams.delete("clientes");
  currentParams.delete("cliente");
  currentParams.delete("poliza");
  currentParams.set("crm", "inmo");
  setUrlParams(currentParams);
  // Asegura navegación base visible incluso si la URL venía sin `crm=inmo` (openCompany puede haberla sobrescrito).
  try {
    ensureCrmForcedInmoNavVisibility();
    window.setTimeout(() => {
      try {
        ensureCrmForcedInmoNavVisibility();
      } catch (e) {}
    }, 0);
  } catch (e) {}
  // UX admin: si llega desde Home (sin ruta explícita), no persistimos un deep-link que haga
  // que un hard refresh "arranque" dentro del CRM en vez de mostrar la Home.
  try {
    const user = getAuthScopeUser();
    if (fromHome && !hadRouteParams && user && isPrivilegedUser(user)) {
      setUrlParams(new URLSearchParams(), { replace: true });
    }
  } catch (e) {}
};

const ensureCrmOpen = (action) => {
  if (crmWorkspaceShell && !crmWorkspaceShell.classList.contains("hidden")) {
    action();
    return;
  }
  openCrmInmobiliario();
  setTimeout(action, 360);
};

const getCrmSearchTargetForView = (view = "") => {
  const nextView = String(view || "").trim();
  if (nextView === "clientes") return crmClientesSearch;
  if (nextView === "inmuebles") return crmInmuebleSearchMirror;
  if (nextView === "mapa_inmuebles") return crmMapaInmueblesSearch;
  if (nextView === "alquileres") return crmAlquilerSearch;
  if (nextView === "compraventas") return crmCompraventaSearch;
  if (nextView === "demandas") return crmDemandaSearch;
  if (nextView === "relaciones") return crmRelacionesSearch;
  if (nextView === "visitas") return crmVisitaSearch;
  if (nextView === "agenda") return crmAgendaSearch;
  if (nextView === "informadores") return crmInformadoresSearch;
  if (nextView === "edificios") return crmEdificiosSearch;
  if (nextView === "seguros") return segurosCrmSearch;
  if (nextView === "fin") return finAsesoramientosSearch;
  return null;
};

const syncCrmGlobalSearchUi = (view = "") => {
  if (!crmGlobalSearch) return;
  const current = String(state.crmGlobalSearch || "");
  if (crmGlobalSearch.value !== current) {
    crmGlobalSearch.value = current;
  }
  const target = getCrmSearchTargetForView(view);
  const placeholder = String(target?.getAttribute?.("placeholder") || "").trim();
  crmGlobalSearch.placeholder = placeholder || (String(view || "").trim() ? "Buscar en la lista..." : "Buscar...");
};

const syncCrmGlobalSearchTargetValue = (view = "") => {
  const target = getCrmSearchTargetForView(view);
  if (!target) return;
  const q = String(state.crmGlobalSearch || "");
  if (target.value !== q) {
    target.value = q;
  }
};

const applyCrmGlobalSearchToCurrentView = () => {
  const view = String(state.crmWorkspaceView || "resumen").trim() || "resumen";
  syncCrmGlobalSearchTargetValue(view);
  if (view === "captaciones") {
    loadCrmCaptaciones();
  } else if (view === "clientes") {
    loadCrmClientes();
  } else if (view === "inmuebles") {
    loadCrmInmuebles();
  } else if (view === "alquileres") {
    loadCrmAlquileres();
  } else if (view === "compraventas") {
    loadCrmCompraventas();
  } else if (view === "demandas") {
    loadCrmDemandas();
  } else if (view === "visitas") {
    loadCrmVisitas();
  } else if (view === "agenda") {
    loadCrmAgenda();
  } else if (view === "informadores") {
    loadCrmInformadores();
  } else if (view === "edificios") {
    loadCrmEdificios();
  } else if (view === "seguros") {
    loadSegurosCrm();
  } else if (view === "fin") {
    loadFinCrm();
  }
};

const filterCrmInsertList = () => {
  if (!crmInsertList) return;
  const q = normalizeSimple(crmInsertSearch ? crmInsertSearch.value : "");
  crmInsertList.querySelectorAll("button[data-crm-insert]").forEach((btn) => {
    const label = normalizeSimple(btn.textContent || "");
    btn.classList.toggle("hidden", Boolean(q) && !label.includes(q));
  });
};

const positionCrmInsertModal = (anchorEl) => {
  if (!crmInsertModal || !anchorEl) return;
  const rect = anchorEl.getBoundingClientRect();
  const sidebarRect = crmLightningSidebar ? crmLightningSidebar.getBoundingClientRect() : null;
  const viewportW = window.innerWidth || document.documentElement.clientWidth || 0;
  const desiredWidth = Math.min(380, Math.max(280, Math.floor(viewportW - 32)));
  let left = rect.left + rect.width / 2 - desiredWidth / 2;
  const minLeft = sidebarRect ? Math.round(sidebarRect.right + 12) : 16;
  left = Math.max(minLeft, Math.min(left, viewportW - desiredWidth - 16));
  const top = Math.max(16, rect.bottom + 10);
  crmInsertModal.style.setProperty("--crm-insert-left", `${Math.round(left)}px`);
  crmInsertModal.style.setProperty("--crm-insert-top", `${Math.round(top)}px`);
  if (sidebarRect) {
    crmInsertModal.style.setProperty("--crm-sidebar-right", `${Math.round(sidebarRect.right)}px`);
  } else {
    crmInsertModal.style.removeProperty("--crm-sidebar-right");
  }
};

const syncCrmModalOpenState = () => {
  try {
    const open =
      (crmInsertModal &&
        !crmInsertModal.classList.contains("hidden") &&
        !crmInsertModal.classList.contains("crm-insert-modal--dropdown")) ||
      (crmClienteModal && !crmClienteModal.classList.contains("hidden")) ||
      (crmCaptacionModal && !crmCaptacionModal.classList.contains("hidden")) ||
      (actionModal && !actionModal.classList.contains("hidden"));
    document.body.classList.toggle("modal-open", Boolean(open));
  } catch (e) {}
};

const setCrmQuickNewOpen = (open = false, options = {}) => {
  if (!crmInsertModal) return;
  const next = Boolean(open);
  crmInsertModal.classList.toggle("hidden", !next);
  [crmQuickNewBtn, crmTopNewBtn].forEach((btn) => {
    if (!btn) return;
    btn.setAttribute("aria-expanded", next ? "true" : "false");
  });
			  if (next) {
			    try {
			      syncCrmInsertOptionsForVertical(resolveCrmTecnocloudVertical());
			    } catch (e) {}
			    const anchorEl = options && options.anchorEl ? options.anchorEl : null;
			    const viewportW = window.innerWidth || document.documentElement.clientWidth || 0;
			    const preferAnchored = viewportW >= 821; // iPad+ / escritorio: menú flotante, móvil: modal completo
			    const isAnchored = Boolean(anchorEl && preferAnchored);
			    crmInsertModal.classList.toggle("crm-insert-modal--anchored", isAnchored);
			    crmInsertModal.classList.remove("crm-insert-modal--dropdown");
			    if (isAnchored) {
			      crmInsertAnchorEl = anchorEl;
			      positionCrmInsertModal(anchorEl);
			    } else {
			      crmInsertAnchorEl = null;
			      crmInsertModal.style.removeProperty("--crm-insert-left");
			      crmInsertModal.style.removeProperty("--crm-insert-top");
			    }
		    setCrmRecentOpen(false);
		    setCrmClienteModalOpen(false);
		    setCrmCaptacionModalOpen(false);
		    if (crmInsertSearch) {
      crmInsertSearch.value = "";
      setTimeout(() => crmInsertSearch.focus(), 0);
    }
    filterCrmInsertList();
				  } else {
				    crmInsertAnchorEl = null;
				    crmInsertModal.classList.remove("crm-insert-modal--anchored");
				    crmInsertModal.classList.remove("crm-insert-modal--dropdown");
				    crmInsertModal.style.removeProperty("--crm-insert-left");
				    crmInsertModal.style.removeProperty("--crm-insert-top");
				    crmInsertModal.style.removeProperty("--crm-sidebar-right");
				  }
				  syncCrmModalOpenState();
				};

// --- Return-to-form drafts (avoid losing user input when opening other records) ---
const RETURN_DRAFT_CTX_KEY = "v2:return_draft_ctx";
const RETURN_DRAFT_PAYLOAD_KEY = "v2:return_draft_payload";

const setReturnDraft = (ctx = "", payload = {}, meta = {}) => {
  try {
    const safeCtx = String(ctx || "").trim();
    if (!safeCtx) return;
    sessionStorage.setItem(RETURN_DRAFT_CTX_KEY, safeCtx);
    sessionStorage.setItem(
      RETURN_DRAFT_PAYLOAD_KEY,
      JSON.stringify({
        ts: Date.now(),
        payload: payload && typeof payload === "object" ? payload : {},
        ...((meta && typeof meta === "object") ? meta : {}),
      })
    );
  } catch (e) {}
};

const peekReturnDraftCtx = () => {
  try {
    return String(sessionStorage.getItem(RETURN_DRAFT_CTX_KEY) || "").trim();
  } catch {
    return "";
  }
};

const consumeReturnDraft = (ctx = "") => {
  try {
    const expected = String(ctx || "").trim();
    const stored = String(sessionStorage.getItem(RETURN_DRAFT_CTX_KEY) || "").trim();
    if (!expected || stored !== expected) return null;
    const raw = sessionStorage.getItem(RETURN_DRAFT_PAYLOAD_KEY);
    sessionStorage.removeItem(RETURN_DRAFT_CTX_KEY);
    sessionStorage.removeItem(RETURN_DRAFT_PAYLOAD_KEY);
    if (!raw) return { payload: {} };
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === "object" ? parsed : { payload: {} };
  } catch {
    return null;
  }
};

const applyDraftToForm = (formEl, payload = {}) => {
  if (!formEl) return;
  const data = payload && typeof payload === "object" ? payload : {};
  try {
    Array.from(formEl.elements || []).forEach((el) => {
      if (!el || !el.name) return;
      if (!(el.name in data)) return;
      const value = data[el.name];
      if (el.type === "checkbox") {
        const key = String(value || "").trim().toLowerCase();
        el.checked = value === true || value === 1 || value === "1" || ["true", "yes", "si", "sí", "on"].includes(key);
        return;
      }
      if (el.tagName === "SELECT" && el.multiple) {
        const values = Array.isArray(value) ? value : String(value || "").split(",").map((v) => v.trim()).filter(Boolean);
        Array.from(el.options || []).forEach((opt) => {
          opt.selected = values.includes(String(opt.value || opt.textContent || "").trim());
        });
        return;
      }
      el.value = value === null || value === undefined ? "" : String(value);
    });
  } catch (e) {}
};

