const createCrmClienteQuick = async (payload = {}, opts = {}) => {
  const scope = resolveInmoScopeParams() || {};
  if (!scope.workspace_id && !scope.empresa_id && !isTenantWorkspaceMode()) {
    throw new Error("Sin empresa Inmobiliaria.");
  }
  const preferExisting = opts?.preferExisting !== false;
  const nombre = String(payload?.nombre || "").trim();
  if (!nombre) {
    throw new Error("Falta el nombre del cliente.");
  }
  const clientePayload = {
    id: randomId(),
    tipo_persona: "Física",
    nombre,
  };
	const nif = String(payload?.nif || payload?.dni || "").trim();
	const telefono = String(payload?.telefono || "").trim();
	const email = String(payload?.email || "").trim();
	const direccion = String(payload?.direccion || "").trim();
	const procedencia_canal = String(payload?.procedencia_canal || "").trim();
	const procedencia_user_id = String(payload?.procedencia_user_id || "").trim();
	const procedencia_cliente_id = String(payload?.procedencia_cliente_id || "").trim();
	const captado_por_user_id =
	  String(payload?.captado_por_user_id || "").trim() || procedencia_user_id;
	if (nif) clientePayload.nif = nif;
	if (telefono) clientePayload.telefono = telefono;
	if (email) clientePayload.email = email;
	if (direccion) clientePayload.direccion = direccion;
	if (procedencia_canal) clientePayload.procedencia_canal = procedencia_canal;
	if (procedencia_user_id) clientePayload.procedencia_user_id = procedencia_user_id;
	if (procedencia_cliente_id) clientePayload.procedencia_cliente_id = procedencia_cliente_id;
	if (captado_por_user_id) clientePayload.captado_por_user_id = captado_por_user_id;
  if (isTenantWorkspaceMode() && state.currentWorkspaceId) {
    clientePayload.workspace_id = state.currentWorkspaceId;
  }

  const response = await fetch("/api/clientes", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(clientePayload),
  });
  const data = await response.json().catch(() => ({}));
  let clienteId = "";
  if (data?.error) {
    if (response.status === 409 && (data?.code === "duplicate_cliente" || data?.id)) {
      if (preferExisting) {
        // En flujos automáticos (alta propietario), preferimos reutilizar el primero.
        clienteId = String(data.id || (Array.isArray(data?.matches) ? data.matches?.[0]?.id : "") || "").trim();
      } else {
        const err = new Error("Posible cliente duplicado. Revisa los candidatos y reutiliza el existente o ajusta los datos.");
        err.code = "duplicate_cliente";
        err.matches = Array.isArray(data?.matches) ? data.matches : [];
        throw err;
      }
    } else {
      throw new Error(data.error);
    }
  } else {
    clienteId = String(data?.id || clientePayload.id || "").trim();
  }
  if (!clienteId) {
    throw new Error("No se pudo crear el cliente.");
  }

		await postJsonWithDbRetry(
		  "/api/clientes_link",
		  {
		    cliente_id: clienteId,
		    ...(isTenantWorkspaceMode() && state.currentWorkspaceId ? { workspace_id: state.currentWorkspaceId } : { empresa_id: resolveLegacyEmpresaId(empresa) }),
		    servicio: "Inmobiliaria",
		    captado_por_user_id: captado_por_user_id || undefined,
		    procedencia_canal: procedencia_canal || undefined,
		    procedencia_cliente_id: procedencia_cliente_id || undefined,
		    estado: "Activo",
	    fecha_inicio: new Date().toISOString().slice(0, 10),
	  },
	  { retries: 2, delayMs: 140 }
	);

  return clienteId;
};

const createCrmCaptacionQuick = async (payload = {}) => {
  const empresaNombre = String(resolveCrmInmoEmpresaNombre?.() || state.currentWorkspaceCompanyName || DASHBOARD_COMPANY || "").trim();
  if (!empresaNombre && !isTenantWorkspaceMode()) {
    throw new Error("Sin empresa Inmobiliaria.");
  }
  const direccion = String(payload?.direccion || "").trim();
  if (!direccion) {
    throw new Error("Falta la dirección del inmueble.");
  }
  const body = {
    empresa_nombre: empresaNombre,
    etapa: "Inmueble",
    direccion,
  };
  if (isTenantWorkspaceMode()) {
    body.workspace_id = String(new URLSearchParams(window.location.search || "").get("workspace") || state.currentWorkspaceId || "").trim();
    body.workspace_company_id = String(state.currentWorkspaceCompanyWsId || "").trim();
  }
  [
    "poblacion",
    "provincia",
    "tipo_inmueble",
    "subtipologia",
    "referencia_catastral",
    "direccion_numero",
    "planta",
    "puerta",
    "codigo_postal",
    "propietario",
    "propietario_telefono",
    "necesidad_venta_alquiler",
  ].forEach((key) => {
    const value = String(payload?.[key] || "").trim();
    if (value) body[key] = value;
  });
  if (String(payload?.allow_duplicate || "").trim()) {
    body.allow_duplicate = "1";
  }

  const res = await fetch("/api/captaciones", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    credentials: "same-origin",
    body: JSON.stringify(body),
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok || data?.error) {
    if (res.status === 409 && data?.code === "duplicate_detected") {
      const err = new Error("Posible duplicado detectado. Abre la ficha existente para comprobarlo o marca “Permitir duplicado” si quieres forzar el alta.");
      err.code = "duplicate_detected";
      err.duplicates = Array.isArray(data?.duplicates) ? data.duplicates : [];
      throw err;
    }
    throw new Error(data?.error || "No se pudo crear el inmueble.");
  }
  const captacionId = String(data?.id || "").trim();
  const inmuebleId = String(data?.inmueble_id || "").trim();
  if (!inmuebleId) {
    throw new Error("El inmueble se creó sin id.");
  }
  return { captacionId, inmuebleId };
};

