const TC_AZ_LETTERS = "ABCDEFGHIJKLMNOPQRSTUVWXYZ".split("");
const isTcAzOther = (value) => String(value || "").trim().toUpperCase() === "OTROS";

const renderTcAzBar = (container, scope, onChange) => {
  if (!container) return;
  const current = String(state.crmAz?.[scope] || "").trim().toUpperCase();
  const mkSep = () => {
    const sep = document.createElement("span");
    sep.className = "tc-az-sep";
    sep.textContent = "|";
    sep.setAttribute("aria-hidden", "true");
    return sep;
  };
  const mkBtn = (label, value) => {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.textContent = label;
    btn.dataset.azValue = String(value || "");
    btn.classList.toggle("active", String(current || "") === String(value || ""));
    btn.addEventListener("click", () => {
      const next = String(value || "").trim().toUpperCase();
      if (!state.crmAz) state.crmAz = {};
      state.crmAz[scope] = next;
      saveCrmAzValue(scope, next);
      renderTcAzBar(container, scope, onChange);
      if (typeof onChange === "function") onChange(next);
    });
    return btn;
  };
  container.innerHTML = "";
  TC_AZ_LETTERS.forEach((letter) => container.appendChild(mkBtn(letter, letter)));
  container.appendChild(mkSep());
  container.appendChild(mkBtn("OTROS", "OTROS"));
  container.appendChild(mkBtn("TODO", ""));
};

const matchTcAz = (az, raw) => {
  const value = normalizeSimple(raw || "");
  const first = value ? value.slice(0, 1).toUpperCase() : "";
  const key = String(az || "").trim().toUpperCase();
  if (!key) return true;
  if (isTcAzOther(key)) return !first || !TC_AZ_LETTERS.includes(first);
  return first === key;
};

	let crmAzCompanyKey = "";
	const syncCrmTecnocloudChrome = () => {
	  const empresaId = String(state.crmInmoEmpresaId || "").trim();
	  if (empresaId && crmAzCompanyKey !== empresaId) {
	    crmAzCompanyKey = empresaId;
	    if (!state.crmAz) state.crmAz = {};
	    ["clientes", "inmuebles", "captaciones", "demandas", "agenda", "relaciones"].forEach((scope) => {
	      state.crmAz[scope] = loadCrmAzValue(scope);
	    });
	  }
	  renderTcAzBar(crmClientesAz, "clientes", () => loadCrmClientes());
	  renderTcAzBar(crmInmueblesAz, "inmuebles", () => loadCrmInmuebles());
	  renderTcAzBar(crmDemandasAz, "demandas", () => loadCrmDemandas());
	  renderTcAzBar(crmAgendaAz, "agenda", () => loadCrmAgenda());
	  renderTcAzBar(crmRelacionesAz, "relaciones", () => loadCrmRelacionesCruce());
	};

const loadCrmRecentItems = () => {
  try {
    const raw = localStorage.getItem(getCrmRecentStorageKey());
    const parsed = raw ? JSON.parse(raw) : [];
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
};

const saveCrmRecentItems = (items = []) => {
  try {
    const trimmed = Array.isArray(items) ? items.slice(0, 10) : [];
    localStorage.setItem(getCrmRecentStorageKey(), JSON.stringify(trimmed));
  } catch (e) {}
};

const pushCrmRecentItem = (item = {}) => {
  const next = {
    kind: String(item.kind || "").trim() || "inmueble",
    id: String(item.id || "").trim(),
    title: String(item.title || "").trim(),
    meta: String(item.meta || "").trim(),
    view: String(item.view || "").trim(),
    inmuebleId: String(item.inmuebleId || "").trim(),
    ts: Number(item.ts || Date.now()) || Date.now(),
  };
  if (!next.id && !next.inmuebleId) return;
  const items = loadCrmRecentItems();
  const signature = `${next.kind}:${next.id || next.inmuebleId}`;
  const filtered = items.filter((row) => `${row?.kind || ""}:${row?.id || row?.inmuebleId || ""}` !== signature);
  filtered.unshift(next);
  saveCrmRecentItems(filtered);
  if (crmRecentMenu && !crmRecentMenu.classList.contains("hidden")) {
    renderCrmRecentMenu();
  }
};

const renderCrmRecentMenu = () => {
  if (!crmRecentList) return;
  const items = loadCrmRecentItems();
  crmRecentList.innerHTML = "";
  if (!items.length) {
    const p = document.createElement("p");
    p.className = "muted";
    p.textContent = "Sin elementos recientes.";
    crmRecentList.appendChild(p);
    return;
  }
  items.slice(0, 10).forEach((row) => {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "crm-recent-item";
    btn.dataset.crmRecentKind = String(row?.kind || "");
    if (row?.id) btn.dataset.crmRecentId = String(row.id);
    if (row?.inmuebleId) btn.dataset.crmRecentInmuebleId = String(row.inmuebleId);
    if (row?.view) btn.dataset.crmRecentView = String(row.view);
    const strong = document.createElement("strong");
    strong.textContent = row?.title || row?.id || row?.inmuebleId || "Elemento";
    btn.appendChild(strong);
    if (row?.meta) {
      const meta = document.createElement("div");
      meta.className = "muted";
      meta.textContent = row.meta;
      btn.appendChild(meta);
    }
    crmRecentList.appendChild(btn);
  });
};

const openCrmRecentItem = (row = {}) => {
  const kind = String(row.kind || "").trim();
  const view = String(row.view || "").trim();
  const id = String(row.id || "").trim();
  const inmuebleId = String(row.inmuebleId || "").trim();
  setCrmRecentOpen(false);
  setCrmGlobalSearchResultsOpen(false);
  ensureCrmOpen(() => {
    if (kind === "compraventa" && id) {
      openCompraventaEditor(id);
      return;
    }
    if (kind === "cliente" && id) {
      openClienteDetail(id);
      return;
    }
    if (kind === "demanda" && id) {
      setCrmWorkspaceView("demandas");
      openDemandaDetail(id);
      return;
    }
    if (kind === "visita" && inmuebleId) {
      setCrmWorkspaceView("visitas");
      openInmuebleDetail(inmuebleId, "visitas");
      return;
    }
    if (kind === "pipeline" && inmuebleId) {
      setCrmWorkspaceView("captaciones");
      openInmuebleDetail(inmuebleId, "captaciones");
      return;
    }
    const targetView = view || "inmuebles";
    if (inmuebleId) {
      setCrmWorkspaceView(targetView);
      openInmuebleDetail(inmuebleId, targetView);
    } else if (id) {
      // Fallback: si no sabemos abrirlo por detalle, filtramos en la vista.
      state.crmGlobalSearch = id;
      setCrmWorkspaceView(targetView);
      applyCrmGlobalSearchToCurrentView();
    }
  });
};

const setCrmGlobalSearchResultsOpen = (open = false) => {
  if (!crmGlobalSearchResults) return;
  crmGlobalSearchResults.classList.toggle("hidden", !open);
  if (crmGlobalSearch) {
    try {
      crmGlobalSearch.setAttribute("aria-expanded", open ? "true" : "false");
    } catch (e) {}
  }
  if (!open) {
    state.crmGlobalSearchActiveIdx = -1;
  }
};

const getCrmGlobalSearchItems = () => {
  if (!crmGlobalSearchResults) return [];
  return Array.from(crmGlobalSearchResults.querySelectorAll(".crm-global-item"));
};

const setCrmGlobalSearchActiveIndex = (index) => {
  const items = getCrmGlobalSearchItems();
  const max = items.length - 1;
  const next = Number.isFinite(index) ? index : -1;
  const bounded = next < 0 ? -1 : next > max ? max : next;
  state.crmGlobalSearchActiveIdx = bounded;
  items.forEach((item, idx) => {
    const isActive = idx === bounded;
    item.classList.toggle("active", isActive);
    item.setAttribute("aria-selected", isActive ? "true" : "false");
    if (isActive) {
      try { item.scrollIntoView({ block: "nearest" }); } catch (e) {}
    }
  });
  if (crmGlobalSearch) {
    const activeItem = bounded >= 0 ? items[bounded] : null;
    try {
      if (activeItem?.id) {
        crmGlobalSearch.setAttribute("aria-activedescendant", activeItem.id);
      } else {
        crmGlobalSearch.removeAttribute("aria-activedescendant");
      }
    } catch (e) {}
  }
};

const moveCrmGlobalSearchActive = (delta) => {
  const items = getCrmGlobalSearchItems();
  if (!items.length) return;
  const current = Number(state.crmGlobalSearchActiveIdx ?? -1);
  const next = current < 0
    ? (delta > 0 ? 0 : items.length - 1)
    : (current + delta + items.length) % items.length;
  setCrmGlobalSearchActiveIndex(next);
};

const setInmuebleTecnoPrintMenuOpen = (open = false) => {
  if (!inmuebleTecnoPrintMenu) return;
  inmuebleTecnoPrintMenu.classList.toggle("hidden", !open);
};

const renderCrmGlobalSearchResults = () => {
  if (!crmGlobalSearchResults) return;
  const raw = String(state.crmGlobalSearch || "").trim();
  const needle = normalizeSimple(raw);
  const activeIdx = Number(state.crmGlobalSearchActiveIdx ?? -1);
  let optionIdx = 0;

  const renderRecents = () => {
    const items = loadCrmRecentItems().slice(0, 5);
    crmGlobalSearchResults.innerHTML = "";
    if (!items.length) {
      const empty = document.createElement("div");
      empty.className = "muted";
      empty.style.padding = "8px 6px";
      empty.textContent = "Sin recientes.";
      crmGlobalSearchResults.appendChild(empty);
      setCrmGlobalSearchResultsOpen(true);
      setCrmGlobalSearchActiveIndex(-1);
      return;
    }
    const wrap = document.createElement("div");
    wrap.className = "crm-global-group";
    const title = document.createElement("div");
    title.className = "crm-global-group-title";
    title.textContent = "Recientes";
    wrap.appendChild(title);
    items.forEach((item) => {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "crm-global-item";
      btn.id = `crmGlobalOpt-${optionIdx++}`;
      btn.setAttribute("role", "option");
      btn.setAttribute("aria-selected", "false");
      btn.dataset.crmGlobalKind = String(item?.kind || "").trim();
      if (item?.view) btn.dataset.crmGlobalView = String(item.view);
      if (item?.id) btn.dataset.crmGlobalId = String(item.id);
      if (item?.inmuebleId) btn.dataset.crmGlobalInmuebleId = String(item.inmuebleId);
      const left = document.createElement("div");
      const strong = document.createElement("strong");
      strong.textContent = item?.title || item?.id || item?.inmuebleId || "Elemento";
      left.appendChild(strong);
      if (item?.meta) {
        const meta = document.createElement("div");
        meta.className = "muted";
        meta.textContent = String(item.meta);
        left.appendChild(meta);
      }
      btn.appendChild(left);
      const pill = document.createElement("span");
      pill.className = "crm-global-pill";
      pill.textContent = String(item?.kind || "").trim() || "Reciente";
      btn.appendChild(pill);
      wrap.appendChild(btn);
    });
    crmGlobalSearchResults.appendChild(wrap);
    setCrmGlobalSearchResultsOpen(true);
    setCrmGlobalSearchActiveIndex(activeIdx);
  };

  // Tecnocloud: al hacer click sin texto, muestra 5 recientes.
  if (!needle) {
    renderRecents();
    return;
  }
  if (needle.length < 1) {
    crmGlobalSearchResults.innerHTML = "";
    setCrmGlobalSearchResultsOpen(false);
    return;
  }

  const MAX_PER_GROUP = 6;
  const groups = [];
  const pushGroup = (title, items) => {
    const trimmed = Array.isArray(items) ? items.slice(0, MAX_PER_GROUP) : [];
    if (!trimmed.length) return;
    groups.push({ title, items: trimmed });
  };

  const matchIncludes = (value) => normalizeSimple(value).includes(needle);

  const inmuebles = (Array.isArray(cachedCrmInmuebles) ? cachedCrmInmuebles : []).filter((row) => {
    const hay = [row?.referencia, row?.direccion, row?.poblacion, row?.provincia, row?.propietarios, row?.propietario]
      .map((v) => String(v || ""))
      .join(" ");
    return matchIncludes(hay);
  });
  pushGroup(
    "Inmuebles",
    inmuebles.map((row) => ({
      kind: "inmueble",
      view: "inmuebles",
      inmuebleId: String(row?.id || "").trim(),
      title: row?.direccion || row?.referencia || "Inmueble",
      meta: [row?.referencia || "", row?.poblacion || "", row?.estado || ""].filter(Boolean).join(" · "),
      pill: "Inmueble",
    }))
  );

  const pipeline = (Array.isArray(cachedCrmCaptaciones) ? cachedCrmCaptaciones : []).filter((row) => {
    const hay = [row?.direccion, row?.propietario, row?.telefono, row?.email, row?.etapa].map((v) => String(v || "")).join(" ");
    return matchIncludes(hay);
  });
  pushGroup(
    "Pipeline",
    pipeline.map((row) => ({
      kind: "pipeline",
      view: "captaciones",
      inmuebleId: String(row?.inmueble_id || row?.id || "").trim(),
      title: row?.direccion || row?.propietario || "Expediente",
      meta: [row?.etapa || "", row?.proxima_accion || ""].filter(Boolean).join(" · "),
      pill: "Pipeline",
    }))
  );

  const demandas = (Array.isArray(cachedCrmDemandas) ? cachedCrmDemandas : []).filter((row) => {
    const hay = [row?.cliente, row?.tipo, row?.estado, row?.prioridad].map((v) => String(v || "")).join(" ");
    return matchIncludes(hay);
  });
  pushGroup(
    "Pedidos",
    demandas.map((row) => ({
      kind: "demanda",
      view: "demandas",
      id: String(row?.id || "").trim(),
      title: row?.cliente || "Pedido",
      meta: [row?.tipo || "", row?.estado || ""].filter(Boolean).join(" · "),
      pill: "Pedido",
    }))
  );

  const compraventas = (Array.isArray(cachedCrmCompraventas) ? cachedCrmCompraventas : []).filter((row) => {
    const hay = [row?.id, row?.direccion, row?.vendedor, row?.comprador, row?.estado].map((v) => String(v || "")).join(" ");
    return matchIncludes(hay);
  });
  pushGroup(
    "Compraventas",
    compraventas.map((row) => ({
      kind: "compraventa",
      id: String(row?.id || "").trim(),
      title: row?.direccion || `Compraventa ${String(row?.id || "").slice(0, 8)}`,
      meta: [row?.estado || "", row?.comprador || row?.vendedor || ""].filter(Boolean).join(" · "),
      pill: "Compraventa",
    }))
  );

  const visitas = (Array.isArray(cachedCrmVisitas) ? cachedCrmVisitas : []).filter((row) => {
    const hay = [row?.inmueble, row?.cliente, row?.asesor, row?.estado, row?.fecha].map((v) => String(v || "")).join(" ");
    return matchIncludes(hay);
  });
  pushGroup(
    "Visitas",
    visitas.map((row) => ({
      kind: "visita",
      view: "visitas",
      inmuebleId: String(row?.inmueble_id || "").trim(),
      title: row?.inmueble || "Visita",
      meta: [row?.fecha || "", row?.hora || "", row?.estado || ""].filter(Boolean).join(" · "),
      pill: "Visita",
    }))
  );

  crmGlobalSearchResults.innerHTML = "";
  if (!groups.length) {
    const empty = document.createElement("div");
    empty.className = "muted";
    empty.style.padding = "8px 6px";
    empty.textContent = "Sin resultados en datos cargados. Pulsa Enter para filtrar la vista actual.";
    crmGlobalSearchResults.appendChild(empty);
    setCrmGlobalSearchResultsOpen(true);
    setCrmGlobalSearchActiveIndex(-1);
    return;
  }

  groups.forEach((group) => {
    const wrap = document.createElement("div");
    wrap.className = "crm-global-group";
    const title = document.createElement("div");
    title.className = "crm-global-group-title";
    title.textContent = group.title;
    wrap.appendChild(title);
    group.items.forEach((item) => {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "crm-global-item";
      btn.id = `crmGlobalOpt-${optionIdx++}`;
      btn.setAttribute("role", "option");
      btn.setAttribute("aria-selected", "false");
      btn.dataset.crmGlobalKind = item.kind;
      if (item.view) btn.dataset.crmGlobalView = item.view;
      if (item.id) btn.dataset.crmGlobalId = item.id;
      if (item.inmuebleId) btn.dataset.crmGlobalInmuebleId = item.inmuebleId;
      const left = document.createElement("div");
      const strong = document.createElement("strong");
      strong.textContent = item.title || "Elemento";
      left.appendChild(strong);
      if (item.meta) {
        const meta = document.createElement("div");
        meta.className = "muted";
        meta.textContent = item.meta;
        left.appendChild(meta);
      }
      btn.appendChild(left);
      const pill = document.createElement("span");
      pill.className = "crm-global-pill";
      pill.textContent = item.pill || "";
      btn.appendChild(pill);
      wrap.appendChild(btn);
    });
    crmGlobalSearchResults.appendChild(wrap);
  });
  setCrmGlobalSearchResultsOpen(true);
  setCrmGlobalSearchActiveIndex(activeIdx);
};

const applyCrmTecnocloudQuickSearch = (token = "") => {
  const raw = String(token || "").trim();
  if (!raw) return;
  const [scope, ...rest] = raw.split(":");
  const value = rest.join(":");
  ensureCrmOpen(() => {
    if (scope === "captaciones") {
      if (crmCaptacionesQuickFilter) crmCaptacionesQuickFilter.value = value || "";
      setCrmWorkspaceView("captaciones");
      loadCrmCaptaciones();
      return;
	    }
		    if (scope === "demandas") {
		      const vRaw = String(value || "").trim();
		      const v = normalizeSimple(vRaw);
		      const isOrigenQuick = v === "web" || v === "agencias";
		      const isDemandasStep =
		        v === "a_analizar"
		        || v === "en_gestion"
		        || v === "en_visita"
		        || v === "negociacion"
		        || v === "otras";

		      // Steps (Tecnocloud).
		      if (isDemandasStep) {
		        state.crmDemandasStep = v;
		        try { localStorage.setItem("crm.demandas.step", v); } catch (e) {}
		        if (crmDemandaEstadoFilter) crmDemandaEstadoFilter.value = "activa";
		        if (crmDemandaOrigenFilter) crmDemandaOrigenFilter.value = "";
		        if (crmDemandaSearch) crmDemandaSearch.value = "";
		        setCrmWorkspaceView("demandas");
		        loadCrmDemandas();
		        return;
		      }

		      // Atajos por origen.
		      if (isOrigenQuick) {
		        if (crmDemandaOrigenFilter) crmDemandaOrigenFilter.value = v;
		        if (crmDemandaEstadoFilter) crmDemandaEstadoFilter.value = "activa";
		        state.crmDemandasStep = "otras";
		        try { localStorage.setItem("crm.demandas.step", "otras"); } catch (e) {}
		        if (crmDemandaSearch) crmDemandaSearch.value = "";
		        setCrmWorkspaceView("demandas");
		        loadCrmDemandas();
		        return;
		      }

		      // Prioridad alta.
		      if (v === "prioridad_alta" || (v === "prioridad" && normalizeSimple(rest[1] || "") === "alta")) {
		        if (crmDemandaOrigenFilter) crmDemandaOrigenFilter.value = "";
		        if (crmDemandaEstadoFilter) crmDemandaEstadoFilter.value = "activa";
		        state.crmDemandasStep = "otras";
		        try { localStorage.setItem("crm.demandas.step", "otras"); } catch (e) {}
		        if (crmDemandaSearch) crmDemandaSearch.value = "prioridad:alta";
		        setCrmWorkspaceView("demandas");
		        loadCrmDemandas();
		        return;
		      }

		      // Estado (incl. "activa"): para ver todas las fases, abrimos el paso "otras".
		      if (crmDemandaOrigenFilter) crmDemandaOrigenFilter.value = "";
		      if (crmDemandaEstadoFilter) crmDemandaEstadoFilter.value = vRaw || "";
		      if (v === "activa") {
		        state.crmDemandasStep = "otras";
		        try { localStorage.setItem("crm.demandas.step", "otras"); } catch (e) {}
		      }
		      if (crmDemandaSearch) crmDemandaSearch.value = "";
		      setCrmWorkspaceView("demandas");
		      loadCrmDemandas();
		      return;
		    }
		    if (scope === "clientes") {
	      if (crmClientesFilter) crmClientesFilter.value = value || "recientes";
	      setCrmWorkspaceView("clientes");
	      loadCrmClientes();
	      return;
	    }
    if (scope === "visitas") {
      if (crmVisitaEstadoFilter) crmVisitaEstadoFilter.value = value || "";
      setCrmWorkspaceView("visitas");
      loadCrmVisitas();
      return;
    }
    if (scope === "agenda") {
      if (crmAgendaEstadoFilter) crmAgendaEstadoFilter.value = value || "";
      setCrmAgendaView("list");
      setCrmWorkspaceView("agenda");
      loadCrmAgenda();
    }
  });
};

