const openServiceCrm = (service) => {
  if (!service) return;
  if (service === "Inmobiliaria") {
    openCrmInmobiliario();
    return;
  }
  if (service === "Administración Fincas" || service === "Fincas") {
    if (state.currentPage === "holding" && (state.currentWorkspaceEntryMode || "platform") === "tenant") {
      focusWorkspaceView("fincas", workspaceFincasCommunityForm, { scroll: true, forceTenantView: true });
      return;
    }
    openHolding({ mode: "tenant", workspace: resolveDefaultTenantWorkspaceSlug(), view: "fincas" });
    return;
  }
  if (service === "Gestoría") {
    openGestoriaCrm();
    return;
  }
  if (service === "Seguros") {
    openSegurosCrm();
    return;
  }
  if (service === "Hipotecas") {
    openFinCrm();
    return;
  }
  alert("CRM en preparación para " + service);
};

const setClienteTab = (tab) => {
  if (!clienteTabs) return;
  clienteTabs.querySelectorAll(".tab").forEach((btn) => {
    btn.classList.toggle("active", btn.dataset.tab === tab);
  });
  if (clienteLightningSidebar) {
    clienteLightningSidebar.querySelectorAll("[data-cliente-tab]").forEach((btn) => {
      btn.classList.toggle("active", String(btn.dataset.clienteTab || "") === String(tab || ""));
    });
  }
  const showExpediente = tab === "datos";
  const showConfig = tab === "profesional";
  const showServicios = tab === "servicios";
  if (clienteTabDatos) clienteTabDatos.classList.toggle("hidden", !showExpediente);
  if (clienteTabRelaciones) clienteTabRelaciones.classList.toggle("hidden", tab !== "relaciones");
  if (clienteTabEconomicos) clienteTabEconomicos.classList.toggle("hidden", tab !== "economicos");
  if (clienteTabDashboard) clienteTabDashboard.classList.toggle("hidden", tab !== "dashboard");
  if (clienteTabProfesional) clienteTabProfesional.classList.toggle("hidden", !showConfig);
  if (clienteTabOperativa) clienteTabOperativa.classList.toggle("hidden", !showServicios);
  if (clienteTabServicios) clienteTabServicios.classList.toggle("hidden", !showServicios);
  if (clienteTabDocs) clienteTabDocs.classList.toggle("hidden", tab !== "docs");
  if (clienteTabFacturas) clienteTabFacturas.classList.toggle("hidden", tab !== "facturas");
  if (clienteTabTrabajos) clienteTabTrabajos.classList.toggle("hidden", tab !== "trabajos");
  if (showServicios) {
    setClienteOperativaTab(state.clienteOperativaTab || "gestoria");
  }
  if (tab === "docs") {
    setClienteDocsTab(state.clienteDocsTab || "seguros");
  }
  if (tab === "economicos") {
    renderClienteContabilidadPanel();
  }
  if (tab === "dashboard") {
    renderClienteRentaDashboardPanel();
  }
};

const renderClienteContabilidadPanel = () => {
  if (!clienteEconomicosPanel) return;
  const services = Array.isArray(state.currentClienteServices) ? state.currentClienteServices : [];
  const hasGestoria = services.includes("gestoria") || services.includes("gestoría");
  const hasHipotecas = services.includes("financiaciones") || services.includes("hipotecas");
  const availableTabs = [];
  if (hasGestoria) availableTabs.push("gestoria");
  if (hasHipotecas) availableTabs.push("financiaciones");
  const desiredTab = normalizeSimple(state.clienteContabServiceTab || "");
  const activeTab =
    availableTabs.includes(desiredTab)
      ? desiredTab
      : (hasGestoria ? "gestoria" : (hasHipotecas ? "financiaciones" : ""));
  state.clienteContabServiceTab = activeTab;

  if (!activeTab) {
    clienteEconomicosPanel.innerHTML = "<p class='muted'>Sin contabilidad disponible para este cliente.</p>";
    return;
  }

  const root = document.createElement("div");
  if (availableTabs.length > 1) {
    const tabs = document.createElement("div");
    tabs.className = "tabs";
    const mk = (key, label) => {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = `tab ${activeTab === key ? "active" : ""}`.trim();
      btn.textContent = label;
      btn.addEventListener("click", () => {
        state.clienteContabServiceTab = key;
        renderClienteContabilidadPanel();
      });
      return btn;
    };
    if (hasGestoria) tabs.appendChild(mk("gestoria", "Gestoría"));
    if (hasHipotecas) tabs.appendChild(mk("financiaciones", "Financiaciones"));
    root.appendChild(tabs);
  }

  if (activeTab === "financiaciones") {
    renderClienteDatosEconomicos(state.currentClienteData || {}, state.currentClienteEconomicData || {});
    return;
  }

  const openRentaEntry = (entryId) => {
    const next = String(entryId || "").trim();
    if (!next) return;
    state.currentRentaEntryId = next;
    setClienteTab("servicios");
    setClienteOperativaTab("gestoria");
    setGestoriaClientModuleTab("renta");
    try {
      if (gestoriaModuleRenta) {
        gestoriaModuleRenta.scrollIntoView({ behavior: "smooth", block: "start" });
      }
    } catch (e) {}
  };

  const gestoria = state.currentClienteGestoriaData || {};
  const entries = Array.isArray(gestoria.renta_entries) ? gestoria.renta_entries : [];
  if (!entries.length) {
    root.appendChild(
      Object.assign(document.createElement("p"), {
        className: "muted",
        textContent: "Sin campañas de renta registradas para este cliente.",
      })
    );
    clienteEconomicosPanel.innerHTML = "";
    clienteEconomicosPanel.appendChild(root);
    return;
  }

  const ejercicios = Array.from(
    new Set(entries.map((e) => String(e?.ejercicio || "").trim()).filter(Boolean))
  ).sort((a, b) => String(b).localeCompare(String(a)));

  const responsables = Array.from(
    new Set(entries.map((e) => String(e?.responsable || "").trim()).filter(Boolean))
  ).sort((a, b) => a.localeCompare(b, "es"));

  const filterBar = document.createElement("div");
  filterBar.className = "form-grid";
  filterBar.innerHTML = `
    <label>
      Mostrar
      <select id="clienteLedgerCobroFilter">
        <option value="all">Todas</option>
        <option value="priced">Con precio</option>
        <option value="unpaid">Pendientes</option>
        <option value="paid">Cobradas</option>
      </select>
    </label>
    <label>
      Ejercicio
      <select id="clienteLedgerEjercicio">
        <option value="">Todos</option>
      </select>
    </label>
    <label>
      Responsable
      <select id="clienteLedgerResponsable">
        <option value="">Todos</option>
      </select>
    </label>
    <div class="form-actions" style="justify-content:flex-end; align-items:flex-end;">
      <button type="button" class="secondary ghost" id="clienteLedgerOpenRenta">Abrir módulo renta</button>
    </div>
  `;

  const cobroSelect = filterBar.querySelector("#clienteLedgerCobroFilter");
  const ejercicioSelect = filterBar.querySelector("#clienteLedgerEjercicio");
  const responsableSelect = filterBar.querySelector("#clienteLedgerResponsable");
  const openRentaBtn = filterBar.querySelector("#clienteLedgerOpenRenta");

  ejercicios.forEach((val) => ejercicioSelect?.appendChild(createOption(val, val)));
  responsables.forEach((val) => responsableSelect?.appendChild(createOption(val, val)));

  if (cobroSelect) cobroSelect.value = state.clienteLedgerCobroFilter || "priced";
  if (ejercicioSelect) ejercicioSelect.value = state.clienteLedgerEjercicio || "";
  if (responsableSelect) responsableSelect.value = state.clienteLedgerResponsable || "";

  openRentaBtn?.addEventListener("click", () => {
    setClienteTab("servicios");
    setClienteOperativaTab("gestoria");
    setGestoriaClientModuleTab("renta");
  });

  const tableWrap = document.createElement("div");
  const renderTable = () => {
    const cobroFilter = String(cobroSelect?.value || state.clienteLedgerCobroFilter || "priced");
    const ejercicio = String(ejercicioSelect?.value || "").trim();
    const responsable = String(responsableSelect?.value || "").trim();
    state.clienteLedgerCobroFilter = cobroFilter;
    state.clienteLedgerEjercicio = ejercicio;
    state.clienteLedgerResponsable = responsable;

    let filtered = [...entries];
    if (ejercicio) filtered = filtered.filter((e) => String(e?.ejercicio || "").trim() === ejercicio);
    if (responsable) filtered = filtered.filter((e) => String(e?.responsable || "").trim() === responsable);
    if (cobroFilter === "priced") {
      filtered = filtered.filter((e) => (toNumber(e?.precio_servicio) || 0) > 0);
    } else if (cobroFilter === "unpaid") {
      filtered = filtered.filter((e) => (toNumber(e?.precio_servicio) || 0) > 0 && Number(e?.cobrada || 0) !== 1);
    } else if (cobroFilter === "paid") {
      filtered = filtered.filter((e) => (toNumber(e?.precio_servicio) || 0) > 0 && Number(e?.cobrada || 0) === 1);
    }

    tableWrap.innerHTML = "";
    if (!filtered.length) {
      tableWrap.appendChild(Object.assign(document.createElement("p"), { className: "muted", textContent: "Sin resultados." }));
      return;
    }

    const table = document.createElement("table");
    table.className = "data-table";
    const thead = document.createElement("thead");
    const trHead = document.createElement("tr");
    ["Ejercicio", "Estado", "Responsable", "Precio", "Cobro", "Forma", "Remesa", ""].forEach((col) => {
      const th = document.createElement("th");
      th.textContent = col;
      trHead.appendChild(th);
    });
    thead.appendChild(trHead);
    table.appendChild(thead);
    const tbody = document.createElement("tbody");
    filtered.forEach((entry) => {
      const ejercicioCell = String(entry?.ejercicio || "").trim() || "-";
      const estadoCell = String(entry?.estado_presentacion || entry?.doc_status || "").trim() || "-";
      const responsableCell = String(entry?.responsable || "").trim() || "Sin responsable";
      const precio = toNumber(entry?.precio_servicio) || 0;
      const cobrada = Number(entry?.cobrada || 0) === 1 ? "Cobrada" : "Pendiente";
      const forma = String(entry?.forma_cobro || "").trim() || "-";
      const remesa = Number(entry?.remesada || 0) === 1 ? "Sí" : "No";
      const tr = document.createElement("tr");
      [ejercicioCell, estadoCell, responsableCell, euroFormatter.format(precio), cobrada, forma, remesa].forEach((value) => {
        const td = document.createElement("td");
        td.textContent = value;
        tr.appendChild(td);
      });
      const actionTd = document.createElement("td");
      const openBtn = createIconButton("open", "Abrir renta");
      openBtn.classList.add("secondary");
      openBtn.addEventListener("click", (event) => {
        event.stopPropagation();
        openRentaEntry(entry?.id);
      });
      actionTd.appendChild(openBtn);
      tr.appendChild(actionTd);
      tr.addEventListener("click", () => openRentaEntry(entry?.id));
      tbody.appendChild(tr);
    });
    table.appendChild(tbody);
    tableWrap.appendChild(table);
  };

  cobroSelect?.addEventListener("change", renderTable);
  ejercicioSelect?.addEventListener("change", renderTable);
  responsableSelect?.addEventListener("change", renderTable);

  root.appendChild(filterBar);
  root.appendChild(tableWrap);
  renderTable();

  clienteEconomicosPanel.innerHTML = "";
  clienteEconomicosPanel.appendChild(root);
};

const renderClienteRentaDashboardPanel = () => {
  if (!clienteDashboardRentaContent) return;
  const services = Array.isArray(state.currentClienteServices) ? state.currentClienteServices : [];
  const hasGestoria = services.includes("gestoria") || services.includes("gestoría");
  if (clienteDashboardRentaPanel) clienteDashboardRentaPanel.classList.toggle("hidden", !hasGestoria);
  if (!hasGestoria) {
    clienteDashboardRentaContent.innerHTML = "";
    return;
  }

  const openRentaEntry = (entryId) => {
    const next = String(entryId || "").trim();
    if (!next) return;
    state.currentRentaEntryId = next;
    setClienteTab("servicios");
    setClienteOperativaTab("gestoria");
    setGestoriaClientModuleTab("renta");
    try {
      if (gestoriaModuleRenta) {
        gestoriaModuleRenta.scrollIntoView({ behavior: "smooth", block: "start" });
      }
    } catch (e) {}
  };

  const makeKpiCard = (label, value, onClick) => {
    const card = document.createElement("div");
    card.className = "card";
    card.style.cursor = onClick ? "pointer" : "default";
    card.setAttribute("role", onClick ? "button" : "group");
    if (onClick) {
      card.tabIndex = 0;
      card.addEventListener("click", onClick);
      card.addEventListener("keydown", (event) => {
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault();
          onClick();
        }
      });
    }
    const l = document.createElement("div");
    l.className = "kpi-label";
    l.textContent = label;
    const v = document.createElement("div");
    v.className = "kpi-value";
    v.textContent = value;
    card.appendChild(l);
    card.appendChild(v);
    return card;
  };

  const renderRentaEntriesTable = (entries = [], options = {}) => {
    const title = String(options.title || "Listado").trim();
    const hint = String(options.hint || "").trim();
    const wrap = document.createElement("div");
    wrap.className = "form-card";
    const head = document.createElement("div");
    head.className = "section-head";
    const left = document.createElement("div");
    left.innerHTML = `<h4>${escapeHtml(title)}</h4>${hint ? `<p class="muted">${escapeHtml(hint)}</p>` : ""}`;
    const right = document.createElement("div");
    const backBtn = document.createElement("button");
    backBtn.type = "button";
    backBtn.className = "secondary ghost";
    backBtn.textContent = "Volver a KPIs";
    backBtn.addEventListener("click", () => {
      state.clienteContabView = "dashboard";
      state.clienteContabResponsable = "";
      renderClienteRentaDashboardPanel();
    });
    right.appendChild(backBtn);
    head.appendChild(left);
    head.appendChild(right);
    wrap.appendChild(head);
    if (!entries.length) {
      const empty = document.createElement("p");
      empty.className = "muted";
      empty.textContent = options.emptyText || "Sin resultados.";
      wrap.appendChild(empty);
      return wrap;
    }
    const table = document.createElement("table");
    const thead = document.createElement("thead");
    const trHead = document.createElement("tr");
    ["Ejercicio", "Estado", "Responsable", "Precio", "Cobro", "Forma", "Remesa", ""].forEach((col) => {
      const th = document.createElement("th");
      th.textContent = col;
      trHead.appendChild(th);
    });
    thead.appendChild(trHead);
    table.appendChild(thead);
    const tbody = document.createElement("tbody");
    entries.forEach((entry) => {
      const ejercicio = String(entry?.ejercicio || "").trim() || "-";
      const estado = String(entry?.estado_presentacion || entry?.doc_status || "").trim() || "-";
      const responsable = String(entry?.responsable || "").trim() || "Sin responsable";
      const precio = toNumber(entry?.precio_servicio) || 0;
      const cobrada = Number(entry?.cobrada || 0) === 1 ? "Cobrada" : "Pendiente";
      const forma = String(entry?.forma_cobro || "").trim() || "-";
      const remesa = Number(entry?.remesada || 0) === 1 ? "Sí" : "No";
      const tr = document.createElement("tr");
      const values = [ejercicio, estado, responsable, euroFormatter.format(precio), cobrada, forma, remesa];
      values.forEach((value) => {
        const td = document.createElement("td");
        td.textContent = value;
        tr.appendChild(td);
      });
      const actionTd = document.createElement("td");
      const openBtn = createIconButton("open", "Abrir renta");
      openBtn.classList.add("secondary");
      openBtn.addEventListener("click", (event) => {
        event.stopPropagation();
        openRentaEntry(entry?.id);
      });
      actionTd.appendChild(openBtn);
      tr.appendChild(actionTd);
      tr.addEventListener("click", () => openRentaEntry(entry?.id));
      tbody.appendChild(tr);
    });
    table.appendChild(tbody);
    wrap.appendChild(table);
    return wrap;
  };

  const renderResponsablesTable = (buckets = []) => {
    const wrap = document.createElement("div");
    wrap.className = "form-card";
    wrap.innerHTML = `
      <div class="section-head">
        <div>
          <h4>Renta por responsable</h4>
          <p class="muted">Pulsa un responsable para ver el detalle de campañas.</p>
        </div>
        <div>
          <button type="button" class="secondary ghost" id="clienteRentaDashBackBtn">Volver a KPIs</button>
        </div>
      </div>
    `;
    const backBtn = wrap.querySelector("#clienteRentaDashBackBtn");
    backBtn?.addEventListener("click", () => {
      state.clienteContabView = "dashboard";
      state.clienteContabResponsable = "";
      renderClienteRentaDashboardPanel();
    });
    if (!buckets.length) {
      wrap.appendChild(Object.assign(document.createElement("p"), { className: "muted", textContent: "Sin responsables." }));
      return wrap;
    }
    const table = document.createElement("table");
    const thead = document.createElement("thead");
    const trHead = document.createElement("tr");
    ["Responsable", "Rentas", "Pendientes", "Importe", "Cobrado", "Pendiente"].forEach((col) => {
      const th = document.createElement("th");
      th.textContent = col;
      trHead.appendChild(th);
    });
    thead.appendChild(trHead);
    table.appendChild(thead);
    const tbody = document.createElement("tbody");
    buckets.forEach((bucket) => {
      const tr = document.createElement("tr");
      tr.style.cursor = "pointer";
      const values = [
        bucket.responsable,
        numberFormatter.format(bucket.total),
        numberFormatter.format(bucket.unpaidCount),
        euroFormatter.format(bucket.totalImporte),
        euroFormatter.format(bucket.paidImporte),
        euroFormatter.format(bucket.unpaidImporte),
      ];
      values.forEach((value) => {
        const td = document.createElement("td");
        td.textContent = value;
        tr.appendChild(td);
      });
      tr.addEventListener("click", () => {
        state.clienteContabView = "responsable";
        state.clienteContabResponsable = bucket.responsableKey;
        renderClienteRentaDashboardPanel();
      });
      tbody.appendChild(tr);
    });
    table.appendChild(tbody);
    wrap.appendChild(table);
    return wrap;
  };

  const gestoria = state.currentClienteGestoriaData || {};
  const entries = Array.isArray(gestoria.renta_entries) ? gestoria.renta_entries : [];
  const gestoriaSummary = state.currentClienteDashboard?.gestoria || {};
  const priced = entries.filter((e) => (toNumber(e?.precio_servicio) || 0) > 0);
  const unpaid = priced.filter((e) => Number(e?.cobrada || 0) !== 1);
  const paid = priced.filter((e) => Number(e?.cobrada || 0) === 1);
  const totalImporte = priced.reduce((acc, e) => acc + (toNumber(e?.precio_servicio) || 0), 0);
  const paidImporte = paid.reduce((acc, e) => acc + (toNumber(e?.precio_servicio) || 0), 0);
  const unpaidImporte = unpaid.reduce((acc, e) => acc + (toNumber(e?.precio_servicio) || 0), 0);

  const bucketMap = new Map();
  entries.forEach((entry) => {
    const responsableRaw = String(entry?.responsable || "").trim() || "Sin responsable";
    const responsableKey = normalizeLookupText(responsableRaw) || "sin-responsable";
    if (!bucketMap.has(responsableKey)) {
      bucketMap.set(responsableKey, {
        responsableKey,
        responsable: responsableRaw,
        total: 0,
        unpaidCount: 0,
        totalImporte: 0,
        paidImporte: 0,
        unpaidImporte: 0,
        entries: [],
      });
    }
    const bucket = bucketMap.get(responsableKey);
    bucket.total += 1;
    const precio = toNumber(entry?.precio_servicio) || 0;
    if (precio > 0) {
      bucket.totalImporte += precio;
      if (Number(entry?.cobrada || 0) === 1) {
        bucket.paidImporte += precio;
      } else {
        bucket.unpaidCount += 1;
        bucket.unpaidImporte += precio;
      }
    }
    bucket.entries.push(entry);
  });
  const buckets = Array.from(bucketMap.values()).sort(
    (a, b) => (b.unpaidImporte - a.unpaidImporte) || (b.total - a.total)
  );

  const view = normalizeSimple(state.clienteContabView || "dashboard") || "dashboard";
  const responsableFilterKey = normalizeLookupText(state.clienteContabResponsable || "");

  const root = document.createElement("div");
  if (gestoriaSummary && Object.keys(gestoriaSummary).length) {
    const summary = document.createElement("div");
    summary.className = "cliente-gestoria-summary";
    const latestYear = String(gestoriaSummary.latest_renta_year || "").trim() || "-";
    const alerts = Array.isArray(gestoriaSummary.alerts) ? gestoriaSummary.alerts : [];
    const checklist = Array.isArray(gestoriaSummary.checklist) ? gestoriaSummary.checklist : [];
    const nextActions = Array.isArray(gestoriaSummary.next_actions) ? gestoriaSummary.next_actions : [];
    const timeline = Array.isArray(gestoriaSummary.timeline) ? gestoriaSummary.timeline : [];
    const statusGlobal = String(gestoriaSummary.status_global || "Sin gestoría").trim();
    summary.innerHTML = `
      <div class="section-head">
        <div>
          <h4>Situación de gestoría <span class="status-pill ${statusGlobal === "Al día" ? "ok" : "warning"}">${escapeHtml(statusGlobal)}</span></h4>
          <p class="muted">Último ejercicio ${escapeHtml(latestYear)} · ${numberFormatter.format(Number(gestoriaSummary.modelo100_docs_total || 0))} Modelo 100 · ${numberFormatter.format(Number(gestoriaSummary.renta_docs_con_pdf || 0))} PDF vinculados · checklist ${numberFormatter.format(Number(gestoriaSummary.checklist_done || 0))}/${numberFormatter.format(Number(gestoriaSummary.checklist_total || 0))}</p>
        </div>
        <div class="form-actions">
          <button type="button" class="secondary ghost" data-gestoria-summary-action="docs">Documentación</button>
          <button type="button" class="secondary ghost" data-gestoria-summary-action="renta">Renta</button>
        </div>
      </div>
      <div class="cliente-mini-kpis">
        <div class="card"><div class="kpi-label">Rentas</div><div class="kpi-value">${numberFormatter.format(Number(gestoriaSummary.rentas_total || 0))}</div></div>
        <div class="card"><div class="kpi-label">Presentadas</div><div class="kpi-value">${numberFormatter.format(Number(gestoriaSummary.rentas_presentadas || 0))}</div></div>
        <div class="card"><div class="kpi-label">Pendiente cobro</div><div class="kpi-value">${euroFormatter.format(Number(gestoriaSummary.importe_rentas_pendiente || 0))}</div></div>
        <div class="card"><div class="kpi-label">Trabajos abiertos</div><div class="kpi-value">${numberFormatter.format(Number(gestoriaSummary.trabajos_abiertos || 0) + Number(gestoriaSummary.acciones_abiertas || 0))}</div></div>
      </div>
      <div class="cliente-gestoria-alerts">
        ${
          alerts.length
            ? alerts.map((item) => `<span class="status-pill ${String(item.level || "info") === "warning" ? "warning" : ""}">${escapeHtml(item.label || "")}</span>`).join("")
            : '<span class="status-pill ok">Sin alertas operativas</span>'
        }
      </div>
      <div class="cliente-gestoria-workgrid">
        <div>
          <h4>Checklist documental</h4>
          <div class="cliente-gestoria-checklist">
            ${
              checklist.length
                ? checklist.map((item) => `
                    <button type="button" class="cliente-checkitem ${item.done ? "done" : "pending"}" data-gestoria-summary-action="docs">
                      <span>${item.done ? "OK" : "Pendiente"}</span>
                      <strong>${escapeHtml(item.label || "")}</strong>
                    </button>
                  `).join("")
                : '<p class="muted">Sin checklist disponible.</p>'
            }
          </div>
        </div>
        <div>
          <h4>Próximas acciones</h4>
          <div class="cliente-gestoria-actions">
            ${
              nextActions.length
                ? nextActions.map((item) => `
                    <button type="button" class="cliente-next-action ${String(item.priority || "") === "alta" ? "urgent" : ""}" data-gestoria-summary-action="${escapeHtml(item.target || "renta")}">
                      <strong>${escapeHtml(item.label || "")}</strong>
                      <span>${escapeHtml(item.meta || "")}</span>
                    </button>
                  `).join("")
                : '<p class="muted">Sin acciones recomendadas.</p>'
            }
          </div>
        </div>
      </div>
      <div class="cliente-gestoria-timeline">
        <h4>Últimos hitos</h4>
        ${
          timeline.length
            ? timeline.map((item) => `
                <div class="cliente-timeline-item">
                  <span>${escapeHtml(item.date || "-")}</span>
                  <strong>${escapeHtml(item.title || "")}</strong>
                  <em>${escapeHtml(item.meta || item.kind || "")}</em>
                </div>
              `).join("")
            : '<p class="muted">Sin hitos registrados.</p>'
        }
      </div>
    `;
    summary.querySelectorAll("[data-gestoria-summary-action]").forEach((btn) => {
      btn.addEventListener("click", () => {
        const action = String(btn.dataset.gestoriaSummaryAction || "").trim();
        if (action === "docs") {
          setClienteTab("docs");
          setClienteDocsTab("gestoria");
          return;
        }
        setClienteTab("servicios");
        setClienteOperativaTab("gestoria");
        if (action === "trabajos" || action === "agenda") {
          setGestoriaClientModuleTab("admin");
        } else {
          setGestoriaClientModuleTab("renta");
        }
      });
    });
    root.appendChild(summary);
  }
  const kpis = document.createElement("div");
  kpis.className = "cliente-mini-kpis";
  kpis.appendChild(makeKpiCard("Rentas", numberFormatter.format(entries.length), () => {
    state.clienteContabView = "all";
    state.clienteContabResponsable = "";
    renderClienteRentaDashboardPanel();
  }));
  kpis.appendChild(makeKpiCard("Pendientes cobro", numberFormatter.format(unpaid.length), () => {
    state.clienteContabView = "unpaid";
    state.clienteContabResponsable = "";
    renderClienteRentaDashboardPanel();
  }));
  kpis.appendChild(makeKpiCard("Importe pendiente", euroFormatter.format(unpaidImporte), () => {
    state.clienteContabView = "unpaid";
    state.clienteContabResponsable = "";
    renderClienteRentaDashboardPanel();
  }));
  kpis.appendChild(makeKpiCard("Importe cobrado", euroFormatter.format(paidImporte), () => {
    state.clienteContabView = "paid";
    state.clienteContabResponsable = "";
    renderClienteRentaDashboardPanel();
  }));
  kpis.appendChild(makeKpiCard("Importe total", euroFormatter.format(totalImporte), () => {
    state.clienteContabView = "all";
    state.clienteContabResponsable = "";
    renderClienteRentaDashboardPanel();
  }));
  kpis.appendChild(makeKpiCard("Responsables", numberFormatter.format(buckets.length), () => {
    state.clienteContabView = "responsables";
    state.clienteContabResponsable = "";
    renderClienteRentaDashboardPanel();
  }));
  root.appendChild(kpis);

  const detail = document.createElement("div");
  if (view === "dashboard") {
    detail.appendChild(renderResponsablesTable(buckets));
  } else if (view === "unpaid") {
    detail.appendChild(
      renderRentaEntriesTable(unpaid, {
        title: "Rentas pendientes de cobro",
        hint: "Campañas con precio asignado y sin marcar como cobradas.",
        emptyText: "No hay rentas pendientes.",
      })
    );
  } else if (view === "paid") {
    detail.appendChild(
      renderRentaEntriesTable(paid, {
        title: "Rentas cobradas",
        hint: "Campañas con precio asignado y marcadas como cobradas.",
        emptyText: "No hay rentas cobradas.",
      })
    );
  } else if (view === "responsables") {
    detail.appendChild(renderResponsablesTable(buckets));
  } else if (view === "responsable" && responsableFilterKey) {
    const bucket = buckets.find((b) => normalizeLookupText(b.responsableKey) === responsableFilterKey);
    const scoped = bucket ? bucket.entries : [];
    detail.appendChild(
      renderRentaEntriesTable(scoped, {
        title: `Rentas · ${bucket?.responsable || "Responsable"}`,
        hint: "Listado de campañas asignadas a este responsable (pulsa para abrir la renta).",
        emptyText: "Sin campañas para este responsable.",
      })
    );
  } else if (view === "all") {
    detail.appendChild(
      renderRentaEntriesTable(entries, {
        title: "Todas las campañas de renta",
        hint: "Pulsa una fila para abrir la renta y actualizar cobro/precio.",
        emptyText: "Sin campañas de renta.",
      })
    );
  } else {
    detail.appendChild(renderResponsablesTable(buckets));
  }
  root.appendChild(detail);

  clienteDashboardRentaContent.innerHTML = "";
  clienteDashboardRentaContent.appendChild(root);
};

const renderClientePremiumHeader = (cliente = {}, payload = {}) => {
  if (!clientePremiumHeader) return;
  const dashboard = payload.dashboard || {};
  const gestoria = dashboard.gestoria || {};
  const empresas = Array.isArray(payload.empresas) ? payload.empresas : [];
  const servicios = Array.from(
    new Set(
      (payload.servicios_activos || empresas.map((row) => row.servicio_key || row.servicio || ""))
        .map((value) => normalizeSimple(value || ""))
        .filter(Boolean)
    )
  );
  const status = String(gestoria.status_global || (servicios.includes("gestoria") ? "En curso" : "Sin gestoría")).trim();
  const statusClass = status === "Al día" ? "ok" : (status === "Sin gestoría" ? "" : "warning");
  const contactItems = [
    cliente.nif ? `NIF ${cliente.nif}` : "",
    cliente.telefono || cliente.movil || "",
    cliente.email || "",
    [cliente.poblacion || "", cliente.provincia || ""].filter(Boolean).join(" · "),
  ].filter(Boolean);
  const serviceLabels = servicios.map((key) => ({
    gestoria: "Gestoría",
    seguros: "Seguros",
    inmobiliaria: "Inmobiliaria",
    financiaciones: "Financiación",
    hipotecas: "Financiación",
  }[key] || key));
  clientePremiumHeader.classList.remove("hidden");
  clientePremiumHeader.innerHTML = `
    <div class="cliente-premium-main">
      <div>
        <div class="cliente-premium-eyebrow">Ficha cliente</div>
        <h2>${escapeHtml(formatNombreCliente(cliente.nombre || "") || "Cliente")}</h2>
        <div class="cliente-premium-meta">${contactItems.length ? contactItems.map(escapeHtml).join(" · ") : "Datos de contacto pendientes"}</div>
      </div>
      <div class="cliente-premium-status">
        <span class="status-pill ${statusClass}">${escapeHtml(status)}</span>
      </div>
    </div>
    <div class="cliente-premium-bottom">
      <div class="cliente-premium-services">
        ${
          serviceLabels.length
            ? serviceLabels.map((label) => `<span>${escapeHtml(label)}</span>`).join("")
            : "<span>Sin servicios activos</span>"
        }
      </div>
      <div class="cliente-premium-actions">
        <button type="button" class="secondary ghost" data-cliente-header-action="dashboard">Dashboard</button>
        <button type="button" class="secondary ghost" data-cliente-header-action="docs">Docs</button>
        <button type="button" class="secondary ghost" data-cliente-header-action="renta">Renta</button>
      </div>
    </div>
  `;
  clientePremiumHeader.querySelectorAll("[data-cliente-header-action]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const action = String(btn.dataset.clienteHeaderAction || "").trim();
      if (action === "docs") {
        setClienteTab("docs");
        setClienteDocsTab(servicios.includes("gestoria") ? "gestoria" : (servicios[0] || "seguros"));
      } else if (action === "renta") {
        setClienteTab("servicios");
        setClienteOperativaTab("gestoria");
        setGestoriaClientModuleTab("renta");
      } else {
        setClienteTab("dashboard");
      }
    });
  });
};

const setClienteOperativaTab = (tab) => {
  if (!clienteOperativaTabs) return;
  const target = tab || "gestoria";
  state.clienteOperativaTab = target;
  clienteOperativaTabs.querySelectorAll(".tab").forEach((btn) => {
    btn.classList.toggle("active", btn.dataset.operativaTab === target);
  });
  if (clienteOperativaGestoriaPanel) {
    clienteOperativaGestoriaPanel.classList.toggle("hidden", target !== "gestoria");
  }
  if (clienteOperativaSegurosPanel) {
    clienteOperativaSegurosPanel.classList.toggle("hidden", target !== "seguros");
  }
  if (clienteOperativaInmoPanel) {
    clienteOperativaInmoPanel.classList.toggle("hidden", target !== "inmobiliaria");
  }
  if (clienteOperativaFinPanel) {
    clienteOperativaFinPanel.classList.toggle("hidden", target !== "financiaciones");
  }
};

if (clienteOperativaGestoriaMount && clienteProfesionalOperativaBlock) {
  clienteOperativaGestoriaMount.appendChild(clienteProfesionalOperativaBlock);
}

const renderClienteDocsTable = (rows, container, options = {}) => {
  if (!container) return;
  const enableOcr = !!options.enableOcr;
  const enableDelete = !!options.enableDelete;
  const onDelete = typeof options.onDelete === "function" ? options.onDelete : null;
  if (!rows.length) {
    container.innerHTML = "<p class='muted'>Sin documentación registrada.</p>";
    return;
  }
  const table = document.createElement("table");
  const thead = document.createElement("thead");
  const trHead = document.createElement("tr");
  const columns = ["Documento", "Tipo", "Fecha", "Estado", "Notas", "PDF"];
  if (enableDelete) {
    columns.push("Acción");
  }
  if (enableOcr) {
    columns.push("OCR");
  }
  columns.forEach((col) => {
    const th = document.createElement("th");
    th.textContent = col;
    trHead.appendChild(th);
  });
  thead.appendChild(trHead);
  table.appendChild(thead);
  const tbody = document.createElement("tbody");
  rows.forEach((row) => {
    const tr = document.createElement("tr");
    const referenciaTipo = normalizeLookupText(row.referencia_tipo || "").toLowerCase();
    const tipoCell = (() => {
      const raw = String(row.tipo || "").trim();
      if (referenciaTipo !== "renta") return raw;
      const normalized = normalizeLookupText(raw).toLowerCase();
      if (normalized.includes("modelo") && normalized.includes("100")) return raw;
      return "Modelo 100";
    })();
    const nombreTd = document.createElement("td");
    const canRename = Boolean(row && row.id);
    if (canRename) {
      const input = document.createElement("input");
      input.type = "text";
      input.value = String(row.nombre || "");
      input.autocomplete = "off";
      input.spellcheck = false;
      input.style.width = "100%";
      input.title = "Editar nombre del documento";
      const commit = () => {
        const next = input.value.trim();
        const prev = String(row.nombre || "").trim();
        if (!next) {
          input.value = prev;
          return;
        }
        if (next === prev) return;
        row.nombre = next;
        try {
          saveGestoriaDocField(row.id, "nombre", next);
        } catch (e) {}
      };
      input.addEventListener("blur", commit);
      input.addEventListener("keydown", (event) => {
        if (event.key === "Enter") {
          event.preventDefault();
          input.blur();
        }
        if (event.key === "Escape") {
          event.preventDefault();
          input.value = String(row.nombre || "");
          input.blur();
        }
      });
      nombreTd.appendChild(input);
    } else {
      nombreTd.textContent = row.nombre || "";
    }
    tr.appendChild(nombreTd);

    [tipoCell, row.fecha || "", row.estado || "", row.notas || ""].forEach((value) => {
      const td = document.createElement("td");
      td.textContent = value;
      tr.appendChild(td);
    });
    const pdfTd = document.createElement("td");
    if (row.doc_key || row.doc_url) {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "secondary";
      btn.textContent = "Ver";
      btn.addEventListener("click", () => {
        openS3File(row.doc_key, row.doc_url);
      });
      pdfTd.appendChild(btn);
    } else {
      pdfTd.textContent = "-";
    }
    tr.appendChild(pdfTd);
    if (enableDelete) {
      const delTd = document.createElement("td");
      const delBtn = document.createElement("button");
      delBtn.type = "button";
      delBtn.className = "ghost";
      delBtn.textContent = "Borrar";
      const canDelete = Boolean(row.id);
      delBtn.disabled = !canDelete;
      delBtn.addEventListener("click", async () => {
        if (!row.id || !onDelete) return;
        await onDelete(row);
      });
      delTd.appendChild(delBtn);
      tr.appendChild(delTd);
    }
    if (enableOcr) {
      const ocrTd = document.createElement("td");
      const ocrBtn = document.createElement("button");
      ocrBtn.type = "button";
      ocrBtn.className = "secondary";
      ocrBtn.textContent = "OCR";
      const hasDoc = Boolean(row.doc_key || row.doc_url);
      ocrBtn.disabled = !hasDoc;
      const ocrStatus = document.createElement("div");
      ocrStatus.className = "muted";
      if (!hasDoc) {
        ocrStatus.textContent = "Sin archivo";
      }
      ocrBtn.addEventListener("click", () => {
        runClienteSegurosDocOcr(row, ocrStatus, ocrBtn);
      });
      ocrTd.appendChild(ocrBtn);
      ocrTd.appendChild(ocrStatus);
      tr.appendChild(ocrTd);
    }
    tbody.appendChild(tr);
  });
  table.appendChild(tbody);
  container.innerHTML = "";
  container.appendChild(table);
};

const loadClienteDocsByService = (clienteId, service, container) => {
  if (!container) return;
  if (!clienteId) {
    container.innerHTML = "<p class='muted'>Selecciona un cliente.</p>";
    return;
  }
  const query = new URLSearchParams({
    cliente_id: clienteId,
    service,
  });
  api(`/api/gestoria_docs?${query.toString()}`).then(async (data) => {
    let rows = data.rows || [];
    if (normalizeSimple(service) === "seguros") {
      rows = rows.map((row) => ({
        ...row,
        seguro_id: row.seguro_id || row.referencia_id || "",
        cliente_id: row.cliente_id || clienteId,
      }));
      if (!SEGUROS_ONLY_UPLOADED_MODE) {
        const seguros = await api(`/api/seguros_cliente?cliente_id=${encodeURIComponent(clienteId)}&uploaded_only=1`).catch(() => ({ rows: [] }));
        const fromSeguros = (seguros.rows || [])
          .filter((row) => row.poliza_url || row.poliza_key)
          .map((row) => ({
            seguro_id: row.id || "",
            referencia_id: row.id || "",
            cliente_id: row.cliente_id || clienteId,
            nombre: row.poliza_numero || `Póliza ${row.compania || ""}`.trim(),
            tipo: "Seguros",
            fecha: row.fecha_efecto || "",
            estado: row.estado || "",
            notas: row.ramo || "",
            doc_key: row.poliza_key || "",
            doc_url: row.poliza_url || "",
          }));
        const seen = new Set(
          rows.map((row) => String(row.seguro_id || row.referencia_id || row.doc_key || row.doc_url || "").trim())
        );
        fromSeguros.forEach((row) => {
          const key = String(row.seguro_id || row.referencia_id || row.doc_key || row.doc_url || "").trim();
          if (!key || seen.has(key)) return;
          seen.add(key);
          rows.push(row);
        });
      }
    }
    renderClienteDocsTable(rows, container, {
      enableOcr: normalizeSimple(service) === "seguros",
      enableDelete: true,
      onDelete: async (row) => {
        if (!row?.id) return;
        if (!window.confirm("¿Borrar este documento?")) return;
        const payload = { id: row.id, usuario: getCurrentUser() };
        const data = await fetch("/api/gestoria_docs_delete", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(payload),
        }).then((res) => res.json());
        if (data?.error) {
          alert(data.error);
          return;
        }
        loadClienteDocsByService(clienteId, service, container);
      },
    });
  });
};

const setClienteDocsTab = (tab) => {
  if (!clienteDocsTabs) return;
  const normalized = tab || "seguros";
  const allowed = getVisibleServiceKeys();
  const fallback = allowed ? Array.from(allowed)[0] || "seguros" : normalized;
  const targetTab = allowed && !allowed.has(normalizeSimple(normalized)) ? fallback : normalized;
  state.clienteDocsTab = targetTab;
  if (clienteDocsUploadService) {
    clienteDocsUploadService.value = targetTab;
  }
  clienteDocsTabs.querySelectorAll(".tab").forEach((btn) => {
    const key = normalizeSimple(btn.dataset.docsTab || "");
    const isAllowed = !allowed || allowed.has(key);
    btn.classList.toggle("hidden", !isAllowed);
    btn.classList.toggle("active", btn.dataset.docsTab === targetTab);
  });
  if (clienteDocsSeguros) {
    clienteDocsSeguros.classList.toggle("hidden", targetTab !== "seguros");
  }
  if (clienteDocsGestoria) {
    clienteDocsGestoria.classList.toggle("hidden", targetTab !== "gestoria");
  }
  if (clienteDocsFin) {
    clienteDocsFin.classList.toggle("hidden", targetTab !== "financiaciones");
  }
  if (clienteDocsInmo) {
    clienteDocsInmo.classList.toggle("hidden", targetTab !== "inmobiliaria");
  }
  const clienteId = state.currentClienteId;
  if (targetTab === "seguros") {
    loadClienteDocsByService(clienteId, "seguros", clienteDocsSeguros);
  } else if (targetTab === "gestoria") {
    loadClienteDocsByService(clienteId, "gestoria", clienteDocsGestoria);
  } else if (targetTab === "financiaciones") {
    loadClienteDocsByService(clienteId, "financiaciones", clienteDocsFin);
  } else if (targetTab === "inmobiliaria") {
    loadClienteDocsByService(clienteId, "inmobiliaria", clienteDocsInmo);
  }
};

const syncHoldingUrlParams = () => {
  if (state.currentPage !== "holding") return;
  const mode = state.currentWorkspaceEntryMode === "tenant" ? "tenant" : "platform";
  const params = new URLSearchParams({ holding: "1", mode });
  if (state.currentWorkspaceTarget) {
    params.set("workspace", state.currentWorkspaceTarget);
  }
  if (state.currentWorkspaceView) {
    params.set("view", state.currentWorkspaceView);
  }
  if (state.currentWorkspaceView === "rrhh" && String(state.workspaceRrhhEntry || "").trim() === "self") {
    params.set("rrhh", "self");
  }
  if (state.currentWorkspaceView === "rrhh") {
    const tab = normalizeWorkspaceRrhhTab(state.workspaceRrhhTab || "");
    if (tab && tab !== "plantilla") {
      params.set("rrhh_tab", tab);
    }
  }
  if (state.currentWorkspaceView === "motores" && state.currentWorkspaceEngineView) {
    params.set("engine", state.currentWorkspaceEngineView);
  }
  setUrlParams(params);
};

const openHolding = (options = {}) => {
  const user = getAuthScopeUser();
  const mode = options.mode === "tenant" ? "tenant" : "platform";
  const canManageWorkspace = Boolean(user && hasAdminWideAccess(user));
  try {
    debugLog(
      "openHolding()",
      `mode=${mode} workspace=${String(options.workspace || "")} view=${String(options.view || "")}\nuser=${user?.usuario || user?.email || user?.id || "-"} priv=${canManageWorkspace ? "1" : "0"}`
    );
  } catch (e) {}
  // En modo plataforma (admin), exigimos permisos globales. En tenant, cualquier usuario autenticado debe poder entrar.
  if (mode === "platform" && !canAccessSharedHomeModules(user)) {
    goHome();
    return;
  }
  if (!user) {
    // No limpiamos la URL ni forzamos home: dejamos el deep-link y pedimos login.
    try {
      showAuthOverlay("La sesión ha caducado. Inicia sesión de nuevo.");
    } catch (e) {}
    return;
  }
  const requestedWorkspace = normalizeTenantWorkspaceSlug(String(options.workspace || "").trim(), "");
  let requestedView = String(options.view || "").trim();
  const requestedEngine = String(options.engine || "").trim();
  const urlParams = new URLSearchParams(window.location.search || "");
  const requestedPersona = ("persona" in options)
    ? String(options.persona || "").trim()
    : String(urlParams.get("persona") || "").trim();
  const requestedRrhh = (("rrhh" in options) ? String(options.rrhh || "") : String(urlParams.get("rrhh") || ""))
    .trim()
    .toLowerCase();
  const requestedRrhhTab = (("rrhh_tab" in options) ? String(options.rrhh_tab || "") : String(urlParams.get("rrhh_tab") || ""))
    .trim()
    .toLowerCase();
  if (mode === "tenant" && !canManageWorkspace) {
    const viewKey = normalizeSimple(requestedView);
    if (viewKey && !["operations", "rrhh", "fincas", "motores"].includes(viewKey)) {
      requestedView = "";
    }
  }
  state.currentWorkspaceEntryMode = mode;
  state.currentWorkspaceTarget = requestedWorkspace || (mode === "tenant" ? resolveDefaultTenantWorkspaceSlug() : "");
  state.workspaceRrhhEntry = requestedRrhh === "self" ? "self" : "";
  state.workspaceRrhhJumpPersonaId = requestedPersona;
  if (requestedRrhhTab && normalizeSimple(requestedView) === "rrhh") {
    state.workspaceRrhhTab = normalizeWorkspaceRrhhTab(requestedRrhhTab);
  }
  const engineKey = normalizeSimple(requestedEngine);
  if (engineKey === "rrhh") {
    // Compatibilidad: URLs antiguas que apuntaban a motores->rrhh ahora abren la vista RRHH.
    if (!requestedView || normalizeSimple(requestedView) === "motores") {
      requestedView = "rrhh";
    }
    state.currentWorkspaceEngineView = "documental";
  } else if (requestedEngine) {
    state.currentWorkspaceEngineView = normalizeWorkspaceEngineKey(requestedEngine);
  }
  if (normalizeSimple(requestedView) !== "rrhh") {
    state.workspaceRrhhEntry = "";
    state.workspaceRrhhJumpPersonaId = "";
  }
  try {
    debugLog(
      "openHolding(): state",
      `target=${state.currentWorkspaceTarget || "-"} nextView=${requestedView || "-"} engine=${state.currentWorkspaceEngineView || "-"}`
    );
  } catch (e) {}
  setModule("empresas");
  if (explorerSection) {
    explorerSection.classList.add("hidden");
  } else {
    try {
      debugLog("openHolding(): missing explorerSection", "DOM element #explorerSection no existe.");
    } catch (e) {}
  }
  try {
    debugLog("openHolding(): setPage", "holding");
  } catch (e) {}
  setPage("holding");
  const nextView = requestedView || (mode === "tenant" ? "operations" : state.currentWorkspaceView || "overview");
  updateWorkspaceEntryChrome();
  try {
    debugLog("openHolding(): setWorkspaceView", nextView);
  } catch (e) {}
  setWorkspaceView(nextView, { forceTenantView: mode === "tenant" && nextView !== "operations" });
  loadWorkspaceCentral().catch(() => {});
  syncHoldingUrlParams();
  window.scrollTo({ top: 0, behavior: state.booting ? "auto" : "smooth" });
};

const openAgenda = () => {
  const user = getAuthScopeUser();
  if (!canAccessSharedHomeModules(user)) {
    goHome();
    return;
  }
  setModule("empresas");
  // Evitar “mezclas”: si venimos de ficha de inmueble (panel CRM), al abrir Agenda general
  // debe ocultarse siempre, si no queda renderizada debajo.
  try {
    if (typeof inmuebleDetail !== "undefined" && inmuebleDetail) {
      inmuebleDetail.classList.add("hidden");
    }
  } catch (e) {}
  explorerSection.classList.add("hidden");
  setPage("agenda");
  if (agendaSection) {
    agendaSection.classList.remove("hidden");
  }
  loadAgendaGeneral();
  setUrlParams(new URLSearchParams({ agenda: "1" }));
  window.scrollTo({ top: 0, behavior: state.booting ? "auto" : "smooth" });
};

