const hasToken = (text, tokens) => tokens.some((token) => text.includes(token));

const isMoneyColumnKey = (value) => {
  const lower = String(value || "").toLowerCase();
  // Campo inmobiliario: es una etiqueta (Venta/Alquiler/Permuta...), no un importe.
  if (lower === "necesidad_venta_alquiler") return false;
  return MONEY_COLUMNS.has(lower) || hasToken(lower, MONEY_COLUMN_TOKENS) || lower.includes("comision");
};

const formatCell = (col, value, tipoPersona = "") => {
  const lower = col.toLowerCase();
  if (["nif", "dni", "cif"].includes(lower)) {
    return normalizeDocumento(value);
  }
  const isNombreCol =
    lower === "nombre" ||
    lower === "cliente" ||
    lower === "tomador" ||
    lower.endsWith("_nombre") ||
    (lower.includes("nombre") && !lower.includes("empresa")) ||
    (lower.includes("cliente") && !lower.includes("cliente_id"));
  if (isNombreCol) {
    return formatNombreCliente(value, tipoPersona);
  }
  const codeLike = hasToken(lower, CODELIKE_COLUMN_TOKENS) || lower.endsWith("_id");
  const number = toNumber(value);
  const isMoney = isMoneyColumnKey(lower);
  if (isMoney && number !== null) {
    return euroFormatter.format(number);
  }
  if (lower.includes("porcentaje")) {
    if (number === null) return value;
    const normalized = number > 0 && number <= 1 ? number * 100 : number;
    return `${normalized.toFixed(2)}%`;
  }
  if (!codeLike && number !== null) {
    const isQuantity =
      typeof value === "number" ||
      hasToken(lower, QUANTITY_COLUMN_TOKENS);
    if (isQuantity) {
      return quantityFormatter.format(number);
    }
  }
  return value;
};

const createWordmarkLogoDataUri = (label, options = {}) => {
  const {
    width = 240,
    height = 72,
    bg = "#f7f4eb",
    bg2 = "#eef3ea",
    text = "#213129",
    accent = "#c7a24a",
  } = options;
  const safeLabel = String(label || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
  const svg = `
    <svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">
      <defs>
        <linearGradient id="bg" x1="0%" y1="0%" x2="100%" y2="100%">
          <stop offset="0%" stop-color="${bg}" />
          <stop offset="100%" stop-color="${bg2}" />
        </linearGradient>
      </defs>
      <rect width="${width}" height="${height}" rx="18" fill="url(#bg)" />
      <rect x="10" y="10" width="6" height="${height - 20}" rx="3" fill="${accent}" />
      <text x="${width / 2 + 8}" y="${height / 2 + 6}" text-anchor="middle" font-family="Space Grotesk, Arial, sans-serif" font-size="26" font-weight="700" fill="${text}" letter-spacing="0.5">${safeLabel}</text>
    </svg>
  `.trim();
  return `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(svg)}`;
};

