const normalizeNifValue = (value) =>
  String(value || "")
    .toUpperCase()
    .replace(/[.\-\s]/g, "")
    .replace(/O/g, "0")
    .replace(/[IL]/g, "1")
    .replace(/S/g, "5")
    .replace(/[^A-Z0-9]/g, "")
    .slice(0, 12);

const getPostalInfo = (value) => {
  const code = normalizePostalCode(value);
  if (code.length < 2) return null;
  const provinceKey = code.slice(0, 2);
  return POSTAL_PROVINCES[provinceKey] || null;
};

const postalCache = new Map();

const fetchPostalLookup = (value) => {
  const code = normalizePostalCode(value);
  if (!code) return Promise.resolve(null);
  if (postalCache.has(code)) {
    return Promise.resolve(postalCache.get(code));
  }
  return api(`/api/postal_lookup?cp=${encodeURIComponent(code)}`)
    .then((data) => {
      if (!data || data.error) return null;
      if (data.provincia || data.poblacion) {
        postalCache.set(code, data);
        return data;
      }
      return null;
    })
    .catch(() => null);
};

const setMultiSelectValues = (selectEl, values = []) => {
  if (!selectEl) return;
  const wanted = new Set((values || []).map((item) => String(item || "").trim()).filter(Boolean));
  Array.from(selectEl.options || []).forEach((option) => {
    option.selected = wanted.has(String(option.value || "").trim());
  });
};

const bindPostalLookup = (formEl) => {
  if (!formEl) return;
  const postalInput = formEl.querySelector('[name="codigo_postal"]');
  const poblacionInput = formEl.querySelector('[name="poblacion"]');
  const provinciaInput = formEl.querySelector('[name="provincia"]');
  if (!postalInput || !poblacionInput || !provinciaInput) return;
  let poblacionSelect = null;
  const label = poblacionInput.closest("label");
  if (label) {
    poblacionSelect = document.createElement("select");
    poblacionSelect.className = "postal-options hidden";
    poblacionSelect.appendChild(createOption("", "Selecciona población"));
    label.appendChild(poblacionSelect);
    poblacionSelect.addEventListener("change", () => {
      const value = poblacionSelect.value;
      if (!value) return;
      poblacionInput.value = value;
      poblacionInput.dataset.auto = "0";
      if (poblacionSelect.dataset.provincia && provinciaInput) {
        provinciaInput.value = poblacionSelect.dataset.provincia;
      }
    });
  }
  poblacionInput.addEventListener("input", () => {
    poblacionInput.dataset.auto = "0";
  });
  const applyPostal = () => {
    const fallback = getPostalInfo(postalInput.value);
    fetchPostalLookup(postalInput.value).then((info) => {
      const resolved = info || fallback;
      if (!resolved) return;
      const provinciaValue = resolved.provincia || fallback?.provincia || "";
      const poblacionValue = resolved.poblacion || fallback?.poblacion || "";
      if (provinciaInput && provinciaValue) {
        provinciaInput.value = provinciaValue;
        try {
          provinciaInput.dispatchEvent(new Event("change", { bubbles: true }));
        } catch (e) {}
      }
      if (poblacionInput && poblacionValue) {
        const shouldAuto =
          !poblacionInput.value || poblacionInput.dataset.auto === "1";
        if (shouldAuto) {
          poblacionInput.value = poblacionValue;
          poblacionInput.dataset.auto = "1";
        }
      }
      if (poblacionSelect) {
        const options = (info && info.opciones) || [];
        const unique = Array.from(
          new Set(options.map((opt) => opt.poblacion).filter(Boolean))
        );
        poblacionSelect.innerHTML = "";
        poblacionSelect.appendChild(createOption("", "Selecciona población"));
        unique.forEach((name) => {
          poblacionSelect.appendChild(createOption(name, name));
        });
        if (unique.length > 1) {
          poblacionSelect.classList.remove("hidden");
          poblacionSelect.dataset.provincia = provinciaValue || "";
        } else {
          poblacionSelect.classList.add("hidden");
          poblacionSelect.dataset.provincia = "";
        }
      }
    });
  };
  postalInput.addEventListener("input", () => {
    postalInput.value = normalizePostalCode(postalInput.value);
    applyPostal();
  });
  postalInput.addEventListener("blur", () => {
    postalInput.value = normalizePostalCode(postalInput.value);
    applyPostal();
  });
};

const GESTORIA_SUBTIPOS = {
  "Cuota mensual": ["Autónomo", "Empresa"],
  "Gestión administrativa": ["Cliente Renta", "Gestiones Administrativas", "Renta", "Puntual"],
};

const GESTORIA_TRABAJO_CATEGORIES = [
  { key: "laboral", label: "Laboral" },
  { key: "fiscal", label: "Fiscal" },
  { key: "contable", label: "Contable" },
  { key: "registro", label: "Registro Mercantil" },
  { key: "sociedades", label: "Sociedades" },
  { key: "rentas", label: "Rentas" },
  { key: "trafico", label: "Tráfico" },
  { key: "herencias", label: "Herencias" },
  { key: "expedientes", label: "Expedientes" },
  { key: "tasaciones", label: "Tasaciones" },
  { key: "otros", label: "Otros" },
];

const normalizeGestoriaTrabajoCategory = (value) => {
  const key = String(value || "").trim().toLowerCase();
  return GESTORIA_TRABAJO_CATEGORIES.some((item) => item.key === key) ? key : "";
};

const classifyGestoriaTrabajoCategory = (tipoTrabajo) => {
  const text = normalizeLookupText(tipoTrabajo || "");
  // Si existe catálogo configurable de tipos, lo usamos como fuente de verdad.
  try {
    const catalog = Array.isArray(state.gestoriaTrabajoTiposCache?.rows) ? state.gestoriaTrabajoTiposCache.rows : [];
    if (catalog.length && text) {
      const match = catalog.find((row) => {
        const nameNorm = normalizeLookupText(row?.nombre || "");
        const keyNorm = normalizeLookupText(String(row?.tipo_key || "").replace(/_/g, " "));
        return nameNorm === text || keyNorm === text;
      });
      if (match) {
        const cat = normalizeGestoriaTrabajoCategory(match.categoria);
        if (cat) return cat;
      }
    }
  } catch (e) {}
  if (!text) return "otros";
  if (text.includes("HERENC")) return "herencias";
  if (text.includes("TRAFIC") || text.includes("TRANSFER") || text.includes("MATRICUL")) return "trafico";
  if (text.includes("TASACI")) return "tasaciones";
  if (text.includes("RENTA") || text.includes("MODELO 100") || text.includes("DECLARACION")) return "rentas";
  if (
    text.includes("EXPEDIENT") ||
    text.includes("ADMINISTRAT") ||
    text.includes("IMV") ||
    text.includes("BECA") ||
    text.includes("BRECHA") ||
    text.includes("CONDOMINIO")
  ) {
    return "expedientes";
  }
  if (text.includes("LABOR")) return "laboral";
  if (
    text.includes("FISCAL") ||
    text.includes("HACIENDA") ||
    text.includes("AEAT") ||
    (text.includes("MODELO") && !text.includes("MODELO 100"))
  ) {
    return "fiscal";
  }
  if (text.includes("CONTAB")) return "contable";
  if (text.includes("REGISTRO") || text.includes("MERCANTIL")) return "registro";
  if (text.includes("CONSTITUCION") || text.includes("SOCIEDAD")) return "sociedades";
  return "otros";
};

const getGestoriaTrabajoCategoryLabel = (key) => {
  const k = normalizeGestoriaTrabajoCategory(key);
  const item = GESTORIA_TRABAJO_CATEGORIES.find((row) => row.key === k);
  return item ? item.label : "";
};

const ensureGestoriaTrabajoCategorySelects = () => {
  const configure = (selectEl, { placeholder = "" } = {}) => {
    if (!selectEl) return;
    const current = String(selectEl.value || "").trim();
    const currentKey = normalizeGestoriaTrabajoCategory(current) || classifyGestoriaTrabajoCategory(current);
    selectEl.innerHTML = "";
    if (placeholder) {
      selectEl.appendChild(createOption("", placeholder));
    }
    GESTORIA_TRABAJO_CATEGORIES.forEach((item) => {
      selectEl.appendChild(createOption(item.key, item.label));
    });
    selectEl.value = currentKey || "";
  };
  configure(gestoriaTrabajosTipoFilter, { placeholder: "Tipo (todos)" });
  configure(gestoriaPipelineServicio, { placeholder: "Todos los servicios" });

  // Selects en formularios (alta de trabajo) para fijar `tipo_categoria`.
  document.querySelectorAll('select[data-gestoria-categoria-select="1"]').forEach((selectEl) => {
    const current = String(selectEl.value || "").trim();
    const defaultKey = normalizeGestoriaTrabajoCategory(selectEl.dataset.default || "");
    const currentKey = normalizeGestoriaTrabajoCategory(current) || defaultKey || "";
    selectEl.innerHTML = "";
    GESTORIA_TRABAJO_CATEGORIES.forEach((item) => {
      selectEl.appendChild(createOption(item.key, item.label));
    });
    selectEl.value = currentKey || "otros";
    if (selectEl.dataset.bound !== "1") {
      selectEl.dataset.bound = "1";
      selectEl.addEventListener("change", () => {
        selectEl.dataset.override = "1";
      });
      const form = selectEl.closest("form");
      const tipoSel = form ? form.querySelector('select[name="tipo_trabajo"]') : null;
      if (tipoSel) {
        tipoSel.addEventListener("change", () => {
          if (selectEl.dataset.override === "1") return;
          const inferred = classifyGestoriaTrabajoCategory(String(tipoSel.value || ""));
          selectEl.value = defaultKey || inferred || "otros";
        });
      }
    }
  });
};

const loadGestoriaTrabajoTipos = async ({ force = false } = {}) => {
  const empresa = resolveCrmGestoriaEmpresa();
  if (!empresa) return [];
  const empresaId = resolveLegacyEmpresaId(empresa);
  const cacheAge = Date.now() - Number(state.gestoriaTrabajoTiposCache?.ts || 0);
  if (
    !force
    && state.gestoriaTrabajoTiposCache
    && String(state.gestoriaTrabajoTiposCache.scopeKey || "") === String(getGestoriaWorkspaceScopeKey() || empresaId || "")
    && cacheAge >= 0
    && cacheAge < 60000
  ) {
    return state.gestoriaTrabajoTiposCache.rows || [];
  }
  const params = buildGestoriaWorkspaceParams();
  const data = await api(`/api/gestoria_trabajo_tipos?${params.toString()}`).catch(() => ({ rows: [] }));
  const rows = Array.isArray(data?.rows) ? data.rows : [];
  state.gestoriaTrabajoTiposCache = { scopeKey: getGestoriaWorkspaceScopeKey() || empresaId, rows, ts: Date.now() };
  return rows;
};

const hydrateGestoriaTrabajoTipoSelect = (selectEl, rows = [], { placeholder = "" } = {}) => {
  if (!selectEl) return;
  const current = String(selectEl.value || "").trim();
  const active = (Array.isArray(rows) ? rows : [])
    .filter((row) => String(row?.nombre || "").trim())
    .filter((row) => Number(row?.activo ?? 1) !== 0)
    .sort((a, b) => {
      const ao = Number(a?.orden ?? 0) || 0;
      const bo = Number(b?.orden ?? 0) || 0;
      if (ao !== bo) return ao - bo;
      return String(a?.nombre || "").localeCompare(String(b?.nombre || ""), "es", { sensitivity: "base" });
    });
  selectEl.innerHTML = "";
  if (placeholder) selectEl.appendChild(createOption("", placeholder));
  active.forEach((row) => {
    const label = String(row.nombre || "").trim();
    const opt = createOption(label, label);
    opt.dataset.key = String(row.tipo_key || "");
    opt.dataset.categoria = String(row.categoria || "");
    opt.dataset.sla = String(row.sla_dias ?? "");
    opt.dataset.ivaPct = String(row.iva_pct ?? "");
    opt.dataset.precioBase = String(row.precio_base ?? "");
    selectEl.appendChild(opt);
  });
  const match = active.find((row) => String(row.nombre || "").trim() === current);
  if (match) selectEl.value = current;
  else if (!String(selectEl.value || "").trim() && active.length) selectEl.value = String(active[0].nombre || "").trim();
};

const getGestoriaTipoMeta = (selectEl) => {
  const opt = selectEl?.selectedOptions?.[0];
  if (!opt) return {};
  const sla = parseInt(String(opt.dataset.sla || "").trim(), 10);
  const ivaPct = parseFloat(String(opt.dataset.ivaPct || "").trim());
  const precioBase = parseFloat(String(opt.dataset.precioBase || "").trim());
  return {
    nombre: String(opt.value || "").trim(),
    tipo_key: String(opt.dataset.key || "").trim(),
    categoria: String(opt.dataset.categoria || "").trim(),
    sla_dias: Number.isFinite(sla) ? sla : null,
    iva_pct: Number.isFinite(ivaPct) ? ivaPct : null,
    precio_base: Number.isFinite(precioBase) ? precioBase : null,
  };
};

const bindGestoriaTipoDefaults = (selectEl, handler) => {
  if (!selectEl) return;
  if (selectEl.dataset.boundDefaults === "1") {
    handler(selectEl);
    return;
  }
  selectEl.dataset.boundDefaults = "1";
  const apply = () => handler(selectEl);
  selectEl.addEventListener("change", apply);
  apply();
};

const persistGestoriaTrabajoTipo = async (payload = {}) => {
  const empresa = resolveCrmGestoriaEmpresa();
  const empresaId = resolveLegacyEmpresaId(empresa);
  if (!empresaId) throw new Error("Sin workspace.");
  const usuario = getCurrentUser();
  const res = await fetch("/api/gestoria_trabajo_tipos_update", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ ...payload, empresa_id: empresaId, empresa_nombre: empresa.nombre || "", usuario }),
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok || data?.error) throw new Error(data?.error || `HTTP ${res.status}`);
  return data;
};

const deleteGestoriaTrabajoTipo = async (id) => {
  const empresa = resolveCrmGestoriaEmpresa();
  const empresaId = resolveLegacyEmpresaId(empresa);
  if (!empresaId) throw new Error("Sin workspace.");
  const usuario = getCurrentUser();
  const res = await fetch("/api/gestoria_trabajo_tipos_delete", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ id, empresa_id: empresaId, empresa_nombre: empresa.nombre || "", usuario }),
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok || data?.error) throw new Error(data?.error || `HTTP ${res.status}`);
  return data;
};

const seedGestoriaTrabajoTipoTemplate = ({ tipo_key = "", categoria = "" } = {}) =>
  JSON.stringify(
    {
      version: 1,
      tipo_key: String(tipo_key || "").trim() || undefined,
      categoria: String(categoria || "").trim() || undefined,
      checklist: [
        { key: "identificacion", label: "DNI/NIE/CIF", required: true },
        { key: "autorizacion", label: "Autorización/encargo", required: false },
      ],
      entregables: [{ key: "resolucion", label: "Justificante/Documento final", required: true }],
      notas_default: "",
    },
    null,
    2
  );

const openGestoriaTrabajoTipoTemplateModal = (row = {}) => {
  if (!gestoriaTrabajoTipoTemplateModal || !gestoriaTrabajoTipoTemplateJson) return false;
  const id = String(row.id || "").trim();
  if (!id) {
    window.alert("Guarda el tipo antes de editar la plantilla.");
    return false;
  }
  state.gestoriaTrabajoTipoTemplateEditingId = id;
  state.gestoriaTrabajoTipoTemplateEditingRow = { ...row };
  if (gestoriaTrabajoTipoTemplateNombre) {
    gestoriaTrabajoTipoTemplateNombre.value = String(row.nombre || "").trim() || "(sin nombre)";
  }
  let text = String(row.plantilla_json || "").trim();
  if (text) {
    try {
      text = JSON.stringify(JSON.parse(text), null, 2);
    } catch (e) {}
  }
  gestoriaTrabajoTipoTemplateJson.value = text;
  if (gestoriaTrabajoTipoTemplateStatus) gestoriaTrabajoTipoTemplateStatus.textContent = "";
  gestoriaTrabajoTipoTemplateModal.classList.remove("hidden");
  document.body.classList.add("modal-open");
  try {
    gestoriaTrabajoTipoTemplateJson.focus();
  } catch (e) {}
  return true;
};

const closeGestoriaTrabajoTipoTemplateModal = () => {
  if (!gestoriaTrabajoTipoTemplateModal) return;
  gestoriaTrabajoTipoTemplateModal.classList.add("hidden");
  document.body.classList.remove("modal-open");
  state.gestoriaTrabajoTipoTemplateEditingId = "";
  state.gestoriaTrabajoTipoTemplateEditingRow = null;
  if (gestoriaTrabajoTipoTemplateStatus) gestoriaTrabajoTipoTemplateStatus.textContent = "";
};

if (gestoriaTrabajoTipoTemplateModalClose) {
  gestoriaTrabajoTipoTemplateModalClose.addEventListener("click", closeGestoriaTrabajoTipoTemplateModal);
}
if (gestoriaTrabajoTipoTemplateCancelBtn) {
  gestoriaTrabajoTipoTemplateCancelBtn.addEventListener("click", closeGestoriaTrabajoTipoTemplateModal);
}
if (gestoriaTrabajoTipoTemplateModal) {
  gestoriaTrabajoTipoTemplateModal.addEventListener("click", (event) => {
    if (event.target === gestoriaTrabajoTipoTemplateModal) closeGestoriaTrabajoTipoTemplateModal();
  });
}
if (gestoriaTrabajoTipoTemplateSeedBtn && gestoriaTrabajoTipoTemplateJson) {
  gestoriaTrabajoTipoTemplateSeedBtn.addEventListener("click", () => {
    const current = String(gestoriaTrabajoTipoTemplateJson.value || "").trim();
    if (current) {
      const ok = window.confirm("Ya hay contenido. ¿Reemplazar por una plantilla base?");
      if (!ok) return;
    }
    const row = state.gestoriaTrabajoTipoTemplateEditingRow || {};
    gestoriaTrabajoTipoTemplateJson.value = seedGestoriaTrabajoTipoTemplate({
      tipo_key: row?.tipo_key || "",
      categoria: row?.categoria || "",
    });
  });
}
if (gestoriaTrabajoTipoTemplateSaveBtn) {
  gestoriaTrabajoTipoTemplateSaveBtn.addEventListener("click", async () => {
    const id = String(state.gestoriaTrabajoTipoTemplateEditingId || "").trim();
    const base = state.gestoriaTrabajoTipoTemplateEditingRow || null;
    if (!id || !base) return;
    const raw = String(gestoriaTrabajoTipoTemplateJson?.value || "").trim();
    let normalized = "";
    if (raw) {
      try {
        normalized = JSON.stringify(JSON.parse(raw), null, 0);
      } catch (e) {
        if (gestoriaTrabajoTipoTemplateStatus) {
          gestoriaTrabajoTipoTemplateStatus.textContent = "JSON inválido: revisa comillas y llaves.";
        }
        return;
      }
    }
    gestoriaTrabajoTipoTemplateSaveBtn.disabled = true;
    if (gestoriaTrabajoTipoTemplateStatus) gestoriaTrabajoTipoTemplateStatus.textContent = "Guardando...";
    try {
      await persistGestoriaTrabajoTipo({
        id,
        nombre: base.nombre,
        tipo_key: base.tipo_key,
        categoria: base.categoria,
        orden: base.orden,
        color: base.color,
        sla_dias: base.sla_dias,
        iva_pct: base.iva_pct,
        precio_base: base.precio_base,
        activo: base.activo,
        plantilla_json: normalized,
      });
      const refreshed = await loadGestoriaTrabajoTipos({ force: true });
      hydrateGestoriaTrabajoTipoSelect(gestoriaTrabajoTipoSelect, refreshed, { placeholder: "Tipo de gestión" });
      hydrateGestoriaTrabajoTipoSelect(gestoriaBudgetTipoTrabajo, refreshed);
      renderGestoriaTrabajoTiposAdmin(refreshed);
      closeGestoriaTrabajoTipoTemplateModal();
    } catch (e) {
      if (gestoriaTrabajoTipoTemplateStatus) gestoriaTrabajoTipoTemplateStatus.textContent = String(e?.message || e || "No se pudo guardar.");
    } finally {
      gestoriaTrabajoTipoTemplateSaveBtn.disabled = false;
    }
  });
}

const renderGestoriaTrabajoTiposAdmin = (rows = []) => {
  if (!gestoriaTrabajoTiposCard || !gestoriaTrabajoTiposTable || !gestoriaTrabajoTiposInfo) return;
  const isAdmin = canAccessGestoriaAdminDashboard();
  gestoriaTrabajoTiposCard.classList.toggle("hidden", !isAdmin);
  if (!isAdmin) return;

  const items = Array.isArray(rows) ? rows : [];
  const table = document.createElement("table");
  const thead = document.createElement("thead");
  const trHead = document.createElement("tr");
  ["orden", "nombre", "key", "categoria", "color", "sla", "iva%", "precio", "plantilla", "activo", "acciones"].forEach((col) => {
    const th = document.createElement("th");
    th.textContent = formatHeader(col);
    trHead.appendChild(th);
  });
  thead.appendChild(trHead);
  table.appendChild(thead);
  const tbody = document.createElement("tbody");

  const buildCategorySelect = (current) => {
    const sel = document.createElement("select");
    GESTORIA_TRABAJO_CATEGORIES.forEach((cat) => sel.appendChild(createOption(cat.key, cat.label)));
    sel.value = normalizeGestoriaTrabajoCategory(current) || classifyGestoriaTrabajoCategory(current) || "otros";
    return sel;
  };

  items.forEach((row) => {
    const tr = document.createElement("tr");
    const ordenInput = document.createElement("input");
    ordenInput.type = "number";
    ordenInput.value = row.orden ?? "";
    ordenInput.style.maxWidth = "84px";

    const nombreInput = document.createElement("input");
    nombreInput.value = row.nombre || "";

    const keyInput = document.createElement("input");
    keyInput.value = row.tipo_key || "";
    keyInput.placeholder = "auto";

    const catSel = buildCategorySelect(row.categoria);

    const colorInput = document.createElement("input");
    colorInput.type = "color";
    colorInput.value = String(row.color || "").trim() || "#0B1D33";
    colorInput.style.maxWidth = "64px";

    const slaInput = document.createElement("input");
    slaInput.type = "number";
    slaInput.value = row.sla_dias ?? "";
    slaInput.style.maxWidth = "86px";

    const ivaInput = document.createElement("input");
    ivaInput.type = "number";
    ivaInput.step = "0.01";
    ivaInput.value = row.iva_pct ?? "";
    ivaInput.style.maxWidth = "86px";

    const precioInput = document.createElement("input");
    precioInput.type = "number";
    precioInput.step = "0.01";
    precioInput.value = row.precio_base ?? "";
    precioInput.style.maxWidth = "110px";

    const plantillaBtn = document.createElement("button");
    plantillaBtn.type = "button";
    plantillaBtn.className = "secondary ghost";
    plantillaBtn.textContent = String(row.plantilla_json || "").trim() ? "Editar" : "Añadir";
    plantillaBtn.disabled = !String(row.id || "").trim();
    plantillaBtn.addEventListener("click", () => openGestoriaTrabajoTipoTemplateModal(row));

    const activoInput = document.createElement("input");
    activoInput.type = "checkbox";
    activoInput.checked = Number(row.activo ?? 1) !== 0;

    const actions = document.createElement("div");
    actions.className = "toolbar";
    const saveBtn = document.createElement("button");
    saveBtn.type = "button";
    saveBtn.className = "secondary";
    saveBtn.textContent = "Guardar";

    const delBtn = document.createElement("button");
    delBtn.type = "button";
    delBtn.className = "secondary ghost";
    delBtn.textContent = "Borrar";
    delBtn.disabled = !String(row.id || "").trim();

    saveBtn.addEventListener("click", async () => {
      saveBtn.disabled = true;
      try {
        const payload = {
          id: String(row.id || "").trim(),
          nombre: String(nombreInput.value || "").trim(),
          tipo_key: String(keyInput.value || "").trim(),
          categoria: String(catSel.value || "").trim(),
          orden: String(ordenInput.value || "").trim(),
          color: String(colorInput.value || "").trim(),
          sla_dias: String(slaInput.value || "").trim(),
          iva_pct: String(ivaInput.value || "").trim(),
          precio_base: String(precioInput.value || "").trim(),
          activo: activoInput.checked ? 1 : 0,
          plantilla_json: row.plantilla_json ?? "",
        };
        await persistGestoriaTrabajoTipo(payload);
        const refreshed = await loadGestoriaTrabajoTipos({ force: true });
        hydrateGestoriaTrabajoTipoSelect(gestoriaTrabajoTipoSelect, refreshed, { placeholder: "Tipo de gestión" });
        hydrateGestoriaTrabajoTipoSelect(gestoriaBudgetTipoTrabajo, refreshed);
        renderGestoriaTrabajoTiposAdmin(refreshed);
      } catch (e) {
        window.alert(String(e?.message || e || "No se pudo guardar."));
      } finally {
        saveBtn.disabled = false;
      }
    });

    delBtn.addEventListener("click", async () => {
      if (!String(row.id || "").trim()) return;
      if (!window.confirm("¿Borrar este tipo de trabajo?")) return;
      delBtn.disabled = true;
      try {
        await deleteGestoriaTrabajoTipo(String(row.id || "").trim());
        const refreshed = await loadGestoriaTrabajoTipos({ force: true });
        hydrateGestoriaTrabajoTipoSelect(gestoriaTrabajoTipoSelect, refreshed, { placeholder: "Tipo de gestión" });
        hydrateGestoriaTrabajoTipoSelect(gestoriaBudgetTipoTrabajo, refreshed);
        renderGestoriaTrabajoTiposAdmin(refreshed);
      } catch (e) {
        window.alert(String(e?.message || e || "No se pudo borrar."));
      } finally {
        delBtn.disabled = false;
      }
    });

    actions.appendChild(saveBtn);
    actions.appendChild(delBtn);

    const cells = [ordenInput, nombreInput, keyInput, catSel, colorInput, slaInput, ivaInput, precioInput, plantillaBtn, activoInput, actions];
    cells.forEach((node) => {
      const td = document.createElement("td");
      td.appendChild(node);
      tr.appendChild(td);
    });
    tbody.appendChild(tr);
  });

  table.appendChild(tbody);
  gestoriaTrabajoTiposTable.innerHTML = "";
  gestoriaTrabajoTiposTable.appendChild(table);
  gestoriaTrabajoTiposInfo.textContent = `${items.length} tipos`;
};

const sumTotals = (items) =>
  items.reduce((acc, item) => acc + (item.total || 0), 0);

const getYearValueFromSeries = (series, year) => {
  const target = normalizeYear(year);
  const entry = series.find((item) => normalizeYear(item.year) === target);
  return entry ? entry.total || 0 : 0;
};

const computeVariations = (series) => {
  const sorted = [...series]
    .filter((item) => item.year !== null && item.year !== undefined)
    .map((item) => ({ year: normalizeYear(item.year), total: item.total || 0 }))
    .sort((a, b) => Number(a.year) - Number(b.year));
  const output = [];
  for (let i = 1; i < sorted.length; i += 1) {
    const prev = sorted[i - 1].total;
    const current = sorted[i].total;
    const change = prev === 0 ? 0 : ((current - prev) / prev) * 100;
    output.push({ year: sorted[i].year, total: change });
  }
  return output;
};

const buildYearIndex = (series) => {
  const years = new Set();
  series.forEach((items) =>
    items.forEach((item) => {
      const normalized = normalizeYear(item.year);
      if (normalized) {
        years.add(normalized);
      }
    })
  );
  return Array.from(years).sort();
};

const alignSeries = (years, items) => {
  const lookup = new Map(
    items.map((item) => [normalizeYear(item.year), item.total])
  );
  return years.map((year) => lookup.get(normalizeYear(year)) || 0);
};

const prepareCanvas = (canvas) => {
  const ratio = window.devicePixelRatio || 1;
  const rect = canvas.getBoundingClientRect();
  let width = rect.width;
  let height = rect.height;
  if (width < 10 || height < 10) {
    const parent = canvas.parentElement;
    const parentWidth = parent ? parent.clientWidth : 0;
    width = parentWidth && parentWidth > 10 ? parentWidth : 600;
    height = height && height > 10 ? height : 300;
    canvas.style.width = `${width}px`;
    canvas.style.height = `${height}px`;
  }
  canvas.width = width * ratio;
  canvas.height = height * ratio;
  const ctx = canvas.getContext("2d");
  ctx.scale(ratio, ratio);
  return ctx;
};

const getCssVar = (el, name, fallback = "") => {
  try {
    const value = window.getComputedStyle(el).getPropertyValue(name).trim();
    return value || fallback;
  } catch {
    return fallback;
  }
};

const safeHexWithAlpha = (hex, alpha = 1) => {
  const raw = String(hex || "").trim();
  if (!raw.startsWith("#") || raw.length !== 7) return raw || "#000000";
  const r = parseInt(raw.slice(1, 3), 16);
  const g = parseInt(raw.slice(3, 5), 16);
  const b = parseInt(raw.slice(5, 7), 16);
  const a = Math.max(0, Math.min(1, Number(alpha)));
  return `rgba(${r}, ${g}, ${b}, ${a})`;
};

const fillRoundedRect = (ctx, x, y, w, h, r = 8) => {
  const width = Number(w) || 0;
  const height = Number(h) || 0;
  if (width <= 0 || height <= 0) return;
  const radius = Math.max(0, Math.min(Number(r) || 0, Math.min(width, height) / 2));
  if (typeof ctx.roundRect === "function") {
    ctx.beginPath();
    ctx.roundRect(x, y, width, height, radius);
    ctx.fill();
    return;
  }
  ctx.beginPath();
  ctx.moveTo(x + radius, y);
  ctx.lineTo(x + width - radius, y);
  ctx.quadraticCurveTo(x + width, y, x + width, y + radius);
  ctx.lineTo(x + width, y + height - radius);
  ctx.quadraticCurveTo(x + width, y + height, x + width - radius, y + height);
  ctx.lineTo(x + radius, y + height);
  ctx.quadraticCurveTo(x, y + height, x, y + height - radius);
  ctx.lineTo(x, y + radius);
  ctx.quadraticCurveTo(x, y, x + radius, y);
  ctx.closePath();
  ctx.fill();
};

const formatCompactNumberEs = (value, { suffix = "", decimals = 1 } = {}) => {
  const num = Number(value || 0);
  const abs = Math.abs(num);
  const sign = num < 0 ? "-" : "";
  const d = Math.max(0, Math.min(2, Number(decimals ?? 1)));
  const fmt = (n) =>
    new Intl.NumberFormat("es-ES", { minimumFractionDigits: 0, maximumFractionDigits: d }).format(n);
  if (abs >= 1e9) return `${sign}${fmt(abs / 1e9)} B${suffix}`;
  if (abs >= 1e6) return `${sign}${fmt(abs / 1e6)} M${suffix}`;
  if (abs >= 1e3) return `${sign}${fmt(abs / 1e3)} k${suffix}`;
  return `${sign}${new Intl.NumberFormat("es-ES").format(abs)}${suffix}`;
};

const niceAxisMax = (rawMax) => {
  const max = Math.max(0, Number(rawMax || 0));
  if (!max) return 1;
  const target = max * 1.08; // headroom
  const exp = Math.floor(Math.log10(target));
  const base = 10 ** exp;
  const f = target / base;
  const nf = f <= 1 ? 1 : f <= 2 ? 2 : f <= 2.5 ? 2.5 : f <= 5 ? 5 : 10;
  return nf * base;
};

const drawBarChart = (canvas, labels, datasets, options = {}) => {
  if (!canvas) return;
  const ctx = prepareCanvas(canvas);
  const rect = canvas.getBoundingClientRect();
  let width = rect.width;
  let height = rect.height;
  if (width < 10 || height < 10) {
    width = canvas.width || 600;
    height = canvas.height || 300;
    canvas.style.width = `${width}px`;
    canvas.style.height = `${height}px`;
  }
  ctx.clearRect(0, 0, width, height);

  const interactive = typeof options.onBarClick === "function";
  const hitAreas = [];
  if (canvas.__barChartHandlers) {
    try {
      canvas.removeEventListener("click", canvas.__barChartHandlers.click);
      canvas.removeEventListener("mousemove", canvas.__barChartHandlers.move);
    } catch (e) {}
    canvas.__barChartHandlers = null;
  }

  const theme = {
    grid: getCssVar(canvas, "--chart-grid", "rgba(11, 29, 51, 0.08)"),
    axis: getCssVar(canvas, "--chart-axis", "rgba(11, 29, 51, 0.22)"),
    label: getCssVar(canvas, "--chart-label", "rgba(11, 29, 51, 0.72)"),
    muted: getCssVar(canvas, "--chart-muted", "rgba(11, 29, 51, 0.56)"),
    ink: getCssVar(canvas, "--ink", "#0B1D33"),
    gold: getCssVar(canvas, "--gold", "#F2C14E"),
    bg: getCssVar(canvas, "--chart-bg", "rgba(255,255,255,0.92)"),
    fontBody: getCssVar(canvas, "--font-body", "system-ui, sans-serif"),
    fontUi: getCssVar(canvas, "--font-ui", "system-ui, sans-serif"),
  };

  // Background (refuerza la identidad visual incluso si el card cambia).
  ctx.fillStyle = theme.bg;
  ctx.fillRect(0, 0, width, height);

  const labelCount = Math.max(1, labels.length);
  const maxLabelLen = labels.reduce(
    (acc, label) => Math.max(acc, String(label || "").length),
    0
  );
  const estimatedGroupWidth = (width - 58) / labelCount;
  const crowdedAxis =
    labelCount >= 10 || estimatedGroupWidth < 42 || maxLabelLen > 16;
  const heavyCrowding =
    labelCount >= 16 || estimatedGroupWidth < 32 || maxLabelLen > 22;
  const rotateLabels =
    options.rotateLabels ?? (crowdedAxis || estimatedGroupWidth < 36);
  const labelFontSize =
    heavyCrowding ? 9 : crowdedAxis ? 10 : 11;
  const labelSkipStep = options.labelSkipStep
    || (labelCount >= 26 ? 4 : labelCount >= 18 ? 3 : labelCount >= 13 ? 2 : 1);
  const rotationAngle = options.labelRotationAngle
    || (heavyCrowding ? Math.PI / 3.2 : Math.PI / 5.2);
  const axisMaxChars = options.axisLabelMaxChars
    || (rotateLabels ? (heavyCrowding ? 16 : 20) : Math.max(8, Math.floor(estimatedGroupWidth / 6)));
  const axisBottomPadding = options.axisBottomPadding
    || (rotateLabels ? (heavyCrowding ? 112 : 96) : 56);
  const legendPosition = options.legendPosition || "top";
  let legendRightPadding = 0;
  if (options.legend && legendPosition === "right") {
    ctx.font = `700 11px ${theme.fontUi}`;
    const maxLegendTextWidth = datasets.reduce((acc, dataset) => {
      const widthText = ctx.measureText(String(dataset.label || "")).width;
      return Math.max(acc, widthText);
    }, 0);
    const desired = Math.ceil(maxLegendTextWidth + 34);
    legendRightPadding = Math.max(110, Math.min(220, desired));
  }

  const padding = {
    top: 22,
    right: 18 + legendRightPadding,
    bottom: axisBottomPadding,
    left: 40,
  };
  const chartWidth = width - padding.left - padding.right;
  const chartHeight = height - padding.top - padding.bottom;
  const secondaryLineSets = datasets.filter(
    (set) => set.type === "line" && set.yAxis === "right"
  );
  const primarySets = datasets.filter(
    (set) => !(set.type === "line" && set.yAxis === "right")
  );
  const normalizedChartValues = primarySets.flatMap((set) =>
    (set.values || []).map((val) => {
      const n = Number(val || 0);
      if (set.type === "line" && set.scale === "percent") {
        return n / 100;
      }
      return n;
    })
  );
  const rawMaxValue = Math.max(
    1,
    ...normalizedChartValues.map((val) => Math.abs(val))
  );
  const maxValue = options.niceScale === false ? rawMaxValue : niceAxisMax(rawMaxValue);
  const secondaryValues = secondaryLineSets.flatMap((set) =>
    (set.values || []).map((val) => Number(val || 0))
  );
  const hasSecondaryAxis = secondaryValues.length > 0;
  const secondaryMinRaw = hasSecondaryAxis ? Math.min(...secondaryValues) : 0;
  const secondaryMaxRaw = hasSecondaryAxis ? Math.max(...secondaryValues) : 0;
  const secondaryMin = hasSecondaryAxis ? Math.min(secondaryMinRaw, 0) : 0;
  const secondaryMax =
    hasSecondaryAxis
      ? secondaryMaxRaw === secondaryMin
        ? secondaryMin + 1
        : secondaryMaxRaw
      : 1;
  const secondaryRange = Math.max(1, secondaryMax - secondaryMin);

  const gridLines = 4;
  ctx.strokeStyle = theme.grid;
  ctx.lineWidth = 1;
  const axisFormat =
    typeof options.yAxisFormat === "function"
      ? options.yAxisFormat
      : (value) => formatCompactNumberEs(value);
  for (let i = 0; i <= gridLines; i += 1) {
    const y = padding.top + (chartHeight / gridLines) * i;
    ctx.beginPath();
    ctx.moveTo(padding.left, y);
    ctx.lineTo(width - padding.right, y);
    ctx.stroke();
    if (options.showYAxisLabels) {
      const ratio = i / gridLines;
      const value = maxValue - ratio * maxValue;
      const text = axisFormat(value);
      ctx.fillStyle = theme.muted;
      ctx.font = `500 10px ${theme.fontBody}`;
      const tw = ctx.measureText(text).width;
      ctx.fillText(text, Math.max(2, padding.left - tw - 6), y - 2);
    }
  }

  ctx.strokeStyle = theme.axis;
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(padding.left, padding.top);
  ctx.lineTo(padding.left, height - padding.bottom);
  ctx.lineTo(width - padding.right, height - padding.bottom);
  ctx.stroke();

  if (hasSecondaryAxis) {
    ctx.strokeStyle = theme.axis;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(width - padding.right, padding.top);
    ctx.lineTo(width - padding.right, height - padding.bottom);
    ctx.stroke();
    const rightFormat =
      options.secondaryAxisFormat || ((value) => numberFormatter.format(value));
    ctx.fillStyle = theme.muted;
    ctx.font = `500 10px ${theme.fontBody}`;
    for (let i = 0; i <= gridLines; i += 1) {
      const ratio = i / gridLines;
      const value = secondaryMax - ratio * secondaryRange;
      const y = padding.top + (chartHeight / gridLines) * i;
      const text = rightFormat(value);
      const textWidth = ctx.measureText(text).width;
      ctx.fillText(text, width - padding.right - textWidth - 4, y - 2);
    }
  }

  const groupWidth = chartWidth / Math.max(1, labels.length);
  const barSets = datasets.filter((set) => set.type !== "line");
  const barWidth = Math.max(6, (groupWidth - 18) / Math.max(1, barSets.length));
  const showZeroBars = Boolean(options.showZeroBars);
  const zeroBarHeight = Math.max(2, Number(options.zeroBarHeight || 2));
  const getTextColorForBar = (color) => {
    const value = String(color || "").trim();
    const hex = value.startsWith("#") ? value.slice(1) : "";
    if (hex.length !== 6) return "#ffffff";
    const r = parseInt(hex.slice(0, 2), 16);
    const g = parseInt(hex.slice(2, 4), 16);
    const b = parseInt(hex.slice(4, 6), 16);
    const luminance = (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255;
    return luminance > 0.56 ? "#1f1a16" : "#ffffff";
  };

  labels.forEach((label, i) => {
    const xBase = padding.left + i * groupWidth;
    barSets.forEach((dataset, j) => {
      const value = Number(dataset.values[i] ?? 0) || 0;
      let barHeight = (Math.abs(value) / maxValue) * chartHeight;
      const isZero = Math.abs(value) < 1e-9;
      if (showZeroBars && isZero) {
        barHeight = Math.max(barHeight || 0, zeroBarHeight);
      }
      const x = xBase + 5 + j * barWidth;
      const y = height - padding.bottom - barHeight;
      const barColor =
        (dataset.colors && dataset.colors[i]) ||
        dataset.color ||
        (j % 2 === 0 ? theme.gold : theme.ink);
      ctx.fillStyle = (showZeroBars && isZero) ? safeHexWithAlpha(barColor, 0.22) : barColor;
      fillRoundedRect(ctx, x, y, barWidth, barHeight, Math.min(10, barWidth / 2));
      if (interactive) {
        hitAreas.push({
          x,
          y,
          w: barWidth,
          h: barHeight,
          labelIndex: i,
          datasetIndex: j,
          label: String(label || ""),
          datasetLabel: String(dataset.label || ""),
          value,
        });
      }

      if (options.showValues && barHeight >= 18 && labels.length <= 18 && groupWidth >= 24) {
        const labelText = dataset.format
          ? dataset.format(value)
          : numberFormatter.format(value);
        ctx.font = `700 10px ${theme.fontUi}`;
        const textWidth = ctx.measureText(labelText).width;
        const textX = x + (barWidth - textWidth) / 2;
        const textY = y + 14;
        ctx.fillStyle = getTextColorForBar(barColor);
        ctx.strokeStyle = safeHexWithAlpha(theme.ink, 0.18);
        ctx.lineWidth = 2;
        ctx.strokeText(labelText, textX, textY);
        ctx.fillText(labelText, textX, textY);
      }
    });

    const labelText = String(label);
    const axisLabel =
      labelText.length > axisMaxChars
        ? `${labelText.slice(0, Math.max(1, axisMaxChars - 1))}…`
        : labelText;
    const shouldRotate = rotateLabels || groupWidth < 40;
    const shouldSkip = labelSkipStep > 1 && i % labelSkipStep !== 0;
    if (!shouldSkip) {
      ctx.fillStyle = theme.label;
      ctx.font = `600 ${labelFontSize}px ${theme.fontBody}`;
      if (shouldRotate) {
        ctx.save();
        const labelX = xBase + Math.max(0, (groupWidth - ctx.measureText(axisLabel).width) / 2);
        const labelY = height - 6;
        ctx.translate(labelX, labelY);
        ctx.rotate(-rotationAngle);
        ctx.fillText(axisLabel, 0, 0);
        ctx.restore();
      } else {
        const labelX = xBase + Math.max(0, (groupWidth - ctx.measureText(axisLabel).width) / 2);
        const labelY = height - 6;
        ctx.fillText(axisLabel, labelX, labelY);
      }
    }
  });

  if (interactive && hitAreas.length) {
    const within = (area, px, py) =>
      px >= area.x && px <= area.x + area.w && py >= area.y && py <= area.y + area.h;
    const onMove = (ev) => {
      const x = ev.offsetX;
      const y = ev.offsetY;
      const found = hitAreas.find((area) => within(area, x, y));
      canvas.style.cursor = found ? "pointer" : "";
    };
    const onClick = (ev) => {
      const x = ev.offsetX;
      const y = ev.offsetY;
      const found = hitAreas.find((area) => within(area, x, y));
      if (!found) return;
      try {
        options.onBarClick(found);
      } catch (e) {}
    };
    canvas.__barChartHandlers = { click: onClick, move: onMove };
    canvas.addEventListener("mousemove", onMove);
    canvas.addEventListener("click", onClick);
  }

  const lineSets = datasets.filter((set) => set.type === "line");
  if (lineSets.length) {
    lineSets.forEach((dataset) => {
      ctx.strokeStyle = dataset.color || theme.ink;
      ctx.lineWidth = Number(dataset.lineWidth || 2);
      ctx.beginPath();
      dataset.values.forEach((value, i) => {
        let y;
        if (dataset.yAxis === "right" && hasSecondaryAxis) {
          const normalized = (Number(value || 0) - secondaryMin) / secondaryRange;
          y = height - padding.bottom - normalized * chartHeight;
        } else {
          const normalized = dataset.scale === "percent" ? (value / 100) * maxValue : value;
          y =
            height -
            padding.bottom -
            (Math.abs(normalized) / maxValue) * chartHeight;
        }
        const x = padding.left + i * groupWidth + groupWidth / 2;
        if (i === 0) {
          ctx.moveTo(x, y);
        } else {
          ctx.lineTo(x, y);
        }
      });
      ctx.stroke();
      dataset.values.forEach((value, i) => {
        let y;
        if (dataset.yAxis === "right" && hasSecondaryAxis) {
          const normalized = (Number(value || 0) - secondaryMin) / secondaryRange;
          y = height - padding.bottom - normalized * chartHeight;
        } else {
          const normalized = dataset.scale === "percent" ? (value / 100) * maxValue : value;
          y =
            height -
            padding.bottom -
            (Math.abs(normalized) / maxValue) * chartHeight;
        }
        const x = padding.left + i * groupWidth + groupWidth / 2;
        ctx.fillStyle = dataset.color || theme.ink;
        ctx.beginPath();
        ctx.arc(x, y, Number(dataset.pointRadius || 3), 0, Math.PI * 2);
        ctx.fill();
        if (dataset.showPointValues && i % Math.max(1, Number(dataset.pointLabelStep || 2)) === 0) {
          const valueText = dataset.format
            ? dataset.format(value)
            : numberFormatter.format(Number(value || 0));
          ctx.fillStyle = dataset.color || theme.ink;
          ctx.font = `700 10px ${theme.fontUi}`;
          ctx.fillText(valueText, x + 4, y - 6);
        }
      });
    });
  }

  if (options.legend) {
    ctx.font = `700 11px ${theme.fontUi}`;
    if (legendPosition === "right") {
      const legendStartX = width - legendRightPadding + 8;
      let legendY = padding.top + 2;
      datasets.forEach((dataset) => {
        ctx.fillStyle = dataset.color || theme.gold;
        ctx.fillRect(legendStartX, legendY, 10, 10);
        ctx.fillStyle = theme.label;
        ctx.fillText(String(dataset.label || ""), legendStartX + 14, legendY + 9);
        legendY += 18;
      });
    } else {
      let offsetX = padding.left;
      const offsetY = padding.top - 12;
      datasets.forEach((dataset) => {
        ctx.fillStyle = dataset.color || theme.gold;
        ctx.fillRect(offsetX, offsetY, 10, 10);
        ctx.fillStyle = theme.label;
        ctx.fillText(String(dataset.label || ""), offsetX + 14, offsetY + 9);
        offsetX += ctx.measureText(String(dataset.label || "")).width + 30;
      });
    }
  }

  if (options.tooltip) {
    attachChartTooltip(canvas, {
      labels,
      datasets,
      groupWidth,
      padding,
    });
  }
};

const attachChartTooltip = (canvas, meta) => {
  if (!canvas || canvas.dataset.tooltip === "1") return;
  canvas.dataset.tooltip = "1";
  const tooltip = document.createElement("div");
  tooltip.className = "chart-tooltip hidden";
  canvas.parentElement?.appendChild(tooltip);

  const formatValue = (dataset, value) =>
    dataset.format ? dataset.format(value) : numberFormatter.format(value);

  const handleMove = (event) => {
    const rect = canvas.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const index = Math.floor((x - meta.padding.left) / meta.groupWidth);
    if (index < 0 || index >= meta.labels.length) {
      tooltip.classList.add("hidden");
      return;
    }
    const label = meta.labels[index];
    const lines = [`${label}`];
    meta.datasets.forEach((dataset) => {
      const value = dataset.values[index];
      lines.push(`${dataset.label}: ${formatValue(dataset, value)}`);
    });
    tooltip.innerHTML = lines.map((line) => `<div>${line}</div>`).join("");
    tooltip.style.left = `${Math.min(rect.width - 140, Math.max(12, x + 12))}px`;
    tooltip.style.top = `${Math.max(12, event.clientY - rect.top - 40)}px`;
    tooltip.classList.remove("hidden");
  };

  const handleLeave = () => {
    tooltip.classList.add("hidden");
  };

  canvas.addEventListener("mousemove", handleMove);
  canvas.addEventListener("mouseleave", handleLeave);
};

const saveTimers = new Map();
const pendingInlineEdits = {
  inmueble: new Map(),
  captacion: new Map(),
};

const setInmuebleSaveStatus = (text) => {
  if (!inmuebleSaveStatus) {
    return;
  }
  inmuebleSaveStatus.textContent = text || "";
  if (String(text || "").trim().startsWith("Guardado")) {
    window.clearTimeout(inmuebleSaveStatus._timer);
    inmuebleSaveStatus._timer = window.setTimeout(() => {
      inmuebleSaveStatus.textContent = "";
    }, 2000);
  }
};

const getPendingInlineEditsCount = () =>
  pendingInlineEdits.inmueble.size + pendingInlineEdits.captacion.size;

const syncInmuebleManualSaveButton = () => {
  if (!inmuebleManualSaveBtn) return;
  const pending = getPendingInlineEditsCount();
  inmuebleManualSaveBtn.disabled = pending === 0 || !state.currentInmuebleId;
  inmuebleManualSaveBtn.textContent = pending ? `Guardar (${pending})` : "Guardar";
  if (!inmuebleSaveStatus || !state.currentInmuebleId) return;
  const currentStatus = String(inmuebleSaveStatus.textContent || "").trim();
  const neutral = new Set(["", "Sin cambios", "No hay cambios pendientes.", "Cambios pendientes"]);
  if (!neutral.has(currentStatus)) return;
  if (pending > 0 && (currentStatus === "" || currentStatus === "Sin cambios" || currentStatus === "No hay cambios pendientes.")) {
    setInmuebleSaveStatus("Cambios pendientes");
    return;
  }
  if (pending === 0 && (currentStatus === "" || currentStatus === "Cambios pendientes" || currentStatus === "No hay cambios pendientes.")) {
    setInmuebleSaveStatus("Sin cambios");
  }
};

const markPendingInlineEdit = (target, field, value) => {
  if (target !== "inmueble" && target !== "captacion") return;
  pendingInlineEdits[target].set(field, value);
  syncInmuebleManualSaveButton();
  const currentStatus = String(inmuebleSaveStatus?.textContent || "").trim();
  if (!currentStatus || currentStatus === "Sin cambios" || currentStatus === "No hay cambios pendientes.") {
    setInmuebleSaveStatus("Cambios pendientes");
  }
};

const clearPendingInlineEdits = (target, fields = []) => {
  if (target !== "inmueble" && target !== "captacion") return;
  const keys = Array.isArray(fields) ? fields : Object.keys(fields || {});
  keys.forEach((key) => pendingInlineEdits[target].delete(key));
  syncInmuebleManualSaveButton();
  if (getPendingInlineEditsCount() === 0 && state.currentInmuebleId) {
    const currentStatus = String(inmuebleSaveStatus?.textContent || "").trim();
    if (!currentStatus || currentStatus === "Cambios pendientes" || currentStatus === "No hay cambios pendientes.") {
      setInmuebleSaveStatus("Sin cambios");
    }
  }
};

const scheduleSave = (key, fn, delay = 500) => {
  if (saveTimers.has(key)) {
    clearTimeout(saveTimers.get(key));
  }
  const timer = setTimeout(() => {
    saveTimers.delete(key);
    fn();
  }, delay);
  saveTimers.set(key, timer);
};

const updateInmuebleMapFromInputs = () => {
  const latInput = document.querySelector(
    '.inline-input[data-target="inmueble"][data-field="lat"]'
  );
  const lonInput = document.querySelector(
    '.inline-input[data-target="inmueble"][data-field="lon"]'
  );
  const lat = latInput ? Number(latInput.value) : null;
  const lon = lonInput ? Number(lonInput.value) : null;
  updateInmuebleMap(lat, lon);
};

const buildInmuebleDisplayAddress = (source = {}) => {
  const direccion = String(source.direccion || "").trim();
  const cp = String(source.codigo_postal || "").trim();
  const poblacion = String(source.poblacion || "").trim();
  const provincia = String(source.provincia || "").trim();
  const locality = [cp, poblacion].filter(Boolean).join(" ") || poblacion || "";
  return [direccion, locality, provincia].filter(Boolean).join(", ");
};

const resolveProvinciaFromFreeText = (text = "") => {
  const raw = String(text || "").trim();
  if (!raw) return "";
  const normalized = normalizeSimple(raw);
  const match = (SPAIN_PROVINCES || []).find((prov) => normalizeSimple(prov) === normalized);
  return match || "";
};

const parseInmuebleDireccionLibre = (rawText = "") => {
  const raw = String(rawText || "").replace(/\s+/g, " ").trim();
  if (!raw) return null;

  const result = {
    direccion: "",
    direccion_numero: "",
    planta: "",
    puerta: "",
    codigo_postal: "",
    poblacion: "",
    provincia: "",
  };

  const cpMatch = raw.match(/\b(\d{5})\b/);
  if (cpMatch) result.codigo_postal = cpMatch[1];

  const parts = raw
    .split(",")
    .map((p) => p.trim())
    .filter(Boolean);

  // Calle y extras en el primer tramo (antes de CP/municipio/provincia).
  const first = parts[0] || raw;
  let street = first;

  // Patrones comunes: "... 2 14D" / "... 2 14 D" / "... 2 14D"
  let m = street.match(/^(.*?)(?:\s+|,)\b(\d{1,5}[A-Za-z]?)\b(?:\s+|,)\b(\d{1,3})\s*([A-Za-z]{1,3})\b\s*$/);
  if (m) {
    result.direccion = String(m[1] || "").trim();
    result.direccion_numero = String(m[2] || "").trim();
    result.planta = String(m[3] || "").trim();
    result.puerta = String(m[4] || "").trim().toUpperCase();
  } else {
    m = street.match(/^(.*?)(?:\s+|,)\b(\d{1,5}[A-Za-z]?)\b(?:\s+|,)\b(\d{1,3})([A-Za-z]{1,3})\b\s*$/);
    if (m) {
      result.direccion = String(m[1] || "").trim();
      result.direccion_numero = String(m[2] || "").trim();
      result.planta = String(m[3] || "").trim();
      result.puerta = String(m[4] || "").trim().toUpperCase();
    } else {
      m = street.match(/^(.*?)(?:\s+|,)\b(?:n[oº°\\.]?\s*)?(\d{1,5}[A-Za-z]?)\b\s*$/i);
      if (m) {
        result.direccion = String(m[1] || "").trim();
        result.direccion_numero = String(m[2] || "").trim();
      } else {
        result.direccion = street.trim();
      }
    }
  }

  if (result.codigo_postal) {
    const idx = parts.findIndex((p) => p.includes(result.codigo_postal));
    if (idx >= 0) {
      const seg = parts[idx];
      const after = seg.replace(result.codigo_postal, "").trim();
      if (after) {
        result.poblacion = after;
      } else if (parts[idx + 1]) {
        result.poblacion = parts[idx + 1];
      }
      const provinciaCandidate = parts[parts.length - 1] || "";
      result.provincia = resolveProvinciaFromFreeText(provinciaCandidate) || "";
    }
  } else if (parts.length >= 2) {
    const provinciaCandidate = parts[parts.length - 1] || "";
    const poblacionCandidate = parts[parts.length - 2] || "";
    result.provincia = resolveProvinciaFromFreeText(provinciaCandidate) || "";
    if (poblacionCandidate && normalizeSimple(poblacionCandidate) !== normalizeSimple(result.provincia)) {
      result.poblacion = poblacionCandidate;
    }
  }

  if (result.poblacion) result.poblacion = result.poblacion.replace(/\s+/g, " ").trim();
  if (result.direccion) result.direccion = result.direccion.replace(/\s+/g, " ").trim();

  return result;
};

const getInmuebleDireccionInputMapFromDom = () => ({
  direccion: document.querySelector('.inline-input[data-target="inmueble"][data-field="direccion"]'),
  direccion_numero: document.querySelector('.inline-input[data-target="inmueble"][data-field="direccion_numero"]'),
  planta: document.querySelector('.inline-input[data-target="inmueble"][data-field="planta"]'),
  puerta: document.querySelector('.inline-input[data-target="inmueble"][data-field="puerta"]'),
  codigo_postal: document.querySelector('.inline-input[data-target="inmueble"][data-field="codigo_postal"]'),
  poblacion: document.querySelector('.inline-input[data-target="inmueble"][data-field="poblacion"]'),
  provincia: document.querySelector('.inline-input[data-target="inmueble"][data-field="provincia"]'),
});

const autocompleteInmuebleDireccionFromUi = async () => {
  if (!state.currentInmuebleId) return;
  const inputs = getInmuebleDireccionInputMapFromDom();
  if (!inputs.direccion) return;
  const raw = String(inputs.direccion.value || "").trim();
  const parsed = parseInmuebleDireccionLibre(raw);
  if (!parsed) {
    setInmuebleSaveStatus("Sin datos para autocompletar.");
    return;
  }

  const updates = {};
  const maybeSet = (key, nextValue) => {
    const el = inputs[key];
    const next = String(nextValue || "").trim();
    if (!el || !next) return;
    const current = String(el.value || "").trim();
    if (current) return; // solo autocompleta si está vacío
    el.value = next;
    updates[key] = next;
  };

  // Si el usuario pegó la dirección completa, rellenamos piezas.
  maybeSet("codigo_postal", parsed.codigo_postal);
  maybeSet("poblacion", parsed.poblacion);
  if (parsed.provincia) {
    const provinciaEl = inputs.provincia;
    const current = provinciaEl ? String(provinciaEl.value || "").trim() : "";
    if (provinciaEl && !current) {
      const resolved = resolveProvinciaFromFreeText(parsed.provincia) || "";
      if (resolved) {
        provinciaEl.value = resolved;
        updates.provincia = resolved;
      }
    }
  }

  // Número/planta/puerta a partir del texto en Dirección.
  maybeSet("direccion_numero", parsed.direccion_numero);
  maybeSet("planta", parsed.planta);
  maybeSet("puerta", parsed.puerta);

  // Limpia la calle si hemos tenido que inferir el número (evita duplicar "2 14D" en Dirección).
  if (Object.prototype.hasOwnProperty.call(updates, "direccion_numero") && parsed.direccion) {
    const currentStreet = String(inputs.direccion.value || "").trim();
    if (currentStreet && currentStreet !== parsed.direccion) {
      inputs.direccion.value = parsed.direccion;
      updates.direccion = parsed.direccion;
    }
  }

  if (!Object.keys(updates).length) {
    setInmuebleSaveStatus("Sin datos para autocompletar.");
    return;
  }

  try {
    await saveInmuebleFields(updates);
  } catch (e) {}
};

const refreshCurrentInmuebleHeader = () => {
  const inmueble = state.currentInmueble || state.currentInmuebleContext?.inmueble || {};
  const captacion = state.currentInmuebleContext?.captacion || {};
  const stageLabel = normalizeCrmMainEtapa(
    inmueble.estado || captacion.etapa || captacion.situacion_comercial || ""
  );
  if (inmuebleTitle) {
    inmuebleTitle.textContent = inmueble.direccion || "Ficha de inmueble";
  }
  if (inmuebleSubtitle) {
    inmuebleSubtitle.textContent =
      [stageLabel || "", inmueble.referencia || "", inmueble.referencia_catastral || "", inmueble.poblacion || ""]
        .filter(Boolean)
        .join(" · ") || "Referencia sin asignar";
  }
};

const refreshInmuebleVisitSheetButton = () => {
  if (!inmuebleVisitaPdfBtn) return;
  const inmueble = state.currentInmueble || state.currentInmuebleContext?.inmueble || {};
  const captacion = state.currentInmuebleContext?.captacion || {};
  const status = String(captacion.situacion_comercial || inmueble.estado || "").trim().toLowerCase();
  const isEncargo = status === "encargo";
  const isNoticia = status === "noticia";
  const isAlquiler = status === "alquiler";
  // Nota de encargo: disponible en Noticia o Encargo (el backend también lo permite).
  const allowEncargoDocs = isEncargo || isNoticia;
  inmuebleEncargoPdfBtn?.classList.toggle("hidden", !allowEncargoDocs);
  // Hoja de visita / documentación base: disponible en Noticia o Encargo (se usa para visitas).
  inmuebleVisitaPdfBtn.classList.toggle("hidden", !allowEncargoDocs);
  // Documentación de venta: solo cuando ya es Encargo.
  inmuebleVentaFichaPdfBtn?.classList.toggle("hidden", !isEncargo);
  inmuebleVentaPrecioPdfBtn?.classList.toggle("hidden", !isEncargo);
  inmuebleExpedienteDocsBtn?.classList.toggle("hidden", !isEncargo);
  inmuebleAlquilerDiaPdfBtn?.classList.toggle("hidden", !isAlquiler);
};

const resolveVisitSheetDemandaId = () => {
  const demandas = Array.isArray(state.currentInmuebleContext?.demandas) ? state.currentInmuebleContext.demandas : [];
  const visitas = Array.isArray(state.currentInmuebleContext?.visitas) ? state.currentInmuebleContext.visitas : [];
  const candidates = new Map();
  demandas.forEach((row) => {
    const demandaId = String(row.id || "").trim();
    const clienteId = String(row.cliente_id || "").trim();
    const cliente = String(row.cliente || "").trim();
    if (!demandaId || !clienteId) return;
    candidates.set(demandaId, {
      demanda_id: demandaId,
      cliente_id: clienteId,
      label: `${cliente || "Cliente"} · ${row.tipo || "Pedido"}`,
    });
  });
  visitas.forEach((row) => {
    const demandaId = String(row.demanda_id || "").trim();
    const clienteId = String(row.cliente_id || "").trim();
    const cliente = String(row.cliente || "").trim();
    if (!demandaId || !clienteId || candidates.has(demandaId)) return;
    candidates.set(demandaId, {
      demanda_id: demandaId,
      cliente_id: clienteId,
      label: `${cliente || "Cliente"} · visita ${row.fecha || "-"}`,
    });
  });
  const items = Array.from(candidates.values());
  if (!items.length) {
    return "";
  }
  if (items.length === 1) {
    return items[0].demanda_id;
  }
  const message = items.map((item, index) => `${index + 1}. ${item.label}`).join("\n");
  const raw = window.prompt(
    `Hay varios compradores vinculados. Indica el número de la demanda para generar la hoja:\n\n${message}`,
    "1"
  );
  if (raw === null) return null;
  const idx = Number(raw);
  if (!Number.isInteger(idx) || idx < 1 || idx > items.length) {
    alert("Selección no válida.");
    return null;
  }
  return items[idx - 1].demanda_id;
};

const openInmuebleVisitSheetPdf = () => {
  if (!state.currentInmuebleId) return;
  const demandaId = resolveVisitSheetDemandaId();
  if (demandaId === null) return;
  const params = new URLSearchParams({ id: state.currentInmuebleId });
  if (demandaId) {
    params.set("demanda_id", demandaId);
  }
  const target = window.open("about:blank", "_blank", "noopener");
  api(`/api/inmueble_visita_docs?${params.toString()}`)
    .catch((error) => {
      console.warn("No se pudo generar el paquete documental de visita", error);
    })
    .finally(() => {
      const url = `/api/inmueble_visita_pdf?${params.toString()}`;
      if (target) {
        target.location = url;
      } else {
        window.open(url, "_blank", "noopener");
      }
      if (state.currentInmuebleId) {
        loadInmuebleDocs(state.currentInmuebleId);
      }
    });
};

const openInmuebleConsumoPdf = (kind) => {
  if (!state.currentInmuebleId || !kind) return;
  const params = new URLSearchParams({ id: state.currentInmuebleId, kind });
  window.open(`/api/inmueble_consumo_pdf?${params.toString()}`, "_blank", "noopener");
};

const generateInmuebleExpedienteDocs = async () => {
  if (!state.currentInmuebleId) return;
  const params = new URLSearchParams({ id: state.currentInmuebleId });
  if (inmuebleSaveStatus) inmuebleSaveStatus.textContent = "Generando expediente...";
  try {
    const data = await api(`/api/inmueble_expediente_docs?${params.toString()}`);
    if (inmuebleSaveStatus) inmuebleSaveStatus.textContent = `Expediente generado (${data.count || 0} documentos).`;
    loadInmuebleDocs(state.currentInmuebleId);
  } catch (error) {
    if (inmuebleSaveStatus) inmuebleSaveStatus.textContent = error?.message || "No se pudo generar el expediente.";
  }
};

const openInmuebleNotaEncargoPdf = () => {
  if (!state.currentInmuebleId) return;
  const inmueble = state.currentInmueble || state.currentInmuebleContext?.inmueble || {};
  const captacion = state.currentInmuebleContext?.captacion || {};
  const docs = Array.isArray(state.currentInmuebleContext?.docs) ? state.currentInmuebleContext.docs : [];
  const tipoOperacionDefault = resolveInmuebleTipoOperacion(inmueble, captacion, docs);
  const lastEncargoDoc =
    docs.find((doc) => normalizeSimple(doc?.plantilla_clave || "") === "nota_encargo" || normalizeSimple(doc?.tipo || "") === "nota de encargo") || null;
  let lastEncargoPayload = {};
  if (lastEncargoDoc && lastEncargoDoc.payload_json) {
    try {
      lastEncargoPayload =
        typeof lastEncargoDoc.payload_json === "string"
          ? JSON.parse(lastEncargoDoc.payload_json)
          : (lastEncargoDoc.payload_json || {});
    } catch (_) {
      lastEncargoPayload = {};
    }
  }

  const addMonths = (isoDate, months) => {
    const base = isoDate ? new Date(`${isoDate}T00:00:00`) : new Date();
    if (Number.isNaN(base.getTime())) return isoDate || "";
    const year = base.getFullYear();
    const month = base.getMonth();
    const day = base.getDate();
    const targetMonth = month + Number(months || 0);
    const candidate = new Date(year, targetMonth, 1);
    const endOfMonth = new Date(candidate.getFullYear(), candidate.getMonth() + 1, 0);
    const finalDay = Math.min(day, endOfMonth.getDate());
    const result = new Date(candidate.getFullYear(), candidate.getMonth(), finalDay);
    return result.toISOString().slice(0, 10);
  };

  const openModal = () =>
    new Promise((resolve) => {
      let modal = document.getElementById("inmoEncargoPdfModal");
      if (!modal) {
        modal = document.createElement("div");
        modal.id = "inmoEncargoPdfModal";
        modal.className = "modal hidden";
        modal.innerHTML = `
          <div class="modal-content" style="max-width: 980px;">
            <div class="modal-header">
              <h3>Nota de encargo (PDF)</h3>
              <button type="button" class="ghost" data-encargo-close>✕</button>
            </div>
            <form class="modal-body form-grid" data-encargo-form>
              <label>
                Tipo de encargo
                <select name="tipo_operacion">
                  <option value="venta">Venta</option>
                  <option value="alquiler">Alquiler</option>
                </select>
              </label>
              <label data-encargo-only="venta">
                Precio de venta (EUR)
                <input name="precio_venta" />
              </label>
              <label data-encargo-only="venta">
                Honorarios (% sin IVA)
                <input name="honorarios_pct" />
              </label>
              <label data-encargo-only="alquiler">
                Renta mensual (EUR)
                <input name="renta_mensual" />
              </label>
              <label data-encargo-only="alquiler">
                Honorarios (mensualidades)
                <input name="honorarios_mensualidades" placeholder="Ej. 1" />
              </label>
              <label data-encargo-only="alquiler">
                Plazo arrendamiento (meses/años)
                <input name="plazo_arrendamiento" placeholder="Ej. 12 meses" />
              </label>
              <label data-encargo-only="alquiler">
                Destino del inmueble
                <select name="destino_arrendamiento">
                  <option value="vivienda">Vivienda</option>
                  <option value="uso_distinto">Uso distinto</option>
                </select>
              </label>
              <label data-encargo-only="alquiler">
                Fianza (art. 36 LAU)
                <select name="fianza_tipo">
                  <option value="una">Una mensualidad</option>
                  <option value="dos">Dos mensualidades</option>
                </select>
              </label>
              <label data-encargo-only="alquiler" class="span-2">
                Garantía adicional (opcional)
                <input name="garantia_adicional" />
              </label>
              <label data-encargo-only="alquiler" class="span-2">
                Entrega del inmueble (momento/fecha)
                <input name="entrega_fecha" />
              </label>
              <label>
                IVA (%)
                <input name="iva_pct" />
              </label>
              <label>
                Fecha inicio (YYYY-MM-DD)
                <input name="fecha_inicio" type="date" />
              </label>
              <label>
                Fecha fin (YYYY-MM-DD)
                <input name="fecha_fin" type="date" />
              </label>
              <label data-encargo-only="venta">
                Venta a partir de (opcional)
                <input name="fecha_venta_desde" placeholder="YYYY-MM-DD" />
              </label>
              <label data-encargo-only="venta">
                Venta antes de (opcional)
                <input name="fecha_venta_antes" placeholder="YYYY-MM-DD" />
              </label>
              <label class="span-2">
                Datos registrales (opcional)
                <input name="datos_registrales" placeholder="Ej. Finca Nº..., folio..." />
              </label>
              <label>
                m² útiles (opcional)
                <input name="m2_utiles" />
              </label>
              <label>
                Cargas/gravámenes
                <input name="cargas" />
              </label>
              <label class="span-2">
                Otros (opcional)
                <input name="otros" />
              </label>
              <label>
                Lugar de firma
                <input name="lugar_firma" />
              </label>
              <label class="span-2">
                Copilot (mejoras legislativas / checklist)
                <textarea name="copilot_mejoras" rows="5" placeholder="Pulsa “Copilot: mejoras” para obtener sugerencias."></textarea>
              </label>
	              <div class="form-actions span-2" style="display:flex;gap:10px;flex-wrap:wrap;">
	                <button type="button" class="secondary" data-encargo-copilot-fill>Copilot: rellenar</button>
	                <button type="button" class="secondary ghost" data-encargo-copilot-legal>Copilot: mejoras</button>
	                <button type="button" class="secondary" data-encargo-generate-final>PDF final</button>
	                <button type="button" data-encargo-generate-editable>PDF editable</button>
	                <span class="muted" data-encargo-status></span>
	              </div>
            </form>
          </div>
        `;
        document.body.appendChild(modal);
      }

      const form = modal.querySelector("[data-encargo-form]");
      const closeBtn = modal.querySelector("[data-encargo-close]");
	      const generateEditableBtn = modal.querySelector("[data-encargo-generate-editable]");
	      const generateFinalBtn = modal.querySelector("[data-encargo-generate-final]");
      const fillBtn = modal.querySelector("[data-encargo-copilot-fill]");
      const legalBtn = modal.querySelector("[data-encargo-copilot-legal]");
      const statusEl = modal.querySelector("[data-encargo-status]");
      const tipoSelect = modal.querySelector('[name="tipo_operacion"]');

      const setValue = (name, value) => {
        const el = form?.querySelector(`[name="${name}"]`);
        if (!el) return;
        el.value = value || "";
      };

      const todayIso = new Date().toISOString().slice(0, 10);
      const defaultStart = todayIso;
      const defaultEnd = addMonths(defaultStart, 6);
      const defaultPrice = String(inmueble.precio_encargo || inmueble.precio_objetivo || "").trim();
      const honorariosRaw = Number(inmueble.honorarios || 0);
      const defaultHonorariosPct =
        honorariosRaw > 0 && honorariosRaw <= 25 ? String(honorariosRaw) : "4";

      form?.reset();
      setValue("tipo_operacion", tipoOperacionDefault || "venta");
      setValue("precio_venta", defaultPrice);
      setValue("honorarios_pct", defaultHonorariosPct);
      setValue("renta_mensual", defaultPrice);
      setValue("honorarios_mensualidades", "1");
      setValue("plazo_arrendamiento", "");
      setValue("destino_arrendamiento", "vivienda");
      setValue("fianza_tipo", "una");
      setValue("garantia_adicional", "");
      setValue("entrega_fecha", "");
      setValue("iva_pct", "21");
      setValue("fecha_inicio", defaultStart);
      setValue("fecha_fin", defaultEnd);
      setValue("fecha_venta_desde", "");
      setValue("fecha_venta_antes", "");
      setValue("datos_registrales", "");
      setValue("m2_utiles", "");
      setValue("cargas", "NADA");
      setValue("otros", "");
      setValue("lugar_firma", String(inmueble.poblacion || inmueble.provincia || "").trim());
      setValue("copilot_mejoras", "");

      // Prefill con la última nota de encargo generada (persistencia real del formulario).
      if (lastEncargoPayload && typeof lastEncargoPayload === "object") {
        [
          "tipo_operacion",
          "precio_venta",
          "renta_mensual",
          "honorarios_pct",
          "honorarios_mensualidades",
          "plazo_arrendamiento",
          "destino_arrendamiento",
          "fianza_tipo",
          "garantia_adicional",
          "entrega_fecha",
          "iva_pct",
          "fecha_inicio",
          "fecha_fin",
          "fecha_venta_desde",
          "fecha_venta_antes",
          "datos_registrales",
          "m2_utiles",
          "cargas",
          "otros",
          "lugar_firma",
        ].forEach((key) => {
          const value = lastEncargoPayload[key];
          if (value === null || value === undefined) return;
          const text = String(value || "").trim();
          if (!text) return;
          setValue(key, text);
        });
      }

      const syncTipoUi = () => {
        const tipo = String(form?.querySelector('[name="tipo_operacion"]')?.value || "venta").trim();
        const nodes = Array.from(form?.querySelectorAll("[data-encargo-only]") || []);
        nodes.forEach((node) => {
          const only = node.getAttribute("data-encargo-only");
          node.classList.toggle("hidden", only && only !== tipo);
        });
        // Campos venta (precio/honorarios pct) se siguen mostrando aunque no tengan data-encargo-only,
        // pero los validamos según tipo.
      };
      tipoSelect?.addEventListener("change", syncTipoUi);
      syncTipoUi();

      const readValues = () => {
        const values = Object.fromEntries(new FormData(form).entries());
        return Object.fromEntries(
          Object.entries(values).map(([key, value]) => [key, String(value || "").trim()])
        );
      };

      const applySuggestedValues = (suggested = {}) => {
        Object.entries(suggested || {}).forEach(([key, value]) => {
          if (key === "copilot_mejoras") return;
          if (value === null || value === undefined) return;
          setValue(key, String(value));
        });
        syncTipoUi();
      };

      let resolved = false;
      const cleanup = (value) => {
        if (resolved) return;
        resolved = true;
        modal.classList.add("hidden");
        modal.classList.remove("open");
        resolve(value);
      };
      closeBtn.onclick = () => cleanup(null);
      modal.onclick = (event) => {
        if (event.target === modal) cleanup(null);
      };

      fillBtn.onclick = async () => {
        if (statusEl) statusEl.textContent = "Copilot rellenando...";
        try {
          const res = await fetch("/api/ai_inmo_encargo_copilot", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              inmueble_id: state.currentInmuebleId,
              tipo_operacion: readValues().tipo_operacion,
              task: "rellenar",
              values: readValues(),
            }),
          });
          const data = await res.json();
          if (data?.error) throw new Error(data.error);
          if (data?.suggested) {
            const ok = window.confirm("Aplicar valores sugeridos por Copilot al formulario?");
            if (ok) applySuggestedValues(data.suggested);
          }
          if (statusEl) statusEl.textContent = "Sugerencias listas.";
        } catch (error) {
          if (statusEl) statusEl.textContent = error?.message || "No se pudo rellenar.";
        }
      };

      legalBtn.onclick = async () => {
        if (statusEl) statusEl.textContent = "Copilot generando mejoras...";
        try {
          const res = await fetch("/api/ai_inmo_encargo_copilot", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              inmueble_id: state.currentInmuebleId,
              tipo_operacion: readValues().tipo_operacion,
              task: "mejoras",
              values: readValues(),
            }),
          });
          const data = await res.json();
          if (data?.error) throw new Error(data.error);
          setValue("copilot_mejoras", data?.output || "");
          if (statusEl) statusEl.textContent = data?.mode === "openai" ? "Mejoras listas (OpenAI)." : "Mejoras listas.";
        } catch (error) {
          if (statusEl) statusEl.textContent = error?.message || "No se pudieron generar mejoras.";
        }
      };

	      const generateEncargoPdf = async (mode) => {
	        const values = readValues();
	        const tipo = values.tipo_operacion || "venta";
	        if (tipo === "alquiler") {
	          if (!values.renta_mensual) {
	            alert("Renta mensual requerida.");
	            return;
	          }
	          if (!values.honorarios_mensualidades) {
	            alert("Honorarios (mensualidades) requeridos.");
	            return;
	          }
	        } else {
	          if (!values.precio_venta) {
	            alert("Precio de venta requerido.");
	            return;
	          }
	          if (!values.honorarios_pct) {
	            alert("Honorarios (%) requeridos.");
	            return;
	          }
	          if (!values.iva_pct) {
	            alert("IVA (%) requerido.");
	            return;
	          }
	        }
	        if (!values.fecha_inicio) {
	          alert("Fecha inicio requerida.");
	          return;
	        }
	        if (!values.fecha_fin) {
	          alert("Fecha fin requerida.");
	          return;
	        }
	        // Persistencia: guarda la operación y los importes principales en la ficha del inmueble.
	        try {
	          const updates = { tipo_operacion: tipo };
	          if (tipo === "alquiler") {
	            updates.precio_objetivo = values.renta_mensual;
	            updates.precio_encargo = values.renta_mensual;
	            updates.honorarios = values.honorarios_mensualidades;
	          } else {
	            updates.precio_objetivo = values.precio_venta;
	            updates.precio_encargo = values.precio_venta;
	            updates.honorarios = values.honorarios_pct;
	          }
	          await saveInmuebleFields(updates);
	        } catch (_) {
	          // No bloquea la generación del PDF.
	        }
	        const params = new URLSearchParams({ id: state.currentInmuebleId });
	        const normalizedMode = String(mode || "").trim().toLowerCase();
	        if (normalizedMode === "final") {
	          params.set("mode", "final");
	        }
	        [
	          "tipo_operacion",
	          "precio_venta",
	          "renta_mensual",
	          "honorarios_pct",
          "honorarios_mensualidades",
          "honorarios_text",
          "plazo_arrendamiento",
          "destino_arrendamiento",
          "fianza_tipo",
          "garantia_adicional",
          "entrega_fecha",
          "iva_pct",
          "fecha_inicio",
          "fecha_fin",
          "fecha_venta_desde",
          "fecha_venta_antes",
          "datos_registrales",
          "m2_utiles",
          "cargas",
          "otros",
          "lugar_firma",
        ].forEach((key) => {
          const value = values[key];
	          if (value) params.set(key, value);
	        });
	        window.open(`/api/inmueble_encargo_pdf?${params.toString()}`, "_blank", "noopener");
	        cleanup(values);
	      };

	      if (generateEditableBtn) {
	        generateEditableBtn.onclick = async () => {
	          await generateEncargoPdf("editable");
	        };
	      }
	      if (generateFinalBtn) {
	        generateFinalBtn.onclick = async () => {
	          await generateEncargoPdf("final");
	        };
	      }

      modal.classList.remove("hidden");
      modal.classList.add("open");
    });

  openModal();
};

const getInmuebleStageRequirements = (stage, inmueble = {}, captacion = {}, propietarios = []) => {
  const normalized = normalizeSimple(stage || "");
  if (!normalized) return [];
  const hasPropietario =
    String(captacion.propietario || "").trim() ||
    (Array.isArray(propietarios) && propietarios.length > 0);
  const isEarly = normalized === "inmueble" || normalized === "noticia" || normalized === "adquisicion";
  const stagePrice = isEarly
    ? (Number(inmueble.precio_pedido_cliente || 0) || Number(inmueble.precio_objetivo || 0) || 0)
    : (Number(inmueble.precio_encargo || 0) || Number(inmueble.precio_objetivo || 0) || Number(inmueble.precio_pedido_cliente || 0) || 0);
  const stagePriceLabel = isEarly ? "Precio propietario" : "Precio encargo";
  const checks = {
    direccion: { label: "Dirección", ok: Boolean(String(inmueble.direccion || "").trim()) },
    poblacion: { label: "Población", ok: Boolean(String(inmueble.poblacion || "").trim()) },
    provincia: { label: "Provincia", ok: Boolean(String(inmueble.provincia || "").trim()) },
    tipo: { label: "Tipo de inmueble", ok: Boolean(String(inmueble.tipo_inmueble || "").trim()) },
    precio: { label: stagePriceLabel, ok: Number(stagePrice || 0) > 0 },
    honorarios: { label: "Honorarios agencia", ok: Number(inmueble.honorarios || 0) > 0 },
    ocupacion: { label: "Situación de ocupación", ok: Boolean(String(inmueble.situacion_ocupacion || "").trim()) },
    propietario: { label: "Propietario vinculado", ok: Boolean(hasPropietario) },
    catastro: { label: "Referencia catastral", ok: Boolean(String(inmueble.referencia_catastral || "").trim()) },
  };
  const stageMap = {
    noticia: ["direccion", "poblacion", "provincia", "tipo", "propietario"],
    inmueble: ["direccion", "poblacion", "provincia", "tipo", "propietario"],
    adquisicion: ["direccion", "poblacion", "provincia", "tipo", "propietario"],
    encargo: ["direccion", "poblacion", "provincia", "tipo", "precio", "honorarios", "ocupacion", "propietario"],
    reservado: ["direccion", "poblacion", "provincia", "tipo", "precio", "honorarios", "ocupacion", "propietario", "catastro"],
    vendido: ["direccion", "poblacion", "provincia", "tipo", "precio", "honorarios", "ocupacion", "propietario", "catastro"],
  };
  return (stageMap[normalized] || [])
    .map((key) => checks[key])
    .filter(Boolean);
};

const validateInmuebleStageTransition = (stage, inmueble = {}, captacion = {}, propietarios = []) => {
  const requirements = getInmuebleStageRequirements(stage, inmueble, captacion, propietarios);
  const missing = requirements.filter((item) => !item.ok);
  return {
    ok: missing.length === 0,
    missing,
  };
};

const rerenderCurrentInmuebleGrids = () => {
  const inmueble = state.currentInmuebleContext?.inmueble || state.currentInmueble || {};
  const captacion = state.currentInmuebleContext?.captacion || {};
  const docs = state.currentInmuebleContext?.docs || [];
  state.currentInmuebleOperacionTipo = resolveInmuebleTipoOperacion(inmueble, captacion, docs);
  const etapaMain = resolveInmuebleMainEtapa(inmueble, captacion);
  syncInmuebleNoticiaTab(inmueble, captacion);
  if (inmuebleDatosGrid) {
    const baseFields = etapaMain === "Encargo" ? INMUEBLE_FIELDS_ENCARGO : INMUEBLE_FIELDS;
    const stageFiltered = filterInmuebleFieldsForStage(baseFields, etapaMain);
    const fields = filterInmuebleFieldsForOperacion(stageFiltered, state.currentInmuebleOperacionTipo);
    renderEditableGrid(inmuebleDatosGrid, fields, inmueble, "inmueble");
  }
  if (inmuebleCaptacionGrid) {
    const fields =
      etapaMain === "Noticia"
        ? CAPTACION_FIELDS_SEGUIMIENTO_NOTICIA
        : (etapaMain === "Encargo" || etapaMain === "Propuesta" || etapaMain === "Vendido")
          ? CAPTACION_FIELDS_ENCARGO
          : CAPTACION_FIELDS;
    renderEditableGrid(inmuebleCaptacionGrid, fields, captacion, "captacion");
  }
  if (inmuebleNoticiaGrid) {
    const stage = normalizeCrmMainEtapa(inmueble.estado || captacion.etapa || captacion.situacion_comercial || "");
    if (["Noticia", "Encargo", "Propuesta", "Vendido"].includes(stage)) {
      renderEditableGrid(inmuebleNoticiaGrid, CAPTACION_FIELDS_NOTICIA, captacion, "captacion");
    } else {
      inmuebleNoticiaGrid.innerHTML = "<p class='muted'>Disponible al convertir el inmueble en Noticia.</p>";
    }
  }
  refreshCurrentInmuebleProfile();
  refreshInmuebleVisitSheetButton();
};

const saveInmuebleFields = async (updates = {}) => {
  if (!state.currentInmuebleId) return { error: "Selecciona un inmueble." };
  setInmuebleSaveStatus("Guardando...");
  try {
    const data = await postJsonWithDbRetry(
      "/api/inmueble_update",
      { inmueble_id: state.currentInmuebleId, ...(updates || {}) },
      { maxRetries: 6, baseDelayMs: 350, timeoutMs: 20000 }
    );
    if (data?.error) return data;
    Object.entries(updates || {}).forEach(([field, value]) => {
      if (state.currentInmueble) {
        state.currentInmueble[field] = value;
      }
      if (state.currentInmuebleContext?.inmueble) {
        state.currentInmuebleContext.inmueble[field] = value;
      }
    });
	    refreshCurrentInmuebleHeader();
	    syncInmuebleArchivePendingButton();
	    setInmuebleSaveStatus("Guardado · cambios aplicados");
	    loadCrmInmuebles();
	    refreshCurrentInmuebleProfile();
	    refreshInmuebleVisitSheetButton();
		    if (Object.prototype.hasOwnProperty.call(updates || {}, "tipo_operacion") || Object.prototype.hasOwnProperty.call(updates || {}, "estado")) {
		      rerenderCurrentInmuebleGrids();
		    }
		    if (Object.prototype.hasOwnProperty.call(updates || {}, "estado")) {
		      syncInmuebleEncargoModalButton(state.currentInmuebleContext?.inmueble || state.currentInmueble || {}, state.currentInmuebleContext?.captacion || {});
		    }
		    clearPendingInlineEdits("inmueble", Object.keys(updates || {}));
		    return data;
		  } catch (error) {
	    setInmuebleSaveStatus(error?.message || "Error al guardar.");
	    return { error: error?.message || "Error al guardar." };
	  }
};

const generateCurrentInmuebleAnuncio = async () => {
  const inmuebleId = String(state.currentInmuebleId || state.currentInmuebleContext?.inmueble?.id || "").trim();
  if (!inmuebleId) return;
  setInmuebleSaveStatus("Generando texto de anuncio...");
  try {
    const data = await postJsonWithDbRetry(
      "/api/inmueble_anuncio_generate",
      { inmueble_id: inmuebleId },
      { maxRetries: 4, baseDelayMs: 300, timeoutMs: 20000 }
    );
    if (data?.error) throw new Error(data.error);
    ["titulo_anuncio", "descripcion_corta", "descripcion_larga", "destacados", "seo_slug", "anuncio_generado_at"].forEach((field) => {
      if (state.currentInmueble) state.currentInmueble[field] = data[field] || "";
      if (state.currentInmuebleContext?.inmueble) state.currentInmuebleContext.inmueble[field] = data[field] || "";
    });
    rerenderCurrentInmuebleGrids();
    refreshCurrentInmuebleProfile();
    loadCrmInmuebles();
    setInmuebleSaveStatus("Texto de anuncio generado.");
  } catch (error) {
    setInmuebleSaveStatus(error?.message || "No se pudo generar el anuncio.");
  }
};

const syncInmuebleArchivePendingButton = () => {
  if (!inmuebleArchivePendingBtn) return;
  const inmueble = state.currentInmuebleContext?.inmueble || state.currentInmueble || {};
  const captacion = state.currentInmuebleContext?.captacion || {};
  const stage = resolveInmuebleMainEtapa(inmueble, captacion);
  const enabled = Boolean(state.currentInmuebleId);
  // Mostrar solo cuando el inmueble ya está en cierre positivo (Vendido/Alquiler) o cierre negativo.
  const visible = ["Vendido", "Alquiler", "Cerrado negativamente"].includes(stage);
  inmuebleArchivePendingBtn.classList.toggle("hidden", !visible);
  inmuebleArchivePendingBtn.disabled = !enabled;
};

const syncInmuebleEncargoCloseButton = () => {
  if (!inmuebleEncargoCloseBtn) return;
  const inmueble = state.currentInmuebleContext?.inmueble || state.currentInmueble || {};
  const captacion = state.currentInmuebleContext?.captacion || {};
  const stage = resolveInmuebleMainEtapa(inmueble, captacion);
  const visible = stage === "Encargo";
  inmuebleEncargoCloseBtn.classList.toggle("hidden", !visible);
  inmuebleEncargoCloseBtn.disabled = !state.currentInmuebleId;
};

const saveInmuebleField = (field, value) => {
  if (!state.currentInmuebleId) {
    return;
  }
  if (field === "asesor") {
    // En este CRM, asesor y responsable son el mismo concepto (Tecnocloud-like): guardamos ambos para mantener compatibilidad.
    void saveInmuebleFields({ asesor: value, responsable: value });
    return;
  }
  if (field === "estado") {
    const inmueble = { ...(state.currentInmuebleContext?.inmueble || state.currentInmueble || {}), estado: value };
    const captacion = state.currentInmuebleContext?.captacion || {};
    const propietarios = state.currentInmuebleContext?.propietarios || [];
    const validation = validateInmuebleStageTransition(value, inmueble, captacion, propietarios);
    if (!validation.ok) {
      setInmuebleSaveStatus(`Faltan datos para pasar a ${value}: ${validation.missing.map((item) => item.label).join(", ")}.`);
      return;
    }
  }
  void saveInmuebleFields({ [field]: value });
};

const saveCaptacionField = (field, value) => {
  if (!state.currentInmuebleId) {
    return;
  }
  if (field === "asesor") {
    // En este CRM, asesor y responsable son el mismo concepto: guardamos ambos.
    setInmuebleSaveStatus("Guardando...");
    postJsonWithDbRetry(
      "/api/captacion_update",
      { inmueble_id: state.currentInmuebleId, asesor: value, responsable: value },
      { maxRetries: 6, baseDelayMs: 350, timeoutMs: 20000 }
    )
      .then((data) => {
        if (data?.error) {
          setInmuebleSaveStatus(data.error);
          return;
        }
        if (state.currentInmuebleContext?.captacion) {
          state.currentInmuebleContext.captacion.asesor = value;
          state.currentInmuebleContext.captacion.responsable = value;
        }
        clearPendingInlineEdits("captacion", ["asesor", "responsable"]);
        setInmuebleSaveStatus("Guardado · cambios aplicados");
        refreshCurrentInmuebleProfile();
      })
      .catch((error) => {
        setInmuebleSaveStatus(error?.message || "Error al guardar.");
      });
    return;
  }
  if (field === "etapa") {
    const inmueble = { ...(state.currentInmuebleContext?.inmueble || state.currentInmueble || {}), estado: value };
    const captacion = { ...(state.currentInmuebleContext?.captacion || {}), etapa: value };
    const propietarios = state.currentInmuebleContext?.propietarios || [];
    const validation = validateInmuebleStageTransition(value, inmueble, captacion, propietarios);
    if (!validation.ok) {
      setInmuebleSaveStatus(`Faltan datos para pasar a ${value}: ${validation.missing.map((item) => item.label).join(", ")}.`);
      return;
    }
  }
  setInmuebleSaveStatus("Guardando...");
	  postJsonWithDbRetry(
	    "/api/captacion_update",
	    { inmueble_id: state.currentInmuebleId, [field]: value },
	    { maxRetries: 6, baseDelayMs: 350, timeoutMs: 20000 }
	  )
		    .then((data) => {
		      if (data?.error) {
		        setInmuebleSaveStatus(data.error);
		        return;
		      }
	      if (state.currentInmuebleContext?.captacion) {
	        state.currentInmuebleContext.captacion[field] = value;
	      }
		      if ((field === "etapa" || field === "situacion_comercial") && state.currentInmuebleContext?.inmueble) {
		        state.currentInmuebleContext.inmueble.estado = value;
		        rerenderCurrentInmuebleGrids();
		        syncInmuebleEncargoModalButton(state.currentInmuebleContext.inmueble, state.currentInmuebleContext?.captacion || {});
		      }
		      clearPendingInlineEdits("captacion", [field]);
		      setInmuebleSaveStatus("Guardado · cambios aplicados");
		      refreshCurrentInmuebleProfile();
		    })
		    .catch((error) => {
		      setInmuebleSaveStatus(error?.message || "Error al guardar.");
		    });
};

const computeInmoDesviacionPct = (precioPedidoCliente, precioValoracion) => {
  const pedido = toNumber(precioPedidoCliente);
  const valor = toNumber(precioValoracion);
  if (pedido === null || valor === null) return null;
  if (!Number.isFinite(pedido) || !Number.isFinite(valor) || valor <= 0) return null;
  const pct = ((pedido - valor) / valor) * 100;
  return Math.round(pct * 100) / 100;
};

const saveClienteField = (field, value) => {
  if (!state.currentClienteId) {
    return;
  }
  let normalizedValue =
    field === "nif" ? normalizeDocumento(value) : value;
  if (clienteDetailSubtitle) {
    clienteDetailSubtitle.textContent = "Guardando...";
  }
  if (field === "nombre" || field === "apellidos") {
    const nombreInput = document.querySelector('.inline-input[data-target="cliente"][data-field="nombre"]');
    const apellidosInput = document.querySelector('.inline-input[data-target="cliente"][data-field="apellidos"]');
    const nombre = nombreInput ? nombreInput.value.trim() : "";
    const apellidos = apellidosInput ? apellidosInput.value.trim() : "";
    const tipoPersonaInput = document.querySelector('.inline-input[data-target="cliente"][data-field="tipo_persona"]');
    const tipoPersona = tipoPersonaInput ? tipoPersonaInput.value : "";
    normalizedValue = apellidos || nombre
      ? (String(tipoPersona).toLowerCase() === "jurídica"
          ? `${nombre}`.trim()
          : `${apellidos}, ${nombre}`.replace(/\s+/g, " ").trim())
      : "";
    field = "nombre";
  }
  postJsonWithDbRetry("/api/cliente_update", {
      id: state.currentClienteId,
      [field]: normalizedValue,
    }, {
      maxRetries: 6,
      baseDelayMs: 350,
      timeoutMs: 20000,
    })
    .then((data) => {
      if (data.error) {
        if (clienteDetailSubtitle) {
          clienteDetailSubtitle.textContent = data.error;
        }
        return;
      }
      if (clienteDetailSubtitle) {
        clienteDetailSubtitle.textContent = "Guardado.";
      }
      loadClientesList().then(() => {
        loadClientesTable();
        if (clienteDetailTitle && field === "nombre") {
          const split = splitNombreApellidos(normalizedValue);
          clienteDetailTitle.textContent = `${split.apellidos} ${split.nombre}`.trim() || "Ficha de cliente";
        }
      });
    })
    .catch(() => {
      if (clienteDetailSubtitle) {
        clienteDetailSubtitle.textContent = "Error al guardar.";
      }
    });
};

