const populateAgendaClientes = (listEl, inputEl, hiddenEl) => {
  if (!listEl) return;
  listEl.innerHTML = "";
  const clientes = Array.isArray(state.clientesList) ? state.clientesList : [];
  const normalizedMap = new Map();
  clientes.forEach((cliente) => {
    const option = document.createElement("option");
    option.value = formatNombreCliente(cliente.nombre);
    option.dataset.id = cliente.id;
    listEl.appendChild(option);
    const key = normalizeSimple(option.value);
    if (key && !normalizedMap.has(key)) normalizedMap.set(key, String(cliente.id || "").trim());
  });
  if (inputEl) {
    const handler = () => {
      const value = inputEl.value.trim();
      if (!value || !hiddenEl) return;
      const norm = normalizeSimple(value);
      let id = (norm && normalizedMap.get(norm)) || "";
      // Si el usuario escribe sin seleccionar del datalist (p.ej. sin tildes),
      // intentamos un match por substring siempre que sea único.
      if (!id && norm && norm.length >= 3) {
        const hits = [];
        normalizedMap.forEach((cid, cname) => {
          if (cname.includes(norm)) hits.push(cid);
        });
        if (hits.length === 1) id = hits[0];
      }
      hiddenEl.value = id || "";
    };
    if (hiddenEl) {
      if (inputEl.dataset.agendaBoundBase !== "1") {
        inputEl.dataset.agendaBoundBase = "1";
        inputEl.addEventListener("input", handler);
        inputEl.addEventListener("change", handler);
      }
      handler();
    }
  }
};

const populateAgendaClientesFromCandidates = (listEl, inputEl, hiddenEl, candidates = []) => {
  if (!listEl) return;
  const cleaned = (Array.isArray(candidates) ? candidates : [])
    .map((row) => {
      const id = String(row.cliente_id || row.id || "").trim();
      const nombreRaw = row.nombre || row.cliente || row.cliente_nombre || row.propietario || "";
      const nombre = formatNombreCliente(nombreRaw);
      return { id, nombre };
    })
    .filter((item) => item.nombre);
  const seen = new Set();
  const unique = cleaned.filter((item) => {
    const key = normalizeSimple(item.nombre);
    if (!key || seen.has(key)) return false;
    seen.add(key);
    return true;
  });
  listEl.innerHTML = "";
  unique.forEach((item) => {
    const option = document.createElement("option");
    option.value = item.nombre;
    option.dataset.id = item.id || "";
    listEl.appendChild(option);
  });
  if (!inputEl || !hiddenEl) return;
  const map = new Map(unique.map((item) => [normalizeSimple(item.nombre), item.id || ""]));
  inputEl._agendaCandidatesMap = map;
  const syncHidden = () => {
    const value = normalizeSimple(inputEl.value || "");
    const id = (inputEl._agendaCandidatesMap && inputEl._agendaCandidatesMap.get(value)) || "";
    hiddenEl.value = id || "";
  };
  if (inputEl.dataset.agendaBound === "1") {
    syncHidden();
    return;
  }
  inputEl.dataset.agendaBound = "1";
  inputEl.addEventListener("input", syncHidden);
  inputEl.addEventListener("change", syncHidden);
  inputEl.addEventListener("blur", syncHidden);
  syncHidden();
};

const populateAgendaClienteQuickSelect = (selectEl, inputEl, hiddenEl, candidates = [], placeholder = "") => {
  if (!selectEl || !inputEl || !hiddenEl) return;
  const cleaned = (Array.isArray(candidates) ? candidates : [])
    .map((row) => {
      const id = String(row.cliente_id || row.id || "").trim();
      const nombreRaw = row.nombre || row.cliente || row.cliente_nombre || row.propietario || "";
      const nombre = formatNombreCliente(nombreRaw);
      return { id, nombre };
    })
    .filter((item) => item.id && item.nombre);
  const seen = new Set();
  const unique = cleaned.filter((item) => {
    const key = normalizeSimple(item.nombre);
    if (!key || seen.has(key)) return false;
    seen.add(key);
    return true;
  });
  selectEl.innerHTML = "";
  selectEl.appendChild(createOption("", placeholder || "Selecciona cliente..."));
  unique.forEach((item) => {
    const opt = document.createElement("option");
    opt.value = item.id;
    opt.textContent = item.nombre;
    selectEl.appendChild(opt);
  });
  selectEl.classList.toggle("hidden", unique.length === 0 || unique.length > 12);
  selectEl._agendaQuickMap = new Map(unique.map((item) => [item.id, item.nombre]));
  if (selectEl.dataset.agendaBound === "1") return;
  selectEl.dataset.agendaBound = "1";
  selectEl.addEventListener("change", () => {
    const id = String(selectEl.value || "").trim();
    hiddenEl.value = id;
    const name = (selectEl._agendaQuickMap && selectEl._agendaQuickMap.get(id)) || "";
    if (name) {
      inputEl.value = name;
    }
  });
  const syncFromHidden = () => {
    const id = String(hiddenEl.value || "").trim();
    if (id && selectEl._agendaQuickMap && selectEl._agendaQuickMap.has(id)) {
      selectEl.value = id;
    } else {
      selectEl.value = "";
    }
  };
  inputEl.addEventListener("change", syncFromHidden);
  inputEl.addEventListener("blur", syncFromHidden);
};

const resolveClienteFromInput = (inputEl, hiddenEl) => {
  const clientes = Array.isArray(state.clientesList) ? state.clientesList : [];
  const nombre = inputEl ? inputEl.value.trim() : "";
  const nombreNorm = normalizeSimple(nombre);
  let clienteId = hiddenEl ? hiddenEl.value.trim() : "";
  // Evita que se "arrastre" el cliente_id anterior si el usuario cambia el texto del cliente.
  // Si el nombre no coincide con el cliente_id actual, limpiamos el id y volvemos a intentar por nombre.
  if (clienteId) {
    if (!nombre) {
      clienteId = "";
      if (hiddenEl) hiddenEl.value = "";
    } else {
      const current = clientes.find((c) => String(c.id || "").trim() === clienteId) || null;
      if (current && formatNombreCliente(current.nombre) !== nombre) {
        clienteId = "";
        if (hiddenEl) hiddenEl.value = "";
      }
    }
  }
  if (!clienteId && nombre) {
    const match = clientes.find((c) => normalizeSimple(formatNombreCliente(c.nombre)) === nombreNorm);
    if (match) {
      clienteId = match.id;
      if (hiddenEl) hiddenEl.value = clienteId;
    }
    if (!clienteId && nombreNorm && nombreNorm.length >= 3) {
      const hits = clientes
        .map((c) => ({ id: String(c.id || "").trim(), key: normalizeSimple(formatNombreCliente(c.nombre)) }))
        .filter((c) => c.id && c.key && c.key.includes(nombreNorm));
      if (hits.length === 1) {
        clienteId = hits[0].id;
        if (hiddenEl) hiddenEl.value = clienteId;
      }
    }
  }
  return { cliente_id: clienteId || "", cliente_nombre: nombre || "" };
};

const gestoriaContabilidadSegurosCache = new Map();
let segurosContabilidadAllCache = null;
let segurosContabilidadClientesCache = null;

const loadSegurosForClienteContabilidad = async (clienteId) => {
  const key = String(clienteId || "").trim();
  if (!key) return [];
  if (gestoriaContabilidadSegurosCache.has(key)) {
    return gestoriaContabilidadSegurosCache.get(key) || [];
  }
  try {
    const payload = await api(`/api/seguros_cliente?cliente_id=${encodeURIComponent(key)}&uploaded_only=0`);
    const rows = Array.isArray(payload?.rows) ? payload.rows : [];
    gestoriaContabilidadSegurosCache.set(key, rows);
    return rows;
  } catch {
    return [];
  }
};

const loadAllSegurosForContabilidad = async () => {
  if (Array.isArray(segurosContabilidadAllCache)) {
    return segurosContabilidadAllCache;
  }
  const empresa = resolveCrmSegurosEmpresa();
  if (!empresa) return [];
  try {
    const params = new URLSearchParams({
      tabla: "seguros",
      empresa_id: resolveLegacyEmpresaId(empresa),
      include_id: "1",
    });
    const data = await api(`/api/tabla?${params.toString()}`);
    const columns = Array.isArray(data?.columns) ? data.columns : [];
    const rows = Array.isArray(data?.rows) ? data.rows : [];
    const idx = (name) => columns.indexOf(name);
    const idIndex = idx("id");
    const polizaIndex = idx("poliza_numero");
    const companiaIndex = idx("compania");
    const ramoIndex = idx("ramo");
    const clienteIndex = idx("cliente_id");
    segurosContabilidadAllCache = rows
      .map((row) => ({
        id: idIndex >= 0 ? row[idIndex] : "",
        poliza_numero: polizaIndex >= 0 ? row[polizaIndex] : "",
        compania: companiaIndex >= 0 ? row[companiaIndex] : "",
        ramo: ramoIndex >= 0 ? row[ramoIndex] : "",
        cliente_id: clienteIndex >= 0 ? row[clienteIndex] : "",
      }))
      .filter((row) => String(row.id || "").trim());
    return segurosContabilidadAllCache;
  } catch {
    return [];
  }
};

const loadClientesForSegurosContabilidad = async () => {
  if (Array.isArray(segurosContabilidadClientesCache)) {
    return segurosContabilidadClientesCache;
  }
  const empresa = resolveCrmSegurosEmpresa();
  const params = new URLSearchParams({ servicio: "seguros" });
  const empresaId = resolveLegacyEmpresaId(empresa);
  if (empresaId) params.set("empresa_id", empresaId);
  try {
    const rows = await api(`/api/clientes_list?${params.toString()}`);
    const list = Array.isArray(rows) ? rows : [];
    list.sort((a, b) => {
      const nameA = normalizeNombre(formatNombreCliente(a.nombre));
      const nameB = normalizeNombre(formatNombreCliente(b.nombre));
      return nameA.localeCompare(nameB, "es", { numeric: true, sensitivity: "base" });
    });
    segurosContabilidadClientesCache = list;
    return list;
  } catch {
    if (Array.isArray(state.clientesList) && state.clientesList.length) {
      segurosContabilidadClientesCache = state.clientesList;
      return state.clientesList;
    }
    return [];
  }
};

const populateSegurosContabilidadClientesSelect = async (selectEl, selectedId = "") => {
  if (!selectEl) return;
  const clientes = await loadClientesForSegurosContabilidad();
  selectEl.innerHTML = "";
  if (!selectEl.multiple) {
    selectEl.appendChild(createOption("", "Selecciona cliente"));
  }
  clientes.forEach((cliente) => {
    selectEl.appendChild(createOption(cliente.id, formatNombreCliente(cliente.nombre)));
  });
  if (selectedId && !selectEl.multiple) {
    selectEl.value = selectedId;
  }
};

const parseGestoriaContaClienteIds = (raw, fallback = "") => {
  let items = [];
  if (Array.isArray(raw)) {
    items = raw;
  } else if (typeof raw === "string") {
    const text = raw.trim();
    if (text) {
      if (text.startsWith("[")) {
        try {
          const parsed = JSON.parse(text);
          items = Array.isArray(parsed) ? parsed : [parsed];
        } catch (_err) {
          items = text.split(",");
        }
      } else {
        items = text.split(",");
      }
    }
  } else if (raw) {
    items = [raw];
  }
  const out = [];
  items.forEach((item) => {
    const value = String(item || "").trim();
    if (value && !out.includes(value)) out.push(value);
  });
  const fallbackValue = String(fallback || "").trim();
  if (!out.length && fallbackValue) out.push(fallbackValue);
  return out;
};

const setSelectMultipleValues = (selectEl, values = []) => {
  if (!selectEl) return;
  const wanted = new Set((values || []).map((v) => String(v || "").trim()).filter(Boolean));
  Array.from(selectEl.options || []).forEach((option) => {
    option.selected = wanted.has(String(option.value || "").trim());
  });
};

const gestoriaContaRowForCliente = (row, clienteId) => {
  const wanted = String(clienteId || "").trim();
  if (!wanted || !row) return null;
  const assigned = parseGestoriaContaClienteIds(row.cliente_ids_json, row.cliente_id);
  if (!assigned.includes(wanted)) return null;
  const importe = parseMoneyValue(row.importe);
  const importeAsignado = assigned.length > 1 ? importe / assigned.length : importe;
  return { ...row, importe_asignado: Math.round(importeAsignado * 100) / 100, cliente_ids: assigned };
};

const fillGestoriaContabilidadPolizaSelect = async (selectEl, clienteId, selectedSeguroId = "") => {
  if (!selectEl) return;
  selectEl.innerHTML = "";
  selectEl.appendChild(createOption("", "Sin vincular"));
  let seguros = await loadSegurosForClienteContabilidad(clienteId);
  if (!seguros.length) {
    seguros = await loadAllSegurosForContabilidad();
  }
  seguros.forEach((seguro) => {
    const value = String(seguro.id || "").trim();
    if (!value) return;
    const label = [
      seguro.poliza_numero || "Sin número",
      seguro.compania || "Sin compañía",
      seguro.ramo || "",
    ]
      .filter(Boolean)
      .join(" · ");
    selectEl.appendChild(createOption(value, label));
  });
  selectEl.value = String(selectedSeguroId || "").trim();
  if (selectEl.value !== String(selectedSeguroId || "").trim()) {
    selectEl.value = "";
  }
};

const hydrateSegurosContabilidadFormSelects = async () => {
  if (!segurosContabilidadCliente || !segurosContabilidadPoliza) return;
  segurosContabilidadClientesCache = null;
  await populateSegurosContabilidadClientesSelect(
    segurosContabilidadCliente,
    segurosContabilidadCliente.value || ""
  );
  await fillGestoriaContabilidadPolizaSelect(
    segurosContabilidadPoliza,
    segurosContabilidadCliente.value || "",
    segurosContabilidadPoliza.value || ""
  );
  if (segurosContabilidadClientesMulti) {
    const selected = parseGestoriaContaClienteIds(
      Array.from(segurosContabilidadClientesMulti.selectedOptions || []).map((opt) => opt.value),
      segurosContabilidadCliente.value || ""
    );
    await populateSegurosContabilidadClientesSelect(
      segurosContabilidadClientesMulti,
      selected[0] || ""
    );
    setSelectMultipleValues(segurosContabilidadClientesMulti, selected);
  }
};

const hydrateSegurosRecibosFormSelects = async () => {
  if (!segurosRecibosCliente || !segurosRecibosPoliza) return;
  segurosContabilidadAllCache = null;
  await populateSegurosContabilidadClientesSelect(segurosRecibosCliente, segurosRecibosCliente.value || "");
  await fillGestoriaContabilidadPolizaSelect(
    segurosRecibosPoliza,
    segurosRecibosCliente.value || "",
    segurosRecibosPoliza.value || ""
  );
};

const hydrateSegurosSiniestrosFormSelects = async () => {
  if (!segurosSiniestrosCliente || !segurosSiniestrosPoliza) return;
  segurosContabilidadAllCache = null;
  await populateSegurosContabilidadClientesSelect(segurosSiniestrosCliente, segurosSiniestrosCliente.value || "");
  await fillGestoriaContabilidadPolizaSelect(
    segurosSiniestrosPoliza,
    segurosSiniestrosCliente.value || "",
    segurosSiniestrosPoliza.value || ""
  );
};

const ensureSelectedPolizaOption = (selectEl, seguroId, polizaNumero = "") => {
  if (!selectEl) return;
  const wanted = String(seguroId || "").trim();
  if (!wanted || selectEl.value === wanted) return;
  const label = (polizaNumero || "").trim() || "Póliza vinculada";
  selectEl.appendChild(createOption(wanted, `${label} · vinculada`));
  selectEl.value = wanted;
};

const loadGestoriaContabilidad = () => {
  if (!gestoriaContabilidadTable || !gestoriaContabilidadInfo) return;
  const params = buildGestoriaWorkspaceParams();
  if (!params.toString()) {
    gestoriaContabilidadTable.innerHTML = "<p class='muted'>Sin workspace.</p>";
    return;
  }
  api(`/api/gestoria_contabilidad?${params.toString()}`).then(async (data) => {
    const rows = data.rows || [];
    if (!rows.length) {
      gestoriaContabilidadTable.innerHTML = "<p class='muted'>Sin anotaciones contables.</p>";
      gestoriaContabilidadInfo.textContent = "";
      return;
    }
    const clienteIds = [
      ...new Set(
        rows
          .flatMap((row) => parseGestoriaContaClienteIds(row.cliente_ids_json, row.cliente_id))
          .filter(Boolean)
      ),
    ];
    await Promise.all(clienteIds.map((clienteId) => loadSegurosForClienteContabilidad(clienteId)));
    const table = document.createElement("table");
    const thead = document.createElement("thead");
    const trHead = document.createElement("tr");
    ["fecha", "concepto", "gestion", "tipo", "importe", "importe €", "póliza", "cliente", "notas", "accion"].forEach((col) => {
      const th = document.createElement("th");
      th.textContent = formatHeader(col);
      trHead.appendChild(th);
    });
    thead.appendChild(trHead);
    table.appendChild(thead);
    const tbody = document.createElement("tbody");
    for (const row of rows) {
      const tr = document.createElement("tr");
      const buildInput = (value, field, type = "text") => {
        const input = document.createElement("input");
        input.type = type;
        input.value = value || "";
        input.classList.add("inline-input");
        input.addEventListener("change", () => {
          saveGestoriaContabilidadField(row.id, field, input.value);
        });
        return input;
      };
      const buildSelect = (value, field, options) => {
        const select = document.createElement("select");
        select.classList.add("inline-input");
        options.forEach((opt) => select.appendChild(createOption(opt, opt)));
        select.value = value || options[0];
        select.addEventListener("change", () => {
          saveGestoriaContabilidadField(row.id, field, select.value);
        });
        return select;
      };
      const fechaTd = document.createElement("td");
      fechaTd.appendChild(buildInput(row.fecha, "fecha", "date"));
      tr.appendChild(fechaTd);
      const conceptoTd = document.createElement("td");
      conceptoTd.appendChild(buildInput(row.concepto, "concepto"));
      tr.appendChild(conceptoTd);
      const gestionTd = document.createElement("td");
      const gestiones = [
        "Herencias",
        "Tráfico",
        "Renta",
        "Modelos Hacienda",
        "Laboral",
        "Fiscal",
        "Contable",
        "Registro Mercantil",
        "Presentación cuentas",
        "Constitución sociedad",
        "Bajas/Altas",
        "Otros",
      ];
      const gestionSelect = document.createElement("select");
      gestionSelect.classList.add("inline-input");
      gestionSelect.appendChild(createOption("", "-"));
      gestiones.forEach((opt) => gestionSelect.appendChild(createOption(opt, opt)));
      if (row.gestion && !gestiones.includes(row.gestion)) {
        gestionSelect.appendChild(createOption(row.gestion, row.gestion));
      }
      gestionSelect.value = row.gestion || "";
      gestionSelect.addEventListener("change", () => {
        saveGestoriaContabilidadField(row.id, "gestion", gestionSelect.value);
      });
      gestionTd.appendChild(gestionSelect);
      tr.appendChild(gestionTd);
      const tipoTd = document.createElement("td");
      tipoTd.appendChild(buildSelect(row.tipo, "tipo", ["Ingreso", "Gasto"]));
      tr.appendChild(tipoTd);
      const importeTd = document.createElement("td");
      const importeInput = buildInput(row.importe, "importe", "number");
      importeInput.step = "0.01";
      importeInput.min = "0";
      importeTd.appendChild(importeInput);
      tr.appendChild(importeTd);
      const importeEurTd = document.createElement("td");
      const importeBadge = document.createElement("span");
      const refreshImporteBadge = () => {
        const parsed = Number.parseFloat(String(importeInput.value || "").replace(",", "."));
        importeBadge.textContent = Number.isFinite(parsed) ? euroFormatter.format(parsed) : "-";
      };
      refreshImporteBadge();
      importeInput.addEventListener("input", refreshImporteBadge);
      importeInput.addEventListener("change", refreshImporteBadge);
      importeEurTd.appendChild(importeBadge);
      tr.appendChild(importeEurTd);
      const polizaTd = document.createElement("td");
      const polizaSelect = document.createElement("select");
      polizaSelect.classList.add("inline-input");
      const rowClienteIds = parseGestoriaContaClienteIds(row.cliente_ids_json, row.cliente_id);
      const primaryClienteId = rowClienteIds[0] || "";
      await fillGestoriaContabilidadPolizaSelect(polizaSelect, primaryClienteId, row.seguro_id);
      ensureSelectedPolizaOption(polizaSelect, row.seguro_id, row.poliza_numero);
      polizaSelect.addEventListener("change", () => {
        saveGestoriaContabilidadField(row.id, "seguro_id", polizaSelect.value || "");
      });
      polizaTd.appendChild(polizaSelect);
      tr.appendChild(polizaTd);
      const clienteTd = document.createElement("td");
      const clienteSelect = document.createElement("select");
      clienteSelect.classList.add("inline-input");
      clienteSelect.appendChild(createOption("", "-"));
      const clientes = await loadClientesForSegurosContabilidad();
      clientes.forEach((cliente) => {
        const label = formatNombreCliente(cliente.nombre);
        clienteSelect.appendChild(createOption(cliente.id, label));
      });
      clienteSelect.value = primaryClienteId;
      clienteSelect.addEventListener("change", () => {
        saveGestoriaContabilidadField(row.id, "cliente_id", clienteSelect.value);
        fillGestoriaContabilidadPolizaSelect(polizaSelect, clienteSelect.value, "");
      });
      clienteTd.appendChild(clienteSelect);
      tr.appendChild(clienteTd);
      const notasTd = document.createElement("td");
      notasTd.appendChild(buildInput(row.notas, "notas"));
      tr.appendChild(notasTd);
      const actionTd = document.createElement("td");
      const delBtn = document.createElement("button");
      delBtn.type = "button";
      delBtn.textContent = "Eliminar";
      delBtn.addEventListener("click", () => {
        deleteGestoriaContabilidad(row.id);
      });
      actionTd.appendChild(delBtn);
      tr.appendChild(actionTd);
      tbody.appendChild(tr);
    }
    table.appendChild(tbody);
    gestoriaContabilidadTable.innerHTML = "";
    gestoriaContabilidadTable.appendChild(table);
    gestoriaContabilidadInfo.textContent = `Mostrando ${rows.length} anotaciones.`;
  });
};

