// Dashboard Gestoría (no admin): evitar avalanchas de peticiones concurrentes a /api/gestoria_trabajos
// (pueden saturar el pool de Postgres en Render). Cachea la respuesta por workspace unos segundos y
// reutiliza la misma Promise mientras está en vuelo.
const _gestoriaTrabajosDashCache = new Map();
const fetchGestoriaTrabajosForDashboard = () => {
  const key = getGestoriaWorkspaceScopeKey();
  if (!key) return Promise.resolve({ rows: [] });
  const now = Date.now();
  const cached = _gestoriaTrabajosDashCache.get(key);
  if (cached) {
    if (cached.data && now - cached.ts < 15000) {
      return Promise.resolve(cached.data);
    }
    if (cached.promise && now - cached.ts < 15000) {
      return cached.promise;
    }
  }
  const params = buildGestoriaWorkspaceParams({ limit: "600" });
  const promise = api(`/api/gestoria_trabajos?${params.toString()}`)
    .then((data) => {
      const payload = data && typeof data === "object" ? data : { rows: [] };
      _gestoriaTrabajosDashCache.set(key, { ts: Date.now(), data: payload, promise: null });
      return payload;
    })
    .catch((error) => {
      _gestoriaTrabajosDashCache.delete(key);
      throw error;
    });
  _gestoriaTrabajosDashCache.set(key, { ts: now, data: null, promise });
  return promise;
};

const loadGestoriaTrabajosOverview = () => {
  if (!gestoriaTrabajosTable || !gestoriaTrabajosInfo) return;
  if (!getGestoriaWorkspaceScopeKey()) {
    gestoriaTrabajosTable.innerHTML = "<p class='muted'>Sin workspace.</p>";
    return;
  }
  ensureGestoriaTrabajoCategorySelects();
  loadGestoriaTrabajoTipos()
    .then((rows) => {
      hydrateGestoriaTrabajoTipoSelect(gestoriaTrabajoTipoSelect, rows, { placeholder: "Tipo de gestión" });
      hydrateGestoriaTrabajoTipoSelect(gestoriaBudgetTipoTrabajo, rows);
      bindGestoriaTipoDefaults(gestoriaTrabajoTipoSelect, () => {
        if (!gestoriaTrabajoForm || !gestoriaTrabajoTipoSelect) return;
        const meta = getGestoriaTipoMeta(gestoriaTrabajoTipoSelect);
        const slaInput = gestoriaTrabajoForm.querySelector('[name="sla_dias"]');
        const importeInput = gestoriaTrabajoForm.querySelector('[name="importe"]');
        const currentSla = parseInt(String(slaInput?.value || "").trim(), 10);
        if (slaInput && (!String(slaInput.value || "").trim() || !Number.isFinite(currentSla)) && meta.sla_dias !== null) {
          slaInput.value = String(meta.sla_dias);
        }
        const currentImporte = parseMoneyValue(String(importeInput?.value || "").trim());
        if (importeInput && (!String(importeInput.value || "").trim() || currentImporte === 0) && meta.precio_base && meta.precio_base > 0) {
          importeInput.value = String(meta.precio_base);
        }
      });
    })
    .catch(() => {});
  fetchGestoriaTrabajosForDashboard().then((data) => {
    let rows = data.rows || [];
    const tipoFilterRaw = gestoriaTrabajosTipoFilter ? gestoriaTrabajosTipoFilter.value.trim() : "";
    const tipoFilter = normalizeGestoriaTrabajoCategory(tipoFilterRaw);
    const estadoFilter = gestoriaTrabajosEstadoFilter ? gestoriaTrabajosEstadoFilter.value.trim() : "";
    const limitValue = gestoriaTrabajosLimit ? parseInt(gestoriaTrabajosLimit.value, 10) : 20;
    if (tipoFilter) {
      rows = rows.filter((row) => {
        const cat = normalizeGestoriaTrabajoCategory(row.tipo_categoria) || classifyGestoriaTrabajoCategory(row.tipo_trabajo);
        return cat === tipoFilter;
      });
    }
    if (estadoFilter) {
      rows = rows.filter((row) => (row.estado || "") === estadoFilter);
    }
    rows.sort((a, b) => String(a.fecha_fin || "").localeCompare(String(b.fecha_fin || "")));
    if (!rows.length) {
      gestoriaTrabajosTable.innerHTML = "<p class='muted'>Sin gestiones activas.</p>";
      gestoriaTrabajosInfo.textContent = "";
      return;
    }
    const visibleRows = rows.slice(0, Number.isFinite(limitValue) ? limitValue : 20);
    const table = document.createElement("table");
    const thead = document.createElement("thead");
    const trHead = document.createElement("tr");
    ["cliente", "tipo_trabajo", "estado", "fecha_inicio", "fecha_fin", "responsable", "importe"].forEach((col) => {
      const th = document.createElement("th");
      th.textContent = formatHeader(col);
      trHead.appendChild(th);
    });
    thead.appendChild(trHead);
    table.appendChild(thead);
    const tbody = document.createElement("tbody");
    visibleRows.forEach((row) => {
      const tr = document.createElement("tr");
      const values = [
        row.cliente || "-",
        row.tipo_trabajo || "-",
        row.estado || "-",
        row.fecha_inicio || "-",
        row.fecha_fin || "-",
        row.responsable || "-",
        row.importe || "-",
      ];
      const cols = ["cliente", "tipo_trabajo", "estado", "fecha_inicio", "fecha_fin", "responsable", "importe"];
      values.forEach((value, idx) => {
        const td = document.createElement("td");
        if (!applyCompanyCell(td, cols[idx], value, { compact: true }) && !applyRamoCell(td, cols[idx], value)) {
          const formatted = formatCell(cols[idx], value);
          td.textContent = formatted === null ? "" : formatted;
        }
        tr.appendChild(td);
      });
      tbody.appendChild(tr);
    });
    table.appendChild(tbody);
    gestoriaTrabajosTable.innerHTML = "";
    gestoriaTrabajosTable.appendChild(table);
    gestoriaTrabajosInfo.textContent = `Mostrando ${visibleRows.length} gestiones.`;
  });
};

