const loadLegalRadarItems = async () => {
  if (!legalRadarTable) return;
  if (legalRadarInfo) legalRadarInfo.textContent = "Cargando...";
  try {
    const area = state.legalCurrentArea || "inmobiliaria";
    const data = await api(`/api/legal_radar_items?area=${encodeURIComponent(area)}&limit=100`);
    const rows = Array.isArray(data?.rows) ? data.rows : [];
    if (!rows.length) {
      legalRadarTable.innerHTML = "<div class='muted'>Sin alertas legales registradas.</div>";
      if (legalRadarInfo) legalRadarInfo.textContent = "0 alertas.";
      return;
    }
    const table = document.createElement("table");
    const thead = document.createElement("thead");
    thead.innerHTML = `
      <tr>
        <th>Fecha</th>
        <th>Fuente</th>
        <th>Título</th>
        <th>Impacto</th>
        <th>Estado</th>
        <th>Recomendación</th>
        <th>Acción</th>
      </tr>
    `;
    table.appendChild(thead);
    const tbody = document.createElement("tbody");
    rows.forEach((row) => {
      const tr = document.createElement("tr");
      const impactLabel = row.impact_score ? `${Math.round(Number(row.impact_score || 0) * 100)}%` : "Sin score";
      const impacts = [
        { label: "Documentos", values: Array.isArray(row.affected_documents) ? row.affected_documents : [] },
        { label: "Workflow", values: Array.isArray(row.affected_workflows) ? row.affected_workflows : [] },
        { label: "Cláusulas", values: Array.isArray(row.affected_clauses) ? row.affected_clauses : [] },
      ];
      const impactoHtml = `
        <div><strong>${escapeHtml(row.impacto || "Sin clasificar")}</strong> · ${escapeHtml(impactLabel)}</div>
        ${impacts
          .map((block) => `<div class="muted" style="margin-top:6px;"><strong>${escapeHtml(block.label)}:</strong></div>${renderLegalRadarImpacts(block.values)}`)
          .join("")}
      `;
      const buttons = [];
      if (normalizeSimple(row.estado || "") !== "revisado") {
        buttons.push(`<button class="secondary ghost button-inline" data-legal-radar-action="revisado" data-id="${row.id}">Revisado</button>`);
      }
      if (normalizeSimple(row.estado || "") !== "aplicado") {
        buttons.push(`<button class="secondary ghost button-inline" data-legal-radar-action="aplicado" data-id="${row.id}">Aplicado</button>`);
      }
      if (row.url) {
        buttons.push(`<a class="secondary ghost button-inline" href="${escapeHtml(row.url)}" target="_blank" rel="noreferrer">Abrir</a>`);
      }
      if (row.auto_detected) {
        buttons.push(`<span class="status-pill status-open">Auto</span>`);
      }
      tr.innerHTML = `
        <td>${escapeHtml(formatCell("fecha", row.fecha_publicacion || "") || row.fecha_publicacion || "-")}</td>
        <td>${escapeHtml(row.fuente || "-")}</td>
        <td>
          <div><strong>${escapeHtml(row.titulo || "-")}</strong></div>
          ${row.topic_key ? `<div class="muted">${escapeHtml(row.topic_key)}</div>` : ""}
        </td>
        <td>${impactoHtml}</td>
        <td><span class="crm-badge">${escapeHtml(row.estado || "Pendiente")}</span></td>
        <td>${escapeHtml(row.accion_recomendada || "Sin acción recomendada")}</td>
        <td>${buttons.join(" ")}</td>
      `;
      tbody.appendChild(tr);
    });
    table.appendChild(tbody);
    legalRadarTable.innerHTML = "";
    legalRadarTable.appendChild(table);
    if (legalRadarInfo) {
      const summary = data?.summary || {};
      legalRadarInfo.textContent = `${rows.length} alertas · pendientes ${summary.pendiente || 0} · revisadas ${summary.revisado || 0} · aplicadas ${summary.aplicado || 0} · auto ${summary.auto_detected || 0} · sincronizadas ${summary.knowledge_synced || 0}`;
    }
  } catch (error) {
    legalRadarTable.innerHTML = "<div class='muted'>No se pudo cargar el radar legal.</div>";
    if (legalRadarInfo) legalRadarInfo.textContent = error?.message || "Error";
  }
};

const goToEstudioAlta = (section = "compraventa") => {
  if (altaSection) {
    altaSection.dataset.estudioActive = section;
  }
  setTab("alta");
  updateEstudioAltaTabs();
};

const getHipotecaFieldValue = (row, columns, candidates = []) => {
  if (!Array.isArray(row) || !Array.isArray(columns)) return "";
  const keys = Array.isArray(candidates) ? candidates : [candidates];
  for (const key of keys) {
    const idx = columns.indexOf(key);
    if (idx >= 0) {
      const value = row[idx];
      if (value !== null && value !== undefined && String(value).trim() !== "") {
        return String(value).trim();
      }
    }
  }
  return "";
};

const getHipotecaDisplayName = (row, columns) => {
  const cliente = getHipotecaFieldValue(row, columns, [
    "cliente",
    "tomador",
    "nombre_cliente",
    "nombre",
    "titular",
  ]);
  if (cliente) return cliente;
  const id = getHipotecaFieldValue(row, columns, ["id"]);
  return id ? `Hipoteca ${id.slice(0, 8)}` : "Hipoteca sin nombre";
};

const buildHipotecaOptionLabel = (row, columns) => {
  const cliente = getHipotecaDisplayName(row, columns);
  const entidad = getHipotecaFieldValue(row, columns, ["entidad", "banco", "entidad_financiera"]);
  const fecha = getHipotecaFieldValue(row, columns, ["fecha_firma", "fecha", "fecha_entrada"]);
  const pieces = [cliente];
  if (entidad) pieces.push(entidad);
  if (fecha) pieces.push(fecha);
  return pieces.join(" · ");
};

const getHipotecaSignedYear = (row, columns) => {
  const raw = getHipotecaFieldValue(row, columns, ["fecha_firma", "fecha"]);
  if (raw) {
    const match = String(raw).trim().match(/^(\d{4})[-/]/);
    if (match) return match[1];
    const reverse = String(raw).trim().match(/[-/](\d{4})$/);
    if (reverse) return reverse[1];
  }
  const anio = getHipotecaFieldValue(row, columns, ["anio"]);
  return /^\d{4}$/.test(String(anio || "").trim()) ? String(anio).trim() : "";
};

const isHipotecaSignedForExport = (row, columns) => {
  const fechaFirma = getHipotecaFieldValue(row, columns, ["fecha_firma"]);
  const estado = normalizeSimple(getHipotecaFieldValue(row, columns, ["estado"]));
  if (!fechaFirma) return false;
  return estado === "firmada" || estado === "firmado";
};

const parseDateToTimestamp = (raw) => {
  const value = String(raw || "").trim();
  if (!value) return 0;
  // ISO: YYYY-MM-DD or YYYY/MM/DD
  const iso = value.match(/^(\d{4})[-/](\d{1,2})[-/](\d{1,2})/);
  if (iso) {
    const year = Number(iso[1]);
    const month = Number(iso[2]) - 1;
    const day = Number(iso[3]);
    const ts = Date.UTC(year, month, day);
    return Number.isFinite(ts) ? ts : 0;
  }
  // ES: DD/MM/YYYY or DD-MM-YYYY
  const es = value.match(/^(\d{1,2})[-/](\d{1,2})[-/](\d{4})/);
  if (es) {
    const day = Number(es[1]);
    const month = Number(es[2]) - 1;
    const year = Number(es[3]);
    const ts = Date.UTC(year, month, day);
    return Number.isFinite(ts) ? ts : 0;
  }
  const ts = Date.parse(value);
  return Number.isFinite(ts) ? ts : 0;
};

const getHipotecaFirmaTimestamp = (row, columns) => {
  const raw = getHipotecaFieldValue(row, columns, ["fecha_firma", "fecha"]);
  return parseDateToTimestamp(raw);
};

const buildHipotecaBdtSearchHaystack = (row, columns) => {
  const cliente = getHipotecaDisplayName(row, columns) || "";
  const banco = getHipotecaFieldValue(row, columns, ["banco", "entidad", "entidad_financiera"]);
  const oficina = getHipotecaFieldValue(row, columns, ["oficina"]);
  const estado = getHipotecaFieldValue(row, columns, ["estado"]);
  const encargo = getHipotecaFieldValue(row, columns, ["encargo"]);
  const fechaFirma = getHipotecaFieldValue(row, columns, ["fecha_firma", "fecha"]);
  const fechaEncargo = getHipotecaFieldValue(row, columns, ["fecha_encargo", "fecha_encargo_cliente", "fecha_encargo_banco"]);
  const anio = getHipotecaFieldValue(row, columns, ["anio", "año", "year"]);

  const estadoNorm = normalizeSimple(estado);
  const isEncargo = estadoNorm === "encargo" || estadoNorm === "encargado" || estadoNorm === "encargada";

  const extractYears = (value) => {
    const raw = String(value || "");
    const matches = raw.match(/\b(19\d{2}|20\d{2})\b/g);
    return matches ? matches : [];
  };
  const yearTokens = Array.from(
    new Set([...extractYears(fechaFirma), ...extractYears(fechaEncargo), ...extractYears(anio)])
  );
  const stageTags = isEncargo ? ["encargo"] : [];

  const clienteInmueble = safeParseJsonObject(getHipotecaFieldValue(row, columns, ["cliente_inmueble_json"]));
  const titulares = [
    getNestedValue(clienteInmueble, "prestataria.p1.nombre"),
    getNestedValue(clienteInmueble, "prestataria.p2.nombre"),
    getNestedValue(clienteInmueble, "comprador.c1.nombre"),
    getNestedValue(clienteInmueble, "comprador.c2.nombre"),
  ]
    .map((v) => String(v || "").trim())
    .filter(Boolean)
    .join(" + ");

  const dniTokens = [
    getNestedValue(clienteInmueble, "prestataria.p1.dni"),
    getNestedValue(clienteInmueble, "prestataria.p1.nif"),
    getNestedValue(clienteInmueble, "prestataria.p2.dni"),
    getNestedValue(clienteInmueble, "prestataria.p2.nif"),
    getNestedValue(clienteInmueble, "comprador.c1.dni"),
    getNestedValue(clienteInmueble, "comprador.c1.nif"),
    getNestedValue(clienteInmueble, "comprador.c2.dni"),
    getNestedValue(clienteInmueble, "comprador.c2.nif"),
    getHipotecaFieldValue(row, columns, ["dni", "nif", "documento", "doc"]),
  ]
    .map((v) => String(v || "").trim())
    .filter(Boolean);

  const normalizedDocTokens = dniTokens
    .map((token) => String(token || "").toUpperCase().replace(/[^0-9A-Z]/g, ""))
    .filter(Boolean);

  const textParts = [cliente, titulares, banco, oficina, estado, encargo, ...stageTags, fechaFirma, fechaEncargo, anio, ...yearTokens].filter(Boolean);
  const normalizedText = normalizeLookupText(textParts.join(" "));
  return { normalizedText, dniTokens, normalizedDocTokens };
};

const filterHipotecaBdtRows = (rows = [], columns = [], queryRaw = "") => {
  const q = String(queryRaw || "").trim();
  const normalizedQuery = normalizeLookupText(q);
  const docQuery = q.toUpperCase().replace(/[^0-9A-Z]/g, "");

  const signed = rows.filter((row) => isHipotecaSignedForExport(row, columns));
  const signedSorted = signed
    .slice()
    .sort((a, b) => getHipotecaFirmaTimestamp(b, columns) - getHipotecaFirmaTimestamp(a, columns));

  if (!normalizedQuery && !docQuery) {
    const getSortTimestamp = (row) => {
      const firma = getHipotecaFieldValue(row, columns, ["fecha_firma", "fecha"]);
      const encargo = getHipotecaFieldValue(row, columns, ["fecha_encargo", "fecha_encargo_cliente", "fecha_encargo_banco"]);
      return parseDateToTimestamp(firma || encargo);
    };
    const sorted = rows
      .slice()
      .sort((a, b) => getSortTimestamp(b) - getSortTimestamp(a));
    return {
      mode: "all",
      total: rows.length,
      signedTotal: signed.length,
      filtered: sorted.slice(0, 200),
      matchCount: rows.length,
    };
  }

  const filtered = rows.filter((row) => {
    const hay = buildHipotecaBdtSearchHaystack(row, columns);
    if (normalizedQuery && hay.normalizedText.includes(normalizedQuery)) return true;
    if (docQuery && docQuery.length >= 5) {
      if (hay.normalizedDocTokens.some((token) => token.includes(docQuery) || docQuery.includes(token))) return true;
    }
    return false;
  });

  const sorted = filtered
    .slice()
    .sort((a, b) => getHipotecaFirmaTimestamp(b, columns) - getHipotecaFirmaTimestamp(a, columns));

  return {
    mode: "search",
    total: rows.length,
    signedTotal: signed.length,
    filtered: sorted.slice(0, 200),
    matchCount: sorted.length,
  };
};

const syncHipotecaExportYears = (rows = [], columns = []) => {
  if (!hipotecaBdtExportYear) return;
  const current = String(hipotecaBdtExportYear.value || "").trim();
  const years = Array.from(
    new Set(
      rows
        .filter((row) => isHipotecaSignedForExport(row, columns))
        .map((row) => getHipotecaSignedYear(row, columns))
        .filter(Boolean)
    )
  ).sort((a, b) => Number(b) - Number(a));
  hipotecaBdtExportYear.innerHTML = "";
  hipotecaBdtExportYear.appendChild(createOption("", "Declarativo · Todos"));
  years.forEach((year) => {
    hipotecaBdtExportYear.appendChild(createOption(year, `Declarativo ${year}`));
  });
  if (current && years.includes(current)) {
    hipotecaBdtExportYear.value = current;
  }
};

const populateHipotecaVincularSelect = (rows = [], columns = []) => {
  if (!hipotecaBdtVincularSelect) return;
  const current = String(hipotecaBdtVincularSelect.value || "").trim();
  hipotecaBdtVincularSelect.innerHTML = "";
  const baseOption = document.createElement("option");
  baseOption.value = "";
  baseOption.textContent = "Seleccionar hipoteca…";
  hipotecaBdtVincularSelect.appendChild(baseOption);
  const idIndex = columns.indexOf("id");
  if (idIndex < 0) {
    hipotecaBdtVincularSelect.disabled = true;
    return;
  }
  rows.forEach((row) => {
    const id = String(row[idIndex] || "").trim();
    if (!id) return;
    const option = document.createElement("option");
    option.value = id;
    option.textContent = buildHipotecaOptionLabel(row, columns);
    hipotecaBdtVincularSelect.appendChild(option);
  });
  hipotecaBdtVincularSelect.disabled = rows.length === 0;
  if (current) {
    hipotecaBdtVincularSelect.value = current;
  }
};

const loadHipotecaBdt = (forceRefresh = false) => {
  if (!hipotecaBdtTable || !hipotecaBdtInfo) {
    return;
  }
  const empresa = resolveCrmFinEmpresa();
  const empresaId = resolveLegacyEmpresaId(empresa);
  if (!empresaId) {
    hipotecaBdtTable.innerHTML = "<p class='muted'>Sin empresa de hipotecas configurada.</p>";
    hipotecaBdtInfo.textContent = "";
    if (hipotecaBdtVincularStatus) hipotecaBdtVincularStatus.textContent = "";
    syncHipotecaExportYears([], []);
    populateHipotecaVincularSelect([], []);
    return;
  }
  const q = hipotecaBdtSearch ? hipotecaBdtSearch.value.trim() : "";
  // Para un buscador "potente" (DNI/NIF, titulares en JSON, etc.) cargamos el dataset
  // completo y filtramos en cliente. Evita depender del buscador del backend.
  const qApi = "";
  const cacheAgeMs = Date.now() - Number(state.hipotecaBdtCache?.ts || 0);
  const isFreshCache = cacheAgeMs >= 0 && cacheAgeMs < 30000;
  if (
    !forceRefresh &&
    state.hipotecaBdtCache &&
    state.hipotecaBdtCache.empresaId === empresaId &&
    state.hipotecaBdtCache.q === qApi &&
    isFreshCache
  ) {
    const cached = state.hipotecaBdtCache.data || {};
    const columns = cached.columns || [];
    const rows = cached.rows || [];
    renderHipotecaBdtList({ columns, rows, query: q });
    syncHipotecaExportYears(rows, columns);
    populateHipotecaVincularSelect(rows, columns);
    if (typeof syncHipotecaBdtViewToggle === "function") syncHipotecaBdtViewToggle();
    return;
  }
  const params = new URLSearchParams({
    empresa_id: empresaId,
    q: qApi,
    limit: "1000",
    include_json: "1",
  });
  api(`/api/hipoteca_bdt?${params.toString()}`)
    .then((data) => {
      const columns = data.columns || [];
      const rows = data.rows || [];
      state.hipotecaBdtCache = {
        empresaId,
        q: qApi,
        data: { columns, rows },
        ts: Date.now(),
      };
      renderHipotecaBdtList({ columns, rows, query: q });
      syncHipotecaExportYears(rows, columns);
      populateHipotecaVincularSelect(rows, columns);
      if (typeof syncHipotecaBdtViewToggle === "function") syncHipotecaBdtViewToggle();
    })
    .catch((error) => {
      const message = error?.data?.error || error?.message || "No se pudo cargar la BDT.";
      hipotecaBdtTable.innerHTML = `<p class='muted'>${message}</p>`;
      hipotecaBdtInfo.textContent = "";
      if (hipotecaBdtVincularStatus) hipotecaBdtVincularStatus.textContent = message;
      syncHipotecaExportYears([], []);
      populateHipotecaVincularSelect([], []);
      if (typeof syncHipotecaBdtViewToggle === "function") syncHipotecaBdtViewToggle();
    });
};

