const HIPOTECA_BDT_VIEW_STORAGE_KEY = "hipotecaBdtView";

const getHipotecaBdtView = () => {
  let stored = "";
  try {
    stored = String(localStorage.getItem(HIPOTECA_BDT_VIEW_STORAGE_KEY) || "").trim().toLowerCase();
  } catch {
    stored = "";
  }
  if (stored === "table" || stored === "tabla") return "table";
  return "cards";
};

const syncHipotecaBdtViewToggle = () => {
  const view = getHipotecaBdtView();
  const pairs = [
    [hipotecaBdtViewCards, view === "cards"],
    [hipotecaBdtViewTable, view === "table"],
  ];
  pairs.forEach(([btn, active]) => {
    if (!btn) return;
    btn.classList.toggle("active", Boolean(active));
    btn.setAttribute("aria-pressed", active ? "true" : "false");
  });
};

const setHipotecaBdtView = (view) => {
  const next = String(view || "").trim().toLowerCase();
  try {
    localStorage.setItem(HIPOTECA_BDT_VIEW_STORAGE_KEY, next);
  } catch {
    // ignore
  }
  if (typeof syncHipotecaBdtViewToggle === "function") syncHipotecaBdtViewToggle();
  const cached = state.hipotecaBdtCache?.data || {};
  const q = hipotecaBdtSearch ? hipotecaBdtSearch.value.trim() : "";
  renderHipotecaBdtList({ columns: cached.columns || [], rows: cached.rows || [], query: q });
};

const getHipotecaFichaFields = (columns = []) => {
  if (!Array.isArray(columns) || columns.length === 0) {
    return [...HIPOTECA_FICHA_PRIORITY_FIELDS];
  }
  const ignored = new Set(["id", "cliente_id"]);
  const available = columns.filter((col) => col && !ignored.has(col));
  const ordered = [];
  HIPOTECA_FICHA_PRIORITY_FIELDS.forEach((field) => {
    if (available.includes(field)) ordered.push(field);
  });
  available.forEach((field) => {
    if (!ordered.includes(field)) ordered.push(field);
  });
  return ordered;
};

const hipotecaRowToObject = (row, columns) => {
  const result = {};
  (columns || []).forEach((col, idx) => {
    result[col] = row?.[idx];
  });
  return result;
};

