const setupHipotecaPrestamoCuotasAuto = (panel) => {
  if (!panel) return;
  if (panel.dataset.prestamoAutoCuotas === "1") {
    // Recalcular en cada apertura, por si cambian valores.
    panel._hipotecaPrestamoAutoSync?.();
    return;
  }
  panel.dataset.prestamoAutoCuotas = "1";
  const plazoEl = panel.querySelector('[data-json="liquidacion_json"][data-path="prestamo.plazo_anos"]');
  const cuotasEl = panel.querySelector('[data-json="liquidacion_json"][data-path="prestamo.numero_cuotas"]');
  if (!plazoEl || !cuotasEl) return;
  // Permitir decimales si hace falta (p.e. cuotas no múltiplo de 12).
  try {
    plazoEl.step = "0.01";
  } catch (e) {}

  let guard = false;
  const syncFromPlazo = () => {
    if (guard) return;
    const years = toNumber(plazoEl.value);
    if (years === null) return;
    const cuotas = Math.round(years * 12);
    guard = true;
    cuotasEl.value = String(cuotas);
    guard = false;
  };
  const syncFromCuotas = () => {
    if (guard) return;
    const cuotas = toNumber(cuotasEl.value);
    if (cuotas === null) return;
    const years = cuotas / 12;
    const rounded = Math.abs(years - Math.round(years)) <= 0.001 ? String(Math.round(years)) : years.toFixed(2);
    guard = true;
    plazoEl.value = rounded;
    guard = false;
  };
  panel._hipotecaPrestamoAutoSync = () => {
    if (String(cuotasEl.value || "").trim() && !String(plazoEl.value || "").trim()) {
      syncFromCuotas();
    } else if (String(plazoEl.value || "").trim() && !String(cuotasEl.value || "").trim()) {
      syncFromPlazo();
    }
  };

  plazoEl.addEventListener("input", () => {
    syncFromPlazo();
    refreshHipotecaLiquidacionComputedControls(panel);
  });
  cuotasEl.addEventListener("input", () => {
    syncFromCuotas();
    refreshHipotecaLiquidacionComputedControls(panel);
  });
  panel._hipotecaPrestamoAutoSync();
};

const fetchHipotecaRowById = async (recordId) => {
  const id = String(recordId || "").trim();
  if (!id) return null;
  const empresa = resolveCrmFinEmpresa();
  const empresaId = resolveLegacyEmpresaId(empresa);
  if (!empresaId) return null;
  try {
    const params = new URLSearchParams({
      empresa_id: empresaId,
      id,
      include_json: "1",
      limit: "1",
    });
    const data = await api(`/api/hipoteca_bdt?${params.toString()}`);
    const columns = data?.columns || [];
    const rows = data?.rows || [];
    const idIndex = columns.indexOf("id");
    if (idIndex < 0) return null;
    const row = rows.find((item) => String(item[idIndex] || "").trim() === id);
    if (!row) return null;
    return { row, columns };
  } catch {
    return null;
  }
};

const openHipotecaFichaPrint = (recordId, section = "") => {
  const id = String(recordId || "").trim();
  if (!id) return;
  const params = new URLSearchParams({ id, autoprint: "1" });
  const normalized = String(section || "").trim();
  if (normalized) params.set("section", normalized);
  const url = `/api/hipoteca_ficha_print?${params.toString()}`;
  const w = window.open(url, "_blank", "noopener");
  if (!w) {
    alert("No se pudo abrir la impresión. Revisa si el navegador está bloqueando pop-ups para este sitio.");
  }
};

const downloadHipotecasFirmadasExcel = () => {
  const empresa = resolveCrmFinEmpresa();
  const empresaId = resolveLegacyEmpresaId(empresa);
  if (!empresaId) return;
  const params = new URLSearchParams({ empresa_id: empresaId });
  const year = String(hipotecaBdtExportYear?.value || "").trim();
  if (year) params.set("year", year);
  const url = `/api/hipotecas_firmadas_excel?${params.toString()}`;
  window.location.href = url;
};

const HIPOTECA_FICHA_DRAFT_ID = "__new__";

const syncHipotecaFichaPdfState = (panel, rowData = {}) => {
  if (!panel) return;
  const buttons = [
    panel.querySelector("#hipotecaFichaPdfComprador"),
    panel.querySelector("#hipotecaFichaPdfVendedor"),
    panel.querySelector("#hipotecaFichaPdfCheques"),
    panel.querySelector("#hipotecaFichaPdfNotaria"),
  ].filter(Boolean);
  if (!buttons.length) return;
  const recordId = String(panel.dataset.recordId || "").trim();
  const isDraft = recordId === HIPOTECA_FICHA_DRAFT_ID;
  // La impresión se controla por la “Revisión Excel” (cuadre y datos mínimos),
  // no por el estado de la operación (muchas históricas están en ESTUDIO).
  buttons.forEach((btn) => {
    btn.disabled = isDraft;
    btn.title = isDraft ? "Guarda la hipoteca para generar el PDF." : "";
  });
};

const setupHipotecaFichaMoneyInputs = (panel) => {
  if (!panel) return;
  if (panel.dataset.moneyFormatListeners === "1") return;
  panel.dataset.moneyFormatListeners = "1";
  panel
    .querySelectorAll(
      [
        // Campos base (columnas) y liquidación (comprador/vendedor/cuadre).
        '#hipotecaFichaForm input[inputmode="decimal"]:not([name="porcentaje"])',
        '#hipotecaFichaForm input[type="number"][step="0.01"]',
      ].join(",")
    )
    .forEach((el) => {
      const path = el.dataset.path || "";
      const jsonKey = el.dataset.json || "";
      const isLiquidacionMoney =
        jsonKey === "liquidacion_json" &&
        (path.startsWith("comprador.") || path.startsWith("vendedor.") || path.startsWith("cuadre.")) &&
        !path.startsWith("prestamo.");
      const isHipotecaDetalleMoney =
        jsonKey === "hipoteca_detalle_json" && ["condiciones.cuota"].includes(path);
      const isHipotecaMoney = !jsonKey && !path; // inputs name=... de la ficha (precio, comision, etc).
      if (!isLiquidacionMoney && !isHipotecaDetalleMoney && !isHipotecaMoney) return;
      el.addEventListener("blur", () => {
        const next = formatMoneyInputValue(el.value ?? "");
        if (String(next || "").trim()) el.value = next;
      });
    });
};

const setupHipotecaFichaDomicilioSync = (panel) => {
  if (!panel) return;
  if (typeof panel._hipotecaFichaApplyDomicilioSync === "function") {
    panel._hipotecaFichaApplyDomicilioSync();
    return;
  }
  panel.dataset.domicilioSyncListeners = "1";

  const c1Dom = panel.querySelector('[data-json="cliente_inmueble_json"][data-path="comprador.c1.domicilio"]');
  const c2Dom = panel.querySelector('[data-json="cliente_inmueble_json"][data-path="comprador.c2.domicilio"]');
  const same = panel.querySelector('[data-json="cliente_inmueble_json"][data-path="comprador.c2.mismo_domicilio"]');
  if (!c1Dom || !c2Dom || !same) return;

  const normalizeYes = (value) => ["si", "sí", "s"].includes(normalizeSimple(value));

  const apply = () => {
    const c1 = String(c1Dom.value || "").trim();
    const c2 = String(c2Dom.value || "").trim();
    if (!String(same.value || "").trim()) {
      same.value = !c2 || c2 === c1 ? "Sí" : "No";
    }
    const isSame = normalizeYes(same.value);
    if (isSame) {
      if (c1) c2Dom.value = c1;
      c2Dom.disabled = true;
    } else {
      c2Dom.disabled = false;
    }
  };

  same.addEventListener("change", apply);
  c1Dom.addEventListener("input", () => {
    if (normalizeYes(same.value)) apply();
  });
  c2Dom.addEventListener("input", () => {
    if (!c2Dom.disabled) same.value = "No";
  });
  panel._hipotecaFichaApplyDomicilioSync = apply;
  apply();
};

const setupHipotecaFichaComputedInputs = (panel) => {
  if (!panel) return;
  if (typeof panel._hipotecaFichaUpdateComputed === "function") {
    panel._hipotecaFichaUpdateComputed();
    return;
  }
  panel.dataset.hipotecaComputedListeners = "1";

  const precioInput = panel.querySelector('[name="precio"]');
  const hipotecaInput = panel.querySelector('[name="importe_hipoteca"]');
  const porcentajeInput = panel.querySelector('[name="porcentaje"]');
  const comisionInput = panel.querySelector('[name="comision"]');
  const comisionJuanInput = panel.querySelector('[name="comision_juan"]');
  const cesionInput = panel.querySelector('[name="cesion"]');
  const comisionModerniaInput = panel.querySelector('[name="comision_modernia"]');
  const oficinaInput = panel.querySelector('[name="oficina"]');
  const inmobiliariaHidden = panel.querySelector('[name="inmobiliaria_compra"]');
  const cesionHint = panel.querySelector("#hipotecaCesionHint");

  const normalizeText = (value) =>
    String(value || "")
      .toLowerCase()
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .trim()
      .replace(/\s+/g, " ");

  const MALAGA_BONUS_OFFICES = new Set([
    "modernia norte",
    "modernia oeste",
    "modernia centro",
    "verifika2 norte",
    "verifika2 oeste",
    "verifika2 centro",
    "malaga norte",
    "malaga oeste",
    "malaga centro",
  ]);

  const updateOficinaInmobiliaria = () => {
    if (!oficinaInput || !inmobiliariaHidden) return;
    const oficina = String(oficinaInput.value || "").trim();
    const inmo = String(inmobiliariaHidden.value || "").trim();
    if (!oficina && inmo) {
      oficinaInput.value = inmo;
    }
    if (oficina && inmo !== oficina) {
      inmobiliariaHidden.value = oficina;
    }
  };

  const updateFinanciacionPct = () => {
    if (!porcentajeInput) return;
    const precio = toNumber(precioInput?.value);
    const hipoteca = toNumber(hipotecaInput?.value);
    if (precio !== null && precio > 0 && hipoteca !== null) {
      porcentajeInput.value = ((hipoteca / precio) * 100).toFixed(2);
    } else {
      porcentajeInput.value = "";
    }
  };

  const updateCommissions = () => {
    if (!comisionInput) return;
    const total = toNumber(comisionInput.value);
    const oficina = normalizeText(oficinaInput?.value);
    const hasBonus = MALAGA_BONUS_OFFICES.has(oficina);
    const cesionRate = hasBonus ? 0.25 : 0.2;
    if (cesionHint) {
      cesionHint.textContent = hasBonus ? "Aplicando 25% (Centro/Norte/Oeste)." : "Aplicando 20% general.";
    }
    if (total === null) return;
    const juan = round2(total * 0.2);
    const cesion = round2(total * cesionRate);
    const modernia = round2(Math.max(total - juan - cesion, 0));
    if (comisionJuanInput) comisionJuanInput.value = formatMoneyInputValue(juan);
    if (cesionInput) cesionInput.value = formatMoneyInputValue(cesion);
    if (comisionModerniaInput) comisionModerniaInput.value = formatMoneyInputValue(modernia);
  };

  ["input", "change"].forEach((evt) => {
    precioInput?.addEventListener(evt, updateFinanciacionPct);
    hipotecaInput?.addEventListener(evt, updateFinanciacionPct);
    oficinaInput?.addEventListener(evt, () => {
      updateOficinaInmobiliaria();
      updateCommissions();
    });
    comisionInput?.addEventListener(evt, updateCommissions);
  });

  panel._hipotecaFichaUpdateComputed = () => {
    updateOficinaInmobiliaria();
    updateFinanciacionPct();
    updateCommissions();
  };
  panel._hipotecaFichaUpdateComputed();
};

const openHipotecaFichaDraft = ({ clienteNombre = "" } = {}) => {
  const panel = ensureHipotecaFichaPanel();
  if (!panel) return;
  panel.dataset.recordId = HIPOTECA_FICHA_DRAFT_ID;
  delete panel.dataset.pdfReviewBlocked;
  delete panel.dataset.pdfReviewBlockedReason;
  const meta = panel.querySelector("#hipotecaFichaMeta");
  const nombre = String(clienteNombre || "").trim();
  if (meta) meta.textContent = nombre ? `${nombre} · Nueva hipoteca` : "Nueva hipoteca";
  setHipotecaFichaTab("cliente");

  // Reset columnas base.
  HIPOTECA_FICHA_COLUMN_FIELDS.forEach((field) => {
    const control = panel.querySelector(`[name="${field}"]`);
    if (!control || control.disabled) return;
    if (control.tagName === "SELECT") {
      control.value = "";
    } else {
      control.value = "";
    }
  });
  const today = new Date().toISOString().slice(0, 10);
  const clienteInput = panel.querySelector('[name="cliente"]');
  if (clienteInput) clienteInput.value = nombre;
  const clienteIdInput = panel.querySelector('[name="cliente_id"]');
  if (clienteIdInput) clienteIdInput.value = "";
  const estadoSelect = panel.querySelector('[name="estado"]');
  if (estadoSelect && !String(estadoSelect.value || "").trim()) {
    setSelectValueCaseInsensitive(estadoSelect, "Pendiente");
  }
  const encargoSelect = panel.querySelector('[name="encargo"]');
  if (encargoSelect && !String(encargoSelect.value || "").trim()) {
    setSelectValueCaseInsensitive(encargoSelect, "Pendiente");
  }
  const fechaEncargoInput = panel.querySelector('[name="fecha_encargo"]');
  if (fechaEncargoInput && !String(fechaEncargoInput.value || "").trim()) {
    fechaEncargoInput.value = today;
  }

  // JSON inicial.
  const clienteInmueble = {};
  const hipotecaDetalle = {};
  const liquidacion = {};
  if (nombre) {
    setNestedValue(clienteInmueble, "comprador.c1.nombre", nombre);
    setNestedValue(clienteInmueble, "prestataria.p1.source", "c1");
    setNestedValue(clienteInmueble, "prestataria.p2.source", "none");
    setNestedValue(liquidacion, "comprador.cliente", nombre);
  }

  fillHipotecaFichaJson(panel, "cliente_inmueble_json", clienteInmueble);
  fillHipotecaFichaJson(panel, "hipoteca_detalle_json", hipotecaDetalle);
  fillHipotecaFichaJson(panel, "liquidacion_json", liquidacion);
  setupHipotecaIntervinientes(panel);
  setHipotecaLiquidacionTab(panel.dataset.liqTab || "comprador");
  syncHipotecaFichaPdfState(panel, {});
  syncHipotecaPrestatariaFromClientes(panel, clienteInmueble);
  autofillHipotecaLiquidacionFromFicha(panel);
  refreshHipotecaLiquidacionComputedControls(panel);
  setupHipotecaFichaMoneyInputs(panel);
  setupHipotecaFichaDomicilioSync(panel);
  setupHipotecaFichaComputedInputs(panel);
  updateHipotecaRegistroDatalist(panel);
  updateHipotecaNotariasDatalist(panel);
  setupHipotecaPrestamoCuotasAuto(panel);

  const status = panel.querySelector("#hipotecaFichaStatus");
  if (status) status.textContent = "";
  panel.classList.remove("hidden");
  panel.classList.add("open");
  window.requestAnimationFrame(() => {
    try {
      panel
        .querySelector('[data-json="cliente_inmueble_json"][data-path="comprador.c1.nombre"]')
        ?.focus?.();
    } catch (e) {}
  });
};

const openHipotecaFicha = async (recordId, prefetched = null) => {
  const target = String(recordId || "").trim();
  if (!target) return;
  if (target === HIPOTECA_FICHA_DRAFT_ID) {
    openHipotecaFichaDraft();
    return;
  }
  const panel = ensureHipotecaFichaPanel();
  if (!panel) return;
  // Importante: evitar que queden valores “arrastrados” de la ficha anterior si el siguiente
  // registro trae campos vacíos o aún no tiene JSON. Reseteamos el formulario antes de rellenar.
  try {
    panel.querySelectorAll("#hipotecaFichaForm input, #hipotecaFichaForm select, #hipotecaFichaForm textarea").forEach((el) => {
      if (!el || el.disabled) return;
      const tag = String(el.tagName || "").toUpperCase();
      if (tag === "INPUT") {
        const t = String(el.type || "").toLowerCase();
        if (t === "checkbox" || t === "radio") {
          el.checked = false;
          return;
        }
      }
      el.value = "";
    });
  } catch (e) {}
  panel.dataset.recordId = target;
  const meta = panel.querySelector("#hipotecaFichaMeta");
  if (meta) meta.textContent = "Cargando ficha...";
  panel.classList.remove("hidden");
  panel.classList.add("open");
  let found = prefetched;
  if (!found) {
    found = findHipotecaBdtRowById(target);
  }
  if (!found) {
    found = await fetchHipotecaRowById(target);
  }
  if (!found) return;
  const rowData = hipotecaRowToObject(found.row, found.columns);
  if (meta) {
    const cliente = String(rowData.cliente || "").trim() || `Hipoteca ${target.slice(0, 8)}`;
    meta.textContent = `${cliente} · ID ${target.slice(0, 8)}`;
  }
  syncHipotecaFichaPdfState(panel, rowData);
  setHipotecaFichaTab("cliente");
  HIPOTECA_FICHA_COLUMN_FIELDS.forEach((field) => {
    const control = panel.querySelector(`[name="${field}"]`);
    if (!control) return;
    const raw = rowData[field];
    if (control.tagName === "SELECT") {
      setSelectValueCaseInsensitive(control, raw);
      return;
    }
    const cfg = EDITABLE_FIELDS.hipotecas?.[field] || { type: "text" };
    if (cfg.type === "money") {
      control.value = formatMoneyInputValue(raw ?? "");
    } else if (cfg.type === "percent") {
      const parsed = toNumber(raw);
      control.value = parsed === null ? (raw ?? "") : String(parsed);
    } else if (cfg.type === "date") {
      const value = String(raw || "").trim();
      control.value = /^\d{4}-\d{2}-\d{2}$/.test(value) ? value : "";
    } else if (cfg.type === "number") {
      const parsed = toNumber(raw);
      control.value = parsed === null ? "" : String(parsed);
    } else {
      control.value = raw ?? "";
    }
  });

  const clienteInmueble = safeParseJsonObject(rowData.cliente_inmueble_json);
  const hipotecaDetalle = safeParseJsonObject(rowData.hipoteca_detalle_json);
  const liquidacion = safeParseJsonObject(rowData.liquidacion_json);

  // Defaults (si el JSON está vacío o viene de instalaciones anteriores).
  const fallbackCliente = String(rowData.cliente || "").trim();
  if (!String(getNestedValue(clienteInmueble, "comprador.c1.nombre") || "").trim() && fallbackCliente) {
    setNestedValue(clienteInmueble, "comprador.c1.nombre", fallbackCliente);
  }
  // Parte prestataria: por defecto, 1º prestatario = C1 y 2º prestatario = C2 (si existe).
  const c2Nombre = String(getNestedValue(clienteInmueble, "comprador.c2.nombre") || "").trim();
  if (!String(getNestedValue(clienteInmueble, "prestataria.p1.source") || "").trim()) {
    setNestedValue(clienteInmueble, "prestataria.p1.source", "c1");
  }
  if (!String(getNestedValue(clienteInmueble, "prestataria.p2.source") || "").trim()) {
    setNestedValue(clienteInmueble, "prestataria.p2.source", c2Nombre ? "c2" : "none");
  }
  if (!String(getNestedValue(liquidacion, "comprador.cliente") || "").trim() && fallbackCliente) {
    setNestedValue(liquidacion, "comprador.cliente", fallbackCliente);
  }
  const precio = toNumber(rowData.precio);
  const importeHipoteca = toNumber(rowData.importe_hipoteca);
  if ((getNestedValue(liquidacion, "comprador.precio_compra") ?? "") === "" && precio !== null) {
    setNestedValue(liquidacion, "comprador.precio_compra", precio);
    setNestedValue(liquidacion, "comprador.escriturado", precio);
  }
  if ((getNestedValue(liquidacion, "comprador.hipoteca.capital") ?? "") === "" && importeHipoteca !== null) {
    setNestedValue(liquidacion, "comprador.hipoteca.capital", importeHipoteca);
  }
  if (!String(getNestedValue(liquidacion, "comprador.hipoteca.seguro_proteccion_financiado") || "").trim()) {
    setNestedValue(liquidacion, "comprador.hipoteca.seguro_proteccion_financiado", "No");
  }
  if (!String(getNestedValue(liquidacion, "comprador.hipoteca.seguro_hogar_financiado") || "").trim()) {
    setNestedValue(liquidacion, "comprador.hipoteca.seguro_hogar_financiado", "No");
  }
  if (!String(getNestedValue(liquidacion, "comprador.hipoteca.seguro_vida_financiado") || "").trim()) {
    setNestedValue(liquidacion, "comprador.hipoteca.seguro_vida_financiado", "No");
  }
  if ((getNestedValue(liquidacion, "comprador.entregas.prestamo_concedido") ?? "") === "" && importeHipoteca !== null) {
    setNestedValue(liquidacion, "comprador.entregas.prestamo_concedido", importeHipoteca);
  }
  if (!String(getNestedValue(liquidacion, "notaria.entidad") || "").trim()) {
    const bank = String(rowData.banco || "").trim();
    if (bank) setNestedValue(liquidacion, "notaria.entidad", bank);
  }
  if (!String(getNestedValue(hipotecaDetalle, "precontractual.seguro_rc") || "").trim()) {
    setNestedValue(
      hipotecaDetalle,
      "precontractual.seguro_rc",
      "LLOYD’S (EXSEL U.A., S.L.) · Póliza BASWZ1733315598407A",
    );
  }

  fillHipotecaFichaJson(panel, "cliente_inmueble_json", clienteInmueble);
  fillHipotecaFichaJson(panel, "hipoteca_detalle_json", hipotecaDetalle);
  fillHipotecaFichaJson(panel, "liquidacion_json", liquidacion);
  setupHipotecaIntervinientes(panel);
  setHipotecaLiquidacionTab(panel.dataset.liqTab || "comprador");
  syncHipotecaPrestatariaFromClientes(panel, clienteInmueble);
  autofillHipotecaLiquidacionFromFicha(panel);
  refreshHipotecaLiquidacionComputedControls(panel);
  setupHipotecaFichaMoneyInputs(panel);
  setupHipotecaFichaDomicilioSync(panel);
  setupHipotecaFichaComputedInputs(panel);
  updateHipotecaRegistroDatalist(panel);
  updateHipotecaNotariasDatalist(panel);
  setupHipotecaPrestamoCuotasAuto(panel);

  if (panel.dataset.liquidacionListeners !== "1") {
    panel.dataset.liquidacionListeners = "1";
    panel.querySelectorAll('[data-json="liquidacion_json"][data-path]:not([readonly])').forEach((el) => {
      el.addEventListener("input", () => refreshHipotecaLiquidacionComputedControls(panel));
      el.addEventListener("change", () => refreshHipotecaLiquidacionComputedControls(panel));
    });
  }
  if (panel.dataset.prestatariaListeners !== "1") {
    panel.dataset.prestatariaListeners = "1";
    panel.querySelectorAll('[data-json="cliente_inmueble_json"][data-path^="prestataria."][data-path$=".source"]').forEach((el) => {
      el.addEventListener("change", () => {
        const fresh = collectHipotecaFichaJson(panel, "cliente_inmueble_json");
        syncHipotecaPrestatariaFromClientes(panel, fresh);
      });
    });
  }
  if (panel.dataset.prestatariaClienteSyncListeners !== "1") {
    panel.dataset.prestatariaClienteSyncListeners = "1";
    panel
      .querySelectorAll(
        [
          '[data-json="cliente_inmueble_json"][data-path^="comprador.c1."]',
          '[data-json="cliente_inmueble_json"][data-path^="comprador.c2."]',
        ].join(",")
      )
      .forEach((el) => {
        el.addEventListener("change", () => {
          const fresh = collectHipotecaFichaJson(panel, "cliente_inmueble_json");
          syncHipotecaPrestatariaFromClientes(panel, fresh);
        });
      });
  }
  if (panel.dataset.liquidacionAutofillListeners !== "1") {
    panel.dataset.liquidacionAutofillListeners = "1";
    panel.querySelector('[name="cliente"]')?.addEventListener("change", () => autofillHipotecaLiquidacionFromFicha(panel));
    panel.querySelector('[name="banco"]')?.addEventListener("change", () => autofillHipotecaLiquidacionFromFicha(panel));
    panel.querySelector('[name="fecha_firma"]')?.addEventListener("change", () => autofillHipotecaLiquidacionFromFicha(panel));
    panel.querySelector('[name="precio"]')?.addEventListener("change", () => autofillHipotecaLiquidacionFromFicha(panel));
    panel.querySelector('[name="importe_hipoteca"]')?.addEventListener("change", () => autofillHipotecaLiquidacionFromFicha(panel));
    panel.querySelectorAll('[data-json="cliente_inmueble_json"][data-path^="inmueble."]').forEach((el) => {
      el.addEventListener("change", () => autofillHipotecaLiquidacionFromFicha(panel));
    });
    panel.querySelectorAll('[data-json="cliente_inmueble_json"][data-path^="comprador.c1."]').forEach((el) => {
      el.addEventListener("change", () => autofillHipotecaLiquidacionFromFicha(panel));
    });
    panel.querySelectorAll('[data-json="cliente_inmueble_json"][data-path^="comprador.c2."]').forEach((el) => {
      el.addEventListener("change", () => autofillHipotecaLiquidacionFromFicha(panel));
    });
    panel.querySelectorAll(
      [
        '[data-json="cliente_inmueble_json"][data-path="inmueble.localidad"]',
        '[data-json="cliente_inmueble_json"][data-path="inmueble.provincia"]',
        '[data-json="liquidacion_json"][data-path="vendedor.localidad"]',
        '[data-json="liquidacion_json"][data-path="comprador.localidad"]',
        '[data-json="liquidacion_json"][data-path="comprador.provincia"]',
      ].join(",")
    ).forEach((el) => {
      el.addEventListener("change", () => updateHipotecaRegistroDatalist(panel));
    });
  }
  const status = panel.querySelector("#hipotecaFichaStatus");
  if (status) status.textContent = "";
  panel.classList.remove("hidden");
  panel.classList.add("open");
};

const saveHipotecaFicha = async (event) => {
  event.preventDefault();
  const panel = ensureHipotecaFichaPanel();
  if (!panel) return;
  const recordId = String(panel.dataset.recordId || "").trim();
  if (!recordId) return;
  const isDraft = recordId === HIPOTECA_FICHA_DRAFT_ID;
  const status = panel.querySelector("#hipotecaFichaStatus");
  if (status) status.textContent = isDraft ? "Creando hipoteca..." : "Guardando cambios...";
  const empresa = resolveCrmFinEmpresa();
  const base = {
    empresa_id: empresa?.id || "",
    empresa_nombre: empresa?.nombre || resolveCrmFinEmpresaNombre(),
  };

  const payload = {
    id: isDraft ? "" : recordId,
    ...base,
  };

  HIPOTECA_FICHA_COLUMN_FIELDS.forEach((field) => {
    const control = panel.querySelector(`[name="${field}"]`);
    if (!control || control.disabled) return;
    const cfg = EDITABLE_FIELDS.hipotecas?.[field] || { type: "text" };
    const value = control.value ?? "";
    if (cfg.type === "money" || cfg.type === "percent" || cfg.type === "number") {
      const parsed = toNumber(value);
      payload[field] = parsed === null ? "" : parsed;
      return;
    }
    payload[field] = value;
  });

  const clienteInmueble = normalizeHipotecaPrestatariaForSave(collectHipotecaFichaJson(panel, "cliente_inmueble_json"));
  const hipotecaDetalle = collectHipotecaFichaJson(panel, "hipoteca_detalle_json");
  const liquidacion = computeHipotecaLiquidacionComputed(collectHipotecaFichaJson(panel, "liquidacion_json"));
  payload.cliente_inmueble_json = JSON.stringify(clienteInmueble || {}, null, 0);
  payload.hipoteca_detalle_json = JSON.stringify(hipotecaDetalle || {}, null, 0);
  payload.liquidacion_json = JSON.stringify(liquidacion || {}, null, 0);

  const prestatarioNombre = String(getNestedValue(clienteInmueble, "prestataria.p1.nombre") || "").trim();
  const c1Nombre = String(getNestedValue(clienteInmueble, "comprador.c1.nombre") || "").trim();
  const liqCliente = String(getNestedValue(liquidacion, "comprador.cliente") || "").trim();
  payload.cliente = prestatarioNombre || c1Nombre || liqCliente || String(payload.cliente || "").trim() || "";

  // Sync: si rellenan el precio de compra/capital en Liquidación, reflejarlo en columnas principales.
  if ((payload.precio ?? "") === "") {
    const liqPrecio = toNumber(
      getNestedValue(liquidacion, "comprador.precio_compra") ?? getNestedValue(liquidacion, "comprador.escriturado")
    );
    if (liqPrecio !== null) payload.precio = liqPrecio;
  }
  if ((payload.importe_hipoteca ?? "") === "") {
    const liqCapital = toNumber(getNestedValue(liquidacion, "comprador.hipoteca.capital"));
    if (liqCapital !== null) payload.importe_hipoteca = liqCapital;
  }
  // Sync: reflejar tipo de interés en `tipo_hipoteca` para listados/filtros legacy.
  if (!String(payload.tipo_hipoteca || "").trim()) {
    const tipoInteres = String(getNestedValue(hipotecaDetalle, "preferencias.tipo_interes") || "").trim();
    if (tipoInteres) payload.tipo_hipoteca = tipoInteres;
  }

  try {
    if (isDraft) {
      const cliente = String(payload.cliente || "").trim();
      if (!cliente) {
        if (status) status.textContent = "Indica al menos el comprador (C1) para crear la hipoteca.";
        return;
      }
      const createPayload = { ...base };
      // Evita “herencias”/reutilización accidental: cada nueva operación debe crear un registro nuevo,
      // incluso si coincide cliente/estado con una pendiente previa.
      createPayload.force_new = true;
      // Endpoint legacy: crea (o reutiliza) una hipoteca en BDT y nos devuelve el id.
      [
        "cliente",
        "cliente_id",
        "banco",
        "oficina",
        "inmobiliaria_compra",
        "asesor",
        "estado",
        "encargo",
        "tipo_hipoteca",
        "fecha_encargo",
        "fecha_firma",
        "precio",
        "importe_hipoteca",
        "porcentaje",
        "entrada",
        "comision",
        "cesion",
        "comision_juan",
        "comision_modernia",
        "anio",
      ].forEach((key) => {
        if (payload[key] !== undefined) createPayload[key] = payload[key];
      });
      const created = await postJsonWithDbRetry("/api/hipotecas", createPayload, {
        maxRetries: 3,
        baseDelayMs: 220,
        timeoutMs: 25000,
      });
      const newId = String(created?.id || "").trim();
      if (!newId) {
        if (status) status.textContent = "No se pudo obtener el id de la nueva hipoteca.";
        return;
      }
      panel.dataset.recordId = newId;
      payload.id = newId;
      const meta = panel.querySelector("#hipotecaFichaMeta");
      if (meta) meta.textContent = `${cliente || "Hipoteca"} · ID ${newId.slice(0, 8)}`;
      syncHipotecaFichaPdfState(panel, payload);
      if (status) status.textContent = created?.created ? "Hipoteca creada. Guardando ficha..." : "Hipoteca encontrada. Guardando ficha...";
    }

    await postJsonWithDbRetry("/api/hipotecas_update", payload, {
      maxRetries: 3,
      baseDelayMs: 220,
      timeoutMs: 25000,
    });
    if (status) status.textContent = "Cambios guardados.";
    loadHipotecaBdt(true);
    loadFinCrm();
    loadHipotecaDashboard();
    loadHomeHipotecaStats().then(() => renderCompanyCards());
    setTimeout(() => {
      if (status) status.textContent = "";
    }, 1200);
  } catch (error) {
    const message = String(error?.message || "").trim();
    if (status) status.textContent = message || "Error API al guardar cambios.";
    try {
      console.error("saveHipotecaFicha error", error);
    } catch (e) {}
  }
};

	const setSelectValueCaseInsensitive = (selectEl, rawValue) => {
	  if (!selectEl) return;
	  const value = String(rawValue ?? "").trim();
	  if (!value) {
	    selectEl.value = "";
	    return;
	  }
	  const exact = Array.from(selectEl.options).find((opt) => String(opt.value) === value);
	  if (exact) {
	    selectEl.value = exact.value;
	    return;
	  }
	  const normalized = normalizeSimple(value);
	  const byNormalized = Array.from(selectEl.options).find(
	    (opt) => normalizeSimple(String(opt.value || "")) === normalized
	  );
	  selectEl.value = byNormalized ? byNormalized.value : "";
	};

const renderHipotecaBdtList = ({ columns = [], rows = [], query } = {}) => {
  const q = typeof query === "string" ? query : hipotecaBdtSearch ? hipotecaBdtSearch.value.trim() : "";
  const result = filterHipotecaBdtRows(rows, columns, q);
  const filteredRows = result.filtered || [];
  const view = getHipotecaBdtView();
  if (view === "table") {
    renderHipotecaBdtTable({ columns, rows: filteredRows });
  } else {
    renderHipotecaBdtCards({ columns, rows: filteredRows });
  }
  if (hipotecaBdtInfo) {
    if (result.mode === "all") {
      hipotecaBdtInfo.textContent = `Mostrando ${filteredRows.length} de ${result.total} hipotecas · firmadas ${result.signedTotal}. Usa el buscador para afinar.`;
    } else {
      const shown = filteredRows.length;
      hipotecaBdtInfo.textContent = `Resultados ${shown} de ${result.matchCount} · firmadas ${result.signedTotal} · dataset ${result.total}.`;
    }
  }
};

const renderHipotecaBdtCards = ({ columns = [], rows = [] } = {}) => {
  if (!hipotecaBdtTable) return;
  const idIndex = columns.indexOf("id");
  if (idIndex < 0) {
    hipotecaBdtTable.innerHTML = "<p class='muted'>No hay identificador para abrir fichas.</p>";
    return;
  }

  const getValue = (row, field) => {
    const idx = columns.indexOf(field);
    if (idx < 0) return "";
    return row?.[idx] ?? "";
  };

  const buildTitularesLabel = (row) => {
    const clienteInmueble = safeParseJsonObject(getValue(row, "cliente_inmueble_json"));
    const p1Nombre = String(getNestedValue(clienteInmueble, "prestataria.p1.nombre") || "").trim();
    const p2Source = normalizePrestatariaSource(getNestedValue(clienteInmueble, "prestataria.p2.source"));
    const p2Nombre =
      p2Source && p2Source !== "none"
        ? String(getNestedValue(clienteInmueble, "prestataria.p2.nombre") || "").trim()
        : "";
    const titulares = [p1Nombre, p2Nombre].map((v) => String(v || "").trim()).filter(Boolean);
    if (titulares.length) return titulares.join(" + ");
    const c1 = String(getNestedValue(clienteInmueble, "comprador.c1.nombre") || "").trim();
    const c2 = String(getNestedValue(clienteInmueble, "comprador.c2.nombre") || "").trim();
    const fallback = [c1, c2].filter(Boolean);
    if (fallback.length) return fallback.join(" + ");
    return getHipotecaDisplayName(row, columns) || String(getValue(row, "cliente") || "").trim() || "Sin titulares";
  };

  const formatYears = (value) => {
    const num = toNumber(value);
    if (num === null) return "";
    if (!Number.isFinite(num) || num <= 0) return "";
    const normalized = Math.round(num);
    return `${normalized} años`;
  };

  const formatInterest = (value) => {
    const num = toNumber(value);
    if (num === null) return "";
    return formatPercent(num);
  };

  const formatMoneyMaybe = (value) => {
    const num = toNumber(value);
    if (num === null) return "";
    return formatEurosCompact(num);
  };

  const cardGrid = document.createElement("div");
  cardGrid.className = "hipoteca-bdt-cards";

  rows.forEach((row) => {
    const recordId = row[idIndex];
    const titulares = buildTitularesLabel(row);
    const banco = String(getValue(row, "banco") || "").trim();
    const oficina = String(getValue(row, "oficina") || "").trim();
    const precio = getValue(row, "precio");
    const importeHipoteca = getValue(row, "importe_hipoteca");
    const comision = getValue(row, "comision");

    const hipotecaDetalle = safeParseJsonObject(getValue(row, "hipoteca_detalle_json"));
    const plazo = getNestedValue(hipotecaDetalle, "preferencias.plazo_anos");
    const interes = getNestedValue(hipotecaDetalle, "condiciones.interes");
    const cuota = getNestedValue(hipotecaDetalle, "condiciones.cuota");

    const brand = resolveHipotecaBankBrand(banco);
    const canGeneratePdf = isHipotecaSignedForExport(row, columns);

    const card = document.createElement("div");
    card.className = "hipoteca-bdt-card is-clickable";
    card.setAttribute("role", "button");
    card.setAttribute("tabindex", "0");
    card.setAttribute("aria-label", `Abrir ficha hipoteca: ${titulares}`);
    const openFicha = () => openHipotecaFicha(recordId, { row, columns });
    card.addEventListener("click", (event) => {
      const target = event?.target;
      if (target && typeof target.closest === "function") {
        if (target.closest("button, a, input, select, textarea, label")) return;
      }
      openFicha();
    });
    card.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        openFicha();
      }
    });

    const header = document.createElement("div");
    header.className = "hipoteca-bdt-card-head";

    const badge = document.createElement("div");
    badge.className = "hipoteca-bdt-bank";
    if (brand.logo) {
      const logo = document.createElement("img");
      logo.className = "hipoteca-bdt-bank-logo";
      logo.src = brand.logo;
      logo.alt = brand.displayName;
      logo.loading = "lazy";
      if (brand.logoOnDark) {
        logo.style.background = brand.color;
      }
      logo.addEventListener(
        "error",
        () => {
          const initials = document.createElement("span");
          initials.className = "hipoteca-bdt-bank-initials";
          initials.style.background = brand.color;
          initials.textContent = brand.short;
          logo.replaceWith(initials);
        },
        { once: true }
      );
      badge.appendChild(logo);
    } else {
      const initials = document.createElement("span");
      initials.className = "hipoteca-bdt-bank-initials";
      initials.style.background = brand.color;
      initials.textContent = brand.short;
      badge.appendChild(initials);
    }
    const bankName = document.createElement("span");
    bankName.className = "hipoteca-bdt-bank-name";
    bankName.textContent = banco || brand.displayName;
    badge.appendChild(bankName);
    header.appendChild(badge);

    const title = document.createElement("div");
    title.className = "hipoteca-bdt-card-title";
    title.textContent = titulares;

    const meta = document.createElement("div");
    meta.className = "hipoteca-bdt-card-meta";
    const metaItems = [];
    if (oficina) metaItems.push(`Oficina: ${oficina}`);
    meta.textContent = metaItems.join(" · ");

    const metrics = document.createElement("div");
    metrics.className = "hipoteca-bdt-card-metrics";
    const metricRows = [
      ["Precio hipoteca", formatMoneyMaybe(importeHipoteca)],
      ["Precio compra", formatMoneyMaybe(precio)],
      ["Plazo", formatYears(plazo)],
      ["Interés", formatInterest(interes)],
      ["Cuota", formatMoneyMaybe(cuota)],
      ["Comisión", formatMoneyMaybe(comision)],
    ].filter(([, value]) => String(value || "").trim());
    metricRows.forEach(([label, value]) => {
      const rowEl = document.createElement("div");
      rowEl.className = "hipoteca-bdt-metric";
      const k = document.createElement("span");
      k.className = "k";
      k.textContent = label;
      const v = document.createElement("span");
      v.className = "v";
      v.textContent = String(value || "").trim();
      rowEl.appendChild(k);
      rowEl.appendChild(v);
      metrics.appendChild(rowEl);
    });

	    const actions = document.createElement("div");
	    actions.className = "inline-actions";
	    const pdfBtn = document.createElement("button");
	    pdfBtn.type = "button";
	    pdfBtn.className = "secondary";
	    pdfBtn.textContent = "PDF";
    pdfBtn.disabled = !canGeneratePdf;
    pdfBtn.title = canGeneratePdf ? "" : "Disponible solo para firmadas con fecha de firma.";
    pdfBtn.addEventListener("click", () => openHipotecaFichaPrint(recordId));

    const deleteBtn = document.createElement("button");
    deleteBtn.type = "button";
    deleteBtn.className = "danger";
    deleteBtn.textContent = "Eliminar";
    deleteBtn.addEventListener("click", async () => {
      if (!recordId) return;
      if (!window.confirm("¿Eliminar esta hipoteca? Esta acción no se puede deshacer.")) return;
      const data = await deleteHipoteca(recordId);
      if (data?.error) {
        alert(data.error);
        return;
      }
      if (String(document.getElementById("hipotecaBdtFichaPanel")?.dataset.recordId || "") === String(recordId)) {
        closeHipotecaFichaPanel();
      }
      loadHipotecaBdt(true);
      loadFinCrm();
      loadHipotecaDashboard();
      loadHomeHipotecaStats().then(() => renderCompanyCards());
	    });

	    actions.appendChild(pdfBtn);
	    actions.appendChild(deleteBtn);

    card.appendChild(header);
    card.appendChild(title);
    if (meta.textContent) card.appendChild(meta);
    if (metrics.childElementCount) card.appendChild(metrics);
    card.appendChild(actions);

    cardGrid.appendChild(card);
  });

  hipotecaBdtTable.innerHTML = "";
  hipotecaBdtTable.appendChild(cardGrid);
};

	const renderHipotecaBdtTable = (data) => {
	  if (!hipotecaBdtTable) return;
	  const columns = data?.columns || [];
	  const rows = data?.rows || [];
	  const idIndex = columns.indexOf("id");
  if (idIndex < 0) {
    hipotecaBdtTable.innerHTML = "<p class='muted'>No hay identificador para abrir fichas.</p>";
    return;
  }
  const table = document.createElement("table");
  const thead = document.createElement("thead");
  const trHead = document.createElement("tr");
  const displayCols = HIPOTECA_BDT_LIST_COLUMNS.filter((col) => columns.includes(col));
  displayCols.forEach((col) => {
    const th = document.createElement("th");
    th.textContent = formatHeader(col);
    trHead.appendChild(th);
  });
  const thAction = document.createElement("th");
  thAction.textContent = "ACCIONES";
  trHead.appendChild(thAction);
  thead.appendChild(trHead);
  table.appendChild(thead);
  const tbody = document.createElement("tbody");
  rows.forEach((row) => {
    const tr = document.createElement("tr");
    displayCols.forEach((col) => {
      const td = document.createElement("td");
      const idx = columns.indexOf(col);
      const value = idx >= 0 ? row[idx] : "";
      const formatted = formatCell(col, value);
      td.textContent = formatted === null ? "" : formatted;
      tr.appendChild(td);
    });
    const tdAction = document.createElement("td");
    const actions = document.createElement("div");
    actions.className = "inline-actions";
    const recordId = row[idIndex];
    const canGeneratePdf = isHipotecaSignedForExport(row, columns);
    const openBtn = document.createElement("button");
    openBtn.type = "button";
    openBtn.className = "secondary";
    openBtn.textContent = "Abrir ficha";
    openBtn.addEventListener("click", () => {
      openHipotecaFicha(recordId, { row, columns });
    });
    const pdfBtn = document.createElement("button");
    pdfBtn.type = "button";
    pdfBtn.className = "secondary";
    pdfBtn.textContent = "PDF";
    pdfBtn.disabled = !canGeneratePdf;
    pdfBtn.title = canGeneratePdf ? "" : "Disponible solo para firmadas con fecha de firma.";
    pdfBtn.addEventListener("click", () => {
      openHipotecaFichaPrint(recordId);
    });
    const deleteBtn = document.createElement("button");
    deleteBtn.type = "button";
    deleteBtn.className = "danger";
    deleteBtn.textContent = "Eliminar";
    deleteBtn.addEventListener("click", async () => {
      if (!recordId) return;
      if (!window.confirm("¿Eliminar esta hipoteca? Esta acción no se puede deshacer.")) return;
      const data = await deleteHipoteca(recordId);
      if (data?.error) {
        alert(data.error);
        return;
      }
      if (String(document.getElementById("hipotecaBdtFichaPanel")?.dataset.recordId || "") === String(recordId)) {
        closeHipotecaFichaPanel();
      }
      loadHipotecaBdt(true);
      loadFinCrm();
      loadHipotecaDashboard();
      loadHomeHipotecaStats().then(() => renderCompanyCards());
    });
    actions.appendChild(openBtn);
    actions.appendChild(pdfBtn);
    actions.appendChild(deleteBtn);
    tdAction.appendChild(actions);
    tr.appendChild(tdAction);
    tbody.appendChild(tr);
  });
  table.appendChild(tbody);
  hipotecaBdtTable.innerHTML = "";
  hipotecaBdtTable.appendChild(table);
};

const findHipotecaBdtRowById = (id) => {
  const target = String(id || "").trim();
  const cached = state.hipotecaBdtCache?.data || {};
  const columns = cached.columns || [];
  const rows = cached.rows || [];
  if (!target || !Array.isArray(columns) || !Array.isArray(rows)) return null;
  const idIndex = columns.indexOf("id");
  if (idIndex < 0) return null;
  const row = rows.find((item) => String(item[idIndex] || "").trim() === target);
  if (!row) return null;
  return { row, columns };
};

const linkFinanciacionServiceToCliente = async (clienteId, empresaId) => {
  const payload = {
    cliente_id: clienteId,
    ...(isTenantWorkspaceMode() && state.currentWorkspaceId ? { workspace_id: state.currentWorkspaceId } : { empresa_id: empresaId }),
    servicio: "Financiaciones",
    estado: "Activo",
    fecha_inicio: new Date().toISOString().slice(0, 10),
  };
  const data = await postJsonWithDbRetry("/api/clientes_link", payload, {
    retries: 1,
    delayMs: 120,
  });
  const errorText = String(data?.error || "").toLowerCase();
  if (data?.error && !errorText.includes("existe") && !errorText.includes("ya")) {
    throw new Error(data.error);
  }
  return data;
};

const createClienteForHipoteca = async (nombre, sourceRow, columns) => {
  const payload = {
    id: randomId(),
    tipo_persona: "Física",
    nombre: String(nombre || "").trim(),
    procedencia_detalle: "Financiaciones (BDT)",
  };
  if (isTenantWorkspaceMode() && state.currentWorkspaceId) {
    payload.workspace_id = state.currentWorkspaceId;
  }
  const nif = getHipotecaFieldValue(sourceRow, columns, ["nif", "dni", "documento"]);
  const telefono = getHipotecaFieldValue(sourceRow, columns, ["telefono", "movil", "teléfono"]);
  const email = getHipotecaFieldValue(sourceRow, columns, ["email", "correo"]);
  const direccion = getHipotecaFieldValue(sourceRow, columns, ["direccion", "dirección"]);
  if (nif) payload.nif = normalizeDocumento(nif);
  if (telefono) payload.telefono = telefono;
  if (email) payload.email = email;
  if (direccion) payload.direccion = direccion;
  const response = await fetch("/api/clientes", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  const data = await response.json();
  if (data?.error) {
    if (response.status === 409 && data.id) {
      return data.id;
    }
    throw new Error(data.error);
  }
  return data?.id || payload.id;
};

const vincularHipotecaSeleccionada = async () => {
  if (!hipotecaBdtVincularSelect || !hipotecaBdtVincularStatus) return;
  const selectedId = String(hipotecaBdtVincularSelect.value || "").trim();
  if (!selectedId) {
    hipotecaBdtVincularStatus.textContent = "Selecciona una hipoteca para vincular.";
    return;
  }
  const empresa = resolveCrmFinEmpresa();
  if (!empresa?.id) {
    hipotecaBdtVincularStatus.textContent = "Empresa de Financiaciones no disponible.";
    return;
  }
  const selected = findHipotecaBdtRowById(selectedId);
  if (!selected) {
    hipotecaBdtVincularStatus.textContent = "No se encuentra la hipoteca seleccionada.";
    return;
  }
  const { row, columns } = selected;
  const nombreCliente = getHipotecaDisplayName(row, columns);
  if (!nombreCliente) {
    hipotecaBdtVincularStatus.textContent = "No hay nombre de cliente para vincular.";
    return;
  }
  hipotecaBdtVincularBtn?.setAttribute("disabled", "disabled");
  hipotecaBdtVincularStatus.textContent = "Vinculando hipoteca con cliente...";
  try {
    const existing = await lookupClienteByNombre(nombreCliente);
    let clienteId = existing?.id || "";
    let wasNew = false;
    if (!clienteId) {
      clienteId = await createClienteForHipoteca(nombreCliente, row, columns);
      wasNew = true;
    }
    const empresaId = resolveLegacyEmpresaId(empresa);
    await linkFinanciacionServiceToCliente(clienteId, empresaId);
    const clienteNombrePersistido = String(existing?.nombre || nombreCliente || "").trim();
    await postJsonWithDbRetry(
      "/api/hipotecas_update",
      {
        id: selectedId,
        empresa_id: empresaId,
        empresa_nombre: empresa.nombre,
        cliente_id: clienteId,
        cliente: clienteNombrePersistido,
      },
      { retries: 1, delayMs: 120 }
    );
    await refreshClientesSummary();
    loadHipotecaBdt(true);
    hipotecaBdtVincularStatus.textContent = wasNew
      ? `Cliente creado y vinculado a Financiaciones: ${nombreCliente}`
      : `Servicio Financiaciones vinculado al cliente: ${existing?.nombre || nombreCliente}`;
  } catch (error) {
    hipotecaBdtVincularStatus.textContent =
      error?.message || "No se pudo completar la vinculación.";
  } finally {
    hipotecaBdtVincularBtn?.removeAttribute("disabled");
  }
};

const formatDaysMetric = (value) => {
  const num = Number(value);
  if (!Number.isFinite(num) || num <= 0) return "-";
  return `${num.toFixed(1)} días`;
};

