const sendTableUpdate = (table, recordId, column, value, statusEl = null) => {
  if (!recordId) {
    return Promise.resolve();
  }
  const endpointMap = {
    seguros: "/api/seguros_update",
    gestoria: "/api/gestoria_update",
    hipotecas: "/api/hipotecas_update",
  };
  const endpoint = endpointMap[table] || "/api/gestoria_update";
  const infoTarget = statusEl || tableInfo;
  if (infoTarget) {
    infoTarget.textContent = "Actualizando...";
  }
  const empresa =
    table === "hipotecas"
      ? resolveCrmFinEmpresa()
      : table === "seguros"
        ? resolveCrmSegurosEmpresa()
        : resolveCrmGestoriaEmpresa();
  const empresaNombre =
    (empresa?.nombre || "").trim()
      || (table === "hipotecas"
        ? resolveCrmFinEmpresaNombre()
        : table === "seguros"
          ? resolveCrmSegurosEmpresaNombre()
          : resolveCrmGestoriaEmpresaNombre());
  const payload = {
    id: recordId,
    empresa_id: empresa?.id || "",
    empresa_nombre: empresaNombre,
    [column]: value,
  };
  return fetch(endpoint, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  })
    .then((res) => res.json())
    .then((data) => {
      if (data.error) {
        if (infoTarget) {
          infoTarget.textContent = data.error;
        }
        return;
      }
      if (infoTarget) {
        infoTarget.textContent = "Actualizado.";
        const baseText = infoTarget.dataset.baseText;
        if (baseText) {
          setTimeout(() => {
            infoTarget.textContent = baseText;
          }, 1200);
        }
      }
    })
    .catch(() => {
      if (infoTarget) {
        infoTarget.textContent = "Error al actualizar.";
      }
    });
};

const renderTable = (data, options = {}) => {
  const { columns, rows } = data;
  const showActions = options.showActions;
  const editableTable = options.editableTable;
  const statusEl = options.infoEl || tableInfo;
  const tableMount = options.container || tableContainer;
  if (!tableMount) return;
  const editableFields = editableTable ? EDITABLE_FIELDS[editableTable] : null;
  const internalCols = new Set(["id", "poliza_key", "poliza_url"]);
  const allDisplayableColumns = (Array.isArray(columns) ? columns : []).filter(
    (col) => col && !internalCols.has(col)
  );
  const requestedVisible = Array.isArray(options.visibleColumns) ? options.visibleColumns : null;
  const visibleColumns = requestedVisible?.length
    ? requestedVisible.filter((col) => allDisplayableColumns.includes(col))
    : allDisplayableColumns;
  const colIndexMap = new Map();
  (Array.isArray(columns) ? columns : []).forEach((col, idx) => {
    colIndexMap.set(col, idx);
  });
  const idIndex = Array.isArray(columns) ? columns.indexOf("id") : -1;
  const table = document.createElement("table");
  const thead = document.createElement("thead");
  const trHead = document.createElement("tr");
  visibleColumns.forEach((col) => {
    const th = document.createElement("th");
    th.textContent = formatHeader(col);
    trHead.appendChild(th);
  });
  if (showActions) {
    const th = document.createElement("th");
    th.textContent = "ACCION";
    trHead.appendChild(th);
  }
  thead.appendChild(trHead);
  table.appendChild(thead);

  const tbody = document.createElement("tbody");
  (Array.isArray(rows) ? rows : []).forEach((row) => {
    const tr = document.createElement("tr");
    const rowId = idIndex >= 0 && Array.isArray(row) ? row[idIndex] : "";
    visibleColumns.forEach((colName) => {
      const idx = colIndexMap.get(colName);
      const cell = idx === undefined || !Array.isArray(row) ? "" : row[idx];
      const td = document.createElement("td");
      if (editableFields && editableFields[colName]) {
        const config = editableFields[colName];
        if (config.type === "select") {
          const select = document.createElement("select");
          const empty = document.createElement("option");
          empty.value = "";
          empty.textContent = "-";
          select.appendChild(empty);
          config.options.forEach((optionValue) => {
            const option = document.createElement("option");
            option.value = optionValue;
            option.textContent = optionValue;
            select.appendChild(option);
          });
          select.value = cell ?? "";
          select.addEventListener("change", () => {
            sendTableUpdate(editableTable, rowId, colName, select.value, statusEl);
          });
          td.appendChild(select);
        } else {
          const input = document.createElement("input");
          const isMoneyType = config.type === "money";
          const isPercentType = config.type === "percent";
          input.type = isMoneyType || isPercentType ? "text" : config.type;
          if (isMoneyType) {
            input.value = formatMoneyInputValue(cell ?? "");
          } else if (isPercentType) {
            const parsed = toNumber(cell);
            input.value = parsed === null ? (cell ?? "") : String(parsed);
          } else {
            input.value = cell ?? "";
          }
          input.addEventListener("change", () => {
            if (isMoneyType) {
              const parsed = toNumber(input.value);
              const valueToSave = parsed === null ? "" : parsed;
              sendTableUpdate(editableTable, rowId, colName, valueToSave, statusEl);
              input.value = parsed === null ? "" : euroFormatter.format(parsed);
              return;
            }
            if (isPercentType) {
              const parsed = toNumber(input.value);
              const valueToSave = parsed === null ? "" : parsed;
              sendTableUpdate(editableTable, rowId, colName, valueToSave, statusEl);
              input.value = parsed === null ? "" : String(parsed);
              return;
            }
            sendTableUpdate(editableTable, rowId, colName, input.value, statusEl);
          });
          td.appendChild(input);
        }
      } else {
        const formatted = formatCell(colName, cell);
        td.textContent = formatted === null ? "" : formatted;
      }
      tr.appendChild(td);
    });
    if (showActions) {
      const td = document.createElement("td");
      const actions = document.createElement("div");
      actions.className = "inline-actions";
      const signBtn = document.createElement("button");
      signBtn.textContent = "Firmar";
      signBtn.addEventListener("click", () => {
        const fecha = prompt("Fecha firma (YYYY-MM-DD):");
        if (!fecha) return;
        const payload = { id: rowId, fecha_firma: fecha, estado: "FIRMADA" };
        fetch("/api/hipotecas/firmar", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(payload),
        })
          .then((res) => res.json())
          .then((data) => {
            if (data.error) {
              alert(data.error);
              return;
            }
            loadTable();
            const empresa = resolveCrmFinEmpresa();
            const empresaId = resolveLegacyEmpresaId(empresa);
            if (empresaId) renderFinDashboard(empresaId);
          });
      });
      actions.appendChild(signBtn);
      const deleteBtn = document.createElement("button");
      deleteBtn.textContent = "Eliminar";
      deleteBtn.className = "danger";
      deleteBtn.addEventListener("click", async () => {
        if (!rowId) return;
        if (!window.confirm("¿Eliminar esta hipoteca? Esta acción no se puede deshacer.")) return;
        const data = await deleteHipoteca(rowId);
        if (data?.error) {
          alert(data.error);
          return;
        }
        loadHipotecaBdt(true);
        loadTable();
        loadHipotecaDashboard();
        loadHomeHipotecaStats().then(() => renderCompanyCards());
      });
      actions.appendChild(deleteBtn);
      td.appendChild(actions);
      tr.appendChild(td);
    }
    tbody.appendChild(tr);
  });
  table.appendChild(tbody);
  tableMount.innerHTML = "";
  tableMount.appendChild(table);
  UI?.enhanceFragment(tableMount);
};

const getSegurosBdtSortValue = (colName, raw) => {
  const name = normalizeSimple(colName || "");
  if (!name) return String(raw || "");
  if (name.includes("fecha")) {
    const value = String(raw || "").trim();
    if (!value) return "";
    const parsed = new Date(value);
    return Number.isNaN(parsed.getTime()) ? value : parsed.getTime();
  }
  if (name.includes("prima") || name.includes("comision") || name.includes("importe")) {
    return parseMoneyValue(raw);
  }
  return normalizeSimple(formatCell(colName, raw) ?? raw ?? "");
};

const renderTableInto = (data, container, infoEl, label) => {
  if (!container) {
    return;
  }
  const { columns, rows } = data;
  const hasPolizaKey = columns.includes("poliza_key");
  const hasPolizaUrl = columns.includes("poliza_url");
  const polizaKeyIndex = columns.indexOf("poliza_key");
  const polizaUrlIndex = columns.indexOf("poliza_url");
  const showPdf = label === "Seguros" && (hasPolizaKey || hasPolizaUrl);
  const showOcr =
    label === "Seguros" && currentTab === "seguros-crm" && state.segurosTab === "bdt";
  const showSeguroFichaAction =
    label === "Seguros" && currentTab === "seguros-crm" && state.segurosTab === "bdt";
  const showHipotecaActions = label === "Hipotecas";
  const showCaptacionActions = (label === "Captaciones" || label === "Pipeline") && currentTab === "crm";
  const enableColumnFilters =
    label === "Seguros" && currentTab === "seguros-crm" && state.segurosTab === "bdt";
  const segurosCompactColumns = [
    "tomador",
    "compania",
    "ramo",
    "poliza_numero",
    "fecha_efecto",
    "fecha_vencimiento",
    "comision",
    "estado",
    "estado_renovacion",
    "cliente_id",
  ];
  // Pipeline Inmobiliaria: vista compacta por defecto (evita tablas interminables).
  const pipelineCompactColumns = [
    "direccion",
    "propietario",
    "etapa",
    "proxima_accion",
    "fecha_contacto",
    "responsable",
    "precio_pedido_cliente",
    "precio_encargo",
  ];
  const displayColumns =
    label === "Seguros"
      ? segurosCompactColumns.filter((col) => columns.includes(col))
      : (label === "Pipeline" || label === "Captaciones")
        ? pipelineCompactColumns.filter((col) => columns.includes(col))
      : columns.filter((col) => col !== "id" && col !== "poliza_key" && col !== "poliza_url");
  const idIndex = columns.indexOf("id");
  const clienteIdIndex = columns.indexOf("cliente_id");
  const colIndexMap = new Map();
  columns.forEach((col, idx) => {
    colIndexMap.set(col, idx);
  });
  const rowsView = Array.isArray(rows) ? [...rows] : [];
  if (enableColumnFilters && state.segurosBdtSort && state.segurosBdtSort.col) {
    const sortCol = state.segurosBdtSort.col;
    const sortDir = state.segurosBdtSort.dir === "desc" ? -1 : 1;
    const sortIdx = colIndexMap.get(sortCol);
    if (sortIdx !== undefined) {
      rowsView.sort((a, b) => {
        const av = getSegurosBdtSortValue(sortCol, a[sortIdx]);
        const bv = getSegurosBdtSortValue(sortCol, b[sortIdx]);
        if (typeof av === "number" && typeof bv === "number") {
          return (av - bv) * sortDir;
        }
        return String(av).localeCompare(String(bv), "es", { sensitivity: "base" }) * sortDir;
      });
    }
  }
  const table = document.createElement("table");
  const thead = document.createElement("thead");
  const trHead = document.createElement("tr");
  const columnFilterInputs = [];
  displayColumns.forEach((col) => {
    const th = document.createElement("th");
    const sorted = enableColumnFilters && state.segurosBdtSort && state.segurosBdtSort.col === col;
    const arrow = sorted ? (state.segurosBdtSort.dir === "desc" ? " ▼" : " ▲") : "";
    th.textContent = `${formatHeader(col)}${arrow}`;
    if (enableColumnFilters) {
      th.style.cursor = "pointer";
      th.title = "Ordenar";
      th.addEventListener("click", () => {
        const current = state.segurosBdtSort || {};
        if (current.col === col) {
          state.segurosBdtSort = { col, dir: current.dir === "asc" ? "desc" : "asc" };
        } else {
          state.segurosBdtSort = { col, dir: "asc" };
        }
        loadSegurosCrm();
      });
    }
    trHead.appendChild(th);
  });
  if (showPdf) {
    const th = document.createElement("th");
    th.textContent = "PDF";
    trHead.appendChild(th);
  }
  if (showOcr) {
    const th = document.createElement("th");
    th.textContent = "OCR";
    trHead.appendChild(th);
  }
  if (showSeguroFichaAction || showHipotecaActions || showCaptacionActions) {
    const th = document.createElement("th");
    th.textContent = "Acciones";
    trHead.appendChild(th);
  }
  thead.appendChild(trHead);
  if (enableColumnFilters) {
    const trFilters = document.createElement("tr");
    displayColumns.forEach((col) => {
      const th = document.createElement("th");
      const input = document.createElement("input");
      input.type = "search";
      input.placeholder = `Filtrar ${formatHeader(col).toLowerCase()}`;
      input.className = "inline-input";
      input.dataset.col = col;
      th.appendChild(input);
      trFilters.appendChild(th);
      columnFilterInputs.push(input);
    });
    if (showPdf) trFilters.appendChild(document.createElement("th"));
    if (showOcr) trFilters.appendChild(document.createElement("th"));
    if (showSeguroFichaAction || showHipotecaActions || showCaptacionActions) trFilters.appendChild(document.createElement("th"));
    thead.appendChild(trFilters);
  }
  table.appendChild(thead);

  const tbody = document.createElement("tbody");
  const filterRows = [];
  rowsView.forEach((row) => {
    const tr = document.createElement("tr");
    const rowMap = buildRowMap(row, columns);
    const recordId = idIndex >= 0 ? row[idIndex] : "";
    displayColumns.forEach((colName) => {
      const idx = colIndexMap.get(colName);
      const cell = idx === undefined ? "" : row[idx];
      const td = document.createElement("td");
      const canOpenSeguro =
        label === "Seguros" &&
        currentTab === "seguros-crm" &&
        state.segurosTab === "bdt" &&
        colName === "poliza_numero" &&
        String(recordId || "").trim();
      if (canOpenSeguro) {
        const btn = document.createElement("button");
        btn.type = "button";
        btn.className = "ghost";
        const formatted = formatCell(colName, cell);
        btn.textContent = formatted === null || formatted === "" ? "Abrir póliza" : String(formatted);
        btn.addEventListener("click", (event) => {
          event.preventDefault();
          event.stopPropagation();
          openSeguroById(recordId, rowMap.cliente_id || "");
        });
        td.appendChild(btn);
      } else if (!applyCompanyCell(td, colName, cell) && !applyRamoCell(td, colName, cell)) {
        const formatted = formatCell(colName, cell);
        td.textContent = formatted === null ? "" : formatted;
      }
      tr.appendChild(td);
    });
    if (showPdf) {
      const td = document.createElement("td");
      const key = polizaKeyIndex >= 0 ? row[polizaKeyIndex] : "";
      const url = polizaUrlIndex >= 0 ? row[polizaUrlIndex] : "";
      if (key || url) {
        const btn = document.createElement("button");
        btn.type = "button";
        btn.className = "secondary";
        btn.textContent = "Ver";
        btn.addEventListener("click", () => {
          openS3File(key, url);
        });
        td.appendChild(btn);
      } else {
        td.textContent = "-";
      }
      tr.appendChild(td);
    }
    if (showOcr) {
      const td = document.createElement("td");
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "secondary";
      btn.textContent = "OCR + cargar";
      const status = document.createElement("span");
      status.className = "muted";
      status.style.marginLeft = "8px";
      const fileInput = document.createElement("input");
      fileInput.type = "file";
      fileInput.accept = "application/pdf";
      fileInput.className = "hidden";
      btn.addEventListener("click", () => {
        if (!recordId) {
          status.textContent = "Sin id.";
          return;
        }
        fileInput.click();
      });
      fileInput.addEventListener("change", () => {
        const file = fileInput.files && fileInput.files[0];
        if (!file) return;
        if (!/pdf$/i.test(file.type) && !/\.pdf$/i.test(file.name || "")) {
          status.textContent = "Solo PDF.";
          return;
        }
        runSegurosBdtRowOcr(recordId, file, status, rowMap);
      });
      td.appendChild(btn);
      td.appendChild(status);
      td.appendChild(fileInput);
      tr.appendChild(td);
    }
    if (showSeguroFichaAction) {
      const td = document.createElement("td");
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "secondary";
      btn.textContent = "Abrir ficha";
      btn.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        openSeguroPage(
          rowMap,
          {
            id: clienteIdIndex >= 0 ? row[clienteIdIndex] : "",
            nombre: rowMap.tomador || "",
          },
          { onSaved: () => loadSegurosCrm() }
        );
      });
      td.appendChild(btn);
      tr.appendChild(td);
    }
    if (showHipotecaActions) {
      const td = document.createElement("td");
      const actions = document.createElement("div");
      actions.className = "inline-actions";
      const openBtn = document.createElement("button");
      openBtn.type = "button";
      openBtn.className = "secondary";
      openBtn.textContent = "Abrir ficha";
      openBtn.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        openHipotecaFicha(recordId, { row, columns });
      });
      actions.appendChild(openBtn);
      const deleteBtn = document.createElement("button");
      deleteBtn.type = "button";
      deleteBtn.className = "danger";
      deleteBtn.textContent = "Eliminar";
      deleteBtn.addEventListener("click", async (event) => {
        event.preventDefault();
        event.stopPropagation();
        if (!recordId) return;
        if (!window.confirm("¿Eliminar esta hipoteca? Esta acción no se puede deshacer.")) return;
        const data = await deleteHipoteca(recordId);
        if (data?.error) {
          alert(data.error);
          return;
        }
        if (String(document.getElementById("hipotecaBdtFichaPanel")?.dataset.recordId || "") === String(recordId)) {
          closeHipotecaFichaPanel();
        }
        loadFinCrm();
        loadHipotecaBdt(true);
        loadHipotecaDashboard();
        loadHomeHipotecaStats().then(() => renderCompanyCards());
      });
      actions.appendChild(deleteBtn);
      td.appendChild(actions);
      tr.appendChild(td);
    }
    if (showCaptacionActions && String(recordId || "").trim()) {
      const td = document.createElement("td");
      const actions = document.createElement("div");
      actions.className = "inline-actions";
      const inmuebleLinkId = String(rowMap?.inmueble_id || "").trim();
      const openLink = document.createElement("a");
      openLink.className = "ghost";
      openLink.textContent = "Ficha";
      openLink.href = inmuebleLinkId
        ? `/?crm=inmo&inmueble=${encodeURIComponent(inmuebleLinkId)}`
        : `/?crm=inmo&captacion=${encodeURIComponent(String(recordId || "").trim())}`;
      // Delegamos la navegación al interceptor de links, pero además prevenimos el reload en click normal.
      openLink.dataset.open = inmuebleLinkId ? "inmueble" : "captacion";
      openLink.addEventListener("click", (event) => {
        if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
        event.preventDefault();
        event.stopPropagation();
        ensureCrmOpen(() => {
          if (inmuebleLinkId) {
            openInmuebleDetail(inmuebleLinkId, "captaciones");
            return;
          }
          openInmuebleFromCaptacion(String(recordId || "").trim(), "captaciones");
        });
      });
      actions.appendChild(openLink);
      const etapaMain = normalizeCrmMainEtapa(rowMap?.etapa || "");
      const citaConfig = (() => {
        if (etapaMain === "Inmueble" || etapaMain === "Noticia") {
          return {
            label: "Programar adquisición",
            tipo: "Cita de adquisición",
            asunto: "Cita de adquisición",
            statusText:
              "Programa la cita (Programada). Al marcarla como Realizada podrás transformar a Noticia (o a Encargo si ya era Noticia).",
          };
        }
        if (etapaMain === "Encargo") {
          return {
            label: "Programar visita",
            tipo: "Cita de venta/alquiler",
            asunto: "Cita de venta",
            statusText: "Programa la visita. Al cerrarla podrás preparar propuesta si hay interés.",
          };
        }
        if (etapaMain === "Propuesta") {
          return {
            label: "Programar propuesta",
            tipo: "Cita de propuesta de compra/alquiler",
            asunto: "Cita de propuesta",
            statusText: "Cierra la propuesta como Rechazada / En negociación / Aprobada (si es Aprobada pasará a Vendido).",
          };
        }
        if (etapaMain === "Vendido") {
          return {
            label: "Programar notaría",
            tipo: "Cita notaria",
            asunto: "Cita notaría",
            statusText: "Registra hitos post-aceptación (contrato privado, notaría, etc.).",
          };
        }
        return null;
      })();
      if (citaConfig) {
        const btn = document.createElement("button");
        btn.type = "button";
        btn.className = "secondary";
        btn.textContent = citaConfig.label;
        btn.addEventListener("click", (event) => {
          event.preventDefault();
          event.stopPropagation();
          queueInmuebleCitaPrefill({
            tipo: citaConfig.tipo,
            asunto: citaConfig.asunto,
            statusText: citaConfig.statusText,
          });
          ensureCrmOpen(() => {
            if (inmuebleLinkId) {
              openInmuebleDetail(inmuebleLinkId, "captaciones");
              return;
            }
            openInmuebleFromCaptacion(String(recordId || "").trim(), "captaciones");
          });
        });
        actions.appendChild(btn);
      }
      td.appendChild(actions);
      tr.appendChild(td);
    }
    if (showCaptacionActions && String(recordId || "").trim()) {
      tr.addEventListener("click", async (event) => {
        if (closestFromEvent(event, "button, input, select, a")) {
          return;
        }
        const inmuebleId = String(rowMap?.inmueble_id || "").trim();
        ensureCrmOpen(() => {
          if (inmuebleId) {
            openInmuebleDetail(inmuebleId, "captaciones");
            return;
          }
          openInmuebleFromCaptacion(String(recordId || "").trim(), "captaciones");
        });
      });
    }
    if (label === "Seguros" && currentTab === "seguros-crm" && state.segurosTab === "bdt" && String(recordId || "").trim()) {
      tr.addEventListener("click", (event) => {
        if (closestFromEvent(event, "button, input, select, a")) {
          return;
        }
        openSeguroById(recordId, rowMap.cliente_id || "");
      });
    }
    if (enableColumnFilters) {
      const values = {};
      displayColumns.forEach((colName) => {
        const idx = colIndexMap.get(colName);
        const raw = idx === undefined ? "" : row[idx];
        values[colName] = normalizeSimple(formatCell(colName, raw) ?? raw ?? "");
      });
      filterRows.push({ tr, values });
    }
    tbody.appendChild(tr);
  });
  table.appendChild(tbody);
  container.innerHTML = "";
  container.appendChild(table);
  UI?.enhanceFragment(container);
  const applyColumnFilters = () => {
    if (!enableColumnFilters) return;
    const active = columnFilterInputs
      .map((input) => ({
        col: input.dataset.col || "",
        value: normalizeSimple(input.value || ""),
      }))
      .filter((item) => item.value);
    let visibleCount = 0;
    filterRows.forEach((entry) => {
      const visible = active.every((flt) => String(entry.values[flt.col] || "").includes(flt.value));
      entry.tr.style.display = visible ? "" : "none";
      if (visible) visibleCount += 1;
    });
    if (infoEl) {
      infoEl.textContent = `Mostrando ${visibleCount} filas de ${label}.`;
    }
  };
  if (enableColumnFilters) {
    columnFilterInputs.forEach((input) => {
      input.addEventListener("input", applyColumnFilters);
    });
    applyColumnFilters();
    return;
  }
  if (infoEl) {
    infoEl.textContent = `Mostrando ${rowsView.length} filas de ${label}.`;
  }
};

const buildCaptacionConversionPayload = async (rowMap, destino) => {
  const payload = {
    captacion_id: rowMap.id,
    destino,
    empresa_nombre: resolveCrmInmoEmpresaNombre(),
  };
  const fallbackPrice = rowMap.precio_encargo || rowMap.precio_pedido_cliente || rowMap.precio_objetivo || "";
  if (destino === "encargo") {
    const conditions = await openInmuebleEncargoConditionsModal(
      { ...rowMap, precio_encargo: fallbackPrice },
      { statusText: "Estas condiciones se guardarán en la ficha del encargo." }
    );
    if (!conditions) return null;
    const updates = buildEncargoConditionUpdates(conditions);
    Object.assign(payload, updates.captacion, updates.inmueble);
  }
  if (destino === "compraventa") {
    const fecha = window.prompt(
      "Fecha de escritura (YYYY-MM-DD, opcional).",
      new Date().toISOString().slice(0, 10)
    );
    if (fecha === null) return null;
    if (String(fecha).trim()) {
      payload.fecha_escritura = String(fecha).trim();
    }
    const precio = window.prompt(
      "Precio de venta (opcional).",
      fallbackPrice
    );
    if (precio === null) return null;
    if (String(precio).trim()) {
      payload.precio_escritura = String(precio).trim();
    }
  }
  if (destino === "alquiler") {
    const fecha = window.prompt(
      "Fecha de alquiler (YYYY-MM-DD, opcional).",
      new Date().toISOString().slice(0, 10)
    );
    if (fecha === null) return null;
    if (String(fecha).trim()) {
      payload.fecha = String(fecha).trim();
    }
    const precio = window.prompt(
      "Renta mensual o importe del alquiler (opcional).",
      fallbackPrice
    );
    if (precio === null) return null;
    if (String(precio).trim()) {
      payload.precio = String(precio).trim();
    }
  }
  return payload;
};

const prepareInmuebleAcquisitionAppointment = () => {
  setInmuebleTab("actividad");
  if (!inmuebleActividadForm) return;
  const tipoSelect = inmuebleActividadForm.querySelector('select[name="tipo"]');
  const estadoSelect = inmuebleActividadForm.querySelector('select[name="estado"]');
  if (tipoSelect) tipoSelect.value = "Cita de adquisición";
  if (estadoSelect) estadoSelect.value = "Pendiente";
  syncInmuebleWorkflowForm();
  const siguienteSelect = inmuebleActividadForm.querySelector('select[name="estado_siguiente"]');
  if (siguienteSelect) siguienteSelect.value = "";
  if (inmuebleActividadStatus) {
    inmuebleActividadStatus.textContent =
      "Programa aquí la cita de adquisición. Al cerrarla como Realizada con resultado Positivo, el inmueble avanzará a Noticia (o a Encargo si ya estaba en Noticia).";
  }
};

const queueInmuebleCitaPrefill = (prefill = null) => {
  state.pendingInmuebleCitaPrefill = prefill;
};

const resetInmuebleActividadForm = () => {
  if (!inmuebleActividadForm) return;
  // Importante: el motor `CRMUI` guarda borradores por `form.id`.
  // Como esta ficha se reutiliza entre inmuebles, limpiamos el draft para evitar herencias.
  try {
    if (window.CRMUI?.clearDraft) {
      window.CRMUI.clearDraft("inmuebleActividadForm");
    }
  } catch (e) {}
  try {
    inmuebleActividadForm.reset();
  } catch (e) {}

  // `form.reset()` puede no limpiar selects dinámicos (p.ej. responsable)
  // ni evitar “herencias” si el DOM no tiene defaultSelected marcado.
  try {
    if (inmuebleActividadClienteInput) inmuebleActividadClienteInput.value = "";
    if (inmuebleActividadClienteId) inmuebleActividadClienteId.value = "";
  } catch (e) {}

  try {
    const tipoSelect = inmuebleActividadForm.querySelector('select[name="tipo"]');
    if (tipoSelect) {
      tipoSelect.value = "Llamada";
      if (tipoSelect.value !== "Llamada") {
        tipoSelect.value = tipoSelect.options?.[0]?.value || "";
      }
    }
    const estadoSelect = inmuebleActividadForm.querySelector('select[name="estado"]');
    if (estadoSelect) {
      estadoSelect.value = "Pendiente";
      if (estadoSelect.value !== "Pendiente") {
        estadoSelect.value = estadoSelect.options?.[0]?.value || "";
      }
    }
    const responsableSelect = inmuebleActividadForm.querySelector('select[name="responsable"]');
    if (responsableSelect) {
      responsableSelect.value = "";
      if (responsableSelect.value) {
        responsableSelect.value = "";
      }
    }
    const modalidadSelect = inmuebleActividadForm.querySelector('select[name="modalidad_contacto"]');
    if (modalidadSelect) modalidadSelect.value = "";
    const horaInput = inmuebleActividadForm.querySelector('input[name="hora"]');
    const horaFinInput = inmuebleActividadForm.querySelector('input[name="hora_fin"]');
    if (horaInput) horaInput.value = "";
    if (horaFinInput) horaFinInput.value = "";
  } catch (e) {}

  try {
    syncInmuebleWorkflowForm();
  } catch (e) {}

  if (inmuebleActividadStatus) inmuebleActividadStatus.textContent = "";
};

const applyPendingInmuebleCitaPrefill = () => {
  const prefill = state.pendingInmuebleCitaPrefill;
  if (!prefill) return;
  state.pendingInmuebleCitaPrefill = null;
  setInmuebleTab("actividad");
  if (!inmuebleActividadForm) return;
  // Importante: evita que una pre-carga “herede” datos de la ficha anterior.
  resetInmuebleActividadForm();
  const tomorrow = new Date(Date.now() + 24 * 60 * 60 * 1000);
  const fechaInput = inmuebleActividadForm.querySelector('input[name="fecha"]');
  const horaInput = inmuebleActividadForm.querySelector('input[name="hora"]');
  const asuntoInput = inmuebleActividadForm.querySelector('input[name="asunto"]');
  const tipoSelect = inmuebleActividadForm.querySelector('select[name="tipo"]');
  const estadoSelect = inmuebleActividadForm.querySelector('select[name="estado"]');
  if (tipoSelect && prefill.tipo) tipoSelect.value = prefill.tipo;
  if (estadoSelect) estadoSelect.value = "Pendiente";
  if (fechaInput && !String(fechaInput.value || "").trim()) fechaInput.value = tomorrow.toISOString().slice(0, 10);
  if (horaInput && !String(horaInput.value || "").trim()) horaInput.value = "10:00";
  if (asuntoInput && prefill.asunto && !String(asuntoInput.value || "").trim()) asuntoInput.value = prefill.asunto;
  syncInmuebleWorkflowForm();
  if (prefill.estado_siguiente) {
    const nextSelect = inmuebleActividadForm.querySelector('select[name="estado_siguiente"]');
    if (nextSelect) nextSelect.value = prefill.estado_siguiente;
  }
  if (inmuebleActividadStatus && prefill.statusText) {
    inmuebleActividadStatus.textContent = prefill.statusText;
  }
};

const INMO_WORKFLOW_RESULT_OPTIONS = {
  "Cita de adquisición": ["Positivo", "Negativo", "Reprogramar", "No realizada"],
  "Cita de venta/alquiler": ["Estudio", "No interesa", "Interesado"],
  "Cita de propuesta de compra/alquiler": ["Rechazada", "Aprobada", "En negociación"],
  "Cita acept. de la propuesta": ["Aceptada", "Rechazada", "Contraoferta"],
  "Post-aceptación": ["Firmada", "Reprogramar", "No realizada"],
  "Cita de gestión encargo (seguimiento)": ["Realizada", "Reprogramar", "No realizada"],
  "Cita general (no comercial)": ["Realizada", "Reprogramar", "No realizada"],
  "Estudio financiero": ["Viable", "No viable", "Pendiente documentación"],
  "Cita comprador": ["Estudio", "No interesa", "Interesado"],
  "Cita propuesta": ["Rechazada", "Aprobada", "En negociación"],
  "Cita aceptación propietarios": ["Aceptada", "Rechazada", "Contraoferta"],
  "Cita aceptación contraoferta": ["Aceptada", "Rechazada"],
  "Cita contrato privado": ["Firmado", "Reprogramar", "No realizada"],
  "Cita notaria": ["Firmada", "Reprogramar", "No realizada"],
};

const isInmoPropuestaActionType = (type) => normalizeInmoActionType(type || "") === "cita_propuesta";

const syncPropuestaMoneyFields = (form) => {
  if (!form) return;
  const type = String(form.querySelector('select[name="tipo"]')?.value || "").trim();
  const show = isInmoPropuestaActionType(type);
  form.querySelectorAll("[data-propuesta-field]").forEach((wrap) => {
    wrap.classList.toggle("hidden", !show);
    if (!show) {
      wrap.querySelectorAll("input, select, textarea").forEach((input) => {
        input.value = "";
      });
    }
  });
};

const getInmuebleActividadClienteScope = (type) => {
  const key = normalizeSimple(type || "");
  if (
    key.includes("comprador")
    || key.includes("propuesta")
    || key.includes("contraoferta")
    || key.includes("visita")
    || key.includes("notaria")
    || key.includes("contrato privado")
  ) {
    return "demandas";
  }
  return "propietarios";
};

const refreshInmuebleActividadClientesCandidates = (type) => {
  if (!inmuebleActividadClientes || !inmuebleActividadClienteInput || !inmuebleActividadClienteId) return;
  const scope = getInmuebleActividadClienteScope(type);
  const propietarios = Array.isArray(state.currentInmuebleContext?.propietarios) ? state.currentInmuebleContext.propietarios : [];
  const demandas = Array.isArray(state.currentInmuebleContext?.demandas) ? state.currentInmuebleContext.demandas : [];
  const candidates = scope === "demandas" ? demandas : propietarios;
  populateAgendaClientesFromCandidates(inmuebleActividadClientes, inmuebleActividadClienteInput, inmuebleActividadClienteId, candidates);
  populateAgendaClienteQuickSelect(
    inmuebleActividadClienteQuick,
    inmuebleActividadClienteInput,
    inmuebleActividadClienteId,
    candidates,
    scope === "demandas" ? "Comprador (opcional)" : "Propietario (opcional)"
  );
  const cleaned = (Array.isArray(candidates) ? candidates : [])
    .map((row) => {
      const id = String(row.cliente_id || row.id || "").trim();
      const nombreRaw = row.nombre || row.cliente || row.cliente_nombre || row.propietario || "";
      const nombre = formatNombreCliente(nombreRaw);
      const key = normalizeSimple(nombre);
      return { id, nombre, key };
    })
    .filter((item) => item.key);
  const idSet = new Set(cleaned.map((item) => item.id).filter(Boolean));
  const nameToId = new Map(cleaned.filter((item) => item.id).map((item) => [item.key, item.id]));
  const setSelection = (id, nombre) => {
    inmuebleActividadClienteId.value = id || "";
    inmuebleActividadClienteInput.value = nombre || "";
    if (inmuebleActividadClienteQuick && inmuebleActividadClienteQuick._agendaQuickMap?.has(id)) {
      inmuebleActividadClienteQuick.value = id;
    }
  };
  const clearSelection = () => {
    inmuebleActividadClienteId.value = "";
    inmuebleActividadClienteInput.value = "";
    if (inmuebleActividadClienteQuick) inmuebleActividadClienteQuick.value = "";
  };
  // Evita “arrastre” de cliente anterior (otro inmueble) y fuerza coherencia con el scope actual.
  const currentId = String(inmuebleActividadClienteId.value || "").trim();
  const currentNameKey = normalizeSimple(inmuebleActividadClienteInput.value || "");
  if (currentId && !idSet.has(currentId)) {
    clearSelection();
  } else if (!currentId && currentNameKey && nameToId.has(currentNameKey)) {
    const id = nameToId.get(currentNameKey) || "";
    const hit = cleaned.find((item) => item.id === id) || null;
    if (id && hit) setSelection(id, hit.nombre);
  } else if (scope === "propietarios" && currentNameKey && !nameToId.has(currentNameKey)) {
    // Para citas de cambio de estado (propietarios), no dejamos un nombre “suelto” que venga del último cliente trabajado.
    clearSelection();
  }
  // Defaults: si estamos en propietarios, siempre proponemos el primer propietario.
  if (!String(inmuebleActividadClienteId.value || "").trim()) {
    if (cleaned.length === 1) {
      const only = cleaned[0] || {};
      if (only.id && only.nombre) setSelection(only.id, only.nombre);
    } else if (scope === "propietarios" && cleaned.length) {
      const first = cleaned.find((item) => item.id) || cleaned[0];
      if (first?.id && first?.nombre) setSelection(first.id, first.nombre);
    }
  }
};

const syncInmuebleWorkflowForm = () => {
  if (!inmuebleActividadForm) return;
  const tipoSelect = inmuebleActividadForm.querySelector('select[name="tipo"]');
  const resultSelect = inmuebleActividadForm.querySelector('select[name="resultado_cierre"]');
  const nextSelect = inmuebleActividadForm.querySelector('select[name="estado_siguiente"]');
  const type = String(tipoSelect?.value || "").trim();
  if (resultSelect) {
    const current = resultSelect.value;
    const options = INMO_WORKFLOW_RESULT_OPTIONS[type] || [];
    resultSelect.innerHTML = "";
    resultSelect.appendChild(createOption("", options.length ? "Selecciona resultado" : "Sin resultado para esta cita"));
    options.forEach((opt) => resultSelect.appendChild(createOption(opt, opt)));
    resultSelect.value = options.includes(current) ? current : "";
  }
  if (nextSelect) {
    const current = nextSelect.value;
    let nextOptions = [];
    if (type === "Cita de adquisición") {
      const resultFinal = String(resultSelect?.value || "").trim();
      if (resultFinal === "Positivo") {
        const etapaActual = normalizeCrmMainEtapa(state.currentInmuebleContext?.inmueble?.estado || "");
        // Inmueble -> Noticia, Noticia -> Encargo
        nextOptions = etapaActual === "Noticia" ? ["Encargo"] : ["Noticia"];
      } else if (resultFinal === "Negativo") {
        nextOptions = ["Cerrado negativamente"];
      }
    }
    nextSelect.innerHTML = "";
    nextSelect.appendChild(createOption("", nextOptions.length ? "Sin cambio automático" : "No aplica"));
    nextOptions.forEach((opt) => nextSelect.appendChild(createOption(opt, opt)));
    if (nextOptions.includes(current)) {
      nextSelect.value = current;
    } else if (!current && nextOptions.length === 1) {
      nextSelect.value = nextOptions[0];
    } else {
      nextSelect.value = "";
    }
  }
  refreshInmuebleActividadClientesCandidates(type);
  syncPropuestaMoneyFields(inmuebleActividadForm);
};

const runCaptacionConversion = async (captacionId, rowMap = {}, destino = "") => {
  if (!captacionId || !destino) return;
  if (destino === "adquisicion" || destino === "valoracion") {
    // Legacy: antes existía el paso "Adquisición". Ahora equivale a "Inmueble".
    destino = "inmueble";
  }
  const destinationLabel = {
    inmueble: "Inmueble",
    noticia: "Noticia",
    encargo: "Encargo",
    propuesta: "Propuesta",
    reservado: "Reservado",
    arras: "Contrato de arras",
    compraventa: "Vendido",
    vendido: "Vendido",
    cerrado_negativamente: "Cerrado negativamente",
    alquiler: "Alquiler",
  }[destino] || destino;
  const ok = window.confirm(
    `¿Convertir la captación "${rowMap.direccion || rowMap.propietario || captacionId}" a ${destinationLabel}?`
  );
  if (!ok) return;
  const payload = await buildCaptacionConversionPayload({ ...rowMap, id: captacionId }, destino);
  if (!payload) return;
  if (crmCaptacionesInfo) {
    crmCaptacionesInfo.textContent = `Convirtiendo a ${destinationLabel}...`;
  }
  try {
    const response = await fetch("/api/captacion_convert", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      credentials: "same-origin",
      body: JSON.stringify(payload),
    });
    const data = await response.json();
    if (!response.ok || data?.error) {
      if (crmCaptacionesInfo) {
        crmCaptacionesInfo.textContent = data?.error || `HTTP ${response.status}`;
      }
      alert(data?.error || `HTTP ${response.status}`);
      return;
    }
    if (crmCaptacionesInfo) {
      crmCaptacionesInfo.textContent = `Convertida a ${destinationLabel}.`;
    }
    loadCrmCaptaciones();
    loadCrmInmuebles();
    if (destino === "compraventa" || destino === "vendido") {
      loadCrmCompraventas();
      setCrmWorkspaceView("compraventas");
      return;
    }
    if (destino === "alquiler") {
      loadCrmAlquileres();
      setCrmWorkspaceView("alquileres");
      return;
    }
    if (destino === "inmueble" || destino === "encargo") {
      setCrmWorkspaceView("inmuebles");
    }
  } catch (error) {
    const message = error?.message || "Error al convertir el inmueble.";
    if (crmCaptacionesInfo) {
      crmCaptacionesInfo.textContent = message;
    }
    alert(message);
  }
};

const runCurrentInmuebleConversion = async (destino) => {
  if (destino === "adquisicion" || destino === "valoracion") {
    // Legacy: antes existía el paso "Adquisición". Ahora equivale a "Inmueble".
    destino = "inmueble";
  }
  const captacion = state.currentInmuebleContext?.captacion || {};
  const inmueble = state.currentInmuebleContext?.inmueble || state.currentInmueble || {};
  const captacionId = String(captacion.id || "").trim();
  const inmuebleId = String(inmueble.id || state.currentInmuebleId || "").trim();
  if (!captacionId && !inmuebleId) {
    alert("La ficha no tiene un inmueble válido para convertir.");
    return;
  }
  const rowPayload = { ...captacion, ...inmueble, id: captacionId || inmuebleId, inmueble_id: inmuebleId };
  const payload = await buildCaptacionConversionPayload(rowPayload, destino);
  if (!payload) return;
  if (captacionId) {
    payload.captacion_id = captacionId;
  } else {
    payload.inmueble_id = inmuebleId;
  }
  const destinationLabel = {
    inmueble: "Inmueble",
    noticia: "Noticia",
    encargo: "Encargo",
    propuesta: "Propuesta",
    reservado: "Reservado",
    arras: "Contrato de arras",
    compraventa: "Vendido",
    vendido: "Vendido",
    cerrado_negativamente: "Cerrado negativamente",
    alquiler: "Alquiler",
  }[destino] || destino;
  const ok = window.confirm(
    `¿Convertir el inmueble "${inmueble.direccion || inmueble.referencia || inmuebleId}" a ${destinationLabel}?`
  );
  if (!ok) return;
  if (crmCaptacionesInfo) {
    crmCaptacionesInfo.textContent = `Convirtiendo a ${destinationLabel}...`;
  }
  fetch("/api/captacion_convert", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    credentials: "same-origin",
    body: JSON.stringify(payload),
  })
    .then((res) => res.json().then((data) => ({ ok: res.ok, status: res.status, data })))
    .then(({ ok, data, status }) => {
      if (!ok || data?.error) {
        const message = data?.error || `HTTP ${status}`;
        if (crmCaptacionesInfo) crmCaptacionesInfo.textContent = message;
        alert(message);
        return;
      }
      if (crmCaptacionesInfo) {
        crmCaptacionesInfo.textContent = `Convertido a ${destinationLabel}.`;
      }
      loadCrmCaptaciones();
      loadCrmInmuebles();
      if (state.currentInmuebleId) {
        openInmuebleDetail(state.currentInmuebleId, state.currentInmuebleOriginView || "inmuebles");
      }
      if (destino === "compraventa") {
        loadCrmCompraventas();
      } else if (destino === "alquiler") {
        loadCrmAlquileres();
      }
    })
    .catch((error) => {
      const message = error?.message || "Error al convertir el inmueble.";
      if (crmCaptacionesInfo) crmCaptacionesInfo.textContent = message;
      alert(message);
    });
};

let cachedCrmClientesScopeKey = "";
let crmClientesReloadTimer = null;

const buildCrmClientesDenseTableNode = (rows = []) => {
  const items = Array.isArray(rows) ? rows : [];
  if (!items.length) return null;
  const table = document.createElement("table");
  table.className = "crm-dense-table crm-clientes-table";
	  const thead = document.createElement("thead");
	  thead.innerHTML = `
	    <tr>
	      <th style="width:34px;"></th>
	      <th>Cliente</th>
	      <th>Teléfono</th>
	      <th>Móvil</th>
	      <th>Otro teléfono</th>
	      <th>Dirección</th>
	      <th>Número</th>
	      <th>Localidad</th>
	    </tr>
	  `;
  table.appendChild(thead);
  const tbody = document.createElement("tbody");
  const splitDireccionNumero = (raw) => {
    const text = String(raw || "").trim();
    if (!text) return { direccion: "", numero: "" };
    const match = text.match(/^(.*?)(?:,?\s+)(\d+[A-Za-z]?|S\/N)$/i);
    if (!match) return { direccion: text, numero: "" };
    return { direccion: String(match[1] || "").trim(), numero: String(match[2] || "").trim() };
  };
  items.forEach((row) => {
    const tr = document.createElement("tr");
    const id = String(row.id || "").trim();
    const open = () => {
      if (!id) return;
      pushCrmRecentItem({
        kind: "cliente",
        id,
        title: String(row.nombre || "").trim() || "Cliente",
        meta: [row.telefono || row.movil || "", row.email || ""].filter(Boolean).join(" · "),
        view: "clientes",
        ts: Date.now(),
      });
      openClienteDetail(id);
    };
    if (id) {
      tr.addEventListener("click", open);
    }
    const selectTd = document.createElement("td");
    selectTd.className = "crm-dense-select";
    const checkbox = document.createElement("input");
    checkbox.type = "checkbox";
    checkbox.dataset.clienteId = id;
    checkbox.addEventListener("click", (event) => event.stopPropagation());
	    selectTd.appendChild(checkbox);
	    tr.appendChild(selectTd);

	    const nameCell = document.createElement("td");
	    const nombre = String(row.nombre || "Sin nombre").trim();
	    nameCell.innerHTML = `<a class="tc-link" href="#" data-open-cliente="1">${escapeHtml(nombre)}</a>`;
	    const anchor = nameCell.querySelector('a[data-open-cliente]');
	    if (anchor) {
	      anchor.addEventListener("click", (event) => {
	        event.preventDefault();
	        event.stopPropagation();
	        open();
	      });
	    }
	    tr.appendChild(nameCell);

    const telCell = document.createElement("td");
    telCell.textContent = String(row.telefono || "").trim();
    tr.appendChild(telCell);

    const movilCell = document.createElement("td");
    movilCell.textContent = String(row.movil || "").trim();
    tr.appendChild(movilCell);

    const otherCell = document.createElement("td");
    otherCell.textContent = String(row.otro_telefono || row.otro_tel || "").trim();
    tr.appendChild(otherCell);

    const dirCell = document.createElement("td");
    const { direccion, numero } = splitDireccionNumero(row.direccion);
    dirCell.textContent = direccion;
    tr.appendChild(dirCell);

    const numCell = document.createElement("td");
    numCell.textContent = numero;
    tr.appendChild(numCell);

    const locCell = document.createElement("td");
    locCell.textContent = [row.poblacion || row.localidad || "", row.provincia || ""].filter(Boolean).join(" · ");
    tr.appendChild(locCell);

    tbody.appendChild(tr);
	  });
	  table.appendChild(tbody);
	  enableCrmDenseTableResize(table);
	  return table;
	};

const scheduleCrmClientesReload = ({ force = false } = {}) => {
  if (crmClientesReloadTimer) {
    window.clearTimeout(crmClientesReloadTimer);
    crmClientesReloadTimer = null;
  }
  crmClientesReloadTimer = window.setTimeout(() => {
    crmClientesReloadTimer = null;
    loadCrmClientes({ force });
  }, 180);
};

const loadCrmClientes = async ({ force = false } = {}) => {
  if (!crmClientesTable) return;
  const scope = resolveInmoScopeParams();
  if (!scope || (!scope.workspace_id && !scope.empresa_id)) {
    crmClientesTable.innerHTML = "<p class='muted'>Sin empresa.</p>";
    if (crmClientesInfo) crmClientesInfo.textContent = "";
    return;
  }
  const scopeKey = scope.workspace_id ? `ws:${scope.workspace_id}` : `empresa:${scope.empresa_id}`;
  const shouldFetch = force || !cachedCrmClientes.length || cachedCrmClientesScopeKey !== scopeKey;
  if (shouldFetch) {
    const params = new URLSearchParams({
      include_id: "1",
      limit: "500",
      ...scope,
      servicio: "inmobiliaria",
    });
    const data = await api(`/api/clientes?${params.toString()}`).catch(() => null);
    if (!data || !Array.isArray(data.columns) || !Array.isArray(data.rows)) {
      crmClientesTable.innerHTML = "<p class='muted'>No se pudieron cargar los clientes.</p>";
      if (crmClientesInfo) crmClientesInfo.textContent = "";
      return;
    }
    cachedCrmClientes = data.rows.map((row) => buildRowMap(row, data.columns));
    cachedCrmClientesScopeKey = scopeKey;
  }

  const filterKey = String(crmClientesFilter?.value || "recientes").trim().toLowerCase();
  const qRaw = String(crmClientesSearch?.value || "").trim();
  const all = Array.isArray(cachedCrmClientes) ? cachedCrmClientes : [];
  // En Inmobiliaria queremos, por defecto, la cartera del servicio. En tenant el backend
  // puede devolver más clientes por compat legacy (sin vínculos en `clientes_empresas`).
  // Filtramos aquí para que el listado sea “Inmobiliaria” (y no el total del workspace).
  const allInmo = all.filter((row) => {
    const servicios = normalizeSimple(row?.servicios || "");
    if (!servicios) return false;
    return servicios.includes("inmobiliaria") || servicios.includes("inmo");
  });

  const matchQuery = createAdvancedSearchMatcher(qRaw, {
    text: (row) =>
      [
        row?.id,
        row?.nombre,
        row?.nif,
        row?.telefono,
        row?.movil,
        row?.email,
        row?.direccion,
        row?.codigo_postal,
        row?.poblacion,
        row?.provincia,
        row?.perfil,
        row?.tipo_persona,
      ]
        .map((v) => String(v || ""))
        .join(" "),
    fields: {
      id: (row) => row?.id,
      nombre: (row) => row?.nombre,
      nif: (row) => row?.nif,
      tel: (row) => row?.telefono || row?.movil,
      movil: (row) => row?.movil,
      email: (row) => row?.email,
      direccion: (row) => row?.direccion,
      codigo_postal: (row) => row?.codigo_postal,
      poblacion: (row) => row?.poblacion,
      provincia: (row) => row?.provincia,
      perfil: (row) => row?.perfil,
      tipo: (row) => row?.tipo_persona,
    },
  });
  const byQuery = (row) => matchQuery(row);

  const applyPresetFilter = (rows) => {
    if (filterKey === "todos") return rows;
    if (filterKey === "contactar") {
      // Tecnocloud: lista priorizada por tiempo sin contacto. Si aún no tenemos esa trazabilidad,
      // aproximamos el concepto con clientes que tienen pedido o vienen de web genérico.
      const pick = rows.filter((row) => {
        const tienePedido = String(row.tiene_pedido || "").trim() === "1";
        const esWeb = String(row.cliente_generico_web || "").trim() === "1";
        return tienePedido || esWeb;
      });
      return pick.length ? pick.slice(0, 120) : rows.slice(0, 120);
    }
    if (filterKey === "informadores") {
      return rows.filter((row) => normalizeSimple(row.perfil || "").includes("informador"));
    }
    if (filterKey === "web") {
      return rows.filter((row) => String(row.cliente_generico_web || "").trim() === "1");
    }
    if (filterKey === "web_ult5") {
      // Tecnocloud: "últimos 5 días sin actividad". Si no tenemos trazabilidad de actividad aquí,
      // aplicamos el filtro base de cliente web genérico (y se refina cuando exista el dato).
      return rows.filter((row) => String(row.cliente_generico_web || "").trim() === "1");
    }
    if (filterKey === "recientes") {
      const recent = loadCrmRecentItems().filter((item) => String(item?.kind || "") === "cliente" && item?.id);
      const ordered = recent
        .map((item) => rows.find((row) => String(row.id || "").trim() === String(item.id)))
        .filter(Boolean);
      if (ordered.length) return ordered;
      return rows.slice(0, 50);
    }
    return rows;
  };

  const az = String(state.crmAz?.clientes || "").trim().toUpperCase();
  const filtered = applyPresetFilter(allInmo)
    .filter(byQuery)
    .filter((row) => matchTcAz(az, row.nombre || row.email || row.telefono || ""));

  crmClientesTable.innerHTML = "";
  const node = buildCrmClientesDenseTableNode(filtered);
  if (!node) {
    crmClientesTable.innerHTML = "<p class='muted'>Sin clientes.</p>";
  } else {
    crmClientesTable.appendChild(node);
  }
	  if (crmClientesInfo) {
	    crmClientesInfo.textContent = `Mostrando ${filtered.length} clientes.`;
	  }
	  try {
	    if (crmViewResumen && !crmViewResumen.classList.contains("hidden")) {
	      renderCrmResumenDashboard();
	    }
	  } catch (e) {}
	};

const resolveCaptacionCodePrefix = (etapa) => {
  const stage = normalizeCrmMainEtapa(etapa || "") || "Inmueble";
  if (stage === "Inmueble") return "IN";
  if (stage === "Noticia") return "NT";
  return "EN";
};

const resolveCaptacionDotTone = (row = {}) => {
  const stage = normalizeCrmMainEtapa(row.etapa || "") || "Inmueble";
  if (stage === "Encargo" || stage === "Propuesta" || stage === "Vendido") return "ok";
  if (stage === "Noticia") return "info";
  if (String(row.proxima_accion || "").trim()) return "neutral";
  return "warn";
};

const buildCrmCaptacionesDenseTableNode = (rows = []) => {
  const items = Array.isArray(rows) ? rows : [];
  if (!items.length) return null;
	  const table = document.createElement("table");
	  table.className = "crm-dense-table crm-captaciones-table";
	  const thead = document.createElement("thead");
	  thead.innerHTML = `
	    <tr>
	      <th>Inmueble</th>
		      <th>Propietario</th>
		      <th>Tel.</th>
		      <th>Subtipología</th>
		      <th>Necesidad</th>
		      <th>Precio</th>
		      <th>Próxima acción</th>
		      <th>Etapa</th>
	    </tr>
	  `;
  table.appendChild(thead);
  const tbody = document.createElement("tbody");
	  items.forEach((row) => {
	    const tr = document.createElement("tr");
	    const captacionId = String(row.id || "").trim();
	    const inmuebleId = String(row.inmueble_id || "").trim();
	    tr.addEventListener("click", () => {
	      ensureCrmOpen(() => {
        if (inmuebleId) {
          openInmuebleDetail(inmuebleId, "captaciones");
          return;
        }
        if (captacionId) {
          openInmuebleFromCaptacion(captacionId, "captaciones");
	        }
	      });
	    });

    const stage = normalizeCrmMainEtapa(row.etapa || "") || "Inmueble";
    const prefix = resolveCaptacionCodePrefix(stage);
    const isVerified = String(row?.noticia_verificada ?? "").trim() === "1";
    const address = String(row.direccion || "").trim() || "-";
    const localidad = [row.poblacion || "", row.provincia || ""].filter(Boolean).join(" · ");
    const inmuebleTd = document.createElement("td");
    inmuebleTd.className = "crm-dense-main";
    inmuebleTd.innerHTML = `
      <strong>${escapeHtml(`${prefix} - ${address}`)}</strong>
      <div class="muted">${escapeHtml(localidad || "-")}</div>
      ${buildVerifika2Badge(isVerified, { compact: true })}
    `;
    tr.appendChild(inmuebleTd);

    const propietarioTd = document.createElement("td");
    propietarioTd.textContent = String(row.propietario || "").trim();
    tr.appendChild(propietarioTd);

    const telTd = document.createElement("td");
    telTd.textContent = String(row.propietario_telefono || "").trim();
    tr.appendChild(telTd);

	    const subTd = document.createElement("td");
	    subTd.textContent = String(row.subtipologia || "").trim();
	    tr.appendChild(subTd);

	    const necTd = document.createElement("td");
	    necTd.textContent = String(row.necesidad_venta_alquiler || "").trim();
	    tr.appendChild(necTd);

    const precioTd = document.createElement("td");
    const early = stage === "Inmueble" || stage === "Noticia";
    const precio = early ? row.precio_pedido_cliente || row.precio_objetivo : row.precio_encargo || row.precio_objetivo;
    const formatted = formatCell("precio_objetivo", precio);
    precioTd.textContent = formatted === null ? "" : formatted;
    tr.appendChild(precioTd);

    const proximaTd = document.createElement("td");
    proximaTd.textContent = String(row.proxima_accion || "").trim();
    tr.appendChild(proximaTd);

    const etapaTd = document.createElement("td");
    etapaTd.textContent = stage;
    tr.appendChild(etapaTd);

    tbody.appendChild(tr);
  });
  table.appendChild(tbody);
  enableCrmDenseTableResize(table, "crm.dense.widths.crm-captaciones-table.v2");
  return table;
};

const loadCrmCaptaciones = () => {
  if (!crmCaptacionesTable) {
    return;
  }
  const scope = resolveInmoScopeParams();
  if (!scope) {
    crmCaptacionesTable.innerHTML = "<p class='muted'>Sin empresa.</p>";
    return;
  }
  const params = new URLSearchParams({
    tabla: "captaciones",
    ...scope,
  });
  params.set("include_id", "1");
  const q = String(state.crmGlobalSearch || "").trim();
  if (state.crmWorkspaceView === "captaciones" && q) {
    params.set("q", q);
  }
  api(`/api/tabla?${params.toString()}`)
    .then((data) => {
    const rowMaps = Array.isArray(data.rows)
      ? data.rows.map((row) => buildRowMap(row, data.columns))
      : [];
    rowMaps.forEach((row) => {
      if (!row) return;
      // Normaliza etapas legacy (Reservado/Arras/etc.) al pipeline de 5 fases.
      row.etapa = normalizeCrmMainEtapa(row.etapa || "") || "Inmueble";
    });
    cachedCrmCaptaciones = rowMaps;
    const etapaIndex = data.columns.indexOf("etapa");
    const idIndex = data.columns.indexOf("id");
    // Compat: normaliza etapas legacy al pipeline de 5 fases.
    if (Array.isArray(data.rows) && etapaIndex >= 0) {
      data.rows.forEach((row) => {
        if (!Array.isArray(row)) return;
        row[etapaIndex] = normalizeCrmMainEtapa(row[etapaIndex] || "") || "Inmueble";
      });
	    }
	    const activeEtapa = crmEtapaFilter?.value || crmEtapaFilterMirror?.value || "";
	    if (crmEtapaFilter) crmEtapaFilter.value = activeEtapa;
	    if (crmEtapaFilterMirror) crmEtapaFilterMirror.value = activeEtapa;
	    if (crmCaptacionesTitle) {
	      const etapaLabel = String(activeEtapa || "").trim();
	      crmCaptacionesTitle.textContent = etapaLabel === "Noticia"
	        ? "Noticias"
	        : etapaLabel === "Encargo"
	          ? "Encargos"
	          : "Nuevas oportunidades";
	    }
		    const quickKey = String(crmCaptacionesQuickFilter?.value || "").trim();
		    const localQRaw = String(crmCaptacionesSearch?.value || "").trim();
		    const matchLocalQuery = createAdvancedSearchMatcher(localQRaw, {
			      text: (rowMap) =>
			        [
			          rowMap?.id,
			          rowMap?.direccion,
			          rowMap?.propietario,
			          rowMap?.propietario_telefono,
			          rowMap?.poblacion,
			          rowMap?.provincia,
			          rowMap?.subtipologia,
			          rowMap?.necesidad_venta_alquiler,
			          rowMap?.proxima_accion,
			          rowMap?.etapa,
			          rowMap?.situacion_ocupacion,
		          rowMap?.ocupado_por,
		        ]
		          .map((value) => String(value || ""))
		          .join(" "),
		      fields: {
		        id: (rowMap) => rowMap?.id,
		        direccion: (rowMap) => rowMap?.direccion,
		        tel: (rowMap) => rowMap?.propietario_telefono,
		        poblacion: (rowMap) => rowMap?.poblacion,
			        provincia: (rowMap) => rowMap?.provincia,
			        etapa: { get: (rowMap) => rowMap?.etapa, match: "equals" },
			        necesidad: (rowMap) => rowMap?.necesidad_venta_alquiler,
			        ocupacion: (rowMap) => rowMap?.situacion_ocupacion,
			      },
			    });
	    const parseDateMs = (value) => {
	      const dateText = String(value || "").trim();
	      if (!dateText) return 0;
      let year = 0;
      let month = 0;
      let day = 0;
      let match = dateText.match(/^(\d{4})-(\d{2})-(\d{2})$/);
      if (match) {
        year = Number(match[1]);
        month = Number(match[2]) - 1;
        day = Number(match[3]);
      } else {
        match = dateText.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
        if (!match) return 0;
        day = Number(match[1]);
        month = Number(match[2]) - 1;
        year = Number(match[3]);
      }
      return new Date(year, month, day, 0, 0, 0).getTime();
    };
    const daysSince = (value) => {
      const ts = parseDateMs(value);
      if (!ts) return Number.POSITIVE_INFINITY;
      return Math.floor((Date.now() - ts) / 86400000);
    };
    const matchQuick = (rowMap) => {
      if (!quickKey) return true;
      const etapa = String(rowMap?.etapa || "Inmueble").trim();
      const ocupacion = normalizeSimple(rowMap?.situacion_ocupacion || "");
      const ocupadoPor = normalizeSimple(rowMap?.ocupado_por || "");
      const proxima = String(rowMap?.proxima_accion || "").trim();
      const dias = daysSince(rowMap?.fecha_contacto);
      const verificada = String(rowMap?.noticia_verificada ?? "").trim();
      if (quickKey === "quick_pisos_vacios") {
        return ocupacion === "libre" || ocupadoPor === "vacio" || ocupadoPor === "vacío";
      }
      if (quickKey === "quick_alquilados") {
        return ocupacion.includes("alquil") || ocupadoPor.includes("inquilin");
      }
      if (quickKey === "quick_sin_contacto_120") {
        return dias === Number.POSITIVE_INFINITY || dias > 120;
      }
      if (quickKey === "quick_noticia_sin_verificar") {
        return etapa === "Noticia" && verificada !== "1";
      }
      if (quickKey === "quick_sin_proxima_accion") {
        return !proxima;
      }
      return true;
    };
	    const baseRowMaps = rowMaps.filter((rowMap) => matchQuick(rowMap));
	    let filteredRowMaps = baseRowMaps.filter((rowMap) => {
	      if (!activeEtapa) return true;
	      return String(rowMap?.etapa || "") === String(activeEtapa || "");
	    });
		    filteredRowMaps = filteredRowMaps.filter((rowMap) => matchLocalQuery(rowMap));
	    const counts = {};
	    baseRowMaps.forEach((row) => {
	      const etapa = row?.etapa || "Sin etapa";
      counts[etapa] = (counts[etapa] || 0) + 1;
    });
    renderCrmPipeline(counts, activeEtapa);
    if (crmCaptacionesOps) {
      const activeRowMaps = baseRowMaps;
      const safeDaysSince = (value) => {
        const days = daysSince(value);
        return Number.isFinite(days) ? days : Number.POSITIVE_INFINITY;
      };
      const isPisosVacios = (rowMap) => {
        const ocupacion = normalizeSimple(rowMap?.situacion_ocupacion || "");
        const ocupadoPor = normalizeSimple(rowMap?.ocupado_por || "");
        return ocupacion === "libre" || ocupadoPor === "vacio" || ocupadoPor === "vacío";
      };
      const isAlquilado = (rowMap) => {
        const ocupacion = normalizeSimple(rowMap?.situacion_ocupacion || "");
        const ocupadoPor = normalizeSimple(rowMap?.ocupado_por || "");
        return ocupacion.includes("alquil") || ocupadoPor.includes("inquilin");
      };
      const missingNext = activeRowMaps.filter((row) => !String(row.proxima_accion || "").trim()).length;
      const noticiasSinVerificar = activeRowMaps.filter((row) => String(row.etapa || "").trim() === "Noticia" && String(row.noticia_verificada ?? "").trim() !== "1").length;
      const sinContacto120 = activeRowMaps.filter((row) => safeDaysSince(row.fecha_contacto) > 120).length;
      const pisosVacios = activeRowMaps.filter(isPisosVacios).length;
      const alquilados = activeRowMaps.filter(isAlquilado).length;
      const ops = [
        {
          title: "Sin próxima acción",
          meta: `${missingNext} expedientes`,
          summary: "Revisar y programar siguiente paso.",
          crmQuick: "captaciones:quick_sin_proxima_accion",
        },
        {
          title: "Noticias sin verificar",
          meta: `${noticiasSinVerificar} noticias`,
          summary: "Valorar/verificar para avanzar el pipeline.",
          crmQuick: "captaciones:quick_noticia_sin_verificar",
        },
        {
          title: "Sin contacto >120 días",
          meta: `${sinContacto120} expedientes`,
          summary: "Reactivar o cerrar para limpiar cartera.",
          crmQuick: "captaciones:quick_sin_contacto_120",
        },
        {
          title: "Pisos vacíos",
          meta: `${pisosVacios} inmuebles`,
          summary: "Oportunidades de entrada rápidas.",
          crmQuick: "captaciones:quick_pisos_vacios",
        },
        {
          title: "Alquilados (inquilinos)",
          meta: `${alquilados} inmuebles`,
          summary: "Cartera con inquilino (seguimiento).",
          crmQuick: "captaciones:quick_alquilados",
        },
      ];
      renderCrmActionList(crmCaptacionesOps, ops, "Sin bloqueos operativos en el pipeline.");
    }
    if (crmKpiCaptaciones) {
      crmKpiCaptaciones.textContent = String(baseRowMaps.length);
    }
    if (crmKpiEtapa) {
      const maxEtapa = Object.entries(counts).sort((a, b) => b[1] - a[1])[0];
      crmKpiEtapa.textContent = maxEtapa ? maxEtapa[0] : "-";
    }
    renderCrmResumenDashboard();
    crmCaptacionesTable.innerHTML = "";
    const node = buildCrmCaptacionesDenseTableNode(filteredRowMaps);
    if (!node) {
      crmCaptacionesTable.innerHTML = "<p class='muted'>Sin expedientes en el pipeline.</p>";
    } else {
      crmCaptacionesTable.appendChild(node);
    }
    if (crmCaptacionesInfo) {
      crmCaptacionesInfo.textContent = activeEtapa
        ? `Mostrando ${filteredRowMaps.length} expedientes en ${activeEtapa}.`
        : `Mostrando ${filteredRowMaps.length} expedientes.`;
    }
    })
    .catch((error) => {
      if (Number(error?.status || 0) === 401) return;
      crmCaptacionesTable.innerHTML = "<p class='muted'>No se pudo cargar el pipeline.</p>";
      console.error("loadCrmCaptaciones failed:", error);
    });
};

const loadCrmAlquileres = () => {
  if (!crmAlquileresTable) {
    return;
  }
  const scope = resolveInmoScopeParams();
  if (!scope || (!scope.workspace_id && !scope.empresa_id)) {
    crmAlquileresTable.innerHTML = "<p class='muted'>Sin empresa.</p>";
    return;
  }
  const params = new URLSearchParams({
    tabla: "alquileres",
    ...scope,
    include_id: "1",
  });
  const q = crmAlquilerSearch?.value?.trim() || "";
  if (q) {
    params.set("q", q);
  }
  api(`/api/tabla?${params.toString()}`).then((data) => {
    const rows = Array.isArray(data?.rows) ? data.rows : [];
    const columns = Array.isArray(data?.columns) ? data.columns : [];
    const rowMaps = rows.map((row) => buildRowMap(row, columns));
    rowMaps.forEach((row) => {
      if (!row) return;
      if (!row.fecha_inicio && row.fecha) row.fecha_inicio = row.fecha;
      if (!row.estado && row.tipo) row.estado = row.tipo;
    });
    cachedCrmAlquileres = rowMaps;
    const preset = normalizeCrmAlquilerPreset(crmAlquilerPreset?.value || "");
    const filteredRows = filterCrmAlquileresRows(rowMaps, { preset });
    const activos = rowMaps.filter((row) => {
      const status = normalizeSimple(row.estado || row.situacion || row.estado_operacion || "");
      return status && !status.includes("cerr") && !status.includes("baja") && !status.includes("cancel");
    }).length;
    const conRenta = rowMaps.filter((row) => {
      const rent = Number(row.renta || row.renta_mensual || row.precio || 0);
      return Number.isFinite(rent) && rent > 0;
    }).length;
    const conInquilino = rowMaps.filter((row) => String(row.inquilino || row.arrendatario || "").trim()).length;
    renderCrmMiniCards(crmAlquileresMini, [
      {
        title: "Alquileres totales",
        value: rowMaps.length,
        meta: "Operaciones",
        summary: "Expedientes activos e históricos de alquiler.",
      },
      {
        title: "Con renta informada",
        value: conRenta,
        meta: "Pricing",
        summary: "Importes listos para seguimiento y documentación.",
      },
      {
        title: "Con inquilino vinculado",
        value: conInquilino,
        meta: "Relación",
        summary: "Alquileres con parte arrendataria identificada.",
      },
      {
        title: "Activos",
        value: activos,
        meta: "Cartera",
        summary: "Expedientes todavía abiertos o en gestión.",
      },
    ]);
    const buildAlquileresTable = (items = []) => {
      if (!crmAlquileresTable) return;
      crmAlquileresTable.innerHTML = "";
      if (!items.length) {
        crmAlquileresTable.innerHTML = "<p class='muted'>Sin alquileres.</p>";
        if (crmAlquileresInfo) crmAlquileresInfo.textContent = "";
        return;
      }
      const table = document.createElement("table");
      table.className = "crm-dense-table crm-alquileres-table";
      const thead = document.createElement("thead");
      thead.innerHTML = `
        <tr>
          <th style="width:34px;"></th>
          <th>Fecha</th>
          <th>Dirección</th>
          <th>Propietario</th>
          <th>Tel.</th>
          <th>Precio</th>
          <th>Inquilino</th>
          <th>Tel.</th>
          <th>Agente</th>
          <th>Oficina</th>
          <th>Tipo</th>
        </tr>
      `;
      table.appendChild(thead);
      const tbody = document.createElement("tbody");
      items.forEach((row) => {
        const tr = document.createElement("tr");
        const selectTd = document.createElement("td");
        selectTd.className = "crm-dense-select";
        const checkbox = document.createElement("input");
        checkbox.type = "checkbox";
        checkbox.addEventListener("click", (event) => event.stopPropagation());
        selectTd.appendChild(checkbox);
        tr.appendChild(selectTd);

        const cells = [
          ["fecha", row.fecha],
          ["direccion", row.direccion],
          ["propietario", row.propietario],
          ["telefono", row.telefono],
          ["precio", row.precio],
          ["inquilino", row.inquilino],
          ["telefono2", row.telefono2],
          ["agente", row.agente],
          ["oficina", row.oficina],
          ["tipo", row.tipo],
        ];
        cells.forEach(([col, value]) => {
          const td = document.createElement("td");
          const formatted = formatCell(col, value);
          td.textContent = formatted === null ? "" : String(formatted || "").trim();
          tr.appendChild(td);
        });
        tbody.appendChild(tr);
      });
      table.appendChild(tbody);
      enableCrmDenseTableResize(table);
      crmAlquileresTable.appendChild(table);
      if (crmAlquileresInfo) {
        crmAlquileresInfo.textContent = `Mostrando ${items.length} alquileres.`;
      }
    };
    buildAlquileresTable(filteredRows);
    if (crmAlquileresInfo) {
      const presetLabel =
        {
          activos: "Activos",
          sin_inquilino: "Sin inquilino",
          sin_renta: "Sin renta",
          todos: "",
        }[preset] || "";
      crmAlquileresInfo.textContent = `Mostrando ${filteredRows.length} de ${rowMaps.length}${presetLabel ? ` · ${presetLabel}` : ""}.`;
    }
    renderCrmResumenDashboard();
  });
};

const normalizeCrmAlquilerPreset = (value) => {
  const normalized = normalizeSimple(value || "");
  if (normalized === "activos") return "activos";
  if (normalized === "sin_inquilino") return "sin_inquilino";
  if (normalized === "sin_renta") return "sin_renta";
  if (normalized === "todos") return "todos";
  return "activos";
};

const filterCrmAlquileresRows = (rows = [], opts = {}) => {
  const items = Array.isArray(rows) ? rows : [];
  const preset = normalizeCrmAlquilerPreset(opts?.preset || crmAlquilerPreset?.value || "");
  return items.filter((row) => {
    if (!row) return false;
    const status = normalizeSimple(row.estado || row.situacion || row.estado_operacion || "");
    const hasInquilino = Boolean(String(row.inquilino || row.arrendatario || "").trim());
    const rent = Number(row.renta || row.renta_mensual || row.precio || 0);
    if (preset === "activos") {
      return !status.includes("cerr") && !status.includes("baja") && !status.includes("cancel") && !status.includes("final");
    }
    if (preset === "sin_inquilino") {
      return !hasInquilino;
    }
    if (preset === "sin_renta") {
      return !(Number.isFinite(rent) && rent > 0);
    }
    return true;
  });
};

const normalizeCrmCompraventasPreset = (value) => {
  const normalized = normalizeSimple(value || "");
  if (normalized === "todas") return "todas";
  if (normalized === "manuales") return "manuales";
  if (normalized === "historicas") return "historicas";
  if (normalized === "escrituradas") return "escrituradas";
  return "todas";
};

const filterCrmCompraventasRows = (rows = [], opts = {}) => {
  const items = Array.isArray(rows) ? rows : [];
  const preset = normalizeCrmCompraventasPreset(opts?.preset || crmCompraventasPreset?.value || "");
  return items.filter((row) => {
    if (!row) return false;
    if (preset === "manuales") {
      const estado = String(row.estado || "").trim().toLowerCase();
      const origen = String(row.origen || "").trim().toLowerCase();
      return estado === "manual" || origen === "formulario";
    }
    if (preset === "historicas") {
      const estado = normalizeSimple(row.estado || "");
      return (
        estado === "importado historico"
        || estado === "cerrada positiva"
        || estado === "cerrado positivo"
        || estado === "cerrada"
        || estado === "cerrado"
      );
    }
    if (preset === "escrituradas") {
      return Boolean(String(row.fecha_escritura || "").trim());
    }
    return true;
  });
};

const renderCrmPipeline = (counts = {}, activeEtapa = "") => {
  const etapas = [...CRM_ETAPAS_MAIN];
  [crmPipeline, crmCaptacionesStageSummary].forEach((container) => {
    if (!container) return;
    container.innerHTML = "";
    etapas.forEach((etapa) => {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.classList.add(`stage-${slugify(etapa)}`);
      btn.textContent = `${etapa} (${counts[etapa] || 0})`;
      btn.classList.toggle("active", activeEtapa === etapa);
      btn.addEventListener("click", () => {
        const nextEtapa = activeEtapa === etapa ? "" : etapa;
        if (crmEtapaFilter) crmEtapaFilter.value = nextEtapa;
        if (crmEtapaFilterMirror) crmEtapaFilterMirror.value = nextEtapa;
        loadCrmCaptaciones();
      });
      container.appendChild(btn);
    });
  });
};

let crmKanbanDragPayload = null;

const renderCrmKanban = (data) => {
  if (!crmKanban && !crmCaptacionesKanban) {
    return;
  }
  const etapaIndex = data.columns.indexOf("etapa");
  const idIndex = data.columns.indexOf("id");
  const propietarioIndex = data.columns.indexOf("propietario");
  const direccionIndex = data.columns.indexOf("direccion");
  const poblacionIndex = data.columns.indexOf("poblacion");
  const provinciaIndex = data.columns.indexOf("provincia");
  const proximaIndex = data.columns.indexOf("proxima_accion");
  const etapas = [...CRM_ETAPAS_MAIN];
  const grouped = new Map(etapas.map((e) => [e, []]));
  data.rows.forEach((row) => {
    const etapa = row[etapaIndex] || "Inmueble";
    if (!grouped.has(etapa)) {
      grouped.set(etapa, []);
    }
    grouped.get(etapa).push(row);
  });
  [crmKanban, crmCaptacionesKanban].forEach((container) => {
    if (!container) return;
    container.innerHTML = "";
    etapas.forEach((etapa) => {
      const column = document.createElement("div");
      column.className = "crm-kanban-column";
      column.innerHTML = `<h4>${etapa}</h4>`;
      column.dataset.etapa = etapa;
      column.addEventListener("dragover", (event) => {
        event.preventDefault();
      });
      column.addEventListener("drop", (event) => {
        event.preventDefault();
        const toEtapa = String(column.dataset.etapa || "").trim();
        const id = String(crmKanbanDragPayload?.captacionId || event.dataTransfer?.getData?.("text/plain") || "").trim();
        const fromEtapa = String(crmKanbanDragPayload?.fromEtapa || "").trim();
        const label = String(crmKanbanDragPayload?.label || "").trim();
        crmKanbanDragPayload = null;
        if (!id || !toEtapa) return;
        if (fromEtapa && normalizeSimple(fromEtapa) === normalizeSimple(toEtapa)) return;
        updateCaptacionEtapa(id, toEtapa, { fromEtapa, label });
      });
      const rows = grouped.get(etapa) || [];
      rows.slice(0, 5).forEach((row) => {
        const rowId = row[idIndex];
        const rowMap = buildRowMap(row, data.columns);
        const isVerified = String(rowMap?.noticia_verificada ?? "").trim() === "1";
        const card = document.createElement("div");
        card.className = "crm-kanban-card";
        // Importante: no hacemos la tarjeta "draggable" completa porque algunos navegadores
        // se comen el click (y el usuario no puede abrir la ficha). El drag se hace con un handle.
        const captacionId = String(rowMap?.id || rowId || "").trim();
        const inmuebleId = String(rowMap?.inmueble_id || "").trim();
        // Deep-link para fallback, pero el click abre dentro de la SPA.
        const deepLink = inmuebleId
          ? `/?crm=inmo&inmueble=${encodeURIComponent(inmuebleId)}`
          : `/?crm=inmo&captacion=${encodeURIComponent(captacionId)}`;
        const verifikaBadge = buildVerifika2Badge(isVerified, { compact: true });
        const localidad = [row[poblacionIndex] || rowMap?.poblacion || "", row[provinciaIndex] || rowMap?.provincia || ""]
          .filter(Boolean)
          .join(" · ");
        card.innerHTML = `
          <div class="crm-kanban-titleline">
            <strong>${row[propietarioIndex] || "Propietario"}</strong>
            <button type="button" class="crm-kanban-handle" draggable="true" aria-label="Mover de etapa"></button>
            ${verifikaBadge}
          </div>
          <div>${row[direccionIndex] || "-"}${localidad ? ` · ${escapeHtml(localidad)}` : ""}</div>
          <div class="muted">${row[proximaIndex] || "Sin próxima acción"}</div>
          <div class="inline-actions"><a class="ghost" href="${deepLink}" data-open="${inmuebleId ? "inmueble" : "captacion"}">Abrir ficha</a></div>
        `;
        const dragHandle = card.querySelector(".crm-kanban-handle");
        if (dragHandle) {
          dragHandle.addEventListener("dragstart", (event) => {
            try {
              event.dataTransfer?.setData?.("text/plain", String(captacionId || ""));
              event.dataTransfer.effectAllowed = "move";
            } catch (e) {}
            crmKanbanDragPayload = {
              captacionId: String(captacionId || "").trim(),
              inmuebleId: String(inmuebleId || "").trim(),
              fromEtapa: String(etapa || "").trim(),
              label: String(row[direccionIndex] || row[propietarioIndex] || "").trim(),
            };
          });
          dragHandle.addEventListener("click", (event) => {
            event.preventDefault();
            event.stopPropagation();
          });
        }
        // Click en tarjeta/link: abrir la ficha sin reload (más robusto en Render).
        const openFn = (event) => {
          if (event?.metaKey || event?.ctrlKey || event?.shiftKey || event?.altKey) return;
          if (String(event?.target?.className || "").includes("crm-kanban-handle")) return;
          event?.preventDefault?.();
          event?.stopPropagation?.();
          ensureCrmOpen(() => {
            if (inmuebleId) {
              openInmuebleDetail(inmuebleId, "captaciones");
              return;
            }
            openInmuebleFromCaptacion(captacionId, "captaciones");
          });
        };
        card.addEventListener("click", openFn);
        const link = card.querySelector('a[data-open="captacion"], a[data-open="inmueble"]');
        if (link) link.addEventListener("click", openFn);
        column.appendChild(card);
      });
      container.appendChild(column);
    });
  });
};

const parseCrmDateTime = (dateValue, timeValue = "") => {
  const dateText = String(dateValue || "").trim();
  if (!dateText) return 0;
  let year = 0;
  let month = 0;
  let day = 0;
  let match = dateText.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (match) {
    year = Number(match[1]);
    month = Number(match[2]) - 1;
    day = Number(match[3]);
  } else {
    match = dateText.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
    if (!match) return 0;
    day = Number(match[1]);
    month = Number(match[2]) - 1;
    year = Number(match[3]);
  }
  const [hours, minutes] = String(timeValue || "")
    .split(":")
    .map((part) => Number(part || 0));
  return new Date(year, month, day, Number.isFinite(hours) ? hours : 0, Number.isFinite(minutes) ? minutes : 0).getTime();
};

const renderCrmMiniCards = (container, items = []) => {
  if (!container) return;
  if (!items.length) {
    container.innerHTML = "";
    return;
  }
  container.innerHTML = items
    .map((item) => {
      const attrs = [];
      if (item.inmuebleId) attrs.push(`data-inmueble-id="${escapeHtml(item.inmuebleId)}"`);
      if (item.captacionId) attrs.push(`data-captacion-id="${escapeHtml(item.captacionId)}"`);
      if (item.crmView) attrs.push(`data-crm-view="${escapeHtml(item.crmView)}"`);
      if (item.etapa) attrs.push(`data-etapa="${escapeHtml(item.etapa)}"`);
      const href = (() => {
        const inmuebleId = String(item.inmuebleId || "").trim();
        const captacionId = String(item.captacionId || "").trim();
        if (!inmuebleId && !captacionId) return "";
        try {
          const params = new URLSearchParams(window.location.search || "");
          ensureTenantParams(params);
          params.set("crm", "inmo");
          params.delete("tab");
          params.delete("empresa");
          params.delete("clientes");
          params.delete("cliente");
          params.delete("poliza");
          if (inmuebleId) {
            params.set("inmueble", inmuebleId);
            params.delete("captacion");
          } else {
            params.set("captacion", captacionId);
            params.delete("inmueble");
          }
          return `/?${params.toString()}`;
        } catch (e) {
          if (inmuebleId) return `/?crm=inmo&inmueble=${encodeURIComponent(inmuebleId)}`;
          return `/?crm=inmo&captacion=${encodeURIComponent(captacionId)}`;
        }
      })();
      const tag = href ? "a" : "div";
      const hrefAttr = href ? ` href="${escapeHtml(href)}"` : "";
      return `
        <${tag}${hrefAttr} class="crm-mini-card${attrs.length ? " crm-mini-card--linkable" : ""}"${attrs.length ? ` ${attrs.join(" ")}` : ""}>
          <div>
            <h4>${escapeHtml(item.title)}</h4>
            <div class="muted">${escapeHtml(item.summary || "")}</div>
          </div>
          <div class="crm-mini-meta">
            <strong>${escapeHtml(String(item.value ?? "-"))}</strong>
            <span>${escapeHtml(item.meta || "")}</span>
          </div>
        </${tag}>
      `;
    })
    .join("");
  container.querySelectorAll(".crm-mini-card[data-inmueble-id], .crm-mini-card[data-captacion-id]").forEach((card) => {
    card.addEventListener("click", async (event) => {
      // Evita depender de reload completos (en algunos entornos terminaba en el panel general).
      // Permitimos abrir en nueva pestaña con Ctrl/⌘ o modificadores.
      if (!(event.metaKey || event.ctrlKey || event.shiftKey || event.altKey)) {
        event.preventDefault?.();
      }
      const inmuebleId = String(card.dataset.inmuebleId || "").trim();
      const captacionId = String(card.dataset.captacionId || "").trim();
      if (inmuebleId) {
        openInmuebleDetail(inmuebleId, "resumen");
        return;
      }
      if (captacionId) {
        const ensured = await ensureInmuebleForCaptacion(captacionId);
        if (!ensured) {
          alert("No se pudo abrir la ficha del inmueble (no hay inmueble vinculado).");
          return;
        }
        openInmuebleDetail(ensured, "resumen");
      }
    });
  });
  container.querySelectorAll(".crm-mini-card[data-crm-view]").forEach((card) => {
    card.addEventListener("click", (event) => {
      if (!(event.metaKey || event.ctrlKey || event.shiftKey || event.altKey)) {
        event.preventDefault?.();
      }
      const view = card.dataset.crmView || "";
      if (!view) return;
      setCrmWorkspaceView(view);
      const etapa = String(card.dataset.etapa || "").trim();
      if (view === "captaciones" && etapa) {
        if (crmEtapaFilter) crmEtapaFilter.value = etapa;
        if (crmEtapaFilterMirror) crmEtapaFilterMirror.value = etapa;
        loadCrmCaptaciones();
      }
    });
  });
};

const renderCrmActionList = (container, items = [], emptyMessage = "Sin elementos pendientes.") => {
  if (!container) return;
  if (!items.length) {
    container.innerHTML = `<p class='muted'>${escapeHtml(emptyMessage)}</p>`;
    return;
  }
  container.innerHTML = items
    .map((item) => {
      const attrs = [];
      if (item.inmuebleId) attrs.push(`data-inmueble-id="${escapeHtml(item.inmuebleId)}"`);
      if (item.captacionId) attrs.push(`data-captacion-id="${escapeHtml(item.captacionId)}"`);
      if (item.crmView) attrs.push(`data-crm-view="${escapeHtml(item.crmView)}"`);
      if (item.etapa) attrs.push(`data-etapa="${escapeHtml(item.etapa)}"`);
      if (item.crmQuick) attrs.push(`data-crm-quick="${escapeHtml(item.crmQuick)}"`);
      const href = item.inmuebleId
        ? `/?crm=inmo&inmueble=${encodeURIComponent(item.inmuebleId)}`
        : item.captacionId
          ? `/?crm=inmo&captacion=${encodeURIComponent(item.captacionId)}`
          : "";
      const tag = href ? "a" : item.crmQuick || item.crmView ? "button" : "div";
      const typeAttr = tag === "button" ? ' type="button"' : "";
      const hrefAttr = tag === "a" ? ` href="${escapeHtml(href)}"` : "";
      return `
        <${tag}${typeAttr}${hrefAttr} class="crm-focus-link"${attrs.length ? ` ${attrs.join(" ")}` : ""}>
          <strong>${escapeHtml(item.title || "-")}</strong>
          ${item.meta ? `<span>${escapeHtml(item.meta)}</span>` : ""}
          ${item.summary ? `<span>${escapeHtml(item.summary)}</span>` : ""}
        </${tag}>
      `;
    })
    .join("");
  container.querySelectorAll("[data-inmueble-id], [data-captacion-id]").forEach((btn) => {
    btn.addEventListener("click", async (event) => {
      if (!(event.metaKey || event.ctrlKey || event.shiftKey || event.altKey)) {
        event.preventDefault?.();
      }
      const inmuebleId = String(btn.dataset.inmuebleId || "").trim();
      const captacionId = String(btn.dataset.captacionId || "").trim();
      if (inmuebleId) {
        ensureCrmOpen(() => openInmuebleDetail(inmuebleId, "resumen"));
        return;
      }
      if (captacionId) {
        const ensured = await ensureInmuebleForCaptacion(captacionId);
        if (!ensured) {
          alert("No se pudo abrir la ficha del inmueble (no hay inmueble vinculado).");
          return;
        }
        ensureCrmOpen(() => openInmuebleDetail(ensured, "resumen"));
      }
    });
  });
  container.querySelectorAll("[data-crm-quick]").forEach((btn) => {
    btn.addEventListener("click", (event) => {
      if (!(event.metaKey || event.ctrlKey || event.shiftKey || event.altKey)) {
        event.preventDefault?.();
      }
      const token = String(btn.dataset.crmQuick || "").trim();
      if (!token) return;
      applyCrmTecnocloudQuickSearch(token);
    });
  });
  container.querySelectorAll("[data-crm-view]").forEach((btn) => {
    btn.addEventListener("click", (event) => {
      if (!(event.metaKey || event.ctrlKey || event.shiftKey || event.altKey)) {
        event.preventDefault?.();
      }
      const view = btn.dataset.crmView || "";
      if (!view) return;
      setCrmWorkspaceView(view);
      const etapa = String(btn.dataset.etapa || "").trim();
      if (view === "captaciones" && etapa) {
        if (crmEtapaFilter) crmEtapaFilter.value = etapa;
        if (crmEtapaFilterMirror) crmEtapaFilterMirror.value = etapa;
        loadCrmCaptaciones();
      }
    });
  });
};

let crmResumenFiltersInitDone = false;

const _toDateInput = (dt) => {
  if (!(dt instanceof Date) || Number.isNaN(dt.getTime())) return "";
  return dt.toISOString().slice(0, 10);
};

const _startOfMonth = (dt) => new Date(dt.getFullYear(), dt.getMonth(), 1);
const _startOfYear = (dt) => new Date(dt.getFullYear(), 0, 1);

const computeCrmResumenRange = (rangeKey = "12m") => {
  const now = new Date();
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const key = String(rangeKey || "12m").trim().toLowerCase();
  if (key === "all") {
    return { desde: "", hasta: "" };
  }
  if (key === "mtd") {
    return { desde: _toDateInput(_startOfMonth(today)), hasta: _toDateInput(today) };
  }
  if (key === "ytd") {
    return { desde: _toDateInput(_startOfYear(today)), hasta: _toDateInput(today) };
  }
  if (key === "30d") {
    const desde = new Date(today);
    desde.setDate(desde.getDate() - 30);
    return { desde: _toDateInput(desde), hasta: _toDateInput(today) };
  }
  if (key === "12m") {
    const desde = new Date(today);
    desde.setFullYear(desde.getFullYear() - 1);
    return { desde: _toDateInput(desde), hasta: _toDateInput(today) };
  }
  return { desde: "", hasta: "" };
};

const getCrmResumenWindowTs = () => {
  const rangeKey = String(state.crmResumenRange || "12m").trim().toLowerCase();
  let desde = String(state.crmResumenDesde || "").trim();
  let hasta = String(state.crmResumenHasta || "").trim();
  if (rangeKey !== "custom") {
    const computed = computeCrmResumenRange(rangeKey);
    desde = computed.desde;
    hasta = computed.hasta;
  }
  const fromTs = desde ? parseCrmDateTime(desde, "00:00") : 0;
  const toTs = hasta ? (parseCrmDateTime(hasta, "23:59") || 0) : Number.MAX_SAFE_INTEGER;
  return { fromTs, toTs };
};

const getCrmVentaOperacionTs = (row = {}) => {
  const fecha = String(row.fecha_operacion || row.fecha_escritura || row.fecha_contrato || row.fecha_propuesta || row.fecha_encargo || "").trim();
  if (!fecha) return 0;
  return parseCrmDateTime(fecha, "00:00") || 0;
};

const computeVentaDeviation = (row = {}) => {
  const salida = Number(row.precio_encargo || 0) || 0;
  const venta = Number(row.precio_venta || row.precio_escritura || 0) || 0;
  const legacyEur = Number(row.desviacion_euros || 0) || 0;
  const legacyPct = Number(row.desviacion_pct || 0) || 0;
  if (salida > 0 && venta > 0) {
    const eur = venta - salida;
    const pct = (eur / salida) * 100;
    return { eur, pct, salida, venta, ok: true };
  }
  if (legacyEur || legacyPct) {
    return { eur: legacyEur, pct: legacyPct, salida: salida || 0, venta: venta || 0, ok: true };
  }
  return { eur: 0, pct: 0, salida: salida || 0, venta: venta || 0, ok: false };
};

const computeVentaDias = (row = {}) => {
  const raw = Number(row.dias_hasta_venta || 0) || 0;
  if (raw > 0) return raw;
  const start = String(row.fecha_encargo || "").trim();
  const end = String(row.fecha_escritura || row.fecha_contrato || "").trim();
  if (!start || !end) return 0;
  const startTs = parseCrmDateTime(start, "00:00");
  const endTs = parseCrmDateTime(end, "00:00");
  if (!startTs || !endTs) return 0;
  const diffDays = Math.round((endTs - startTs) / (1000 * 60 * 60 * 24));
  return diffDays > 0 ? diffDays : 0;
};

const computeVentaVisitas = (row = {}, visitsByInmueble = new Map()) => {
  const direct = Number(row.num_visitas || 0) || 0;
  if (direct > 0) return direct;
  const inmuebleId = String(row.inmueble_id || "").trim();
  if (!inmuebleId) return 0;
  return Number(visitsByInmueble.get(inmuebleId) || 0) || 0;
};

const hydrateCrmResumenFilters = () => {
  if (!crmResumenRange || !crmResumenDireccionKpis) return;
  if (crmResumenFiltersInitDone) return;
  crmResumenFiltersInitDone = true;

  const syncUi = () => {
    if (crmResumenRange) crmResumenRange.value = String(state.crmResumenRange || "12m");
    const isCustom = String(state.crmResumenRange || "").trim().toLowerCase() === "custom";
    if (crmResumenDesdeWrap) crmResumenDesdeWrap.classList.toggle("hidden", !isCustom);
    if (crmResumenHastaWrap) crmResumenHastaWrap.classList.toggle("hidden", !isCustom);
    if (crmResumenDesde) crmResumenDesde.value = String(state.crmResumenDesde || "");
    if (crmResumenHasta) crmResumenHasta.value = String(state.crmResumenHasta || "");
    if (crmResumenResponsable) crmResumenResponsable.value = String(state.crmResumenResponsable || "");
    if (crmResumenOrigen) crmResumenOrigen.value = String(state.crmResumenOrigen || "");
  };

  const ensureDates = () => {
    const key = String(state.crmResumenRange || "12m").trim().toLowerCase();
    if (key !== "custom") {
      const computed = computeCrmResumenRange(key);
      state.crmResumenDesde = computed.desde;
      state.crmResumenHasta = computed.hasta;
      return;
    }
    if (!String(state.crmResumenDesde || "").trim() || !String(state.crmResumenHasta || "").trim()) {
      const fallback = computeCrmResumenRange("30d");
      state.crmResumenDesde = state.crmResumenDesde || fallback.desde;
      state.crmResumenHasta = state.crmResumenHasta || fallback.hasta;
    }
  };

  ensureDates();
  syncUi();

  crmResumenRange.addEventListener("change", () => {
    state.crmResumenRange = String(crmResumenRange.value || "12m");
    ensureDates();
    syncUi();
    renderCrmResumenDashboard();
  });
  crmResumenDesde?.addEventListener("change", () => {
    state.crmResumenDesde = String(crmResumenDesde.value || "");
    renderCrmResumenDashboard();
  });
  crmResumenHasta?.addEventListener("change", () => {
    state.crmResumenHasta = String(crmResumenHasta.value || "");
    renderCrmResumenDashboard();
  });
  crmResumenResponsable?.addEventListener("change", () => {
    state.crmResumenResponsable = String(crmResumenResponsable.value || "");
    renderCrmResumenDashboard();
  });
  crmResumenOrigen?.addEventListener("change", () => {
    state.crmResumenOrigen = String(crmResumenOrigen.value || "");
    renderCrmResumenDashboard();
  });
  crmResumenReset?.addEventListener("click", () => {
    state.crmResumenRange = "12m";
    const computed = computeCrmResumenRange("12m");
    state.crmResumenDesde = computed.desde;
    state.crmResumenHasta = computed.hasta;
    state.crmResumenResponsable = "";
    state.crmResumenOrigen = "";
    syncUi();
    renderCrmResumenDashboard();
  });
};

let crmResumenYtdInitDone = false;
let crmResumenYtdInFlightKey = "";
let crmResumenYtdLastData = null;

const hydrateCrmResumenYtdControls = () => {
  if (crmResumenYtdInitDone) return;
  if (!crmResumenYtdBoard || !crmResumenYtdYear) return;
  crmResumenYtdInitDone = true;

  const now = new Date();
  const currentYear = now.getFullYear();
  const years = [currentYear, currentYear - 1, currentYear - 2].map((y) => String(y));
  crmResumenYtdYear.innerHTML = years.map((y) => `<option value="${escapeHtml(y)}">${escapeHtml(y)}</option>`).join("");
  crmResumenYtdYear.value = years.includes(String(state.crmResumenYtdYear || "")) ? String(state.crmResumenYtdYear) : String(currentYear);
  state.crmResumenYtdYear = crmResumenYtdYear.value;

  crmResumenYtdYear.addEventListener("change", () => {
    state.crmResumenYtdYear = String(crmResumenYtdYear.value || String(currentYear));
    try {
      localStorage.setItem("crm.resumen.ytdYear", state.crmResumenYtdYear);
    } catch (e) {}
    renderCrmResumenYtdBoard({ force: true });
  });

  crmResumenYtdResponsable?.addEventListener("change", () => {
    state.crmResumenYtdResponsable = String(crmResumenYtdResponsable.value || "");
    try {
      localStorage.setItem("crm.resumen.ytdResponsable", state.crmResumenYtdResponsable);
    } catch (e) {}
    renderCrmResumenYtdBoard({ force: true });
  });
};

const buildCrmYtdMonths = (year) => {
  const y = Number(year || 0) || new Date().getFullYear();
  const now = new Date();
  const maxMonth = y === now.getFullYear() ? (now.getMonth() + 1) : 12;
  const months = Array.from({ length: maxMonth }, (_, idx) => `${y}-${String(idx + 1).padStart(2, "0")}`);
  const labelsEs = ["Ene", "Feb", "Mar", "Abr", "May", "Jun", "Jul", "Ago", "Sep", "Oct", "Nov", "Dic"];
  const labels = months.map((m) => labelsEs[Math.max(0, Math.min(11, Number(m.slice(5, 7)) - 1))] || m);
  return { months, labels };
};

const alignMonthlySeries = (rows, months, field) => {
  const map = new Map();
  (Array.isArray(rows) ? rows : []).forEach((row) => {
    const key = String(row?.month || "").trim();
    if (!key) return;
    map.set(key, row);
  });
  return months.map((m) => {
    const row = map.get(m);
    const raw = row ? row[field] : 0;
    const n = Number(raw || 0);
    return Number.isFinite(n) ? n : 0;
  });
};

const renderCrmResumenYtdBoard = async ({ force = false } = {}) => {
  if (!crmResumenYtdBoard || !crmResumenYtdKpis) return;
  if (crmViewResumen && crmViewResumen.classList.contains("hidden")) return;
  const empresa = resolveCrmInmoEmpresa();
  const empresaId = resolveLegacyEmpresaId(empresa);
  if (!empresaId) return;
  hydrateCrmResumenYtdControls();

  const authUser = getAuthScopeUser();
  const isPrivileged = Boolean(authUser && isPrivilegedUser(authUser));
  if (crmResumenYtdResponsableWrap) {
    crmResumenYtdResponsableWrap.classList.toggle("hidden", !isPrivileged);
  }
  if (!isPrivileged) {
    state.crmResumenYtdResponsable = "";
    if (crmResumenYtdResponsable) crmResumenYtdResponsable.value = "";
  }

  const year = String(state.crmResumenYtdYear || new Date().getFullYear());
  const responsable = isPrivileged ? String(state.crmResumenYtdResponsable || "") : "";
  const key = `${empresaId}::${year}::${responsable}::${isPrivileged ? "1" : "0"}`;
  if (!force && crmResumenYtdLastData && crmResumenYtdInFlightKey === "" && crmResumenYtdLastData.__key === key) {
    // Ya renderizado.
    return;
  }
  if (crmResumenYtdInFlightKey === key) return;
  crmResumenYtdInFlightKey = key;

  const params = new URLSearchParams({ empresa_id: empresaId, year });
  if (responsable) params.set("responsable", responsable);
  try {
    const data = await api(`/api/crm_resumen_ytd?${params.toString()}`);
    crmResumenYtdInFlightKey = "";
    crmResumenYtdLastData = { ...data, __key: key };

    const safeYear = String(data?.year || year);
    if (crmResumenYtdTitle) {
      const suffix = isPrivileged && responsable ? ` · ${responsable}` : "";
      crmResumenYtdTitle.textContent = `KPIs ${safeYear}${suffix}`;
    }
    if (crmResumenYtdYear) crmResumenYtdYear.value = safeYear;

    if (isPrivileged && crmResumenYtdResponsable) {
      const current = String(state.crmResumenYtdResponsable || "");
      const opts = Array.isArray(data?.responsables) ? data.responsables : [];
      crmResumenYtdResponsable.innerHTML = `<option value="">Todos</option>${opts
        .map((v) => `<option value="${escapeHtml(v)}">${escapeHtml(v)}</option>`)
        .join("")}`;
      if (current) crmResumenYtdResponsable.value = current;
    }

    const kpis = data?.kpis || {};
    const funnelMeta = String(data?.funnel_source || "") === "pipeline" ? "pipeline actual" : "eventos YTD";
    renderCrmMiniCards(crmResumenYtdKpis, [
      {
        title: "Ventas realizadas",
        value: Number(kpis.ventas || 0) || 0,
        meta: safeYear,
        summary: "Operaciones de venta cerradas (escritura/precio).",
        crmView: "compraventas",
      },
      {
        title: "Comisión oficina",
        value: formatEuros(Number(kpis.comision_ventas || 0) || 0),
        meta: "Ventas",
        summary: "Suma de honorarios en ventas cerradas.",
        crmView: "compraventas",
      },
      {
        title: "Alquileres realizados",
        value: Number(kpis.alquileres || 0) || 0,
        meta: safeYear,
        summary: "Contratos de alquiler registrados.",
        crmView: "alquileres",
      },
      {
        title: "Comisión alquileres",
        value: formatEuros(Number(kpis.comision_alquileres || 0) || 0),
        meta: "Alquileres",
        summary: "Suma de importe de comisión en alquileres.",
        crmView: "alquileres",
      },
      {
        title: "Noticias por encargo",
        value: Number(kpis.noticias_por_encargo || 0).toFixed(2),
        meta: `${Number(kpis.noticias || 0) || 0} → ${Number(kpis.encargos || 0) || 0}`,
        summary: `Conversión Noticia→Encargo (${funnelMeta}).`,
        crmView: "captaciones",
        etapa: "Noticia",
      },
      {
        title: "Citas por propuesta",
        value: Number(kpis.citas_por_propuesta || 0).toFixed(2),
        meta: `${Number(kpis.citas || 0) || 0} → ${Number(kpis.propuestas || 0) || 0}`,
        summary: "Ratio de citas registradas por propuesta generada.",
        crmView: "agenda",
      },
      {
        title: "Pisos propuestos",
        value: Number(kpis.pisos_propuestos || 0) || 0,
        meta: safeYear,
        summary: "Matches inmueble–demanda creados.",
        crmView: "demandas",
      },
      {
        title: "Pendientes",
        value: Number(kpis.pendientes || 0) || 0,
        meta: "Vencidas",
        summary: "Acciones/visitas vencidas (sin cierre).",
        crmView: "agenda",
      },
      {
        title: "Próximas 7d",
        value: Number(kpis.proximas || 0) || 0,
        meta: "Agenda",
        summary: "Acciones/visitas en los próximos 7 días.",
        crmView: "agenda",
      },
    ]);

    const mapReminder = (item) => {
      const kind = String(item?.kind || "").trim();
      const fecha = String(item?.fecha || "-");
      const hora = String(item?.hora || "").trim();
      const responsableLabel = String(item?.responsable || "").trim();
      const when = `${fecha}${hora ? ` ${hora}` : ""}`.trim();
      const inmuebleId = String(item?.inmueble_id || "").trim();
      const base = {
        title: kind === "visita" ? "Visita" : (String(item?.asunto || "").trim() || String(item?.tipo || "").trim() || "Acción"),
        meta: [when, responsableLabel].filter(Boolean).join(" · "),
        summary: [String(item?.tipo || "").trim(), String(item?.estado || "").trim(), String(item?.cliente || "").trim()].filter(Boolean).join(" · "),
      };
      if (inmuebleId) return { ...base, inmuebleId };
      return { ...base, crmView: kind === "visita" ? "visitas" : "agenda" };
    };

    const upcoming = Array.isArray(data?.reminders?.upcoming) ? data.reminders.upcoming : [];
    const overdue = Array.isArray(data?.reminders?.overdue) ? data.reminders.overdue : [];
    renderCrmActionList(crmResumenProximas, upcoming.map(mapReminder).slice(0, 8), "Sin próximos hitos.");
    renderCrmActionList(crmResumenPendientes, overdue.map(mapReminder).slice(0, 8), "Sin pendientes vencidos.");

    const { months, labels } = buildCrmYtdMonths(safeYear);
    const series = data?.series || {};
    requestAnimationFrame(() => {
      drawBarChart(
        crmYtdOperacionesChart,
        labels,
        [
          {
            label: "Ventas",
            values: alignMonthlySeries(series.ventas_by_month, months, "total"),
            color: "#824c45",
            format: (value) => numberFormatter.format(value),
          },
          {
            label: "Alquileres",
            values: alignMonthlySeries(series.alquileres_by_month, months, "total"),
            color: "#cca33c",
            format: (value) => numberFormatter.format(value),
          },
          {
            label: "Citas",
            values: alignMonthlySeries(series.citas_by_month, months, "total"),
            color: "#22C55E",
            format: (value) => numberFormatter.format(value),
          },
        ],
        { legend: true, showValues: false }
      );

      drawBarChart(
        crmYtdComisionesChart,
        labels,
        [
          {
            label: "Comisión ventas",
            values: alignMonthlySeries(series.ventas_by_month, months, "comision"),
            color: "#d7b04c",
            format: (value) => euroFormatter.format(value),
          },
          {
            label: "Comisión alquileres",
            values: alignMonthlySeries(series.alquileres_by_month, months, "comision"),
            color: "#334155",
            format: (value) => euroFormatter.format(value),
          },
        ],
        { legend: true, showValues: false }
      );

      const embudoLabels = ["Noticias", "Encargos", "Propuestas", "Pisos propuestos"];
      const embudoValues = [
        Number(kpis.noticias || 0) || 0,
        Number(kpis.encargos || 0) || 0,
        Number(kpis.propuestas || 0) || 0,
        Number(kpis.pisos_propuestos || 0) || 0,
      ];
      drawBarChart(
        crmYtdEmbudoChart,
        embudoLabels,
        [
          {
            label: "Total",
            values: embudoValues,
            color: "#334155",
            format: (value) => numberFormatter.format(value),
          },
        ],
        { legend: false, showValues: true }
      );
    });
  } catch (err) {
    crmResumenYtdInFlightKey = "";
    crmResumenYtdKpis.innerHTML = "<p class='muted'>No se pudieron cargar los KPIs del año.</p>";
  }
};

let crmInicioDragPayload = null;

const renderCrmHomeAgendaPreview = () => {
  const container = document.getElementById("crmHomeAgendaPreview");
  if (!container) return;
  const rows = Array.isArray(state.crmAgendaRowsAll) ? state.crmAgendaRowsAll : [];
  if (!rows.length) {
    container.innerHTML = "<p class='muted'>Sin actividades registradas.</p>";
    return;
  }
  const isDone = (row) => normalizeSimple(row?.estado || "") === "realizada";
  const items = rows
    .filter((row) => !isDone(row))
    .map((row) => {
      const fecha = String(row?.fecha || "").trim();
      const hora = String(row?.hora || "").trim();
      const ts = parseCrmDateTime(fecha, hora) || 0;
      return { ...row, __ts: ts };
    })
    .sort((a, b) => (a.__ts || 0) - (b.__ts || 0))
    .slice(0, 8)
    .map((row) => ({
      crmView: "agenda",
      title: row.asunto || row.tipo || "Actividad",
      meta: [row.fecha || "", row.hora || ""].filter(Boolean).join(" ").trim(),
      summary: [row.cliente || "", row.estado || ""].filter(Boolean).join(" · "),
    }));
  renderCrmActionList(container, items, "Sin próximas acciones.");
};

const renderCrmInicioBoard = (pipelineItems = []) => {
  if (!crmInicioBoard) return;
  const items = Array.isArray(pipelineItems) ? pipelineItems : [];
  if (!items.length) {
    crmInicioBoard.innerHTML = "<p class='muted'>Sin inmuebles en cartera.</p>";
    return;
  }

  const etapas = ["Inmueble", "Noticia", "Encargo", "Propuesta", "Reservado", "Contrato de arras", "Vendido"];
  const normalizeStage = (raw) => normalizeCrmMainEtapa(String(raw || "").trim()) || "Inmueble";
  const grouped = new Map(etapas.map((e) => [e, []]));
  items.forEach((row) => {
    const stage = normalizeStage(row.stage || row.estado || "");
    const key = grouped.has(stage) ? stage : "Inmueble";
    grouped.get(key).push(row);
  });

  const scoreRow = (row) => {
    let score = 0;
    const stage = normalizeStage(row.stage || row.estado || "");
    const next = String(row.proxima_accion || "").trim();
    if (!next) score += 4;
    if (stage === "Inmueble") score += 2;
    if (stage === "Noticia" && !row.noticia_verificada) score += 3;
    return score;
  };
  const sortEs = (a, b) => String(a || "").localeCompare(String(b || ""), "es", { sensitivity: "base" });

  crmInicioBoard.innerHTML = "";
  crmInicioBoard.classList.add("crm-kanban");

  etapas.forEach((etapa) => {
    const columnRows = (grouped.get(etapa) || [])
      .slice()
      .sort((a, b) => (scoreRow(b) - scoreRow(a)) || sortEs(a.direccion, b.direccion));
    const col = document.createElement("div");
    col.className = "crm-kanban-column";
    col.dataset.etapa = etapa;
    col.innerHTML = `<h4>${escapeHtml(etapa)} (${columnRows.length})</h4>`;
    col.addEventListener("dragover", (event) => event.preventDefault());
    col.addEventListener("drop", (event) => {
      event.preventDefault();
      const payload = crmInicioDragPayload;
      crmInicioDragPayload = null;
      const toEtapa = String(col.dataset.etapa || "").trim();
      const captacionId = String(payload?.captacionId || "").trim();
      const fromEtapa = String(payload?.fromEtapa || "").trim();
      const label = String(payload?.label || "").trim();
      if (!captacionId) {
        alert("No se pudo mover: falta el id de la captación (registro legacy).");
        return;
      }
      if (!toEtapa) return;
      if (fromEtapa && normalizeSimple(fromEtapa) === normalizeSimple(toEtapa)) return;
      updateCaptacionEtapa(captacionId, toEtapa, { fromEtapa, label });
    });

    const maxCards = 6;
    columnRows.slice(0, maxCards).forEach((row) => {
      const inmuebleId = String(row.inmueble_id || row.id || "").trim();
      const captacionId = String(row.captacion_id || "").trim();
      const stage = normalizeStage(row.stage || row.estado || "");
      const codePrefix = resolveCaptacionCodePrefix(stage);
      const direccion = String(row.direccion || "").trim() || "Sin dirección";
      const propietario = String(row.propietario || row.propietarios || "").trim() || "Propietario pendiente";
      const proxima = String(row.proxima_accion || "").trim() || "Sin próxima acción definida.";
      const verifiedBadge = buildVerifika2Badge(Boolean(row.noticia_verificada), { compact: true });

      const card = document.createElement("button");
      card.type = "button";
      card.className = "crm-kanban-card";
      card.innerHTML = `
        <div class="crm-kanban-titleline">
          <strong title="${escapeHtml(`${codePrefix} - ${direccion}`)}">${escapeHtml(`${codePrefix} - ${direccion}`)}</strong>
          ${verifiedBadge}
          <span class="crm-kanban-handle" draggable="true" aria-label="Mover"></span>
        </div>
        <div class="muted">${escapeHtml(propietario)}</div>
        <div class="muted">${escapeHtml(proxima)}</div>
      `;
      card.addEventListener("click", () => {
        if (inmuebleId) openInmuebleDetail(inmuebleId, "resumen");
      });
      const handle = card.querySelector(".crm-kanban-handle");
      if (handle) {
        handle.addEventListener("click", (event) => {
          event.preventDefault();
          event.stopPropagation();
        });
        handle.addEventListener("dragstart", (event) => {
          event.stopPropagation();
          crmInicioDragPayload = { captacionId, fromEtapa: stage, label: `${codePrefix} - ${direccion}` };
          try {
            event.dataTransfer?.setData?.("text/plain", captacionId);
          } catch (e) {}
        });
      }
      col.appendChild(card);
    });
    if (columnRows.length > maxCards) {
      const more = document.createElement("div");
      more.className = "muted";
      more.textContent = `… ${columnRows.length - maxCards} más`;
      col.appendChild(more);
    }
    crmInicioBoard.appendChild(col);
  });
};

let lastCrmInicioDashboardKey = "";
let lastCrmInicioDashboardPayload = null;

const renderCrmInicioInmoDashboard = ({ force = false } = {}) => {
  if (!crmInicioDashboardKpis || !crmInicioDashYear) return;
  const vertical = resolveCrmTecnocloudVertical();
  if (vertical !== "inmo") return;

  const workspaceId = String(state.currentWorkspaceId || "").trim();
  const empresa = resolveCrmInmoEmpresa();
  const empresaId = String(state.crmInmoEmpresaId || empresa?.id || "").trim();

  if (!crmInicioDashYear.options || crmInicioDashYear.options.length === 0) {
    const y = String(new Date().getFullYear());
    crmInicioDashYear.innerHTML = "";
    crmInicioDashYear.appendChild(createOption(y, y));
    crmInicioDashYear.value = y;
  }
  const desiredYear = String(crmInicioDashYear.value || "").trim() || String(new Date().getFullYear());
  const qs = new URLSearchParams();
  if (workspaceId) qs.set("workspace_id", workspaceId);
  else if (empresaId) qs.set("empresa_id", empresaId);
  qs.set("year", desiredYear);

  const cacheKey = `${workspaceId || empresaId}:${desiredYear}`;
  if (!force && cacheKey && cacheKey === lastCrmInicioDashboardKey && lastCrmInicioDashboardPayload) {
    return;
  }

  const ensureYearOptions = () => {
    const current = String(crmInicioDashYear.value || "").trim() || String(new Date().getFullYear());
    api("/api/years")
      .then((res) => {
        const years = (res?.years || [])
          .map((y) => String(y || "").trim())
          .filter((y) => /^\d{4}$/.test(y))
          .sort();
        const list = Array.from(new Set(years));
        const fallback = String(new Date().getFullYear());
        const finalYears = list.length ? list.slice(-10) : [fallback];
        crmInicioDashYear.innerHTML = "";
        finalYears.forEach((y) => crmInicioDashYear.appendChild(createOption(y, y)));
        crmInicioDashYear.value = finalYears.includes(current) ? current : finalYears[finalYears.length - 1];
      })
      .catch(() => {
        if (!String(crmInicioDashYear.value || "").trim()) {
          const y = String(new Date().getFullYear());
          crmInicioDashYear.innerHTML = "";
          crmInicioDashYear.appendChild(createOption(y, y));
          crmInicioDashYear.value = y;
        }
      });
  };

  if (crmInicioDashYear.dataset.bound !== "1") {
    crmInicioDashYear.dataset.bound = "1";
    ensureYearOptions();
    crmInicioDashYear.addEventListener("change", () => renderCrmInicioInmoDashboard({ force: true }));
  }

  crmInicioDashboardKpis.innerHTML = "<p class='muted'>Cargando dashboard…</p>";

  api(`/api/inmo_inicio_dashboard?${qs.toString()}`)
    .then((payload) => {
      lastCrmInicioDashboardKey = cacheKey;
      lastCrmInicioDashboardPayload = payload;

      const year = String(payload?.year || desiredYear || "").trim() || desiredYear;
      const kpis = payload?.kpis || {};
      const fmtPct = (value, digits = 1) => `${(Number(value || 0) * 100).toFixed(digits)}%`;
      const fmtRatio = (value, digits = 2) => Number(value || 0).toFixed(digits);

      const addKpi = ({ title, value, note }) => {
        const el = document.createElement("div");
        el.className = "card kpi-card";
        el.innerHTML = `
          <h3>${escapeHtml(title)}</h3>
          <div class="kpi-value">${escapeHtml(value)}</div>
          <div class="muted">${escapeHtml(note || "")}</div>
        `;
        crmInicioDashboardKpis.appendChild(el);
      };

      crmInicioDashboardKpis.innerHTML = "";
      addKpi({
        title: `Facturado ${year}`,
        value: euroFormatter.format(Number(kpis.facturado || 0)),
        note: `Comisión ganada: ventas ${euroFormatter.format(Number(kpis.facturado_ventas || 0))} · alquiler ${euroFormatter.format(Number(kpis.facturado_alquileres || 0))}`,
      });
      addKpi({
        title: `Gastos ${year}`,
        value: euroFormatter.format(Number(kpis.gastos || 0)),
        note: "Provisional (pendiente de cargador de facturas y nóminas).",
      });
      addKpi({
        title: `Rentabilidad ${year}`,
        value: euroFormatter.format(Number(kpis.rentabilidad || 0)),
        note: `Margen: ${fmtPct(kpis.margen, 1)}`,
      });
      addKpi({
        title: `Ventas ${year}`,
        value: numberFormatter.format(Number(kpis.ventas || 0)),
        note: "Operaciones de compraventa.",
      });
      addKpi({
        title: `Encargos ${year}`,
        value: numberFormatter.format(Number(kpis.encargos || 0)),
        note: `Ratio adq→enc: ${fmtPct(kpis.ratio_adquisicion_encargo, 1)}`,
      });
      addKpi({
        title: `Citas por propuesta ${year}`,
        value: fmtRatio(kpis.ratio_cita_propuesta, 2),
        note: `${numberFormatter.format(Number(kpis.citas_venta || 0))} citas (Agenda) · ${numberFormatter.format(Number(kpis.propuestas || 0))} propuestas`,
      });
      addKpi({
        title: `Tiempo venta ${year}`,
        value:
          Number(kpis.tiempo_venta_avg_dias || 0) > 0
            ? `${Number(kpis.tiempo_venta_avg_dias || 0).toFixed(1)} días`
            : "-",
        note:
          Number(kpis.tiempo_venta_median_dias || 0) > 0
            ? `Mediana: ${Number(kpis.tiempo_venta_median_dias || 0).toFixed(1)} días`
            : "Sin dato suficiente.",
      });
      addKpi({
        title: "Publicables",
        value: numberFormatter.format(Number(kpis.calidad_publicables || 0)),
        note: `${numberFormatter.format(Number(kpis.calidad_no_publicables || 0))} inmuebles con requisitos pendientes · ${numberFormatter.format(Number(kpis.portal_publicados || 0))} publicados`,
      });
      addKpi({
        title: "Alertas demanda-oferta",
        value: numberFormatter.format(Number(kpis.demandas_con_matches || 0)),
        note: "Demandas activas con inmuebles compatibles.",
      });

      const quality = payload?.quality || {};
      const qCounts = quality?.counts || {};
      const qIssues = Array.isArray(quality?.issues) ? quality.issues : [];
      const alerts = payload?.alerts || {};
      const demandaAlerts = Array.isArray(alerts?.demanda_oferta) ? alerts.demanda_oferta : [];
      const panel = document.createElement("div");
      panel.className = "card kpi-card";
      panel.style.gridColumn = "1 / -1";
      panel.innerHTML = `
        <h3>Calidad de cartera y alertas</h3>
        <div class="workspace-mini-kpis" style="margin-top:10px;">
          <div class="workspace-mini-kpi"><span>Sin foto</span><strong>${numberFormatter.format(Number(qCounts.sin_foto || 0))}</strong></div>
          <div class="workspace-mini-kpi"><span>Sin texto</span><strong>${numberFormatter.format(Number(qCounts.sin_texto || 0))}</strong></div>
          <div class="workspace-mini-kpi"><span>Sin precio</span><strong>${numberFormatter.format(Number(qCounts.sin_precio || 0))}</strong></div>
          <div class="workspace-mini-kpi"><span>Sin propietario</span><strong>${numberFormatter.format(Number(qCounts.sin_propietario || 0))}</strong></div>
          <div class="workspace-mini-kpi"><span>Sin documentación</span><strong>${numberFormatter.format(Number(qCounts.sin_documentacion || 0))}</strong></div>
        </div>
        <div class="workspace-central-layout" style="margin-top:12px;">
          <div>
            <strong>Inmuebles a completar</strong>
            ${
              qIssues.length
                ? `<div class="workspace-billing-list" style="margin-top:8px;">${qIssues
                    .slice(0, 6)
                    .map(
                      (row) => `
                        <div class="workspace-billing-row">
                          <div>
                            <strong>${escapeHtml(row.direccion || row.id || "Inmueble")}</strong>
                            <div class="muted">${escapeHtml((row.missing || []).join(" · ") || row.estado || "")}</div>
                          </div>
                          <button type="button" class="secondary ghost button-inline" data-dashboard-open-inmueble="${escapeHtml(row.id || "")}">Abrir</button>
                        </div>
                      `
                    )
                    .join("")}</div>`
                : "<p class='muted'>Sin incidencias de publicación.</p>"
            }
          </div>
          <div>
            <strong>Demandas con oferta compatible</strong>
            ${
              demandaAlerts.length
                ? `<div class="workspace-billing-list" style="margin-top:8px;">${demandaAlerts
                    .slice(0, 6)
                    .map((row) => {
                      const first = Array.isArray(row.matches) && row.matches.length ? row.matches[0] : {};
                      return `
                        <div class="workspace-billing-row">
                          <div>
                            <strong>${escapeHtml([row.tipo, row.zona].filter(Boolean).join(" · ") || row.demanda_id || "Demanda")}</strong>
                            <div class="muted">${escapeHtml(first.direccion || "")}${first.score ? ` · ${escapeHtml(String(first.score))}%` : ""}</div>
                          </div>
                          ${first.id ? `<button type="button" class="secondary ghost button-inline" data-dashboard-open-inmueble="${escapeHtml(first.id || "")}">Ver match</button>` : ""}
                        </div>
                      `;
                    })
                    .join("")}</div>`
                : "<p class='muted'>Sin alertas de cruce.</p>"
            }
          </div>
        </div>
      `;
      crmInicioDashboardKpis.appendChild(panel);
      panel.querySelectorAll("[data-dashboard-open-inmueble]").forEach((btn) => {
        btn.addEventListener("click", () => {
          const id = String(btn.dataset.dashboardOpenInmueble || "").trim();
          if (id) openInmuebleDetail(id, "dashboard");
        });
      });

      const series = payload?.series || {};

      const drawCanvasEmpty = (canvas, text = "Sin datos.") => {
        if (!canvas) return;
        const ctx = prepareCanvas(canvas);
        const width = canvas.getBoundingClientRect().width;
        const height = canvas.getBoundingClientRect().height;
        ctx.clearRect(0, 0, width, height);
        ctx.fillStyle = getCssVar(canvas, "--chart-bg", "rgba(255,255,255,0.92)");
        ctx.fillRect(0, 0, width, height);
        ctx.fillStyle = getCssVar(canvas, "--chart-muted", "rgba(11, 29, 51, 0.56)");
        ctx.font = `700 12px ${getCssVar(canvas, "--font-ui", "system-ui, sans-serif")}`;
        ctx.fillText(String(text || "Sin datos."), 16, 28);
      };

      const drawRespChart = (canvas, items, { label, color, format } = {}) => {
        if (!canvas) return;
        const rows = Array.isArray(items) ? items : [];
        if (!rows.length) {
          drawCanvasEmpty(canvas);
          return;
        }
        const labels = rows.map((r) => String(r?.responsable || "Sin responsable"));
        const values = rows.map((r) => Number(r?.total || 0) || 0);
        drawBarChart(
          canvas,
          labels,
          [
            {
              label: label || "",
              values,
              color: color || "#d7b04c",
              format: format || ((v) => numberFormatter.format(v)),
            },
          ],
          { legend: false, showValues: true }
        );
      };

      drawRespChart(crmInicioVentasResponsableChart, series.ventas_por_responsable, {
        label: "Ventas",
        color: "#cca33c",
        format: (v) => numberFormatter.format(v),
      });
      drawRespChart(crmInicioFacturadoResponsableChart, series.facturado_por_responsable, {
        label: "Facturado",
        color: "#d7b04c",
        format: (v) => euroFormatter.format(v),
      });
      drawRespChart(crmInicioEncargosResponsableChart, series.encargos_por_responsable, {
        label: "Encargos",
        color: "#334155",
        format: (v) => numberFormatter.format(v),
      });

      if (crmInicioTiempoVentaChart) {
        const rows = Array.isArray(series.tiempo_venta_por_anio) ? series.tiempo_venta_por_anio : [];
        if (!rows.length) {
          drawCanvasEmpty(crmInicioTiempoVentaChart);
        } else {
          const labels = rows.map((r) => String(r?.year || ""));
          const avg = rows.map((r) => Number(r?.avg_dias || 0) || 0);
          const med = rows.map((r) => Number(r?.median_dias || 0) || 0);
          drawBarChart(
            crmInicioTiempoVentaChart,
            labels,
            [
              { label: "Media (días)", values: avg, color: "#cca33c", format: (v) => `${Number(v || 0).toFixed(0)}d` },
              { label: "Mediana (días)", values: med, color: "#334155", format: (v) => `${Number(v || 0).toFixed(0)}d` },
            ],
            { legend: true, showValues: false }
          );
        }
      }
    })
    .catch(() => {
      crmInicioDashboardKpis.innerHTML = "<p class='muted'>No se pudo cargar el dashboard.</p>";
    });
};

const renderCrmResumenDashboard = () => {
  const captaciones = Array.isArray(cachedCrmCaptaciones) ? cachedCrmCaptaciones : [];
  const inmuebles = Array.isArray(cachedCrmInmuebles) ? cachedCrmInmuebles : [];
  const compraventas = Array.isArray(cachedCrmCompraventas) ? cachedCrmCompraventas : [];
  const visitas = Array.isArray(cachedCrmVisitas) ? cachedCrmVisitas : [];
  const demandas = Array.isArray(cachedCrmDemandas) ? cachedCrmDemandas : [];
  const alquileres = Array.isArray(cachedCrmAlquileres) ? cachedCrmAlquileres : [];

  hydrateCrmResumenFilters();

  const normalizeStageLabel = (raw) => {
    return normalizeCrmMainEtapa(String(raw || "").trim());
  };

  const isClosedStage = (raw) => {
    const key = normalizeSimple(raw || "");
    return key === "vendido" || key === "cerrado negativamente";
  };

  // Fuente de verdad visual: inmuebles (estado). Captaciones solo aporta "siguiente paso" y señales legacy.
  const captacionByInmueble = new Map();
  captaciones.forEach((row) => {
    const inmuebleId = String(row?.inmueble_id || "").trim();
    if (!inmuebleId) return;
    const prev = captacionByInmueble.get(inmuebleId);
    if (!prev) {
      captacionByInmueble.set(inmuebleId, row);
      return;
    }
    const prevTs = parseCrmDateTime(prev.updated_at || prev.created_at || "", "");
    const nextTs = parseCrmDateTime(row.updated_at || row.created_at || "", "");
    if ((nextTs || 0) >= (prevTs || 0)) {
      captacionByInmueble.set(inmuebleId, row);
    }
  });

  const pipelineItems = inmuebles
    .map((row) => {
      const inmuebleId = String(row?.id || "").trim();
      const cap = inmuebleId ? (captacionByInmueble.get(inmuebleId) || {}) : {};
      const stage = normalizeStageLabel(row?.estado || cap?.etapa || "Inmueble");
      const proxima = String(cap?.proxima_accion || "").trim();
      const verificada = String(cap?.noticia_verificada ?? "").trim() === "1";
      const propietario = String(cap?.propietario || "").trim();
      return {
        ...row,
        inmueble_id: inmuebleId,
        captacion_id: String(cap?.id || "").trim(),
        stage,
        proxima_accion: proxima,
        noticia_verificada: verificada,
        propietario,
      };
    })
    .filter((row) => row && String(row.inmueble_id || "").trim());
  const stageCount = (name) => pipelineItems.filter((row) => row.stage === name).length;
  const activePipelineItems = pipelineItems.filter((row) => !isClosedStage(row.stage));

  // Oportunidades (Tecnocloud-like): web/agencias y notificaciones en el menú superior.
  const clientesRows = Array.isArray(cachedCrmClientes) ? cachedCrmClientes : [];
  const demandasRows = Array.isArray(cachedCrmDemandas) ? cachedCrmDemandas : [];
  const captacionesRows = Array.isArray(cachedCrmCaptaciones) ? cachedCrmCaptaciones : [];

  const clientesWebCount = clientesRows.filter((row) => String(row?.cliente_generico_web || "").trim() === "1").length;
  const pedidosNuevosCount = demandasRows.filter((row) => isDateWithinLastDays(row?.created_at || row?.updated_at || "", 5)).length;
  const pedidosWebCount = demandasRows.filter((row) => {
    const pedidoWeb = String(row?.pedido_web || "").trim() === "1";
    const origen = normalizeSimple(row?.origen || "");
    return pedidoWeb || origen.includes("web");
  }).length;
  const pedidosAgenciasCount = demandasRows.filter((row) => String(row?.agencia_insercion || "").trim()).length;
  const noticiasWebCount = captacionesRows.filter((row) => {
    const etapa = normalizeCrmMainEtapa(String(row?.etapa || "").trim());
    if (etapa !== "Noticia") return false;
    const canal = normalizeSimple(row?.canal || "");
    return canal.includes("web");
  }).length;
  const noticiasSinVerificarCount = activePipelineItems.filter((row) => row.stage === "Noticia" && !row.noticia_verificada).length;

  const setBadge = (el, count) => {
    if (!el) return;
    const n = Number(count || 0) || 0;
    el.textContent = n > 99 ? "99+" : String(n);
    el.classList.toggle("hidden", n <= 0);
  };
	  setBadge(crmBadgePedidos, pedidosNuevosCount || pedidosWebCount || pedidosAgenciasCount);
	  setBadge(crmBadgeNoticias, noticiasSinVerificarCount || noticiasWebCount);

  if (crmHomeOportunidades) {
    const items = [
      pedidosNuevosCount
        ? { title: "Pedidos nuevos (5 días)", summary: `${pedidosNuevosCount} por revisar.`, crmQuick: "demandas:activa" }
        : null,
	      pedidosWebCount
	        ? { title: "Pedidos web", summary: `${pedidosWebCount} recibidos.`, crmQuick: "demandas:web" }
	        : null,
	      pedidosAgenciasCount
	        ? { title: "Pedidos de agencias", summary: `${pedidosAgenciasCount} compartidos.`, crmQuick: "demandas:agencias" }
	        : null,
	      clientesWebCount
	        ? { title: "Clientes web genérico", summary: `${clientesWebCount} sin cualificar.`, crmQuick: "clientes:web" }
	        : null,
	      noticiasWebCount
	        ? { title: "Noticias web", summary: `${noticiasWebCount} en captación.`, crmView: "captaciones", etapa: "Noticia" }
	        : null,
    ].filter(Boolean);
    renderCrmActionList(crmHomeOportunidades, items, "Sin oportunidades nuevas.");
  }

  // Alertas (Tecnocloud-like).
  try {
    const snapshot = collectCrmAlertsSnapshot();
    updateCrmAlertsBadge(snapshot);
  } catch (e) {}

  renderCrmHomeAgendaPreview();

  if (crmInicioBoard) {
    renderCrmInicioBoard(pipelineItems);
  }

  if (crmResumenDireccionKpis || crmResumenTopDesviacion || crmResumenTopPlazo) {
    const responsables = new Set();
    const origenes = new Set();
    compraventas.forEach((row) => {
      const resp = String(row.responsable_gestion || "").trim();
      const org = String(row.origen_inmueble || row.origen || "").trim();
      if (resp) responsables.add(resp);
      if (org) origenes.add(org);
    });
    const sortEs = (a, b) => String(a).localeCompare(String(b), "es", { sensitivity: "base" });
    if (crmResumenResponsable) {
      const current = String(state.crmResumenResponsable || "");
      crmResumenResponsable.innerHTML = `<option value="">Todos</option>${
        Array.from(responsables).sort(sortEs).map((v) => `<option value="${escapeHtml(v)}">${escapeHtml(v)}</option>`).join("")
      }`;
      if (current) crmResumenResponsable.value = current;
    }
    if (crmResumenOrigen) {
      const current = String(state.crmResumenOrigen || "");
      crmResumenOrigen.innerHTML = `<option value="">Todos</option>${
        Array.from(origenes).sort(sortEs).map((v) => `<option value="${escapeHtml(v)}">${escapeHtml(v)}</option>`).join("")
      }`;
      if (current) crmResumenOrigen.value = current;
    }

    const { fromTs, toTs } = getCrmResumenWindowTs();
    const responsableFilter = normalizeSimple(state.crmResumenResponsable || "");
    const origenFilter = normalizeSimple(state.crmResumenOrigen || "");
    const matchesFilters = (row) => {
      if (responsableFilter && !normalizeSimple(row.responsable_gestion || "").includes(responsableFilter)) return false;
      if (origenFilter && !normalizeSimple(row.origen_inmueble || row.origen || "").includes(origenFilter)) return false;
      const ts = getCrmVentaOperacionTs(row);
      if (!ts && (fromTs || toTs !== Number.MAX_SAFE_INTEGER)) return false;
      if (ts && (ts < fromTs || ts > toTs)) return false;
      return true;
    };

    const visitasByInmueble = new Map();
    visitas.forEach((v) => {
      const inmuebleId = String(v.inmueble_id || "").trim();
      if (!inmuebleId) return;
      visitasByInmueble.set(inmuebleId, (Number(visitasByInmueble.get(inmuebleId) || 0) || 0) + 1);
    });

    const ventas = compraventas.filter(matchesFilters);
    const cerradas = ventas.filter((row) => String(row.fecha_escritura || "").trim() || Number(row.precio_escritura || 0) > 0);
    const honorariosTotal = cerradas.reduce((sum, row) => sum + (Number(row.honorarios || 0) || 0), 0);
    const volumenCierre = cerradas.reduce((sum, row) => sum + (Number(row.precio_escritura || row.precio_venta || 0) || 0), 0);
    const desviaciones = cerradas.map((row) => computeVentaDeviation(row)).filter((d) => d.ok && Number.isFinite(d.pct));
    const desvPctAvg = desviaciones.length ? (desviaciones.reduce((sum, d) => sum + (Number(d.pct || 0) || 0), 0) / desviaciones.length) : 0;
    const desvEurAvg = desviaciones.length ? (desviaciones.reduce((sum, d) => sum + (Number(d.eur || 0) || 0), 0) / desviaciones.length) : 0;
    const dias = cerradas.map((row) => computeVentaDias(row)).filter((n) => Number(n || 0) > 0);
    const diasAvg = dias.length ? (dias.reduce((a, b) => a + b, 0) / dias.length) : 0;
    const visitasVenta = cerradas.map((row) => computeVentaVisitas(row, visitasByInmueble)).filter((n) => Number(n || 0) > 0);
    const visitasAvg = visitasVenta.length ? (visitasVenta.reduce((a, b) => a + b, 0) / visitasVenta.length) : 0;
    const ticketMedio = cerradas.length ? (volumenCierre / cerradas.length) : 0;
    const honorariosMedio = cerradas.length ? (honorariosTotal / cerradas.length) : 0;

    if (crmResumenDireccionKpis) {
      renderCrmMiniCards(crmResumenDireccionKpis, [
        {
          title: "Comisión ganada",
          value: formatEuros(honorariosTotal),
          meta: `${cerradas.length} ventas`,
          summary: "Suma de honorarios en operaciones cerradas dentro del periodo.",
          crmView: "compraventas",
        },
        {
          title: "Ticket medio escritura",
          value: formatEuros(ticketMedio),
          meta: "Precio",
          summary: "Precio medio de cierre (escritura o venta) en el periodo.",
          crmView: "compraventas",
        },
        {
          title: "Desviación media",
          value: `${desvPctAvg ? desvPctAvg.toFixed(1) : "0.0"}%`,
          meta: formatEuros(desvEurAvg),
          summary: "Media de (venta - encargo). Negativo indica cierre por debajo de salida.",
          crmView: "compraventas",
        },
        {
          title: "Plazo medio venta",
          value: `${diasAvg ? Math.round(diasAvg) : 0} días`,
          meta: "Encargo → cierre",
          summary: "Tiempo medio desde fecha de encargo hasta escritura/contrato cuando hay datos.",
          crmView: "compraventas",
        },
        {
          title: "Visitas por venta",
          value: `${visitasAvg ? visitasAvg.toFixed(1) : "0.0"}`,
          meta: "Media",
          summary: "Promedio de visitas registradas por operación cerrada.",
          crmView: "visitas",
        },
        {
          title: "Comisión media",
          value: formatEuros(honorariosMedio),
          meta: "Por venta",
          summary: "Honorarios medios por operación cerrada en el periodo.",
          crmView: "compraventas",
        },
      ]);
    }

    const topDesv = cerradas
      .map((row) => ({ row, d: computeVentaDeviation(row) }))
      .filter((item) => item.d.ok)
      .sort((a, b) => Math.abs(b.d.pct) - Math.abs(a.d.pct))
      .slice(0, 6)
      .map((item) => ({
        inmuebleId: item.row.inmueble_id || "",
        crmView: "compraventas",
        title: item.row.direccion || "Operación",
        meta: `${item.row.responsable_gestion || "Responsable"} · ${item.row.origen_inmueble || item.row.origen || "Origen"}`,
        summary: `Encargo ${formatEuros(item.d.salida || 0)} → Venta ${formatEuros(item.d.venta || 0)} · ${item.d.pct.toFixed(1)}% (${formatEuros(item.d.eur || 0)})`,
      }));
    renderCrmActionList(crmResumenTopDesviacion, topDesv, "Sin ventas con precios de encargo/venta suficientes.");

    const topPlazo = cerradas
      .map((row) => ({
        row,
        dias: computeVentaDias(row),
        visitas: computeVentaVisitas(row, visitasByInmueble),
      }))
      .sort((a, b) => (b.dias - a.dias) || (b.visitas - a.visitas))
      .slice(0, 6)
      .map((item) => ({
        inmuebleId: item.row.inmueble_id || "",
        crmView: "compraventas",
        title: item.row.direccion || "Operación",
        meta: `${item.row.responsable_gestion || "Responsable"} · ${item.row.fecha_escritura || item.row.fecha_contrato || "-"}`,
        summary: `${item.dias ? `${item.dias} días` : "Plazo pendiente"} · ${item.visitas ? `${item.visitas} visitas` : "Visitas n/d"} · ${formatEuros(Number(item.row.honorarios || 0) || 0)}`,
      }));
    renderCrmActionList(crmResumenTopPlazo, topPlazo, "Sin ventas cerradas en el periodo.");
  }

  if (crmResumenPulse) {
    renderCrmMiniCards(crmResumenPulse, [
      {
        title: "Noticias vivas",
        value: stageCount("Noticia"),
        meta: "Noticia",
        summary: "Oportunidades activas pendientes de cualificación o siguientes pasos.",
        crmView: "captaciones",
        etapa: "Noticia",
      },
      {
        title: "Encargos",
        value: stageCount("Encargo"),
        meta: "Encargo",
        summary: "Comercialización activa: anuncio, documentación, visitas y negociación.",
        crmView: "captaciones",
        etapa: "Encargo",
      },
      {
        title: "Pedidos",
        value: demandas.filter((row) => normalizeSimple(row.estado || "") === "activa").length,
        meta: "Compradores",
        summary: "Pedidos activos para matching o visita.",
        crmView: "demandas",
      },
    ]);
  }

  if (crmInicioNoticias || crmInicioEncargos || crmInicioPedidos || crmInicioInmuebles) {
    const activeStages = new Set(["Inmueble", "Noticia", "Encargo", "Propuesta", "Reservado", "Contrato de arras"]);
    const missingNext = activePipelineItems.filter((row) => activeStages.has(String(row.stage || "")) && !String(row.proxima_accion || "").trim()).length;
    const missingCatastro = activePipelineItems.filter((row) => !String(row.referencia_catastral || "").trim()).length;
    const missingOwner = activePipelineItems.filter((row) => !String(row.propietarios || "").trim()).length;
    const noticiasVivas = stageCount("Noticia");
    const noticiasSinVerificar = activePipelineItems.filter((row) => String(row.stage || "") === "Noticia" && !row.noticia_verificada).length;

    const activeEncargos = stageCount("Encargo");
    const pendingPropuestas = stageCount("Propuesta");
    const pendingArras = stageCount("Contrato de arras");
    const encargosSinAccion = activePipelineItems.filter((row) => String(row.stage || "") === "Encargo" && !String(row.proxima_accion || "").trim()).length;

    const demandasActivas = demandas.filter((row) => normalizeSimple(row.estado || "") === "activa").length;
    const pendingVisits = visitas.filter((row) => normalizeSimple(row.estado || "").includes("pendiente")).length;
    const urgentDemandas = demandas.filter((row) => normalizeSimple(row.prioridad || "") === "alta" && normalizeSimple(row.estado || "") === "activa").length;

    if (crmInicioNoticias) {
      renderCrmActionList(
        crmInicioNoticias,
        [
          {
            title: "Noticias vivas",
            summary: `${noticiasVivas} oportunidades en fase Noticia.`,
            crmView: "captaciones",
            etapa: "Noticia",
          },
          {
            title: "Noticias sin verificar",
            summary: `${noticiasSinVerificar} noticias pendientes de verificar.`,
            crmQuick: "captaciones:quick_noticia_sin_verificar",
          },
          {
            title: "Pipeline sin próxima acción",
            summary: `${missingNext} inmuebles sin siguiente paso definido.`,
            crmQuick: "captaciones:quick_sin_proxima_accion",
          },
        ],
        "Sin foco de noticias."
      );
    }

    if (crmInicioEncargos) {
      renderCrmActionList(
        crmInicioEncargos,
        [
          {
            title: "Encargos activos",
            summary: `${activeEncargos} expedientes en comercialización activa.`,
            crmView: "captaciones",
            etapa: "Encargo",
          },
          {
            title: "Encargos sin siguiente acción",
            summary: `${encargosSinAccion} encargos sin próximo hito definido.`,
            crmView: "captaciones",
            etapa: "Encargo",
          },
          {
            title: "Propuestas pendientes",
            summary: `${pendingPropuestas} propuestas/ofertas a la espera de aceptación.`,
            crmView: "captaciones",
            etapa: "Propuesta",
          },
          {
            title: "Arras pendientes",
            summary: `${pendingArras} expedientes en fase de arras.`,
            crmView: "captaciones",
            etapa: "Contrato de arras",
          },
        ],
        "Sin foco de encargos."
      );
    }

    if (crmInicioPedidos) {
      renderCrmActionList(
        crmInicioPedidos,
        [
          {
            title: "Demandas activas",
            summary: `${demandasActivas} compradores en seguimiento.`,
            crmQuick: "demandas:activa",
          },
          {
            title: "Demandas urgentes",
            summary: `${urgentDemandas} compradores de prioridad alta.`,
            crmView: "demandas",
          },
          {
            title: "Visitas pendientes",
            summary: `${pendingVisits} visitas por cerrar resultado.`,
            crmQuick: "visitas:pendiente",
          },
          {
            title: "Act./Citas pendientes",
            summary: "Acciones y citas pendientes de cierre.",
            crmQuick: "agenda:Pendiente",
          },
        ],
        "Sin foco de pedidos."
      );
    }

    if (crmInicioInmuebles) {
      renderCrmActionList(
        crmInicioInmuebles,
        [
          {
            title: "Catastro pendiente",
            summary: `${missingCatastro} inmuebles sin referencia catastral.`,
            crmView: "inmuebles",
          },
          {
            title: "Propietario por revisar",
            summary: `${missingOwner} inmuebles sin propietario enlazado.`,
            crmView: "inmuebles",
          },
          {
            title: "Pisos vacíos",
            summary: "Abrir búsqueda rápida de inmuebles vacíos.",
            crmQuick: "captaciones:quick_pisos_vacios",
          },
          {
            title: "Alquilados (inquilinos)",
            summary: "Abrir búsqueda rápida de inmuebles alquilados.",
            crmQuick: "captaciones:quick_alquilados",
          },
        ],
        "Sin foco de inmuebles."
      );
    }
  }

  if (crmResumenHoy) {
    const jobs = [
      ...pipelineItems
        .filter((row) => !isClosedStage(row.stage))
        .map((row) => {
        const etapa = String(row.stage || "Inmueble").trim();
        const proxima = String(row.proxima_accion || "").trim();
        const verificada = !!row.noticia_verificada;
        let priority = 0;
        let summary = proxima || "Sin próxima acción";
        if (!proxima) priority += 4;
        if (etapa === "Inmueble") {
          priority += 4;
          summary = proxima || "Completar ficha y cualificar (pasar a Noticia).";
        } else if (etapa === "Noticia") {
          priority += 4;
          if (!verificada) {
            priority += 3;
            summary = proxima ? `${proxima} · Noticia sin verificar` : "Noticia sin verificar: llamada/cita pendiente.";
          } else if (!proxima) {
            summary = "Llamada pendiente o noticia sin siguiente acción.";
          }
        } else if (etapa === "Encargo") {
          priority += 2;
          summary = proxima || "Encargo activo sin siguiente hito definido.";
        } else if (etapa === "Propuesta") {
          priority += 2;
          summary = proxima || "Propuesta/oferta pendiente de respuesta.";
        } else if (etapa === "Reservado") {
          priority += 1;
          summary = proxima || "Reserva lista para arras o siguiente paso documental.";
        } else if (etapa === "Contrato de arras") {
          priority += 1;
          summary = proxima || "Arras firmadas: preparar pre-escritura y agenda.";
        }
        const ownerLabel = String(row.propietario || row.propietarios || "").trim();
        return {
          inmuebleId: row.inmueble_id || row.id || "",
          title: row.direccion || "Inmueble sin dirección",
          meta: `${ownerLabel || "Propietario pendiente"} · ${etapa}`,
          summary,
          priority,
          crmView: "captaciones",
          etapa,
        };
      }),
      ...visitas
        .filter((row) => normalizeSimple(row.estado || "").includes("pendiente"))
        .map((row) => ({
          inmuebleId: row.inmueble_id || "",
          title: row.inmueble || "Visita pendiente",
          meta: `${row.cliente || "Cliente pendiente"} · Visita`,
          summary: `${row.fecha || "-"} ${row.hora || ""}`.trim() || "Pendiente de agenda",
          priority: 5,
        })),
      ...demandas
        .filter((row) => normalizeSimple(row.estado || "") === "activa" && normalizeSimple(row.prioridad || "") === "alta")
        .map((row) => ({
          crmView: "demandas",
          title: row.cliente || "Demanda prioritaria",
          meta: `${row.tipo || "Tipo pendiente"}`,
          summary: "Revisar matching, visita o redefinir la búsqueda.",
          priority: 3,
        })),
    ]
      .sort((a, b) => b.priority - a.priority || a.title.localeCompare(b.title, "es"))
      .slice(0, 6);
    renderCrmActionList(crmResumenHoy, jobs, "Sin trabajo pendiente visible.");
  }

  if (crmResumenAlertas) {
    const activeStages = new Set(["Inmueble", "Noticia", "Encargo", "Propuesta", "Reservado", "Contrato de arras"]);
    const missingNext = activePipelineItems.filter((row) => activeStages.has(String(row.stage || "")) && !String(row.proxima_accion || "").trim()).length;
    const missingCatastro = activePipelineItems.filter((row) => !String(row.referencia_catastral || "").trim()).length;
    const missingOwner = activePipelineItems.filter((row) => !String(row.propietarios || "").trim()).length;
    const activeEncargos = stageCount("Encargo");
    const pendingPropuestas = stageCount("Propuesta");
    const pendingReservas = stageCount("Reservado");
    const pendingArras = stageCount("Contrato de arras");
    const pendingVisits = visitas.filter((row) => normalizeSimple(row.estado || "").includes("pendiente")).length;
    const urgentDemandas = demandas.filter((row) => normalizeSimple(row.prioridad || "") === "alta" && normalizeSimple(row.estado || "") === "activa").length;
    const alerts = [
      {
        title: "Pipeline sin siguiente acción",
        summary: `${missingNext} inmuebles sin siguiente paso definido.`,
        crmView: "captaciones",
      },
      {
        title: "Catastro pendiente",
        summary: `${missingCatastro} inmuebles sin referencia catastral.`,
        crmView: "inmuebles",
      },
      {
        title: "Propietario por revisar",
        summary: `${missingOwner} inmuebles sin propietario enlazado correctamente.`,
        crmView: "inmuebles",
      },
      {
        title: "Encargos activos",
        summary: `${activeEncargos} expedientes en comercialización activa.`,
        crmView: "captaciones",
        etapa: "Encargo",
      },
      {
        title: "Propuestas pendientes",
        summary: `${pendingPropuestas} propuestas/ofertas a la espera de aceptación.`,
        crmView: "captaciones",
        etapa: "Propuesta",
      },
      {
        title: "Reservas pendientes",
        summary: `${pendingReservas} reservas pendientes de arras o siguiente hito.`,
        crmView: "captaciones",
        etapa: "Reservado",
      },
      {
        title: "Arras pendientes de escritura",
        summary: `${pendingArras} expedientes en fase de arras.`,
        crmView: "captaciones",
        etapa: "Contrato de arras",
      },
      {
        title: "Visitas por cerrar",
        summary: `${pendingVisits} citas todavía sin resultado comercial.`,
        crmView: "visitas",
      },
      {
        title: "Demandas urgentes",
        summary: `${urgentDemandas} compradores de prioridad alta en seguimiento.`,
        crmView: "demandas",
      },
    ];
    renderCrmActionList(crmResumenAlertas, alerts, "Sin alertas activas.");
  }

  // Home Tecnocloud-like: paneles de gestión (sin duplicar el dashboard general).
  if (crmHomePanelNoticias || crmHomePanelEncargos || crmHomePanelPedidos || crmHomePanelObjetivos) {
    const stageLabel = (row) => normalizeStageLabel(row?.stage || row?.etapa || row?.estado || "");
    const isNoticia = (row) => stageLabel(row) === "Noticia";
    const isEncargo = (row) => stageLabel(row) === "Encargo";
    const isPropuesta = (row) => stageLabel(row) === "Propuesta";

    const noticias = activePipelineItems.filter(isNoticia);
    const noticiasSinVerificar = noticias.filter((row) => !row.noticia_verificada).length;
    const noticiasSinProxima = noticias.filter((row) => !String(row.proxima_accion || "").trim()).length;
    const noticiasValoradas = noticias.filter((row) => {
      const valor = Number(row.precio_valoracion || 0);
      const desvi = Number(row.desviacion_pct || 0);
      return (Number.isFinite(valor) && valor > 0) || (Number.isFinite(desvi) && desvi > 0 && desvi <= 10);
    }).length;

    const encargos = activePipelineItems.filter((row) => isEncargo(row) || isPropuesta(row));
    const encargosActivos = encargos.filter(isEncargo).length;
    const propuestasPendientes = encargos.filter(isPropuesta).length;
    const encargosSinProxima = encargos.filter((row) => !String(row.proxima_accion || "").trim()).length;

    const pendingVisits = visitas.filter((row) => normalizeSimple(row.estado || "").includes("pendiente")).length;
    const demandasActivas = demandas.filter((row) => normalizeSimple(row.estado || "") === "activa").length;
    const urgentDemandas = demandas.filter((row) => normalizeSimple(row.prioridad || "") === "alta" && normalizeSimple(row.estado || "") === "activa").length;

    if (crmHomePanelNoticias) {
      renderCrmActionList(
        crmHomePanelNoticias,
        [
          { title: "Noticias sin verificar", summary: `${noticiasSinVerificar} pendientes.`, crmQuick: "captaciones:quick_noticia_sin_verificar" },
          { title: "Noticias valoradas / <10%", summary: `${noticiasValoradas} con valoración o desviación baja.`, crmView: "captaciones", etapa: "Noticia" },
          { title: "Sin próxima acción", summary: `${noticiasSinProxima} sin siguiente paso.`, crmQuick: "captaciones:quick_sin_proxima_accion" },
        ],
        "Sin noticias pendientes."
      );
    }

    if (crmHomePanelEncargos) {
      renderCrmActionList(
        crmHomePanelEncargos,
        [
          { title: "Encargos activos", summary: `${encargosActivos} en comercialización.`, crmView: "captaciones", etapa: "Encargo" },
          { title: "Propuestas pendientes", summary: `${propuestasPendientes} a la espera.`, crmView: "captaciones", etapa: "Propuesta" },
          { title: "Sin próxima acción", summary: `${encargosSinProxima} sin siguiente hito.`, crmQuick: "captaciones:quick_sin_proxima_accion" },
        ],
        "Sin encargos/propuestas pendientes."
      );
    }

    if (crmHomePanelPedidos) {
      renderCrmActionList(
        crmHomePanelPedidos,
        [
          { title: "Demandas activas", summary: `${demandasActivas} compradores.`, crmView: "demandas", crmQuick: "demandas:activa" },
          { title: "Demandas urgentes", summary: `${urgentDemandas} prioridad alta.`, crmView: "demandas" },
          { title: "Visitas por cerrar", summary: `${pendingVisits} pendientes de resultado.`, crmQuick: "visitas:pendiente" },
        ],
        "Sin foco de pedidos."
      );
    }

    if (crmHomePanelObjetivos) {
      renderCrmActionList(
        crmHomePanelObjetivos,
        [
          { title: "Dashboard", summary: "KPIs y embudo comercial.", crmView: "dashboard" },
          { title: "Objetivos", summary: "Revisar metas por asesor/agencia.", crmView: "dashboard" },
        ],
        "Sin objetivos configurados."
      );
    }
  }

  if (crmResumenActividad) {
    const recentItems = [];
    visitas.forEach((row) => {
      recentItems.push({
        title: row.inmueble || "Visita",
        meta: `Visita · ${row.fecha || "-"} ${row.hora || ""}`.trim(),
        badge: row.estado || "Pendiente",
        ts: parseCrmDateTime(row.fecha, row.hora),
      });
    });
    compraventas.forEach((row) => {
      recentItems.push({
        title: row.direccion || "Compraventa",
        meta: `Venta · ${row.fecha_escritura || row.fecha_contrato || "-"}`,
        badge: row.estado || "Manual",
        ts: parseCrmDateTime(row.fecha_escritura || row.fecha_contrato, ""),
      });
    });
    alquileres.forEach((row) => {
      recentItems.push({
        title: row.direccion || row.inmueble || "Alquiler",
        meta: `Alquiler · ${row.fecha_contrato || row.fecha_inicio || "-"}`,
        badge: row.estado || row.situacion || "Activo",
        ts: parseCrmDateTime(row.fecha_contrato || row.fecha_inicio, ""),
      });
    });
    const sorted = recentItems.sort((a, b) => (b.ts || 0) - (a.ts || 0)).slice(0, 6);
    crmResumenActividad.innerHTML = sorted.length
      ? sorted
          .map(
            (item) => `
              <div class="crm-recent-item">
                <div>
                  <strong>${escapeHtml(item.title)}</strong>
                  <div class="muted">${escapeHtml(item.meta)}</div>
                </div>
                <span class="crm-badge">${escapeHtml(item.badge)}</span>
              </div>
            `
          )
          .join("")
      : "<p class='muted'>Sin actividad reciente.</p>";
  }

  if (crmResumenInmuebles) {
    const hot = activePipelineItems
      .map((row) => {
        const reasons = [];
        if (!String(row.referencia_catastral || "").trim()) reasons.push("Catastro pendiente");
        if (!String(row.propietarios || "").trim()) reasons.push("Propietario pendiente");
        const stage = normalizeStageLabel(row.stage || row.estado || "Inmueble");
        if (stage === "Inmueble") reasons.push("En entrada (sin cualificar)");
        else if (stage === "Noticia") reasons.push("Noticia: cualificar y siguiente acción");
        else if (stage === "Propuesta") reasons.push("Propuesta pendiente");
        else if (stage === "Vendido") reasons.push("Post-aceptación: contrato / notaría");
        const proxima = String(row.proxima_accion || "").trim();
        if (!proxima) reasons.push("Sin próxima acción");
        let score = reasons.length;
        if (stage === "Inmueble") score += 2;
        if (stage === "Propuesta") score += 2;
        if (stage === "Vendido") score += 1;
        return {
          id: row.id || "",
          title: row.direccion || "Sin dirección",
          meta: [row.stage || row.estado, row.poblacion].filter(Boolean).join(" · ") || "Ubicación pendiente",
          summary: proxima || reasons[0] || "Ficha activa",
          score,
        };
      })
      .sort((a, b) => b.score - a.score || a.title.localeCompare(b.title, "es"))
      .slice(0, 6);
    crmResumenInmuebles.innerHTML = hot.length
      ? hot
          .map(
            (item) => `
              <button type="button" class="crm-recent-item crm-resumen-card" data-inmueble-id="${escapeHtml(item.id)}">
                <div>
                  <strong>${escapeHtml(item.title)}</strong>
                  <div class="muted">${escapeHtml(item.meta)}</div>
                  <div class="muted">${escapeHtml(item.summary)}</div>
                </div>
              </button>
            `
          )
          .join("")
      : "<p class='muted'>Sin inmuebles prioritarios.</p>";
    crmResumenInmuebles.querySelectorAll("[data-inmueble-id]").forEach((btn) => {
      btn.addEventListener("click", () => {
        const id = btn.dataset.inmuebleId || "";
        if (id) openInmuebleDetail(id, "resumen");
      });
    });
  }

  renderCrmResumenYtdBoard().catch(() => {});
};

const buildInmuebleEncargoConditionsDefaults = (row = {}) => {
  const today = new Date().toISOString().slice(0, 10);
  return {
    fecha_encargo: row.fecha_encargo || today,
    precio_encargo: row.precio_encargo || row.precio_pedido_cliente || row.precio_objetivo || "",
    honorarios: row.honorarios || "",
    planificacion_encargo: row.planificacion_encargo || row.duracion_encargo_meses || "6",
  };
};

const openInmuebleEncargoConditionsModal = (row = {}, opts = {}) =>
  new Promise((resolve) => {
    let modal = document.getElementById("inmoEncargoConditionsModal");
    if (!modal) {
      modal = document.createElement("div");
      modal.id = "inmoEncargoConditionsModal";
      modal.className = "modal hidden";
      modal.innerHTML = `
        <div class="modal-content" style="max-width: 680px;">
          <div class="modal-header">
            <div>
              <h3>Condiciones del encargo</h3>
              <p class="muted" style="margin:0;">Define las condiciones antes de pasar la noticia a encargo.</p>
            </div>
            <button type="button" class="ghost" data-encargo-x>Cerrar</button>
          </div>
          <form class="modal-body form-grid" data-encargo-form>
            <label>
              Fecha encargo
              <input name="fecha_encargo" type="date" />
            </label>
            <label>
              Duración (meses)
              <input name="planificacion_encargo" type="number" step="1" min="0" inputmode="numeric" />
            </label>
            <label>
              Precio encargo
              <input name="precio_encargo" type="number" step="0.01" inputmode="decimal" />
            </label>
            <label>
              Honorarios agencia
              <input name="honorarios" type="number" step="0.01" inputmode="decimal" />
            </label>
            <label class="span-2">
              Próxima acción
              <input name="proxima_accion" placeholder="Ej. Preparar hoja de encargo / publicar anuncio" />
            </label>
            <div class="modal-actions">
              <span class="muted" data-encargo-status></span>
              <button type="button" class="secondary" data-encargo-cancel>Cancelar</button>
              <button type="submit">Guardar y pasar a Encargo</button>
            </div>
          </form>
        </div>
      `;
      document.body.appendChild(modal);
    }

    const defaults = buildInmuebleEncargoConditionsDefaults(row);
    const form = modal.querySelector("[data-encargo-form]");
    const statusEl = modal.querySelector("[data-encargo-status]");
    const xBtn = modal.querySelector("[data-encargo-x]");
    const cancelBtn = modal.querySelector("[data-encargo-cancel]");
    if (statusEl) statusEl.textContent = opts?.statusText || "";
    if (form) {
      form.reset();
      Object.entries(defaults).forEach(([key, value]) => {
        const input = form.querySelector(`[name="${key}"]`);
        if (input) input.value = value ?? "";
      });
      const proximaInput = form.querySelector('[name="proxima_accion"]');
      if (proximaInput) proximaInput.value = row.proxima_accion || "Preparar hoja de encargo";
    }

    let resolved = false;
    const cleanup = (value) => {
      if (resolved) return;
      resolved = true;
      modal.classList.add("hidden");
      modal.classList.remove("open");
      document.body.classList.remove("modal-open");
      resolve(value);
    };
    if (xBtn) xBtn.onclick = () => cleanup(null);
    if (cancelBtn) cancelBtn.onclick = () => cleanup(null);
    modal.onclick = (event) => {
      if (event.target === modal) cleanup(null);
    };
    if (form) {
      form.onsubmit = (event) => {
        event.preventDefault();
        const data = Object.fromEntries(new FormData(form).entries());
        const precio = String(data.precio_encargo || "").trim();
        if (!precio) {
          if (statusEl) statusEl.textContent = "Indica el precio de encargo.";
          return;
        }
        cleanup({
          fecha_encargo: String(data.fecha_encargo || "").trim(),
          precio_encargo: precio,
          honorarios: String(data.honorarios || "").trim(),
          planificacion_encargo: String(data.planificacion_encargo || "").trim(),
          proxima_accion: String(data.proxima_accion || "").trim(),
        });
      };
    }
    modal.classList.remove("hidden");
    modal.classList.add("open");
    document.body.classList.add("modal-open");
  });

const buildEncargoConditionUpdates = (conditions = {}) => {
  const inmueble = {};
  const captacion = {};
  ["precio_encargo", "planificacion_encargo"].forEach((key) => {
    if (String(conditions[key] || "").trim()) {
      inmueble[key] = String(conditions[key]).trim();
      captacion[key] = String(conditions[key]).trim();
    }
  });
  ["fecha_encargo", "honorarios"].forEach((key) => {
    if (String(conditions[key] || "").trim()) {
      inmueble[key] = String(conditions[key]).trim();
    }
  });
  if (String(conditions.proxima_accion || "").trim()) {
    captacion.proxima_accion = String(conditions.proxima_accion).trim();
  }
  return { inmueble, captacion };
};

const updateCaptacionEtapa = async (id, etapa, { fromEtapa = "", label = "" } = {}) => {
  const recordId = String(id || "").trim();
  const nextEtapa = String(etapa || "").trim();
  if (!recordId || !nextEtapa) return;
  const from = String(fromEtapa || "").trim();
  const title = String(label || "").trim();
  const msg = `Cambiar etapa${title ? ` (${title})` : ""}:\n${from || "Actual"} → ${nextEtapa}\n\n¿Confirmas el cambio?`;
  if (!window.confirm(msg)) return;
  try {
    const empresaNombre = resolveCrmInmoEmpresaNombre();
    const extra = {};
    if (normalizeSimple(from) === "noticia" && normalizeSimple(nextEtapa) === "encargo") {
      const row = (cachedCrmCaptaciones || []).find((item) => String(item?.id || "") === recordId) || {};
      const conditions = await openInmuebleEncargoConditionsModal(row, {
        statusText: "Estas condiciones se guardarán en la ficha del encargo.",
      });
      if (!conditions) return;
      const updates = buildEncargoConditionUpdates(conditions);
      Object.assign(extra, updates.captacion, updates.inmueble);
    }
    const data = await postJsonWithDbRetry(
      "/api/captaciones_update",
      {
        empresa_nombre: empresaNombre,
        id: recordId,
        etapa: nextEtapa,
        allow_manual_stage: 1,
        ...extra,
      },
      { maxRetries: 5, baseDelayMs: 350, timeoutMs: 15000 }
    );
    if (data?.error) throw new Error(data.error);
    loadCrmCaptaciones();
    window.setTimeout(() => loadCrmInmuebles(), 120);
    renderCrmResumenDashboard();
  } catch (error) {
    alert(error?.message || "No se pudo actualizar la etapa.");
  }
};

let cachedCrmInmuebles = [];
let cachedCrmClientes = [];
let cachedCrmAlquileres = [];
let cachedCrmDemandas = [];
let cachedCrmCaptaciones = [];
let cachedCrmCompraventas = [];
let cachedCrmVisitas = [];
let cachedCrmMapaInmueblesEmpresaId = "";
let cachedCrmMapaInmuebles = [];

const formatDisplayCell = (col, value, fallback = "-") => {
  if (value === null || value === undefined || value === "") return fallback;
  const formatted = formatCell(col, value);
  return formatted === null || formatted === undefined || formatted === "" ? fallback : formatted;
};

const buildInmuebleBadge = (value, tone = "neutral") => {
  const text = String(value || "").trim();
  if (!text) return "";
  return `<span class="inmueble-badge tone-${tone}">${text}</span>`;
};

const buildVerifika2Badge = (isVerified, { compact = false } = {}) => {
  if (!isVerified) return "";
  return `
    <span class="inmueble-badge verifika2${compact ? " compact" : ""}" title="Verificado por Verifika² (documentación revisada)">
      <img src="/assets/verifika2/verifika2_mark.svg" alt="" aria-hidden="true" loading="lazy" />
      <span>Verifika²</span>
    </span>
  `;
};

const buildPortalBadge = (isPublished) => {
  const on = Boolean(isPublished);
  return `
    <span class="inmueble-badge portal${on ? " on" : " off"}" title="Visibilidad en el portal público">
      <span>Portal</span>
      <span>${on ? "Publicado" : "Oculto"}</span>
    </span>
  `;
};

const buildCertifiedBadge = (isCertified) => {
  if (!isCertified) return "";
  return `
    <span class="inmueble-badge certified" title="Certificado premium (idoneidad)">
      <span>Certificado</span>
    </span>
  `;
};

const renderInmuebleTecnocloudPanels = ({
  inmueble = {},
  captacion = {},
  propietarios = [],
  docs = [],
  demandas = [],
  visitas = [],
  actividad = [],
} = {}) => {
  const stageLabel = normalizeCrmMainEtapa(inmueble.estado || captacion.etapa || captacion.situacion_comercial || "");

  if (inmuebleTecnoMeta) {
    const createdAt = String(captacion.created_at || "").trim();
    const ageDays = (() => {
      if (!createdAt) return "";
      const ts = Date.parse(createdAt);
      if (!Number.isFinite(ts)) return "";
      return String(Math.max(0, Math.floor((Date.now() - ts) / (1000 * 60 * 60 * 24))));
    })();
    const meta = [
      { label: "Dirección", value: String(inmueble.direccion || "").trim() },
      { label: "Tipología", value: String(inmueble.tipo_inmueble || "").trim() },
      { label: "Subtipología", value: String(inmueble.subtipologia || "").trim() },
      { label: "Localidad", value: [inmueble.poblacion, inmueble.provincia].filter(Boolean).join(" · ") },
      { label: "Antigüedad", value: ageDays ? `${ageDays} días` : "" },
    ].filter((item) => String(item.value || "").trim());
    inmuebleTecnoMeta.innerHTML = meta.length
      ? meta
          .map(
            (item) => `
              <div class="meta-item">
                <span>${escapeHtml(item.label)}</span>
                <strong>${escapeHtml(item.value)}</strong>
              </div>
            `
          )
          .join("")
      : "";
  }

  if (inmuebleTecnoKpis) {
    const isPlanned = String(captacion.planificado || inmueble.planificado || "").trim() === "1";
    const now = Date.now();
    const withinDays = (row, days) => {
      const raw = String(row?.fecha || row?.created_at || "").trim();
      if (!raw) return false;
      const ts = Date.parse(raw.length > 10 ? raw : `${raw}T00:00:00`);
      if (!Number.isFinite(ts)) return false;
      return (now - ts) <= (days * 24 * 60 * 60 * 1000);
    };
    const citasVenta30 = (Array.isArray(actividad) ? actividad : []).filter((row) => {
      const tipo = normalizeSimple(row?.tipo || "");
      if (!tipo.includes("cita")) return false;
      return withinDays(row, 30);
    }).length;
    const gestiones15 = (Array.isArray(actividad) ? actividad : []).filter((row) => withinDays(row, 15)).length;
    const hasValoracion = Boolean(Number(inmueble.precio_valoracion || 0));

    const kpis = [
      { label: "Planificado", value: isPlanned ? "✓" : "✗" },
      { label: "Citas venta (30 días)", value: String(citasVenta30) },
      { label: "Actividades (15 días)", value: String(gestiones15) },
      { label: "Valoración", value: hasValoracion ? "✓" : "✗" },
    ];
    inmuebleTecnoKpis.innerHTML = kpis
      .map(
        (item) => `
          <div class="inmueble-tecno-kpi">
            <span>${escapeHtml(item.label)}</span>
            <strong>${escapeHtml(item.value)}</strong>
          </div>
        `
      )
      .join("");
  }

  if (inmuebleTecnoStages) {
    // Tecnocloud: barra superior simple (Inmueble → Noticia → Encargo).
    // Las fases posteriores se siguen mostrando en badges/estado, pero aquí mantenemos la claridad visual.
    const stages = ["Inmueble", "Noticia", "Encargo"];
    const activeStage = stageLabel === "Inmueble" || stageLabel === "Noticia" ? stageLabel : "Encargo";
    inmuebleTecnoStages.innerHTML = stages
      .map((label) => {
        const active = normalizeSimple(label) === normalizeSimple(activeStage);
        return `<span class="inmueble-tecno-stage${active ? " active" : ""}">${escapeHtml(label)}</span>`;
      })
      .join("");
  }

  if (inmuebleTecnoSideDemandasList) {
    const items = Array.isArray(demandas) ? demandas.slice(0, 5) : [];
    if (inmuebleTecnoSideDemandasCount) {
      inmuebleTecnoSideDemandasCount.textContent = String(Array.isArray(demandas) ? demandas.length : 0);
    }
    if (!items.length) {
      inmuebleTecnoSideDemandasList.innerHTML = "<p class='muted'>Sin pedidos compatibles.</p>";
    } else {
      inmuebleTecnoSideDemandasList.innerHTML = items
        .map((row) => {
          const title = String(row?.cliente || "").trim() || "Pedido";
          const meta = [row?.tipo || "", row?.estado || ""].filter(Boolean).join(" · ");
          return `
            <div class="inmueble-tecno-minirow">
              <strong>${escapeHtml(title)}</strong>
              <div class="muted">${escapeHtml(meta || "-")}</div>
            </div>
          `;
        })
        .join("");
    }
  }

  if (inmuebleTecnoSideActividadList) {
    const items = Array.isArray(actividad) ? actividad.slice(0, 5) : [];
    if (inmuebleTecnoSideActividadCount) {
      inmuebleTecnoSideActividadCount.textContent = String(Array.isArray(actividad) ? actividad.length : 0);
    }
    if (!items.length) {
      inmuebleTecnoSideActividadList.innerHTML = "<p class='muted'>Sin actividad registrada.</p>";
    } else {
      inmuebleTecnoSideActividadList.innerHTML = items
        .map((row) => {
          const title = String(row?.tipo || "").trim() || "Actividad";
          const date = row?.fecha ? formatCell("fecha", row.fecha) : "-";
          const meta = [row?.hora || "", row?.estado || ""].filter(Boolean).join(" · ");
          return `
            <div class="inmueble-tecno-minirow">
              <strong>${escapeHtml(title)}</strong>
              <div class="muted">${escapeHtml([date, meta].filter(Boolean).join(" · ") || "-")}</div>
            </div>
          `;
        })
        .join("");
    }
  }

  const compradores = Array.isArray(state.currentInmuebleContext?.compradores)
    ? state.currentInmuebleContext.compradores
    : [];
  const servicios = Array.isArray(state.currentInmuebleContext?.servicios)
    ? state.currentInmuebleContext.servicios
    : [];

  if (inmuebleTecnoSidePersonasCard) {
    const topKey = resolveInmuebleTopTabKey(state.currentInmuebleTabKey || "datos");
    const personasMode = topKey === "datos";

    if (inmuebleTecnoSidePropietarioTitle) {
      inmuebleTecnoSidePropietarioTitle.textContent = personasMode ? "Personas relacionadas" : "Propietario";
    }
    if (inmuebleTecnoSidePropietarioSubtitle) {
      inmuebleTecnoSidePropietarioSubtitle.textContent = personasMode
        ? "Propietarios, compradores e informadores vinculados al expediente."
        : "Propietario principal del expediente (según ficha).";
    }
    if (inmuebleTecnoSidePersonasNew) {
      inmuebleTecnoSidePersonasNew.classList.toggle("hidden", !personasMode);
    }
    if (inmuebleTecnoSidePersonasCount) {
      inmuebleTecnoSidePersonasCount.classList.toggle("hidden", !personasMode);
    }

    if (!personasMode) {
      const owner = (Array.isArray(propietarios) ? propietarios : []).find((p) => String(p?.nombre || "").trim()) || {};
      const nombre = String(owner?.nombre || "").trim();
      const telefono = String(owner?.telefono || "").trim();
      const email = String(owner?.email || "").trim();
      const nif = String(owner?.nif || "").trim();
      inmuebleTecnoSidePersonasCard.innerHTML = `
        <div class="inmueble-tecno-minirow">
          <strong>${escapeHtml(nombre || "Sin propietario")}</strong>
          <div class="muted">
            ${escapeHtml([telefono, email, nif ? `NIF ${nif}` : ""].filter(Boolean).join(" · ") || "-")}
          </div>
        </div>
        <button type="button" class="secondary ghost tc-servmore" data-open-personas="1">Ver personas relacionadas</button>
      `;
      const openBtn = inmuebleTecnoSidePersonasCard.querySelector("[data-open-personas]");
      if (openBtn) {
        openBtn.onclick = (event) => {
          event.preventDefault();
          event.stopPropagation();
          setInmuebleTab("personas");
        };
      }
      return;
    }

    const ownerNames = (Array.isArray(propietarios) ? propietarios : [])
      .map((p) => String(p?.nombre || "").trim())
      .filter(Boolean);
    const buyerNames = compradores
      .map((row) => String(row?.cliente || "").trim())
      .filter(Boolean);
    const uniqueBuyers = Array.from(new Set(buyerNames));
    const informador = String(captacion?.informador_nombre || "").trim();
    const responsable = String(inmueble?.asesor || captacion?.asesor || inmueble?.responsable || captacion?.responsable || "").trim();

    const personasRows = [
      {
        label: `Propietarios${ownerNames.length ? ` (${ownerNames.length})` : ""}`,
        value: ownerNames.length ? ownerNames.slice(0, 2).join(", ") + (ownerNames.length > 2 ? ` · +${ownerNames.length - 2} más` : "") : "Sin enlazar",
      },
      {
        label: `Compradores${uniqueBuyers.length ? ` (${uniqueBuyers.length})` : ""}`,
        value: uniqueBuyers.length ? uniqueBuyers.slice(0, 2).join(", ") + (uniqueBuyers.length > 2 ? ` · +${uniqueBuyers.length - 2} más` : "") : "-",
      },
      { label: "Informador", value: informador || "-" },
      { label: "Responsable", value: responsable || "-" },
    ];

    if (inmuebleTecnoSidePersonasCount) {
      const count =
        ownerNames.length +
        uniqueBuyers.length +
        (informador ? 1 : 0);
      inmuebleTecnoSidePersonasCount.textContent = String(count);
    }

    inmuebleTecnoSidePersonasCard.innerHTML = personasRows
      .map(
        (item) => `
          <div class="inmueble-tecno-minirow">
            <strong>${escapeHtml(item.label)}</strong>
            <div class="muted">${escapeHtml(item.value)}</div>
          </div>
        `
      )
      .join("");
  }

  if (inmuebleTecnoSideServiciosList) {
    const list = (Array.isArray(servicios) ? servicios : [])
      .map((s) => String(s || "").trim())
      .filter(Boolean);
    if (inmuebleTecnoSideServiciosCount) {
      inmuebleTecnoSideServiciosCount.textContent = String(list.length);
    }
	    if (!list.length) {
	      inmuebleTecnoSideServiciosList.innerHTML = "<p class='muted'>Sin servicios definidos.</p>";
	    } else {
	      const quick = list.slice(0, 8);
	      inmuebleTecnoSideServiciosList.innerHTML = `
	        <div class="tc-servgrid" role="list">
	          ${quick
	            .map(
	              (s) => `
	                <div class="tc-servitem" role="listitem">
	                  <div class="tc-servico" aria-hidden="true">${inmuebleServicioIconFor(s, 18)}</div>
	                  <div class="tc-servlabel">${escapeHtml(s)}</div>
	                </div>
	              `
	            )
	            .join("")}
	        </div>
	        <button type="button" class="secondary ghost tc-servmore" data-open-servicios="1">Ver/Editar todos</button>
	      `;
      const openBtn = inmuebleTecnoSideServiciosList.querySelector("[data-open-servicios]");
      if (openBtn) {
        openBtn.onclick = (event) => {
          event.preventDefault();
          event.stopPropagation();
          if (inmuebleTecnoSideServiciosEdit) {
            inmuebleTecnoSideServiciosEdit.click();
          }
        };
      }
    }
  }
};

const inmuebleServicioIconKeyFor = (label) => {
  const key = normalizeSimple(label || "");
  if (key.includes("bañ") || key.includes("bano") || key.includes("aseo")) return "bathtub";
  if (key.includes("cocin")) return "kitchen";
  if (key.includes("calef")) return "flame";
  if (key.includes("ascens")) return "elevator";
  if (key.includes("terraza") || key.includes("balcon") || key.includes("balcón")) return "sun";
  if (key.includes("garaje") || key.includes("parking")) return "car";
  if (key.includes("traster")) return "box";
  if (key.includes("piscin")) return "pool";
  if (key.includes("jardin") || key.includes("jardín")) return "leaf";
  if (key.includes("aire") || key.includes("a/a") || key.includes("acond")) return "snowflake";
  return "plus";
};

const inmuebleServicioIconFor = (label, size = 18) => renderIco(inmuebleServicioIconKeyFor(label), size);

