const lookupClienteByNif = async (nif) => {
  if (!nif) return null;
  const serviceParam = getServiceFilterParam();
  const params = new URLSearchParams({ nif });
  if (serviceParam) {
    params.set("servicio", serviceParam);
  }
  try {
    return await api(`/api/cliente_lookup?${params.toString()}`);
  } catch {
    return null;
  }
};

const lookupClienteByNombre = async (nombre) => {
  const text = String(nombre || "").trim();
  if (!text) return null;
  const params = new URLSearchParams({
    q: text,
    include_id: "1",
    limit: "100",
  });
  try {
    const data = await api(`/api/clientes?${params.toString()}`);
    const columns = data?.columns || [];
    const rows = data?.rows || [];
    const idIndex = columns.indexOf("id");
    const nombreIndex = columns.indexOf("nombre");
    if (idIndex < 0 || nombreIndex < 0) return null;
    const wanted = normalizeName(text);
    const exact = rows.find((row) => normalizeName(row[nombreIndex] || "") === wanted);
    if (exact) {
      return { id: exact[idIndex], nombre: exact[nombreIndex] || text };
    }
    let best = null;
    let bestScore = 0;
    const candidates = buildNameCandidates(text);
    rows.forEach((row) => {
      const rowName = row[nombreIndex] || "";
      let score = 0;
      candidates.forEach((candidate) => {
        score = Math.max(score, scoreNameSimilarity(rowName, candidate));
      });
      if (score > bestScore) {
        bestScore = score;
        best = row;
      }
    });
    if (best && bestScore >= 0.4) {
      return { id: best[idIndex], nombre: best[nombreIndex] || text };
    }
  } catch (e) {}
  return null;
};

const getClienteServicios = async (clienteId) => {
  if (!clienteId) return [];
  try {
    const data = await api(`/api/cliente?id=${encodeURIComponent(clienteId)}`);
    return data?.servicios || data?.empresas || [];
  } catch {
    return [];
  }
};

const resolveOcrClienteMatch = async (type, fields) => {
  const ctx = getOcrClienteContext(type);
  if (!ctx) return;
  const nifRaw = fields.nif || fields.dni || "";
  const nif = String(nifRaw || "").trim();
  setOcrClienteUi(ctx, { status: "Comprobando cliente..." });
  let clienteId = "";
  let clienteNombre = "";
  let servicios = [];
  if (nif) {
    const data = await lookupClienteByNif(nif);
    if (data && data.found) {
      const cliente = data.cliente || {};
      clienteId = cliente.id || data.cliente_id || "";
      clienteNombre = cliente.nombre || "";
      servicios = data.servicios || [];
    }
  }
  if (!clienteId) {
    const byName = await lookupClienteByNombre(fields.tomador || "");
    if (byName && byName.id) {
      clienteId = byName.id;
      clienteNombre = byName.nombre || "";
      servicios = await getClienteServicios(clienteId);
    }
  }
  if (!clienteId) {
    ctx.setId("");
    setOcrClienteUi(ctx, {
      status: "Cliente no encontrado. Puedes crearlo desde aquí.",
      showCreate: true,
      showAdd: false,
      showOpen: false,
    });
    return;
  }
  ctx.setId(clienteId);
  const hasSeguros = servicios.some((row) => normalizeServicio(row.servicio) === "seguros");
  if (!hasSeguros) {
    setOcrClienteUi(ctx, {
      status: "Cliente existe en el sistema. Puedes asignar Seguros.",
      showCreate: false,
      showAdd: true,
      showOpen: true,
    });
    return;
  }
  setOcrClienteUi(ctx, {
    status: `Cliente encontrado: ${clienteNombre || "Sin nombre"}${nif ? ` · ${nif}` : ""}`,
    showCreate: false,
    showAdd: false,
    showOpen: true,
  });
};

const linkClienteSegurosService = async (clienteId, ctx, tomador = "") => {
  const ensureEmpresas = state.empresas && state.empresas.length
    ? Promise.resolve(state.empresas)
    : api("/api/empresas").then((data) => {
        state.empresas = data || [];
        return state.empresas;
      });
  const empresas = await ensureEmpresas;
  const fincas = (empresas || []).find((empresa) => empresa.nombre === FINCAS_COMPANY);
  if (!fincas) {
    if (ctx?.statusEl) ctx.statusEl.textContent = "Empresa seguros no encontrada.";
    return;
  }
  if (!clienteId) {
    if (ctx?.statusEl) ctx.statusEl.textContent = "Cliente no seleccionado.";
    return;
  }
  if (ctx?.statusEl) ctx.statusEl.textContent = "Asignando servicio Seguros...";
  try {
    const data = await postJsonWithDbRetry("/api/clientes_link", {
      cliente_id: clienteId,
      empresa_id: fincas.id,
      servicio: "Seguros",
      estado: "Activo",
      fecha_inicio: new Date().toISOString().slice(0, 10),
    });
    if (data.error) {
      if (ctx?.statusEl) ctx.statusEl.textContent = data.error;
      return;
    }
    const nombreTomador = String(tomador || "").trim();
    if (nombreTomador) {
      const params = new URLSearchParams({
        cliente_id: clienteId,
        tomador: nombreTomador,
        autolink: "1",
      });
      if (fincas?.id) params.set("empresa_id", fincas.id);
      try {
        await api(`/api/seguros_cliente?${params.toString()}`);
      } catch (e) {}
    }
    setOcrClienteUi(ctx, {
      status: "Servicio Seguros asignado y pólizas revisadas.",
      showCreate: false,
      showAdd: false,
      showOpen: true,
    });
  } catch {
    if (ctx?.statusEl) ctx.statusEl.textContent = "Error al asignar el servicio.";
  }
};

const createClienteFromOcr = async (type, fields) => {
  const ctx = getOcrClienteContext(type);
  if (!ctx) return;
  const nif = String(fields.nif || "").trim();
  const tomador = String(fields.tomador || "").trim();
  const nombre = buildClienteNombreFromTomador(tomador);
  if (!nombre) {
    if (ctx.statusEl) ctx.statusEl.textContent = "Introduce el nombre del tomador.";
    return;
  }
  if (!nif) {
    if (ctx.statusEl) ctx.statusEl.textContent = "Introduce el DNI/NIF para crear el cliente.";
    return;
  }
  if (ctx.statusEl) ctx.statusEl.textContent = "Creando cliente...";
  const clienteId = randomId();
  const payload = {
    id: clienteId,
    nombre,
    tipo_persona: "Física",
    nif,
    procedencia_detalle: "Seguros (OCR)",
    telefono: fields.telefono || "",
    email: fields.email || "",
    direccion: fields.direccion || "",
    fecha_nacimiento: fields.fecha_nacimiento || "",
  };
  const procedenciaControls =
    type === "bdt"
      ? {
          canalEl: segurosBdtOcrCanal,
          userEl: segurosBdtOcrCanalUser,
          clienteEl: segurosBdtOcrCanalCliente,
        }
      : {
          canalEl: segurosOcrCanal,
          userEl: segurosOcrCanalUser,
          clienteEl: segurosOcrCanalCliente,
        };
  const { procedencia, error } = readProcedenciaFromControls(procedenciaControls);
  if (error) {
    if (ctx.statusEl) ctx.statusEl.textContent = error;
    return;
  }
  Object.assign(payload, procedencia || {});
  try {
    const res = await fetch("/api/clientes", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    });
    const data = await res.json();
    let finalId = clienteId;
    let existed = false;
    if (data.error) {
      if (res.status === 409 && data.id) {
        finalId = data.id;
        existed = true;
      } else {
        if (ctx.statusEl) ctx.statusEl.textContent = data.error;
        return;
      }
    }
    ctx.setId(finalId);
    await linkClienteSegurosService(finalId, ctx);
    await refreshClientesSummary();
    setOcrClienteUi(ctx, {
      status: existed ? "Cliente ya existía. Servicio Seguros asignado." : "Cliente creado y asignado a Seguros.",
      showCreate: false,
      showAdd: false,
      showOpen: true,
    });
  } catch {
    if (ctx.statusEl) ctx.statusEl.textContent = "Error al crear cliente.";
  }
};

const ensureSegurosBdtData = async (forceRefresh = false) => {
  const empresa = resolveCrmSegurosEmpresa();
  const empresaId = resolveLegacyEmpresaId(empresa);
  if (!empresaId) return null;
  if (!forceRefresh && state.segurosBdtCache && state.segurosBdtCache.empresaId === empresaId) {
    return state.segurosBdtCache.data;
  }
  const params = new URLSearchParams({
    tabla: "seguros",
    empresa_id: empresaId,
    include_id: "1",
    limit: "1000",
  });
  const data = await api(`/api/tabla?${params.toString()}`);
  if (data?.error) return data;
  state.segurosBdtCache = { empresaId, data, ts: Date.now() };
  return data;
};

const matchSegurosBdtFromFields = async () => {
  if (segurosBdtOcrStatus) segurosBdtOcrStatus.textContent = "";
  let data = await ensureSegurosBdtData(true);
  if (!data || data.error) {
    if (segurosBdtOcrStatus) {
      segurosBdtOcrStatus.textContent = data?.error || "No se pudo cargar registros.";
    }
    return;
  }
  const fields = getSegurosBdtOcrFields();
  const columns = data.columns || [];
  const rows = data.rows || [];
  const idIndex = columns.indexOf("id");
  if (idIndex < 0) {
    if (segurosBdtOcrStatus) segurosBdtOcrStatus.textContent = "Registros sin identificador.";
    return;
  }
  const hasInput =
    fields.poliza_numero ||
    fields.tomador ||
    fields.nif ||
    fields.cliente_id ||
    fields.compania ||
    fields.ramo ||
    fields.fecha_efecto ||
    fields.fecha_vencimiento ||
    fields.prima_neta ||
    fields.prima_total;
  if (!hasInput) {
    populateSegurosBdtSelect(rows, columns);
    if (segurosBdtOcrStatus) {
      segurosBdtOcrStatus.textContent = "Completa campos para buscar o selecciona manualmente.";
    }
    return;
  }
  const matches = rows
    .map((row) => ({
      row,
      score: scoreSegurosBdtMatch(row, columns, fields),
    }))
    .filter((item) => item.score > 0)
    .sort((a, b) => b.score - a.score);
  if (!matches.length) {
    // Retry once with fresh data in case cache/data became stale between saves.
    data = await ensureSegurosBdtData(true);
    const retryColumns = data.columns || [];
    const retryRows = data.rows || [];
    const retryIdIndex = retryColumns.indexOf("id");
    if (retryIdIndex >= 0) {
      const retryMatches = retryRows
        .map((row) => ({ row, score: scoreSegurosBdtMatch(row, retryColumns, fields) }))
        .filter((item) => item.score > 0)
        .sort((a, b) => b.score - a.score);
      if (retryMatches.length) {
        const retryBest = retryMatches[0];
        const retryBestId = retryBest.row[retryIdIndex];
        const retryBestLabel = formatSegurosBdtLabel(retryBest.row, retryColumns);
        populateSegurosBdtSelect(retryMatches.slice(0, 12).map((item) => item.row), retryColumns, retryBestId);
        if (segurosBdtOcrStatus) {
          segurosBdtOcrStatus.textContent = `Coincidencia automática: ${retryBestLabel}.`;
        }
        return;
      }
    }
    populateSegurosBdtSelect(rows, columns);
    if (segurosBdtOcrStatus) {
      segurosBdtOcrStatus.textContent = "Sin coincidencias. Completa campos o selecciona manualmente.";
    }
    return;
  }
  const best = matches[0];
  const next = matches[1];
  const bestId = best.row[idIndex];
  const bestLabel = formatSegurosBdtLabel(best.row, columns);
  const topRows = matches.slice(0, 12).map((item) => item.row);
  populateSegurosBdtSelect(topRows, columns, bestId);
  const isStrong = best.score >= 12 && (!next || best.score >= next.score + 3);
  if (segurosBdtOcrStatus) {
    segurosBdtOcrStatus.textContent = isStrong
      ? `Coincidencia automática: ${bestLabel}.`
      : "Varias coincidencias. Selecciona la correcta.";
  }
};

