const setSuggestText = (target, rows) => {
  if (!target) return;
  if (!rows || !rows.length) {
    target.textContent = "";
    return;
  }
  const line = rows
    .slice(0, 3)
    .map((row) => `${row.codigo} · ${row.descripcion}`)
    .join(" | ");
  target.textContent = `Sugerencias: ${line}`;
};

const setupCatalogoInputs = () => {
  const cnaeInput = clienteProfesionalCnaeForm?.querySelector('[name="cnae"]');
  const iaeInput = clienteProfesionalIaeForm?.querySelector('[name="iae"]');
  const actividadInput = clienteProfesionalActividadForm?.querySelector('[name="actividad"]');
  if (cnaeInput) {
    cnaeInput.addEventListener("input", () => {
      const q = cnaeInput.value.trim();
      loadCatalogo("cnae", q).then((rows) => {
        updateCatalogoList(cnaeCatalogo, rows);
        setSuggestText(cnaeSuggest, rows);
      });
    });
    cnaeInput.addEventListener("blur", () => {
      const codigo = cnaeInput.value.trim();
      if (!codigo) return;
      loadCatalogo("cnae", codigo).then((rows) => {
        const exact = rows.find((row) => row.codigo === codigo);
        if (exact && actividadInput && !actividadInput.value.trim()) {
          actividadInput.value = exact.descripcion;
        }
      });
    });
  }
  if (iaeInput) {
    iaeInput.addEventListener("input", () => {
      const q = iaeInput.value.trim();
      loadCatalogo("iae", q).then((rows) => {
        updateCatalogoList(iaeCatalogo, rows);
        setSuggestText(iaeSuggest, rows);
      });
    });
    iaeInput.addEventListener("blur", () => {
      const codigo = iaeInput.value.trim();
      if (!codigo) return;
      loadCatalogo("iae", codigo).then((rows) => {
        const exact = rows.find((row) => row.codigo === codigo);
        if (exact && actividadInput && !actividadInput.value.trim()) {
          actividadInput.value = exact.descripcion;
        }
      });
    });
  }
  if (actividadInput) {
    actividadInput.addEventListener("blur", () => {
      const texto = actividadInput.value.trim();
      if (!texto) return;
      api(`/api/catalogo_match?texto=${encodeURIComponent(texto)}`).then((data) => {
        const cnaeRows = data.cnae || [];
        const iaeRows = data.iae || [];
        setSuggestText(actividadSuggest, [
          ...cnaeRows.map((row) => ({ ...row, codigo: `CNAE ${row.codigo}` })),
          ...iaeRows.map((row) => ({ ...row, codigo: `IAE ${row.codigo}` })),
        ]);
        if (cnaeRows.length === 1 && cnaeInput && !cnaeInput.value.trim()) {
          cnaeInput.value = cnaeRows[0].codigo;
        }
        if (iaeRows.length === 1 && iaeInput && !iaeInput.value.trim()) {
          iaeInput.value = iaeRows[0].codigo;
        }
      });
    });
  }
};

const ensureGestoriaBudgetsWorkspaceId = async () => {
  if (state.currentWorkspaceId) return state.currentWorkspaceId;
  if (state.gestoriaBudgetWorkspaceId) return state.gestoriaBudgetWorkspaceId;
  try {
    const cached = localStorage.getItem("crm.gestoriaBudgetWorkspaceId") || "";
    if (cached) {
      state.gestoriaBudgetWorkspaceId = cached;
      return cached;
    }
  } catch (e) {}
  const data = await api("/api/workspaces");
  const rows = Array.isArray(data?.rows) ? data.rows : [];
  const picked = String(rows[0]?.id || "").trim();
  if (!picked) {
    throw new Error("No hay workspaces disponibles para crear presupuestos.");
  }
  state.gestoriaBudgetWorkspaceId = picked;
  try {
    localStorage.setItem("crm.gestoriaBudgetWorkspaceId", picked);
  } catch (e) {}
  return picked;
};

const syncGestoriaBudgetQuickComputed = () => {
  if (!gestoriaBudgetQuickForm) return;
  const subtotalInput = gestoriaBudgetQuickForm.querySelector('[name="subtotal"]');
  const ivaPctInput = gestoriaBudgetQuickForm.querySelector('[name="iva_pct"]');
  const ivaInput = gestoriaBudgetQuickForm.querySelector('[name="impuestos"]');
  const totalInput = gestoriaBudgetQuickForm.querySelector('[name="total"]');
  const subtotal = parseMoneyValue(subtotalInput?.value || "");
  const ivaPct = Math.max(0, Math.min(100, parseMoneyValue(ivaPctInput?.value || "")));
  const ivaManual = parseMoneyValue(ivaInput?.value || "");
  const iva = subtotal > 0 ? (subtotal * ivaPct) / 100 : ivaManual;
  const total = subtotal + iva;
  if (ivaPctInput) ivaPctInput.value = ivaPct ? String(ivaPct) : "";
  if (ivaInput) ivaInput.value = iva > 0 ? iva.toFixed(2) : "";
  if (totalInput) totalInput.value = total > 0 ? total.toFixed(2) : "";
};

const renderGestoriaBudgetsList = (rows = []) => {
  if (!gestoriaBudgetsTable) return;
  const items = Array.isArray(rows) ? rows : [];
  if (!items.length) {
    gestoriaBudgetsTable.innerHTML = "<p class='muted'>Sin presupuestos todavía.</p>";
    return;
  }
  const table = document.createElement("table");
  const thead = document.createElement("thead");
  const trHead = document.createElement("tr");
  ["fecha", "cliente", "titulo", "servicio", "estado", "total", "acciones"].forEach((col) => {
    const th = document.createElement("th");
    th.textContent = formatHeader(col);
    trHead.appendChild(th);
  });
  thead.appendChild(trHead);
  table.appendChild(thead);
  const tbody = document.createElement("tbody");
  items.forEach((row) => {
    const tr = document.createElement("tr");
    const estado = String(row.estado || "").trim();
    const total = euroFormatter.format(Number(row.total || 0));
    const servicio = String(row.servicio || "").trim() || "-";
    const pdfHref = `/api/workspace_presupuesto_pdf?id=${encodeURIComponent(String(row.id || ""))}&workspace_id=${encodeURIComponent(String(row.workspace_id || ""))}`;
    const encargoHref = `/api/workspace_presupuesto_encargo_pdf?id=${encodeURIComponent(String(row.id || ""))}&workspace_id=${encodeURIComponent(String(row.workspace_id || ""))}`;
    const actions = `
      <a class="secondary ghost button-inline" href="${pdfHref}" target="_blank" rel="noreferrer">PDF</a>
      ${normalizeSimple(estado) === "aceptado" ? `<a class="secondary ghost button-inline" href="${encargoHref}" target="_blank" rel="noreferrer">Encargo</a>` : ""}
    `;
    const cells = [
      formatCell("fecha", row.fecha) || row.fecha || "-",
      escapeHtml(row.cliente_nombre || "-"),
      escapeHtml(row.titulo || "Presupuesto"),
      escapeHtml(SERVICE_LABELS[servicio] || servicio),
      escapeHtml(estado || "-"),
      escapeHtml(total),
      actions,
    ];
    cells.forEach((value, index) => {
      const td = document.createElement("td");
      if (index === cells.length - 1) {
        td.innerHTML = value;
      } else {
        td.innerHTML = value;
      }
      tr.appendChild(td);
    });
    tbody.appendChild(tr);
  });
  table.appendChild(tbody);
  gestoriaBudgetsTable.innerHTML = "";
  gestoriaBudgetsTable.appendChild(table);
};

const loadGestoriaFact = () => {
  const empresa = resolveCrmGestoriaEmpresa();
  if (!empresa) return;
  if (gestoriaBudgetsInfo) gestoriaBudgetsInfo.textContent = "Cargando presupuestos...";
	  loadGestoriaTrabajoTipos()
	    .then((rows) => {
	      hydrateGestoriaBudgetCategorySelect(gestoriaBudgetTipoCategoria);
	      const baseRows = Array.isArray(rows) ? rows : [];
	      const applyFilter = () => {
	        const source = Array.isArray(state.gestoriaTrabajoTiposCache?.rows) ? state.gestoriaTrabajoTiposCache.rows : baseRows;
	        const filtered = filterGestoriaTrabajoTiposByCategory(source, gestoriaBudgetTipoCategoria?.value || "");
	        hydrateGestoriaTrabajoTipoSelect(gestoriaBudgetTipoTrabajo, filtered);
	        renderGestoriaBudgetTipoTemplateFields();
	      };
	      if (gestoriaBudgetTipoCategoria && gestoriaBudgetTipoCategoria.dataset.bound !== "1") {
	        gestoriaBudgetTipoCategoria.dataset.bound = "1";
	        gestoriaBudgetTipoCategoria.addEventListener("change", () => {
	          applyFilter();
	          try { syncGestoriaBudgetQuickComputed(); } catch (e) {}
	        });
	      }
	      applyFilter();
	      renderGestoriaTrabajoTiposAdmin(rows);
	      bindGestoriaTipoDefaults(gestoriaBudgetTipoTrabajo, () => {
	        if (!gestoriaBudgetQuickForm || !gestoriaBudgetTipoTrabajo) return;
	        const meta = getGestoriaTipoMeta(gestoriaBudgetTipoTrabajo);
        const subtotalInput = gestoriaBudgetQuickForm.querySelector('[name="subtotal"]');
        const ivaPctInput = gestoriaBudgetQuickForm.querySelector('[name="iva_pct"]');
        const currentSubtotal = parseMoneyValue(String(subtotalInput?.value || "").trim());
        if (subtotalInput && (!String(subtotalInput.value || "").trim() || currentSubtotal === 0) && meta.precio_base && meta.precio_base > 0) {
          subtotalInput.value = String(meta.precio_base);
        }
	        const currentIvaPct = parseMoneyValue(String(ivaPctInput?.value || "").trim());
	        if (ivaPctInput && (!String(ivaPctInput.value || "").trim() || currentIvaPct === 0) && meta.iva_pct !== null) {
	          ivaPctInput.value = String(meta.iva_pct);
	        }
	        renderGestoriaBudgetTipoTemplateFields();
	        syncGestoriaBudgetQuickComputed();
	      });
	    })
	    .catch(() => {});
  const servicio = String(gestoriaBudgetsServicioFilter?.value || "gestoria").trim().toLowerCase();
  const estado = String(gestoriaBudgetsEstadoFilter?.value || "all").trim();
  const params = new URLSearchParams({
    empresa_id: resolveLegacyEmpresaId(empresa),
    limit: "120",
  });
  if (servicio && servicio !== "all") params.set("servicio", servicio);
  if (estado && estado !== "all") params.set("estado", estado);
  api(`/api/empresa_presupuestos?${params.toString()}`)
    .then((data) => {
      const rows = Array.isArray(data?.rows) ? data.rows : [];
      renderGestoriaBudgetsList(rows);
      if (gestoriaBudgetsInfo) {
        const labelServicio = servicio === "all" ? "Todos" : (SERVICE_LABELS[servicio] || servicio);
        const labelEstado = estado === "all" ? "Todos" : estado;
        gestoriaBudgetsInfo.textContent = `${rows.length} presupuestos · ${labelServicio} · ${labelEstado}`;
      }
    })
    .catch((error) => {
      if (gestoriaBudgetsTable) gestoriaBudgetsTable.innerHTML = `<p class='muted'>${escapeHtml(error?.message || "No se pudieron cargar los presupuestos.")}</p>`;
      if (gestoriaBudgetsInfo) gestoriaBudgetsInfo.textContent = "";
    });
};

const loadAgendaGeneral = () => {
  if (!agendaGeneral) return;
  // Por diseño: cada vertical tiene su propia agenda. La “agenda general” solo la dejamos
  // disponible para usuarios privilegiados (dirección/superadmin) para visión transversal.
  const authUser = getAuthScopeUser();
  if (!authUser || !isPrivilegedUser(authUser)) {
    agendaGeneral.innerHTML = "<p class='muted'>La agenda general está desactivada. Usa la agenda del servicio (Inmobiliaria/Seguros/Financiaciones/Gestoría).</p>";
    return;
  }
  const fincas = state.empresas.find((e) => e.nombre === FINCAS_COMPANY);
  const fin = resolveCrmFinEmpresa();
  const tasks = [];
  const allowed = (state.currentUserServices && state.currentUserServices.length)
    ? state.currentUserServices
    : expandServiceAliases(parseServiceList(authUser?.servicio || ""));
  const allowService = (value) => {
    if (!allowed.length) return true;
    return allowed.includes(normalizeSimple(value));
  };
  if (fincas) {
    if (allowService("gestoria")) {
      tasks.push(api(`/api/acciones?${buildAgendaActionParams("gestoria", { empresa_id: fincas.id }).toString()}`));
    }
    if (allowService("seguros")) {
      tasks.push(api(`/api/acciones?${buildAgendaActionParams("seguros", { empresa_id: fincas.id }).toString()}`));
    }
  }
  if (fin) {
    if (allowService("financiaciones")) {
      tasks.push(api(`/api/acciones?${buildAgendaActionParams("financiaciones", { empresa_id: fin.id }).toString()}`));
    }
  }
  if (!tasks.length) {
    agendaGeneral.innerHTML = "<p class='muted'>Sin empresas cargadas.</p>";
    return;
  }
  agendaGeneral.dataset.readonly = "1";
  Promise.all(tasks.map((t) => t.catch(() => ({ rows: [] })))).then((responses) => {
    const allRows = responses.flatMap((data) => data.rows || []);
    const events = buildAgendaEvents(allRows, "", "");
    renderAgendaCalendar(agendaGeneral, events, "Agenda general");
  });
};

const parseMoneyValue = (value) => {
  const parsed = toNumber(value);
  return Number.isFinite(parsed) ? parsed : 0;
};

const getTableRowsByEmpresa = async (tabla, empresaId, q = "") => {
  if (!tabla || !empresaId) return { columns: [], rows: [] };
  const params = new URLSearchParams({ tabla, empresa_id: empresaId });
  if (q) params.set("q", q);
  const data = await api(`/api/tabla?${params.toString()}`);
  return {
    columns: data?.columns || [],
    rows: data?.rows || [],
  };
};

const ensureClienteFinPanel = (container) => {
  if (!container) return { form: null, data: null };
  let form = container.querySelector("[data-cliente-fin-form]");
  let data = container.querySelector("[data-cliente-fin-data]");
  if (form && data) return { form, data };
  container.innerHTML = `
    <div class="form-actions" style="margin:0 0 10px 0;">
      <button type="button" class="secondary" data-cliente-fin-open-alta="1" title="Crear una hipoteca para este cliente (Financiaciones)">Cliente financiación</button>
    </div>
    <div class="cliente-service-form" data-cliente-fin-form="1"></div>
    <div class="cliente-service-data" data-cliente-fin-data="1"></div>
  `;
  form = container.querySelector("[data-cliente-fin-form]");
  data = container.querySelector("[data-cliente-fin-data]");
  return { form, data };
};

const loadClienteHipotecasFicha = async (cliente = null, empresasActivas = []) => {
  if (!clienteHipotecaFicha) return;
  const panel = ensureClienteFinPanel(clienteHipotecaFicha);
  if (panel.form) {
    try {
      renderEditableGrid(panel.form, CLIENTE_FIELDS_FIN_PROFILE, cliente || {}, "cliente");
    } catch {
      panel.form.innerHTML = "";
    }
  }
  const clienteNombre = String(cliente?.nombre || "").trim();
	  const openBtn = clienteHipotecaFicha.querySelector("[data-cliente-fin-open-alta]");
	  if (openBtn) {
	    openBtn.onclick = () => {
	      if (!clienteNombre) {
	        window.alert("Indica el nombre del cliente para crear una hipoteca.");
	        return;
	      }
	      state.pendingHipotecaDraft = { clienteNombre };
	      openFinCrm();
	      window.setTimeout(() => {
	        try {
	          setHipotecaAltaView("alta");
	        } catch (e) {}
	      }, 0);
	    };
	  }
  if (!clienteNombre) {
    if (panel.data) {
      panel.data.innerHTML = "<p class='muted'>Sin nombre de cliente para buscar financiaciones.</p>";
    } else {
      clienteHipotecaFicha.innerHTML = "<p class='muted'>Sin nombre de cliente para buscar financiaciones.</p>";
    }
    return;
  }
  const empresaByName = new Map((state.empresas || []).map((item) => [item.nombre, item.id]));
  let finEmpresaIds = (empresasActivas || [])
    .filter((row) => normalizeSimple(row.servicio || "") === "financiaciones")
    .map((row) => empresaByName.get(row.empresa))
    .filter(Boolean);
  if (!finEmpresaIds.length) {
    const fin = resolveCrmFinEmpresa();
    if (fin?.id) finEmpresaIds = [fin.id];
  }
  if (!finEmpresaIds.length) {
    if (panel.data) {
      panel.data.innerHTML = "<p class='muted'>Sin empresa de financiaciones configurada.</p>";
    } else {
      clienteHipotecaFicha.innerHTML = "<p class='muted'>Sin empresa de financiaciones configurada.</p>";
    }
    return;
  }
  try {
    const groups = await Promise.all(
      finEmpresaIds.map((empresaId) =>
        getTableRowsByEmpresa("hipotecas", empresaId, clienteNombre).catch(() => ({ columns: [], rows: [] }))
      )
    );
    const base = groups.find((item) => Array.isArray(item.columns) && item.columns.length) || { columns: [], rows: [] };
    const columns = base.columns || [];
    if (!columns.length) {
      if (panel.data) {
        panel.data.innerHTML = "<p class='muted'>Sin financiaciones vinculadas.</p>";
      } else {
        clienteHipotecaFicha.innerHTML = "<p class='muted'>Sin financiaciones vinculadas.</p>";
      }
      return;
    }
    const idIndex = columns.indexOf("id");
    const clienteIdx = columns.indexOf("cliente");
    const seen = new Set();
    const clienteKey = normalizeSimple(clienteNombre);
    const rows = groups
      .flatMap((item) => item.rows || [])
      .filter((row) => Array.isArray(row))
      .filter((row) => {
        const uniqueKey =
          idIndex >= 0 ? String(row[idIndex] || "").trim() : JSON.stringify(row);
        if (uniqueKey && seen.has(uniqueKey)) return false;
        if (uniqueKey) seen.add(uniqueKey);
        if (clienteIdx < 0) return true;
        return normalizeSimple(String(row[clienteIdx] || "")).includes(clienteKey);
      });
    if (!rows.length) {
      if (panel.data) {
        panel.data.innerHTML = "<p class='muted'>Sin financiaciones vinculadas.</p>";
      } else {
        clienteHipotecaFicha.innerHTML = "<p class='muted'>Sin financiaciones vinculadas.</p>";
      }
      return;
    }
    if (panel.data) {
      renderTableInto({ columns, rows }, panel.data, null, "Hipotecas");
    } else {
      renderTableInto({ columns, rows }, clienteHipotecaFicha, null, "Hipotecas");
    }
  } catch {
    if (panel.data) {
      panel.data.innerHTML = "<p class='muted'>No se pudo cargar la ficha de financiaciones.</p>";
    } else {
      clienteHipotecaFicha.innerHTML = "<p class='muted'>No se pudo cargar la ficha de financiaciones.</p>";
    }
  }
};

