const renderClienteDatosEconomicos = (cliente = {}, economicData = {}) => {
  if (!clienteEconomicosPanel) return;
  const current = economicData && typeof economicData === "object" ? economicData : {};
  const defaults = {
    cliente1_nombre: current.cliente1_nombre || cliente.nombre || "",
    cliente1_dni: current.cliente1_dni || cliente.nif || "",
    cliente1_telefono: current.cliente1_telefono || cliente.telefono || "",
    cliente1_email: current.cliente1_email || cliente.email || "",
    cliente1_fecha_nacimiento: current.cliente1_fecha_nacimiento || cliente.fecha_nacimiento || "",
  };
  const form = document.createElement("form");
  form.className = "form-grid";
  form.id = "clienteEconomicosForm";
  const hiddenId = document.createElement("input");
  hiddenId.type = "hidden";
  hiddenId.name = "id";
  hiddenId.value = current.id || "";
  form.appendChild(hiddenId);
  const hiddenOrigen = document.createElement("input");
  hiddenOrigen.type = "hidden";
  hiddenOrigen.name = "origen";
  hiddenOrigen.value = current.origen || "Cliente";
  form.appendChild(hiddenOrigen);
  CLIENTE_ECONOMIC_FORM_FIELDS.forEach((field) => {
    const label = document.createElement("label");
    if (field.span === 2) label.classList.add("span-2");
    label.textContent = field.label;
    let input;
    if (field.type === "textarea") {
      input = document.createElement("textarea");
      input.rows = 2;
    } else {
      input = document.createElement("input");
      input.type = field.type === "money" ? "text" : field.type;
    }
    input.name = field.name;
    if (field.required) input.required = true;
    const value = current[field.name] ?? defaults[field.name] ?? "";
    if (field.type === "date") {
      input.value = normalizeDateInput(value || "");
    } else if (field.type === "money") {
      const num = toNumber(value);
      input.value = num === null ? (value || "") : euroFormatter.format(num);
    } else {
      input.value = value || "";
    }
    label.appendChild(input);
    form.appendChild(label);
  });
  const actions = document.createElement("div");
  actions.className = "form-actions span-2";
  actions.innerHTML = `
    <button type="submit">Guardar datos económicos</button>
    <span id="clienteEconomicosStatus" class="muted"></span>
  `;
  form.appendChild(actions);
  clienteEconomicosPanel.innerHTML = "";
  clienteEconomicosPanel.appendChild(form);
  bindMoneyInputs(form);
  bindIngresosConjuntos(form);
  form.addEventListener("submit", (event) => {
    event.preventDefault();
    const statusEl = form.querySelector("#clienteEconomicosStatus");
    if (statusEl) statusEl.textContent = "Guardando...";
    const payload = Object.fromEntries(new FormData(form).entries());
    payload.empresa_nombre = resolveCrmFinEmpresaNombre();
    payload.cliente1_id = payload.cliente1_id || cliente.id || "";
    payload.cliente1_ingresos = toNumber(payload.cliente1_ingresos);
    payload.cliente2_ingresos = toNumber(payload.cliente2_ingresos);
    payload.ingresos_conjuntos = toNumber(payload.ingresos_conjuntos);
    payload.aportacion_cv = toNumber(payload.aportacion_cv);
    if (!payload.fecha) payload.fecha = new Date().toISOString().slice(0, 10);
    if (!payload.estado) payload.estado = current.estado || "En estudio";
    const endpoint = payload.id ? "/api/fin_asesoramientos_update" : "/api/fin_asesoramientos";
    fetch(endpoint, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    })
      .then((res) => res.json())
      .then((data) => {
        if (statusEl) {
          statusEl.textContent = data.error || "Guardado.";
        }
        if (!data.error && state.currentClienteId) {
          openClienteDetail(state.currentClienteId);
        }
      })
      .catch(() => {
        if (statusEl) statusEl.textContent = "Error al guardar.";
      });
  });
};

const renderClienteMiniChart = (container, items = []) => {
  if (!container) return;
  if (!items.length) {
    container.innerHTML = "<p class='muted'>Sin datos.</p>";
    return;
  }
  const maxValue = Math.max(
    1,
    ...items.map((item) => Math.abs(Number(item.value) || 0))
  );
  const wrapper = document.createElement("div");
  wrapper.className = "cliente-mini-chart";
  items.forEach((item) => {
    const row = document.createElement("div");
    row.className = "cliente-mini-chart-row";
    if (typeof item.onClick === "function") {
      row.style.cursor = "pointer";
      row.title = item.title || "Ver detalle";
      row.addEventListener("click", () => item.onClick(item));
    }
    const label = document.createElement("div");
    label.className = "cliente-mini-chart-label";
    label.textContent = item.label || "-";
    const track = document.createElement("div");
    track.className = "cliente-mini-chart-track";
    const fill = document.createElement("div");
    fill.className = "cliente-mini-chart-fill";
    const ratio = Math.max(0, Math.min(100, (Math.abs(Number(item.value) || 0) / maxValue) * 100));
    fill.style.width = `${ratio}%`;
    fill.style.background = item.color || "var(--brand)";
    track.appendChild(fill);
    const value = document.createElement("div");
    value.className = "cliente-mini-chart-value";
    value.textContent = item.display || String(item.value || 0);
    row.appendChild(label);
    row.appendChild(track);
    row.appendChild(value);
    wrapper.appendChild(row);
  });
  container.innerHTML = "";
  container.appendChild(wrapper);
};

const getSeguroRamoLabel = (value) => {
  return getSegurosRamoLabel(value);
};

const summarizeSegurosByRamo = (rows = []) => {
  const map = new Map();
  rows.forEach((row) => {
    const ramo = getSeguroRamoLabel(row.ramo);
    if (!map.has(ramo)) {
      map.set(ramo, { ramo, total: 0, primaTotal: 0, rows: [] });
    }
    const bucket = map.get(ramo);
    bucket.total += 1;
    bucket.primaTotal += parseMoneyValue(row.prima_total);
    bucket.rows.push(row);
  });
  return Array.from(map.values()).sort((a, b) => b.total - a.total);
};

const renderClienteRamoListado = (ramoLabel, rows = [], cliente = null) => {
  if (!clienteRamoListado) return;
  if (!rows.length) {
    clienteRamoListado.innerHTML = "<p class='muted'>Sin pólizas para este ramo.</p>";
    return;
  }
  const title = document.createElement("h5");
  title.textContent = `Pólizas · ${ramoLabel}`;
  const table = document.createElement("table");
  const thead = document.createElement("thead");
  const trHead = document.createElement("tr");
  ["Póliza", "Compañía", "Efecto", "Vencimiento", "Estado", "Prima", "Detalle"].forEach((col) => {
    const th = document.createElement("th");
    th.textContent = col;
    trHead.appendChild(th);
  });
  thead.appendChild(trHead);
  table.appendChild(thead);
  const tbody = document.createElement("tbody");
  rows.forEach((row) => {
    const tr = document.createElement("tr");
    const computed = computeSeguroDisplayState(row);
    const values = [
      row.poliza_numero || "-",
      row.compania || "-",
      row.fecha_efecto || "-",
      computed.vencimiento || "-",
      computed.estado || "-",
      row.prima_total ? euroFormatter.format(parseMoneyValue(row.prima_total)) : "-",
    ];
    values.forEach((value) => {
      const td = document.createElement("td");
      td.textContent = value;
      tr.appendChild(td);
    });
    const actionTd = document.createElement("td");
    const openBtn = document.createElement("button");
    openBtn.type = "button";
    openBtn.className = "secondary";
    openBtn.textContent = "Abrir póliza";
    openBtn.addEventListener("click", (event) => {
      event.stopPropagation();
      openSeguroPage(
        row,
        cliente || state.currentClienteData || { id: state.currentClienteId, nombre: row.tomador || "" },
        {
          onSaved: () => {
            const fincas = state.empresas.find((e) => e.nombre === FINCAS_COMPANY);
            if (fincas) renderFincasDashboard(fincas.id);
          },
        }
      );
    });
    actionTd.appendChild(openBtn);
    tr.appendChild(actionTd);
    tr.addEventListener("click", () =>
      openSeguroPage(
        row,
        cliente || state.currentClienteData || { id: state.currentClienteId, nombre: row.tomador || "" },
        {
          onSaved: () => {
            const fincas = state.empresas.find((e) => e.nombre === FINCAS_COMPANY);
            if (fincas) renderFincasDashboard(fincas.id);
          },
        }
      )
    );
    tbody.appendChild(tr);
  });
  table.appendChild(tbody);
  clienteRamoListado.innerHTML = "";
  clienteRamoListado.appendChild(title);
  clienteRamoListado.appendChild(table);
};

const renderClienteRamosDashboard = (rows = [], cliente = null) => {
  if (!clienteRamoKpis || !clienteChartRamos || !clienteRamoListado) return;
  state.currentClienteSegurosRows = Array.isArray(rows) ? [...rows] : [];
  const summary = summarizeSegurosByRamo(state.currentClienteSegurosRows);
  if (!summary.length) {
    clienteRamoKpis.innerHTML = "<p class='muted'>Sin pólizas para agrupar por ramo.</p>";
    clienteChartRamos.innerHTML = "<p class='muted'>Sin datos.</p>";
    clienteRamoListado.innerHTML = "<p class='muted'>Selecciona una póliza en servicios para ver detalle.</p>";
    state.currentClienteRamoSelected = "";
    return;
  }
  clienteRamoKpis.innerHTML = "";
  summary.forEach((item) => {
    const card = document.createElement("button");
    card.type = "button";
    card.className = "card cliente-ramo-kpi-card";
    if (state.currentClienteRamoSelected === item.ramo) {
      card.classList.add("active");
    }
    card.innerHTML = `
      <div class="kpi-label">${item.ramo}</div>
      <div class="kpi-value">${item.total}</div>
      <div class="muted">${euroFormatter.format(item.primaTotal)}</div>
    `;
    card.addEventListener("click", () => {
      state.currentClienteRamoSelected = item.ramo;
      renderClienteRamosDashboard(state.currentClienteSegurosRows, cliente || state.currentClienteData);
      renderClienteRamoListado(item.ramo, item.rows, cliente || state.currentClienteData);
    });
    clienteRamoKpis.appendChild(card);
  });
  renderClienteMiniChart(
    clienteChartRamos,
    summary.map((item, idx) => ({
      label: item.ramo,
      value: item.total,
      display: `${item.total} póliza${item.total === 1 ? "" : "s"}`,
      color: ["#0B1D33", "#F2C14E", "#22C55E", "#38BDF8", "#64748B"][idx % 5],
    }))
  );
  const selected =
    summary.find((item) => item.ramo === state.currentClienteRamoSelected) || summary[0];
  state.currentClienteRamoSelected = selected.ramo;
  renderClienteRamoListado(selected.ramo, selected.rows, cliente || state.currentClienteData);
};

const renderClienteMiniDashboardFromPayload = (dashboard) => {
  if (!dashboard || !clienteKpiRentabilidad || !clienteKpiPendientes || !clienteKpiCitas || !clienteKpiPrimas) {
    return false;
  }
  const rent = dashboard.rentabilidad || {};
  const realizado = Number(rent.realizado || 0);
  const cobrado = Number(rent.cobrado || 0);
  const margen = Number(rent.margen || 0);
  const primas = Number(dashboard.primas_total || 0);
  const pendientes = Number(dashboard.tareas_pendientes || 0);
  const citas = Number(dashboard.citas_programadas || 0);
  const proxima = dashboard.proxima_cita || "";
  clienteKpiRentabilidad.textContent =
    `${euroFormatter.format(realizado)} / ${euroFormatter.format(cobrado)} · ${euroFormatter.format(margen)}`;
  clienteKpiPrimas.textContent = euroFormatter.format(primas);
  clienteKpiPendientes.textContent = String(pendientes);
  clienteKpiCitas.textContent = proxima ? `${citas} · Próxima ${proxima}` : String(citas);
  const series = dashboard.series || {};
  renderClienteMiniChart(
    clienteChartRentabilidad,
    (series.rentabilidad || []).map((item, idx) => ({
      label: item.label || "-",
      value: Number(item.value || 0),
      display: euroFormatter.format(Number(item.value || 0)),
      color: ["#4f46e5", "#16a34a", "#0284c7"][idx % 3],
    }))
  );
  renderClienteMiniChart(
    clienteChartActividad,
    (series.actividad || []).map((item, idx) => ({
      label: item.label || "-",
      value: Number(item.value || 0),
      display:
        idx === 0 || (item.label || "").toLowerCase().includes("prima")
          ? euroFormatter.format(Number(item.value || 0))
          : String(Number(item.value || 0)),
      color: ["#d97706", "#7c3aed", "#0ea5e9"][idx % 3],
    }))
  );
  if (clienteMiniDashboardHint) {
    clienteMiniDashboardHint.textContent = "Dashboard consolidado de todos los servicios adscritos.";
  }
  return true;
};

const loadClienteMiniDashboard = async (clienteId, empresas = [], prefetched = null) => {
  if (!clienteKpiRentabilidad || !clienteKpiPendientes || !clienteKpiCitas || !clienteKpiPrimas) {
    return;
  }
  if (renderClienteMiniDashboardFromPayload(prefetched)) {
    return;
  }
  if (!clienteId) {
    clienteKpiRentabilidad.textContent = "-";
    clienteKpiPrimas.textContent = "-";
    clienteKpiPendientes.textContent = "-";
    clienteKpiCitas.textContent = "-";
    renderClienteMiniChart(clienteChartRentabilidad, []);
    renderClienteMiniChart(clienteChartActividad, []);
    renderClienteRamosDashboard([], null);
    return;
  }
  clienteKpiRentabilidad.textContent = "Calculando...";
  clienteKpiPrimas.textContent = "Calculando...";
  clienteKpiPendientes.textContent = "Calculando...";
  clienteKpiCitas.textContent = "Calculando...";
  if (clienteMiniDashboardHint) {
    clienteMiniDashboardHint.textContent = "Resumen operativo y económico del cliente.";
  }
  const servicios = new Set(
    (empresas || []).map((row) => normalizeSimple(row.servicio || ""))
  );
  const empresaByName = new Map((state.empresas || []).map((item) => [item.nombre, item.id]));
  const clienteNombre = String(
    ((state.clientesList || []).find((item) => item.id === clienteId)?.nombre || "")
  ).trim();
  const clienteNameKey = normalizeSimple(clienteNombre);
  const serviciosAgenda = ["seguros", "gestoria", "financiaciones", "inmobiliaria"].filter(
    (name) => !servicios.size || servicios.has(name)
  );
  const agendaServices = serviciosAgenda.length
    ? serviciosAgenda
    : ["seguros", "gestoria", "financiaciones", "inmobiliaria"];
  const accionesReqs = agendaServices.map((servicio) =>
    api(`/api/acciones?${buildAgendaActionParams(servicio, { cliente_id: clienteId }).toString()}`)
      .catch(() => ({ rows: [] }))
  );
  const trabajosReq = api(`/api/gestoria_trabajos?cliente_id=${encodeURIComponent(clienteId)}`)
    .catch(() => ({ rows: [] }));
  const segurosReq = api(`/api/seguros_cliente?cliente_id=${encodeURIComponent(clienteId)}`)
    .catch(() => ({ rows: [] }));
  const gestoriaEmpresaIds = (empresas || [])
    .filter((row) => normalizeSimple(row.servicio || "") === "gestoria")
    .map((row) => empresaByName.get(row.empresa))
    .filter(Boolean);
  const finEmpresaIds = (empresas || [])
    .filter((row) => normalizeSimple(row.servicio || "") === "financiaciones")
    .map((row) => empresaByName.get(row.empresa))
    .filter(Boolean);
  const inmoEmpresaIds = (empresas || [])
    .filter((row) => normalizeSimple(row.servicio || "") === "inmobiliaria")
    .map((row) => empresaByName.get(row.empresa))
    .filter(Boolean);
  const workspaceId = String(state.currentWorkspaceId || "").trim();
  const contaReqs = workspaceId
    ? [api(`/api/gestoria_contabilidad?workspace_id=${encodeURIComponent(workspaceId)}`).catch(() => ({ rows: [] }))]
    : (gestoriaEmpresaIds.length
        ? gestoriaEmpresaIds
        : ((state.empresas || []).find((emp) => emp.nombre === FINCAS_COMPANY)?.id
          ? [(state.empresas || []).find((emp) => emp.nombre === FINCAS_COMPANY).id]
          : [])
      ).map((empresaId) =>
        api(`/api/gestoria_contabilidad?empresa_id=${encodeURIComponent(empresaId)}`)
          .catch(() => ({ rows: [] }))
      );
  const finReqs = finEmpresaIds.map((empresaId) =>
    getTableRowsByEmpresa("hipotecas", empresaId, clienteNombre).catch(() => ({ columns: [], rows: [] }))
  );
  const inmoReqs = inmoEmpresaIds.map((empresaId) =>
    getTableRowsByEmpresa("movimientos", empresaId, clienteNombre).catch(() => ({ columns: [], rows: [] }))
  );
  try {
    const [trabajosData, segurosData, ...rest] = await Promise.all([
      trabajosReq,
      segurosReq,
      ...accionesReqs,
      ...contaReqs,
      ...finReqs,
      ...inmoReqs,
    ]);
    const accionesGroups = rest.slice(0, accionesReqs.length);
    const contaGroups = rest.slice(accionesReqs.length, accionesReqs.length + contaReqs.length);
    const finGroups = rest.slice(
      accionesReqs.length + contaReqs.length,
      accionesReqs.length + contaReqs.length + finReqs.length
    );
    const inmoGroups = rest.slice(accionesReqs.length + contaReqs.length + finReqs.length);
    const trabajos = trabajosData.rows || [];
    const seguros = segurosData.rows || [];
    renderClienteRamosDashboard(seguros, state.currentClienteData);
    const acciones = accionesGroups.flatMap((payload) => payload.rows || []);
    const movimientos = contaGroups
      .flatMap((payload) => payload.rows || [])
      .map((row) => gestoriaContaRowForCliente(row, clienteId))
      .filter(Boolean);
    const finComisiones = !clienteNameKey ? 0 : finGroups.reduce((sum, payload) => {
      const cols = payload.columns || [];
      const rows = payload.rows || [];
      const clienteCols = ["cliente", "cliente1_nombre", "cliente2_nombre"];
      const comisionCols = ["comision", "honorarios", "ingreso"];
      return sum + rows.reduce((inner, row) => {
        const clienteMatch = clienteCols.some((col) =>
          normalizeSimple(String(pickColumnValue(row, cols, [col]) || "")).includes(clienteNameKey)
        );
        if (!clienteMatch) return inner;
        return inner + parseMoneyValue(pickColumnValue(row, cols, comisionCols));
      }, 0);
    }, 0);
    const inmoComisiones = !clienteNameKey ? 0 : inmoGroups.reduce((sum, payload) => {
      const cols = payload.columns || [];
      const rows = payload.rows || [];
      return sum + rows.reduce((inner, row) => {
        const concepto = normalizeSimple(String(pickColumnValue(row, cols, ["concepto"]) || ""));
        const clienteText = normalizeSimple(
          `${pickColumnValue(row, cols, ["cliente"]) || ""} ${pickColumnValue(row, cols, ["cliente_nombre"]) || ""}`
        );
        if (!concepto.includes("compraventa") && !concepto.includes("alquiler")) return inner;
        if (!clienteText.includes(clienteNameKey)) return inner;
        return inner + parseMoneyValue(pickColumnValue(row, cols, ["comision", "ingresos", "importe"]));
      }, 0);
    }, 0);
    const segurosCartera = seguros.reduce((sum, row) => sum + parseMoneyValue(row.prima_total), 0);
    const realizado = trabajos
      .filter((row) => normalizeSimple(row.estado || "").includes("final"))
      .reduce((sum, row) => sum + parseMoneyValue(row.importe), 0);
    const cobrado = movimientos
      .filter((row) => {
        const tipo = normalizeSimple(row.tipo || "");
        return tipo !== "gasto";
      })
      .reduce((sum, row) => sum + parseMoneyValue(row.importe_asignado), 0);
    // Rentabilidad sin primas: primas se muestran aparte como KPI de cartera.
    const realizadoTotal = realizado + finComisiones + inmoComisiones;
    const cobradoTotal = cobrado + finComisiones + inmoComisiones;
    const margen = cobradoTotal - realizadoTotal;
    const pendientesTrabajos = trabajos.filter((row) => {
      const estado = normalizeSimple(row.estado || "");
      return estado && !estado.includes("final") && !estado.includes("cancel");
    }).length;
    const pendientesAcciones = acciones.filter((row) => {
      const estado = normalizeSimple(row.estado || "");
      return !estado || (!estado.includes("hecho") && !estado.includes("cancel") && !estado.includes("final"));
    }).length;
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const citas = acciones.filter((row) => {
      const fecha = parseAgendaDate(row.fecha);
      if (!fecha) return false;
      const estado = normalizeSimple(row.estado || "");
      return fecha >= today && !estado.includes("cancel") && !estado.includes("hecho");
    });
    const nextCita = citas
      .map((row) => row.fecha)
      .filter(Boolean)
      .sort()[0];
    clienteKpiRentabilidad.textContent =
      `${euroFormatter.format(realizadoTotal)} / ${euroFormatter.format(cobradoTotal)} · ${euroFormatter.format(margen)}`;
    clienteKpiPrimas.textContent = euroFormatter.format(segurosCartera);
    clienteKpiPendientes.textContent = String(pendientesTrabajos + pendientesAcciones);
    clienteKpiCitas.textContent = nextCita ? `${citas.length} · Próxima ${nextCita}` : String(citas.length);
    renderClienteMiniChart(clienteChartRentabilidad, [
      {
        label: "Realizado",
        value: realizadoTotal,
        display: euroFormatter.format(realizadoTotal),
        color: "#4f46e5",
      },
      {
        label: "Cobrado",
        value: cobradoTotal,
        display: euroFormatter.format(cobradoTotal),
        color: "#16a34a",
      },
      {
        label: "Margen",
        value: Math.abs(margen),
        display: euroFormatter.format(margen),
        color: margen >= 0 ? "#0284c7" : "#dc2626",
      },
    ]);
    renderClienteMiniChart(clienteChartActividad, [
      {
        label: "Primas",
        value: segurosCartera,
        display: euroFormatter.format(segurosCartera),
        color: "#d97706",
      },
      {
        label: "Pendientes",
        value: pendientesTrabajos + pendientesAcciones,
        display: String(pendientesTrabajos + pendientesAcciones),
        color: "#7c3aed",
      },
      {
        label: "Citas",
        value: citas.length,
        display: String(citas.length),
        color: "#0ea5e9",
      },
    ]);
    if (clienteMiniDashboardHint) {
      const parts = [];
      if (segurosCartera) parts.push(`Seguros ${euroFormatter.format(segurosCartera)}`);
      if (realizado) parts.push(`Gestoria ${euroFormatter.format(realizado)}`);
      if (finComisiones) parts.push(`Fin ${euroFormatter.format(finComisiones)}`);
      if (inmoComisiones) parts.push(`Inmo ${euroFormatter.format(inmoComisiones)}`);
      clienteMiniDashboardHint.textContent =
        `Multiservicio adscrito: ${parts.length ? parts.join(" · ") : "sin importes disponibles"}.`;
    }
  } catch {
    clienteKpiRentabilidad.textContent = "-";
    clienteKpiPrimas.textContent = "-";
    clienteKpiPendientes.textContent = "-";
    clienteKpiCitas.textContent = "-";
    renderClienteMiniChart(clienteChartRentabilidad, []);
    renderClienteMiniChart(clienteChartActividad, []);
    renderClienteRamosDashboard([], state.currentClienteData);
    if (clienteMiniDashboardHint) {
      clienteMiniDashboardHint.textContent = "No se pudo calcular el dashboard del cliente.";
    }
  }
};

const loadClienteFacturasServicios = async (clienteId, empresas = [], prefetchedRows = null) => {
  if (!clienteFacturas) return;
  if (!clienteId) {
    clienteFacturas.innerHTML = "<p class='muted'>Sin cliente seleccionado.</p>";
    return;
  }
  if (Array.isArray(prefetchedRows)) {
    const rows = [...prefetchedRows]
      .map((row) => gestoriaContaRowForCliente(row, clienteId) || row)
      .sort((a, b) => String(b.fecha || "").localeCompare(String(a.fecha || "")));
    if (!rows.length) {
      clienteFacturas.innerHTML = "<p class='muted'>Sin facturas registradas.</p>";
      return;
    }
    const table = document.createElement("table");
    const thead = document.createElement("thead");
    const trHead = document.createElement("tr");
    ["Fecha", "Concepto", "Tipo", "Importe", "Notas"].forEach((col) => {
      const th = document.createElement("th");
      th.textContent = col;
      trHead.appendChild(th);
    });
    thead.appendChild(trHead);
    table.appendChild(thead);
    const tbody = document.createElement("tbody");
    rows.slice(0, 200).forEach((row) => {
      const tr = document.createElement("tr");
      const values = [
        row.fecha || "-",
        row.concepto || "-",
        row.tipo || "-",
        parseMoneyValue(row.importe_asignado ?? row.importe)
          ? euroFormatter.format(parseMoneyValue(row.importe_asignado ?? row.importe))
          : "-",
        row.notas || "-",
      ];
      values.forEach((value) => {
        const td = document.createElement("td");
        td.textContent = value;
        tr.appendChild(td);
      });
      tbody.appendChild(tr);
    });
    table.appendChild(tbody);
    clienteFacturas.innerHTML = "";
    clienteFacturas.appendChild(table);
    return;
  }
  const workspaceId = String(state.currentWorkspaceId || "").trim();
  const empresaByName = new Map((state.empresas || []).map((item) => [item.nombre, item.id]));
  const gestoriaEmpresaIds = workspaceId
    ? []
    : (empresas || [])
        .filter((row) => normalizeSimple(row.servicio || "") === "gestoria")
        .map((row) => empresaByName.get(row.empresa))
        .filter(Boolean);
  if (!workspaceId && !gestoriaEmpresaIds.length) {
    clienteFacturas.innerHTML = "<p class='muted'>Sin facturación registrada para servicios adscritos.</p>";
    return;
  }
  const payloads = await Promise.all(
    workspaceId
      ? [api(`/api/gestoria_contabilidad?workspace_id=${encodeURIComponent(workspaceId)}`).catch(() => ({ rows: [] }))]
      : gestoriaEmpresaIds.map((id) =>
          api(`/api/gestoria_contabilidad?empresa_id=${encodeURIComponent(id)}`).catch(() => ({ rows: [] }))
        )
  );
  const rows = payloads
    .flatMap((item) => item.rows || [])
    .map((row) => gestoriaContaRowForCliente(row, clienteId))
    .filter(Boolean)
    .sort((a, b) => String(b.fecha || "").localeCompare(String(a.fecha || "")));
  if (!rows.length) {
    clienteFacturas.innerHTML = "<p class='muted'>Sin facturas registradas.</p>";
    return;
  }
  const table = document.createElement("table");
  const thead = document.createElement("thead");
  const trHead = document.createElement("tr");
  ["Fecha", "Concepto", "Tipo", "Importe", "Notas"].forEach((col) => {
    const th = document.createElement("th");
    th.textContent = col;
    trHead.appendChild(th);
  });
  thead.appendChild(trHead);
  table.appendChild(thead);
  const tbody = document.createElement("tbody");
  rows.slice(0, 200).forEach((row) => {
    const tr = document.createElement("tr");
    const values = [
      row.fecha || "-",
      row.concepto || "-",
      row.tipo || "-",
      parseMoneyValue(row.importe_asignado ?? row.importe)
        ? euroFormatter.format(parseMoneyValue(row.importe_asignado ?? row.importe))
        : "-",
      row.notas || "-",
    ];
    values.forEach((value) => {
      const td = document.createElement("td");
      td.textContent = value;
      tr.appendChild(td);
    });
    tbody.appendChild(tr);
  });
  table.appendChild(tbody);
  clienteFacturas.innerHTML = "";
  clienteFacturas.appendChild(table);
};

const loadClienteHistoricoServicios = async (clienteId, empresas = [], prefetchedRows = null) => {
  if (!clienteTrabajos) return;
  if (!clienteId) {
    clienteTrabajos.innerHTML = "<p class='muted'>Sin cliente seleccionado.</p>";
    return;
  }
  if (Array.isArray(prefetchedRows)) {
    const timeline = [...prefetchedRows].sort((a, b) => String(b.fecha || "").localeCompare(String(a.fecha || "")));
    if (!timeline.length) {
      clienteTrabajos.innerHTML = "<p class='muted'>Sin histórico de trabajos realizados.</p>";
      return;
    }
    const table = document.createElement("table");
    const thead = document.createElement("thead");
    const trHead = document.createElement("tr");
    ["Fecha", "Servicio", "Concepto", "Estado", "Importe"].forEach((col) => {
      const th = document.createElement("th");
      th.textContent = col;
      trHead.appendChild(th);
    });
    thead.appendChild(trHead);
    table.appendChild(thead);
    const tbody = document.createElement("tbody");
    timeline.slice(0, 300).forEach((row) => {
      const tr = document.createElement("tr");
      const values = [
        row.fecha || "-",
        getServiceLabelFromNormalized(row.servicio || row.service || "") || row.servicio || "-",
        row.concepto || "-",
        row.estado || "-",
        row.importe ? euroFormatter.format(parseMoneyValue(row.importe)) : "-",
      ];
      values.forEach((value) => {
        const td = document.createElement("td");
        td.textContent = value;
        tr.appendChild(td);
      });
      tbody.appendChild(tr);
    });
    table.appendChild(tbody);
    clienteTrabajos.innerHTML = "";
    clienteTrabajos.appendChild(table);
    return;
  }
  const serviceSet = new Set((empresas || []).map((row) => normalizeSimple(row.servicio || "")));
  const tasks = [];
  if (serviceSet.has("gestoria")) {
    tasks.push(
      api(`/api/gestoria_trabajos?cliente_id=${encodeURIComponent(clienteId)}`)
        .then((data) => ({ kind: "gestoria", rows: data.rows || [] }))
        .catch(() => ({ kind: "gestoria", rows: [] }))
    );
  }
  if (serviceSet.has("seguros")) {
    tasks.push(
      api(`/api/seguros_cliente?cliente_id=${encodeURIComponent(clienteId)}`)
        .then((data) => ({ kind: "seguros", rows: data.rows || [] }))
        .catch(() => ({ kind: "seguros", rows: [] }))
    );
  }
  if (!tasks.length) {
    clienteTrabajos.innerHTML = "<p class='muted'>Sin histórico para servicios adscritos.</p>";
    return;
  }
  const datasets = await Promise.all(tasks);
  const timeline = [];
  datasets.forEach((dataset) => {
    if (dataset.kind === "gestoria") {
      (dataset.rows || []).forEach((row) => {
        timeline.push({
          fecha: row.fecha_fin || row.fecha_inicio || "",
          servicio: "Gestoría",
          concepto: row.tipo_trabajo || "Trabajo",
          estado: row.estado || "-",
          importe: row.importe || "",
        });
      });
    } else if (dataset.kind === "seguros") {
      (dataset.rows || []).forEach((row) => {
        const computed = computeSeguroDisplayState(row);
        timeline.push({
          fecha: computed.vencimiento || row.fecha_efecto || "",
          servicio: "Seguros",
          concepto: `${row.compania || "Seguro"} ${row.poliza_numero || ""}`.trim(),
          estado: computed.estado || "-",
          importe: row.prima_total || "",
        });
      });
    }
  });
  timeline.sort((a, b) => String(b.fecha || "").localeCompare(String(a.fecha || "")));
  if (!timeline.length) {
    clienteTrabajos.innerHTML = "<p class='muted'>Sin histórico de trabajos realizados.</p>";
    return;
  }
  const table = document.createElement("table");
  const thead = document.createElement("thead");
  const trHead = document.createElement("tr");
  ["Fecha", "Servicio", "Concepto", "Estado", "Importe"].forEach((col) => {
    const th = document.createElement("th");
    th.textContent = col;
    trHead.appendChild(th);
  });
  thead.appendChild(trHead);
  table.appendChild(thead);
  const tbody = document.createElement("tbody");
  timeline.slice(0, 300).forEach((row) => {
    const tr = document.createElement("tr");
    const values = [
      row.fecha || "-",
      row.servicio || "-",
      row.concepto || "-",
      row.estado || "-",
      row.importe ? euroFormatter.format(parseMoneyValue(row.importe)) : "-",
    ];
    values.forEach((value) => {
      const td = document.createElement("td");
      td.textContent = value;
      tr.appendChild(td);
    });
    tbody.appendChild(tr);
  });
  table.appendChild(tbody);
  clienteTrabajos.innerHTML = "";
  clienteTrabajos.appendChild(table);
};

const loadClienteTrabajosPlanificados = async (clienteId, empresas = []) => {
  if (!clienteTrabajosPlanificados) return;
  if (!clienteId) {
    clienteTrabajosPlanificados.innerHTML = "<p class='muted'>Sin cliente seleccionado.</p>";
    return;
  }
  const serviceSet = new Set((empresas || []).map((row) => normalizeSimple(row.servicio || "")));
  if (!serviceSet.size) {
    clienteTrabajosPlanificados.innerHTML = "<p class='muted'>Sin servicios asignados.</p>";
    return;
  }
  const hasGestoria = serviceSet.has("gestoria") || serviceSet.has("gestoría");
  const hasSeguros = serviceSet.has("seguros");
  const hasFin = serviceSet.has("financiaciones") || serviceSet.has("hipotecas");
  const hasInmo = serviceSet.has("inmobiliaria");
  try {
    const [
      gestoriaCfg,
      contaTasks,
      modelos,
      trabajosGestoria,
      accionesGestoria,
      accionesSeguros,
      accionesFin,
      accionesInmo,
    ] = await Promise.all([
      hasGestoria
        ? api(`/api/cliente_gestoria?cliente_id=${encodeURIComponent(clienteId)}`).catch(() => ({ row: {} }))
        : Promise.resolve({ row: {} }),
      hasGestoria
        ? api(`/api/gestoria_conta_tasks?cliente_id=${encodeURIComponent(clienteId)}`).catch(() => ({ rows: [] }))
        : Promise.resolve({ rows: [] }),
      hasGestoria
        ? api(`/api/gestoria_modelos?cliente_id=${encodeURIComponent(clienteId)}`).catch(() => ({ rows: [] }))
        : Promise.resolve({ rows: [] }),
      hasGestoria
        ? api(`/api/gestoria_trabajos?cliente_id=${encodeURIComponent(clienteId)}`).catch(() => ({ rows: [] }))
        : Promise.resolve({ rows: [] }),
      hasGestoria
        ? api(`/api/acciones?${buildAgendaActionParams("gestoria", { cliente_id: clienteId }).toString()}`).catch(() => ({ rows: [] }))
        : Promise.resolve({ rows: [] }),
      hasSeguros
        ? api(`/api/acciones?${buildAgendaActionParams("seguros", { cliente_id: clienteId }).toString()}`).catch(() => ({ rows: [] }))
        : Promise.resolve({ rows: [] }),
      hasFin
        ? api(`/api/acciones?${buildAgendaActionParams("financiaciones", { cliente_id: clienteId }).toString()}`).catch(() => ({ rows: [] }))
        : Promise.resolve({ rows: [] }),
      hasInmo
        ? api(`/api/acciones?${buildAgendaActionParams("inmobiliaria", { cliente_id: clienteId }).toString()}`).catch(() => ({ rows: [] }))
        : Promise.resolve({ rows: [] }),
    ]);
    const cfg = gestoriaCfg.row || {};
    const pendingConta = (contaTasks.rows || []).filter((row) => {
      const estado = normalizeSimple(row.estado || "");
      return !estado || (!estado.includes("hecho") && !estado.includes("presentado") && !estado.includes("final"));
    }).length;
    const pendingModelos = (modelos.rows || []).filter((row) => {
      const estado = normalizeSimple(row.estado || "");
      return !estado || (!estado.includes("presentado") && !estado.includes("hecho"));
    }).length;
    const pendingGestoriaJobs = (trabajosGestoria.rows || []).filter((row) => {
      const estado = normalizeSimple(row.estado || "");
      return !estado || (!estado.includes("final") && !estado.includes("cancel"));
    }).length;
    const pendingGestoriaAcciones = (accionesGestoria.rows || []).filter((row) => {
      const estado = normalizeSimple(row.estado || "");
      return !estado || (!estado.includes("hecho") && !estado.includes("final") && !estado.includes("cancel"));
    }).length;
    const pendingSegurosAcciones = (accionesSeguros.rows || []).filter((row) => {
      const estado = normalizeSimple(row.estado || "");
      return !estado || (!estado.includes("hecho") && !estado.includes("final") && !estado.includes("cancel"));
    }).length;
    const pendingFinAcciones = (accionesFin.rows || []).filter((row) => {
      const estado = normalizeSimple(row.estado || "");
      return !estado || (!estado.includes("hecho") && !estado.includes("final") && !estado.includes("cancel"));
    }).length;
    const pendingInmoAcciones = (accionesInmo.rows || []).filter((row) => {
      const estado = normalizeSimple(row.estado || "");
      return !estado || (!estado.includes("hecho") && !estado.includes("final") && !estado.includes("cancel"));
    }).length;

    const planRows = [];
    if (hasGestoria) {
      if (Number(cfg.mod_contable || 0)) {
        planRows.push({ servicio: "Gestoría", tarea: "Contabilidad periódica", indicador: `${pendingConta} pendientes`, estado: pendingConta ? "En curso" : "Al día" });
      }
      if (Number(cfg.mod_fiscal || 0)) {
        planRows.push({ servicio: "Gestoría", tarea: "Modelos fiscales", indicador: `${pendingModelos} pendientes`, estado: pendingModelos ? "Pendiente" : "Al día" });
      }
      if (Number(cfg.mod_laboral || 0)) {
        planRows.push({ servicio: "Gestoría", tarea: "Gestiones laborales", indicador: `${pendingGestoriaJobs} en curso`, estado: pendingGestoriaJobs ? "En curso" : "Sin carga" });
      }
      if (Number(cfg.mod_renta || 0)) {
        planRows.push({ servicio: "Gestoría", tarea: "Renta / expedientes", indicador: `${pendingGestoriaAcciones} acciones`, estado: pendingGestoriaAcciones ? "Seguimiento" : "Sin pendientes" });
      }
      if (Number(cfg.mod_registro || 0) || Number(cfg.mod_trafico || 0) || Number(cfg.mod_puntuales || 0)) {
        planRows.push({ servicio: "Gestoría", tarea: "Gestiones administrativas", indicador: `${pendingGestoriaAcciones} acciones`, estado: pendingGestoriaAcciones ? "Seguimiento" : "Sin pendientes" });
      }
    }
    if (hasSeguros) {
      planRows.push({ servicio: "Seguros", tarea: "Seguimiento de pólizas y renovaciones", indicador: `${pendingSegurosAcciones} acciones`, estado: pendingSegurosAcciones ? "Seguimiento" : "Sin pendientes" });
    }
    if (hasFin) {
      planRows.push({ servicio: "Financiaciones", tarea: "Seguimiento de expedientes", indicador: `${pendingFinAcciones} acciones`, estado: pendingFinAcciones ? "Seguimiento" : "Sin pendientes" });
    }
    if (hasInmo) {
      planRows.push({ servicio: "Inmobiliaria", tarea: "Gestión comercial activa", indicador: `${pendingInmoAcciones} acciones`, estado: pendingInmoAcciones ? "Seguimiento" : "Sin pendientes" });
    }

    if (!planRows.length) {
      clienteTrabajosPlanificados.innerHTML = "<p class='muted'>No hay módulos configurados aún para generar plan de trabajo.</p>";
      return;
    }
    const table = document.createElement("table");
    const thead = document.createElement("thead");
    const trHead = document.createElement("tr");
    ["Servicio", "Trabajo a realizar", "Indicador", "Estado"].forEach((col) => {
      const th = document.createElement("th");
      th.textContent = col;
      trHead.appendChild(th);
    });
    thead.appendChild(trHead);
    table.appendChild(thead);
    const tbody = document.createElement("tbody");
    planRows.forEach((row) => {
      const tr = document.createElement("tr");
      [row.servicio, row.tarea, row.indicador, row.estado].forEach((value) => {
        const td = document.createElement("td");
        td.textContent = value;
        tr.appendChild(td);
      });
      tbody.appendChild(tr);
    });
    table.appendChild(tbody);
    clienteTrabajosPlanificados.innerHTML = "";
    clienteTrabajosPlanificados.appendChild(table);
  } catch {
    clienteTrabajosPlanificados.innerHTML = "<p class='muted'>No se pudo cargar el plan operativo.</p>";
  }
};

