	if (coreCards) {
			  coreCards.addEventListener("click", (event) => {
			    const target = closestFromEvent(event, "[data-action]");
			    if (!target || !coreCards.contains(target)) {
			      return;
		    }
		    const action = target.dataset.action;
	    const authUser = getAuthScopeUser();
	    const fallbackLink = target.tagName === "A" ? target : target.querySelector("a[href]");
	    const fallbackHref = (() => {
	      const raw = fallbackLink?.getAttribute ? fallbackLink.getAttribute("href") : "";
	      return String(raw || "").trim();
	    })();
	    const fallbackUrl = (() => {
	      try {
	        if (!fallbackHref) return null;
	        return new URL(fallbackHref, window.location.origin);
	      } catch {
	        return null;
	      }
	    })();
		    const fallbackNavigate = () => {
		      try {
		        if (fallbackLink && fallbackLink.href) {
		          window.location.href = fallbackLink.href;
		        } else if (fallbackUrl) {
		          window.location.href = fallbackUrl.toString();
		        }
		      } catch (e) {}
		    };
		    const workspaceFromFallback = (() => {
		      try {
		        const raw = fallbackUrl?.searchParams?.get("workspace") || "";
		        return normalizeTenantWorkspaceSlug(String(raw || "").trim(), "");
		      } catch {
        return "";
      }
    })();
	    // Si aún no hay sesión en memoria (boot lento / SW viejo), dejamos que el enlace navegue normal.
	    if (!authUser?.id) {
	      fallbackNavigate();
	      return;
	    }
    if (target.tagName === "A") {
      event.preventDefault();
    }
		    try {
		      if (action === "holding") {
		        openHolding();
		      } else if (action === "holding-workspaces") {
		        // Home: acceso directo a la vista de workspaces (admin).
		        openHolding({ mode: "platform", view: "tenant" });
		      } else if (action === "holding-admin") {
		        openHolding({ mode: "platform", view: "overview" });
		      } else if (action === "holding-tenant") {
		        openHolding({ mode: "tenant", workspace: workspaceFromFallback || resolveDefaultTenantWorkspaceSlug(), view: "overview" });
		      } else if (String(action || "").startsWith("home-workspace:")) {
	        const rawWorkspace = String(action || "").split(":").slice(1).join(":").trim();
	        const workspace = normalizeTenantWorkspaceSlug(rawWorkspace, "") || workspaceFromFallback || resolveDefaultTenantWorkspaceSlug();
	        const view = "operations";
	        // Evita el reload completo cuando el usuario pulsa "Entrar" dentro de la card.
	        if (fallbackLink && fallbackLink.tagName === "A") {
	          event.preventDefault();
	        }
	        openHolding({ mode: "tenant", workspace, view });
	      } else if (action === "time-punch") {
	        openHomeTimePunchModal({ persist: true });
	      } else if (action === "time-home") {
	        openHolding({ mode: "tenant", workspace: workspaceFromFallback || resolveDefaultTenantWorkspaceSlug(), view: "motores", engine: "registro_horario" });
	        window.setTimeout(() => {
          focusWorkspaceEngine("registro_horario", workspaceTimeSummary, { forceTenantView: true });
        }, 250);
      } else if (action === "crm-inmo") {
        openCrmInmobiliario();
      } else if (action === "crm-gestoria") {
        openGestoriaCrm();
      } else if (action === "crm-seguros") {
        openSegurosCrm();
      } else if (action === "crm-fin") {
        openFinCrm();
      } else if (action === "clientes") {
        openClientesModule();
      } else if (action === "agenda") {
        openAgenda();
	      } else if (action === "admin") {
	        openAdmin();
		      } else if (action === "rrhh-home") {
		        const workspace = normalizeTenantWorkspaceSlug(
		          workspaceFromFallback || state.currentWorkspaceTarget || state.currentWorkspaceName || DEFAULT_TENANT_WORKSPACE_SLUG
		        );
		        // La card Personal siempre abre RRHH en modo self (también para admins).
		        openHolding({ mode: "tenant", workspace, view: "rrhh", rrhh: "self" });
		      } else {
		        // Fallback defensivo: si aparece una nueva card sin handler, navega al href real.
		        fallbackNavigate();
		      }
	    } catch (error) {
	      // Importante: si hay un error JS al abrir (estado incompleto / caché vieja),
	      // no bloqueamos el acceso: navegamos al href real.
	      fallbackNavigate();
    }
  });
}

viewTabs.addEventListener("click", (event) => {
  const btn = closestFromEvent(event, ".tab");
  if (!btn) return;
  const requestedTab = String(btn.dataset.tab || "").trim();
  // Fase 1 (guardarraíl): los CRMs de servicio no dependen de la empresa "actual".
  // Si el usuario navega por pestañas, garantizamos que el contexto (empresa interna) sea el correcto.
  if (requestedTab === "crm") {
    openCrmInmobiliario();
    return;
  }
  if (requestedTab === "seguros-crm") {
    openSegurosCrm();
    return;
  }
  if (requestedTab === "fin-crm" || requestedTab === "fin-sim") {
    openFinServiceTab(requestedTab);
    return;
  }
  if (requestedTab.startsWith("gestoria-")) {
    openGestoriaServiceTab(requestedTab);
    return;
  }
  setTab(requestedTab);
  if (state.currentModule === "clientes") {
    loadClientesTable();
    updateTableVisibility();
    return;
  }
  if (currentTab === "crm") {
    setCrmWorkspaceView(state.crmWorkspaceView || "resumen");
    loadCrmCaptaciones();
    loadCrmInmuebles();
    loadCrmCompraventas();
    updateTableVisibility();
    return;
  }
  if (currentTab === "gestoria-crm") {
    loadGestoriaCrm();
    updateTableVisibility();
    return;
  }
  if (currentTab === "gestoria-docs") {
    loadGestoriaDocsWorkspace();
    updateTableVisibility();
    return;
  }
  if (currentTab === "gestoria-dash") {
    loadGestoriaDashboard();
    updateTableVisibility();
    return;
  }
  if (currentTab === "gestoria-conta") {
    loadGestoriaContabilidad();
    loadGestoriaContaQueue();
    updateTableVisibility();
    return;
  }
  if (currentTab === "gestoria-agenda") {
    const empresa = resolveCrmGestoriaEmpresa();
    if (empresa) {
      loadAcciones("gestoria", isTenantWorkspaceMode() ? "" : resolveLegacyEmpresaId(empresa), gestoriaAgendaTable, gestoriaAgendaInfo);
    }
    updateTableVisibility();
    return;
  }
  if (currentTab === "gestoria-fact") {
    loadGestoriaFact();
    updateTableVisibility();
    return;
  }
  if (currentTab === "seguros-crm") {
    loadSegurosCrm();
    updateTableVisibility();
    return;
  }
  if (currentTab === "fin-crm") {
    loadFinCrm();
    updateTableVisibility();
    return;
  }
  if (currentTab === "operativa") {
    const resumenItem = state.resumen.find(
      (item) => item.empresa === state.empresas.find((e) => e.id === empresaSelect.value)?.nombre
    );
    setDefaultTableForCompany(resumenItem);
    ensureOperativaTable();
  } else {
    tablaSelect.value = "movimientos";
  }
  loadTable();
  updateTableVisibility();
});

