if (crmWorkspaceTabs) {
  crmWorkspaceTabs.addEventListener("click", (event) => {
    const actionBtn = closestFromEvent(event, "[data-crm-action]");
    if (actionBtn) {
      const action = String(actionBtn.dataset.crmAction || "").trim();
      if (action === "recientes") {
        event.preventDefault();
        event.stopPropagation();
        const isOpen = crmRecentMenu ? !crmRecentMenu.classList.contains("hidden") : false;
        setCrmRecentOpen(!isOpen);
        return;
      }
    }
    const quick = closestFromEvent(event, "[data-crm-quick]");
    if (quick) {
      applyCrmTecnocloudQuickSearch(String(quick.dataset.crmQuick || "").trim());
      return;
    }
    const svcBtn = closestFromEvent(event, "[data-crm-service-tab]");
    if (svcBtn) {
      const tab = String(svcBtn.dataset.crmServiceTab || "").trim();
      if (tab) {
        try {
          openGestoriaServiceTab(tab);
        } catch {
          try {
            setTab(tab);
          } catch (e) {}
        }
      }
      return;
    }
    const btn = closestFromEvent(event, "[data-crm-view]");
    if (!btn) return;
    const view = String(btn.dataset.crmView || "").trim();
    if (view === "agenda") {
      const preset = String(btn.dataset.crmAgendaPreset || "").trim();
      if (preset && crmAgendaPreset) {
        crmAgendaPreset.value = preset;
        setCrmAgendaView("list");
        setCrmWorkspaceView("agenda");
        loadCrmAgenda();
        return;
      }
    }
    if (view === "agenda" && btn.dataset.crmAgendaOpen) {
      const desired = normalizeCrmAgendaView(btn.dataset.crmAgendaOpen || "day");
      setCrmAgendaAnchorDay(formatAgendaDate(new Date()));
      setCrmAgendaView(desired);
      setCrmWorkspaceView("agenda");
      loadCrmAgenda();
      return;
    }
    setCrmWorkspaceView(view);
    const etapa = String(btn.dataset.etapa || "").trim();
    if (view === "captaciones" && etapa) {
      if (crmEtapaFilter) crmEtapaFilter.value = etapa;
      if (crmEtapaFilterMirror) crmEtapaFilterMirror.value = etapa;
      loadCrmCaptaciones();
    }
  });
}

if (crmLightningSidebar) {
  crmLightningSidebar.addEventListener("click", (event) => {
    const quick = closestFromEvent(event, "[data-crm-quick]");
    if (quick) {
      applyCrmTecnocloudQuickSearch(String(quick.dataset.crmQuick || "").trim());
      return;
    }
    const gestoriaMore = closestFromEvent(event, "[data-gestoria-more]");
    if (gestoriaMore) {
      const key = String(gestoriaMore.dataset.gestoriaMore || "").trim();
      try {
        const details = gestoriaMore.closest("details");
        if (details) details.open = false;
      } catch (e) {}
      if (!key) return;
      if (key === "config") {
        openGestoriaServiceTab("gestoria-dash");
        window.setTimeout(() => {
          try {
            setGestoriaDashboardView("servicios");
          } catch (e) {}
          window.setTimeout(() => {
            try {
              focusElementInView(gestoriaTrabajoTiposCard || gestoriaDashServiciosPaneAnalytics);
            } catch (e) {}
          }, 0);
        }, 0);
        return;
      }
      if (key === "conta") {
        openGestoriaServiceTab("gestoria-conta");
        window.setTimeout(() => {
          try {
            focusElementInView(gestoriaContabilidadForm || gestoriaContaSection);
          } catch (e) {}
        }, 0);
        return;
      }
      if (key === "informes") {
        openGestoriaServiceTab("gestoria-dash");
        window.setTimeout(() => {
          try {
            setGestoriaDashboardView("rentas");
          } catch (e) {}
          window.setTimeout(() => {
            try {
              focusElementInView(gestoriaDashRentaContent || gestoriaDashboardTabs);
            } catch (e) {}
          }, 0);
        }, 0);
        return;
      }
      if (key === "import") {
        openGestoriaRentaCampaign();
        window.setTimeout(() => {
          try {
            focusElementInView(gestoriaCrmUploadRentaBtn || gestoriaCrmSection);
          } catch (e) {}
        }, 0);
        return;
      }
      if (key === "audit") {
        openGestoriaServiceTab("gestoria-docs");
        window.setTimeout(() => {
          try {
            focusElementInView(gestoriaAuditTable || gestoriaDocsSection);
          } catch (e) {}
        }, 0);
        return;
      }
      if (key === "ayuda") {
        try {
          openCrmSupportModal();
        } catch (e) {}
        return;
      }
      return;
    }
    const svcBtn = closestFromEvent(event, "[data-crm-service-tab]");
    if (svcBtn) {
      const tab = String(svcBtn.dataset.crmServiceTab || "").trim();
      if (tab) {
        try {
          openGestoriaServiceTab(tab);
        } catch {
          try {
            setTab(tab);
          } catch (e) {}
        }
      }
      return;
    }
    const manualBtn = closestFromEvent(event, "[data-crm-manual]");
    if (manualBtn) {
      event.preventDefault();
      event.stopPropagation();
      const key = String(manualBtn.dataset.crmManual || "").trim();
      if (key === "inmobiliaria") {
        window.open("/manual_inmobiliaria.html", "_blank", "noopener,noreferrer");
        return;
      }
    }
    const adminBtn = closestFromEvent(event, "[data-crm-admin]");
    if (adminBtn) {
      const key = String(adminBtn.dataset.crmAdmin || "").trim();
      if (key === "users") {
        openAdmin();
        return;
      }
      if (key === "workspaces") {
        openHolding({ mode: "tenant", view: "overview" });
        return;
      }
    }
    const btn = closestFromEvent(event, "[data-crm-view]");
    if (!btn) return;
    const view = String(btn.dataset.crmView || "").trim();
    if (view === "agenda") {
      // Paridad con tabs superiores: en Agenda, además de cambiar la vista, cargamos datos y respetamos
      // atajos de apertura (día/semana/mes) si existen.
      const desired = normalizeCrmAgendaView(btn.dataset.crmAgendaOpen || state.crmAgendaView || "week");
      try {
        setCrmAgendaAnchorDay(formatAgendaDate(new Date()));
      } catch (e) {}
      try {
        setCrmAgendaView(desired);
      } catch (e) {}
      setCrmWorkspaceView("agenda");
      loadCrmAgenda();
      return;
    }
    setCrmWorkspaceView(view);
    const etapa = String(btn.dataset.etapa || "").trim();
    if (view === "captaciones" && etapa) {
      if (crmEtapaFilter) crmEtapaFilter.value = etapa;
      if (crmEtapaFilterMirror) crmEtapaFilterMirror.value = etapa;
      loadCrmCaptaciones();
    }
  });
}

