if (crmAgendaForm) {
  const crmAgendaTipoSelect = crmAgendaForm.querySelector('select[name="tipo"]');
  if (crmAgendaTipoSelect) {
    crmAgendaTipoSelect.addEventListener("change", () => {
      syncPropuestaMoneyFields(crmAgendaForm);
    });
  }
  syncPropuestaMoneyFields(crmAgendaForm);
  crmAgendaForm.addEventListener("submit", (event) => {
    event.preventDefault();
    if (crmAgendaStatus) crmAgendaStatus.textContent = "Guardando...";
    const formData = new FormData(crmAgendaForm);
    const payload = Object.fromEntries(formData.entries());
    // Guardrail: creación de actividad/cita nunca debe mandar `id`.
    // Si por cualquier bug del DOM apareciera, podría provocar un update accidental en otros flujos.
    if ("id" in payload) delete payload.id;
    payload.empresa_nombre = resolveCrmInmoEmpresaNombre();
    payload.servicio = "inmobiliaria";
    apiPost("/api/acciones", payload)
      .then((data) => {
        if (crmAgendaStatus) crmAgendaStatus.textContent = data.error || "Guardado.";
        if (data.error) return;
        crmAgendaForm.reset();
        syncPropuestaMoneyFields(crmAgendaForm);
        ensureCrmAgendaSelectors().catch(() => {});
        if (data?.accion) {
          upsertCrmAgendaActionRow(data.accion);
          scheduleSave("crm-agenda-revalidate", () => loadCrmAgenda(), 350);
        } else {
          loadCrmAgenda();
        }
      })
      .catch(() => {
        if (crmAgendaStatus) crmAgendaStatus.textContent = "Error al guardar.";
      });
  });
}

