if (actionModalSave) {
  actionModalSave.addEventListener("click", () => {
    if (actionModalStatus) actionModalStatus.textContent = "Guardando...";
    const editId = String(state.actionModalEditId || "").trim();
    const editSnapshot = state.actionModalEditSnapshot && typeof state.actionModalEditSnapshot === "object"
      ? state.actionModalEditSnapshot
      : null;
    const serviceValue = actionModalServicioSelect ? actionModalServicioSelect.value : "";
    const service = serviceValue || "gestoria";
    if (!serviceValue) {
      if (actionModalStatus) actionModalStatus.textContent = "Selecciona servicio.";
      return;
    }
    const empresaNombre =
      service === "financiaciones"
        ? resolveCrmFinEmpresaNombre()
        : service === "seguros"
          ? resolveCrmSegurosEmpresaNombre()
          : service === "inmobiliaria"
            ? resolveCrmInmoEmpresaNombre()
            : resolveCrmGestoriaEmpresaNombre();
    const clienteData = resolveClienteFromInput(actionModalClienteInput, actionModalClienteId);
    const payload = {
      id: editId || undefined,
      fecha: actionModalFecha ? actionModalFecha.value : editSnapshot?.dateKey,
      hora: actionModalHora ? actionModalHora.value : editSnapshot?.time,
      hora_fin: actionModalHoraFin ? actionModalHoraFin.value : editSnapshot?.timeEnd,
      tipo: actionModalTipo ? actionModalTipo.value.trim() : editSnapshot?.tipo,
      responsable: actionModalResponsable ? actionModalResponsable.value : editSnapshot?.responsable,
      estado: actionModalEstado ? actionModalEstado.value : editSnapshot?.estado,
      notas: actionModalNotas ? actionModalNotas.value.trim() : editSnapshot?.notas,
      recordatorio_min: actionModalRecordatorio ? actionModalRecordatorio.value : editSnapshot?.recordatorio_min,
      servicio: service,
      empresa_nombre: empresaNombre,
      cliente_id: clienteData.cliente_id,
      cliente_nombre: clienteData.cliente_nombre,
    };
    payload.hora = normalizeAgendaTimeString(payload.hora || "");
    payload.hora_fin = normalizeAgendaTimeString(payload.hora_fin || "");
    if (payload.hora_fin && !payload.hora) {
      if (actionModalStatus) actionModalStatus.textContent = "Indica primero la hora de inicio.";
      return;
    }
    if (payload.hora) {
      const startMin = parseAgendaTimeMinutes(payload.hora);
      if (startMin === null) {
        if (actionModalStatus) actionModalStatus.textContent = "Hora de inicio inválida.";
        return;
      }
      if (payload.hora_fin) {
        const endMin = parseAgendaTimeMinutes(payload.hora_fin);
        if (endMin === null) {
          if (actionModalStatus) actionModalStatus.textContent = "Hora fin inválida.";
          return;
        }
        if (endMin <= startMin) {
          if (actionModalStatus) actionModalStatus.textContent = "La hora fin debe ser posterior a la hora de inicio.";
          return;
        }
      }
    }
    if (!String(payload.responsable || "").trim()) {
      payload.responsable = getCurrentUser();
    }
    const ctx = state.actionModalContext;
    if (ctx && typeof ctx === "object") {
      if (!editId) {
        ["asesoramiento_id", "inmueble_id", "related_id", "related_tipo"].forEach((key) => {
          const value = ctx[key];
          if (value === undefined || value === null) return;
          if (!String(value).trim()) return;
          payload[key] = value;
        });
        if (!payload.cliente_id && ctx.cliente_id) {
          payload.cliente_id = ctx.cliente_id;
        }
        if (!payload.cliente_nombre && ctx.cliente_nombre) {
          payload.cliente_nombre = ctx.cliente_nombre;
        }
      }
    }
    const conflict = lastAgendaEvents.find((ev) => {
      if (editId && ev.id === editId) return false;
      if (!ev.dateKey || !payload.fecha) return false;
      if (ev.dateKey !== payload.fecha) return false;
      if (!payload.hora || !ev.time) return false;
      if (ev.time !== payload.hora) return false;
      if (payload.responsable && ev.responsable && ev.responsable === payload.responsable) {
        return true;
      }
      return false;
    });
    if (conflict) {
      const ok = window.confirm(
        "Existe otra cita con el mismo responsable y hora. ¿Quieres guardarla igualmente?"
      );
      if (!ok) {
        if (actionModalStatus) actionModalStatus.textContent = "Cancelado.";
        return;
      }
    }
    if (isTenantWorkspaceMode() && state.currentWorkspaceId) {
      payload.workspace_id = state.currentWorkspaceId;
    }
    const endpoint = editId ? "/api/acciones_update" : "/api/acciones";
    apiPost(endpoint, payload)
      .then((data) => {
        if (actionModalStatus) actionModalStatus.textContent = "Guardado.";
        closeActionEditor();
        // UX: si guardamos una cita en otra fecha distinta a la vista actual,
        // anclamos la agenda a esa fecha para que el usuario la vea y no parezca que “desapareció”.
        try {
          if (service === "inmobiliaria" && payload?.fecha) {
            state.crmAgendaAnchorDay = String(payload.fecha || "").trim() || state.crmAgendaAnchorDay;
          }
        } catch (e) {}
        try {
          const u = getAuthScopeUser();
          if (u && isPrivilegedUser(u)) {
            loadAgendaGeneral();
          }
        } catch (e) {}
        if (service === "inmobiliaria") {
          loadCrmAgenda();
        }
        if (service === "inmobiliaria") {
          const inmId =
            String(payload.inmueble_id || state.currentInmuebleId || "").trim();
          const empresaId = resolveLegacyEmpresaId(resolveCrmInmoEmpresa());
          if (inmId && empresaId) {
            loadInmuebleActividad(inmId, empresaId);
          }
        }
        const fincas = state.empresas.find((e) => e.nombre === FINCAS_COMPANY);
        const fin = resolveCrmFinEmpresa();
        if (fincas) {
          const fincasId = resolveLegacyEmpresaId(fincas);
          if (userCanAccessService("gestoria")) {
            loadAcciones("gestoria", fincasId, gestoriaAgendaTable, gestoriaAgendaInfo);
          }
          if (userCanAccessService("seguros")) {
            loadAcciones("seguros", fincasId, segurosAgendaTable, segurosAgendaInfo);
          }
        }
        if (fin) {
          const finId = resolveLegacyEmpresaId(fin);
          if (userCanAccessService("financiaciones")) {
            loadAcciones("financiaciones", finId, finAgendaTable, finAgendaInfo);
            loadFinWorkflowActions(finId);
            if (payload.related_tipo === "hipoteca" && payload.related_id) {
              loadFinHipotecaActions(finId);
            }
          }
        }
        if (state.currentClienteId) {
          loadGestoriaClienteAgenda(state.currentClienteId);
        }
      })
      .catch((err) => {
        if (actionModalStatus) actionModalStatus.textContent = err?.message || "Error al guardar.";
      });
  });
}

if (actionModalCreateCliente) {
  actionModalCreateCliente.addEventListener("click", async () => {
    const clienteData = resolveClienteFromInput(actionModalClienteInput, actionModalClienteId);
    const nombre = String(clienteData.cliente_nombre || "").trim();
    if (!nombre) {
      actionModalClienteInput?.focus?.();
      return;
    }
    if (clienteData.cliente_id) {
      syncActionModalClienteButtons();
      return;
    }
    const ok = window.confirm(`Crear nuevo cliente “${nombre}”?`);
    if (!ok) return;
    if (actionModalStatus) actionModalStatus.textContent = "Creando cliente...";
    actionModalCreateCliente.disabled = true;
    try {
      const clienteId = await createCrmClienteQuick({ nombre }, { preferExisting: true });
      await loadClientesList().catch(() => null);
      populateAgendaClientes(actionModalClientes, actionModalClienteInput, actionModalClienteId);
      if (actionModalClienteId) actionModalClienteId.value = clienteId;
      const matched = (Array.isArray(state.clientesList) ? state.clientesList : []).find((c) => c.id === clienteId);
      if (matched && actionModalClienteInput) {
        actionModalClienteInput.value = formatNombreCliente(matched.nombre);
      }
      if (actionModalStatus) actionModalStatus.textContent = "Cliente creado.";
    } catch (err) {
      if (actionModalStatus) actionModalStatus.textContent = err?.message || "Error al crear cliente.";
    } finally {
      syncActionModalClienteButtons();
    }
  });
}

