if (segurosBdtOcrLink) {
  segurosBdtOcrLink.addEventListener("click", async () => {
    if (segurosBdtOcrStatus) segurosBdtOcrStatus.textContent = "";
    const recordId = segurosBdtOcrSelect ? segurosBdtOcrSelect.value : "";
    if (!recordId) {
      if (segurosBdtOcrStatus) segurosBdtOcrStatus.textContent = "Selecciona una póliza.";
      return;
    }
    let fields = getSegurosBdtOcrFields();
    await resolveOcrClienteMatch("bdt", getSegurosBdtOcrClienteFields());
    fields = {
      ...fields,
      cliente_id: state.segurosBdtOcrClienteId || fields.cliente_id || "",
    };
    const file =
      segurosBdtOcrFile && segurosBdtOcrFile.files && segurosBdtOcrFile.files.length
        ? segurosBdtOcrFile.files[0]
        : null;
    if (segurosBdtOcrStatus) segurosBdtOcrStatus.textContent = "Vinculando...";
    let upload = null;
    if (file) {
      try {
        upload = await uploadFileToS3(file, "seguros", segurosBdtOcrStatus);
      } catch (err) {
        if (segurosBdtOcrStatus) {
          segurosBdtOcrStatus.textContent = `Error al subir: ${err.message}`;
        }
        return;
      }
    }
    const empresaNombre = resolveCrmSegurosEmpresaNombre();
    fetch("/api/seguros_update", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        empresa_nombre: empresaNombre,
        id: recordId,
        cliente_id: fields.cliente_id || "",
      }),
    })
      .then((res) => res.json())
      .then(async (bindResp) => {
        if (bindResp?.error) {
          if (segurosBdtOcrStatus) segurosBdtOcrStatus.textContent = bindResp.error;
          return;
        }
        const resp = await fetch("/api/seguros_enrich", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ empresa_nombre: empresaNombre, id: recordId, ...fields }),
        }).then((res) => res.json());
        if (resp?.error) {
          if (segurosBdtOcrStatus) segurosBdtOcrStatus.textContent = resp.error;
          return;
        }
        if (upload) {
          const updateResp = await fetch("/api/seguros_update", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              empresa_nombre: empresaNombre,
              id: recordId,
              cliente_id: fields.cliente_id || "",
              poliza_key: upload.key || "",
              poliza_url: upload.public_url || "",
            }),
          }).then((res) => res.json());
          if (updateResp?.error) {
            throw new Error(updateResp.error || "No se pudo adjuntar la póliza al registro.");
          }
        }
        resetSegurosBdtOcrAggregator();
        if (segurosBdtOcrStatus) segurosBdtOcrStatus.textContent = "Registro vinculado.";
        loadSegurosCrm();
      })
      .catch((err) => {
        if (segurosBdtOcrStatus) {
          segurosBdtOcrStatus.textContent = err?.message || "Error al vincular.";
        }
      });
  });
}

