  if (workspaceTimeEmployeeForm) {
  workspaceTimeEmployeeForm.addEventListener("submit", async (event) => {
    event.preventDefault();
    if (workspaceTimeEmployeeStatus) workspaceTimeEmployeeStatus.textContent = "Guardando...";
    const submit = workspaceTimeEmployeeForm.querySelector('button[type="submit"]');
    if (submit) submit.disabled = true;
    const formData = new FormData(workspaceTimeEmployeeForm);
    const payload = Object.fromEntries(formData.entries());
    payload.workspace_id = state.currentWorkspaceId;
    payload.activo = workspaceTimeEmployeeForm.querySelector('[name="activo"]')?.checked ? 1 : 0;
    await ensureWorkspaceCompaniesLoaded();
    payload.empresa_manual = String(payload.empresa_id || "").trim() ? 1 : 0;
    const companies = state.currentWorkspaceDetail?.companies || [];
    const matchedCompany = companies.find((company) => String(company.id || "") === String(payload.empresa_id || ""));
    payload.empresa_nombre = matchedCompany?.nombre || "";
    try {
      const data = await apiPost("/api/workspace_registro_personal", payload);
      if (workspaceTimeEmployeeStatus) workspaceTimeEmployeeStatus.textContent = "Persona guardada.";
      if (data?.id) {
        upsertWorkspaceEmployeeLocal({
          ...payload,
          id: String(data.id || "").trim(),
          empresa_nombre: matchedCompany?.nombre || "",
        });
        // Re-render inmediato para que la card/listado refleje el cambio aunque el reload falle.
        renderWorkspaceRrhhHub();
      }
      await loadWorkspaceDetail(state.currentWorkspaceId);
      if (data?.id) {
        state.workspaceRrhhSelectedPersonaId = String(data.id || "");
        state.workspaceRrhhScopeAll = false;
      }
      if (state.currentWorkspaceView === "rrhh") {
        await refreshWorkspaceRrhh();
      }
      fillWorkspaceTimeEmployeeForm();
    } catch (error) {
      if (workspaceTimeEmployeeStatus) workspaceTimeEmployeeStatus.textContent = error.message || "No se pudo guardar.";
    } finally {
      if (submit) submit.disabled = false;
    }
  });
}

