if (inmuebleBackBtn) {
  inmuebleBackBtn.addEventListener("click", () => {
    try {
      restoreWorkspaceSimuladoresFromInmueble();
    } catch (e) {}
    if (inmuebleDetail) {
      inmuebleDetail.classList.add("hidden");
    }
    if (crmWorkspaceShell) {
      crmWorkspaceShell.classList.remove("hidden");
    }
    try {
      updateTableVisibility();
    } catch (e) {}
    setCrmWorkspaceView(state.currentInmuebleOriginView || "inmuebles");
    state.currentInmuebleId = "";
    state.currentInmuebleOriginView = "inmuebles";
    // Limpia el deep-link del inmueble (volvemos al CRM, no a la ficha).
    try {
      const params = new URLSearchParams(window.location.search || "");
      ensureTenantParams(params);
      if (params.get("crm") === "inmo") {
        params.delete("inmueble");
        params.delete("captacion");
        setUrlParams(params);
      }
    } catch (e) {}
    // Si el usuario estaba creando un inmueble y abrió una ficha para comprobar duplicado, reabrimos el alta con su borrador.
    maybeReturnToCrmCaptacionCreate();
    maybeReturnToCrmClienteCreate();
    maybeReturnToAltaCaptacion();
  });
}

if (inmuebleDeleteBtn) {
  inmuebleDeleteBtn.addEventListener("click", () => {
    if (!state.currentInmuebleId) return;
    const inmueble = state.currentInmueble || state.currentInmuebleContext?.inmueble || {};
    const label = String(inmueble.direccion || inmueble.referencia || "este inmueble").trim();
    const confirmed = window.confirm(`Vas a borrar ${label}. Esta acción eliminará también su captación, visitas, acciones y documentos vinculados. ¿Quieres continuar?`);
    if (!confirmed) return;
    if (inmuebleSaveStatus) {
      inmuebleSaveStatus.textContent = "Borrando inmueble...";
    }
    fetch("/api/inmueble_delete", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      credentials: "same-origin",
      body: JSON.stringify({
        inmueble_id: state.currentInmuebleId,
        usuario: getCurrentUser(),
        ...(isTenantWorkspaceMode()
          ? {
              workspace_id: String(
                new URLSearchParams(window.location.search || "").get("workspace") || state.currentWorkspaceId || ""
              ).trim(),
              workspace_company_id: String(state.currentWorkspaceCompanyWsId || "").trim(),
            }
          : {}),
      }),
    })
      .then((res) => res.json())
      .then((data) => {
        if (data.error) {
          if (inmuebleSaveStatus) {
            inmuebleSaveStatus.textContent = data.error;
          }
          return;
        }
        if (inmuebleDetail) {
          inmuebleDetail.classList.add("hidden");
        }
        if (crmWorkspaceShell) {
          crmWorkspaceShell.classList.remove("hidden");
        }
        try {
          updateTableVisibility();
        } catch (e) {}
        setCrmWorkspaceView(state.currentInmuebleOriginView || "inmuebles");
        state.currentInmuebleId = "";
        state.currentInmueble = null;
        state.currentInmuebleContext = null;
        state.currentInmuebleOriginView = "inmuebles";
        loadCrmInmuebles();
      })
      .catch(() => {
        if (inmuebleSaveStatus) {
          inmuebleSaveStatus.textContent = "Error al borrar.";
        }
      });
  });
}

