	if (inmuebleGoEstadoBtn) {
	  inmuebleGoEstadoBtn.addEventListener("click", () => {
	    const etapaMain = normalizeCrmMainEtapa(state.currentInmuebleContext?.inmueble?.estado || "");
	    const tipo = etapaMain === "Encargo"
      ? "Cita de venta/alquiler"
      : etapaMain === "Propuesta"
        ? "Cita de propuesta de compra/alquiler"
        : "Cita de adquisición";
    queueInmuebleCitaPrefill({
      tipo,
      asunto: tipo,
      statusText: "Registra la cita y ciérrala para que el inmueble avance de fase.",
    });
	    applyPendingInmuebleCitaPrefill();
	  });
	}

	if (inmuebleGuidedBtn) {
	  const getEtapaMain = () => {
	    const ctx = state.currentInmuebleContext || {};
	    const inmueble = ctx.inmueble || {};
	    const captacion = ctx.captacion || {};
	    return (
	      normalizeCrmMainEtapa(inmueble.estado || captacion.etapa || captacion.situacion_comercial || "")
	      || "Inmueble"
	    );
	  };

	  const normalizeStageLabel = (value) => {
	    const raw = String(value || "").trim();
	    if (!raw) return "Inmueble";
	    return normalizeCrmMainEtapa(raw) || raw;
	  };

	  const setOpen = (open) => {
	    if (!inmuebleGuidedModal) return;
	    inmuebleGuidedModal.classList.toggle("hidden", !open);
	    if (open) void refresh();
	  };

	  const focusInmuebleField = ({ tab = "", target = "", field = "" } = {}) => {
	    const tabKey = String(tab || "").trim();
	    const targetKey = String(target || "").trim();
	    const fieldKey = String(field || "").trim();
	    if (!fieldKey || !targetKey) return;
	    if (tabKey) {
	      try {
	        setInmuebleTab(tabKey);
	      } catch (e) {}
	    }
	    window.setTimeout(() => {
	      try {
	        const scope =
	          tabKey === "datos"
	            ? inmuebleTabDatos
	            : tabKey === "captacion"
	              ? inmuebleTabCaptacion
	              : tabKey === "adjuntos"
	                ? inmuebleTabAdjuntos
	                : tabKey === "actividad"
	                  ? inmuebleTabActividad
	                  : inmuebleDetail;
	        const selector = `.inline-input[data-target="${CSS.escape(targetKey)}"][data-field="${CSS.escape(fieldKey)}"]`;
	        const el = scope?.querySelector?.(selector) || document.querySelector(selector);
	        if (!el) return;
	        try {
	          el.scrollIntoView({ behavior: "smooth", block: "center" });
	        } catch (e) {}
	        if (el.focus) el.focus();
	      } catch (e) {}
	    }, 80);
	  };

	  const scrollToOwnersEditor = () => {
	    try {
	      setInmuebleTab("captacion");
	    } catch (e) {}
	    window.setTimeout(() => {
	      const card = inmuebleTabCaptacion?.querySelector?.(".editable-card--owners");
	      if (!card) return;
	      try {
	        card.scrollIntoView({ behavior: "smooth", block: "start" });
	      } catch (e) {}
	      try {
	        const firstSelect = card.querySelector("select");
	        if (firstSelect && firstSelect.focus) firstSelect.focus();
	      } catch (e) {}
	    }, 120);
	  };

	  const openInmuebleDocs = (tipo = "") => {
	    try {
	      setInmuebleTab("adjuntos");
	    } catch (e) {}
	    window.setTimeout(() => {
	      try {
	        const select = inmuebleDocsForm?.querySelector?.('select[name="tipo"]');
	        const next = String(tipo || "").trim();
	        if (select && next) {
	          select.value = next;
	        }
	      } catch (e) {}
	      try {
	        inmuebleDocsForm?.scrollIntoView?.({ behavior: "smooth", block: "start" });
	      } catch (e) {}
	      try {
	        inmuebleDocsFile?.focus?.();
	      } catch (e) {}
	    }, 120);
	  };

			  const openCatastroForCurrent = () => {
			    try {
			      const ctx = state.currentInmuebleContext || {};
			      const inmueble = ctx.inmueble || {};
			      const address = [inmueble.direccion, inmueble.poblacion, inmueble.provincia, "España"].filter(Boolean).join(", ");
			      const url = buildCatastroUrl(String(inmueble.referencia_catastral || "").trim(), address);
			      openExternalUrl(url || "https://www.sedecatastro.gob.es/", { allowSameTabFallback: false });
			    } catch {
			      openExternalUrl("https://www.sedecatastro.gob.es/", { allowSameTabFallback: false });
			    }
			  };

	  const renderChecklistPreview = (rows = []) => {
	    if (!inmuebleGuidedChecklistPreview) return;
	    const items = Array.isArray(rows) ? rows : [];
	    if (!items.length) {
	      inmuebleGuidedChecklistPreview.innerHTML = "<p class='muted'>Sin checklist para esta etapa. Pulsa «Generar».</p>";
	      return;
	    }
	    const list = document.createElement("div");
	    list.className = "inline-list";
	    items.slice(0, 10).forEach((row) => {
	      const estado = String(row?.estado || "Pendiente").trim() || "Pendiente";
	      const key = normalizeSimple(estado);
	      const tone = key.includes("complet") ? "accent" : "soft";
	      const item = document.createElement("div");
	      item.className = "inline-row";
	      item.innerHTML = `
	        <div>
	          <strong>${escapeHtml(String(row?.tarea || "").trim() || "Tarea")}</strong>
	          <div class="muted">${escapeHtml(String(row?.responsable || "").trim() || "Sin asignar")}</div>
	        </div>
	        <div class="inmueble-summary-badges">
	          <span class="inmueble-badge tone-${tone}">${escapeHtml(estado)}</span>
	        </div>
	      `;
	      list.appendChild(item);
	    });
	    inmuebleGuidedChecklistPreview.innerHTML = "";
	    inmuebleGuidedChecklistPreview.appendChild(list);
	  };

	  const renderActionsPreview = (rows = []) => {
	    if (!inmuebleGuidedActionsPreview) return;
	    const items = Array.isArray(rows) ? rows : [];
	    if (!items.length) {
	      inmuebleGuidedActionsPreview.innerHTML = "<p class='muted'>Sin acciones pendientes.</p>";
	      return;
	    }
	    const list = document.createElement("div");
	    list.className = "inline-list";
	    items.slice(0, 8).forEach((row) => {
	      const item = document.createElement("div");
	      item.className = "inline-row";
	      const fecha = row?.fecha ? formatCell("fecha", row.fecha) : "-";
	      const hora = String(row?.hora || "").trim();
	      const tipo = String(row?.tipo || "").trim() || "Acción";
	      const asunto = String(row?.asunto || "").trim();
	      const resp = String(row?.responsable || "").trim();
	      item.innerHTML = `
	        <div>
	          <strong>${escapeHtml(tipo)}${asunto ? ` · ${escapeHtml(asunto)}` : ""}</strong>
	          <div class="muted">${escapeHtml([fecha, hora].filter(Boolean).join(" · "))}${resp ? ` · ${escapeHtml(resp)}` : ""}</div>
	        </div>
	        <div class="inmueble-summary-badges">
	          <span class="inmueble-badge tone-soft">${escapeHtml(String(row?.estado || "Pendiente"))}</span>
	        </div>
	      `;
	      list.appendChild(item);
	    });
	    inmuebleGuidedActionsPreview.innerHTML = "";
	    inmuebleGuidedActionsPreview.appendChild(list);
	  };

	  const renderWizardSteps = (steps = []) => {
	    if (!inmuebleGuidedSteps) return;
	    const items = Array.isArray(steps) ? steps : [];
	    if (!items.length) {
	      inmuebleGuidedSteps.innerHTML = "<p class='muted'>No hay pasos sugeridos.</p>";
	      return;
	    }
	    const list = document.createElement("div");
	    list.className = "inline-list";
	    items.forEach((step) => {
	      const title = String(step?.title || "").trim() || "Paso";
	      const summary = String(step?.summary || "").trim();
	      const ok = Boolean(step?.ok);
	      const tone = ok ? "accent" : "soft";
	      const row = document.createElement("div");
	      row.className = "inline-row";
	      const left = document.createElement("div");
	      left.innerHTML = `<strong>${escapeHtml(title)}</strong>${summary ? `<div class="muted">${escapeHtml(summary)}</div>` : ""}`;
	      const right = document.createElement("div");
	      right.className = "inmueble-summary-badges";
	      const badge = document.createElement("span");
	      badge.className = `inmueble-badge tone-${tone}`;
	      badge.textContent = ok ? "OK" : "Pendiente";
	      right.appendChild(badge);
	      const actions = Array.isArray(step?.actions) ? step.actions : [];
	      actions.slice(0, 3).forEach((action) => {
	        const btn = document.createElement("button");
	        btn.type = "button";
	        btn.className = "secondary";
	        btn.textContent = String(action?.label || "").trim() || "Abrir";
	        btn.addEventListener("click", () => {
	          try {
	            action?.onClick?.();
	          } catch (e) {}
	        });
	        right.appendChild(btn);
	      });
	      row.appendChild(left);
	      row.appendChild(right);
	      list.appendChild(row);
	    });
	    inmuebleGuidedSteps.innerHTML = "";
	    inmuebleGuidedSteps.appendChild(list);
	  };

	  const computeWizardSteps = (stage, inmueble = {}, captacion = {}, propietarios = [], pendingAcciones = []) => {
	    const etapa = normalizeStageLabel(stage);
	    const stageKey = normalizeSimple(etapa);
	    const steps = [];

	    const hasAddress = Boolean(String(inmueble.direccion || "").trim()) && Boolean(String(inmueble.poblacion || "").trim()) && Boolean(String(inmueble.provincia || "").trim());
	    const hasTipo = Boolean(String(inmueble.tipo_inmueble || "").trim());
	    const hasProp = Boolean(String(captacion.propietario || "").trim()) || (Array.isArray(propietarios) && propietarios.length > 0);
	    const hasCatastro = Boolean(String(inmueble.referencia_catastral || "").trim());
	    const hasProximaAccion = Boolean(String(captacion.proxima_accion || "").trim()) || (Array.isArray(pendingAcciones) && pendingAcciones.length > 0);
	    const noticiaOk = String(captacion.noticia_verificada ?? "").trim() === "1";

	    steps.push({
	      title: "Completar dirección (CP/Población/Provincia)",
	      summary: "Esto alimenta duplicados, Catastro y mapas.",
	      ok: hasAddress,
	      actions: [
	        { label: "Ir a dirección", onClick: () => focusInmuebleField({ tab: "datos", target: "inmueble", field: "direccion" }) },
	      ],
	    });

	    steps.push({
	      title: "Definir tipo de inmueble",
	      summary: "Ayuda a clasificar y publicar en el portal.",
	      ok: hasTipo,
	      actions: [
	        { label: "Ir a tipo", onClick: () => focusInmuebleField({ tab: "datos", target: "inmueble", field: "tipo_inmueble" }) },
	      ],
	    });

	    steps.push({
	      title: "Vincular propietario real",
	      summary: "La vinculación activa documentos y seguimiento.",
	      ok: hasProp,
	      actions: [{ label: "Abrir propietarios", onClick: () => scrollToOwnersEditor() }],
	    });

	    if (stageKey === "noticia") {
	      steps.push({
	        title: "Marcar noticia como verificada",
	        summary: "INDICIO: confirma la información antes de avanzar.",
	        ok: noticiaOk,
	        actions: [
	          { label: "Ir a verificación", onClick: () => focusInmuebleField({ tab: "captacion", target: "captacion", field: "noticia_verificada" }) },
	        ],
	      });
	    }

	    steps.push({
	      title: "Consultar Catastro y registrar referencia",
	      summary:
	        stageKey === "reservado" || stageKey === "vendido"
	          ? "La referencia catastral es obligatoria para cierre."
	          : "Recomendado para evitar duplicados y acelerar verificaciones.",
	      ok: hasCatastro,
	      actions: [
	        { label: "Abrir Catastro", onClick: () => openCatastroForCurrent() },
	        { label: "Ir a ref.", onClick: () => focusInmuebleField({ tab: "datos", target: "inmueble", field: "referencia_catastral" }) },
	      ],
	    });

	    steps.push({
	      title: "Subir documentación básica",
	      summary: "Ej: Nota simple, Escritura, Contrato/Arras.",
	      ok: true,
	      actions: [
	        { label: "Abrir adjuntos", onClick: () => openInmuebleDocs("Nota simple") },
	      ],
	    });

	    steps.push({
	      title: "Mantener próxima acción",
	      summary: "Agenda viva para avanzar la fase con trazabilidad.",
	      ok: hasProximaAccion,
	      actions: [
	        { label: "Crear acción", onClick: () => inmuebleGuidedCreateAction?.click?.() },
	        { label: "Ir a citas", onClick: () => inmuebleGuidedGoActividad?.click?.() },
	      ],
	    });

	    return steps;
	  };

	  const refresh = async () => {
	    if (!inmuebleGuidedModal || inmuebleGuidedModal.classList.contains("hidden")) return;
	    const ctx = state.currentInmuebleContext || {};
	    const inmueble = ctx.inmueble || {};
	    const captacion = ctx.captacion || {};
	    const propietarios = Array.isArray(ctx.propietarios) ? ctx.propietarios : [];
	    const inmuebleId = String(inmueble.id || state.currentInmuebleId || "").trim();
	    const empresaId = String(inmueble.empresa_id || "").trim();
	      const etapaMain = getEtapaMain();
	      const stageSelected = normalizeStageLabel(inmuebleGuidedStageSelect?.value || etapaMain);
	      if (inmuebleGuidedStageSelect) {
	        const wanted = stageSelected;
	        const has = Array.from(inmuebleGuidedStageSelect.options || []).some((opt) => String(opt.value || opt.textContent || "").trim() === wanted);
	        if (!has) {
	          const opt = document.createElement("option");
	          opt.textContent = wanted;
	          inmuebleGuidedStageSelect.appendChild(opt);
	        }
	        inmuebleGuidedStageSelect.value = wanted;
	      }
	    if (!inmuebleId) return;

	    if (inmuebleGuidedStatus) inmuebleGuidedStatus.textContent = "Cargando...";
	    try {
	      try {
	        await apiPost("/api/inmueble_guided_prepare", { inmueble_id: inmuebleId });
	      } catch (e) {}

	      const checklistParams = new URLSearchParams({ inmueble_id: inmuebleId, etapa: etapaMain });
	      const [checklistData, accionesData] = await Promise.all([
	        api(`/api/inmueble_checklist?${checklistParams.toString()}`).catch(() => ({ rows: [] })),
	        empresaId
	          ? api(`/api/acciones?servicio=inmobiliaria&empresa_id=${encodeURIComponent(empresaId)}&inmueble_id=${encodeURIComponent(inmuebleId)}`).catch(() => ({ rows: [] }))
	          : Promise.resolve({ rows: [] }),
	      ]);

	      const checklist = Array.isArray(checklistData?.rows) ? checklistData.rows : [];
	      const acciones = Array.isArray(accionesData?.rows)
	        ? accionesData.rows
	        : Array.isArray(ctx.actividad)
	          ? ctx.actividad
	          : [];
	      const pendingAcciones = acciones.filter((row) => normalizeSimple(row?.estado || "") === "pendiente");
	      const requirements = getInmuebleStageRequirements(stageSelected, inmueble, captacion, propietarios);
	      const pendientes = requirements.filter((item) => !item.ok);
	      const completedChecklist = checklist.filter((row) => normalizeSimple(row?.estado || "").includes("complet")).length;

	      renderCrmMiniCards(inmuebleGuidedHeader, [
	        { title: "Etapa", value: etapaMain, meta: "Pipeline", summary: "Situación actual del inmueble." },
	        {
	          title: "Validaciones pendientes",
	          value: pendientes.length,
	          meta: "Bloqueos",
	          summary: pendientes.length ? pendientes.slice(0, 2).map((it) => it.label).join(" · ") : "Sin bloqueos.",
	        },
	        {
	          title: "Checklist completada",
	          value: checklist.length ? `${completedChecklist}/${checklist.length}` : "0/0",
	          meta: "Tareas",
	          summary: checklist.length ? "Tareas sugeridas para esta etapa." : "Aún no hay tareas para esta etapa.",
	        },
	        {
	          title: "Acciones pendientes",
	          value: pendingAcciones.length,
	          meta: "Agenda",
	          summary: pendingAcciones.length ? "Revisa próximas citas/acciones." : "No hay acciones pendientes.",
	        },
	      ]);

	      renderCrmMiniCards(
	        inmuebleGuidedRequirements,
	        requirements.map((item) => ({
	          title: item.label,
	          value: item.ok ? "OK" : "Pendiente",
	          meta: "Validación",
	          summary: item.ok ? "Cumplido." : "Completa este dato para avanzar.",
	        }))
	      );

	      renderChecklistPreview(checklist);
	      renderActionsPreview(pendingAcciones);
	      renderWizardSteps(computeWizardSteps(stageSelected, inmueble, captacion, propietarios, pendingAcciones));

	      if (inmuebleGuidedStatus) {
	        const hints = [];
	        if (stageSelected === "Noticia" && String(captacion.noticia_verificada ?? "").trim() !== "1") {
	          hints.push("Noticia sin verificar.");
	        }
	        if (!String(captacion.proxima_accion || "").trim() && !pendingAcciones.length) {
	          hints.push("Sin próxima acción.");
	        }
	        inmuebleGuidedStatus.textContent = hints.length ? hints.join(" ") : "Listo.";
	      }
	    } catch (error) {
	      if (inmuebleGuidedStatus) inmuebleGuidedStatus.textContent = error?.message || "No se pudo cargar el proceso guiado.";
	    }
	  };

	  inmuebleGuidedBtn.addEventListener("click", () => setOpen(true));

	  if (inmuebleGuidedStageSelect) {
	    inmuebleGuidedStageSelect.addEventListener("change", () => void refresh());
	  }
	  if (inmuebleGuidedRefreshBtn) {
	    inmuebleGuidedRefreshBtn.addEventListener("click", () => void refresh());
	  }

	  if (inmuebleGuidedClose) {
	    inmuebleGuidedClose.addEventListener("click", () => setOpen(false));
	  }

	  if (inmuebleGuidedModal) {
	    document.addEventListener("click", (event) => {
	      if (inmuebleGuidedModal.classList.contains("hidden")) return;
	      const target = event.target;
	      if (target && target.closest && target.closest("#inmuebleGuidedModal .modal-content")) return;
	      setOpen(false);
	    });
	    document.addEventListener("keydown", (event) => {
	      if (event.key !== "Escape") return;
	      if (inmuebleGuidedModal.classList.contains("hidden")) return;
	      setOpen(false);
	    });
	  }

	  if (inmuebleGuidedOpenChecklist) {
	    inmuebleGuidedOpenChecklist.addEventListener("click", () => {
	      setOpen(false);
	      setInmuebleTab("estado");
	      window.setTimeout(() => {
	        try {
	          document.getElementById("inmuebleChecklistTable")?.scrollIntoView({ behavior: "smooth", block: "start" });
	        } catch (e) {}
	      }, 0);
	    });
	  }

	  if (inmuebleGuidedGenerateChecklist) {
	    inmuebleGuidedGenerateChecklist.addEventListener("click", () => {
	      const etapa = getEtapaMain();
	      const ok = window.confirm(`¿Generar (o regenerar) checklist para la etapa \"${etapa}\"?`);
	      if (!ok) return;
	      generateInmuebleChecklist(etapa);
	      window.setTimeout(() => void refresh(), 300);
	    });
	  }

	  if (inmuebleGuidedGoActividad) {
	    inmuebleGuidedGoActividad.addEventListener("click", () => {
	      setOpen(false);
	      setInmuebleTab("actividad");
	      window.setTimeout(() => window.scrollTo({ top: 0, behavior: "smooth" }), 0);
	    });
	  }

	  if (inmuebleGuidedCreateAction) {
	    inmuebleGuidedCreateAction.addEventListener("click", () => {
	      const ctx = state.currentInmuebleContext || {};
	      const captacion = ctx.captacion || {};
	      const etapa = getEtapaMain();
	      const warnings = [];
	      if (etapa === "Noticia" && String(captacion.noticia_verificada ?? "").trim() !== "1") {
	        warnings.push("La noticia no está verificada (INDICIO).");
	      }
	      if (!String(captacion.proxima_accion || "").trim()) {
	        warnings.push("No hay próxima acción programada.");
	      }
	      const tipo =
	        etapa === "Encargo"
	          ? "Cita de gestión encargo (seguimiento)"
	          : etapa === "Propuesta"
	            ? "Cita de propuesta"
	            : etapa === "Noticia"
	              ? "Llamada propietario (verificar noticia)"
	              : etapa === "Inmueble"
	                ? "Cita de adquisición"
	                : "Llamada";
	      queueInmuebleCitaPrefill({
	        tipo,
	        asunto: tipo,
	        statusText: warnings.length ? `Checklist guiado:\n- ${warnings.join("\n- ")}` : "",
	      });
	      setOpen(false);
	      applyPendingInmuebleCitaPrefill();
	    });
	  }
	}

