if (inmuebleActividadForm) {
  const tipoSelect = inmuebleActividadForm.querySelector('select[name="tipo"]');
  const resultSelect = inmuebleActividadForm.querySelector('select[name="resultado_cierre"]');
  if (tipoSelect) {
    tipoSelect.addEventListener("change", () => {
      syncInmuebleWorkflowForm();
    });
  }
  if (resultSelect) {
    resultSelect.addEventListener("change", () => {
      syncInmuebleWorkflowForm();
    });
  }

  if (inmuebleGeocodeBtn) {
    inmuebleGeocodeBtn.addEventListener("click", () => {
      runInmuebleGeocodeFromUi();
    });
  }
  syncInmuebleWorkflowForm();
  inmuebleActividadForm.addEventListener("submit", (event) => {
    event.preventDefault();
    if (!state.currentInmuebleId) {
      if (inmuebleActividadStatus) {
        inmuebleActividadStatus.textContent = "Selecciona un inmueble.";
      }
      return;
    }
    if (inmuebleActividadStatus) {
      inmuebleActividadStatus.textContent = "Guardando...";
    }
    const formData = new FormData(inmuebleActividadForm);
    const payload = Object.fromEntries(formData.entries());
    const tipo = String(payload.tipo || "").trim();
    const estado = String(payload.estado || "").trim() || "Pendiente";
    const requiredResults = INMO_WORKFLOW_RESULT_OPTIONS[tipo];
    if (!requiredResults) {
      payload.resultado_cierre = "";
      payload.estado_siguiente = "";
    } else if (estado.toLowerCase() === "pendiente") {
      payload.resultado_cierre = "";
      payload.estado_siguiente = "";
    } else if (!String(payload.resultado_cierre || "").trim()) {
      if (inmuebleActividadStatus) {
        inmuebleActividadStatus.textContent = "Esta cita debe cerrarse con resultado.";
      }
      return;
    } else if (!requiredResults.includes(String(payload.resultado_cierre || "").trim())) {
      if (inmuebleActividadStatus) {
        inmuebleActividadStatus.textContent = "El resultado no es válido para este tipo de cita.";
      }
      return;
    }
    Object.assign(
      payload,
      resolveClienteFromInput(inmuebleActividadClienteInput, inmuebleActividadClienteId)
    );
    if (isTenantWorkspaceMode()) {
      payload.workspace_id =
        String(new URLSearchParams(window.location.search || "").get("workspace") || state.currentWorkspaceId || "").trim();
      if (!payload.workspace_company_id) {
        payload.workspace_company_id = String(state.currentWorkspaceCompanyWsId || "").trim();
      }
    } else {
      payload.empresa_id = resolveCurrentInmuebleEmpresaId() || resolveCrmInmoEmpresaId();
      payload.empresa_nombre = resolveCurrentInmuebleEmpresaNombre() || resolveCrmInmoEmpresaNombre();
    }
    payload.servicio = "inmobiliaria";
    payload.inmueble_id = state.currentInmuebleId;
    apiPost("/api/acciones", payload)
      .then((data) => {
        if (inmuebleActividadStatus) {
          const extra = data?._workflow_error ? ` (workflow: ${data._workflow_error})` : "";
          inmuebleActividadStatus.textContent = (data.error ? `${data.error}${extra}` : `Guardado.${extra}`).trim();
        }
        if (!data.error) {
          // Reset “duro” para evitar herencias (Safari + selects dinámicos).
          resetInmuebleActividadForm();
          const empresa = resolveCrmInmoEmpresa();
          const empresaId = resolveLegacyEmpresaId(empresa);
          if (empresaId) loadInmuebleActividad(state.currentInmuebleId, empresaId);
          try {
            loadCrmCaptaciones();
            loadCrmInmuebles();
          } catch (e) {}
          if (data?.inmueble_id && String(data.inmueble_id) === String(state.currentInmuebleId || "")) {
            try {
              if (state.currentInmuebleContext?.inmueble && data?.inmueble_estado) {
                state.currentInmuebleContext.inmueble.estado = data.inmueble_estado;
              }
              if (state.currentInmuebleContext?.captacion && data?.captacion_etapa) {
                state.currentInmuebleContext.captacion.etapa = data.captacion_etapa;
                state.currentInmuebleContext.captacion.situacion_comercial = data.captacion_etapa;
              }
              refreshCurrentInmuebleHeader();
            } catch (e) {}
          }
        }
      })
      .catch(() => {
        if (inmuebleActividadStatus) {
          inmuebleActividadStatus.textContent = "Error al guardar.";
        }
      });
  });
}

const uploadInmuebleDocsFiles = async ({ files = [], tipo = "", nombreBase = "", statusEl = null } = {}) => {
  if (!state.currentInmuebleId) throw new Error("Selecciona un inmueble.");
  const queue = Array.from(files || []).filter(Boolean);
  if (!queue.length) throw new Error("Selecciona un archivo.");
  const maxInline = 2_000_000;

  for (let i = 0; i < queue.length; i += 1) {
    const file = queue[i];
	    const payload = {
	      inmueble_id: state.currentInmuebleId,
	      empresa_nombre: resolveCurrentInmuebleEmpresaNombre(),
	      usuario: getCurrentUser(),
	      tipo,
	      nombre: queue.length === 1 && nombreBase ? nombreBase : file.name,
	    };
    try {
      if (file.size > maxInline) {
        try {
          if (statusEl) statusEl.textContent = `Subiendo ${i + 1}/${queue.length} (S3)...`;
          const upload = await uploadFileToS3(file, `inmuebles/${state.currentInmuebleId}`, statusEl);
          if (upload?.key) payload.s3_key = upload.key;
          else payload.file_base64 = await fileToBase64(file);
        } catch {
          payload.file_base64 = await fileToBase64(file);
        }
      } else {
        if (statusEl) statusEl.textContent = `Subiendo ${i + 1}/${queue.length}...`;
        payload.file_base64 = await fileToBase64(file);
      }
    } catch (err) {
      throw new Error(err?.message || "No se pudo leer el archivo.");
    }
    if (statusEl) statusEl.textContent = `Registrando ${i + 1}/${queue.length}...`;
    const res = await fetch("/api/inmueble_docs", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok || data?.error) {
      throw new Error(data?.error || "Error al subir.");
    }
  }
  return queue.length;
};

