if (hipotecaClienteForm) {
  hipotecaClienteForm.addEventListener("submit", async (event) => {
    event.preventDefault();
    if (hipotecaClienteFormStatus) {
      hipotecaClienteFormStatus.textContent = "Guardando cliente...";
    }
    const formData = new FormData(hipotecaClienteForm);
    const payload = Object.fromEntries(formData.entries());
    const tipoPersona = payload.tipo_persona || "Física";
    const nombreBase = String(payload.nombre || "").trim();
    const apellido1 = String(payload.apellido1 || "").trim();
    const apellido2 = String(payload.apellido2 || "").trim();

    if (String(tipoPersona).toLowerCase() === "jurídica") {
      if (!nombreBase) {
        if (hipotecaClienteFormStatus) {
          hipotecaClienteFormStatus.textContent = "Indica la razón social.";
        }
        return;
      }
    } else if (!apellido1 || !nombreBase) {
      if (hipotecaClienteFormStatus) {
        hipotecaClienteFormStatus.textContent = "Indica apellido 1 y nombre.";
      }
      return;
    }

    if (payload.nif) {
      const nif = normalizeDocumento(payload.nif);
      if (!isValidDocumento(nif)) {
        if (hipotecaClienteFormStatus) {
          hipotecaClienteFormStatus.textContent = "DNI/NIF/CIF no válido.";
        }
        return;
      }
      payload.nif = nif;
    }

    if (String(tipoPersona).toLowerCase() === "jurídica") {
      payload.nombre = nombreBase;
    } else {
      const apellidos = [apellido1, apellido2].filter(Boolean).join(" ").trim();
      payload.nombre =
        apellidos || nombreBase
          ? `${apellidos}${apellidos && nombreBase ? ", " : ""}${nombreBase}`.trim()
          : "";
    }
    delete payload.apellido1;
    delete payload.apellido2;

    const newClienteId = randomId();
    payload.id = newClienteId;

    try {
      const res = await fetch("/api/clientes", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });
      const data = await res.json();
      if (data.error) {
        if (hipotecaClienteFormStatus) {
          hipotecaClienteFormStatus.textContent = data.error;
        }
        return;
      }

      const clienteId = data.id || newClienteId;
      const empresaFin = resolveCrmFinEmpresa();
      if (empresaFin?.id) {
        await postJsonWithDbRetry(
          "/api/clientes_link",
          {
            cliente_id: clienteId,
            empresa_id: empresaFin.id,
            servicio: "Financiaciones",
            estado: "Activo",
            fecha_inicio: new Date().toISOString().slice(0, 10),
          },
          { retries: 1, delayMs: 120 }
        );
      }

      if (hipotecaClienteFormStatus) {
        hipotecaClienteFormStatus.textContent = "Cliente creado y vinculado a Financiaciones.";
      }
      hipotecaClienteForm.reset();
      updateHipotecaClientePersona();
      loadClientesCardStats().then(() => renderCompanyCards());
    } catch (_) {
      if (hipotecaClienteFormStatus) {
        hipotecaClienteFormStatus.textContent = "Error al guardar cliente.";
      }
    }
  });
}

if (hipotecaForm) {
  const comisionInput = hipotecaForm.querySelector("input[name='comision']");
  const comisionJuanInput = hipotecaForm.querySelector("input[name='comision_juan']");
  const comisionNetaModerniaInput = document.getElementById("hipotecaComisionNeta");
  const cesionHint = document.getElementById("hipotecaCesionHint");
  const cesionInput = hipotecaForm.querySelector("input[name='cesion']");
  const inmobiliariaCompraInput = hipotecaForm.querySelector("input[name='inmobiliaria_compra']");
  const oficinaInput = hipotecaForm.querySelector("input[name='oficina']");
  const precioInput = hipotecaForm.querySelector("input[name='precio']");
  const hipotecaInput = hipotecaForm.querySelector("input[name='importe_hipoteca']");
  const porcentajeInput = hipotecaForm.querySelector("input[name='porcentaje']");
  const normalizeText = (value) =>
    String(value || "")
      .toLowerCase()
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .trim();

	  const MALAGA_BONUS_OFFICES = new Set([
	    "modernia norte",
	    "modernia oeste",
	    "modernia centro",
	    "verifika2 norte",
	    "verifika2 oeste",
	    "verifika2 centro",
	    "malaga norte",
	    "malaga oeste",
	    "malaga centro",
	  ]);

  const canonicalOffice = (value) =>
    normalizeText(value)
      .replace(/\s+/g, " ")
      .trim();

  const hasMalagaBonusOffice = (value) => MALAGA_BONUS_OFFICES.has(canonicalOffice(value));

  const syncInmobiliariaCompra = () => {
    if (!inmobiliariaCompraInput || !oficinaInput) return;
    inmobiliariaCompraInput.value = String(oficinaInput.value || "").trim();
  };

  const updateCommissions = () => {
    if (!comisionInput) return;
    const total = Number(comisionInput.value);
    const oficina = oficinaInput?.value || "";
    const hasBonus = hasMalagaBonusOffice(oficina);
    const cesionRate = hasBonus ? 0.25 : 0.2;
    if (cesionHint) {
      cesionHint.textContent = hasBonus
        ? "Aplicando 25% (Centro/Norte/Oeste)."
        : "Aplicando 20% general.";
    }
    if (Number.isNaN(total)) {
      return;
    }
    if (comisionJuanInput) {
      comisionJuanInput.value = (total * 0.2).toFixed(2);
    }
    const juan = total * 0.2;
    if (cesionInput) {
      cesionInput.value = (total * cesionRate).toFixed(2);
    }
    const cesion = total * cesionRate;
    if (comisionNetaModerniaInput) {
      const modernia = Math.max(total - juan - cesion, 0);
      comisionNetaModerniaInput.value = modernia.toFixed(2);
    }
  };

  const updateFinanciacion = () => {
    const precio = toNumber(precioInput?.value);
    const hipoteca = toNumber(hipotecaInput?.value);
    if (precio !== null && precio > 0 && hipoteca !== null) {
      if (porcentajeInput) {
        porcentajeInput.value = ((hipoteca / precio) * 100).toFixed(2);
      }
    } else if (porcentajeInput) {
      porcentajeInput.value = "";
    }
  };

  if (comisionInput && comisionJuanInput) {
    comisionInput.addEventListener("input", updateCommissions);
  }
  if (oficinaInput) {
    oficinaInput.addEventListener("input", () => {
      syncInmobiliariaCompra();
      updateCommissions();
    });
  }
  syncInmobiliariaCompra();
  if (precioInput) {
    precioInput.addEventListener("input", updateFinanciacion);
  }
  if (hipotecaInput) {
    hipotecaInput.addEventListener("input", updateFinanciacion);
  }
  updateCommissions();
  updateFinanciacion();
  hipotecaForm.addEventListener("submit", (event) => {
    event.preventDefault();
    if (hipotecaFormStatus) {
      hipotecaFormStatus.textContent = "Guardando...";
    }
    const formData = new FormData(hipotecaForm);
    const payload = Object.fromEntries(formData.entries());
    payload.empresa_nombre = resolveCrmFinEmpresaNombre();
    if (!payload.anio && payload.fecha_firma) {
      payload.anio = String(payload.fecha_firma).slice(0, 4);
    }
    fetch("/api/hipotecas", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    })
      .then((res) => res.json())
      .then((data) => {
        if (data.error) {
          if (hipotecaFormStatus) {
            hipotecaFormStatus.textContent = data.error;
          }
          return;
        }
        if (hipotecaFormStatus) {
          hipotecaFormStatus.textContent = "Guardado.";
        }
        hipotecaForm.reset();
        if ((state.hipotecaAltaView || "") === "bdt") {
          loadHipotecaBdt(true);
        }
        if ((state.hipotecaAltaView || "") === "dashboard") {
          loadHipotecaDashboard();
        }
        loadHomeHipotecaStats().then(() => renderCompanyCards());
      })
      .catch(() => {
        if (hipotecaFormStatus) {
          hipotecaFormStatus.textContent = "Error al guardar.";
        }
      });
  });
}

const redrawDashboardOnResize = () => {
  if (lastDashboardData && dashboardSection && !dashboardSection.classList.contains("hidden")) {
    const ventasYears = buildYearIndex([lastDashboardData.ventas]);
    const facturadoYears = buildYearIndex([lastDashboardData.ingresos, lastDashboardData.gastos]);
    const alquilerYears = buildYearIndex([lastDashboardData.alquileres]);
    drawBarChart(
      ventasChart,
      ventasYears,
      [
        {
          label: "Ventas",
          values: alignSeries(ventasYears, lastDashboardData.ventas),
          color: "#824c45",
          format: (value) => numberFormatter.format(value),
        },
      ],
      { legend: false, showValues: true }
    );
    drawBarChart(
      facturadoChart,
      facturadoYears,
      [
        {
          label: "Facturado",
          values: alignSeries(facturadoYears, lastDashboardData.ingresos),
          color: "#d7b04c",
          format: (value) => euroFormatter.format(value),
        },
        {
          label: "Gastos",
          values: alignSeries(facturadoYears, lastDashboardData.gastos),
          color: "#334155",
          format: (value) => euroFormatter.format(value),
        },
      ],
      { legend: true, showValues: true }
    );
    drawBarChart(
      alquileresChart,
      alquilerYears,
      [
        {
          label: "Alquileres",
          values: alignSeries(alquilerYears, lastDashboardData.alquileres),
          color: "#cca33c",
          format: (value) => numberFormatter.format(value),
        },
      ],
      { legend: false, showValues: true }
    );
    const ventasVar = computeVariations(lastDashboardData.ventas);
    const alquilerVar = computeVariations(lastDashboardData.alquileres);
    const facturadoVar = computeVariations(lastDashboardData.ingresos);
    drawSignedBarChart(
      ventasVarChart,
      ventasVar.map((item) => item.year),
      ventasVar.map((item) => item.total),
      "#824c45"
    );
    drawSignedBarChart(
      alquileresVarChart,
      alquilerVar.map((item) => item.year),
      alquilerVar.map((item) => item.total),
      "#cca33c"
    );
    drawSignedBarChart(
      facturadoVarChart,
      facturadoVar.map((item) => item.year),
      facturadoVar.map((item) => item.total),
      "#d7b04c"
    );
  }
};

