// --- CRM Inmobiliaria: catálogo de poblaciones (todas) -----------------------
let INMO_POBLACIONES_CACHE = null;
let INMO_POBLACIONES_LOADING = null;
let INMO_DATALIST_FILTER_KEY = "";

const loadInmoPoblacionesCatalog = async () => {
  if (Array.isArray(INMO_POBLACIONES_CACHE) && INMO_POBLACIONES_CACHE.length) {
    return INMO_POBLACIONES_CACHE;
  }
  if (INMO_POBLACIONES_LOADING) return INMO_POBLACIONES_LOADING;
  INMO_POBLACIONES_LOADING = (async () => {
    const data = await api("/api/catalogo_poblaciones?limit=50000");
    const items = Array.isArray(data?.items) ? data.items : [];
    INMO_POBLACIONES_CACHE = items
      .map((item) => ({
        poblacion: String(item?.poblacion || "").trim(),
        provincia: String(item?.provincia || "").trim(),
      }))
      .filter((item) => item.poblacion);
    return INMO_POBLACIONES_CACHE;
  })().finally(() => {
    INMO_POBLACIONES_LOADING = null;
  });
  return INMO_POBLACIONES_LOADING;
};

const getInmoProvinciaFromContext = (el) => {
  try {
    const form = el?.closest?.("form");
    const sel = form?.querySelector?.('select.inmo-province-select[name="provincia"]');
    return String(sel?.value || "").trim();
  } catch {
    return "";
  }
};

const renderInmoPoblacionSelect = async (selectEl, provincia = "") => {
  if (!selectEl) return;
  const provKey = normalizeSimple(provincia || "");
  let items = [];
  try {
    items = await loadInmoPoblacionesCatalog();
  } catch {
    items = [];
  }
  const filtered = provKey
    ? items.filter((item) => normalizeSimple(item.provincia || "") === provKey)
    : items;
  const unique = [];
  const seen = new Set();
  filtered.forEach((item) => {
    const value = String(item?.poblacion || "").trim();
    const key = normalizeSimple(value);
    if (!value || !key || seen.has(key)) return;
    seen.add(key);
    unique.push(value);
  });
  unique.sort((a, b) => a.localeCompare(b, "es", { sensitivity: "base" }));
  const current = String(selectEl.value || "").trim();
  selectEl.innerHTML = "";
  selectEl.appendChild(createOption("", "Selecciona población"));
  unique.slice(0, 25000).forEach((value) => {
    selectEl.appendChild(createOption(value, value));
  });
  if (current && unique.some((v) => normalizeSimple(v) === normalizeSimple(current))) {
    selectEl.value = current;
  } else {
    selectEl.value = "";
  }
};

const renderInmoPoblacionDatalist = async (provincia = "") => {
  const datalist = document.getElementById("inmoPoblacionOptions");
  if (!datalist) return;

  const provKey = normalizeSimple(provincia || "");
  if (INMO_DATALIST_FILTER_KEY === provKey && datalist.childElementCount > 0) return;

  let items = [];
  try {
    items = await loadInmoPoblacionesCatalog();
  } catch {
    items = [];
  }

  const filtered = provKey
    ? items.filter((item) => normalizeSimple(item.provincia || "") === provKey)
    : items;

  datalist.innerHTML = "";
  const frag = document.createDocumentFragment();
  filtered.forEach((item) => {
    const opt = document.createElement("option");
    opt.value = item.poblacion;
    frag.appendChild(opt);
  });
  datalist.appendChild(frag);
  INMO_DATALIST_FILTER_KEY = provKey;
};

document.addEventListener("focusin", (event) => {
  const target = event.target;
  if (!target || !target.getAttribute) return;
  if (target.classList && target.classList.contains("inmo-poblacion-select")) {
    const provincia = getInmoProvinciaFromContext(target);
    renderInmoPoblacionSelect(target, provincia);
    return;
  }
  const list = target.getAttribute("list");
  if (list !== "inmoPoblacionOptions") return;
  const provincia = getInmoProvinciaFromContext(target);
  renderInmoPoblacionDatalist(provincia);
});

document.addEventListener("change", (event) => {
  const target = event.target;
  if (!target || !target.classList || !target.classList.contains("inmo-province-select")) return;
  try {
    const form = target.closest("form");
    const pop = form?.querySelector?.('input[list="inmoPoblacionOptions"][name="poblacion"]');
    const popSel = form?.querySelector?.('select.inmo-poblacion-select[name="poblacion"]');
    const provincia = String(target.value || "").trim();
    if (popSel) {
      renderInmoPoblacionSelect(popSel, provincia);
    } else if (pop) {
      renderInmoPoblacionDatalist(provincia);
    }
  } catch (e) {}
});

// --- Inmobiliaria: códigos postales por población (datalist) ---
const INMO_POSTAL_CODES_CACHE = new Map();
let INMO_POSTAL_DATALIST_FILTER_KEY = "";

const normalizeInmoPostalKey = (poblacion = "", provincia = "") =>
  `${normalizeSimple(poblacion || "")}||${normalizeSimple(provincia || "")}`;

const loadInmoPostalCodesCatalog = async (poblacion = "", provincia = "") => {
  const pop = String(poblacion || "").trim();
  if (!pop) return [];
  const prov = String(provincia || "").trim();
  const key = normalizeInmoPostalKey(pop, prov);
  if (INMO_POSTAL_CODES_CACHE.has(key)) return INMO_POSTAL_CODES_CACHE.get(key);
  const qs = new URLSearchParams({ poblacion: pop });
  if (prov) qs.set("provincia", prov);
  const data = await api(`/api/postal_codes?${qs.toString()}`);
  const codes = Array.isArray(data?.codes) ? data.codes : [];
  const cleaned = codes.map((c) => normalizePostalCode(c)).filter(Boolean).slice(0, 500);
  INMO_POSTAL_CODES_CACHE.set(key, cleaned);
  return cleaned;
};

const getInmoPoblacionFromContext = (el) => {
  try {
    const form = el?.closest?.("form");
    const input = form?.querySelector?.('select[name="poblacion"], input[name="poblacion"]');
    return String(input?.value || "").trim();
  } catch {
    return "";
  }
};

const getInmoPostalContext = (el) => {
  try {
    const form = el?.closest?.("form");
    const poblacion = String(form?.querySelector?.('select[name="poblacion"], input[name="poblacion"]')?.value || "").trim();
    const provincia = String(form?.querySelector?.('select[name="provincia"]')?.value || "").trim();
    return { form, poblacion, provincia };
  } catch {
    return { form: null, poblacion: "", provincia: "" };
  }
};

const renderInmoPostalDatalist = async (poblacion = "", provincia = "") => {
  const datalist = document.getElementById("inmoPostalOptions");
  if (!datalist) return;
  const key = normalizeInmoPostalKey(poblacion, provincia);
  if (INMO_POSTAL_DATALIST_FILTER_KEY === key && datalist.childElementCount > 0) return;
  let codes = [];
  try {
    codes = await loadInmoPostalCodesCatalog(poblacion, provincia);
  } catch {
    codes = [];
  }
  datalist.innerHTML = "";
  const frag = document.createDocumentFragment();
  codes.forEach((cp) => {
    const opt = document.createElement("option");
    opt.value = cp;
    frag.appendChild(opt);
  });
  datalist.appendChild(frag);
  INMO_POSTAL_DATALIST_FILTER_KEY = key;
};

document.addEventListener("focusin", (event) => {
  const target = event.target;
  if (!target || !target.getAttribute) return;
  const list = target.getAttribute("list");
  if (list !== "inmoPostalOptions") return;
  const { poblacion, provincia } = getInmoPostalContext(target);
  if (!poblacion) return;
  renderInmoPostalDatalist(poblacion, provincia);
});

document.addEventListener("input", (event) => {
  const target = event.target;
  if (!target) return;
  if (target.name !== "poblacion") return;
  const form = target.closest?.("form");
  const postalInput = form?.querySelector?.('input[list="inmoPostalOptions"][name="codigo_postal"]');
  if (!postalInput) return;
  const provincia = getInmoProvinciaFromContext(target);
  const poblacion = getInmoPoblacionFromContext(target);
  if (!poblacion) return;
  renderInmoPostalDatalist(poblacion, provincia);
});

document.addEventListener("change", (event) => {
  const target = event.target;
  if (!target) return;
  if (target.name !== "poblacion") return;
  if (String(target.tagName || "").toLowerCase() !== "select") return;
  const form = target.closest?.("form");
  const postalInput = form?.querySelector?.('input[list="inmoPostalOptions"][name="codigo_postal"]');
  if (!postalInput) return;
  const provincia = getInmoProvinciaFromContext(target);
  const poblacion = getInmoPoblacionFromContext(target);
  if (!poblacion) return;
  renderInmoPostalDatalist(poblacion, provincia);
});

document.addEventListener("change", (event) => {
  const target = event.target;
  if (!target) return;
  if (!target.classList || !target.classList.contains("inmo-province-select")) return;
  try {
    const form = target.closest("form");
    const postalInput = form?.querySelector?.('input[list="inmoPostalOptions"][name="codigo_postal"]');
    const poblacionInput = form?.querySelector?.('select[name="poblacion"], input[name="poblacion"]');
    if (!postalInput || !poblacionInput) return;
    const poblacion = String(poblacionInput.value || "").trim();
    if (!poblacion) return;
    renderInmoPostalDatalist(poblacion, String(target.value || "").trim());
  } catch (e) {}
});

